INSERT INTO questions (
    id, simulado_id, stem, options, correct_id, explanation,
    topic, domain, difficulty, scenario_type, tags, source, status,
    created_at, updated_at
) VALUES
    ('clf-c02-bill-001', 'aws-clf', 'Uma startup roda 20 instâncias EC2 m5.large em produção 24/7 há 18 meses sem previsão de redução. O CFO pediu para reduzir custo de compute sem mudar o tipo de instância. Considerando compromisso de 1 ano, qual modelo entrega o maior desconto sobre On-Demand mantendo flexibilidade entre regiões?', '[{"id":"A","text":"Spot Instances com fleet diversificada"},{"id":"B","text":"Compute Savings Plans de 1 ano, pagamento parcial"},{"id":"C","text":"EC2 Reserved Instances Standard zonal de 1 ano"},{"id":"D","text":"Dedicated Hosts com licença BYOL"}]'::jsonb, 'B', '{"summary":"Compute Savings Plans aplicam desconto (até ~66%) em qualquer região, família ou tamanho de EC2/Fargate/Lambda mediante compromisso de gasto $/h.","whyCorrect":"Compute Savings Plans aplicam desconto (até ~66%) em qualquer região, família ou tamanho de EC2/Fargate/Lambda mediante compromisso de gasto $/h.","whyWrong":{"A":"Spot pode ser interrompido [extra: não serve workload 24/7 crítico]","C":"Standard RI zonal trava AZ específica e família","D":"Dedicated Hosts são mais caros (foco em licenças)."},"keyConcept":"Regra: workload steady com flexibilidade → Savings Plans; workload tolerante a falhas → Spot.","tutorSeeds":["Pode explicar com mais detalhe: Regra: workload steady com flexibilidade → Savings Plans; workload tolerante a falhas → Spot?","Quais cenários reais aplicam Regra: workload steady com flexibilidade → Savings Plans; workload tolerante a falhas → Spot?","Como EC2 se compara com alternativas?"]}'::jsonb, 'Billing, Pricing & Support', 'Billing, Pricing & Support', 'medium', 'scenario', '["pricing","savings-plans","ec2"]'::jsonb, 'ai-draft', 'active', now(), now()),
    ('clf-c02-bill-002', 'aws-clf', 'Um time precisa rodar um job batch de processamento de imagens que tolera interrupções, com janela de 12 horas para concluir e prioridade no menor custo possível. Qual modelo de compra EC2 melhor atende?', '[{"id":"A","text":"On-Demand sob demanda"},{"id":"B","text":"Reserved Instances Convertible de 3 anos"},{"id":"C","text":"Spot Instances com checkpointing"},{"id":"D","text":"Dedicated Instances horárias"}]'::jsonb, 'C', '{"summary":"Spot oferece até 90% de desconto sobre On-Demand para workloads interruptíveis; com checkpointing, o job retoma após reclaim.","whyCorrect":"Spot oferece até 90% de desconto sobre On-Demand para workloads interruptíveis; com checkpointing, o job retoma após reclaim.","whyWrong":{"A":"On-Demand é o mais caro","B":"RI Convertible exige compromisso anual e workload steady","D":"Dedicated não traz desconto."},"keyConcept":"Regra: batch/stateless tolerante a falhas → Spot; produção 24/7 → Savings Plans/RI.","tutorSeeds":["Pode explicar com mais detalhe: Regra: batch/stateless tolerante a falhas → Spot; produção 24/7 → Savings Plans/RI?","Quais cenários reais aplicam Regra: batch/stateless tolerante a falhas → Spot; produção 24/7 → Savings Plans/RI?"]}'::jsonb, 'Billing, Pricing & Support', 'Billing, Pricing & Support', 'easy', 'scenario', '["pricing","spot","batch"]'::jsonb, 'ai-draft', 'active', now(), now()),
    ('clf-c02-bill-003', 'aws-clf', 'Qual a principal diferença entre EC2 Instance Savings Plans e Compute Savings Plans?', '[{"id":"A","text":"Compute SP só vale para Lambda; Instance SP só para EC2"},{"id":"B","text":"Instance SP exige família/região fixas com maior desconto; Compute SP é flexível com desconto menor"},{"id":"C","text":"Compute SP exige compromisso de 3 anos obrigatório"},{"id":"D","text":"Não há diferença prática — são sinônimos comerciais"}]'::jsonb, 'B', '{"summary":"Instance SP exige commit em família+região específicas (ex: m5 em us-east-1) e dá desconto similar ao RI Standard (~72%); Compute SP é cross-família/região/serviço (EC2/Fargate/Lambda) com desconto até ~66%.","whyCorrect":"Instance SP exige commit em família+região específicas (ex: m5 em us-east-1) e dá desconto similar ao RI Standard (~72%); Compute SP é cross-família/região/serviço (EC2/Fargate/Lambda) com desconto até ~66%.","whyWrong":{"A":"Compute SP cobre também Fargate e Lambda","C":"prazos são 1 ou 3 anos para ambos.","D":"Instance SP e Compute SP são produtos distintos com regras de aplicação, escopo e desconto diferentes. Instance SP é restrito a família+região (até ~72% de desconto, similar ao Standard RI); Compute SP cobre EC2 (qualquer família/região/SO), Fargate e Lambda (~66%). A AWS expõe ambos no console como SKUs separados — não são sinônimos comerciais."},"keyConcept":"Regra: mais restrição → maior desconto.","tutorSeeds":["Pode explicar com mais detalhe: Regra: mais restrição → maior desconto?","Quais cenários reais aplicam Regra: mais restrição → maior desconto?","Como SP se compara com alternativas?"]}'::jsonb, 'Billing, Pricing & Support', 'Billing, Pricing & Support', 'medium', 'recall', '["pricing","savings-plans"]'::jsonb, 'ai-draft', 'active', now(), now()),
    ('clf-c02-bill-004', 'aws-clf', 'Uma empresa adquiriu Reserved Instances Standard de 3 anos para EC2 m5.xlarge em us-east-1. Seis meses depois, querem trocar para r5.xlarge devido a novo workload memory-bound. Qual ação é possível?', '[{"id":"A","text":"Trocar livremente entre famílias via console"},{"id":"B","text":"Vender a RI no Reserved Instance Marketplace e comprar nova"},{"id":"C","text":"Cancelar a RI com reembolso integral"},{"id":"D","text":"Converter para Convertible RI sem custo"}]'::jsonb, 'B', '{"summary":"Standard RI não permite mudar família — apenas tamanho dentro da mesma família (size-flexibility).","whyCorrect":"Standard RI não permite mudar família — apenas tamanho dentro da mesma família (size-flexibility). Para trocar, deve vender no Marketplace (sujeito a aprovação) e comprar nova.","whyWrong":{"C":"AWS não permite cancelar com reembolso","D":"Standard não converte para Convertible troca livre só com Convertible RI.","A":"Standard RI não permite troca livre entre famílias de instância — só size-flexibility dentro da MESMA família (ex: m5.large ↔ m5.xlarge). Trocar m5 por r5 (família diferente) requer vender a RI no Marketplace ou ter comprado Convertible RI desde o início. Esta opção seria correta apenas para Convertible RIs."},"keyConcept":"Regra: workload incerto → Convertible; workload fixo → Standard.","tutorSeeds":["Pode explicar com mais detalhe: Regra: workload incerto → Convertible; workload fixo → Standard?","Quais cenários reais aplicam Regra: workload incerto → Convertible; workload fixo → Standard?","Como RI se compara com alternativas?"]}'::jsonb, 'Billing, Pricing & Support', 'Billing, Pricing & Support', 'hard', 'troubleshoot', '["pricing","reserved-instances"]'::jsonb, 'ai-draft', 'active', now(), now()),
    ('clf-c02-bill-005', 'aws-clf', 'Uma empresa precisa rodar software com licença vinculada a sockets físicos (ex: Windows Server BYOL legado). Qual modelo de compra é exigido para atender ao requisito de licenciamento?', '[{"id":"A","text":"EC2 On-Demand padrão"},{"id":"B","text":"Spot Instances"},{"id":"C","text":"Dedicated Hosts"},{"id":"D","text":"Savings Plans Compute"}]'::jsonb, 'C', '{"summary":"Dedicated Hosts dão visibilidade dos sockets/cores do host físico, permitindo BYOL de licenças socket-based.","whyCorrect":"Dedicated Hosts dão visibilidade dos sockets/cores do host físico, permitindo BYOL de licenças socket-based.","whyWrong":{"B":"Dedicated Instances isolam tenant mas não dão visibilidade de sockets.","D":"On-Demand/Spot/Savings Plans rodam em multi-tenant","A":"EC2 On-Demand rodam em hardware compartilhado (multi-tenant) com mapping dinâmico para hosts físicos — o cliente não tem visibilidade nem garantia de quais sockets/cores estão sendo usados. Licenças socket-based exigem essa visibilidade para conformidade de auditoria do fabricante. On-Demand padrão atende quando não há restrição de licenciamento por socket."},"keyConcept":"Regra: BYOL socket-based → Dedicated Hosts.","tutorSeeds":["Pode explicar com mais detalhe: Regra: BYOL socket-based → Dedicated Hosts?","Quais cenários reais aplicam Regra: BYOL socket-based → Dedicated Hosts?","Como BYOL se compara com alternativas?"]}'::jsonb, 'Billing, Pricing & Support', 'Billing, Pricing & Support', 'medium', 'scenario', '["pricing","dedicated-hosts","byol"]'::jsonb, 'ai-draft', 'active', now(), now()),
    ('clf-c02-bill-006', 'aws-clf', 'Qual diferença prática entre Dedicated Instances e Dedicated Hosts?', '[{"id":"A","text":"Não há — são o mesmo produto"},{"id":"B","text":"Dedicated Instances isolam tenant; Dedicated Hosts ainda dão visibilidade e controle do hardware físico"},{"id":"C","text":"Dedicated Hosts são cobrados por instância; Dedicated Instances por host"},{"id":"D","text":"Dedicated Instances só rodam em Outposts"}]'::jsonb, 'B', '{"summary":"Dedicated Instances garantem que VMs do cliente rodam em hardware não compartilhado, mas o cliente não vê o host.","whyCorrect":"Dedicated Instances garantem que VMs do cliente rodam em hardware não compartilhado, mas o cliente não vê o host. Dedicated Hosts alocam o host físico inteiro — cliente vê sockets/cores e controla onde cada instância roda (essencial para BYOL).","whyWrong":{"A":"Outposts é outro produto.","C":"cobrança Hosts é por host/hora, Instances por instância/hora","D":"Dedicated Instances estão disponíveis em qualquer Região AWS comercial — não há vinculação com AWS Outposts. Outposts é uma oferta de hardware AWS instalado on-premises do cliente e funciona com modelo de tenancy próprio. Esta opção mistura dois conceitos não relacionados (tenancy dedicada vs hardware hybrid)."},"keyConcept":"Regra: licença socket-based → Hosts; só isolamento → Instances.","tutorSeeds":["Pode explicar com mais detalhe: Regra: licença socket-based → Hosts; só isolamento → Instances?","Quais cenários reais aplicam Regra: licença socket-based → Hosts; só isolamento → Instances?","Como VMs se compara com alternativas?"]}'::jsonb, 'Billing, Pricing & Support', 'Billing, Pricing & Support', 'medium', 'recall', '["pricing","dedicated-hosts","dedicated-instances"]'::jsonb, 'ai-draft', 'active', now(), now()),
    ('clf-c02-bill-007', 'aws-clf', 'Uma equipe quer aplicar Savings Plans, mas tem dúvida se cobre AWS Lambda. Qual statement está correto sobre Compute Savings Plans e Lambda?', '[{"id":"A","text":"Não cobre Lambda — apenas EC2 e Fargate"},{"id":"B","text":"Cobre Lambda Duration (não Requests) com desconto até 17%"},{"id":"C","text":"Cobre 100% do custo Lambda incluindo data transfer"},{"id":"D","text":"Cobre apenas Provisioned Concurrency"}]'::jsonb, 'B', '{"summary":"Compute SP aplica desconto à parte de Duration ($/GB-s) do Lambda — não cobre Requests nem data transfer.","whyCorrect":"Compute SP aplica desconto à parte de Duration ($/GB-s) do Lambda — não cobre Requests nem data transfer.","whyWrong":{"A":"Cobre Lambda sim","C":"não cobre 100% do custo","D":"aplica a Duration e Provisioned Concurrency, não apenas a este último."},"keyConcept":"Regra: Compute SP = EC2 + Fargate + Lambda Duration.","tutorSeeds":["Pode explicar com mais detalhe: Regra: Compute SP = EC2 + Fargate + Lambda Duration?","Quais cenários reais aplicam Regra: Compute SP = EC2 + Fargate + Lambda Duration?","Como SP se compara com alternativas?"]}'::jsonb, 'Billing, Pricing & Support', 'Billing, Pricing & Support', 'hard', 'recall', '["pricing","savings-plans","lambda"]'::jsonb, 'ai-draft', 'active', now(), now()),
    ('clf-c02-bill-008', 'aws-clf', 'Um workload de inferência ML precisa de GPU 24/7 por 3 anos com previsibilidade de custo total upfront. O time aceita pagar antecipado para maior desconto. Qual modelo entrega o menor TCO?', '[{"id":"A","text":"On-Demand com auto scaling"},{"id":"B","text":"Spot com placement groups"},{"id":"C","text":"Reserved Instances Standard 3 anos All Upfront"},{"id":"D","text":"Dedicated Hosts mensal"}]'::jsonb, 'C', '{"summary":"RI Standard 3y All Upfront entrega o maior desconto possível (~72%) sobre On-Demand e fixa custo total.","whyCorrect":"RI Standard 3y All Upfront entrega o maior desconto possível (~72%) sobre On-Demand e fixa custo total.","whyWrong":{"A":"On-Demand é o mais caro","B":"Spot não serve para workload 24/7 sem tolerância a falhas","D":"Dedicated Hosts focam em licenças, não em desconto."},"keyConcept":"Regra: workload super-estável de longo prazo + pagamento upfront aceito → RI Standard.","tutorSeeds":["Pode explicar com mais detalhe: Regra: workload super-estável de longo prazo + pagamento upfront aceito → RI Standard?","Quais cenários reais aplicam Regra: workload super-estável de longo prazo + pagamento upfront aceito → RI Standard?","Como RI se compara com alternativas?"]}'::jsonb, 'Billing, Pricing & Support', 'Billing, Pricing & Support', 'medium', 'scenario', '["pricing","reserved-instances"]'::jsonb, 'ai-draft', 'active', now(), now()),
    ('clf-c02-bill-009', 'aws-clf', 'Uma empresa deseja descontos em Amazon RDS, ElastiCache e Redshift sem migrar instâncias. Qual mecanismo de pricing aplica desconto a esses serviços managed de banco?', '[{"id":"A","text":"Compute Savings Plans"},{"id":"B","text":"Reserved Instances/Reserved Nodes específicos do serviço"},{"id":"C","text":"Spot Instances"},{"id":"D","text":"EC2 Instance Savings Plans"}]'::jsonb, 'B', '{"summary":"RDS, ElastiCache, Redshift, OpenSearch e DynamoDB têm seus próprios programas de Reserved (Reserved DB Instances, Reserved Nodes, Reserved Capacity).","whyCorrect":"RDS, ElastiCache, Redshift, OpenSearch e DynamoDB têm seus próprios programas de Reserved (Reserved DB Instances, Reserved Nodes, Reserved Capacity).","whyWrong":{"A":"Savings Plans não cobrem esses serviços","C":"Spot só existe para EC2/EMR/Fargate batch","D":"EC2 Instance Savings Plans aplicam-se exclusivamente a EC2 (família+região fixa) — não cobrem instâncias de RDS, ElastiCache, Redshift ou qualquer outro serviço managed. Cada serviço managed de banco tem seu próprio programa de Reserved (Reserved DB Instances para RDS, Reserved Nodes para ElastiCache/Redshift). EC2 Instance SP seria correto se a empresa quisesse desconto em EC2 m5 em us-east-1, por exemplo."},"keyConcept":"Regra: cada serviço managed tem seu próprio mecanismo de RI.","tutorSeeds":["Pode explicar com mais detalhe: Regra: cada serviço managed tem seu próprio mecanismo de RI?","Quais cenários reais aplicam Regra: cada serviço managed tem seu próprio mecanismo de RI?","Como RDS se compara com alternativas?"]}'::jsonb, 'Billing, Pricing & Support', 'Billing, Pricing & Support', 'medium', 'recall', '["pricing","reserved-instances","rds"]'::jsonb, 'ai-draft', 'active', now(), now()),
    ('clf-c02-bill-010', 'aws-clf', 'Sobre EC2 On-Demand, qual statement é correto?', '[{"id":"A","text":"Exige compromisso mínimo de 1 ano"},{"id":"B","text":"Cobrança por segundo (mínimo 60s) para Linux e por hora para Windows"},{"id":"C","text":"Inclui automaticamente desconto Savings Plans"},{"id":"D","text":"Garante capacidade reservada na AZ"}]'::jsonb, 'B', '{"summary":"On-Demand não tem compromisso; cobrança per-second para a maioria das AMIs Linux (mínimo 60s) e per-hour para Windows e algumas distribuições comerciais Linux.","whyCorrect":"On-Demand não tem compromisso; cobrança per-second para a maioria das AMIs Linux (mínimo 60s) e per-hour para Windows e algumas distribuições comerciais Linux.","whyWrong":{"A":"Não exige commit","D":"reserva de capacidade requer Capacity Reservation explícito ou Zonal RI.","C":"On-Demand não inclui desconto algum — é o pricing baseline de referência. Savings Plans são um compromisso ($/hora por 1 ou 3 anos) que o cliente compra separadamente; o desconto só é aplicado após adquirir um SP que cubra a instância. Esta opção seria correta se o cliente tivesse comprado um Compute ou Instance SP."},"keyConcept":"Regra: On-Demand = flexibilidade máxima, sem desconto.","tutorSeeds":["Pode explicar com mais detalhe: Regra: On-Demand = flexibilidade máxima, sem desconto?","Quais cenários reais aplicam Regra: On-Demand = flexibilidade máxima, sem desconto?","Como AMIs se compara com alternativas?"]}'::jsonb, 'Billing, Pricing & Support', 'Billing, Pricing & Support', 'easy', 'recall', '["pricing","on-demand"]'::jsonb, 'ai-draft', 'active', now(), now()),
    ('clf-c02-bill-011', 'aws-clf', 'Uma equipe configurou uma Auto Scaling Group para batch processing usando Spot Instances. Após uma semana, observam que vários jobs falham por interrupção e pedem alternativa que mantenha desconto mas garanta capacidade para os dois nós críticos. Qual abordagem é a mais adequada?', '[{"id":"A","text":"Migrar 100% para On-Demand"},{"id":"B","text":"Mixed Instances Policy: 2 On-Demand baseline + restante em Spot"},{"id":"C","text":"Trocar todos os nós por Dedicated Hosts"},{"id":"D","text":"Comprar Convertible RI para todos os nós"}]'::jsonb, 'B', '{"summary":"ASG com Mixed Instances Policy combina On-Demand baseline para garantir SLA e Spot para escala com desconto, atendendo o requisito sem abrir mão do custo.","whyCorrect":"ASG com Mixed Instances Policy combina On-Demand baseline para garantir SLA e Spot para escala com desconto, atendendo o requisito sem abrir mão do custo.","whyWrong":{"A":"100% On-Demand elimina o desconto","C":"Dedicated Hosts são caros e fora do caso de uso","D":"RI Convertible para batch é overkill."},"keyConcept":"Regra: workload misto crítico+elástico → Mixed Instances.","tutorSeeds":["Pode explicar com mais detalhe: Regra: workload misto crítico+elástico → Mixed Instances?","Quais cenários reais aplicam Regra: workload misto crítico+elástico → Mixed Instances?","Como ASG se compara com alternativas?"]}'::jsonb, 'Billing, Pricing & Support', 'Billing, Pricing & Support', 'hard', 'scenario', '["pricing","spot","auto-scaling"]'::jsonb, 'ai-draft', 'active', now(), now()),
    ('clf-c02-bill-012', 'aws-clf', 'Uma empresa quer estimar o custo mensal de uma nova arquitetura com EC2, RDS, S3 e CloudFront antes de provisionar qualquer recurso. Qual ferramenta gratuita da AWS atende a esse propósito?', '[{"id":"A","text":"AWS Cost Explorer"},{"id":"B","text":"AWS Pricing Calculator"},{"id":"C","text":"AWS Budgets"},{"id":"D","text":"Cost and Usage Report (CUR)"}]'::jsonb, 'B', '{"summary":"Pricing Calculator estima custo de arquiteturas hipotéticas antes de provisionar; gera planilhas compartilháveis com breakdown por serviço/região.","whyCorrect":"Pricing Calculator estima custo de arquiteturas hipotéticas antes de provisionar; gera planilhas compartilháveis com breakdown por serviço/região.","whyWrong":{"A":"Cost Explorer analisa gastos já realizados","C":"Budgets define alertas sobre custos reais","D":"Cost and Usage Report (CUR) é o relatório granular de gastos REAIS já incorridos, entregue em CSV/Parquet no S3 para análise via Athena/Redshift. Não estima custos de arquitetura futura — só reporta consumo passado. CUR seria a ferramenta certa para análise FinOps detalhada após meses de operação."},"keyConcept":"Regra: pré-provisionamento → Pricing Calculator; pós-provisionamento → Cost Explorer/Budgets/CUR.","tutorSeeds":["Pode explicar com mais detalhe: Regra: pré-provisionamento → Pricing Calculator; pós-provisionamento → Cost Explorer/Budgets/CUR?","Quais cenários reais aplicam Regra: pré-provisionamento → Pricing Calculator; pós-provisionamento → Cost Explorer/Budgets/CUR?"]}'::jsonb, 'Billing, Pricing & Support', 'Billing, Pricing & Support', 'easy', 'scenario', '["billing-tools","pricing-calculator"]'::jsonb, 'ai-draft', 'active', now(), now()),
    ('clf-c02-bill-013', 'aws-clf', 'Uma equipe finance pede um relatório com breakdown de custo do último trimestre por serviço, com filtros por tag de projeto e visualização gráfica interativa. Qual serviço atende nativamente?', '[{"id":"A","text":"AWS Pricing Calculator"},{"id":"B","text":"AWS Cost Explorer"},{"id":"C","text":"AWS CloudTrail"},{"id":"D","text":"AWS Config"}]'::jsonb, 'B', '{"summary":"Cost Explorer oferece UI gráfica com filtros por serviço, tag, conta e período (até 13 meses por padrão, 38 meses opcional).","whyCorrect":"Cost Explorer oferece UI gráfica com filtros por serviço, tag, conta e período (até 13 meses por padrão, 38 meses opcional).","whyWrong":{"A":"Pricing Calculator é pre-spend","C":"CloudTrail é audit log de API","D":"Config rastreia configuração de recursos, não custos."},"keyConcept":"Regra: análise visual de custo histórico → Cost Explorer.","tutorSeeds":["Pode explicar com mais detalhe: Regra: análise visual de custo histórico → Cost Explorer?","Quais cenários reais aplicam Regra: análise visual de custo histórico → Cost Explorer?","Como UI se compara com alternativas?"]}'::jsonb, 'Billing, Pricing & Support', 'Billing, Pricing & Support', 'easy', 'scenario', '["billing-tools","cost-explorer"]'::jsonb, 'ai-draft', 'active', now(), now()),
    ('clf-c02-bill-014', 'aws-clf', 'Um CTO quer ser notificado por email quando o gasto do mês ultrapassar $5,000 ou quando estiver previsto a ultrapassar até o fim do mês. Qual ferramenta deve configurar?', '[{"id":"A","text":"AWS Trusted Advisor"},{"id":"B","text":"AWS Budgets com budget de custo + alerta forecasted"},{"id":"C","text":"AWS CloudWatch billing metric"},{"id":"D","text":"AWS Cost Anomaly Detection"}]'::jsonb, 'B', '{"summary":"AWS Budgets suporta thresholds em actual e forecasted spend; envia alerta via SNS/email.","whyCorrect":"AWS Budgets suporta thresholds em actual e forecasted spend; envia alerta via SNS/email.","whyWrong":{"A":"Trusted Advisor dá recomendações pontuais","C":"CloudWatch billing metric existe mas é menos rico que Budgets","D":"Cost Anomaly Detection foca em desvios estatísticos, não thresholds fixos."},"keyConcept":"Regra: alerta proativo com limite → Budgets.","tutorSeeds":["Pode explicar com mais detalhe: Regra: alerta proativo com limite → Budgets?","Quais cenários reais aplicam Regra: alerta proativo com limite → Budgets?","Como AWS Budgets se compara com alternativas?"]}'::jsonb, 'Billing, Pricing & Support', 'Billing, Pricing & Support', 'easy', 'best-practice', '["billing-tools","budgets"]'::jsonb, 'ai-draft', 'active', now(), now()),
    ('clf-c02-bill-015', 'aws-clf', 'Uma equipe data precisa do dataset granular hora-a-hora de todos os custos AWS para carregar em Athena/QuickSight e construir dashboards customizados. Qual entrega esse nível de detalhe?', '[{"id":"A","text":"Cost Explorer API"},{"id":"B","text":"AWS Cost and Usage Report (CUR) com integração Athena"},{"id":"C","text":"Trusted Advisor export"},{"id":"D","text":"AWS Budgets reports"}]'::jsonb, 'B', '{"summary":"CUR é o dataset mais detalhado: linha por recurso/hora em S3 (Parquet ou CSV), com integração nativa para Athena/Redshift/QuickSight.","whyCorrect":"CUR é o dataset mais detalhado: linha por recurso/hora em S3 (Parquet ou CSV), com integração nativa para Athena/Redshift/QuickSight.","whyWrong":{"A":"Cost Explorer API tem granularidade diária e limites de query","C":"Trusted Advisor não exporta custo","D":"Budgets gera reports agregados."},"keyConcept":"Regra: BI customizado em cima de custos → CUR.","tutorSeeds":["Pode explicar com mais detalhe: Regra: BI customizado em cima de custos → CUR?","Quais cenários reais aplicam Regra: BI customizado em cima de custos → CUR?","Como CUR se compara com alternativas?"]}'::jsonb, 'Billing, Pricing & Support', 'Billing, Pricing & Support', 'medium', 'scenario', '["billing-tools","cur","athena"]'::jsonb, 'ai-draft', 'active', now(), now()),
    ('clf-c02-bill-016', 'aws-clf', 'Uma equipe quer recomendações automáticas de rightsizing para reduzir custo em EC2 e EBS, baseadas em métricas reais de uso (CPU, memory, IO). Qual serviço entrega isso?', '[{"id":"A","text":"AWS Compute Optimizer"},{"id":"B","text":"AWS Trusted Advisor (categoria Performance)"},{"id":"C","text":"AWS Config"},{"id":"D","text":"AWS Systems Manager Inventory"}]'::jsonb, 'A', '{"summary":"Compute Optimizer analisa CloudWatch metrics (incluindo memory via agent) e recomenda tipo/tamanho ideal para EC2, ASG, EBS, Lambda e ECS on Fargate.","whyCorrect":"Compute Optimizer analisa CloudWatch metrics (incluindo memory via agent) e recomenda tipo/tamanho ideal para EC2, ASG, EBS, Lambda e ECS on Fargate.","whyWrong":{"B":"Trusted Advisor identifica idle/low-utilization de forma mais simples","C":"Config é compliance","D":"SSM Inventory lista recursos sem recomendar."},"keyConcept":"Regra: rightsizing ML-based → Compute Optimizer.","tutorSeeds":["Pode explicar com mais detalhe: Regra: rightsizing ML-based → Compute Optimizer?","Quais cenários reais aplicam Regra: rightsizing ML-based → Compute Optimizer?","Como EC2 se compara com alternativas?"]}'::jsonb, 'Billing, Pricing & Support', 'Billing, Pricing & Support', 'medium', 'scenario', '["billing-tools","compute-optimizer","rightsizing"]'::jsonb, 'ai-draft', 'active', now(), now()),
    ('clf-c02-bill-017', 'aws-clf', 'Uma empresa observou um spike de $8,000 no DynamoDB ontem, sem mudança de deploy aparente. Buscam ferramenta que detecte automaticamente desvios deste tipo e envie alerta com root cause. Qual serviço usar?', '[{"id":"A","text":"AWS Budgets com alerta fixo"},{"id":"B","text":"AWS Cost Anomaly Detection"},{"id":"C","text":"AWS CloudTrail Insights"},{"id":"D","text":"Amazon DevOps Guru"}]'::jsonb, 'B', '{"summary":"Cost Anomaly Detection usa ML para detectar desvios estatísticos no padrão de gasto e alerta com breakdown por serviço/conta/uso.","whyCorrect":"Cost Anomaly Detection usa ML para detectar desvios estatísticos no padrão de gasto e alerta com breakdown por serviço/conta/uso.","whyWrong":{"A":"Budgets dispara em threshold fixo (não anomalia)","C":"CloudTrail Insights detecta padrões anômalos em API calls, não custo","D":"DevOps Guru foca em operacional."},"keyConcept":"Regra: anomalia financeira → Cost Anomaly Detection.","tutorSeeds":["Pode explicar com mais detalhe: Regra: anomalia financeira → Cost Anomaly Detection?","Quais cenários reais aplicam Regra: anomalia financeira → Cost Anomaly Detection?","Como ML se compara com alternativas?"]}'::jsonb, 'Billing, Pricing & Support', 'Billing, Pricing & Support', 'medium', 'troubleshoot', '["billing-tools","anomaly-detection"]'::jsonb, 'ai-draft', 'active', now(), now()),
    ('clf-c02-bill-018', 'aws-clf', 'Sobre o AWS Pricing Calculator, qual statement é correto?', '[{"id":"A","text":"É pago, com cobrança por estimativa gerada"},{"id":"B","text":"Permite gerar estimativas compartilháveis via URL pública sem login"},{"id":"C","text":"Sincroniza automaticamente o gasto real da conta"},{"id":"D","text":"Substitui o Cost Explorer para análise histórica"}]'::jsonb, 'B', '{"summary":"Pricing Calculator é gratuito e gera links públicos para estimativas — útil para sales/arquitetos compartilharem com clientes/stakeholders.","whyCorrect":"Pricing Calculator é gratuito e gera links públicos para estimativas — útil para sales/arquitetos compartilharem com clientes/stakeholders.","whyWrong":{"A":"Não é pago","C":"não acessa conta real (é pré-spend, hipotético)","D":"não substitui Cost Explorer (pós-spend)."},"keyConcept":"Regra: ferramenta hipotética pré-provisionamento.","tutorSeeds":["Pode explicar com mais detalhe: Regra: ferramenta hipotética pré-provisionamento?","Quais cenários reais aplicam Regra: ferramenta hipotética pré-provisionamento?"]}'::jsonb, 'Billing, Pricing & Support', 'Billing, Pricing & Support', 'easy', 'recall', '["billing-tools","pricing-calculator"]'::jsonb, 'ai-draft', 'active', now(), now()),
    ('clf-c02-bill-019', 'aws-clf', 'Uma empresa configura um Budget mas o time não recebe alertas mesmo após ultrapassar threshold. O que verificar primeiro?', '[{"id":"A","text":"Se a região do budget está em us-east-1 (única suportada)"},{"id":"B","text":"Se o tópico SNS / endereço de email foi confirmado e se IAM permite SNS publish"},{"id":"C","text":"Se o budget é Reserved Instance e não de custo"},{"id":"D","text":"Se Trusted Advisor está habilitado"}]'::jsonb, 'B', '{"summary":"Alertas via email exigem confirmação do destinatário; via SNS exigem topic policy permitindo billing publicar.","whyCorrect":"Alertas via email exigem confirmação do destinatário; via SNS exigem topic policy permitindo billing publicar.","whyWrong":{"A":"tipo do budget não impede notificação","D":"Trusted Advisor é independente.","C":"RI Budgets é apenas um tipo de Budget (utilização/cobertura de RI), enquanto Cost Budget é outro. Ambos disparam alertas pelo mesmo mecanismo (SNS/email) — o tipo do budget não impede a entrega de notificação. O problema descrito (alerta não chega) é independente do tipo do budget; é sempre falha de subscription ou IAM/SNS policy."},"keyConcept":"Regra: troubleshoot Budgets → confirmação de subscription e IAM/SNS policy.","tutorSeeds":["Pode explicar com mais detalhe: Regra: troubleshoot Budgets → confirmação de subscription e IAM/SNS policy?","Quais cenários reais aplicam Regra: troubleshoot Budgets → confirmação de subscription e IAM/SNS policy?","Como SNS se compara com alternativas?"]}'::jsonb, 'Billing, Pricing & Support', 'Billing, Pricing & Support', 'medium', 'troubleshoot', '["billing-tools","budgets","sns"]'::jsonb, 'ai-draft', 'active', now(), now()),
    ('clf-c02-bill-020', 'aws-clf', 'Uma empresa quer ativar o CUR mas se preocupa com custo de armazenamento. Qual statement é verdadeiro?', '[{"id":"A","text":"CUR é cobrado por linha gerada"},{"id":"B","text":"CUR é gratuito mas o S3 bucket de destino é cobrado normalmente"},{"id":"C","text":"CUR só funciona com S3 Glacier"},{"id":"D","text":"CUR requer Enterprise Support"}]'::jsonb, 'B', '{"summary":"A geração e entrega do CUR não tem custo; o cliente paga apenas o storage do S3 e o uso de Athena/Redshift se consultar.","whyCorrect":"A geração e entrega do CUR não tem custo; o cliente paga apenas o storage do S3 e o uso de Athena/Redshift se consultar.","whyWrong":{"A":"Não cobra por linha","C":"não exige Glacier (use Standard)","D":"CUR está disponível em qualquer plano de suporte (incluindo Basic) — não há requisito de Enterprise Support. O recurso é configurável diretamente no console Billing por qualquer conta. Enterprise Support adiciona TAM, Concierge e SLA agressivo, mas não é prerequisito para habilitar relatórios de billing."},"keyConcept":"Regra: CUR free, S3 storage normal.","tutorSeeds":["Pode explicar com mais detalhe: Regra: CUR free, S3 storage normal?","Quais cenários reais aplicam Regra: CUR free, S3 storage normal?","Como CUR se compara com alternativas?"]}'::jsonb, 'Billing, Pricing & Support', 'Billing, Pricing & Support', 'medium', 'recall', '["billing-tools","cur","s3"]'::jsonb, 'ai-draft', 'active', now(), now()),
    ('clf-c02-bill-021', 'aws-clf', 'Uma startup precisa de suporte 24/7 com SLA de resposta <1h para casos production-down e acesso a guidance arquitetural via chat/email. Está disposta a pagar a partir de $100/mês. Qual plano de suporte AWS é o mínimo adequado?', '[{"id":"A","text":"Basic"},{"id":"B","text":"Developer"},{"id":"C","text":"Business"},{"id":"D","text":"Enterprise"}]'::jsonb, 'C', '{"summary":"Business é o menor plano com suporte 24/7, SLA <1h para production-down, Trusted Advisor full, e acesso a Infrastructure Event Management.","whyCorrect":"Business é o menor plano com suporte 24/7, SLA <1h para production-down, Trusted Advisor full, e acesso a Infrastructure Event Management.","whyWrong":{"A":"Basic não tem suporte técnico [extra: fora do orçamento.]","B":"Developer tem 24h business hours apenas","D":"Enterprise oferece TAM mas começa em ~$15k/mês"},"keyConcept":"Regra: production 24/7 minimum → Business.","tutorSeeds":["Pode explicar com mais detalhe: Regra: production 24/7 minimum → Business?","Quais cenários reais aplicam Regra: production 24/7 minimum → Business?","Como SLA se compara com alternativas?"]}'::jsonb, 'Billing, Pricing & Support', 'Billing, Pricing & Support', 'medium', 'scenario', '["support","business-plan"]'::jsonb, 'ai-draft', 'active', now(), now()),
    ('clf-c02-bill-022', 'aws-clf', 'Qual plano de suporte AWS inclui um Technical Account Manager (TAM) dedicado e Concierge Support para billing?', '[{"id":"A","text":"Developer"},{"id":"B","text":"Business"},{"id":"C","text":"Enterprise On-Ramp"},{"id":"D","text":"Enterprise"}]'::jsonb, 'D', '{"summary":"Enterprise inclui TAM dedicado, Concierge para billing, IEM ilimitado, Well-Architected reviews e SLA <15min para business/mission-critical down.","whyCorrect":"Enterprise inclui TAM dedicado, Concierge para billing, IEM ilimitado, Well-Architected reviews e SLA <15min para business/mission-critical down.","whyWrong":{"A":"Developer/Business não têm TAM","C":"On-Ramp tem acesso a pool de TAMs (não dedicado), com SLA <30min.","B":"Business Support ($100/mês mínimo) inclui suporte 24/7, Trusted Advisor completo e tempo de resposta <1h para production down, mas NÃO inclui TAM dedicado nem Concierge Support de billing. TAM dedicado e Concierge são exclusivos do Enterprise. Business seria a resposta para ''suporte 24/7 com Trusted Advisor completo, sem TAM''."},"keyConcept":"Regra: TAM dedicado → Enterprise.","tutorSeeds":["Pode explicar com mais detalhe: Regra: TAM dedicado → Enterprise?","Quais cenários reais aplicam Regra: TAM dedicado → Enterprise?","Como TAM se compara com alternativas?"]}'::jsonb, 'Billing, Pricing & Support', 'Billing, Pricing & Support', 'easy', 'recall', '["support","enterprise","tam"]'::jsonb, 'ai-draft', 'active', now(), now()),
    ('clf-c02-bill-023', 'aws-clf', 'Qual plano de suporte AWS é incluído sem custo adicional em toda conta AWS?', '[{"id":"A","text":"Basic Support"},{"id":"B","text":"Developer Support"},{"id":"C","text":"Business Support"},{"id":"D","text":"On-Ramp"}]'::jsonb, 'A', '{"summary":"Basic é gratuito e inclui: 24/7 customer service (billing/account), documentação, whitepapers, e 7 checks core do Trusted Advisor.","whyCorrect":"Basic é gratuito e inclui: 24/7 customer service (billing/account), documentação, whitepapers, e 7 checks core do Trusted Advisor.","whyWrong":{"B":"Developer começa em ~$29/mês","C":"Business em $100/mês","D":"On-Ramp em ~$5,500/mês."},"keyConcept":"Regra: toda conta tem Basic por padrão.","tutorSeeds":["Pode explicar com mais detalhe: Regra: toda conta tem Basic por padrão?","Quais cenários reais aplicam Regra: toda conta tem Basic por padrão?"]}'::jsonb, 'Billing, Pricing & Support', 'Billing, Pricing & Support', 'easy', 'recall', '["support","basic-plan"]'::jsonb, 'ai-draft', 'active', now(), now()),
    ('clf-c02-bill-024', 'aws-clf', 'Uma empresa quer contratar engenheiros AWS para auxiliar em migração complexa para a cloud, com escopo de meses e entregáveis definidos. Qual oferta atende?', '[{"id":"A","text":"AWS IQ"},{"id":"B","text":"AWS Professional Services"},{"id":"C","text":"AWS Trusted Advisor"},{"id":"D","text":"AWS Marketplace"}]'::jsonb, 'B', '{"summary":"AWS Professional Services é o time de consultoria pago da AWS para projetos grandes (migrations, modernization, AI/ML).","whyCorrect":"AWS Professional Services é o time de consultoria pago da AWS para projetos grandes (migrations, modernization, AI/ML).","whyWrong":{"C":"Trusted Advisor é ferramenta automática","D":"Marketplace é catálogo de software/serviços de terceiros.","A":"AWS IQ é marketplace de consultores Experts certificados para projetos pequenos e pontuais (horas a poucas semanas), com pagamento direto via console. Não é dimensionado para migrações enterprise complexas que demandam time multidisciplinar, governança contratual e meses de execução — esse é o sweet spot do AWS ProServe. IQ seria correto para ''consultor freelancer para configurar uma VPC em 2 dias''."},"keyConcept":"Regra: projeto complexo da AWS Inc → ProServe; freelance curto → IQ.","tutorSeeds":["Pode explicar com mais detalhe: Regra: projeto complexo da AWS Inc → ProServe; freelance curto → IQ?","Quais cenários reais aplicam Regra: projeto complexo da AWS Inc → ProServe; freelance curto → IQ?","Como AWS Professional se compara com alternativas?"]}'::jsonb, 'Billing, Pricing & Support', 'Billing, Pricing & Support', 'medium', 'scenario', '["support","professional-services"]'::jsonb, 'ai-draft', 'active', now(), now()),
    ('clf-c02-bill-025', 'aws-clf', 'Uma PME quer contratar um consultor AWS certificado para um projeto pontual de 2 semanas (configurar VPC + landing zone), com pagamento por projeto ou por hora. Qual oferta da AWS atende?', '[{"id":"A","text":"AWS IQ"},{"id":"B","text":"AWS Professional Services"},{"id":"C","text":"AWS Activate"},{"id":"D","text":"AWS Partner Network management"}]'::jsonb, 'A', '{"summary":"AWS IQ conecta clientes a Experts certificados (indivíduos ou pequenas empresas) para projetos curtos; pagamento via console AWS, com IAM cross-account temporário.","whyCorrect":"AWS IQ conecta clientes a Experts certificados (indivíduos ou pequenas empresas) para projetos curtos; pagamento via console AWS, com IAM cross-account temporário.","whyWrong":{"C":"Activate é programa para startups","B":"AWS Professional Services é o time de consultoria interno da AWS, focado em projetos grandes (migrações enterprise, modernization, ML em escala) com escopo de meses e contratos diretos com AWS Inc. Para uma PME com projeto de 2 semanas e pagamento pontual, ProServe é overhead caro e burocrático — o fit é AWS IQ.","D":"AWS Partner Network (APN) é o programa que classifica empresas parceiras (consultoras, ISVs) em tiers (Select, Advanced, Premier). Não é uma oferta para contratar consultores diretamente — é um diretório/programa de credenciamento. Para contratação direta de freelancer/consultor curto, a oferta certa é AWS IQ."},"keyConcept":"Regra: projeto curto e baseado em escopo → AWS IQ.","tutorSeeds":["Pode explicar com mais detalhe: Regra: projeto curto e baseado em escopo → AWS IQ?","Quais cenários reais aplicam Regra: projeto curto e baseado em escopo → AWS IQ?","Como AWS IQ se compara com alternativas?"]}'::jsonb, 'Billing, Pricing & Support', 'Billing, Pricing & Support', 'medium', 'scenario', '["support","aws-iq"]'::jsonb, 'ai-draft', 'active', now(), now()),
    ('clf-c02-bill-026', 'aws-clf', 'Sobre o plano Enterprise On-Ramp, qual statement é correto?', '[{"id":"A","text":"Inclui um TAM dedicado, igual ao Enterprise"},{"id":"B","text":"É um plano intermediário entre Business e Enterprise, com acesso a pool de TAMs e SLA <30min para business-critical down"},{"id":"C","text":"É mais barato que Business"},{"id":"D","text":"Foi descontinuado em 2024"}]'::jsonb, 'B', '{"summary":"Enterprise On-Ramp custa a partir de ~$5,500/mês, oferece pool de TAMs (não dedicado), 1 Concierge ad-hoc por mês e SLA <30min para business-critical.","whyCorrect":"Enterprise On-Ramp custa a partir de ~$5,500/mês, oferece pool de TAMs (não dedicado), 1 Concierge ad-hoc por mês e SLA <30min para business-critical.","whyWrong":{"A":"TAM dedicado é só Enterprise","C":"é mais caro que Business (que começa em $100)","D":"Enterprise On-Ramp continua disponível em 2026 como plano intermediário entre Business e Enterprise. Foi lançado em 2022 justamente para atender clientes que precisam de pool de TAMs e SLA mais agressivo sem o custo de $15k+/mês do Enterprise full. Não há indicação de descontinuação."},"keyConcept":"Regra: On-Ramp = Enterprise lite para empresas que ainda não justificam $15k+/mês.","tutorSeeds":["Pode explicar com mais detalhe: Regra: On-Ramp = Enterprise lite para empresas que ainda não justificam $15k+/mês?","Quais cenários reais aplicam Regra: On-Ramp = Enterprise lite para empresas que ainda não justificam $15k+/mês?","Como TAMs se compara com alternativas?"]}'::jsonb, 'Billing, Pricing & Support', 'Billing, Pricing & Support', 'hard', 'recall', '["support","on-ramp"]'::jsonb, 'ai-draft', 'active', now(), now()),
    ('clf-c02-bill-027', 'aws-clf', 'Um cliente Developer Support tenta abrir caso para um problema production-down e descobre que o SLA é apenas em horário comercial. O que o cliente deve fazer para ter SLA 24/7?', '[{"id":"A","text":"Pedir override pontual no console"},{"id":"B","text":"Fazer upgrade para Business ou superior"},{"id":"C","text":"Comprar Trusted Advisor full"},{"id":"D","text":"Solicitar via AWS IQ"}]'::jsonb, 'B', '{"summary":"Developer só atende em business hours (general guidance 24h, system impaired 12h).","whyCorrect":"Developer só atende em business hours (general guidance 24h, system impaired 12h). 24/7 é a partir de Business ($100/mês).","whyWrong":{"A":"AWS não faz override","C":"Trusted Advisor não inclui suporte","D":"AWS IQ é marketplace de consultores certificados para projetos pontuais — não é canal de suporte técnico AWS. Casos de production down devem ser abertos no AWS Support Center mediante plano apropriado; nenhum consultor IQ pode acionar o pipeline de engenharia AWS. O caminho correto é upgrade do plano de suporte."},"keyConcept":"Regra: 24/7 → Business+.","tutorSeeds":["Pode explicar com mais detalhe: Regra: 24/7 → Business+?","Quais cenários reais aplicam Regra: 24/7 → Business+?"]}'::jsonb, 'Billing, Pricing & Support', 'Billing, Pricing & Support', 'easy', 'troubleshoot', '["support","developer-plan","sla"]'::jsonb, 'ai-draft', 'active', now(), now()),
    ('clf-c02-bill-028', 'aws-clf', 'Uma empresa quer aplicar tags como `Project=alpha` e `CostCenter=eng` para que custos sejam quebrados por tag no Cost Explorer e CUR. O que precisa fazer além de tagear os recursos?', '[{"id":"A","text":"Nada — basta aplicar a tag"},{"id":"B","text":"Ativar as tags como cost allocation tags na console de Billing"},{"id":"C","text":"Migrar para AWS Organizations"},{"id":"D","text":"Comprar Business Support"}]'::jsonb, 'B', '{"summary":"Cost allocation tags exigem ativação explícita em Billing → Cost Allocation Tags antes de aparecerem como filtro/dimension em Cost Explorer e CUR.","whyCorrect":"Cost allocation tags exigem ativação explícita em Billing → Cost Allocation Tags antes de aparecerem como filtro/dimension em Cost Explorer e CUR.","whyWrong":{"A":"Apenas aplicar a tag não basta","C":"Organizations não é pré-requisito","D":"Cost allocation tags são feature gratuita do Billing, disponível em qualquer plano de suporte (inclusive Basic). Business Support adiciona Trusted Advisor full e SLA 24/7, mas não habilita nem é prerequisito de cost allocation tags. A ativação é feita no console Billing → Cost Allocation Tags, independente do plano."},"keyConcept":"Regra: tag + ativação como cost allocation tag.","tutorSeeds":["Pode explicar com mais detalhe: Regra: tag + ativação como cost allocation tag?","Quais cenários reais aplicam Regra: tag + ativação como cost allocation tag?","Como CUR se compara com alternativas?"]}'::jsonb, 'Billing, Pricing & Support', 'Billing, Pricing & Support', 'medium', 'best-practice', '["tagging","cost-allocation"]'::jsonb, 'ai-draft', 'active', now(), now()),
    ('clf-c02-bill-029', 'aws-clf', 'Qual a diferença entre AWS-generated cost allocation tags e user-defined cost allocation tags?', '[{"id":"A","text":"Não há — são sinônimos"},{"id":"B","text":"AWS-generated (ex: aws:createdBy) são geradas pela AWS; user-defined são criadas pelo cliente. Ambas exigem ativação para custo"},{"id":"C","text":"AWS-generated são pagas; user-defined são gratuitas"},{"id":"D","text":"Apenas user-defined funcionam em CUR"}]'::jsonb, 'B', '{"summary":"AWS gera tags como `aws:createdBy`, `aws:cloudformation:stack-name`; cliente cria tags arbitrárias `Environment=prod`.","whyCorrect":"AWS gera tags como `aws:createdBy`, `aws:cloudformation:stack-name`; cliente cria tags arbitrárias `Environment=prod`. Ambas precisam ser ativadas como cost allocation tag para aparecer em billing.","whyWrong":{"D":"ambas funcionam em CUR.","A":"Existe diferença clara e documentada: AWS-generated tags têm prefixo `aws:` (ex: `aws:createdBy`, `aws:cloudformation:stack-name`) e são imutáveis — o cliente não pode editá-las nem aplicá-las manualmente. User-defined tags têm chave arbitrária criada pelo cliente. Ambas precisam de ativação separada como cost allocation tag para aparecer em Cost Explorer/CUR.","C":"Tagueamento (incluindo cost allocation) é gratuito em AWS — não há cobrança por aplicar tags nem por ativá-las como cost allocation. O único custo associado é indireto: armazenamento do CUR no S3 e queries de Athena. Tanto AWS-generated quanto user-defined são gratuitas."},"keyConcept":"Regra: prefixo `aws:` = system tag; sem prefixo = user.","tutorSeeds":["Pode explicar com mais detalhe: Regra: prefixo `aws:` = system tag; sem prefixo = user?","Quais cenários reais aplicam Regra: prefixo `aws:` = system tag; sem prefixo = user?","Como AWS se compara com alternativas?"]}'::jsonb, 'Billing, Pricing & Support', 'Billing, Pricing & Support', 'hard', 'recall', '["tagging","cost-allocation"]'::jsonb, 'ai-draft', 'active', now(), now()),
    ('clf-c02-bill-030', 'aws-clf', 'Uma holding tem 12 contas AWS de diferentes BUs e quer consolidar billing, compartilhar Savings Plans e Reserved Instances, e centralizar limites de gasto. Qual serviço atende?', '[{"id":"A","text":"AWS Resource Access Manager"},{"id":"B","text":"AWS Organizations com consolidated billing"},{"id":"C","text":"AWS Control Tower somente"},{"id":"D","text":"AWS Cost Explorer multi-account standalone"}]'::jsonb, 'B', '{"summary":"Organizations com consolidated billing agrega faturas das contas member sob a management account, compartilha SP/RI por padrão (RI sharing on) e habilita SCPs/Budgets centralizados.","whyCorrect":"Organizations com consolidated billing agrega faturas das contas member sob a management account, compartilha SP/RI por padrão (RI sharing on) e habilita SCPs/Budgets centralizados.","whyWrong":{"C":"Control Tower setup multi-account em cima de Organizations (não substitui)","D":"Cost Explorer mostra dados consolidados quando Organizations já está ativo.","A":"AWS Resource Access Manager (RAM) compartilha RECURSOS específicos (subnets, Transit Gateways, License Manager configs) entre contas de uma Organization — não consolida billing nem compartilha SP/RI. RAM seria a resposta para ''compartilhar uma VPC ou um TGW entre múltiplas contas'', não para centralizar faturas e descontos."},"keyConcept":"Regra: consolidated billing → Organizations.","tutorSeeds":["Pode explicar com mais detalhe: Regra: consolidated billing → Organizations?","Quais cenários reais aplicam Regra: consolidated billing → Organizations?","Como SP se compara com alternativas?"]}'::jsonb, 'Billing, Pricing & Support', 'Billing, Pricing & Support', 'easy', 'scenario', '["organizations","consolidated-billing"]'::jsonb, 'ai-draft', 'active', now(), now()),
    ('clf-c02-bill-031', 'aws-clf', 'Uma management account de uma Organizations comprou um RI Standard. Por padrão, o desconto é aplicado a qual conta?', '[{"id":"A","text":"Apenas à management account"},{"id":"B","text":"À primeira conta member que usar o tipo de instância"},{"id":"C","text":"A qualquer conta da Organizations que use a instância matching, salvo se RI sharing estiver desativado"},{"id":"D","text":"Apenas a contas com Business Support"}]'::jsonb, 'C', '{"summary":"Por padrão RI sharing está ON: o desconto é aplicado horariamente a qualquer conta member que rode instância matching.","whyCorrect":"Por padrão RI sharing está ON: o desconto é aplicado horariamente a qualquer conta member que rode instância matching. Pode ser desativado por conta.","whyWrong":{"A":"Não é exclusivo da management","B":"Não há regra de ''primeira conta que usar'' — RI sharing aplica o desconto a QUALQUER conta member que tenha instância matching durante a hora de billing, podendo distribuir o benefício entre várias contas na mesma hora. Não é first-come-first-served.","D":"RI sharing em Organizations não tem dependência de plano de suporte — Basic Support em conta member já recebe o benefício de RI compartilhada da management account. Business Support adiciona Trusted Advisor full e SLA, mas é irrelevante para mecânica de RI sharing."},"keyConcept":"Regra: RI sharing on → benefício distribuído na Org.","tutorSeeds":["Pode explicar com mais detalhe: Regra: RI sharing on → benefício distribuído na Org?","Quais cenários reais aplicam Regra: RI sharing on → benefício distribuído na Org?","Como RI se compara com alternativas?"]}'::jsonb, 'Billing, Pricing & Support', 'Billing, Pricing & Support', 'medium', 'best-practice', '["organizations","reserved-instances","ri-sharing"]'::jsonb, 'ai-draft', 'active', now(), now()),
    ('clf-c02-bill-032', 'aws-clf', 'Sobre volume discounts em AWS Organizations consolidated billing, qual statement é correto?', '[{"id":"A","text":"Volume discounts são aplicados isoladamente por conta member"},{"id":"B","text":"Usos das contas member são agregados para atingir tiers de volume (ex: S3 storage) com desconto consolidado"},{"id":"C","text":"Volume discounts não existem em consolidated billing"},{"id":"D","text":"Aplica-se apenas a EC2"}]'::jsonb, 'B', '{"summary":"Consolidated billing soma o uso de todas as contas para fins de volume tiering (ex: S3, data transfer) — todas se beneficiam do tier alcançado pela soma.","whyCorrect":"Consolidated billing soma o uso de todas as contas para fins de volume tiering (ex: S3, data transfer) — todas se beneficiam do tier alcançado pela soma.","whyWrong":{"A":"Não é por conta","D":"aplica-se a vários serviços com tiered pricing","C":"Volume discounts EXISTEM em consolidated billing e são justamente um dos principais benefícios financeiros de usar Organizations. Serviços com tiered pricing (S3 storage, data transfer out) somam o uso de todas as contas member para determinar o tier — todas se beneficiam do tier coletivo alcançado."},"keyConcept":"Regra: consolidated billing = melhor pricing tier coletivo.","tutorSeeds":["Pode explicar com mais detalhe: Regra: consolidated billing = melhor pricing tier coletivo?","Quais cenários reais aplicam Regra: consolidated billing = melhor pricing tier coletivo?"]}'::jsonb, 'Billing, Pricing & Support', 'Billing, Pricing & Support', 'hard', 'recall', '["organizations","volume-discount"]'::jsonb, 'ai-draft', 'active', now(), now()),
    ('clf-c02-bill-033', 'aws-clf', 'Uma equipe FinOps quer impor uma tagging policy que rejeite recursos criados sem a tag `CostCenter`. Qual abordagem nativa do AWS Organizations atende?', '[{"id":"A","text":"Tag Policies do AWS Organizations"},{"id":"B","text":"IAM password policy"},{"id":"C","text":"AWS Trusted Advisor"},{"id":"D","text":"Service Catalog"}]'::jsonb, 'A', '{"summary":"Tag Policies do Organizations definem regras de tag (key/value padronizados) e reportam não-conformidade; combinadas com SCPs, podem bloquear criação sem tags.","whyCorrect":"Tag Policies do Organizations definem regras de tag (key/value padronizados) e reportam não-conformidade; combinadas com SCPs, podem bloquear criação sem tags.","whyWrong":{"B":"IAM password policy é de senha","C":"Trusted Advisor recomenda sem impor","D":"Service Catalog padroniza produtos."},"keyConcept":"Regra: governance de tag → Tag Policies + SCP.","tutorSeeds":["Pode explicar com mais detalhe: Regra: governance de tag → Tag Policies + SCP?","Quais cenários reais aplicam Regra: governance de tag → Tag Policies + SCP?","Como SCPs se compara com alternativas?"]}'::jsonb, 'Billing, Pricing & Support', 'Billing, Pricing & Support', 'medium', 'best-practice', '["tagging","organizations","tag-policies"]'::jsonb, 'ai-draft', 'active', now(), now()),
    ('clf-c02-bill-034', 'aws-clf', 'Uma startup com Basic Support liga querendo full Trusted Advisor (todas as categorias de checks). Como obter?', '[{"id":"A","text":"Basic já inclui Trusted Advisor full"},{"id":"B","text":"Upgrade para Business, Enterprise On-Ramp ou Enterprise"},{"id":"C","text":"Comprar Trusted Advisor avulso"},{"id":"D","text":"Pedir ao AWS IQ"}]'::jsonb, 'B', '{"summary":"Basic/Developer têm apenas 7 checks core (Service Quotas + 6 security); Business/On-Ramp/Enterprise habilitam todas as 5 categorias (Cost, Performance, Security, Fault Tolerance, Service Limits).","whyCorrect":"Basic/Developer têm apenas 7 checks core (Service Quotas + 6 security); Business/On-Ramp/Enterprise habilitam todas as 5 categorias (Cost, Performance, Security, Fault Tolerance, Service Limits).","whyWrong":{"A":"Basic é limitado","C":"não há SKU avulso","D":"AWS IQ é marketplace para contratar consultores certificados em projetos pontuais — não habilita nem entrega checks do Trusted Advisor. Trusted Advisor é serviço AWS interno cujo escopo de checks é determinado exclusivamente pelo plano de suporte da conta. Upgrade do plano é o único caminho para destravar os checks completos."},"keyConcept":"Regra: full Trusted Advisor → Business+.","tutorSeeds":["Pode explicar com mais detalhe: Regra: full Trusted Advisor → Business+?","Quais cenários reais aplicam Regra: full Trusted Advisor → Business+?"]}'::jsonb, 'Billing, Pricing & Support', 'Billing, Pricing & Support', 'easy', 'best-practice', '["trusted-advisor","support"]'::jsonb, 'ai-draft', 'active', now(), now()),
    ('clf-c02-bill-035', 'aws-clf', 'Quais são as 5 categorias de checks do AWS Trusted Advisor?', '[{"id":"A","text":"Cost, Performance, Security, Fault Tolerance, Service Limits"},{"id":"B","text":"Compute, Storage, Database, Network, Security"},{"id":"C","text":"Reliability, Security, Cost, Performance, Sustainability"},{"id":"D","text":"Operational, Security, Reliability, Performance, Cost"}]'::jsonb, 'A', '{"summary":"As 5 categorias do Trusted Advisor são Cost Optimization, Performance, Security, Fault Tolerance e Service Limits (quotas).","whyCorrect":"As 5 categorias do Trusted Advisor são Cost Optimization, Performance, Security, Fault Tolerance e Service Limits (quotas).","whyWrong":{"C":"opção C/D são pilares do Well-Architected Framework (que tem 6: + Operational Excellence, Sustainability).","B":"Esta lista mistura categorias de serviço (Compute, Storage, Database, Network) com Security — corresponde a uma taxonomia de produtos AWS, não às categorias de checks do Trusted Advisor. Trusted Advisor categoriza por dimensão de qualidade arquitetural, não por tipo de serviço.","D":"Esta lista (Operational, Security, Reliability, Performance, Cost) corresponde aos 5 pilares originais do AWS Well-Architected Framework — não às categorias do Trusted Advisor. Confusão comum: Well-Architected é framework de design/review; Trusted Advisor é serviço de checks automatizados sobre a conta."},"keyConcept":"Regra: TA ≠ Well-Architected.","tutorSeeds":["Pode explicar com mais detalhe: Regra: TA ≠ Well-Architected?","Quais cenários reais aplicam Regra: TA ≠ Well-Architected?"]}'::jsonb, 'Billing, Pricing & Support', 'Billing, Pricing & Support', 'easy', 'recall', '["trusted-advisor"]'::jsonb, 'ai-draft', 'active', now(), now()),
    ('clf-c02-bill-036', 'aws-clf', 'Qual check do Trusted Advisor identifica buckets S3 com permissão pública de leitura/escrita?', '[{"id":"A","text":"Cost Optimization → Idle Load Balancers"},{"id":"B","text":"Security → Amazon S3 Bucket Permissions"},{"id":"C","text":"Performance → Overutilized EC2"},{"id":"D","text":"Service Limits → S3 Bucket count"}]'::jsonb, 'B', '{"summary":"Trusted Advisor inclui check Security → S3 Bucket Permissions, sinalizando buckets com ACLs públicas ou bucket policies permissivas.","whyCorrect":"Trusted Advisor inclui check Security → S3 Bucket Permissions, sinalizando buckets com ACLs públicas ou bucket policies permissivas.","whyWrong":{"A":"Idle Load Balancers é um check de Cost Optimization que sinaliza ALBs/NLBs sem traffic ou backend saudável para reduzir gasto — não tem relação com permissões de S3. Seria a resposta para ''identificar load balancers desperdiçando dinheiro sem uso''.","C":"Overutilized EC2 é check de Performance que sinaliza instâncias com CPU/memória/network consistentemente saturadas, sugerindo upgrade de tipo — escopo de capacity planning, não de segurança de S3. Seria a resposta para ''identificar instâncias EC2 sobrecarregadas''.","D":"S3 Bucket count é um Service Limits check que monitora aproximação ao limite de 1000 buckets por conta — é sobre quotas, não sobre permissões. Seria a resposta para ''identificar contas próximas de atingir o limite de buckets''."},"keyConcept":"Regra: permissões públicas S3 → categoria Security.","tutorSeeds":["Pode explicar com mais detalhe: Regra: permissões públicas S3 → categoria Security?","Quais cenários reais aplicam Regra: permissões públicas S3 → categoria Security?","Como ACLs se compara com alternativas?"]}'::jsonb, 'Billing, Pricing & Support', 'Billing, Pricing & Support', 'medium', 'scenario', '["trusted-advisor","security","s3"]'::jsonb, 'ai-draft', 'active', now(), now()),
    ('clf-c02-bill-037', 'aws-clf', 'Uma equipe quer aproveitar Savings Plans existentes, mas observa cobertura abaixo de 60%. Qual ferramenta gera recomendações de novos commits para maximizar cobertura?', '[{"id":"A","text":"Trusted Advisor → Cost Optimization"},{"id":"B","text":"AWS Cost Explorer → Savings Plans Recommendations"},{"id":"C","text":"AWS Pricing Calculator"},{"id":"D","text":"AWS Config"}]'::jsonb, 'B', '{"summary":"Cost Explorer tem seção dedicada de Savings Plans Recommendations com análise de uso histórico e simulação de termos (1y/3y, payment option).","whyCorrect":"Cost Explorer tem seção dedicada de Savings Plans Recommendations com análise de uso histórico e simulação de termos (1y/3y, payment option).","whyWrong":{"A":"Trusted Advisor sugere RIs idle/underutilized mas não SP commits novos detalhados","C":"Pricing Calculator é manual","D":"Config não trata custo."},"keyConcept":"Regra: recomendação algorítmica de SP → Cost Explorer.","tutorSeeds":["Pode explicar com mais detalhe: Regra: recomendação algorítmica de SP → Cost Explorer?","Quais cenários reais aplicam Regra: recomendação algorítmica de SP → Cost Explorer?"]}'::jsonb, 'Billing, Pricing & Support', 'Billing, Pricing & Support', 'hard', 'best-practice', '["billing-tools","savings-plans","cost-explorer"]'::jsonb, 'ai-draft', 'active', now(), now()),
    ('clf-c02-bill-038', 'aws-clf', 'Uma startup elegível recebeu créditos AWS via AWS Activate. Como eles aparecem no billing?', '[{"id":"A","text":"Como linha negativa aplicada automaticamente até o limite/expiração"},{"id":"B","text":"Como reembolso em cartão"},{"id":"C","text":"Como Savings Plans"},{"id":"D","text":"Como tag aws:credit nos recursos"}]'::jsonb, 'A', '{"summary":"Créditos aparecem como crédito aplicado na fatura (linha negativa), respeitando regras de elegibilidade por serviço/região e data de expiração configurada.","whyCorrect":"Créditos aparecem como crédito aplicado na fatura (linha negativa), respeitando regras de elegibilidade por serviço/região e data de expiração configurada.","whyWrong":{"B":"Não há reembolso de cartão","D":"não tagueiam recursos.","C":"Savings Plans são compromissos de gasto $/hora comprados pelo cliente (1 ou 3 anos) — créditos AWS Activate são benefícios promocionais (linha negativa na fatura). São mecanismos contábeis e operacionais completamente distintos: SP gera desconto sobre uso futuro mediante commit; créditos abatem o valor faturado. Activate não é entregue na forma de SP."},"keyConcept":"Regra: créditos AWS são aplicados automaticamente até esgotar/expirar.","tutorSeeds":["Pode explicar com mais detalhe: Regra: créditos AWS são aplicados automaticamente até esgotar/expirar?","Quais cenários reais aplicam Regra: créditos AWS são aplicados automaticamente até esgotar/expirar?"]}'::jsonb, 'Billing, Pricing & Support', 'Billing, Pricing & Support', 'medium', 'best-practice', '["billing-tools","credits","activate"]'::jsonb, 'ai-draft', 'active', now(), now()),
    ('clf-c02-bill-039', 'aws-clf', 'Uma equipe FinOps quer impedir que contas member criem recursos em regiões não-aprovadas (por compliance) sem afetar billing. Qual ferramenta usar?', '[{"id":"A","text":"AWS Budgets"},{"id":"B","text":"SCPs (Service Control Policies) no AWS Organizations"},{"id":"C","text":"Cost Anomaly Detection"},{"id":"D","text":"Trusted Advisor"}]'::jsonb, 'B', '{"summary":"SCPs do Organizations restringem ações IAM em contas member — incluindo deny de regiões específicas via condition `aws:RequestedRegion`.","whyCorrect":"SCPs do Organizations restringem ações IAM em contas member — incluindo deny de regiões específicas via condition `aws:RequestedRegion`.","whyWrong":{"A":"Budgets alerta gasto mas não impede","C":"Cost Anomaly detecta desvios","D":"Trusted Advisor recomenda."},"keyConcept":"Regra: enforcement preventivo → SCP.","tutorSeeds":["Pode explicar com mais detalhe: Regra: enforcement preventivo → SCP?","Quais cenários reais aplicam Regra: enforcement preventivo → SCP?","Como SCPs se compara com alternativas?"]}'::jsonb, 'Billing, Pricing & Support', 'Billing, Pricing & Support', 'medium', 'best-practice', '["organizations","scp","governance"]'::jsonb, 'ai-draft', 'active', now(), now()),
    ('clf-c02-bill-040', 'aws-clf', 'Uma empresa que rodava EC2 m5.xlarge em On-Demand a $0.192/h migrou para Compute Savings Plan 1y All Upfront com desconto de 50%. Sobre o efetivo desconto, qual statement é correto?', '[{"id":"A","text":"O desconto aplica-se a horas além do commit em All Upfront sem custo adicional"},{"id":"B","text":"Horas até o commit/hora são cobertas pelo SP; horas excedentes voltam a On-Demand a $0.192/h"},{"id":"C","text":"All Upfront permite cobrir 100% das horas do ano sem limite"},{"id":"D","text":"Após esgotar o crédito, o custo cai para zero"}]'::jsonb, 'B', '{"summary":"SP comprometem um valor $/hora; uso até esse hourly commit é coberto com desconto; uso adicional é cobrado a On-Demand.","whyCorrect":"SP comprometem um valor $/hora; uso até esse hourly commit é coberto com desconto; uso adicional é cobrado a On-Demand.","whyWrong":{"A":"Não há cobertura ilimitada (depende do commit/h) All Upfront paga upfront mas com mesmo commit/h","D":"nunca cai a zero.","C":"All Upfront refere-se a COMO o commit é pago (100% adiantado, gerando desconto extra) — não a QUE quantidade de uso é coberto. O commit em $/hora é o mesmo independentemente de payment option; horas que excedem o commit/h voltam a On-Demand. All Upfront vs Partial vs No Upfront muda só o cashflow e o desconto efetivo, não o teto de cobertura."},"keyConcept":"Regra: SP cobrem até o commit/h — dimensionar com cuidado.","tutorSeeds":["Pode explicar com mais detalhe: Regra: SP cobrem até o commit/h — dimensionar com cuidado?","Quais cenários reais aplicam Regra: SP cobrem até o commit/h — dimensionar com cuidado?","Como SP se compara com alternativas?"]}'::jsonb, 'Billing, Pricing & Support', 'Billing, Pricing & Support', 'hard', 'troubleshoot', '["pricing","savings-plans"]'::jsonb, 'ai-draft', 'active', now(), now()),
    ('clf-c02-bill-v2-001', 'aws-clf', 'Uma empresa roda workload misto: 200 vCPU em EC2 (várias famílias), 50 funções Lambda críticas e 30 tarefas Fargate. Quer um único commitment que reduza custo em todos esses serviços ao máximo com flexibilidade de família e região. Qual Savings Plan escolher?', '[{"id":"A","text":"EC2 Instance Savings Plans em cada família predominante"},{"id":"B","text":"Compute Savings Plans de 1 ou 3 anos"},{"id":"C","text":"SageMaker Savings Plans"},{"id":"D","text":"Reserved Instances Standard regionais"}]'::jsonb, 'B', '{"summary":"Compute Savings Plans é o único tipo que cobre EC2 + Fargate + Lambda simultaneamente, com flexibilidade cross-família e cross-região.","whyCorrect":"Compute SP aplica desconto (~66%) em qualquer uso de EC2 (qualquer família, tamanho, OS, tenancy, região), Fargate e Lambda. É exatamente o caso de uso de workload misto.","whyWrong":{"A":"EC2 Instance SP cobre APENAS EC2 numa família+região específicas. Não cobre Lambda nem Fargate, e exige múltiplos commitments separados por família.","C":"SageMaker SP cobre apenas instâncias SageMaker (ml.*). Não se aplica a EC2 genérico, Lambda ou Fargate.","D":"RI Standard cobre só EC2 (não Lambda nem Fargate) e Regional RI dá flexibilidade de AZ/size dentro da família apenas — não cross-família."},"keyConcept":"Hierarquia de Savings Plans: Compute SP (máxima flexibilidade, ~66% off) > EC2 Instance SP (família+região fixas, ~72% off) > SageMaker SP (só ML). Escolha pelo escopo do workload.","compareWith":["EC2 Instance Savings Plans","SageMaker Savings Plans","Reserved Instances Standard"],"realWorldContext":"Empresas com arquitetura mista (web/API em EC2, eventos em Lambda, containers em Fargate) padronizam em Compute SP. Trocar ''qual família vou usar daqui a 12 meses?'' por ''qual gasto $/h vou manter?'' é o ponto.","commonMistakes":"Achar que Compute SP cobre RDS, ElastiCache ou Redshift — NÃO cobre. Para RDS/ElastiCache/Redshift/OpenSearch existem Reserved Nodes/Instances específicas, não Savings Plans.","tutorSeeds":["Por que Compute SP dá menos desconto que EC2 Instance SP?","Quais serviços NÃO são cobertos por Compute Savings Plans?"]}'::jsonb, 'Billing, Pricing & Support', 'Billing, Pricing & Support', 'medium', 'scenario', '["savings-plans","compute-sp","lambda","fargate"]'::jsonb, 'ai-draft', 'active', now(), now()),
    ('clf-c02-bill-v2-002', 'aws-clf', 'O CFO autoriza um commitment de Savings Plans, mas tem caixa restrito no primeiro mês. Entre as opções de pagamento (All Upfront, Partial Upfront, No Upfront) de um Compute SP de 1 ano, qual a relação correta entre pagamento e desconto?', '[{"id":"A","text":"Todas as opções dão o mesmo desconto, só muda o cronograma de cobrança"},{"id":"B","text":"All Upfront dá o maior desconto; No Upfront, o menor; Partial fica no meio"},{"id":"C","text":"No Upfront dá maior desconto porque a AWS prefere fluxo recorrente"},{"id":"D","text":"Só All Upfront é elegível para Compute SP"}]'::jsonb, 'B', '{"summary":"Quanto mais cedo o pagamento, maior o desconto efetivo — All Upfront > Partial > No Upfront.","whyCorrect":"A AWS recompensa risco financeiro antecipado: All Upfront paga 100% no início e tem o maior desconto efetivo. Partial paga 50% upfront + mensal. No Upfront paga só mensalmente — o desconto cai poucos pontos percentuais comparado a All Upfront.","whyWrong":{"A":"Falso. As três opções têm descontos efetivos diferentes, embora a diferença entre elas seja pequena (1–3 pp).","C":"Inverso. A AWS premia caixa antecipado, não fluxo recorrente.","D":"Falso. Compute SP aceita as três opções de pagamento."},"keyConcept":"Trade-off de Savings Plans: maior commitment financeiro upfront = maior desconto. Avaliar custo de oportunidade do caixa vs economia adicional.","compareWith":["RI All/Partial/No Upfront","Pagamento antecipado em commitments cloud em geral"],"realWorldContext":"Para a maioria das empresas, Partial Upfront é o ponto ótimo: ~50% do desconto máximo sem comprometer caixa integralmente. Startups em runway curto preferem No Upfront mesmo perdendo ~3 pp.","commonMistakes":"Pensar que No Upfront ''não tem commitment'' — TEM. Você se obriga ao gasto mensal mesmo sem uso; cobrança continua se workload some.","tutorSeeds":["Como calcular o break-even entre Partial e All Upfront?","O que acontece se eu deletar todas as instâncias com Compute SP ativo?"]}'::jsonb, 'Billing, Pricing & Support', 'Billing, Pricing & Support', 'easy', 'recall', '["savings-plans","payment-options"]'::jsonb, 'ai-draft', 'active', now(), now()),
    ('clf-c02-bill-v2-003', 'aws-clf', 'Time de ML usa instâncias ml.p4d.24xlarge no SageMaker Training 24/7. Quer reduzir custo, mas mantém liberdade de mudar entre ml.p4d e ml.g5 conforme experimento. Qual commitment é o adequado?', '[{"id":"A","text":"EC2 Instance Savings Plans família p4d"},{"id":"B","text":"Compute Savings Plans"},{"id":"C","text":"SageMaker Savings Plans"},{"id":"D","text":"Reserved Instances padrão EC2"}]'::jsonb, 'C', '{"summary":"SageMaker Savings Plans é o único que cobre uso do SageMaker (Training, Inference, Notebooks, Processing) com flexibilidade entre famílias ml.*.","whyCorrect":"SageMaker SP foi criado especificamente para workloads ml.*: cobre Training, RealTime Inference, Batch Transform, Notebook, Processing, Data Wrangler, Studio. Permite mudar entre famílias (ml.p4d, ml.g5, ml.c5, etc.) dentro do compromisso de $/h.","whyWrong":{"A":"EC2 Instance SP não cobre SageMaker. Instâncias ml.* são gerenciadas pelo SageMaker e cobradas em SKU separado de EC2.","B":"Compute SP cobre apenas EC2, Lambda e Fargate. NÃO cobre SageMaker.","D":"EC2 RI também não se aplica a ml.* instances do SageMaker — é cobrança diferente."},"keyConcept":"Cada família de Savings Plan tem escopo de serviços específico. SageMaker tem SKU separado do EC2; precisa de SP dedicado.","compareWith":["Compute SP","EC2 Instance SP","EC2 Reserved Instances"],"realWorldContext":"Times de ML que rodam treinamento contínuo (foundational models, fine-tuning constante) economizam ~64% com SageMaker SP de 3 anos All Upfront. Sem SP, ml.p4d.24xlarge On-Demand chega a ~$32/h.","commonMistakes":"Comprar Compute SP achando que vai cobrir SageMaker — a fatura continua cobrando o uso ml.* em On-Demand.","tutorSeeds":["Por que a AWS separou SageMaker das outras famílias de SP?","SageMaker Serverless Inference é coberto pelo SageMaker SP?"]}'::jsonb, 'Billing, Pricing & Support', 'Billing, Pricing & Support', 'medium', 'scenario', '["savings-plans","sagemaker","ml"]'::jsonb, 'ai-draft', 'active', now(), now()),
    ('clf-c02-bill-v2-004', 'aws-clf', 'Empresa estuda Savings Plans de 1 ano vs 3 anos. Roadmap diz que migração para Graviton (arm64) acontece em 14 meses, com mudança de famílias e possível redução de footprint de 40%. Qual a recomendação mais prudente?', '[{"id":"A","text":"Comprar 3 anos All Upfront — maior desconto independe da migração"},{"id":"B","text":"Comprar 1 ano No Upfront e reavaliar após a migração"},{"id":"C","text":"Misturar 3 anos All Upfront em 100% do baseline e cobrir picos com On-Demand"},{"id":"D","text":"Não comprar nada e usar On-Demand até a migração"}]'::jsonb, 'B', '{"summary":"Com mudança arquitetural prevista em 14 meses e possível redução de footprint, 1 ano é mais prudente que 3 anos.","whyCorrect":"Compute SP é flexível entre famílias (incluindo Graviton), mas o commitment é em $/h. Se o footprint cai 40%, sobra commitment não utilizado por ~22 meses no plano de 3 anos. O plano de 1 ano permite recalibrar após a migração.","whyWrong":{"A":"Maximizar desconto sem considerar o commitment de gasto é armadilha — sobra de SP vira custo sem uso correspondente.","C":"Comprar 3 anos em 100% do baseline atual ignora que o baseline vai diminuir; mesmo problema do A.","D":"Renunciar a ~30% de desconto durante 14 meses é desperdício; o risco de 1 ano é baixo."},"keyConcept":"Prazo do Savings Plan deve casar com horizonte de visibilidade do workload. 3 anos para steady state confirmado; 1 ano quando há mudanças previstas.","compareWith":["RI Convertible (permite trocar família mas mantém commitment)","On-Demand"],"realWorldContext":"Migração para Graviton tipicamente reduz custo de compute em 20–40% adicional. Combinar essa redução com SP existente exige cálculo cuidadoso de break-even.","commonMistakes":"Comprar 3 anos pelo desconto sem considerar volatilidade do workload — empresa fica pagando SP fantasma.","tutorSeeds":["Compute SP cobre Graviton automaticamente?","Como dimensionar o tamanho do commitment ($/h) de um SP?"]}'::jsonb, 'Billing, Pricing & Support', 'Billing, Pricing & Support', 'hard', 'scenario', '["savings-plans","graviton","term-length"]'::jsonb, 'ai-draft', 'active', now(), now()),
    ('clf-c02-bill-v2-005', 'aws-clf', 'Um Compute Savings Plan já está ativo. O time scala up adicionando novas instâncias EC2 c7g em outra região. Como o desconto se comporta?', '[{"id":"A","text":"Não se aplica — Compute SP cobre apenas a região onde foi comprado"},{"id":"B","text":"Aplica-se automaticamente até o limite de $/h não consumido em outras instâncias"},{"id":"C","text":"Aplica somente após reativação manual no console"},{"id":"D","text":"Aplica só se as instâncias forem da mesma família que existia antes"}]'::jsonb, 'B', '{"summary":"Compute SP é cross-região e cross-família por padrão; o desconto é aplicado automaticamente até esgotar o commitment de $/h.","whyCorrect":"O motor de billing avalia uso elegível por hora e aplica o desconto até o limite do commitment $/h, priorizando o uso de maior desconto on-demand-equivalent. Não importa a região nem família.","whyWrong":{"A":"Confunde com EC2 Instance SP, que é fixo em região+família. Compute SP é global na conta.","C":"Não há reativação manual — aplicação é automática pelo billing engine a cada hora.","D":"Compute SP cobre todas as famílias EC2 e ainda Lambda/Fargate; não há restrição."},"keyConcept":"Compute SP funciona como ''crédito horário de gasto'' — qualquer uso elegível desconta do crédito até o teto $/h.","compareWith":["EC2 Instance SP (região+família fixas)","RI Regional (família fixa, região fixa)"],"realWorldContext":"Times multi-região usam um único Compute SP corporativo que cobre us-east-1, sa-east-1 e eu-west-1 simultaneamente — sem precisar dividir commitments.","commonMistakes":"Comprar múltiplos Compute SPs achando que precisa um por região — desperdício, um único SP cobre tudo.","tutorSeeds":["Como o billing engine prioriza qual instância recebe desconto primeiro?","O que é ''on-demand equivalent rate''?"]}'::jsonb, 'Billing, Pricing & Support', 'Billing, Pricing & Support', 'medium', 'scenario', '["savings-plans","compute-sp","cross-region"]'::jsonb, 'ai-draft', 'active', now(), now()),
    ('clf-c02-bill-v2-006', 'aws-clf', 'Comparando EC2 Instance Savings Plans de 3 anos All Upfront com Compute Savings Plans de 3 anos All Upfront para a mesma família m6i em us-east-1, qual a diferença esperada de desconto?', '[{"id":"A","text":"EC2 Instance SP dá ~72%, Compute SP dá ~66% — Instance é maior por ser mais restrito"},{"id":"B","text":"Compute SP sempre dá maior desconto por ser mais flexível"},{"id":"C","text":"Ambos dão exatamente o mesmo desconto"},{"id":"D","text":"Não existe Instance SP de 3 anos — só de 1 ano"}]'::jsonb, 'A', '{"summary":"EC2 Instance SP dá desconto maior (~72%) que Compute SP (~66%) na mesma família, porque exige commitment fixo em família+região.","whyCorrect":"Trade-off padrão da AWS: mais restrição = mais desconto. EC2 Instance SP trava região e família; em troca, oferece desconto similar ao RI Standard. Compute SP é flexível mas paga preço pela flexibilidade.","whyWrong":{"B":"Inverso — flexibilidade custa desconto, não dá. Compute SP é menor que Instance SP.","C":"Falso — descontos diferem em até 6 pp.","D":"Falso. Instance SP existe em 1 ou 3 anos, igual Compute SP."},"keyConcept":"Regra de ouro de pricing AWS: quanto mais restrição você aceita (família, região, AZ, prazo, pagamento upfront), maior o desconto.","compareWith":["RI Standard (~72%)","RI Convertible (~66%)","Compute SP (~66%)","EC2 Instance SP (~72%)"],"realWorldContext":"Padrão de mercado: usar EC2 Instance SP para o baseline ''cravado'' (família que você TEM CERTEZA que vai manter) + Compute SP para a camada flexível.","commonMistakes":"Comprar 100% em EC2 Instance SP de uma família — qualquer mudança de família desperdiça o SP.","tutorSeeds":["Posso ter EC2 Instance SP e Compute SP ativos ao mesmo tempo?","Qual a ordem de aplicação de descontos entre RI, Instance SP e Compute SP?"]}'::jsonb, 'Billing, Pricing & Support', 'Billing, Pricing & Support', 'medium', 'recall', '["savings-plans","compute-sp","instance-sp"]'::jsonb, 'ai-draft', 'active', now(), now()),
    ('clf-c02-bill-v2-007', 'aws-clf', 'Equipe FinOps quer entender a ordem em que descontos são aplicados quando uma conta tem RI Standard, EC2 Instance SP e Compute SP ativos simultaneamente. Qual é a ordem correta?', '[{"id":"A","text":"Compute SP → Instance SP → RI"},{"id":"B","text":"RI → EC2 Instance SP → Compute SP"},{"id":"C","text":"É aleatório a cada hora"},{"id":"D","text":"Sempre o que dá maior desconto primeiro, ignorando o tipo"}]'::jsonb, 'B', '{"summary":"Ordem fixa: RI primeiro (descontos mais granulares), depois EC2 Instance SP, por fim Compute SP — sempre maximizando o uso dos commitments mais restritos.","whyCorrect":"A AWS aplica primeiro o RI (que é instance-specific), depois EC2 Instance SP (família+região fixas) e por último Compute SP (flexível). Isso garante que o cliente não desperdice commitments mais restritivos.","whyWrong":{"A":"Ordem inversa — gastaria Compute SP primeiro e poderia deixar RI/Instance SP ocioso.","C":"Não é aleatório — há ordem determinística documentada.","D":"Não é por desconto, é por especificidade do commitment."},"keyConcept":"Aplicação de descontos vai do mais específico para o mais flexível, protegendo o cliente de desperdiçar commitments com escopo estreito.","compareWith":["Bin-packing de descontos","Como Cost Explorer mostra utilização de RI/SP"],"realWorldContext":"Cost Explorer → Reservations / Savings Plans Utilization mostra % de uso de cada commitment. Ideal: RI e Instance SP a 100%, Compute SP a 100% — qualquer < 95% é sinal de over-commitment.","commonMistakes":"Comprar RI Standard zonal e Compute SP cobrindo a mesma instância — RI é aplicado primeiro, mas se RI vence e Compute SP sobra, há período de overlap mal otimizado.","tutorSeeds":["Como ver a ordem de aplicação na fatura?","O que é ''unused commitment'' e como evitar?"]}'::jsonb, 'Billing, Pricing & Support', 'Billing, Pricing & Support', 'hard', 'best-practice', '["savings-plans","ri","discount-order"]'::jsonb, 'ai-draft', 'active', now(), now()),
    ('clf-c02-bill-v2-008', 'aws-clf', 'Após 18 meses do SP de 3 anos, o time descobre que está sub-utilizando o commitment ($/h efetivo está em 70% do plano). Qual ação está disponível?', '[{"id":"A","text":"Cancelar o SP e receber reembolso proporcional"},{"id":"B","text":"Reduzir o commitment $/h via console"},{"id":"C","text":"Continuar pagando o commitment; SPs não podem ser cancelados nem reduzidos"},{"id":"D","text":"Trocar por outro SP de prazo menor"}]'::jsonb, 'C', '{"summary":"Savings Plans não podem ser cancelados, reduzidos nem trocados; o commitment é firme até o fim do prazo.","whyCorrect":"Diferente de RI Convertible (que permite trocar por outro RI Convertible), SPs são compromissos firmes. AWS oferece em troca a flexibilidade interna (cross-família/região) — mas não cancelamento.","whyWrong":{"A":"Não há reembolso. Após compra, o commitment é irrevogável.","B":"Console não tem opção de reduzir; apenas de comprar SPs adicionais.","D":"SPs não podem ser trocados — só RI Convertible tem essa flexibilidade."},"keyConcept":"Savings Plans = trade-off entre flexibilidade de uso (cross-família/região) e flexibilidade financeira (sem cancelamento). RI Convertible tem flexibilidade financeira (troca), mas é mais limitado em uso.","compareWith":["RI Standard (no cancelamento, vendável no Marketplace)","RI Convertible (trocável)","On-Demand"],"realWorldContext":"Erro caro: comprar 3 anos em volume agressivo e ter contração de workload. Best-practice é começar com 60–70% do baseline em SP, deixar 30–40% em On-Demand para absorver volatilidade.","commonMistakes":"Achar que ''Convertible'' aplica a SP — não aplica. Só RI Convertible permite troca.","tutorSeeds":["Posso revender SP no Marketplace?","Como mitigar over-commitment de SP?"]}'::jsonb, 'Billing, Pricing & Support', 'Billing, Pricing & Support', 'medium', 'troubleshoot', '["savings-plans","cancellation","commitment"]'::jsonb, 'ai-draft', 'active', now(), now()),
    ('clf-c02-bill-v2-009', 'aws-clf', 'Empresa quer flexibilidade para trocar de família (de m5 para m7i, depois para m7g Graviton) ao longo de 3 anos, sem perder o desconto. Qual instrumento de compra é o adequado?', '[{"id":"A","text":"Reserved Instances Standard regional"},{"id":"B","text":"Reserved Instances Convertible"},{"id":"C","text":"EC2 Instance Savings Plans"},{"id":"D","text":"Spot Instances com fleet"}]'::jsonb, 'B', '{"summary":"RI Convertible é o único que permite trocar família/OS/tenancy/região durante o termo, mantendo o desconto.","whyCorrect":"RI Convertible permite operações ''exchange'' — troca por outro RI Convertible de igual ou maior valor. Suporta mudança de família, OS, tenancy e região. Ideal para roadmaps multi-família.","whyWrong":{"A":"RI Standard regional é fixo em família; só permite mudar tamanho dentro da mesma família. Pode ser vendido no Marketplace, mas não trocado.","C":"EC2 Instance SP é fixo em família+região; não permite troca de família.","D":"Spot não tem ''desconto fixo''; é preço de mercado volátil e pode ser interrompido."},"keyConcept":"RI Convertible troca desconto (~66% vs ~72% do Standard) por flexibilidade contratual de mudança de família/OS/tenancy.","compareWith":["RI Standard","Compute SP (mais flexível ainda, sem precisar de exchange)"],"realWorldContext":"Convertible já foi muito usado, mas Compute SP cobre 80% dos casos com menos burocracia (sem precisar fazer ''exchange''). Convertible ainda faz sentido em famílias específicas que SP não cobre bem.","commonMistakes":"Confundir Convertible com Standard regional — Standard só muda size dentro da família, não troca família.","tutorSeeds":["Quando RI Convertible ainda vale mais que Compute SP?","Como funciona a operação ''exchange'' de RI Convertible?"]}'::jsonb, 'Billing, Pricing & Support', 'Billing, Pricing & Support', 'medium', 'scenario', '["ri","convertible","exchange"]'::jsonb, 'ai-draft', 'active', now(), now()),
    ('clf-c02-bill-v2-010', 'aws-clf', 'Para garantir capacidade reservada (capacity reservation) numa AZ específica para um workload de baixa latência, qual variante de RI é a única que oferece capacity reservation por design?', '[{"id":"A","text":"RI Standard regional"},{"id":"B","text":"RI Standard zonal"},{"id":"C","text":"RI Convertible regional"},{"id":"D","text":"Compute Savings Plans"}]'::jsonb, 'B', '{"summary":"Apenas Zonal RIs reservam capacidade na AZ; Regional RIs e SPs dão apenas billing discount, sem garantia de capacidade.","whyCorrect":"RI Standard zonal especifica a AZ e reserva capacidade ali (a AWS garante que a instância poderá ser lançada). Regional RIs só dão desconto sobre uso sem reservar capacidade.","whyWrong":{"A":"Regional RI dá desconto e flexibilidade de AZ, MAS não reserva capacidade — em evento de scarcity, pode haver Insufficient Capacity Error.","C":"Convertible regional também não reserva capacidade.","D":"Savings Plans nunca reservam capacidade — são puramente desconto."},"keyConcept":"Reserva de capacidade vs reserva de desconto: zonal RI faz os dois; regional RI e SP fazem só desconto. Para capacidade pura, existe também On-Demand Capacity Reservation (sem desconto).","compareWith":["On-Demand Capacity Reservation (ODCR)","Capacity Blocks for ML"],"realWorldContext":"Empresas em mercados regulados (finance, healthcare) com DR multi-AZ usam zonal RI para garantir failover. Hoje a alternativa moderna é Compute SP + ODCR para separar desconto de capacidade.","commonMistakes":"Comprar Regional RI achando que reserva capacidade — em evento de capacidade insuficiente da AZ, lança ICE.","tutorSeeds":["O que é On-Demand Capacity Reservation?","Capacity Blocks for ML — quando usar?"]}'::jsonb, 'Billing, Pricing & Support', 'Billing, Pricing & Support', 'hard', 'best-practice', '["ri","zonal","capacity-reservation"]'::jsonb, 'ai-draft', 'active', now(), now()),
    ('clf-c02-bill-v2-011', 'aws-clf', 'Um RI Standard de 3 anos foi comprado há 18 meses, mas o workload foi descontinuado. A empresa quer recuperar parte do valor. Qual opção existe?', '[{"id":"A","text":"Cancelar diretamente no console com reembolso proporcional"},{"id":"B","text":"Vender no AWS Reserved Instance Marketplace"},{"id":"C","text":"Trocar por On-Demand credits via Support"},{"id":"D","text":"Converter em Savings Plan equivalente"}]'::jsonb, 'B', '{"summary":"RI Standard pode ser listado e vendido no Reserved Instance Marketplace para outros clientes AWS — recupera parte do valor não consumido.","whyCorrect":"RI Marketplace é o canal oficial. Vendedor define preço, AWS cobra taxa de 12% sobre o valor recebido. Comprador adquire RI com termo restante. Standard regional e zonal são vendíveis.","whyWrong":{"A":"Não há cancelamento direto com reembolso para RI.","C":"Support não converte RI em créditos genéricos.","D":"Não há conversão automática RI→SP. SP precisa ser comprado separadamente."},"keyConcept":"RI Marketplace é o único mecanismo de ''saída'' antes do fim do termo para RI Standard. Convertible NÃO pode ser vendido no Marketplace (exchange é a saída deles).","compareWith":["RI Convertible exchange","Savings Plans (sem saída possível)"],"realWorldContext":"Conta vendedora precisa ter US Bank Account configurada. Compradores acham bons preços em RIs com 6–12 meses restantes — bom para projetos curtos.","commonMistakes":"Tentar vender RI Convertible no Marketplace — não é elegível. Apenas Standard.","tutorSeeds":["Como precificar um RI no Marketplace?","Por que Convertible não é vendável?"]}'::jsonb, 'Billing, Pricing & Support', 'Billing, Pricing & Support', 'medium', 'troubleshoot', '["ri","marketplace","resale"]'::jsonb, 'ai-draft', 'active', now(), now()),
    ('clf-c02-bill-v2-012', 'aws-clf', 'Diferença entre RI Standard ''regional'' e ''zonal'' (mesma família, mesmo prazo): qual afirmação é correta?', '[{"id":"A","text":"Zonal dá maior desconto e reserva capacidade na AZ; regional dá flexibilidade de AZ/size mas não reserva capacidade"},{"id":"B","text":"Regional dá maior desconto e reserva capacidade em qualquer AZ"},{"id":"C","text":"Zonal cobre múltiplas regiões; regional só uma"},{"id":"D","text":"Não há diferença prática"}]'::jsonb, 'A', '{"summary":"Zonal: maior desconto + capacity reservation, mas trava AZ. Regional: desconto menor, flexibilidade de AZ/size dentro da família, sem capacidade reservada.","whyCorrect":"Trade-off clássico: zonal entrega o máximo (desconto + capacidade) em troca de rigidez de AZ. Regional troca capacidade por flexibilidade — útil para workloads que escalam entre AZs.","whyWrong":{"B":"Inverso — regional dá desconto menor que zonal, e não reserva capacidade em nenhuma AZ.","C":"Nenhum dos dois cobre múltiplas regiões — RI é sempre por região. Para múltiplas regiões use Compute SP.","D":"Há diferença significativa em capacidade e flexibilidade."},"keyConcept":"Eixo de RI: especificidade (Zonal > Regional) determina desconto e capacidade. Quanto mais específico, mais desconto e mais garantia, menos flexibilidade.","compareWith":["RI Convertible","On-Demand Capacity Reservation"],"realWorldContext":"Workloads stateful (RDS, NoSQL self-managed) em AZ fixa: zonal RI. Workloads stateless atrás de ALB com Auto Scaling cross-AZ: regional RI.","commonMistakes":"Comprar regional achando que reserva capacidade — em events de capacity scarcity, lança ICE.","tutorSeeds":["Como migrar de zonal RI para regional RI?","Quando vale a pena a flexibilidade de regional vs o desconto extra de zonal?"]}'::jsonb, 'Billing, Pricing & Support', 'Billing, Pricing & Support', 'medium', 'recall', '["ri","zonal","regional"]'::jsonb, 'ai-draft', 'active', now(), now()),
    ('clf-c02-bill-v2-013', 'aws-clf', 'Equipe quer rodar workload Spot com diversificação máxima entre famílias e AZs para minimizar interrupções. Qual abordagem é a recomendada pela AWS?', '[{"id":"A","text":"EC2 Spot Fleet ou EC2 Auto Scaling Group com allocation strategy ''price-capacity-optimized''"},{"id":"B","text":"On-Demand Capacity Reservation com Spot fallback"},{"id":"C","text":"Spot Block de 6 horas (sem interrupção garantida)"},{"id":"D","text":"Single instance Spot na maior família disponível"}]'::jsonb, 'A', '{"summary":"Spot Fleet/ASG com ''price-capacity-optimized'' diversifica entre famílias/AZs escolhendo pools com melhor combinação preço+capacidade — minimiza interrupção.","whyCorrect":"''price-capacity-optimized'' é a estratégia recomendada hoje pela AWS (substituiu ''capacity-optimized'' como padrão). Escolhe pools considerando ambos: preço atual e disponibilidade de capacidade. Resultado: ~60% menos interrupção que estratégias antigas.","whyWrong":{"B":"ODCR é On-Demand, não tem ''Spot fallback'' nativo. Misturar é via Mixed Instance Policy no ASG, não em ODCR.","C":"Spot Blocks foram DESCONTINUADOS para novas instâncias (deprecated). Não estão mais disponíveis.","D":"Single instance é exatamente o anti-padrão — sem diversificação, qualquer reclaim daquele pool derruba tudo."},"keyConcept":"Spot interruption se minimiza por diversificação (mais pools = menos correlação de reclaim). Estratégia atual: price-capacity-optimized.","compareWith":["lowest-price (mais barato mas mais interrupção)","capacity-optimized (foco em capacidade, ignora preço)"],"realWorldContext":"EMR, Karpenter no EKS, ECS Capacity Providers usam Spot Fleet com price-capacity-optimized + 10+ instance types diversificados. Interrupção rate cai para <5%.","commonMistakes":"Usar ''lowest-price'' como estratégia — economiza centavos mas eleva taxa de interrupção significativamente.","tutorSeeds":["Por que Spot Block foi descontinuado?","Como o 2-minute warning de Spot interruption funciona?"]}'::jsonb, 'Billing, Pricing & Support', 'Billing, Pricing & Support', 'hard', 'best-practice', '["spot","spot-fleet","allocation-strategy"]'::jsonb, 'ai-draft', 'active', now(), now()),
    ('clf-c02-bill-v2-014', 'aws-clf', 'Workload Spot precisa drainar conexões e salvar checkpoint antes de ser interrompido. Qual mecanismo AWS notifica a instância?', '[{"id":"A","text":"Spot Interruption Notice — disponível em IMDS e EventBridge, com 2 minutos de antecedência"},{"id":"B","text":"SNS topic gerenciado pela AWS automaticamente assinado"},{"id":"C","text":"CloudWatch alarm acionado por métrica ''SpotInterruptPending''"},{"id":"D","text":"Não há notificação — a instância é encerrada sem aviso"}]'::jsonb, 'A', '{"summary":"Spot Interruption Notice é entregue via IMDS (Instance Metadata Service em /latest/meta-data/spot/instance-action) e como evento EventBridge, com 2 minutos de antecedência.","whyCorrect":"Dois canais: (1) IMDS poll: app dentro da instância consulta endpoint; (2) EventBridge: rule reage ao evento ''EC2 Spot Instance Interruption Warning'' e dispara Lambda/SQS para orquestrar drain. 2 minutos é suficiente para checkpoint leve.","whyWrong":{"B":"Não há SNS topic gerenciado automaticamente. Pode-se configurar via EventBridge → SNS, mas não vem pronto.","C":"Não existe métrica nativa ''SpotInterruptPending'' no CloudWatch — o canal é EventBridge.","D":"Há sim 2 minutos de notice. Antes disso, a instância também pode receber ''rebalance recommendation'' (signal preventivo)."},"keyConcept":"Spot Interruption Notice = 2 min de aviso; Rebalance Recommendation = signal preventivo, sem deadline fixo, indicando elevado risco de reclaim em breve.","compareWith":["EC2 Rebalance Recommendation","ASG Lifecycle Hooks"],"realWorldContext":"Karpenter + Spot usa rebalance recommendation para começar a substituir nodes ANTES dos 2 min do interrupt notice — drain limpo sem perda de pods.","commonMistakes":"Esperar SNS sem configurar a EventBridge rule. Outro: ignorar rebalance recommendation achando que basta o 2-min notice.","tutorSeeds":["Diferença entre rebalance recommendation e interruption notice?","Como testar o handler de interrupção em desenvolvimento?"]}'::jsonb, 'Billing, Pricing & Support', 'Billing, Pricing & Support', 'medium', 'scenario', '["spot","interruption","eventbridge","imds"]'::jsonb, 'ai-draft', 'active', now(), now()),
    ('clf-c02-bill-v2-015', 'aws-clf', 'Time discute Spot Blocks (defined duration Spot) para job batch de 4 horas. Qual é a situação atual desse modelo?', '[{"id":"A","text":"Funciona normalmente em todas as regiões"},{"id":"B","text":"Foi descontinuado para novos workloads — não disponível para novas contas/instâncias"},{"id":"C","text":"Só disponível em regiões US"},{"id":"D","text":"Renomeado para Spot Reservation"}]'::jsonb, 'B', '{"summary":"Spot Blocks (defined duration) foram descontinuados pela AWS para novos workloads — a recomendação é usar Spot regular com handling adequado ou EC2 On-Demand para jobs curtos críticos.","whyCorrect":"AWS oficialmente descontinuou Spot Blocks (''defined duration Spot'') por baixo uso e overlap com Spot regular bem configurado. Não está disponível em novas implantações.","whyWrong":{"A":"Falso — está descontinuado globalmente para novos workloads.","C":"Não é uma restrição regional; é descontinuação global.","D":"Não foi renomeado — foi removido. Não existe ''Spot Reservation''."},"keyConcept":"Modelos legacy: AWS descontinua periodicamente features pouco usadas (Spot Blocks, EC2 Classic, T2 Unlimited override, etc.). Verificar status atual antes de planejar.","compareWith":["Spot regular com diversificação","Capacity Blocks for ML (novo, ainda existe)"],"realWorldContext":"Para jobs batch de duração definida (4h), best practice atual: Spot regular com checkpoint + retry, ou On-Demand se downtime impactar SLA.","commonMistakes":"Estudar material antigo de certificação que ainda menciona Spot Blocks como vivos.","tutorSeeds":["Quais outras features foram descontinuadas em EC2 recentemente?","Como o exame CLF-C02 cobre features descontinuadas?"]}'::jsonb, 'Billing, Pricing & Support', 'Billing, Pricing & Support', 'easy', 'recall', '["spot","spot-blocks","deprecated"]'::jsonb, 'ai-draft', 'active', now(), now()),
    ('clf-c02-bill-v2-016', 'aws-clf', 'Time FinOps quer fazer queries SQL ad-hoc sobre todos os custos detalhados da última 12 meses (linha por linha de uso). Qual combinação de ferramentas atende?', '[{"id":"A","text":"Cost Explorer com filtro avançado"},{"id":"B","text":"Cost and Usage Report (CUR) em S3 + Athena (ou Redshift/QuickSight)"},{"id":"C","text":"AWS Budgets com SQL builder"},{"id":"D","text":"AWS Pricing Calculator com export"}]'::jsonb, 'B', '{"summary":"CUR exporta o detalhamento de cobrança linha-a-linha para S3 (Parquet ou CSV); Athena consulta diretamente com SQL padrão.","whyCorrect":"Cost and Usage Report é o dataset mais granular da AWS (linha por linha de uso, com tags, RI/SP allocation, blended/unblended cost). Em Parquet particionado por mês, Athena consulta em segundos.","whyWrong":{"A":"Cost Explorer é poderoso mas com granularidade limitada e SEM SQL — UI filtros + API.","C":"Budgets não tem SQL builder; serve para definir limites com alertas.","D":"Pricing Calculator estima custo futuro, não relata uso passado."},"keyConcept":"Stack de FinOps avançado: CUR → S3 → Athena/Redshift → QuickSight/Tableau. Esse é o padrão para empresas que precisam de SQL flexível e dashboards customizados.","compareWith":["Cost Explorer (UI/API, sem SQL)","AWS Cost Anomaly Detection (detecção, não query)"],"realWorldContext":"Empresas grandes mantêm CUR em Parquet em S3 + Glue Crawler + Athena workgroup dedicado para FinOps. QuickSight conecta para dashboards. Custo do storage CUR é desprezível.","commonMistakes":"Tentar fazer análise complexa só com Cost Explorer e bater no limite de granularidade. Outro: não habilitar CUR no início e depois precisar de retroativo (CUR só gera a partir da ativação).","tutorSeeds":["Qual a diferença entre blended e unblended cost no CUR?","Como queriar CUR no Athena com particionamento eficiente?"]}'::jsonb, 'Billing, Pricing & Support', 'Billing, Pricing & Support', 'medium', 'best-practice', '["cur","athena","finops"]'::jsonb, 'ai-draft', 'active', now(), now()),
    ('clf-c02-bill-v2-017', 'aws-clf', 'Empresa tem 80 contas em uma Organization. Quer agrupar custo por ''projeto'', ''time'' e ''ambiente'' independentemente de tags inconsistentes nas contas. Qual feature do AWS Billing entrega isso?', '[{"id":"A","text":"Cost Allocation Tags somente"},{"id":"B","text":"Cost Categories"},{"id":"C","text":"Resource Groups"},{"id":"D","text":"Tag Policies"}]'::jsonb, 'B', '{"summary":"Cost Categories agrupa custos via regras (account ID, service, tag, region, charge type, etc.) — independente de tagging consistente.","whyCorrect":"Cost Categories permite criar dimensões customizadas (ex: ''Projeto Alpha'' = contas 111, 222 + tag Project=alpha). Funciona em Cost Explorer, Budgets e CUR como dimensão pivotável.","whyWrong":{"A":"Cost Allocation Tags só funciona se as tags estão presentes e ativadas em billing. Não resolve tagging inconsistente.","C":"Resource Groups agrupa recursos para gerenciamento (não para billing). Não é dimensão de Cost Explorer.","D":"Tag Policies validam/padronizam tags (governança), mas não criam dimensões de billing."},"keyConcept":"Cost Categories = camada de regras lógicas sobre o dado de custo. Resolve fragmentação de tagging sem precisar refazer tags em todos os recursos.","compareWith":["Cost Allocation Tags (tag-based)","Resource Groups (management)","Tag Policies (governance)"],"realWorldContext":"Empresas que herdaram tagging caótico (M&A, equipes diferentes) usam Cost Categories como ''camada de tradução'' até estabilizar tag policy. Suporta inheritance entre categorias.","commonMistakes":"Tentar resolver com Cost Allocation Tags em ambiente sem disciplina de tagging — leva meses.","tutorSeeds":["Cost Categories vs Cost Allocation Tags — quando usar cada?","Como aplicar Cost Categories retroativamente?"]}'::jsonb, 'Billing, Pricing & Support', 'Billing, Pricing & Support', 'medium', 'scenario', '["cost-categories","finops"]'::jsonb, 'ai-draft', 'active', now(), now()),
    ('clf-c02-bill-v2-018', 'aws-clf', 'Empresa quer detecção automática de gastos anômalos (picos repentinos) por serviço, conta ou Cost Category, com alerta por email/SNS. Qual ferramenta entrega isso nativamente?', '[{"id":"A","text":"AWS Budgets com threshold dinâmico"},{"id":"B","text":"AWS Cost Anomaly Detection"},{"id":"C","text":"CloudWatch Anomaly Detection"},{"id":"D","text":"Trusted Advisor"}]'::jsonb, 'B', '{"summary":"AWS Cost Anomaly Detection usa ML para detectar gastos fora do padrão histórico e alertar via SNS/email, organizado por monitor (service/account/Cost Category/tag).","whyCorrect":"É um serviço dedicado de FinOps: ML treinado em histórico, detecção contínua, suporta múltiplos ''monitors'' segmentados, integrado a SNS/email. Não exige threshold manual.","whyWrong":{"A":"Budgets exige threshold explícito (fixo ou % do baseline). Não usa ML para detecção de anomalia.","C":"CloudWatch Anomaly Detection é para métricas técnicas (CPU, latência, etc.), não para custo.","D":"Trusted Advisor traz recomendações estáticas de economia, não detecção de anomalia em tempo real."},"keyConcept":"Cost Anomaly Detection = detecção; Budgets = limites; Cost Explorer = análise; CUR = dado bruto. Cada um tem papel distinto na pilha FinOps.","compareWith":["AWS Budgets","CloudWatch alarms","AWS Trusted Advisor"],"realWorldContext":"Padrão de configuração: 1 monitor por linha de negócio + 1 monitor ''service-level'' geral. Threshold de alerta tipicamente $100 ou 10% — abaixo disso, vira ruído.","commonMistakes":"Achar que Budgets faz detecção de anomalia — Budgets só dispara em threshold fixo definido por você.","tutorSeeds":["Como Cost Anomaly Detection escolhe o baseline?","Pode-se suprimir false positives recorrentes?"]}'::jsonb, 'Billing, Pricing & Support', 'Billing, Pricing & Support', 'easy', 'scenario', '["cost-anomaly-detection","finops","alerting"]'::jsonb, 'ai-draft', 'active', now(), now()),
    ('clf-c02-bill-v2-019', 'aws-clf', 'Cost Explorer mostra que 35% do gasto de EC2 está ''Unblended'' diferente de ''Amortized''. Qual a diferença conceitual entre essas duas visões?', '[{"id":"A","text":"Unblended é cobrança real do mês; Amortized distribui custos upfront de RI/SP ao longo do termo"},{"id":"B","text":"Unblended inclui taxas; Amortized exclui"},{"id":"C","text":"São sinônimos"},{"id":"D","text":"Amortized é o preço bruto; Unblended é com desconto aplicado"}]'::jsonb, 'A', '{"summary":"Unblended = visão de cash (o que foi cobrado naquele mês). Amortized = distribuição contábil de pagamentos upfront ao longo do prazo do RI/SP.","whyCorrect":"Se você compra RI All Upfront de $36.000 por 3 anos, Unblended mostra $36k no mês 1 e $0 nos seguintes; Amortized mostra $1.000/mês durante 36 meses. Para análise de unit economics, use Amortized.","whyWrong":{"B":"Diferença não é sobre taxas; é sobre tratamento de upfront.","C":"Não são sinônimos — visões diferentes do mesmo dado.","D":"Inverso na ideia — mas ambos consideram desconto."},"keyConcept":"Blended cost = média entre contas da Org (legado). Unblended = cobrança real por conta. Amortized = distribuição de pagamentos upfront. Net Amortized = amortized líquido de RI/SP refunds.","compareWith":["Blended cost (legacy)","Net unblended","Net amortized"],"realWorldContext":"Times de FinOps reportam unit economics ($ por usuário, por API call) usando Amortized para não distorcer o mês de compra de RI/SP. Time financeiro vê Unblended para gestão de caixa.","commonMistakes":"Apresentar custo por feature usando Unblended e ver ''queda artificial'' depois do mês 1 de RI upfront — métrica enviesada.","tutorSeeds":["Como CUR expõe blended/unblended/amortized?","Quando usar Blended cost ainda hoje?"]}'::jsonb, 'Billing, Pricing & Support', 'Billing, Pricing & Support', 'hard', 'recall', '["cost-explorer","amortized","unblended"]'::jsonb, 'ai-draft', 'active', now(), now()),
    ('clf-c02-bill-v2-020', 'aws-clf', 'Equipe SRE quer disparar ação automática quando um Budget atinge 90% — por exemplo, anexar SCP de Deny para impedir lançamento de novas instâncias. Qual feature da AWS entrega isso?', '[{"id":"A","text":"AWS Budgets Actions"},{"id":"B","text":"Cost Anomaly Detection Hooks"},{"id":"C","text":"CloudWatch Alarm com SNS"},{"id":"D","text":"Trusted Advisor Auto-Remediation"}]'::jsonb, 'A', '{"summary":"AWS Budgets Actions automatiza respostas quando um Budget é violado — aplicar SCP, IAM policy, parar EC2/RDS, etc.","whyCorrect":"Budgets Actions permite vincular ações concretas ao threshold: anexar SCP de Deny, aplicar IAM policy custom, executar SSM Automation, parar EC2/RDS. Aprovação manual ou automática.","whyWrong":{"B":"Cost Anomaly Detection alerta via SNS, mas não tem ''hooks'' que apliquem SCPs. Você precisa orquestrar via Lambda.","C":"CloudWatch + SNS notifica humano; não anexa SCP nativamente.","D":"Trusted Advisor não tem auto-remediation nativa (recomenda, não age)."},"keyConcept":"Budgets evoluiu de ''apenas alerta'' para ''enforcement'': Actions fecham o loop entre detecção e mitigação.","compareWith":["EventBridge + Lambda (DIY equivalente)","Service Control Policies"],"realWorldContext":"Padrão em sandboxes: Budget de $500/mês com Action que anexa SCP de Deny para ec2:RunInstances ao atingir 100%. Evita ''PoC que vira produção sem aviso''.","commonMistakes":"Confiar só em alerta de Budget e ninguém olhar o email no fim de semana — gasto explode antes da resposta humana.","tutorSeeds":["Como reverter Budget Action depois?","Quais permissões a Budgets Actions role precisa?"]}'::jsonb, 'Billing, Pricing & Support', 'Billing, Pricing & Support', 'medium', 'best-practice', '["budgets","budget-actions","automation"]'::jsonb, 'ai-draft', 'active', now(), now()),
    ('clf-c02-bill-v2-021', 'aws-clf', 'Time precisa monitorar especificamente se a utilização dos seus Savings Plans está caindo abaixo de 95% (sinal de over-commitment). Qual tipo de Budget é apropriado?', '[{"id":"A","text":"Cost Budget com filtro de SP"},{"id":"B","text":"Savings Plans Utilization Budget"},{"id":"C","text":"Usage Budget em EC2-Hours"},{"id":"D","text":"Reservation Budget Convertible-only"}]'::jsonb, 'B', '{"summary":"Savings Plans Utilization Budget alerta quando a utilização do commitment cai abaixo de um % definido — diagnóstico direto de over-commitment.","whyCorrect":"Tipo nativo de Budget dedicado a SP utilization: você define o piso (ex: 95%) e recebe alerta se cair. Existe também Coverage Budget (% do uso elegível coberto por SP) e RI Utilization/Coverage equivalents.","whyWrong":{"A":"Cost Budget monitora gasto $, não utilização %.","C":"Usage Budget conta horas de uso, não cobre métrica de utilization de SP.","D":"Não existe ''Reservation Budget Convertible-only'' como tipo — RI tem Utilization e Coverage budgets, sem filtro Convertible-only nativo."},"keyConcept":"4 tipos de Budget: Cost, Usage, Reservation Utilization/Coverage, Savings Plans Utilization/Coverage. Cada um responde uma pergunta diferente.","compareWith":["RI Utilization Budget","SP Coverage Budget"],"realWorldContext":"FinOps maduro tem 2 budgets: SP Utilization > 95% (evitar desperdício) + SP Coverage > 70% do EC2 elegível (evitar gastar demais em On-Demand evitável).","commonMistakes":"Olhar só Cost Budget e não notar que SP está sub-utilizado mensalmente.","tutorSeeds":["Diferença entre SP Utilization Budget e Coverage Budget?","Como calcular o threshold ótimo de utilization?"]}'::jsonb, 'Billing, Pricing & Support', 'Billing, Pricing & Support', 'medium', 'best-practice', '["budgets","savings-plans","utilization"]'::jsonb, 'ai-draft', 'active', now(), now()),
    ('clf-c02-bill-v2-022', 'aws-clf', 'Time recebeu alerta de Budget às 23h e ninguém viu. Para reduzir dependência humana, qual padrão arquitetural integra Budget Actions a workflow de aprovação corporativo?', '[{"id":"A","text":"Budget Action com ''approval required'' apontando para SNS topic integrado ao Slack/PagerDuty via Lambda"},{"id":"B","text":"Budget Action ''auto-execute'' sem aprovação — sempre"},{"id":"C","text":"Cron Lambda que verifica Budget a cada minuto"},{"id":"D","text":"Email para todos os usuários da conta"}]'::jsonb, 'A', '{"summary":"Budget Action com modo ''approval required'' + SNS para Slack/PagerDuty permite aprovação humana on-call sem bloquear nem ignorar.","whyCorrect":"Modo ''approval required'' segura a ação até alguém aprovar via console ou API. Combinado com SNS → Lambda → Slack/PagerDuty, gera notificação acionável 24/7.","whyWrong":{"B":"Auto-execute sem aprovação é arriscado em produção — pode parar workload crítico em alerta de falso positivo.","C":"Cron a cada minuto reinventa a roda; Budget já tem trigger nativo.","D":"Email broadcast vira ruído ignorado."},"keyConcept":"Defesa em profundidade: detecção (Budget) + canal de alerta acionável (PagerDuty/Slack) + capacidade de aprovar/recusar com 1 clique.","compareWith":["Cost Anomaly Detection alerts","CloudWatch composite alarms"],"realWorldContext":"Empresas com on-call 24/7: PagerDuty service dedicado a ''AWS Cost Anomaly + Budget Critical'' com escalation policy. SLA de 15min para responder.","commonMistakes":"Apenas auto-execute em prod — pode causar outage por falso positivo de Budget.","tutorSeeds":["Como integrar Budget Actions com ServiceNow approval?","Como auditar quem aprovou cada Budget Action?"]}'::jsonb, 'Billing, Pricing & Support', 'Billing, Pricing & Support', 'hard', 'scenario', '["budgets","budget-actions","incident-response"]'::jsonb, 'ai-draft', 'active', now(), now()),
    ('clf-c02-bill-v2-023', 'aws-clf', 'Equipe quer monitorar especificamente quanto do uso EC2 elegível está coberto por RI/SP (objetivo: aumentar coverage). Qual budget atende?', '[{"id":"A","text":"RI Coverage Budget"},{"id":"B","text":"Cost Budget filtrado por RI"},{"id":"C","text":"Usage Budget em EC2-Hours"},{"id":"D","text":"Não existe budget nativo para coverage"}]'::jsonb, 'A', '{"summary":"RI Coverage Budget (e SP Coverage Budget equivalente) monitora % do uso elegível coberto por reservation — é a métrica certa para guiar compras adicionais.","whyCorrect":"AWS oferece tipos específicos: Coverage Budget (cobertura — quanto do uso está protegido por commitment) e Utilization Budget (utilização — quanto do commitment está em uso). Para guiar compra adicional, Coverage.","whyWrong":{"B":"Cost Budget mede $, não % de cobertura.","C":"Usage Budget mede consumo, não cobertura.","D":"Existe sim — Coverage Budget é nativo."},"keyConcept":"Coverage = quanto do uso está sob desconto. Utilization = quanto do desconto comprado está sendo usado. Ambos próximos de 100% = pricing eficiente.","compareWith":["SP Coverage Budget","RI Utilization Budget"],"realWorldContext":"Pipeline típico: Coverage < 70% sinal para comprar mais SP/RI; Utilization < 95% sinal para investigar over-commitment e ajustar futuras compras.","commonMistakes":"Confundir Coverage com Utilization — eles medem coisas opostas (cobertura do uso vs uso do commitment).","tutorSeeds":["Como decidir entre comprar mais RI vs mais SP via Coverage Budget?","Existe coverage budget para Lambda?"]}'::jsonb, 'Billing, Pricing & Support', 'Billing, Pricing & Support', 'medium', 'recall', '["budgets","ri","coverage"]'::jsonb, 'ai-draft', 'active', now(), now()),
    ('clf-c02-bill-v2-024', 'aws-clf', 'Em AWS Organizations com Consolidated Billing ativo, qual NÃO é um benefício direto?', '[{"id":"A","text":"Volume discount tiering agregado entre contas-membro"},{"id":"B","text":"Compartilhamento automático de descontos de RI/SP entre contas"},{"id":"C","text":"Fatura única para todas as contas-membro"},{"id":"D","text":"Aumento de quotas de serviço automaticamente em todas as contas"}]'::jsonb, 'D', '{"summary":"Quotas de serviço são por conta e região — Consolidated Billing não muda quotas. Os outros 3 itens SÃO benefícios reais.","whyCorrect":"Quotas (ex: número de VPCs, EIPs, EC2 vCPU) são definidos por conta+região e não compartilhados via Organizations. Aumento exige Service Quotas request per account ou IPM por nível de Support.","whyWrong":{"A":"É benefício real: volume tiering (ex: S3, data transfer) considera o consumo agregado da Org.","B":"É benefício real: RI Regional e Savings Plans compartilham desconto entre contas-membro por padrão (controlável via ''sharing settings'').","C":"É benefício real: payer account recebe a fatura unificada."},"keyConcept":"Consolidated Billing afeta dinheiro (descontos, volume tiers, fatura), não limites técnicos (quotas).","compareWith":["Service Quotas","RI/SP sharing settings"],"realWorldContext":"Erro comum em adoção de Organizations: assumir que ''agora todas as contas têm quota X'' — não. Cada conta precisa de quota request individual.","commonMistakes":"Achar que Org agrega quota de vCPU e descobrir limite ao escalar prod.","tutorSeeds":["Como desabilitar RI/SP sharing entre contas?","Volume discount tiering — quais serviços têm?"]}'::jsonb, 'Billing, Pricing & Support', 'Billing, Pricing & Support', 'medium', 'recall', '["organizations","consolidated-billing"]'::jsonb, 'ai-draft', 'active', now(), now()),
    ('clf-c02-bill-v2-025', 'aws-clf', 'Conta-membro A comprou RI Regional para m5.large em us-east-1. A conta B (mesma Org) também tem m5.large rodando. Por padrão, o RI da conta A pode dar desconto para a conta B?', '[{"id":"A","text":"Não — cada conta usa só seus próprios RIs"},{"id":"B","text":"Sim — RI sharing está ativo por padrão na Organization"},{"id":"C","text":"Apenas se A for o management account"},{"id":"D","text":"Só RI Zonal compartilha, Regional não"}]'::jsonb, 'B', '{"summary":"RI sharing está LIGADO por padrão na Organization. Discount excedente flui para outras contas-membro automaticamente, priorizando primeiro a conta que comprou.","whyCorrect":"Setting ''Reserved Instance discount sharing'' é true por default em Organizations. Mecânica: a conta dona usa primeiro; o que sobra vira pool para outras contas com uso elegível. Mesma lógica para SP sharing.","whyWrong":{"A":"Falso — sharing está on por default; precisaria explicitamente desligar (RI sharing = false).","C":"Não há restrição de quem é management — qualquer conta dona compartilha por default.","D":"Inverso — Regional RI tem flexibilidade e é compartilhável; Zonal também compartilha mas só com matching exato AZ."},"keyConcept":"Sharing default ON é decisão da AWS para maximizar uso de descontos. Desligar é caso de uso específico (ex: chargeback estrito).","compareWith":["Cost Allocation per account","SP Sharing settings"],"realWorldContext":"Empresas com chargeback rigoroso (cada BU paga seu) desativam sharing para que cada conta veja só descontos próprios. Caso contrário, A ''subsidia'' B sem clareza.","commonMistakes":"Achar que comprou RI mas não vê desconto na conta — descoberta: foi consumido por outra conta da Org primeiro.","tutorSeeds":["Como desligar RI sharing por conta?","Sharing afeta amortized cost por conta?"]}'::jsonb, 'Billing, Pricing & Support', 'Billing, Pricing & Support', 'medium', 'scenario', '["organizations","ri-sharing"]'::jsonb, 'ai-draft', 'active', now(), now()),
    ('clf-c02-bill-v2-026', 'aws-clf', 'Empresa quer que cada conta-membro pague exatamente o que consome SEM benefício de descontos cross-account. O que configurar?', '[{"id":"A","text":"Desabilitar RI/SP discount sharing nas configurações de billing da Organization"},{"id":"B","text":"Não há como — sharing é obrigatório"},{"id":"C","text":"Criar SCP de Deny billing:Share"},{"id":"D","text":"Comprar RI em cada conta separadamente apenas"}]'::jsonb, 'A', '{"summary":"No Billing console da management account, em ''Preferences'', pode-se desligar RI discount sharing e SP discount sharing por conta-membro.","whyCorrect":"Setting explícito em Billing Preferences. Pode aplicar globalmente ou por conta específica. Quando off, RI/SP só dá desconto à conta que comprou.","whyWrong":{"B":"Falso — é configurável, não obrigatório.","C":"Não existe action ''billing:Share'' como SCP-controlável; é setting de preference.","D":"Sub-ótimo — fragmenta commitments e perde eficiência. Setting de sharing é o caminho correto."},"keyConcept":"Trade-off: sharing ON maximiza uso de descontos (eficiência financeira global); sharing OFF dá visibilidade pura de chargeback (governança financeira).","compareWith":["Cost Categories para chargeback (alternativa que mantém sharing)","Cost Allocation Tags"],"realWorldContext":"Empresas com BUs com P&L separado e demanda de chargeback rigoroso fazem off. Empresas startup-like ou com cost center compartilhado deixam on.","commonMistakes":"Tentar resolver chargeback desligando sharing sem entender que perde eficiência de pooling.","tutorSeeds":["Cost Categories + sharing ON resolve chargeback sem perder eficiência?","Posso desligar sharing só para SP e manter para RI?"]}'::jsonb, 'Billing, Pricing & Support', 'Billing, Pricing & Support', 'medium', 'scenario', '["organizations","billing-preferences","chargeback"]'::jsonb, 'ai-draft', 'active', now(), now()),
    ('clf-c02-bill-v2-027', 'aws-clf', 'Conta-membro foi removida da Organization. O que acontece com os Savings Plans comprados por essa conta?', '[{"id":"A","text":"SP é transferido automaticamente para a payer account"},{"id":"B","text":"SP continua ativo na conta agora standalone, com mesmo termo e desconto"},{"id":"C","text":"SP é cancelado e reembolsado"},{"id":"D","text":"SP vira On-Demand imediatamente"}]'::jsonb, 'B', '{"summary":"SP fica vinculado à conta que comprou. Se essa conta sai da Org, o SP segue ativa na conta standalone com mesmo termo.","whyCorrect":"Ownership de SP/RI é por conta, não por Organization. Quando uma conta deixa a Org, leva consigo os commitments. Apenas o sharing entre contas se interrompe.","whyWrong":{"A":"Não há transferência automática para payer.","C":"SP não pode ser cancelado nem reembolsado — em remoção da Org também não.","D":"SP não vira On-Demand."},"keyConcept":"Commitments seguem a conta, não a Org. Movimentação de contas entre Orgs preserva RI/SP.","compareWith":["RI transfer (Convertible exchange dentro da mesma conta)","Account migration"],"realWorldContext":"Em M&A, divestiture, ou reorganização interna, planejar SP/RI ownership cuidadosamente — comprar na conta certa importa para futuras separações.","commonMistakes":"Comprar todo SP na management account ''para centralizar'' e descobrir que ao quebrar a Org, todo o commitment fica na ex-management.","tutorSeeds":["Como migrar SP entre contas?","Account migration entre Orgs — passos?"]}'::jsonb, 'Billing, Pricing & Support', 'Billing, Pricing & Support', 'hard', 'troubleshoot', '["organizations","savings-plans","account-migration"]'::jsonb, 'ai-draft', 'active', now(), now()),
    ('clf-c02-bill-v2-028', 'aws-clf', 'Empresa tem 50 contas e quer um único pagamento mensal com nota fiscal centralizada, mantendo isolamento de recursos. Qual estrutura é a correta?', '[{"id":"A","text":"AWS Organizations com Consolidated Billing — management account paga e recebe fatura única"},{"id":"B","text":"Cross-account IAM role ''BillingPayer'' em cada conta"},{"id":"C","text":"Migrar todas as contas para uma única conta com IAM Identity Center"},{"id":"D","text":"Contratar AWS Marketplace Reseller Program"}]'::jsonb, 'A', '{"summary":"AWS Organizations + Consolidated Billing é o mecanismo nativo: management account é o pagador; member accounts mantêm isolamento de recursos.","whyCorrect":"Consolidated Billing é a feature core da Org: uma fatura, ainda com detalhamento por conta no Cost Explorer e CUR. Cada conta-membro mantém seu próprio IAM, recursos, VPCs.","whyWrong":{"B":"IAM role não muda quem paga — billing payer é definido pela hierarquia de Organizations.","C":"Consolidar em uma única conta destrói isolamento (qualquer IAM error vaza recursos).","D":"Reseller Program é para parceiros revendendo AWS, não para gestão interna."},"keyConcept":"Multi-account é best-practice de isolamento (security boundary). Consolidated Billing resolve o trade-off da multiplicidade de faturas.","compareWith":["Single account com IAM (anti-padrão)","AWS Control Tower (Org + guardrails)"],"realWorldContext":"Padrão: Control Tower (sobre Organizations) cria landing zone com OUs estruturadas, log archive, audit, billing centralizado. Single sign-on via Identity Center.","commonMistakes":"Tentar resolver com IAM cross-account — não muda billing ownership.","tutorSeeds":["Diferença entre Consolidated Billing only vs full Organizations?","Como funcionou antes do AWS Organizations existir?"]}'::jsonb, 'Billing, Pricing & Support', 'Billing, Pricing & Support', 'easy', 'best-practice', '["organizations","consolidated-billing"]'::jsonb, 'ai-draft', 'active', now(), now()),
    ('clf-c02-bill-v2-029', 'aws-clf', 'Empresa tem incidente crítico em produção e precisa de chamada arquitetural com engenheiro AWS em até 1 hora, 24/7, com Slack channel dedicado. Qual nível de Support entrega isso?', '[{"id":"A","text":"Developer Support"},{"id":"B","text":"Business Support"},{"id":"C","text":"Enterprise On-Ramp Support"},{"id":"D","text":"Enterprise Support"}]'::jsonb, 'D', '{"summary":"Enterprise Support é o único com TAM (Technical Account Manager) dedicado, response em <15min para Business-Critical System Down, IEM e suporte arquitetural contínuo.","whyCorrect":"Enterprise: TAM dedicado, response <15min para Business-Critical System Down, Infrastructure Event Management (IEM), Concierge Billing, suporte 24/7 para todos os usuários da conta, acesso a workshops, Well-Architected reviews.","whyWrong":{"A":"Developer: response 12–24h business hours, sem TAM, sem chat 24/7. Inadequado para produção crítica.","B":"Business: response <1h para Production Down, 24/7, mas sem TAM dedicado nem IEM nem Concierge.","C":"Enterprise On-Ramp: TAM pool (não dedicado), response <30min para Business-Critical, sem IEM full. Intermediário entre Business e Enterprise."},"keyConcept":"Pirâmide de Support: Basic (free, doc only) → Developer (12–24h) → Business (<1h prod down) → Enterprise On-Ramp (<30min, TAM pool) → Enterprise (<15min, TAM dedicado, IEM).","compareWith":["Enterprise On-Ramp (mid-tier novo)","Business Support"],"realWorldContext":"Enterprise Support custa ~$15k/mês mínimo (10% do gasto da conta com floor). Faz sentido para empresas com >$150k/mês em AWS ou com workload regulado.","commonMistakes":"Tentar Business Support em workload com SLA 99.99% — sem TAM, sem IEM, atendimento por ticket via chat.","tutorSeeds":["O que é IEM (Infrastructure Event Management)?","Quando Enterprise On-Ramp é melhor que Business?"]}'::jsonb, 'Billing, Pricing & Support', 'Billing, Pricing & Support', 'medium', 'scenario', '["support","enterprise","tam"]'::jsonb, 'ai-draft', 'active', now(), now()),
    ('clf-c02-bill-v2-030', 'aws-clf', 'Diferença entre Trusted Advisor checks no nível Basic/Developer vs Business+/Enterprise: qual está correto?', '[{"id":"A","text":"Basic/Developer recebem apenas 7 checks core; Business+/Enterprise recebem todos os checks (~115+) em todas as 5 categorias"},{"id":"B","text":"Todos os tiers recebem todos os checks; só muda o canal de notificação"},{"id":"C","text":"Apenas Enterprise tem checks de Cost Optimization"},{"id":"D","text":"Trusted Advisor é pago à parte do Support"}]'::jsonb, 'A', '{"summary":"Basic/Developer recebem 7 checks core (foco em segurança e service limits); Business+/Enterprise desbloqueiam o catálogo completo nas 5 categorias.","whyCorrect":"Os 7 checks core do free tier focam em alto risco: IAM use, MFA root, security groups overly permissive, S3 bucket public, EBS public snapshots, RDS public snapshots, service limits. Business+ libera o catálogo full (~115+ checks).","whyWrong":{"B":"Falso — número de checks varia significativamente por tier.","C":"Cost Optimization checks existem em Business+ também, não só Enterprise.","D":"Trusted Advisor é incluído no Support — não cobra à parte."},"keyConcept":"Trusted Advisor 5 categorias: Cost Optimization, Performance, Security, Fault Tolerance, Service Limits. Free = subset de Security + Service Limits.","compareWith":["AWS Compute Optimizer (recommendations distintas)","AWS Cost Explorer (Rightsizing recommendations)"],"realWorldContext":"TA é primeira parada FinOps em empresas com Business Support — checks ''Underutilized EC2 Instances'' e ''Reserved Instance Optimization'' identificam economia rapidamente.","commonMistakes":"Ficar no Developer Support achando que tem TA full e perder visibilidade de Cost Optimization.","tutorSeeds":["TA vs Compute Optimizer — quando usar cada?","Como API de Trusted Advisor expõe os checks?"]}'::jsonb, 'Billing, Pricing & Support', 'Billing, Pricing & Support', 'easy', 'recall', '["support","trusted-advisor"]'::jsonb, 'ai-draft', 'active', now(), now()),
    ('clf-c02-bill-v2-031', 'aws-clf', 'Empresa vai fazer launch importante (Black Friday) e quer suporte AWS dedicado durante o evento, com revisão pré-evento de arquitetura, monitoramento em tempo real e equipe AWS standby. Qual feature do Enterprise Support entrega isso?', '[{"id":"A","text":"Infrastructure Event Management (IEM)"},{"id":"B","text":"Concierge Billing"},{"id":"C","text":"Well-Architected Review"},{"id":"D","text":"Trusted Advisor Operations Review"}]'::jsonb, 'A', '{"summary":"IEM é o serviço dedicado a eventos críticos: AWS engineers revisam arquitetura antes, monitoram durante e fazem hot-line standby.","whyCorrect":"Infrastructure Event Management: scope pré-evento (review arquitetural, load test analysis, scaling plan), durante (war room com AWS standby) e pós (postmortem). Incluído em Enterprise Support; em Enterprise On-Ramp é via ad-hoc charge.","whyWrong":{"B":"Concierge Billing é equipe especializada em billing/cost — não em eventos técnicos.","C":"Well-Architected Review é avaliação genérica de arquitetura, não event-specific standby.","D":"Não existe esse produto nomeado."},"keyConcept":"IEM = ''AWS engineers as event SREs'' — preparação, monitoring e response durante janela crítica.","compareWith":["Well-Architected Review","Countdown program (AWS Pro Services)"],"realWorldContext":"Black Friday e-commerce, lançamento de produto, IPO press release, migrações grandes — momentos típicos de IEM. Solicitar 4–6 semanas antes.","commonMistakes":"Achar que Business Support permite IEM — só Enterprise (e On-Ramp em modo limitado).","tutorSeeds":["Quantos IEMs vêm incluídos por ano no Enterprise?","Diferença IEM vs AWS Countdown Premium?"]}'::jsonb, 'Billing, Pricing & Support', 'Billing, Pricing & Support', 'medium', 'scenario', '["support","iem","enterprise"]'::jsonb, 'ai-draft', 'active', now(), now()),
    ('clf-c02-bill-v2-032', 'aws-clf', 'Empresa quer downgrade de Enterprise Support para Business Support para economizar. Qual consideração é crítica?', '[{"id":"A","text":"Perde TAM, IEM e response <15min — passa a <1h para Production Down sem TAM dedicado"},{"id":"B","text":"Trusted Advisor full ainda funciona mesmo em Business"},{"id":"C","text":"Concierge Billing continua disponível"},{"id":"D","text":"Letra A e B são corretas"}]'::jsonb, 'D', '{"summary":"Downgrade Enterprise→Business mantém Trusted Advisor full e response Production Down <1h, mas perde TAM, IEM, Concierge Billing e response Business-Critical <15min.","whyCorrect":"Tanto (A) quanto (B) são verdadeiros. A perda principal é o suporte dedicado (TAM) e eventos críticos. Mas Trusted Advisor full E Cost Optimization Hub continuam ativos em Business+.","whyWrong":{"A":"Verdadeiro mas incompleto — também é verdade que TA full segue.","B":"Verdadeiro mas incompleto.","C":"Concierge Billing é exclusivo do Enterprise — perde no downgrade."},"keyConcept":"Mapeamento de features por tier exige tabela mental: TAM, IEM, Concierge, response <15min são Enterprise-only.","compareWith":["Tabela completa de Support plans"],"realWorldContext":"Empresas em fase de cost-cutting fazem downgrade temporário. Risco: incidente crítico em janela vulnerável. Plan B: tickets continuam funcionando, mas sem TAM proativo.","commonMistakes":"Achar que perde tudo no downgrade — TA e support 24/7 chat continuam.","tutorSeeds":["Posso ter Enterprise Support em uma conta e Business em outra na mesma Org?","Como ressuscitar TAM relationship depois de upgrade?"]}'::jsonb, 'Billing, Pricing & Support', 'Billing, Pricing & Support', 'hard', 'troubleshoot', '["support","tier-comparison"]'::jsonb, 'ai-draft', 'active', now(), now()),
    ('clf-c02-bill-v2-033', 'aws-clf', 'Empresa quer comprar software de terceiro na AWS Marketplace com termo negociado, preço customizado e contrato direto com vendor. Qual modalidade atende?', '[{"id":"A","text":"Public offer padrão"},{"id":"B","text":"Private Offer (Marketplace Private Offer)"},{"id":"C","text":"SaaS pay-as-you-go"},{"id":"D","text":"Free Tier listing"}]'::jsonb, 'B', '{"summary":"Private Offers permitem ao vendor criar oferta customizada (preço, termo, EULA) visível apenas para a conta-alvo, cobrada via AWS bill.","whyCorrect":"Private Offer é o canal padrão de Marketplace para deals enterprise: vendor cria oferta com termos negociados, comprador aceita, cobrança aparece no AWS bill consolidado. Conta como spend AWS para EDP (Enterprise Discount Program) muitas vezes.","whyWrong":{"A":"Public offer = preço de catálogo fixo, sem negociação.","C":"SaaS pay-as-you-go é modelo de cobrança (uso medido), não modalidade de contratação. Pode existir em Private Offer também.","D":"Free Tier não envolve negociação."},"keyConcept":"Marketplace tem 3 modelos de pricing (SaaS subscription, SaaS contract, AMI hourly/annual) × 2 visibilidades (public/private offer). Private offer aplica sobre qualquer modelo.","compareWith":["BYOL (Bring Your Own License)","SaaS Subscription Marketplace"],"realWorldContext":"Datadog, Snowflake, Databricks comumente vendidos via Private Offer para enterprise — cliente consolida $ no AWS bill (compra de SP/RI fica mais escalável) e vendor recebe sem fricção de PO/invoice.","commonMistakes":"Comprar tudo em Public Offer e perder negociação possível via Private.","tutorSeeds":["Private Offer count para AWS EDP commit?","Como Channel Partner facilita Private Offer?"]}'::jsonb, 'Billing, Pricing & Support', 'Billing, Pricing & Support', 'medium', 'scenario', '["marketplace","private-offer"]'::jsonb, 'ai-draft', 'active', now(), now()),
    ('clf-c02-bill-v2-034', 'aws-clf', 'Empresa já tem licença on-prem do Oracle Database e quer trazer para EC2 sem comprar nova licença pelo Marketplace. Qual modelo de licenciamento aplica?', '[{"id":"A","text":"BYOL — Bring Your Own License"},{"id":"B","text":"License-Included (LI)"},{"id":"C","text":"SaaS Contract"},{"id":"D","text":"Free Tier"}]'::jsonb, 'A', '{"summary":"BYOL permite usar licença adquirida fora da AWS em recursos AWS, pagando apenas compute/storage. Para Oracle, exige Dedicated Hosts em muitos casos por requisitos de licenciamento.","whyCorrect":"BYOL é o modelo padrão para reutilizar licença on-prem. Para Oracle/SQL Server enterprise, costuma exigir Dedicated Host (visibilidade do hardware físico para licenciamento por socket/core).","whyWrong":{"B":"License-Included = AMI/SaaS já vem com licença embutida no preço (você paga por hora a AWS, que repassa ao vendor).","C":"SaaS Contract = compra de período prefixado de SaaS via Marketplace.","D":"Free Tier = pricing tier, não modelo de licença."},"keyConcept":"Modelos de licença: BYOL (sua), LI (AWS te vende junto), SaaS subscription. AWS License Manager governa o uso de BYOL para evitar non-compliance.","compareWith":["License-Included AMI (RHEL, SQL Server, Windows)","AWS License Manager"],"realWorldContext":"Empresas que migram Oracle/SQL Server enterprise para AWS usam BYOL + Dedicated Hosts + License Manager para garantir compliance e evitar audit risk.","commonMistakes":"Trazer Oracle via BYOL em instância EC2 normal (shared tenancy) — viola termos da maioria das licenças Oracle Enterprise.","tutorSeeds":["AWS License Manager — quais use cases?","Por que Oracle exige Dedicated Host?"]}'::jsonb, 'Billing, Pricing & Support', 'Billing, Pricing & Support', 'medium', 'scenario', '["marketplace","byol","license-manager"]'::jsonb, 'ai-draft', 'active', now(), now()),
    ('clf-c02-bill-v2-035', 'aws-clf', 'AWS Compute Optimizer recomenda ''downsizing'' de uma EC2 m5.4xlarge para m5.2xlarge com ''medium risk''. Qual ação é a correta antes de aplicar?', '[{"id":"A","text":"Aplicar imediatamente — Compute Optimizer só recomenda quando é seguro"},{"id":"B","text":"Verificar métricas no detalhe (CPU/memory/network percentile), considerar burst patterns e testar em staging"},{"id":"C","text":"Ignorar — Compute Optimizer só serve para Reserved Instances"},{"id":"D","text":"Trocar imediatamente por Graviton (m6g.2xlarge)"}]'::jsonb, 'B', '{"summary":"Compute Optimizer fornece recomendações baseadas em 14 dias de métricas. ''Medium risk'' indica algum picos não cobertos — validar antes de aplicar.","whyCorrect":"Compute Optimizer apresenta: current type, recommended type, estimated savings, risk level (low/medium/high), métricas observadas (p99 CPU, memory se CWAgent ativo). ''Medium'' = há sinais de pico que podem regredir performance.","whyWrong":{"A":"Recomendações são sugestões, não automações. Risk level indica confiança.","C":"Falso — Compute Optimizer analisa EC2, Auto Scaling, EBS, Lambda. Não é RI-specific.","D":"Migrar para Graviton exige rebuild da aplicação (ARM compatibility); não é decisão de ''aplicar imediatamente''."},"keyConcept":"Rightsizing requer dado (métricas), recomendação (Compute Optimizer) e validação (teste em staging). Pular qualquer etapa gera risco.","compareWith":["AWS Trusted Advisor (Underutilized EC2)","Cost Explorer Rightsizing Recommendations"],"realWorldContext":"Empresas maduras integram Compute Optimizer API em pipeline FinOps: recomendações com ''low risk'' + economia > $200/mês entram em ticket automático para revisão técnica.","commonMistakes":"Aplicar ''medium/high risk'' sem teste e gerar incidente de performance. Outro: ignorar baseline de memory (precisa CWAgent ou nightly snapshot).","tutorSeeds":["Como habilitar memory metrics no Compute Optimizer?","Compute Optimizer vs Cost Explorer Rightsizing — diferença?"]}'::jsonb, 'Billing, Pricing & Support', 'Billing, Pricing & Support', 'medium', 'best-practice', '["compute-optimizer","rightsizing"]'::jsonb, 'ai-draft', 'active', now(), now()),
    ('clf-c02-bill-v2-036', 'aws-clf', 'Diferença entre AWS Compute Optimizer e Trusted Advisor ''Low Utilization EC2 Instances''?', '[{"id":"A","text":"Mesma feature com nomes diferentes"},{"id":"B","text":"Trusted Advisor faz check binário (utilização baixa); Compute Optimizer faz recomendação granular de instance type com modelo ML"},{"id":"C","text":"Trusted Advisor é pago, Compute Optimizer é grátis"},{"id":"D","text":"Compute Optimizer só funciona em Spot"}]'::jsonb, 'B', '{"summary":"TA detecta instâncias subutilizadas (regra estática). Compute Optimizer recomenda instance type específico via ML treinado em 14 dias de métricas.","whyCorrect":"TA: regra simples (p.ex. CPU médio < 10% por 14 dias = subutilizada). Compute Optimizer: ML que avalia CPU, memory, network, I/O e sugere instance type específico com economia estimada e nível de risco.","whyWrong":{"A":"São features distintas com overlap parcial.","C":"Ambos têm tier free; TA full está em Business+, Compute Optimizer é free com opt-in.","D":"Compute Optimizer cobre EC2, ASG, EBS, Lambda — não é Spot-only."},"keyConcept":"Trusted Advisor = checks gerais binários. Compute Optimizer = recomendação ML granular. Cost Explorer Rightsizing = visão de custo+economia projetada.","compareWith":["TA Low Utilization check","Cost Explorer Rightsizing","AWS Optimizations Hub"],"realWorldContext":"Stack FinOps: TA para alertas básicos, Compute Optimizer para decisão de instance type, Cost Explorer para projeção financeira.","commonMistakes":"Usar só TA e perder oportunidades de migração entre famílias (que Compute Optimizer destaca).","tutorSeeds":["AWS Optimizations Hub agrega ambos?","Compute Optimizer cobra algo?"]}'::jsonb, 'Billing, Pricing & Support', 'Billing, Pricing & Support', 'easy', 'recall', '["compute-optimizer","trusted-advisor","comparison"]'::jsonb, 'ai-draft', 'active', now(), now()),
    ('clf-c02-bill-v2-037', 'aws-clf', 'Time quer comparar Spot regular com ''Spot best-fit allocation strategy''. Qual descrição corresponde a ''price-capacity-optimized''?', '[{"id":"A","text":"Escolhe sempre o pool de menor preço, ignorando capacidade"},{"id":"B","text":"Escolhe pools considerando combinação ótima de baixo preço E alta capacidade disponível, reduzindo interrupções"},{"id":"C","text":"Pré-aloca capacidade On-Demand e converte em Spot"},{"id":"D","text":"Apenas reserva capacidade na AZ, sem otimizar preço"}]'::jsonb, 'B', '{"summary":"''price-capacity-optimized'' é a estratégia padrão recomendada: combina sinal de preço E capacidade para minimizar interrupções mantendo preço atrativo.","whyCorrect":"AWS treinou modelo que combina ambos os sinais. Lança em pools com balanço ótimo — não é só o mais barato (volátil), não é só capacidade (caro). Substituiu ''capacity-optimized'' como recomendação padrão da AWS desde 2022.","whyWrong":{"A":"Essa descrição é da ''lowest-price'' (estratégia antiga e arriscada).","C":"Não existe esse mecanismo nomeado.","D":"Confunde com Zonal RI / ODCR — capacidade pura sem otimização de preço."},"keyConcept":"Spot strategies: lowest-price (legado, arriscado), capacity-optimized (foco em capacidade, ignora preço), price-capacity-optimized (padrão atual, balanceado), diversified (espalhar uniformemente).","compareWith":["lowest-price","capacity-optimized","diversified"],"realWorldContext":"Karpenter, EMR-on-EKS e ECS Capacity Providers usam price-capacity-optimized por padrão para alcançar <5% interruption rate em workloads ML/batch.","commonMistakes":"Continuar usando lowest-price por inércia de tutoriais antigos.","tutorSeeds":["Quando capacity-optimized ainda faz sentido?","Diversified strategy — quando aplicar?"]}'::jsonb, 'Billing, Pricing & Support', 'Billing, Pricing & Support', 'hard', 'best-practice', '["spot","allocation-strategy","price-capacity-optimized"]'::jsonb, 'ai-draft', 'active', now(), now()),
    ('clf-c02-bill-v2-038', 'aws-clf', 'Empresa precisa de relatório customizado: gasto S3 por bucket, por mês, com cost allocation tag ''Team''. Cost Explorer mostra agregado da Org. Onde estão os dados granulares por bucket?', '[{"id":"A","text":"Cost and Usage Report (CUR) com nível de granularidade ''resource-level'' habilitado"},{"id":"B","text":"S3 access logs"},{"id":"C","text":"CloudTrail data events"},{"id":"D","text":"AWS Config"}]'::jsonb, 'A', '{"summary":"CUR com ''resource ID'' option ativa expõe cost por ARN de recurso — incluindo bucket S3, individual EC2 instance, etc.","whyCorrect":"CUR é o único dataset com granularidade de resource ID + tag por linha de uso. Cost Explorer não chega a bucket-level por padrão. CUR + Athena permite SUM por bucket, por tag, por mês.","whyWrong":{"B":"S3 access logs mostram requisições, não custo.","C":"CloudTrail data events trackeia chamadas API, não custo.","D":"AWS Config trackeia config/state, não custo."},"keyConcept":"Cost por recurso: CUR + resource ID + tags ativadas como cost allocation tags. Sem essas três peças, dado granular não existe.","compareWith":["S3 Storage Lens (storage metrics, não custo)","Cost Explorer (agregado)"],"realWorldContext":"FinOps maduro: CUR diário em S3 Parquet + Glue table + Athena workgroup. Dashboard QuickSight mostra ''custo S3 por bucket por team'' com refresh diário.","commonMistakes":"Tentar fazer no Cost Explorer e bater no limite de detalhamento por recurso.","tutorSeeds":["Custo do próprio CUR storage e queries Athena?","Como ativar cost allocation tags retroativamente?"]}'::jsonb, 'Billing, Pricing & Support', 'Billing, Pricing & Support', 'medium', 'troubleshoot', '["cur","athena","s3","resource-level"]'::jsonb, 'ai-draft', 'active', now(), now()),
    ('clf-c02-bill-v2-039', 'aws-clf', 'Time usa Cost Anomaly Detection com monitor ''AWS services'' e recebe muitos falsos positivos em fim de mês (consumo recorrente de billing closing). Qual ação reduz ruído sem desativar a detecção?', '[{"id":"A","text":"Aumentar threshold de alerta para $5.000"},{"id":"B","text":"Criar subscriptions específicas por dimensão (service/account/Cost Category) e ajustar thresholds por monitor"},{"id":"C","text":"Desligar Cost Anomaly Detection no fim do mês"},{"id":"D","text":"Mover para AWS Budgets em vez de CAD"}]'::jsonb, 'B', '{"summary":"Segmentar monitors por dimensão e ajustar thresholds individualmente reduz ruído sem perder sensibilidade. CAD aprende padrão por monitor.","whyCorrect":"CAD permite múltiplos monitors com escopos diferentes (todos os services, service específico, Cost Category, linked account, tag). ML treina por monitor, então um monitor ''EC2-only'' fica mais sensível a anomalias EC2 sem ruído de S3, etc. Subscription de alerta tem threshold próprio.","whyWrong":{"A":"Sobe threshold global e perde sensibilidade a anomalias menores em outros services.","C":"Desligar perde valor justamente quando mais precisa (mês cheio).","D":"Budgets não detecta anomalias por ML — só thresholds fixos."},"keyConcept":"CAD escala por segmentação: 1 monitor genérico + N monitors específicos = melhor sinal/ruído.","compareWith":["AWS Budgets (limites fixos)","Cost Explorer (análise manual)"],"realWorldContext":"Padrão maduro: monitor ''service-level'' geral + monitors ''critical-service'' (EC2, RDS, OpenSearch) com threshold mais sensível. Subscriptions diferentes para email vs PagerDuty.","commonMistakes":"Único monitor com threshold único — fica entre dois extremos ruins.","tutorSeeds":["Como suprimir anomalia recorrente?","CAD funciona por linked account em Org?"]}'::jsonb, 'Billing, Pricing & Support', 'Billing, Pricing & Support', 'hard', 'troubleshoot', '["cost-anomaly-detection","tuning"]'::jsonb, 'ai-draft', 'active', now(), now()),
    ('clf-c02-bill-v2-040', 'aws-clf', 'Empresa quer escolher rapidamente o nível de Support adequado. Workload: e-commerce em produção, ~$80k/mês gasto AWS, SLA 99.9% para usuários finais, sem TAM dedicado (mas quer response rápido). Qual tier escolher?', '[{"id":"A","text":"Developer Support"},{"id":"B","text":"Business Support"},{"id":"C","text":"Enterprise On-Ramp Support"},{"id":"D","text":"Enterprise Support"}]'::jsonb, 'B', '{"summary":"Business Support: response <1h para Production System Down, 24/7, Trusted Advisor full, sem TAM. Para $80k/mês sem necessidade de TAM, é o sweet spot.","whyCorrect":"Business cobre: 24/7 phone/chat/email, response <1h Production Down, <4h Production Impaired, Trusted Advisor completo, AWS Support API, Infra Event Management ad-hoc. Custo: 10% do gasto AWS com floor de $100/mês. Para $80k → ~$8k/mês.","whyWrong":{"A":"Developer: business-hours only, response 12–24h. Inadequado para 99.9% SLA.","C":"Enterprise On-Ramp: TAM pool (não dedicado), response <30min, mas custa ~$5.5k mínimo + benefício marginal para esse perfil (sem necessidade de TAM).","D":"Enterprise: ~$15k/mês mínimo + TAM dedicado. Overkill quando ''sem TAM dedicado'' é requisito explícito."},"keyConcept":"Escolha de Support: workload prod 24/7 SLA = Business no mínimo. TAM justifica On-Ramp/Enterprise quando há complexidade arquitetural contínua.","compareWith":["Tabela Support tiers","Enterprise Discount Program (EDP)"],"realWorldContext":"Padrão mid-market: Business Support entre $50k–$200k/mês gasto AWS. Acima disso, On-Ramp ou Enterprise compensa pelo TAM e IEM.","commonMistakes":"Ficar em Developer para economizar e perder SLA por response 24h em incidente.","tutorSeeds":["Como calcular ROI de upgrade de Support?","Posso ter Support diferentes em contas diferentes da mesma Org?"]}'::jsonb, 'Billing, Pricing & Support', 'Billing, Pricing & Support', 'medium', 'best-practice', '["support","business-tier","decision"]'::jsonb, 'ai-draft', 'active', now(), now()),
    ('clf-c02-cc-001', 'aws-clf', 'Uma startup pequena precisa lançar um MVP em 3 semanas, mas a aquisição de servidores físicos levaria 8 semanas de lead time. A equipe quer começar com 2 instâncias agora e escalar conforme tração. Qual benefício da nuvem AWS atende diretamente esse problema de prazo e provisionamento incremental?', '[{"id":"A","text":"Trade capital expense for variable expense"},{"id":"B","text":"Increase speed and agility"},{"id":"C","text":"Stop spending money running and maintaining data centers"},{"id":"D","text":"Go global in minutes"}]'::jsonb, 'B', '{"summary":"''Speed and agility'' é o benefício que captura a redução de lead time de semanas para minutos — provisionar EC2 em segundos resolve o gargalo de hardware.","whyCorrect":"''Speed and agility'' é o benefício que captura a redução de lead time de semanas para minutos — provisionar EC2 em segundos resolve o gargalo de hardware.","whyWrong":{"C":"CapEx→OpEx é financeiro, não fala de prazo. ''Stop maintaining DCs'' é foco operacional. ''Go global'' é geografia.","A":"CapEx→OpEx (trade capital expense for variable expense) é benefício financeiro real, mas não endereça diretamente o gargalo de TEMPO descrito no enunciado (3 semanas vs 8 semanas de lead time). É consequência secundária; o benefício primário aqui é velocidade de provisionamento.","D":"''Go global in minutes'' descreve replicar workload em múltiplas Regions globalmente — não é o problema da startup, que precisa lançar UM MVP localmente em 3 semanas. Seria a resposta se o requisito fosse ''expandir para Europa e Ásia rapidamente''."},"keyConcept":"Princípio Well-Architected: experimentação rápida sem comprometer hardware.","tutorSeeds":["Pode explicar com mais detalhe: Princípio Well-Architected: experimentação rápida sem comprometer hardware?","Quais cenários reais aplicam Princípio Well-Architected: experimentação rápida sem comprometer hardware?","Como EC2 se compara com alternativas?"]}'::jsonb, 'Cloud Concepts', 'Cloud Concepts', 'easy', 'scenario', '["benefits","agility","mvp"]'::jsonb, 'ai-draft', 'active', now(), now()),
    ('clf-c02-cc-002', 'aws-clf', 'Um CFO avalia migrar de um data center próprio (servidores comprados a cada 5 anos, energia, refrigeração, equipe de operação física) para AWS. Qual é o principal benefício financeiro desse movimento, segundo os 6 benefícios da nuvem?', '[{"id":"A","text":"Eliminar completamente todos os custos operacionais"},{"id":"B","text":"Trocar despesa de capital (CapEx) por despesa variável (OpEx) baseada no uso"},{"id":"C","text":"Garantir o mesmo custo unitário independente da escala"},{"id":"D","text":"Transferir a responsabilidade fiscal dos servidores para a AWS"}]'::jsonb, 'B', '{"summary":"Trade CapEx for variable expense: deixa de comprar hardware adiantado (CapEx amortizado) e paga pelo consumo (OpEx).","whyCorrect":"Trade CapEx for variable expense: deixa de comprar hardware adiantado (CapEx amortizado) e paga pelo consumo (OpEx).","whyWrong":{"C":"Custo operacional não desaparece Custo unitário diminui com escala (economies of scale, outro benefício).","D":"Responsabilidade fiscal é tema contábil/jurídico, não relacionado.","A":"AWS não elimina todos os custos operacionais — apenas converte CapEx em OpEx variável e elimina custos de DC físico (refrigeração, energia, hardware swap). Empresa ainda tem custos: pessoas, software, suporte AWS, transferência de dados, treinamento. ''Eliminar completamente'' é claim absoluto que não se sustenta."},"keyConcept":"Princípio 1 dos 6 benefícios.","tutorSeeds":["Pode explicar com mais detalhe: Princípio 1 dos 6 benefícios?","Quais cenários reais aplicam Princípio 1 dos 6 benefícios?"]}'::jsonb, 'Cloud Concepts', 'Cloud Concepts', 'easy', 'recall', '["benefits","capex-opex","finance"]'::jsonb, 'ai-draft', 'active', now(), now()),
    ('clf-c02-cc-003', 'aws-clf', 'Uma empresa de e-commerce serve apenas o Brasil, mas precisa expandir para Europa e Japão em 6 meses, com latência aceitável para usuários locais. A equipe quer evitar construir data centers no exterior. Qual benefício da nuvem AWS atende esse objetivo?', '[{"id":"A","text":"Benefit from massive economies of scale"},{"id":"B","text":"Stop guessing capacity"},{"id":"C","text":"Go global in minutes"},{"id":"D","text":"Increase speed and agility"}]'::jsonb, 'C', '{"summary":"''Go global in minutes'' descreve replicar workload em múltiplas regiões AWS sem CapEx adicional — sa-east-1, eu-west-1, ap-northeast-1 cobrem os 3 mercados.","whyCorrect":"''Go global in minutes'' descreve replicar workload em múltiplas regiões AWS sem CapEx adicional — sa-east-1, eu-west-1, ap-northeast-1 cobrem os 3 mercados.","whyWrong":{"B":"Economias de escala falam de custo por unidade. ''Stop guessing capacity'' é elasticidade.","D":"Agility é velocidade de iteração interna.","A":"Economies of scale (preço unitário menor por agregação de demanda) é benefício real da AWS, mas não endereça o requisito específico de EXPANSÃO GEOGRÁFICA com baixa latência. Pricing global da AWS pode ser melhor, mas o que viabiliza Europa+Japão em meses é a presença de Regions em cada geografia."},"keyConcept":"Princípio dos 6 benefícios da nuvem.","tutorSeeds":["Pode explicar com mais detalhe: Princípio dos 6 benefícios da nuvem?","Quais cenários reais aplicam Princípio dos 6 benefícios da nuvem?","Como AWS se compara com alternativas?"]}'::jsonb, 'Cloud Concepts', 'Cloud Concepts', 'easy', 'scenario', '["benefits","global","regions"]'::jsonb, 'ai-draft', 'active', now(), now()),
    ('clf-c02-cc-004', 'aws-clf', 'Uma equipe gasta 60% do tempo aplicando patches no SO de servidores físicos, trocando discos defeituosos e renovando hardware de 5 anos. O CTO quer redirecionar esse esforço para construir features de produto. Qual benefício da nuvem AWS descreve diretamente essa mudança?', '[{"id":"A","text":"Trade capital expense for variable expense"},{"id":"B","text":"Stop spending money running and maintaining data centers"},{"id":"C","text":"Massive economies of scale"},{"id":"D","text":"Stop guessing capacity"}]'::jsonb, 'B', '{"summary":"''Stop spending money running and maintaining DCs'' captura exatamente o undifferentiated heavy lifting — racks, energia, hardware swap são abstraídos pela AWS.","whyCorrect":"''Stop spending money running and maintaining DCs'' captura exatamente o undifferentiated heavy lifting — racks, energia, hardware swap são abstraídos pela AWS.","whyWrong":{"D":"Economies of scale é preço por uso. ''Stop guessing capacity'' é planejamento de capacidade.","A":"CapEx→OpEx é benefício financeiro (não comprar hardware adiantado) — mas o enunciado fala de TEMPO da equipe gasto em patching/troca de discos, não de orçamento. A redirecionamento de ESFORÇO é capturado por ''stop maintaining DCs''; redirecionamento de DINHEIRO é ''trade CapEx for OpEx''.","C":"Economies of scale (preço por agregação) reduz custo de cloud — não tem relação direta com tempo de equipe gasto operando hardware. Mesmo se a AWS fosse mais cara, o benefício de ''stop maintaining DCs'' (liberar equipe) ainda existiria."},"keyConcept":"Foco no diferencial do produto vs operação de infra.","tutorSeeds":["Pode explicar com mais detalhe: Foco no diferencial do produto vs operação de infra?","Quais cenários reais aplicam Foco no diferencial do produto vs operação de infra?","Como DCs se compara com alternativas?"]}'::jsonb, 'Cloud Concepts', 'Cloud Concepts', 'easy', 'scenario', '["benefits","undifferentiated-heavy-lifting"]'::jsonb, 'ai-draft', 'active', now(), now()),
    ('clf-c02-cc-005', 'aws-clf', 'Uma plataforma de streaming previa 10.000 usuários simultâneos mas comprou hardware para 50.000 ''por garantia''. 80% da capacidade fica ociosa fora de eventos. Qual benefício da nuvem AWS resolve esse antipadrão?', '[{"id":"A","text":"Massive economies of scale"},{"id":"B","text":"Stop guessing capacity"},{"id":"C","text":"Go global in minutes"},{"id":"D","text":"Trade capital expense for variable expense"}]'::jsonb, 'B', '{"summary":"''Stop guessing capacity'' descreve elasticidade: provisiona 10k normalmente, escala para 50k+ no evento e reduz após.","whyCorrect":"''Stop guessing capacity'' descreve elasticidade: provisiona 10k normalmente, escala para 50k+ no evento e reduz após. Pagar só pelo usado elimina overprovisioning.","whyWrong":{"A":"Economies of scale é preço unitário. ''Go global'' é geografia.","C":"Go global (Regions múltiplas) endereça expansão geográfica — não tem relação com overprovisioning de capacidade local. A startup tem 1 problema, capacity planning, não expansão internacional.","D":"CapEx→OpEx é benefício relacionado (pagar variável vs fixo), mas o ângulo específico do problema é ''previsão errada de capacidade'', que é resolvido por elasticidade automática (stop guessing), não por modelo financeiro per se. Em CapEx fixo de cloud também daria overprovisioning."},"keyConcept":"Princípio dos 6 benefícios.","tutorSeeds":["Pode explicar com mais detalhe: Princípio dos 6 benefícios?","Quais cenários reais aplicam Princípio dos 6 benefícios?"]}'::jsonb, 'Cloud Concepts', 'Cloud Concepts', 'easy', 'scenario', '["benefits","elasticity","capacity"]'::jsonb, 'ai-draft', 'active', now(), now()),
    ('clf-c02-cc-006', 'aws-clf', 'Um arquiteto explica para a diretoria por que rodar 1 milhão de instâncias EC2 no agregado da AWS resulta em preço/hora menor do que rodar 100 servidores no DC próprio. Qual benefício da nuvem AWS sustenta essa lógica?', '[{"id":"A","text":"Benefit from massive economies of scale"},{"id":"B","text":"Speed and agility"},{"id":"C","text":"Stop guessing capacity"},{"id":"D","text":"Go global in minutes"}]'::jsonb, 'A', '{"summary":"AWS agrega o consumo de milhões de clientes e negocia hardware/energia em volume — esse desconto se reflete no preço por instância.","whyCorrect":"AWS agrega o consumo de milhões de clientes e negocia hardware/energia em volume — esse desconto se reflete no preço por instância. É o benefício clássico de economies of scale.","whyWrong":{"B":"Agility é prazo, elasticidade é variação, ''go global'' é geografia.","C":"Stop guessing capacity refere-se a elasticidade individual do cliente (escalar conforme demanda) — não explica por que o preço unitário AWS é menor que DC próprio. São benefícios diferentes.","D":"Go global in minutes é sobre expansão geográfica — não justifica menor preço/hora vs DC próprio. Pricing menor vem de agregação massiva (economies of scale)."},"keyConcept":"Conceito: poder de compra agregado da AWS > cliente individual.","tutorSeeds":["Pode explicar com mais detalhe: Conceito: poder de compra agregado da AWS > cliente individual?","Quais cenários reais aplicam Conceito: poder de compra agregado da AWS > cliente individual?","Como AWS se compara com alternativas?"]}'::jsonb, 'Cloud Concepts', 'Cloud Concepts', 'easy', 'recall', '["benefits","economies-of-scale"]'::jsonb, 'ai-draft', 'active', now(), now()),
    ('clf-c02-cc-007', 'aws-clf', 'Uma equipe quer rodar 50 experimentos A/B simultâneos com diferentes configurações de ML, derrubando cada experimento após 2 horas. No DC físico isso seria proibitivo. Qual COMBINAÇÃO de benefícios da nuvem habilita esse padrão?', '[{"id":"A","text":"Economies of scale + global reach"},{"id":"B","text":"CapEx→OpEx + speed/agility + stop guessing capacity"},{"id":"C","text":"Stop maintaining DCs + economies of scale"},{"id":"D","text":"Go global + economies of scale"}]'::jsonb, 'B', '{"summary":"Pagar por hora (variable expense) + provisionar/destruir em segundos (agility) + escalar dinamicamente (stop guessing) habilitam experimentação massiva.","whyCorrect":"Pagar por hora (variable expense) + provisionar/destruir em segundos (agility) + escalar dinamicamente (stop guessing) habilitam experimentação massiva.","whyWrong":{"C":"Economies of scale dá desconto mas não habilita o padrão. ''Stop maintaining DCs'' é operacional, não experimental. ''Go global'' é irrelevante para A/B local.","A":"Economies of scale e global reach são benefícios reais mas não são o que VIABILIZA 50 experimentos curtos: o problema central é provisionar/destruir rápido + pagar só pelas horas usadas. Global reach seria relevante se experimentos precisassem rodar em múltiplas geografias.","D":"Go global + economies of scale tratam de geografia e pricing — não endereçam diretamente experimentação rápida e fail-cheap. A combinação correta foca em variable expense + agility + elasticity."},"keyConcept":"Padrão fail-fast/cheap experimentation.","tutorSeeds":["Pode explicar com mais detalhe: Padrão fail-fast/cheap experimentation?","Quais cenários reais aplicam Padrão fail-fast/cheap experimentation?"]}'::jsonb, 'Cloud Concepts', 'Cloud Concepts', 'medium', 'scenario', '["benefits","experimentation","agility"]'::jsonb, 'ai-draft', 'active', now(), now()),
    ('clf-c02-cc-008', 'aws-clf', 'Uma empresa migrou para AWS e a diretoria reclama que ''a conta da AWS é maior que o custo do DC antigo''. Investigando, descobre-se que rodam EC2 m5.4xlarge 24/7 em On-Demand mesmo para workloads de batch noturno. Qual benefício da nuvem NÃO está sendo aproveitado?', '[{"id":"A","text":"Economies of scale (a AWS é cara mesmo)"},{"id":"B","text":"Variable expense / pay-as-you-go (deveriam desligar/redimensionar conforme uso)"},{"id":"C","text":"Go global in minutes"},{"id":"D","text":"Stop spending on data centers"}]'::jsonb, 'B', '{"summary":"On-Demand 24/7 para batch noturno é o oposto de variable expense — paga por horas ociosas.","whyCorrect":"On-Demand 24/7 para batch noturno é o oposto de variable expense — paga por horas ociosas. Deveriam usar Spot, scheduling, ou desligar fora do horário.","whyWrong":{"A":"Economies of scale é benefício embutido no preço base. ''Go global'' não é aplicável.","C":"Go global é sobre presença geográfica — não tem relação com o antipadrão descrito (instâncias 24/7 para workload batch). A empresa não está deixando de aproveitar expansão geográfica; está deixando de aproveitar pay-as-you-go.","D":"Já houve benefício de stop spending on DCs (saíram do DC físico) — esse não é o que está sendo NEGLIGENCIADO. A reclamação é custo da AWS alto, e a causa é uso fixo 24/7 que ignora a natureza variável do pricing."},"keyConcept":"Antipattern: migrar lift-and-shift e manter padrão de uso fixo.","tutorSeeds":["Pode explicar com mais detalhe: Antipattern: migrar lift-and-shift e manter padrão de uso fixo?","Quais cenários reais aplicam Antipattern: migrar lift-and-shift e manter padrão de uso fixo?"]}'::jsonb, 'Cloud Concepts', 'Cloud Concepts', 'medium', 'troubleshoot', '["benefits","cost","variable-expense"]'::jsonb, 'ai-draft', 'active', now(), now()),
    ('clf-c02-cc-009', 'aws-clf', 'Uma fintech expandindo para 5 países precisa cumprir requisitos de soberania de dados locais (dados de cidadãos europeus em EU, brasileiros no BR, etc). Qual benefício da nuvem AWS habilita esse padrão sem CapEx em cada país?', '[{"id":"A","text":"Economies of scale"},{"id":"B","text":"Go global in minutes (deploy em Regions locais)"},{"id":"C","text":"Variable expense"},{"id":"D","text":"Speed and agility"}]'::jsonb, 'B', '{"summary":"AWS Regions em cada geografia (eu-central-1, sa-east-1, ap-southeast-1) permitem deploy local rapidamente — atende soberania sem construir DC físico.","whyCorrect":"AWS Regions em cada geografia (eu-central-1, sa-east-1, ap-southeast-1) permitem deploy local rapidamente — atende soberania sem construir DC físico.","whyWrong":{"A":"Economies of scale e variable expense são vantagens transversais mas não endereçam soberania.","D":"Agility é tempo de iteração.","C":"Variable expense (pay-as-you-go) é benefício de pricing — mas não endereça SOBERANIA DE DADOS, que é requisito regulatório de localização física. Mesmo com OpEx, dados precisam estar nos Regions corretos. Variable expense seria a resposta se o problema fosse custo variável."},"keyConcept":"Conceito: Regions são unidades geográficas independentes para compliance/soberania.","tutorSeeds":["Pode explicar com mais detalhe: Conceito: Regions são unidades geográficas independentes para compliance/soberania?","Quais cenários reais aplicam Conceito: Regions são unidades geográficas independentes para compliance/soberania?","Como AWS Regions se compara com alternativas?"]}'::jsonb, 'Cloud Concepts', 'Cloud Concepts', 'medium', 'best-practice', '["benefits","data-sovereignty","regions"]'::jsonb, 'ai-draft', 'active', now(), now()),
    ('clf-c02-cc-010', 'aws-clf', 'Um diretor financeiro pergunta por que ''pagar apenas pelo que usa'' é considerado vantajoso vs ter um servidor próprio fixo. Qual argumento NÃO é uma justificativa válida do modelo variable expense?', '[{"id":"A","text":"Elimina overprovisioning durante períodos de baixa demanda"},{"id":"B","text":"Reduz risco financeiro de capacity planning errado"},{"id":"C","text":"Garante que o custo total ao longo de 5 anos será sempre menor que servidor próprio"},{"id":"D","text":"Converte CapEx em OpEx, melhorando fluxo de caixa"}]'::jsonb, 'C', '{"summary":"Variable expense NÃO garante TCO menor sempre — workloads ultra-estáveis 24/7 com hardware totalmente amortizado podem ser mais baratos on-prem.","whyCorrect":"Variable expense NÃO garante TCO menor sempre — workloads ultra-estáveis 24/7 com hardware totalmente amortizado podem ser mais baratos on-prem. O ganho é flexibilidade + redução de risco + melhor cash flow.","whyWrong":{"D":"Eliminação de overprovisioning, redução de risco e CapEx→OpEx são argumentos legítimos.","A":"Eliminar overprovisioning é justificativa LEGÍTIMA do modelo variable expense — quando demanda cai, escala-se para baixo e paga menos. Esta opção descreve um benefício REAL, não algo que falha como justificativa. (Item correto: a opção que NÃO é justificativa válida é C — garantir TCO sempre menor).","B":"Reduzir risco de capacity planning errado É justificativa válida do variable expense — paga-se o que se usa, sem aposta em demanda futura. Esta opção descreve um benefício REAL, não algo que falha como justificativa. (Item correto: C — garantia universal de menor TCO)."},"keyConcept":"Conceito: ''pay-as-you-go'' é sobre alinhar custo à demanda, não garantia universal de menor TCO.","tutorSeeds":["Pode explicar com mais detalhe: Conceito: ''pay-as-you-go'' é sobre alinhar custo à demanda, não garantia universal de menor TCO?","Quais cenários reais aplicam Conceito: ''pay-as-you-go'' é sobre alinhar custo à demanda, não garantia universal de menor TCO?","Como TCO se compara com alternativas?"]}'::jsonb, 'Cloud Concepts', 'Cloud Concepts', 'hard', 'best-practice', '["benefits","tco","variable-expense"]'::jsonb, 'ai-draft', 'active', now(), now()),
    ('clf-c02-cc-011', 'aws-clf', 'Uma equipe lança um produto novo sem saber se vai atrair 100 ou 100.000 usuários. Querem evitar comprar capacidade para o pior cenário e também evitar quedas em sucesso viral. Qual combinação de benefícios da nuvem AWS atende?', '[{"id":"A","text":"Stop guessing capacity + variable expense"},{"id":"B","text":"Economies of scale + go global"},{"id":"C","text":"Speed/agility + stop maintaining DCs"},{"id":"D","text":"Go global + economies of scale"}]'::jsonb, 'A', '{"summary":"Stop guessing = escalar para cima/baixo conforme demanda real.","whyCorrect":"Stop guessing = escalar para cima/baixo conforme demanda real. Variable expense = pagar pela escala efetivamente usada. Juntos eliminam o dilema ''subestimar = queda / superestimar = desperdício''.","whyWrong":{"B":"Economies of scale dá desconto, não elasticidade. ''Go global'' é geografia.","C":"Agility é tempo de iteração.","D":"Go global + economies of scale são benefícios reais, mas não endereçam o dilema CENTRAL descrito (capacity uncertainty entre 100 e 100.000 usuários). Go global cobre expansão geográfica; o problema aqui é elasticidade pura. A combinação certa é stop guessing + variable expense."},"keyConcept":"Padrão clássico de produto em early stage.","tutorSeeds":["Pode explicar com mais detalhe: Padrão clássico de produto em early stage?","Quais cenários reais aplicam Padrão clássico de produto em early stage?"]}'::jsonb, 'Cloud Concepts', 'Cloud Concepts', 'medium', 'scenario', '["benefits","elasticity","demand"]'::jsonb, 'ai-draft', 'active', now(), now()),
    ('clf-c02-cc-012', 'aws-clf', 'Qual afirmação descreve melhor a diferença entre ''elasticidade'' e ''escalabilidade'' no contexto dos benefícios da nuvem AWS?', '[{"id":"A","text":"São sinônimos no contexto AWS"},{"id":"B","text":"Escalabilidade é a capacidade de crescer; elasticidade é crescer E encolher automaticamente conforme demanda"},{"id":"C","text":"Elasticidade só se aplica a storage; escalabilidade só a compute"},{"id":"D","text":"Elasticidade exige Reserved Instances; escalabilidade exige On-Demand"}]'::jsonb, 'B', '{"summary":"Escalabilidade = sistema suporta carga maior (pode ser manual).","whyCorrect":"Escalabilidade = sistema suporta carga maior (pode ser manual). Elasticidade = ajuste automático bidirecional (cresce E encolhe) conforme demanda real — é estritamente um superset orientado a custo.","whyWrong":{"A":"Não são sinônimos.","C":"Elasticidade e escalabilidade aplicam-se a ambos compute E storage (e mais — network, database, etc.). Auto Scaling de EC2 é elasticidade de compute; S3 Intelligent-Tiering é elasticidade de storage class; RDS storage autoscaling existe. Não há separação por tipo de recurso.","D":"Elasticidade NÃO depende de Reserved Instances — RIs são compromisso de pricing, ortogonal a escalar. Auto Scaling Groups e elasticidade funcionam em On-Demand, Spot ou em capacidade coberta por SP/RI. Conceitos confundidos: pricing model vs scaling behavior."},"keyConcept":"Distinção importante em provas e em design de arquitetura.","tutorSeeds":["Pode explicar com mais detalhe: Distinção importante em provas e em design de arquitetura?","Quais cenários reais aplicam Distinção importante em provas e em design de arquitetura?"]}'::jsonb, 'Cloud Concepts', 'Cloud Concepts', 'hard', 'recall', '["benefits","elasticity","scalability"]'::jsonb, 'ai-draft', 'active', now(), now()),
    ('clf-c02-cc-013', 'aws-clf', 'Uma equipe projeta uma aplicação web e o arquiteto recomenda ''design for failure'' — assumir que qualquer componente pode falhar a qualquer momento. Qual prática AWS implementa esse princípio mais diretamente?', '[{"id":"A","text":"Usar apenas instâncias EC2 do mesmo tipo para uniformidade"},{"id":"B","text":"Distribuir instâncias em múltiplas Availability Zones com health checks e auto-recovery"},{"id":"C","text":"Aumentar o tamanho da instância (scale up) para evitar falhas"},{"id":"D","text":"Manter snapshots EBS semanais em uma única AZ"}]'::jsonb, 'B', '{"summary":"AZs são datacenters fisicamente isolados — distribuir Auto Scaling Group em ≥2 AZs sobrevive a falha de uma AZ inteira.","whyCorrect":"AZs são datacenters fisicamente isolados — distribuir Auto Scaling Group em ≥2 AZs sobrevive a falha de uma AZ inteira. Health checks substituem instâncias falhas automaticamente.","whyWrong":{"A":"Mesmo tipo de instância não previne falha.","C":"Scale up vertical aumenta blast radius.","D":"Snapshots em 1 AZ falham junto com a AZ."},"keyConcept":"Princípio: assumir falha → redundância em múltiplas AZs.","tutorSeeds":["Pode explicar com mais detalhe: Princípio: assumir falha → redundância em múltiplas AZs?","Quais cenários reais aplicam Princípio: assumir falha → redundância em múltiplas AZs?","Como AZs se compara com alternativas?"]}'::jsonb, 'Cloud Concepts', 'Cloud Concepts', 'easy', 'best-practice', '["design-principles","fail-fast","multi-az"]'::jsonb, 'ai-draft', 'active', now(), now()),
    ('clf-c02-cc-014', 'aws-clf', 'Um time mantém uma aplicação monolítica em que o módulo de pagamento e o módulo de notificação estão no mesmo processo. Quando o serviço de email cai, todo o checkout trava. Qual princípio de design AWS endereça esse problema?', '[{"id":"A","text":"Implement loose coupling (acoplamento fraco entre componentes)"},{"id":"B","text":"Scale up vertically"},{"id":"C","text":"Stop guessing capacity"},{"id":"D","text":"Buy Reserved Instances"}]'::jsonb, 'A', '{"summary":"Loose coupling via filas (SQS) ou pub/sub (SNS/EventBridge) desacopla checkout de notificação — se email falha, mensagens ficam na fila, checkout continua.","whyCorrect":"Loose coupling via filas (SQS) ou pub/sub (SNS/EventBridge) desacopla checkout de notificação — se email falha, mensagens ficam na fila, checkout continua.","whyWrong":{"B":"Scale up não resolve dependência síncrona.","C":"Capacity é ortogonal.","D":"Reserved Instances são compromisso de pricing (1-3 anos por desconto) — não tem relação com acoplamento entre módulos da aplicação. RIs reduzem custo de instâncias, mas o problema descrito (módulos no mesmo processo) é arquitetural, não financeiro. Resolveria se o problema fosse ''custo alto de EC2''."},"keyConcept":"Princípio: componentes acoplados via mensageria assíncrona sobrevivem a falhas isoladas.","tutorSeeds":["Pode explicar com mais detalhe: Princípio: componentes acoplados via mensageria assíncrona sobrevivem a falhas isoladas?","Quais cenários reais aplicam Princípio: componentes acoplados via mensageria assíncrona sobrevivem a falhas isoladas?","Como SQS se compara com alternativas?"]}'::jsonb, 'Cloud Concepts', 'Cloud Concepts', 'medium', 'scenario', '["design-principles","loose-coupling","sqs"]'::jsonb, 'ai-draft', 'active', now(), now()),
    ('clf-c02-cc-015', 'aws-clf', 'Uma equipe provisiona infraestrutura clicando manualmente no Console AWS. Sempre que um ambiente novo é criado, há divergências sutis vs produção. Qual princípio de design AWS resolve esse problema?', '[{"id":"A","text":"Comprar Reserved Instances para padronizar custos"},{"id":"B","text":"Automate everything — usar Infrastructure as Code (CloudFormation/CDK/Terraform)"},{"id":"C","text":"Aumentar o tamanho das instâncias para reduzir variabilidade"},{"id":"D","text":"Habilitar versionamento no S3"}]'::jsonb, 'B', '{"summary":"IaC declara infra em código versionado — ambientes recriáveis bit-by-bit, sem drift por cliques manuais.","whyCorrect":"IaC declara infra em código versionado — ambientes recriáveis bit-by-bit, sem drift por cliques manuais.","whyWrong":{"C":"Tamanho de instância não resolve drift.","D":"Versionamento S3 é para objetos, não infra.","A":"Reserved Instances afetam pricing de EC2 — não têm relação com drift de configuração entre ambientes. O problema descrito (divergências por cliques manuais) é arquitetural/operacional, resolvido por IaC. RIs seriam a resposta para ''custo alto de EC2 stable workload''."},"keyConcept":"Princípio: ''automate to make frequent, small, reversible changes'' do Well-Architected.","tutorSeeds":["Pode explicar com mais detalhe: Princípio: ''automate to make frequent, small, reversible changes'' do Well-Architected?","Quais cenários reais aplicam Princípio: ''automate to make frequent, small, reversible changes'' do Well-Architected?"]}'::jsonb, 'Cloud Concepts', 'Cloud Concepts', 'easy', 'best-practice', '["design-principles","automation","iac"]'::jsonb, 'ai-draft', 'active', now(), now()),
    ('clf-c02-cc-016', 'aws-clf', 'Uma aplicação processa pedidos chamando sincronamente 5 microsserviços em cadeia (A→B→C→D→E). Se um serviço fica lento, toda a chain trava. Qual abordagem AWS aplica o princípio ''design for failure'' e ''loose coupling''?', '[{"id":"A","text":"Substituir todas as chamadas síncronas por mensageria assíncrona via SQS/SNS quando possível"},{"id":"B","text":"Aumentar o timeout das chamadas síncronas para 60 segundos"},{"id":"C","text":"Consolidar todos os microsserviços em um monolito"},{"id":"D","text":"Migrar de EC2 para Lambda mantendo chamadas síncronas em cadeia"}]'::jsonb, 'A', '{"summary":"Filas/eventos quebram o acoplamento temporal — A escreve em fila e segue; B consome no seu ritmo.","whyCorrect":"Filas/eventos quebram o acoplamento temporal — A escreve em fila e segue; B consome no seu ritmo. Falhas/lentidão de B não bloqueiam A.","whyWrong":{"B":"Timeout maior amplifica o problema (mais conexões presas).","C":"Monolito tem outro tipo de acoplamento (deploy).","D":"Lambda em cadeia síncrona tem o mesmo problema com cold starts."},"keyConcept":"Princípio: desacoplar via mensagens.","tutorSeeds":["Pode explicar com mais detalhe: Princípio: desacoplar via mensagens?","Quais cenários reais aplicam Princípio: desacoplar via mensagens?"]}'::jsonb, 'Cloud Concepts', 'Cloud Concepts', 'medium', 'best-practice', '["design-principles","async","microservices"]'::jsonb, 'ai-draft', 'active', now(), now()),
    ('clf-c02-cc-017', 'aws-clf', 'Uma equipe quer aumentar capacidade de processamento. Tem duas opções: (1) trocar uma instância m5.large por m5.24xlarge (scale up vertical), ou (2) adicionar mais instâncias m5.large em um Auto Scaling Group (scale out horizontal). Qual princípio AWS recomenda preferir a segunda?', '[{"id":"A","text":"Scale horizontally to increase aggregate workload availability"},{"id":"B","text":"Use a single large instance to minimize networking"},{"id":"C","text":"Always use the largest available instance type"},{"id":"D","text":"Prefer monolithic architecture for cost optimization"}]'::jsonb, 'A', '{"summary":"Scale out (horizontal) distribui carga entre múltiplos nós menores: aumenta disponibilidade agregada, reduz blast radius de uma instância morta, e em geral é mais granular.","whyCorrect":"Scale out (horizontal) distribui carga entre múltiplos nós menores: aumenta disponibilidade agregada, reduz blast radius de uma instância morta, e em geral é mais granular. Scale up (vertical) tem ceiling físico e SPOF.","whyWrong":{"B":"Networking interno entre EC2 na mesma VPC tem latência baixa.","C":"Usar sempre o maior tipo de instância é o anti-padrão: viola scale horizontally (concentra carga em SPOF), tem ceiling físico (mesmo o maior tipo eventualmente esgota), e o blast radius de uma falha é máximo. AWS recomenda múltiplas instâncias menores.","D":"Arquitetura monolítica concentra todos os componentes em um processo/instância — oposto de loose coupling, oposto de scale out horizontal. Aumenta blast radius e dificulta escalar componentes individualmente. AWS Well-Architected recomenda decomposição em serviços fracamente acoplados."},"keyConcept":"Princípio Well-Architected.","tutorSeeds":["Pode explicar com mais detalhe: Princípio Well-Architected?","Quais cenários reais aplicam Princípio Well-Architected?","Como SPOF se compara com alternativas?"]}'::jsonb, 'Cloud Concepts', 'Cloud Concepts', 'medium', 'best-practice', '["design-principles","horizontal-scaling"]'::jsonb, 'ai-draft', 'active', now(), now()),
    ('clf-c02-cc-018', 'aws-clf', 'Uma equipe migra para AWS e mantém o padrão antigo: provisiona EC2 para o pico previsto de Black Friday durante o ano inteiro. Qual princípio AWS de design recomenda mudar essa prática?', '[{"id":"A","text":"Stop guessing your capacity needs — provision based on actual demand"},{"id":"B","text":"Always use the largest instance type for safety"},{"id":"C","text":"Buy 3-year Reserved Instances for the peak"},{"id":"D","text":"Disable Auto Scaling to keep performance predictable"}]'::jsonb, 'A', '{"summary":"''Stop guessing capacity'' = usar Auto Scaling baseado em métricas reais.","whyCorrect":"''Stop guessing capacity'' = usar Auto Scaling baseado em métricas reais. Nuvem permite ter capacidade de pico só durante o pico.","whyWrong":{"B":"Usar sempre o maior tipo de instância para ''segurança'' é overprovisioning crônico — paga-se pela capacidade de pico durante 100% do tempo. Viola variable expense e stop guessing. Pior em On-Demand. Seria razoável apenas se workload realmente fosse 24/7 saturado.","C":"Comprar 3-year RIs para o pico de Black Friday compromete capital por 3 anos para servir 1 semana de uso real — desperdício enorme. RIs são para BASELINE de uso constante, não para spikes. Para picos, usar Auto Scaling com On-Demand/Spot.","D":"Desativar Auto Scaling para ''performance previsível'' é o oposto do princípio: AS é exatamente o mecanismo que viabiliza não-provisionar para pico. Performance previsível vem de health checks, monitoring e tuning, não de capacidade fixa em pico."},"keyConcept":"Princípio dos 5 design principles.","tutorSeeds":["Pode explicar com mais detalhe: Princípio dos 5 design principles?","Quais cenários reais aplicam Princípio dos 5 design principles?"]}'::jsonb, 'Cloud Concepts', 'Cloud Concepts', 'easy', 'best-practice', '["design-principles","capacity"]'::jsonb, 'ai-draft', 'active', now(), now()),
    ('clf-c02-cc-019', 'aws-clf', 'Uma equipe de DevOps quer reduzir o tempo de feedback entre commit e detecção de problemas em produção. Qual princípio de design AWS recomenda?', '[{"id":"A","text":"Make frequent, small, reversible changes (deploys pequenos e frequentes com rollback fácil)"},{"id":"B","text":"Deploys mensais consolidados para reduzir risco"},{"id":"C","text":"Deploys apenas em horário comercial com aprovação manual"},{"id":"D","text":"Eliminar testes automatizados para acelerar deploy"}]'::jsonb, 'A', '{"summary":"Mudanças pequenas e frequentes (com canary/blue-green/CI-CD) reduzem blast radius e aceleram aprendizado.","whyCorrect":"Mudanças pequenas e frequentes (com canary/blue-green/CI-CD) reduzem blast radius e aceleram aprendizado. Reversibilidade fácil incentiva experimentação.","whyWrong":{"B":"Deploys mensais grandes têm maior blast radius e dificultam isolamento de bugs.","C":"Restrições de horário não escalam com produto global.","D":"Sem testes é antipattern."},"keyConcept":"Princípio Operational Excellence.","tutorSeeds":["Pode explicar com mais detalhe: Princípio Operational Excellence?","Quais cenários reais aplicam Princípio Operational Excellence?","Como CI-CD se compara com alternativas?"]}'::jsonb, 'Cloud Concepts', 'Cloud Concepts', 'medium', 'best-practice', '["design-principles","ci-cd"]'::jsonb, 'ai-draft', 'active', now(), now()),
    ('clf-c02-cc-020', 'aws-clf', 'Uma startup tem orçamento limitado e quer otimizar custos sem comprometer reliability. Qual abordagem alinha com o princípio AWS de ''evolve'' (evolução contínua)?', '[{"id":"A","text":"Configurar tudo no primeiro dia e nunca rever"},{"id":"B","text":"Anticipate failure — antecipar e testar modos de falha com Game Days"},{"id":"C","text":"Manter arquitetura legada por anos para evitar mudança"},{"id":"D","text":"Desativar logs em produção para reduzir custo"}]'::jsonb, 'B', '{"summary":"Anticipate failure: Game Days, chaos engineering, fault injection testam o sistema continuamente.","whyCorrect":"Anticipate failure: Game Days, chaos engineering, fault injection testam o sistema continuamente. ''Evolve'' é melhoria contínua baseada em aprendizado real.","whyWrong":{"D":"Sem logs em prod compromete observability.","A":"Configurar e nunca rever é o ANTI-padrão de ''evolve'' — assume que a primeira decisão sempre será a melhor para sempre. Tecnologias mudam, demanda muda, melhores práticas evoluem. ''Evolve'' exige revisão contínua via well-architected reviews e métricas.","C":"Manter legado por anos para evitar mudança é estagnação — oposto de ''evolve''. Tecnologia obsoleta acumula technical debt, custos crescentes de manutenção, e vulnerabilidades não-patchadas. Princípio AWS é mudança contínua e segura via automação."},"keyConcept":"Princípio Operational Excellence.","tutorSeeds":["Pode explicar com mais detalhe: Princípio Operational Excellence?","Quais cenários reais aplicam Princípio Operational Excellence?"]}'::jsonb, 'Cloud Concepts', 'Cloud Concepts', 'hard', 'best-practice', '["design-principles","chaos-engineering"]'::jsonb, 'ai-draft', 'active', now(), now()),
    ('clf-c02-cc-021', 'aws-clf', 'Um arquiteto deseja eliminar SPOFs (single points of failure) na camada web. A app está em uma única EC2 sem ALB, sem ASG, em uma única AZ. Quais mudanças aplicam o princípio ''design for failure''?', '[{"id":"A","text":"Aumentar o tamanho da instância de m5.large para m5.4xlarge"},{"id":"B","text":"Colocar instâncias em Auto Scaling Group atrás de um ALB, distribuídas em ≥2 AZs"},{"id":"C","text":"Habilitar Termination Protection na instância única"},{"id":"D","text":"Migrar para um Dedicated Host"}]'::jsonb, 'B', '{"summary":"ASG + ALB + multi-AZ é a receita padrão: ALB roteia para instâncias saudáveis, ASG substitui automaticamente as falhas, multi-AZ sobrevive a falha de DC.","whyCorrect":"ASG + ALB + multi-AZ é a receita padrão: ALB roteia para instâncias saudáveis, ASG substitui automaticamente as falhas, multi-AZ sobrevive a falha de DC.","whyWrong":{"A":"Maior instância continua SPOF.","C":"Termination Protection só protege contra delete acidental.","D":"Dedicated Host é tenancy, não HA."},"keyConcept":"Princípio: redundância > recursos maiores.","tutorSeeds":["Pode explicar com mais detalhe: Princípio: redundância > recursos maiores?","Quais cenários reais aplicam Princípio: redundância > recursos maiores?","Como ASG se compara com alternativas?"]}'::jsonb, 'Cloud Concepts', 'Cloud Concepts', 'medium', 'best-practice', '["design-principles","high-availability"]'::jsonb, 'ai-draft', 'active', now(), now()),
    ('clf-c02-cc-022', 'aws-clf', 'Qual dos seguintes é um dos 6 pilares do AWS Well-Architected Framework adicionado mais recentemente (2021)?', '[{"id":"A","text":"Operational Excellence"},{"id":"B","text":"Security"},{"id":"C","text":"Sustainability"},{"id":"D","text":"Reliability"}]'::jsonb, 'C', '{"summary":"Sustainability foi o 6º pilar adicionado em re:Invent 2021.","whyCorrect":"Sustainability foi o 6º pilar adicionado em re:Invent 2021. Os outros 5 (OE, Security, Reliability, Performance, Cost) já existiam.","whyWrong":{"B":"OE, Security, Reliability são pilares originais.","A":"Operational Excellence é um dos 5 pilares ORIGINAIS do Well-Architected Framework (lançado em 2015) — não é o adicionado mais recentemente. Foi um dos primeiros pilares formalizados.","D":"Reliability é um dos 5 pilares ORIGINAIS do Well-Architected (existe desde 2015). Não foi adicionado em 2021. O adicionado em re:Invent 2021 foi Sustainability, refletindo crescente preocupação com pegada de carbono."},"keyConcept":"Conceito: 6 pilares = OE + Security + Reliability + Performance Efficiency + Cost Optimization + Sustainability.","tutorSeeds":["Pode explicar com mais detalhe: Conceito: 6 pilares = OE + Security + Reliability + Performance Efficiency + Cost Optimization + Sustainability?","Quais cenários reais aplicam Conceito: 6 pilares = OE + Security + Reliability + Performance Efficiency + Cost Optimization + Sustainability?","Como OE se compara com alternativas?"]}'::jsonb, 'Cloud Concepts', 'Cloud Concepts', 'easy', 'recall', '["well-architected","sustainability"]'::jsonb, 'ai-draft', 'active', now(), now()),
    ('clf-c02-cc-023', 'aws-clf', 'Uma equipe quer estabelecer práticas para ''run and monitor systems to deliver business value, e continually improve supporting processes and procedures''. A qual pilar do Well-Architected isso corresponde?', '[{"id":"A","text":"Reliability"},{"id":"B","text":"Operational Excellence"},{"id":"C","text":"Performance Efficiency"},{"id":"D","text":"Cost Optimization"}]'::jsonb, 'B', '{"summary":"OE foca em rodar sistemas com valor de negócio + melhoria contínua de processos (runbooks, observability, post-mortems, automação).","whyCorrect":"OE foca em rodar sistemas com valor de negócio + melhoria contínua de processos (runbooks, observability, post-mortems, automação).","whyWrong":{"A":"Reliability é resiliência/recovery.","C":"Performance é uso eficiente de recursos para SLOs.","D":"Cost é otimização financeira."},"keyConcept":"Definição direta do pilar OE.","tutorSeeds":["Pode explicar com mais detalhe: Definição direta do pilar OE?","Quais cenários reais aplicam Definição direta do pilar OE?","Como OE se compara com alternativas?"]}'::jsonb, 'Cloud Concepts', 'Cloud Concepts', 'easy', 'recall', '["well-architected","operational-excellence"]'::jsonb, 'ai-draft', 'active', now(), now()),
    ('clf-c02-cc-024', 'aws-clf', 'Uma equipe implementa criptografia at-rest com KMS, criptografia in-transit com TLS, least-privilege IAM policies e CloudTrail em todas as contas. Qual pilar do Well-Architected é o foco dessas práticas?', '[{"id":"A","text":"Reliability"},{"id":"B","text":"Security"},{"id":"C","text":"Operational Excellence"},{"id":"D","text":"Cost Optimization"}]'::jsonb, 'B', '{"summary":"Security pillar cobre: identity & access management, detection, infrastructure protection, data protection (encryption), incident response.","whyCorrect":"Security pillar cobre: identity & access management, detection, infrastructure protection, data protection (encryption), incident response. Todas as práticas listadas são de Security.","whyWrong":{"A":"Reliability é resiliência.","D":"Cost é custo.","C":"Operational Excellence cobre runbooks, observability, post-mortems, automation, continuous improvement — não criptografia ou IAM. OE governa COMO operar; Security governa O QUE proteger. Práticas listadas (encryption, least-privilege, CloudTrail) são todas Security."},"keyConcept":"Definição direta do pilar Security.","tutorSeeds":["Pode explicar com mais detalhe: Definição direta do pilar Security?","Quais cenários reais aplicam Definição direta do pilar Security?"]}'::jsonb, 'Cloud Concepts', 'Cloud Concepts', 'easy', 'recall', '["well-architected","security"]'::jsonb, 'ai-draft', 'active', now(), now()),
    ('clf-c02-cc-025', 'aws-clf', 'Uma aplicação deve sobreviver a falha de uma Availability Zone inteira, ter backups testados e RTO/RPO definidos. Qual pilar do Well-Architected é o foco principal dessas práticas?', '[{"id":"A","text":"Performance Efficiency"},{"id":"B","text":"Reliability"},{"id":"C","text":"Security"},{"id":"D","text":"Sustainability"}]'::jsonb, 'B', '{"summary":"Reliability cobre: foundations (capacidade/limits), workload architecture, change management, failure management (backups, DR, RTO/RPO).","whyCorrect":"Reliability cobre: foundations (capacidade/limits), workload architecture, change management, failure management (backups, DR, RTO/RPO).","whyWrong":{"A":"Performance é uso eficiente.","C":"Security é confidencialidade/integridade.","D":"Sustainability é ambiental."},"keyConcept":"Definição direta do pilar Reliability.","tutorSeeds":["Pode explicar com mais detalhe: Definição direta do pilar Reliability?","Quais cenários reais aplicam Definição direta do pilar Reliability?","Como DR se compara com alternativas?"]}'::jsonb, 'Cloud Concepts', 'Cloud Concepts', 'easy', 'recall', '["well-architected","reliability","dr"]'::jsonb, 'ai-draft', 'active', now(), now()),
    ('clf-c02-cc-026', 'aws-clf', 'Uma equipe escolhe instâncias EC2 do tipo certo para o workload, usa caching com ElastiCache, faz benchmarks e monitora throughput. Qual pilar do Well-Architected guia essas decisões?', '[{"id":"A","text":"Performance Efficiency"},{"id":"B","text":"Operational Excellence"},{"id":"C","text":"Cost Optimization"},{"id":"D","text":"Reliability"}]'::jsonb, 'A', '{"summary":"Performance Efficiency: ''use computing resources efficiently to meet system requirements'' — seleção de recursos certos, monitoring de performance, trade-offs.","whyCorrect":"Performance Efficiency: ''use computing resources efficiently to meet system requirements'' — seleção de recursos certos, monitoring de performance, trade-offs.","whyWrong":{"C":"Cost é financeiro.","D":"Reliability é falha/recovery.","B":"Operational Excellence cobre runbooks, observability, automation, change management — não escolha de tipo de instância e benchmarks de throughput. As práticas descritas focam em eficiência de uso de recursos, que é definição literal de Performance Efficiency."},"keyConcept":"Definição direta do pilar Performance.","tutorSeeds":["Pode explicar com mais detalhe: Definição direta do pilar Performance?","Quais cenários reais aplicam Definição direta do pilar Performance?"]}'::jsonb, 'Cloud Concepts', 'Cloud Concepts', 'easy', 'recall', '["well-architected","performance"]'::jsonb, 'ai-draft', 'active', now(), now()),
    ('clf-c02-cc-027', 'aws-clf', 'Uma equipe usa Compute Savings Plans, S3 Intelligent-Tiering, right-sizes EC2 mensalmente e desliga ambientes de dev fora do horário comercial. Qual pilar do Well-Architected guia essas práticas?', '[{"id":"A","text":"Reliability"},{"id":"B","text":"Security"},{"id":"C","text":"Cost Optimization"},{"id":"D","text":"Performance Efficiency"}]'::jsonb, 'C', '{"summary":"Cost Optimization: ''avoid unnecessary costs'' — practice cloud financial management, expenditure awareness, cost-effective resources, manage demand.","whyCorrect":"Cost Optimization: ''avoid unnecessary costs'' — practice cloud financial management, expenditure awareness, cost-effective resources, manage demand. Todas as práticas listadas são cost-driven.","whyWrong":{"A":"Reliability/Security/Performance têm outros focos.","B":"Security cobre IAM, encryption, threat detection, incident response — não Savings Plans, right-sizing ou shutdown de ambientes. As práticas descritas são todas sobre custo, não sobre proteção de dados/identidades.","D":"Performance Efficiency cobre seleção de recursos para meeting de performance requirements, monitoring, trade-offs técnicos — não Savings Plans (pricing) ou desligar ambientes (cost behavior). As práticas listadas reduzem GASTO, não melhoram performance."},"keyConcept":"Definição direta.","tutorSeeds":["Pode explicar com mais detalhe: Definição direta?","Quais cenários reais aplicam Definição direta?"]}'::jsonb, 'Cloud Concepts', 'Cloud Concepts', 'easy', 'recall', '["well-architected","cost"]'::jsonb, 'ai-draft', 'active', now(), now()),
    ('clf-c02-cc-028', 'aws-clf', 'Uma empresa quer reduzir o impacto ambiental de suas workloads na AWS — otimizar uso de energia, reduzir dados não usados, escolher Regions com energia renovável. Qual pilar do Well-Architected endereça isso?', '[{"id":"A","text":"Cost Optimization"},{"id":"B","text":"Sustainability"},{"id":"C","text":"Operational Excellence"},{"id":"D","text":"Performance Efficiency"}]'::jsonb, 'B', '{"summary":"Sustainability pillar (adicionado 2021) cobre: region selection, user behavior patterns, software/architecture patterns, data patterns, hardware patterns, development patterns — tudo voltado a reduzir energia/carbono.","whyCorrect":"Sustainability pillar (adicionado 2021) cobre: region selection, user behavior patterns, software/architecture patterns, data patterns, hardware patterns, development patterns — tudo voltado a reduzir energia/carbono.","whyWrong":{"A":"Cost se sobrepõe parcialmente mas tem foco financeiro, não ambiental.","C":"Operational Excellence governa runbooks, observability e melhoria contínua — não pegada ambiental ou escolha de Region por energia renovável. OE pode SUPORTAR sustainability (via automação de shutdown), mas o pilar específico para impacto ambiental é Sustainability.","D":"Performance Efficiency foca em uso eficiente de recursos para meeting de performance — não em redução de emissões de carbono ou seleção de Region por energia renovável. Pode haver sobreposição (eficiência reduz consumo), mas o pilar canônico para metas ambientais é Sustainability."},"keyConcept":"Conceito: pilar específico para responsabilidade ambiental.","tutorSeeds":["Pode explicar com mais detalhe: Conceito: pilar específico para responsabilidade ambiental?","Quais cenários reais aplicam Conceito: pilar específico para responsabilidade ambiental?"]}'::jsonb, 'Cloud Concepts', 'Cloud Concepts', 'easy', 'recall', '["well-architected","sustainability"]'::jsonb, 'ai-draft', 'active', now(), now()),
    ('clf-c02-cc-029', 'aws-clf', 'Uma equipe quer aumentar disponibilidade movendo de single-AZ para multi-AZ. O custo dobra. Qual pilar do Well-Architected captura esse trade-off explícito entre dois pilares?', '[{"id":"A","text":"Sustainability vs Performance"},{"id":"B","text":"Reliability vs Cost Optimization (trade-off explícito permitido pelo framework)"},{"id":"C","text":"Security vs Operational Excellence"},{"id":"D","text":"Não existe trade-off — pilares são independentes"}]'::jsonb, 'B', '{"summary":"O framework reconhece explicitamente trade-offs entre pilares — mais Reliability (redundância) frequentemente custa mais.","whyCorrect":"O framework reconhece explicitamente trade-offs entre pilares — mais Reliability (redundância) frequentemente custa mais. A decisão é informada pelo business value.","whyWrong":{"A":"Outros pares têm trade-offs também (ex: Security vs Performance via encryption overhead), mas o cenário descrito é o clássico Reliability x Cost.","C":"Security e Operational Excellence frequentemente se reforçam (mais OE = melhor detection/response) — não há trade-off canônico entre eles. O trade-off mais clássico e citado pelo framework é Reliability vs Cost: redundância (multi-AZ, multi-Region) aumenta tanto disponibilidade quanto custo.","D":"Trade-offs entre pilares EXISTEM e são explicitamente reconhecidos no Well-Architected — esta opção é factualmente incorreta. Multi-AZ aumenta Reliability mas dobra custo de RDS; encryption pode adicionar latência (Performance vs Security); auto-shutdown reduz custo mas pode afetar reliability se mal configurado."},"keyConcept":"Conceito: pilares NÃO são independentes — equilíbrio é parte do framework.","tutorSeeds":["Pode explicar com mais detalhe: Conceito: pilares NÃO são independentes — equilíbrio é parte do framework?","Quais cenários reais aplicam Conceito: pilares NÃO são independentes — equilíbrio é parte do framework?"]}'::jsonb, 'Cloud Concepts', 'Cloud Concepts', 'medium', 'scenario', '["well-architected","trade-offs"]'::jsonb, 'ai-draft', 'active', now(), now()),
    ('clf-c02-cc-030', 'aws-clf', 'Após um post-mortem, a equipe escreve um runbook automatizado para o procedimento que falhou e adiciona um Game Day mensal para validar a recovery. Essas práticas pertencem majoritariamente a qual pilar?', '[{"id":"A","text":"Security"},{"id":"B","text":"Operational Excellence"},{"id":"C","text":"Cost Optimization"},{"id":"D","text":"Performance Efficiency"}]'::jsonb, 'B', '{"summary":"OE inclui runbooks, playbooks, Game Days, observability, post-mortems e melhoria contínua.","whyCorrect":"OE inclui runbooks, playbooks, Game Days, observability, post-mortems e melhoria contínua. Embora a recovery seja Reliability, a prática de Game Day + runbook é OE.","whyWrong":{"A":"Security/Cost/Performance têm outros focos.","C":"Cost Optimization cobre Savings Plans, right-sizing, expenditure awareness — não runbooks de recovery ou Game Days. Práticas pós-mortem e validação de recovery são governança operacional, não financeira.","D":"Performance Efficiency cobre seleção de tipos de recurso, caching, monitoring para latência — não runbooks de incidente ou Game Days. Práticas descritas são sobre operar bem (OE), não sobre throughput/latência (Performance)."},"keyConcept":"Conceito: OE é a ''meta-disciplina'' que governa operação dos outros pilares.","tutorSeeds":["Pode explicar com mais detalhe: Conceito: OE é a ''meta-disciplina'' que governa operação dos outros pilares?","Quais cenários reais aplicam Conceito: OE é a ''meta-disciplina'' que governa operação dos outros pilares?","Como OE se compara com alternativas?"]}'::jsonb, 'Cloud Concepts', 'Cloud Concepts', 'medium', 'best-practice', '["well-architected","operational-excellence","game-day"]'::jsonb, 'ai-draft', 'active', now(), now()),
    ('clf-c02-cc-031', 'aws-clf', 'Qual prática AWS NÃO faz parte do pilar Security do Well-Architected Framework?', '[{"id":"A","text":"Implementar least-privilege IAM"},{"id":"B","text":"Habilitar AWS CloudTrail para auditoria"},{"id":"C","text":"Comprar Reserved Instances de 3 anos para reduzir custo"},{"id":"D","text":"Criptografar dados at-rest com KMS"}]'::jsonb, 'C', '{"summary":"RIs são prática do pilar Cost Optimization — pricing/commitment não tem relação direta com Security.","whyCorrect":"RIs são prática do pilar Cost Optimization — pricing/commitment não tem relação direta com Security.","whyWrong":{"A":"Least-privilege, CloudTrail e KMS encryption são práticas core de Security (IAM, detection, data protection).","B":"Habilitar CloudTrail para auditoria É prática central de Security (pilar Detection) — log de todas chamadas de API é fundamental para detectar acesso indevido e investigar incidentes. Esta opção É parte de Security (item correto a marcar: C — Reserved Instances pertencem a Cost Optimization).","D":"Criptografar dados at-rest com KMS É prática central de Security (pilar Data Protection). Esta opção É parte de Security (item correto a marcar: C — Reserved Instances pertencem a Cost Optimization, não Security)."},"keyConcept":"Conceito: cada pilar tem práticas próprias; misturar é erro comum de classificação.","tutorSeeds":["Pode explicar com mais detalhe: Conceito: cada pilar tem práticas próprias; misturar é erro comum de classificação?","Quais cenários reais aplicam Conceito: cada pilar tem práticas próprias; misturar é erro comum de classificação?","Como RIs se compara com alternativas?"]}'::jsonb, 'Cloud Concepts', 'Cloud Concepts', 'medium', 'recall', '["well-architected","security","cost"]'::jsonb, 'ai-draft', 'active', now(), now()),
    ('clf-c02-cc-032', 'aws-clf', 'Uma aplicação atende SLO de 99.9% mas a equipe quer subir para 99.99%. Custo de redundância adicional cresce não-linearmente. Qual ferramenta do Well-Architected ajuda a justificar (ou recusar) esse investimento?', '[{"id":"A","text":"AWS Pricing Calculator apenas"},{"id":"B","text":"AWS Well-Architected Tool (review) cruzando Reliability vs Cost com impacto de negócio"},{"id":"C","text":"AWS Config rules apenas"},{"id":"D","text":"AWS Trusted Advisor apenas"}]'::jsonb, 'B', '{"summary":"Well-Architected Tool conduz uma revisão estruturada que expõe trade-offs entre pilares com perguntas específicas, registrando decisões e mitigações — base para discussão custo/benefício de SLO.","whyCorrect":"Well-Architected Tool conduz uma revisão estruturada que expõe trade-offs entre pilares com perguntas específicas, registrando decisões e mitigações — base para discussão custo/benefício de SLO.","whyWrong":{"A":"Pricing Calculator estima custo isolado.","C":"Config monitora compliance.","D":"Trusted Advisor dá recomendações genéricas."},"keyConcept":"Conceito: WA Tool é o instrumento formal de review.","tutorSeeds":["Pode explicar com mais detalhe: Conceito: WA Tool é o instrumento formal de review?","Quais cenários reais aplicam Conceito: WA Tool é o instrumento formal de review?","Como SLO se compara com alternativas?"]}'::jsonb, 'Cloud Concepts', 'Cloud Concepts', 'hard', 'scenario', '["well-architected","tool","slo"]'::jsonb, 'ai-draft', 'active', now(), now()),
    ('clf-c02-cc-033', 'aws-clf', 'Uma equipe escolhe rodar workloads em Regions com maior % de energia renovável quando latência permite. Essa decisão alinha primariamente com qual pilar?', '[{"id":"A","text":"Cost Optimization"},{"id":"B","text":"Sustainability"},{"id":"C","text":"Performance Efficiency"},{"id":"D","text":"Security"}]'::jsonb, 'B', '{"summary":"Sustainability pillar lista ''region selection'' como prática direta — escolher Regions com menor pegada de carbono.","whyCorrect":"Sustainability pillar lista ''region selection'' como prática direta — escolher Regions com menor pegada de carbono.","whyWrong":{"A":"Cost pode coincidir mas o driver explícito é ambiental.","C":"Performance é latência/throughput.","D":"Security é não relacionado."},"keyConcept":"Conceito: decisões com driver ambiental → Sustainability.","tutorSeeds":["Pode explicar com mais detalhe: Conceito: decisões com driver ambiental → Sustainability?","Quais cenários reais aplicam Conceito: decisões com driver ambiental → Sustainability?"]}'::jsonb, 'Cloud Concepts', 'Cloud Concepts', 'medium', 'best-practice', '["well-architected","sustainability","regions"]'::jsonb, 'ai-draft', 'active', now(), now()),
    ('clf-c02-cc-034', 'aws-clf', 'Uma equipe não tem monitoring centralizado, não tem dashboards de erro, e descobre incidentes através de tickets de cliente. Qual pilar do Well-Architected está mais deficiente?', '[{"id":"A","text":"Operational Excellence (observability ausente)"},{"id":"B","text":"Security (não relacionado a monitoring)"},{"id":"C","text":"Cost Optimization"},{"id":"D","text":"Sustainability"}]'::jsonb, 'A', '{"summary":"OE inclui ''understand operational health'' — telemetry, logs, métricas, alertas.","whyCorrect":"OE inclui ''understand operational health'' — telemetry, logs, métricas, alertas. Descobrir incidente via cliente é sinal clássico de OE imatura.","whyWrong":{"B":"Security também tem monitoring (GuardDuty, CloudTrail) mas o foco do cenário é operação.","C":"Cost/Sustainability são não relacionados.","D":"Sustainability cobre escolha de Region por energia renovável, eficiência de recursos para reduzir carbono, data lifecycle para reduzir storage — não tem relação direta com observability de incidentes. Falta de monitoring é deficiência operacional (OE), não ambiental."},"keyConcept":"Princípio OE: observability proativa.","tutorSeeds":["Pode explicar com mais detalhe: Princípio OE: observability proativa?","Quais cenários reais aplicam Princípio OE: observability proativa?","Como OE se compara com alternativas?"]}'::jsonb, 'Cloud Concepts', 'Cloud Concepts', 'medium', 'troubleshoot', '["well-architected","observability"]'::jsonb, 'ai-draft', 'active', now(), now()),
    ('clf-c02-cc-035', 'aws-clf', 'Uma aplicação tem latência p99 ruim. A equipe quer atacar pelo pilar Performance Efficiency. Qual prática NÃO é parte desse pilar?', '[{"id":"A","text":"Selecionar o tipo de instância ideal para o workload (compute, memory, storage optimized)"},{"id":"B","text":"Usar caching com ElastiCache/CloudFront"},{"id":"C","text":"Habilitar AWS Shield para mitigar DDoS"},{"id":"D","text":"Monitorar performance e ajustar continuamente"}]'::jsonb, 'C', '{"summary":"AWS Shield é prática do pilar Security (infrastructure protection contra DDoS) — não é Performance.","whyCorrect":"AWS Shield é prática do pilar Security (infrastructure protection contra DDoS) — não é Performance.","whyWrong":{"B":"Seleção de recursos, caching e monitoring são práticas core de Performance Efficiency.","A":"Selecionar tipo de instância correto para o workload É prática CENTRAL de Performance Efficiency — compute optimized para CPU-bound, memory optimized para in-memory caches, storage optimized para I/O. Esta opção É parte de Performance (item correto: C — AWS Shield é Security).","D":"Monitorar performance e ajustar continuamente É prática central de Performance Efficiency — review architecture and metrics regularly. Esta opção É parte de Performance (item correto: C — AWS Shield para DDoS pertence a Security)."},"keyConcept":"Conceito: DDoS é threat; mitigação cabe em Security mesmo que impacto seja em performance.","tutorSeeds":["Pode explicar com mais detalhe: Conceito: DDoS é threat; mitigação cabe em Security mesmo que impacto seja em performance?","Quais cenários reais aplicam Conceito: DDoS é threat; mitigação cabe em Security mesmo que impacto seja em performance?","Como AWS Shield se compara com alternativas?"]}'::jsonb, 'Cloud Concepts', 'Cloud Concepts', 'medium', 'recall', '["well-architected","performance"]'::jsonb, 'ai-draft', 'active', now(), now()),
    ('clf-c02-cc-036', 'aws-clf', 'Uma startup decide rodar apenas em On-Demand para flexibilidade máxima. Após 1 ano, descobre que paga 3x mais do que poderia. Qual prática do pilar Cost Optimization deveria ter sido aplicada?', '[{"id":"A","text":"Adotar Compute Savings Plans para workloads estáveis após análise de baseline"},{"id":"B","text":"Migrar tudo para Spot Instances independente do workload"},{"id":"C","text":"Ignorar Cost Explorer para não ''criar burocracia''"},{"id":"D","text":"Aumentar tamanho de todas as instâncias para reduzir quantidade"}]'::jsonb, 'A', '{"summary":"Cost pillar: ''use cost-effective resources'' — pricing models adequados.","whyCorrect":"Cost pillar: ''use cost-effective resources'' — pricing models adequados. Baseline estável → SP/RI com 1-3 anos de compromisso = até 72% de economia.","whyWrong":{"B":"Spot só vale para workloads tolerantes a interrupção.","C":"Ignorar Cost Explorer perde visibilidade.","D":"Aumentar instância é o oposto de right-sizing."},"keyConcept":"Cost Optimization é prática estruturada.","tutorSeeds":["Pode explicar com mais detalhe: Cost Optimization é prática estruturada?","Quais cenários reais aplicam Cost Optimization é prática estruturada?","Como SP se compara com alternativas?"]}'::jsonb, 'Cloud Concepts', 'Cloud Concepts', 'medium', 'scenario', '["well-architected","cost","savings-plans"]'::jsonb, 'ai-draft', 'active', now(), now()),
    ('clf-c02-cc-037', 'aws-clf', 'Qual é o objetivo central do AWS Well-Architected Framework?', '[{"id":"A","text":"Substituir a documentação de produtos AWS"},{"id":"B","text":"Fornecer um conjunto consistente de princípios e melhores práticas para projetar/operar cargas na AWS"},{"id":"C","text":"Garantir descontos de pricing automáticos para quem aderir"},{"id":"D","text":"Forçar uso de serviços específicos da AWS"}]'::jsonb, 'B', '{"summary":"WA Framework é um conjunto de boas práticas + perguntas + tool de revisão para guiar decisões arquiteturais — não substitui docs, não dá desconto, e não força serviços.","whyCorrect":"WA Framework é um conjunto de boas práticas + perguntas + tool de revisão para guiar decisões arquiteturais — não substitui docs, não dá desconto, e não força serviços.","whyWrong":{"A":"Well-Architected NÃO substitui documentação de produtos AWS — são recursos complementares. Documentação descreve COMO usar um serviço; WA descreve PRINCÍPIOS arquiteturais e práticas. WA referencia documentação, não a substitui.","C":"Não há descontos automáticos de pricing por aderir ao Well-Architected — é framework de boas práticas, não programa de billing. Cliente pode até receber créditos AWS após realizar WA Review com partner certificado, mas isso é promoção pontual, não característica do framework.","D":"Well-Architected NÃO força uso de serviços específicos — é agnóstico a quais serviços usar. As perguntas são sobre práticas (encryption ativa? logs centralizados?), não ''use serviço X''. O framework reconhece que múltiplos serviços podem atender ao mesmo requisito."},"keyConcept":"Ver Well-Architected Framework.","tutorSeeds":["Pode explicar com mais detalhe: Ver Well-Architected Framework?","Quais cenários reais aplicam Ver Well-Architected Framework?","Como WA se compara com alternativas?"]}'::jsonb, 'Cloud Concepts', 'Cloud Concepts', 'easy', 'recall', '["well-architected","framework"]'::jsonb, 'ai-draft', 'active', now(), now()),
    ('clf-c02-cc-038', 'aws-clf', 'Uma empresa percebe que tem 80 TB de snapshots EBS antigos sem owner, dados S3 em Standard com último acesso há 2 anos, e clusters dev rodando 24/7. Qual pilar do Well-Architected mais imediatamente endereçaria essas observações?', '[{"id":"A","text":"Cost Optimization (com forte sobreposição com Sustainability)"},{"id":"B","text":"Security apenas"},{"id":"C","text":"Performance Efficiency apenas"},{"id":"D","text":"Reliability apenas"}]'::jsonb, 'A', '{"summary":"Recursos não usados → custo + uso desnecessário de energia/hardware.","whyCorrect":"Recursos não usados → custo + uso desnecessário de energia/hardware. Cost Optimization (expenditure awareness, cost-effective resources) é o foco direto, com sobreposição com Sustainability (data patterns — eliminar dados não-essenciais).","whyWrong":{"B":"Security/Performance/Reliability não tratam recursos ociosos.","C":"Performance Efficiency foca em uso adequado de recursos para meeting de SLAs de latência/throughput — recursos órfãos não impactam diretamente performance da aplicação que está rodando. O problema descrito é gasto desnecessário, não lentidão.","D":"Reliability foca em disponibilidade e recovery — recursos sem owner não comprometem reliability da aplicação principal. Snapshots órfãos e dev 24/7 não são fault modes — são waste. O pilar canônico é Cost Optimization."},"keyConcept":"Conceito: pilares são complementares — várias respostas podem ser corretas, mas Cost é o mais direto.","tutorSeeds":["Pode explicar com mais detalhe: Conceito: pilares são complementares — várias respostas podem ser corretas, mas Cost é o mais direto?","Quais cenários reais aplicam Conceito: pilares são complementares — várias respostas podem ser corretas, mas Cost é o mais direto?"]}'::jsonb, 'Cloud Concepts', 'Cloud Concepts', 'hard', 'scenario', '["well-architected","cost","sustainability"]'::jsonb, 'ai-draft', 'active', now(), now()),
    ('clf-c02-cc-039', 'aws-clf', 'Em uma migração das 6 Rs, qual estratégia descreve mover a aplicação para AWS sem mudanças significativas no código (também chamado de ''lift and shift'')?', '[{"id":"A","text":"Rehost"},{"id":"B","text":"Replatform"},{"id":"C","text":"Refactor"},{"id":"D","text":"Repurchase"}]'::jsonb, 'A', '{"summary":"Rehost = lift-and-shift puro: VM para EC2 sem alterar binários/código.","whyCorrect":"Rehost = lift-and-shift puro: VM para EC2 sem alterar binários/código. Rápido, baixo risco, mas não aproveita features cloud-native.","whyWrong":{"B":"Replatform = lift-tinker-shift (ex: migrar DB para RDS managed).","C":"Refactor = redesenhar (ex: monolito → microserviços/serverless).","D":"Repurchase = trocar produto (ex: SAP on-prem → SaaS)."},"keyConcept":"Termos AWS Migration Strategies.","tutorSeeds":["Pode explicar com mais detalhe: Termos AWS Migration Strategies?","Quais cenários reais aplicam Termos AWS Migration Strategies?","Como VM se compara com alternativas?"]}'::jsonb, 'Cloud Concepts', 'Cloud Concepts', 'easy', 'recall', '["migration","6rs","rehost"]'::jsonb, 'ai-draft', 'active', now(), now()),
    ('clf-c02-cc-040', 'aws-clf', 'Uma empresa migra um app Java rodando em servidor próprio para AWS, mantém o código, mas troca o MySQL self-managed por Amazon RDS for MySQL. Qual estratégia das 6 Rs descreve essa migração?', '[{"id":"A","text":"Rehost"},{"id":"B","text":"Replatform"},{"id":"C","text":"Refactor"},{"id":"D","text":"Retain"}]'::jsonb, 'B', '{"summary":"Replatform = ''lift-tinker-shift'': mantém código mas troca componentes de infra por managed equivalents (MySQL → RDS, JVM em VM → JVM em EC2 com auto-scaling).","whyCorrect":"Replatform = ''lift-tinker-shift'': mantém código mas troca componentes de infra por managed equivalents (MySQL → RDS, JVM em VM → JVM em EC2 com auto-scaling). Ganha benefício managed sem reescrever app.","whyWrong":{"A":"Rehost não trocaria DB.","C":"Refactor reescreveria o app.","D":"Retain mantém on-prem."},"keyConcept":"Conceito: tinkering = mudanças leves.","tutorSeeds":["Pode explicar com mais detalhe: Conceito: tinkering = mudanças leves?","Quais cenários reais aplicam Conceito: tinkering = mudanças leves?","Como RDS se compara com alternativas?"]}'::jsonb, 'Cloud Concepts', 'Cloud Concepts', 'medium', 'scenario', '["migration","6rs","replatform"]'::jsonb, 'ai-draft', 'active', now(), now()),
    ('clf-c02-cc-041', 'aws-clf', 'Uma empresa decide reescrever sua aplicação monolítica .NET em microserviços usando Lambda + API Gateway + DynamoDB. Qual estratégia das 6 Rs descreve essa decisão?', '[{"id":"A","text":"Refactor (Re-architect)"},{"id":"B","text":"Rehost"},{"id":"C","text":"Repurchase"},{"id":"D","text":"Retire"}]'::jsonb, 'A', '{"summary":"Refactor = reescrita significativa para arquitetura cloud-native — mais investimento, mais ROI, mais agilidade futura.","whyCorrect":"Refactor = reescrita significativa para arquitetura cloud-native — mais investimento, mais ROI, mais agilidade futura.","whyWrong":{"B":"Rehost mantém código.","C":"Repurchase troca por SaaS pronto.","D":"Retire descomissiona."},"keyConcept":"Conceito: Refactor é o R mais caro e impactante das 6 Rs.","tutorSeeds":["Pode explicar com mais detalhe: Conceito: Refactor é o R mais caro e impactante das 6 Rs?","Quais cenários reais aplicam Conceito: Refactor é o R mais caro e impactante das 6 Rs?","Como ROI se compara com alternativas?"]}'::jsonb, 'Cloud Concepts', 'Cloud Concepts', 'easy', 'scenario', '["migration","6rs","refactor"]'::jsonb, 'ai-draft', 'active', now(), now()),
    ('clf-c02-cc-042', 'aws-clf', 'Uma empresa substitui seu CRM Siebel on-prem por Salesforce SaaS durante a migração para AWS. Qual estratégia das 6 Rs descreve esse movimento?', '[{"id":"A","text":"Refactor"},{"id":"B","text":"Replatform"},{"id":"C","text":"Repurchase (drop and shop)"},{"id":"D","text":"Retain"}]'::jsonb, 'C', '{"summary":"Repurchase = trocar produto atual por outro (geralmente SaaS) — ''drop and shop''.","whyCorrect":"Repurchase = trocar produto atual por outro (geralmente SaaS) — ''drop and shop''. Comum para CRM (Salesforce), email (M365), HR (Workday).","whyWrong":{"A":"Refactor/Replatform implicariam manter ou portar o Siebel.","D":"Retain manteria on-prem.","B":"Replatform (lift, tinker, and shift) seria mover a aplicação para AWS com alterações mínimas (ex: trocar MySQL self-managed por RDS) mantendo o produto/funcionalidade. Substituir TOTALMENTE o CRM por uma alternativa SaaS é Repurchase, não Replatform — o app antigo desaparece e é trocado por outro produto."},"keyConcept":"Conceito: Repurchase elimina a app de uma vez por um equivalente comercial.","tutorSeeds":["Pode explicar com mais detalhe: Conceito: Repurchase elimina a app de uma vez por um equivalente comercial?","Quais cenários reais aplicam Conceito: Repurchase elimina a app de uma vez por um equivalente comercial?","Como CRM se compara com alternativas?"]}'::jsonb, 'Cloud Concepts', 'Cloud Concepts', 'medium', 'scenario', '["migration","6rs","repurchase","saas"]'::jsonb, 'ai-draft', 'active', now(), now()),
    ('clf-c02-cc-043', 'aws-clf', 'Durante a discovery de migração, uma equipe descobre que um servidor de aplicação está rodando mas ninguém na empresa consegue identificar a função, nem aparece tráfego significativo nos logs há 18 meses. Qual estratégia das 6 Rs aplicar?', '[{"id":"A","text":"Rehost"},{"id":"B","text":"Retire (descomissionar)"},{"id":"C","text":"Refactor"},{"id":"D","text":"Retain"}]'::jsonb, 'B', '{"summary":"Retire = identificar e desligar workloads sem uso.","whyCorrect":"Retire = identificar e desligar workloads sem uso. Reduz custo, surface de ataque e escopo de migração. Estima-se que ~10-20% das apps em DCs grandes podem ser retired.","whyWrong":{"C":"Refactor de app sem uso é absurdo.","D":"Retain = manter on-prem por motivo específico (não ''por inércia'').","A":"Rehost (lift-and-shift) migraria o servidor para AWS as-is — mas o requisito aqui é DESLIGAR um workload sem uso, não migrar. Rehostar app esquecido seria gastar dinheiro em algo que ninguém usa. A 6R correta é Retire (descomissionar)."},"keyConcept":"Conceito: discovery é crucial — retire libera orçamento.","tutorSeeds":["Pode explicar com mais detalhe: Conceito: discovery é crucial — retire libera orçamento?","Quais cenários reais aplicam Conceito: discovery é crucial — retire libera orçamento?","Como DCs se compara com alternativas?"]}'::jsonb, 'Cloud Concepts', 'Cloud Concepts', 'medium', 'scenario', '["migration","6rs","retire"]'::jsonb, 'ai-draft', 'active', now(), now()),
    ('clf-c02-cc-044', 'aws-clf', 'Durante a migração, uma equipe identifica um mainframe rodando workload regulado que ainda não tem caminho viável para nuvem nesta janela e cuja licença vai expirar em 4 anos. Qual estratégia das 6 Rs aplicar agora?', '[{"id":"A","text":"Retain (manter on-prem temporariamente, revisitar depois)"},{"id":"B","text":"Rehost imediatamente para EC2 metal"},{"id":"C","text":"Retire o sistema regulado"},{"id":"D","text":"Refactor para Lambda em 1 sprint"}]'::jsonb, 'A', '{"summary":"Retain = decisão consciente de manter on-prem (ou em outro provedor) por compliance, dependência técnica ou ROI insuficiente.","whyCorrect":"Retain = decisão consciente de manter on-prem (ou em outro provedor) por compliance, dependência técnica ou ROI insuficiente. Revisitar em ciclos futuros.","whyWrong":{"B":"Mainframe regulated não é trivial para EC2 metal.","C":"Retire de sistema regulado em uso é impossível.","D":"Refactor em 1 sprint é fantasia."},"keyConcept":"Conceito: Retain é estratégia válida, não ''falha''.","tutorSeeds":["Pode explicar com mais detalhe: Conceito: Retain é estratégia válida, não ''falha''?","Quais cenários reais aplicam Conceito: Retain é estratégia válida, não ''falha''?","Como ROI se compara com alternativas?"]}'::jsonb, 'Cloud Concepts', 'Cloud Concepts', 'medium', 'scenario', '["migration","6rs","retain"]'::jsonb, 'ai-draft', 'active', now(), now()),
    ('clf-c02-cc-045', 'aws-clf', 'Qual das 6 Rs tipicamente entrega o MENOR ganho de cloud-native features, porém com o menor risco e prazo mais curto de migração?', '[{"id":"A","text":"Refactor"},{"id":"B","text":"Rehost"},{"id":"C","text":"Repurchase"},{"id":"D","text":"Retire"}]'::jsonb, 'B', '{"summary":"Rehost (lift-and-shift) é o caminho mais rápido — VM vira AMI, sobe em EC2, sem reescrita.","whyCorrect":"Rehost (lift-and-shift) é o caminho mais rápido — VM vira AMI, sobe em EC2, sem reescrita. Ganho de cloud-native é mínimo, mas tempo/risco também. Bom como ponto de partida antes de iterar para replatform/refactor.","whyWrong":{"A":"Refactor é o oposto.","C":"Repurchase troca por outro produto.","D":"Retire não é migração."},"keyConcept":"Conceito: trade-off prazo/risco × benefício cloud-native.","tutorSeeds":["Pode explicar com mais detalhe: Conceito: trade-off prazo/risco × benefício cloud-native?","Quais cenários reais aplicam Conceito: trade-off prazo/risco × benefício cloud-native?","Como VM se compara com alternativas?"]}'::jsonb, 'Cloud Concepts', 'Cloud Concepts', 'medium', 'best-practice', '["migration","6rs","rehost"]'::jsonb, 'ai-draft', 'active', now(), now()),
    ('clf-c02-cc-046', 'aws-clf', 'Uma empresa quer reduzir TCO ao máximo na migração e tem 12 meses para concluir. A maioria das aplicações é de baixa complexidade. Qual estratégia das 6 Rs MAIS provavelmente domina o portfólio nesse cenário?', '[{"id":"A","text":"Rehost para acelerar, com replatform/refactor seletivo em apps de maior ROI"},{"id":"B","text":"Refactor 100% do portfólio em 12 meses"},{"id":"C","text":"Retain todas as apps por segurança"},{"id":"D","text":"Repurchase de todas as apps por SaaS"}]'::jsonb, 'A', '{"summary":"Padrão real de migrações de grande escala: rehost domina (60-80%) para destravar a saída do DC, e em paralelo aplica-se replatform/refactor onde o ROI justifica.","whyCorrect":"Padrão real de migrações de grande escala: rehost domina (60-80%) para destravar a saída do DC, e em paralelo aplica-se replatform/refactor onde o ROI justifica.","whyWrong":{"B":"Refactor 100% em 12 meses é inviável.","C":"Retain integral nega o objetivo.","D":"Repurchase total é raro."},"keyConcept":"Conceito: estratégia mista é a regra.","tutorSeeds":["Pode explicar com mais detalhe: Conceito: estratégia mista é a regra?","Quais cenários reais aplicam Conceito: estratégia mista é a regra?","Como DC se compara com alternativas?"]}'::jsonb, 'Cloud Concepts', 'Cloud Concepts', 'hard', 'best-practice', '["migration","6rs","portfolio"]'::jsonb, 'ai-draft', 'active', now(), now()),
    ('clf-c02-cc-047', 'aws-clf', 'Qual modelo de serviço cloud descreve quando o cliente é responsável apenas por configurar a aplicação e os dados, enquanto o provedor gerencia OS, middleware, runtime e infraestrutura?', '[{"id":"A","text":"IaaS"},{"id":"B","text":"PaaS"},{"id":"C","text":"SaaS"},{"id":"D","text":"On-premises"}]'::jsonb, 'B', '{"summary":"PaaS = cliente cuida só de app + dados.","whyCorrect":"PaaS = cliente cuida só de app + dados. Ex AWS: Elastic Beanstalk, App Runner.","whyWrong":{"A":"IaaS = cliente gerencia OS+middleware+app (ex: EC2).","C":"SaaS = cliente só consome a aplicação (ex: Amazon WorkMail, Salesforce).","D":"On-premises NÃO é modelo cloud — é o oposto: cliente é responsável por TUDO (data center físico, networking, hardware, hypervisor, SO, middleware, runtime, aplicação, dados). PaaS e on-prem são extremos opostos do espectro de responsabilidade."},"keyConcept":"Regra: quanto mais ''aaS'', menos responsabilidade do cliente.","tutorSeeds":["Pode explicar com mais detalhe: Regra: quanto mais ''aaS'', menos responsabilidade do cliente?","Quais cenários reais aplicam Regra: quanto mais ''aaS'', menos responsabilidade do cliente?","Como AWS se compara com alternativas?"]}'::jsonb, 'Cloud Concepts', 'Cloud Concepts', 'easy', 'recall', '["service-models","paas"]'::jsonb, 'ai-draft', 'active', now(), now()),
    ('clf-c02-cc-048', 'aws-clf', 'Amazon EC2 é classificado em qual modelo de serviço cloud?', '[{"id":"A","text":"SaaS"},{"id":"B","text":"PaaS"},{"id":"C","text":"IaaS"},{"id":"D","text":"FaaS"}]'::jsonb, 'C', '{"summary":"EC2 entrega VMs — cliente escolhe AMI, configura OS, instala software.","whyCorrect":"EC2 entrega VMs — cliente escolhe AMI, configura OS, instala software. É IaaS clássico.","whyWrong":{"A":"SaaS é app pronta.","B":"PaaS abstrai OS.","D":"FaaS (Lambda) é função-as-a-service, ainda mais alto."},"keyConcept":"Hierarquia: IaaS (EC2) < PaaS (Beanstalk) < FaaS (Lambda) < SaaS (WorkMail).","tutorSeeds":["Pode explicar com mais detalhe: Hierarquia: IaaS (EC2) < PaaS (Beanstalk) < FaaS (Lambda) < SaaS (WorkMail)?","Quais cenários reais aplicam Hierarquia: IaaS (EC2) < PaaS (Beanstalk) < FaaS (Lambda) < SaaS (WorkMail)?","Como EC2 se compara com alternativas?"]}'::jsonb, 'Cloud Concepts', 'Cloud Concepts', 'easy', 'recall', '["service-models","iaas","ec2"]'::jsonb, 'ai-draft', 'active', now(), now()),
    ('clf-c02-cc-049', 'aws-clf', 'Uma empresa usa Amazon WorkMail para email corporativo. Qual modelo de serviço cloud isso representa?', '[{"id":"A","text":"IaaS"},{"id":"B","text":"PaaS"},{"id":"C","text":"SaaS"},{"id":"D","text":"FaaS"}]'::jsonb, 'C', '{"summary":"SaaS = software pronto, cliente consome — não gerencia OS, runtime, app.","whyCorrect":"SaaS = software pronto, cliente consome — não gerencia OS, runtime, app. WorkMail (email), Chime (comunicação), QuickSight (BI) são SaaS da AWS.","whyWrong":{"A":"IaaS exige gestão de OS.","B":"PaaS exige gestão da app.","D":"FaaS exige código da função."},"keyConcept":"Regra: cliente clica e usa = SaaS.","tutorSeeds":["Pode explicar com mais detalhe: Regra: cliente clica e usa = SaaS?","Quais cenários reais aplicam Regra: cliente clica e usa = SaaS?","Como OS se compara com alternativas?"]}'::jsonb, 'Cloud Concepts', 'Cloud Concepts', 'easy', 'recall', '["service-models","saas","workmail"]'::jsonb, 'ai-draft', 'active', now(), now()),
    ('clf-c02-cc-050', 'aws-clf', 'Qual afirmação descreve corretamente a diferença de responsabilidade entre IaaS e PaaS na AWS?', '[{"id":"A","text":"Em IaaS o cliente patcha o OS; em PaaS isso é abstraído pelo provedor"},{"id":"B","text":"Em IaaS o cliente não tem responsabilidade nenhuma; PaaS é mais restritivo"},{"id":"C","text":"PaaS exige que o cliente gerencie o datacenter físico"},{"id":"D","text":"IaaS e PaaS são idênticos em responsabilidade"}]'::jsonb, 'A', '{"summary":"IaaS (EC2): cliente é responsável por guest OS, patches, middleware e app.","whyCorrect":"IaaS (EC2): cliente é responsável por guest OS, patches, middleware e app. PaaS (Beanstalk): cliente entrega só o código; AWS cuida de OS, runtime, scaling.","whyWrong":{"B":"Cliente sempre tem responsabilidade (dados, IAM, config). PaaS é mais ''managed'', não mais restritivo.","C":"DC físico é sempre AWS.","D":"IaaS e PaaS NÃO são idênticos — diferem fundamentalmente no nível de abstração e responsabilidade. IaaS expõe VMs e exige cliente gerenciar OS+up; PaaS abstrai OS/runtime e cliente entrega só código. Esta opção é factualmente incorreta."},"keyConcept":"Conceito: shared responsibility varia com nível de managed.","tutorSeeds":["Pode explicar com mais detalhe: Conceito: shared responsibility varia com nível de managed?","Quais cenários reais aplicam Conceito: shared responsibility varia com nível de managed?","Como EC2 se compara com alternativas?"]}'::jsonb, 'Cloud Concepts', 'Cloud Concepts', 'medium', 'best-practice', '["service-models","iaas","paas","shared-responsibility"]'::jsonb, 'ai-draft', 'active', now(), now()),
    ('clf-c02-cc-051', 'aws-clf', 'Um cliente quer rodar um app web em Java sem se preocupar com configurar EC2, Auto Scaling, ALB ou patching de OS — só fazer upload do JAR. Qual serviço AWS entrega esse modelo PaaS?', '[{"id":"A","text":"Amazon EC2"},{"id":"B","text":"AWS Elastic Beanstalk"},{"id":"C","text":"AWS Lambda em modo container"},{"id":"D","text":"Amazon ECS launch type EC2"}]'::jsonb, 'B', '{"summary":"Elastic Beanstalk = PaaS clássico AWS: upload do código, AWS provisiona EC2/ALB/ASG/patching automaticamente.","whyCorrect":"Elastic Beanstalk = PaaS clássico AWS: upload do código, AWS provisiona EC2/ALB/ASG/patching automaticamente.","whyWrong":{"C":"Lambda é FaaS (modelo de função, não de app long-running).","A":"Amazon EC2 é IaaS puro — cliente é responsável por provisionar instância, configurar Auto Scaling, criar ALB, patchar OS, instalar JRE/Tomcat, fazer deploy. É o oposto do que o cliente quer (''upload do JAR e pronto''). EC2 seria correto se cliente quisesse controle máximo sobre tuning de OS/JVM.","D":"ECS launch type EC2 ainda exige que o cliente gerencie o cluster de EC2 (provisioning, scaling, patching dos hosts). É menos managed que Fargate. Para ''só fazer upload e esquecer infra'', o caminho é Beanstalk (PaaS clássico) ou Fargate/Lambda (serverless)."},"keyConcept":"Regra: PaaS = upload e esquece infra.","tutorSeeds":["Pode explicar com mais detalhe: Regra: PaaS = upload e esquece infra?","Quais cenários reais aplicam Regra: PaaS = upload e esquece infra?","Como AWS se compara com alternativas?"]}'::jsonb, 'Cloud Concepts', 'Cloud Concepts', 'medium', 'scenario', '["service-models","paas","elastic-beanstalk"]'::jsonb, 'ai-draft', 'active', now(), now()),
    ('clf-c02-cc-052', 'aws-clf', 'Uma equipe precisa decidir entre 3 modelos: IaaS (EC2), PaaS (Elastic Beanstalk), SaaS (WorkMail). Qual fator NÃO é um critério legítimo de escolha entre modelos?', '[{"id":"A","text":"Quanto controle a equipe precisa sobre OS/runtime"},{"id":"B","text":"Tempo de equipe disponível para gerenciar infra"},{"id":"C","text":"Se a AWS oferece SLA financeiro maior em IaaS vs SaaS"},{"id":"D","text":"Customização técnica exigida pela aplicação"}]'::jsonb, 'C', '{"summary":"SLAs variam por serviço específico, não por modelo (IaaS/PaaS/SaaS).","whyCorrect":"SLAs variam por serviço específico, não por modelo (IaaS/PaaS/SaaS). Não é critério de escolha entre modelos.","whyWrong":{"A":"Controle, tempo de equipe e customização são critérios legítimos clássicos.","B":"Tempo de equipe disponível para gerenciar infra É critério legítimo de escolha — equipes pequenas tendem a preferir mais managed (PaaS/SaaS) para focar em produto; equipes com expertise em ops podem assumir IaaS. (Item correto: C — SLA não varia sistematicamente por modelo).","D":"Customização técnica exigida pela aplicação É critério legítimo — apps com necessidades especiais (drivers customizados, kernel tuning, GPU específica) podem exigir IaaS; apps padrão Java/Python rodam bem em PaaS. (Item correto: C — SLA financeiro não é função do modelo)."},"keyConcept":"Conceito: escolha do modelo é trade-off controle × esforço × customização — não SLA agregado.","tutorSeeds":["Pode explicar com mais detalhe: Conceito: escolha do modelo é trade-off controle × esforço × customização — não SLA agregado?","Quais cenários reais aplicam Conceito: escolha do modelo é trade-off controle × esforço × customização — não SLA agregado?","Como SLAs se compara com alternativas?"]}'::jsonb, 'Cloud Concepts', 'Cloud Concepts', 'hard', 'best-practice', '["service-models","decision"]'::jsonb, 'ai-draft', 'active', now(), now()),
    ('clf-c02-cc-053', 'aws-clf', 'Qual descreve corretamente o modelo de deployment ''public cloud''?', '[{"id":"A","text":"Infra hospedada e operada por um provedor (ex: AWS), multi-tenant, acessível via internet"},{"id":"B","text":"Infra hospedada no DC do próprio cliente, com hardware dedicado"},{"id":"C","text":"Combinação de cloud + on-premises com conectividade dedicada"},{"id":"D","text":"Apenas acessível por usuários de um único país"}]'::jsonb, 'A', '{"summary":"Public cloud = provedor (AWS/Azure/GCP) é dono da infra, oferta multi-tenant, acesso via internet com isolamento lógico (VPC, IAM, encryption).","whyCorrect":"Public cloud = provedor (AWS/Azure/GCP) é dono da infra, oferta multi-tenant, acesso via internet com isolamento lógico (VPC, IAM, encryption).","whyWrong":{"C":"On-prem/private cloud é cliente-owned.","B":"Infra hospedada no DC do cliente com hardware dedicado é DEFINIÇÃO de private cloud (on-premises) — oposto de public cloud. Public cloud é multi-tenant, do provedor, acessível via internet pública (com isolamento lógico).","D":"Public cloud por design é acessível globalmente via internet — não é restrita a um único país. AWS Regions estão espalhadas globalmente e qualquer cliente pode acessar qualquer Region (com exceções: GovCloud e China são restritas). ''Acessível por usuários de um único país'' descreveria uma cloud privada de uma empresa local."},"keyConcept":"Conceito: 3 modelos = public, private/on-prem, hybrid.","tutorSeeds":["Pode explicar com mais detalhe: Conceito: 3 modelos = public, private/on-prem, hybrid?","Quais cenários reais aplicam Conceito: 3 modelos = public, private/on-prem, hybrid?","Como AWS se compara com alternativas?"]}'::jsonb, 'Cloud Concepts', 'Cloud Concepts', 'easy', 'recall', '["deployment-models","public-cloud"]'::jsonb, 'ai-draft', 'active', now(), now()),
    ('clf-c02-cc-054', 'aws-clf', 'Uma empresa quer rodar workloads regulados on-prem (compliance bancária) E aproveitar burst para AWS quando precisa de capacidade extra, com VPN/Direct Connect entre os dois. Qual modelo de deployment isso representa?', '[{"id":"A","text":"Public cloud apenas"},{"id":"B","text":"Hybrid cloud"},{"id":"C","text":"Private cloud apenas"},{"id":"D","text":"Multi-tenant cloud"}]'::jsonb, 'B', '{"summary":"Hybrid = combinação on-prem + cloud com conectividade integrada (Direct Connect, VPN, Storage Gateway, Outposts).","whyCorrect":"Hybrid = combinação on-prem + cloud com conectividade integrada (Direct Connect, VPN, Storage Gateway, Outposts). Cargas reguladas ficam on-prem; burst e workloads novos vão para cloud.","whyWrong":{"A":"Public-only não retém workload on-prem.","D":"Private-only não tem AWS. ''Multi-tenant'' não é um modelo de deployment.","C":"Private cloud é infra exclusiva on-prem ou hosted, sem componente de cloud pública integrada — não cobre o cenário descrito que envolve burst para AWS. Private cloud apenas não daria capacidade extra elástica. A combinação on-prem + AWS com conectividade é definição de hybrid."},"keyConcept":"Conceito: hybrid é padrão dominante em enterprise.","tutorSeeds":["Pode explicar com mais detalhe: Conceito: hybrid é padrão dominante em enterprise?","Quais cenários reais aplicam Conceito: hybrid é padrão dominante em enterprise?","Como VPN se compara com alternativas?"]}'::jsonb, 'Cloud Concepts', 'Cloud Concepts', 'easy', 'scenario', '["deployment-models","hybrid"]'::jsonb, 'ai-draft', 'active', now(), now()),
    ('clf-c02-cc-055', 'aws-clf', 'Uma empresa precisa rodar serviços AWS DENTRO do próprio data center on-prem por requisitos de latência ultra-baixa para máquinas industriais. Qual serviço AWS habilita esse padrão hybrid?', '[{"id":"A","text":"AWS Direct Connect"},{"id":"B","text":"AWS Outposts"},{"id":"C","text":"Amazon CloudFront"},{"id":"D","text":"AWS Storage Gateway"}]'::jsonb, 'B', '{"summary":"Outposts = racks AWS instalados fisicamente no DC do cliente, rodando EC2/EBS/S3/RDS/ECS locally e gerenciados pela AWS — extensão da Region.","whyCorrect":"Outposts = racks AWS instalados fisicamente no DC do cliente, rodando EC2/EBS/S3/RDS/ECS locally e gerenciados pela AWS — extensão da Region. Latência sub-ms para hardware adjacente.","whyWrong":{"A":"Direct Connect é só conectividade.","C":"CloudFront é edge para conteúdo.","D":"Storage Gateway é integração de storage."},"keyConcept":"Conceito: Outposts é AWS rodando no DC do cliente.","tutorSeeds":["Pode explicar com mais detalhe: Conceito: Outposts é AWS rodando no DC do cliente?","Quais cenários reais aplicam Conceito: Outposts é AWS rodando no DC do cliente?","Como AWS se compara com alternativas?"]}'::jsonb, 'Cloud Concepts', 'Cloud Concepts', 'medium', 'scenario', '["deployment-models","hybrid","outposts"]'::jsonb, 'ai-draft', 'active', now(), now()),
    ('clf-c02-cc-056', 'aws-clf', 'Uma empresa de mídia quer rodar workloads VMware existentes na AWS sem reescrever para EC2 nativo, mantendo vSphere/vSAN/NSX. Qual serviço AWS habilita esse padrão?', '[{"id":"A","text":"VMware Cloud on AWS"},{"id":"B","text":"AWS Lambda"},{"id":"C","text":"AWS Elastic Beanstalk"},{"id":"D","text":"Amazon S3"}]'::jsonb, 'A', '{"summary":"VMware Cloud on AWS roda o vSphere stack nativo em hardware dedicado AWS — VMs migram com vMotion sem refactor, mantém ferramentas VMware existentes.","whyCorrect":"VMware Cloud on AWS roda o vSphere stack nativo em hardware dedicado AWS — VMs migram com vMotion sem refactor, mantém ferramentas VMware existentes.","whyWrong":{"B":"Lambda é serverless function.","C":"Beanstalk é PaaS para apps de novo design.","D":"Amazon S3 é serviço de object storage — não roda VMs nem executa stack VMware. S3 seria útil para backups, snapshots ou archival de dados VMware, mas não para rodar o vSphere stack. VMware Cloud on AWS é o serviço dedicado para rodar VMware nativamente na AWS."},"keyConcept":"Conceito: VMware on AWS é caminho de migração para parques VMware grandes.","tutorSeeds":["Pode explicar com mais detalhe: Conceito: VMware on AWS é caminho de migração para parques VMware grandes?","Quais cenários reais aplicam Conceito: VMware on AWS é caminho de migração para parques VMware grandes?","Como VMware se compara com alternativas?"]}'::jsonb, 'Cloud Concepts', 'Cloud Concepts', 'medium', 'scenario', '["deployment-models","vmware","hybrid"]'::jsonb, 'ai-draft', 'active', now(), now()),
    ('clf-c02-cc-057', 'aws-clf', 'Qual descreve corretamente ''private cloud'' (também chamada on-premises cloud)?', '[{"id":"A","text":"Infra exclusiva de uma organização, on-prem ou hosted, sem multi-tenancy externa"},{"id":"B","text":"AWS dedicada para um único cliente, exclusiva por SLA"},{"id":"C","text":"Apenas acessível em uma única região geográfica"},{"id":"D","text":"Uma combinação obrigatória de cloud pública + on-prem"}]'::jsonb, 'A', '{"summary":"Private cloud = infra dedicada a uma única organização, geralmente on-prem com OpenStack/VMware.","whyCorrect":"Private cloud = infra dedicada a uma única organização, geralmente on-prem com OpenStack/VMware. Não é multi-tenant. AWS não é private cloud (multi-tenant por design).","whyWrong":{"B":"AWS NÃO é private cloud — é public cloud multi-tenant por design. AWS oferece isolamento LÓGICO (VPC, IAM, encryption) e algumas opções de tenancy dedicada (Dedicated Hosts, Dedicated Instances) mas a infra subjacente é compartilhada entre clientes. ''Private cloud'' refere-se a deploy on-prem (OpenStack, VMware) exclusivo de uma organização.","C":"Private cloud pode ser acessível de qualquer geografia — depende da configuração de rede da organização, não do modelo. Não há restrição inerente a uma região geográfica. Esta opção mistura conceitos não relacionados.","D":"Private cloud SOZINHA é um modelo válido — não exige combinação com cloud pública. Hybrid é o modelo que combina obrigatoriamente os dois. Private pura existe (empresa com OpenStack on-prem e zero cloud pública)."},"keyConcept":"Conceito: 3 modelos de deployment = public, private, hybrid.","tutorSeeds":["Pode explicar com mais detalhe: Conceito: 3 modelos de deployment = public, private, hybrid?","Quais cenários reais aplicam Conceito: 3 modelos de deployment = public, private, hybrid?","Como VMware se compara com alternativas?"]}'::jsonb, 'Cloud Concepts', 'Cloud Concepts', 'medium', 'recall', '["deployment-models","private-cloud"]'::jsonb, 'ai-draft', 'active', now(), now()),
    ('clf-c02-cc-058', 'aws-clf', 'Qual é a definição correta de Total Cost of Ownership (TCO) no contexto de avaliar migração para AWS?', '[{"id":"A","text":"Apenas o custo de hardware comprado"},{"id":"B","text":"Soma de todos os custos diretos e indiretos ao longo do ciclo de vida (hardware, software, energia, real estate, equipe, downtime, suporte)"},{"id":"C","text":"Custo mensal previsto na fatura AWS apenas"},{"id":"D","text":"Apenas o salário da equipe de DevOps"}]'::jsonb, 'B', '{"summary":"TCO completo inclui CapEx (servidores, racks, real estate) + OpEx (energia, refrigeração, equipe, licenças, manutenção, downtime, segurança física).","whyCorrect":"TCO completo inclui CapEx (servidores, racks, real estate) + OpEx (energia, refrigeração, equipe, licenças, manutenção, downtime, segurança física). AWS substitui várias categorias dessas, daí a comparação é multi-dimensional.","whyWrong":{"A":"Hardware sozinho é fração.","C":"Fatura AWS é só uma parte.","D":"Salário sozinho é fração."},"keyConcept":"Conceito: TCO é holístico, não custo único.","tutorSeeds":["Pode explicar com mais detalhe: Conceito: TCO é holístico, não custo único?","Quais cenários reais aplicam Conceito: TCO é holístico, não custo único?","Como TCO se compara com alternativas?"]}'::jsonb, 'Cloud Concepts', 'Cloud Concepts', 'easy', 'recall', '["tco","finance"]'::jsonb, 'ai-draft', 'active', now(), now()),
    ('clf-c02-cc-059', 'aws-clf', 'Um CIO quer comparar o custo de continuar no DC próprio vs migrar para AWS ao longo de 5 anos. Qual ferramenta AWS é desenhada especificamente para essa análise?', '[{"id":"A","text":"AWS Pricing Calculator (com inputs de uso projetado)"},{"id":"B","text":"AWS Cost Explorer"},{"id":"C","text":"AWS Budgets"},{"id":"D","text":"AWS Trusted Advisor"}]'::jsonb, 'A', '{"summary":"AWS Pricing Calculator estima custo prospectivo baseado em configurações hipotéticas — entrada certa para comparar cenários on-prem vs AWS antes da migração.","whyCorrect":"AWS Pricing Calculator estima custo prospectivo baseado em configurações hipotéticas — entrada certa para comparar cenários on-prem vs AWS antes da migração.","whyWrong":{"B":"Cost Explorer analisa gasto histórico (precisa já estar na AWS).","C":"Budgets é alerta sobre gasto.","D":"Trusted Advisor é recomendação de otimização."},"keyConcept":"Conceito: pré-migração → Pricing Calculator; pós-migração → Cost Explorer.","tutorSeeds":["Pode explicar com mais detalhe: Conceito: pré-migração → Pricing Calculator; pós-migração → Cost Explorer?","Quais cenários reais aplicam Conceito: pré-migração → Pricing Calculator; pós-migração → Cost Explorer?","Como AWS Pricing se compara com alternativas?"]}'::jsonb, 'Cloud Concepts', 'Cloud Concepts', 'medium', 'scenario', '["tco","pricing-calculator","migration"]'::jsonb, 'ai-draft', 'active', now(), now()),
    ('clf-c02-cc-060', 'aws-clf', 'Em uma análise CapEx vs OpEx, qual afirmação descreve corretamente a natureza do gasto com AWS?', '[{"id":"A","text":"AWS gera CapEx, pois o cliente compra a infra"},{"id":"B","text":"AWS gera OpEx, pois o cliente paga pelo uso variável sem ser dono do hardware"},{"id":"C","text":"AWS gera tanto CapEx quanto OpEx em partes iguais"},{"id":"D","text":"AWS não gera nem CapEx nem OpEx, é considerado ''investimento intangível''"}]'::jsonb, 'B', '{"summary":"Cliente AWS paga uso (OpEx) — não detém hardware.","whyCorrect":"Cliente AWS paga uso (OpEx) — não detém hardware. Exceção: compromissos longos (SP/RI) ainda são contabilizados como OpEx contratual.","whyWrong":{"A":"Cliente não compra hardware.","D":"Não há mix obrigatório. ''Investimento intangível'' é categoria contábil distinta (software interno), não AWS.","C":"AWS gera principalmente OpEx — não é misto 50/50 com CapEx. Cliente não compra hardware, não deprecia bens. Exceções marginais: compromissos longos como Savings Plans/Reserved Instances podem ser tratados contabilmente como leasing, mas mesmo assim não viram CapEx no sentido tradicional."},"keyConcept":"Conceito: nuvem viabiliza CapEx→OpEx, central nos 6 benefícios.","tutorSeeds":["Pode explicar com mais detalhe: Conceito: nuvem viabiliza CapEx→OpEx, central nos 6 benefícios?","Quais cenários reais aplicam Conceito: nuvem viabiliza CapEx→OpEx, central nos 6 benefícios?","Como AWS se compara com alternativas?"]}'::jsonb, 'Cloud Concepts', 'Cloud Concepts', 'easy', 'recall', '["tco","capex-opex"]'::jsonb, 'ai-draft', 'active', now(), now()),
    ('clf-c02-cc-061', 'aws-clf', 'Uma empresa monta análise de TCO comparando DC próprio (servidores totalmente amortizados em 5 anos, equipe enxuta, baixo crescimento) com AWS On-Demand. AWS sai mais caro. Qual conclusão é mais defensável?', '[{"id":"A","text":"AWS é sempre mais cara que DC próprio"},{"id":"B","text":"Para workloads ultra-estáveis com hardware amortizado, DC próprio pode ter TCO menor; AWS ganha em flexibilidade, agility, time-to-market e elimina risco de capacity planning errado"},{"id":"C","text":"TCO em AWS é sempre menor independente do cenário"},{"id":"D","text":"TCO não é métrica relevante para nuvem"}]'::jsonb, 'B', '{"summary":"Realidade: nem sempre AWS é mais barata em TCO direto — workloads estáticos com hardware amortizado podem custar menos on-prem.","whyCorrect":"Realidade: nem sempre AWS é mais barata em TCO direto — workloads estáticos com hardware amortizado podem custar menos on-prem. O valor de AWS combina TCO + benefícios não-financeiros (agility, elasticidade, redução de risco).","whyWrong":{"A":"Afirmações absolutas (sempre mais cara/mais barata) são falsas.","C":"TCO em AWS NÃO é sempre menor — esta é falsa promessa de marketing simplista. Workloads ultra-estáveis 24/7 com hardware totalmente amortizado em DC já existente podem custar menos on-prem. O valor de AWS está na combinação TCO + agility + redução de risco + time-to-market, não em garantia universal de menor preço.","D":"TCO É métrica altamente relevante para nuvem — CFOs usam TCO para justificar migrações, otimizações de cost. AWS publica calculadoras TCO oficialmente. Dizer que TCO é irrelevante é factualmente errado e contradiz prática estabelecida de cloud financial management (FinOps)."},"keyConcept":"Conceito: TCO é uma das dimensões, não a única.","tutorSeeds":["Pode explicar com mais detalhe: Conceito: TCO é uma das dimensões, não a única?","Quais cenários reais aplicam Conceito: TCO é uma das dimensões, não a única?","Como AWS se compara com alternativas?"]}'::jsonb, 'Cloud Concepts', 'Cloud Concepts', 'hard', 'best-practice', '["tco","finance","trade-off"]'::jsonb, 'ai-draft', 'active', now(), now()),
    ('clf-c02-cc-062', 'aws-clf', 'Quais categorias de custo on-prem o cliente DEIXA de pagar ao migrar 100% para AWS public cloud?', '[{"id":"A","text":"Hardware de servidor, energia, refrigeração, real estate do DC, equipe de operação física"},{"id":"B","text":"Salários de desenvolvedores que escrevem a aplicação"},{"id":"C","text":"Licenças de software de aplicação proprietária (ex: licença SAP do cliente)"},{"id":"D","text":"Custos de marketing do produto que roda na cloud"}]'::jsonb, 'A', '{"summary":"Categorias eliminadas: hardware, energia, refrigeração, espaço físico, equipe de DC (data center engineers, electricians).","whyCorrect":"Categorias eliminadas: hardware, energia, refrigeração, espaço físico, equipe de DC (data center engineers, electricians). Diluídas no preço AWS via economies of scale.","whyWrong":{"B":"escrevem a app. [extra: Devs continuam]","C":"Licenças de app proprietária do cliente continuam (BYOL ou nova licença).","D":"Marketing é outro centro de custo."},"keyConcept":"Conceito: AWS substitui infra física, não toda a stack de negócio.","tutorSeeds":["Pode explicar com mais detalhe: Conceito: AWS substitui infra física, não toda a stack de negócio?","Quais cenários reais aplicam Conceito: AWS substitui infra física, não toda a stack de negócio?","Como DC se compara com alternativas?"]}'::jsonb, 'Cloud Concepts', 'Cloud Concepts', 'medium', 'scenario', '["tco","cost-categories"]'::jsonb, 'ai-draft', 'active', now(), now()),
    ('clf-c02-cc-063', 'aws-clf', 'Um CFO comenta que prefere CapEx pois pode depreciar ao longo de anos e melhora o EBITDA. Qual é uma resposta tecnicamente correta sobre OpEx em AWS?', '[{"id":"A","text":"OpEx em AWS aparece como despesa operacional no período em que é consumido, melhorando alinhamento com a receita gerada e eliminando risco de obsolescência"},{"id":"B","text":"OpEx em AWS é sempre superior a CapEx em qualquer cenário"},{"id":"C","text":"AWS oferece opção de capitalizar gastos como CapEx por padrão"},{"id":"D","text":"EBITDA é irrelevante para análise de TCO em cloud"}]'::jsonb, 'A', '{"summary":"OpEx por consumo casa custo com receita (matching principle), evita CapEx sunk em hardware que pode ficar obsoleto, e libera capital para investimento no negócio.","whyCorrect":"OpEx por consumo casa custo com receita (matching principle), evita CapEx sunk em hardware que pode ficar obsoleto, e libera capital para investimento no negócio. Trade-off real: CapEx reduz despesa de período via depreciação; OpEx aumenta despesa imediata mas dá flexibilidade.","whyWrong":{"D":"EBITDA é métrica legítima.","B":"OpEx NÃO é sempre superior a CapEx em qualquer cenário — workloads ultra-estáveis com hardware amortizado podem ter CapEx menor. Trade-off depende de contexto (volatilidade de demanda, capital disponível, depreciação tributária). Afirmação absoluta é falsa.","C":"AWS NÃO oferece opção de capitalizar gastos como CapEx por padrão — o pricing é fundamentalmente OpEx (pay-per-use). Compromissos longos (SP/RI) podem ser tratados pelo contador como prepaid expense amortizada, mas isso é decisão contábil do cliente, não feature da AWS."},"keyConcept":"Conceito: decisão CapEx/OpEx é multi-fatorial.","tutorSeeds":["Pode explicar com mais detalhe: Conceito: decisão CapEx/OpEx é multi-fatorial?","Quais cenários reais aplicam Conceito: decisão CapEx/OpEx é multi-fatorial?"]}'::jsonb, 'Cloud Concepts', 'Cloud Concepts', 'hard', 'best-practice', '["tco","capex-opex","finance"]'::jsonb, 'ai-draft', 'active', now(), now()),
    ('clf-c02-cc-064', 'aws-clf', 'Qual elemento NÃO faz parte do cálculo de TCO típico para comparar AWS vs DC próprio?', '[{"id":"A","text":"Custo de energia e refrigeração do DC"},{"id":"B","text":"Custo de equipe dedicada à operação de hardware físico"},{"id":"C","text":"Receita gerada pela aplicação que roda na infra"},{"id":"D","text":"Custo de depreciação de hardware ao longo de 3-5 anos"}]'::jsonb, 'C', '{"summary":"TCO captura custos — não receitas.","whyCorrect":"TCO captura custos — não receitas. Receita gerada entra em análise de ROI/payback, não TCO.","whyWrong":{"A":"Energia, refrigeração, equipe de ops e depreciação são todos componentes válidos de TCO.","B":"Custo de equipe dedicada à operação de hardware físico É parte legítima de TCO de DC próprio — sysadmins, engenheiros de DC, operadores. Migrar para AWS elimina ou reduz drasticamente essa equipe. (Item correto: C — receita é elemento de ROI, não TCO).","D":"Depreciação de hardware ao longo de 3-5 anos É elemento legítimo de TCO de DC próprio — captura o custo amortizado do CapEx inicial. Em AWS, equivalente seria os compromissos de SP/RI. (Item correto: C — receita gerada pela aplicação não é custo, é benefício, fica em ROI)."},"keyConcept":"Conceito: TCO = só lado do custo; ROI = custo vs benefício.","tutorSeeds":["Pode explicar com mais detalhe: Conceito: TCO = só lado do custo; ROI = custo vs benefício?","Quais cenários reais aplicam Conceito: TCO = só lado do custo; ROI = custo vs benefício?","Como TCO se compara com alternativas?"]}'::jsonb, 'Cloud Concepts', 'Cloud Concepts', 'medium', 'recall', '["tco","calculation"]'::jsonb, 'ai-draft', 'active', now(), now()),
    ('clf-c02-cc-065', 'aws-clf', 'Um gerente de produto pergunta ''qual é a diferença entre AWS Region e Availability Zone?''. Qual é a resposta tecnicamente correta?', '[{"id":"A","text":"Region é uma localização geográfica com múltiplas AZs (datacenters fisicamente isolados); AZ é um conjunto de 1+ datacenters dentro da Region, com energia/rede/refrigeração independentes"},{"id":"B","text":"Region é o mesmo que AZ, apenas nome diferente"},{"id":"C","text":"Region é um datacenter físico único; AZ é uma sala dentro dele"},{"id":"D","text":"Region é um conceito lógico apenas; AZs não existem fisicamente"}]'::jsonb, 'A', '{"summary":"Region = área geográfica (ex: sa-east-1 em São Paulo, BR) com múltiplas AZs (≥3 tipicamente).","whyCorrect":"Region = área geográfica (ex: sa-east-1 em São Paulo, BR) com múltiplas AZs (≥3 tipicamente). AZ = um ou mais DCs fisicamente isolados (km de distância em alguns casos), com falhas independentes.","whyWrong":{"B":"Region ≠ AZ.","C":"Region não é um único DC.","D":"AZs SÃO entidades físicas concretas — cada AZ é um ou mais data centers reais com prédios, energia, rede, refrigeração e backups independentes. AWS publica esses fatos em white papers (mesmo sem revelar localizações exatas por segurança). Dizer que são ''lógicas'' contradiz a documentação oficial."},"keyConcept":"Conceito: hierarquia AWS = Region > AZ > DC.","tutorSeeds":["Pode explicar com mais detalhe: Conceito: hierarquia AWS = Region > AZ > DC?","Quais cenários reais aplicam Conceito: hierarquia AWS = Region > AZ > DC?","Como BR se compara com alternativas?"]}'::jsonb, 'Cloud Concepts', 'Cloud Concepts', 'easy', 'recall', '["global-infra","region","az"]'::jsonb, 'ai-draft', 'active', now(), now()),
    ('clf-c02-cc-066', 'aws-clf', 'Uma equipe quer reduzir latência de assets estáticos (imagens, CSS, JS) para usuários globais sem mover origem de us-east-1. Qual componente da Global Infrastructure atende melhor?', '[{"id":"A","text":"Edge Locations (via Amazon CloudFront)"},{"id":"B","text":"Availability Zones adicionais"},{"id":"C","text":"AWS Outposts"},{"id":"D","text":"AWS Wavelength"}]'::jsonb, 'A', '{"summary":"Edge Locations (~600+ globalmente) servem cache de CloudFront perto do usuário — ideal para conteúdo estático cacheável.","whyCorrect":"Edge Locations (~600+ globalmente) servem cache de CloudFront perto do usuário — ideal para conteúdo estático cacheável. Reduz latência sem replicar origem.","whyWrong":{"C":"Outposts é AWS no DC do cliente.","D":"Wavelength é 5G edge para apps móveis ultra-low latency.","B":"AZs adicionais reduzem latência apenas marginalmente (intra-Region) — não resolvem o problema de usuários em outros continentes alcançando us-east-1. Multi-AZ é HA dentro de uma Region; latência global exige distribuição via Edge Locations (CDN) ou Regions múltiplas."},"keyConcept":"Conceito: hierarquia = Region > AZ > Local Zone > Edge Location > Wavelength.","tutorSeeds":["Pode explicar com mais detalhe: Conceito: hierarquia = Region > AZ > Local Zone > Edge Location > Wavelength?","Quais cenários reais aplicam Conceito: hierarquia = Region > AZ > Local Zone > Edge Location > Wavelength?"]}'::jsonb, 'Cloud Concepts', 'Cloud Concepts', 'easy', 'scenario', '["global-infra","edge","cloudfront"]'::jsonb, 'ai-draft', 'active', now(), now()),
    ('clf-c02-cc-067', 'aws-clf', 'Uma empresa de games quer servir compute com latência de um dígito de milissegundos para jogadores em Los Angeles, mas a Region mais próxima (us-west-2) está em Oregon. Qual componente da Global Infrastructure resolve?', '[{"id":"A","text":"Edge Location para cache estático"},{"id":"B","text":"AWS Local Zones (ex: Los Angeles Local Zone)"},{"id":"C","text":"Mais AZs em us-west-2"},{"id":"D","text":"AWS Storage Gateway"}]'::jsonb, 'B', '{"summary":"Local Zones colocam EC2/EBS/ECS/ELB/RDS perto de grandes centros metropolitanos não cobertos por uma Region (LA, Miami, Denver etc) — single-digit-ms para usuários locais.","whyCorrect":"Local Zones colocam EC2/EBS/ECS/ELB/RDS perto de grandes centros metropolitanos não cobertos por uma Region (LA, Miami, Denver etc) — single-digit-ms para usuários locais.","whyWrong":{"A":"Edge Location é cache estático, não compute geral.","D":"Storage Gateway é integração on-prem.","C":"Adicionar AZs em us-west-2 mantém o compute em Oregon — a latência de Oregon para LA continua sendo a mesma (cerca de 20-25ms RTT), não single-digit-ms. Para latência metro, é necessário ter compute fisicamente no metro de LA, que é o que Local Zones entregam."},"keyConcept":"Conceito: Local Zones = extensões de Region para latência metro.","tutorSeeds":["Pode explicar com mais detalhe: Conceito: Local Zones = extensões de Region para latência metro?","Quais cenários reais aplicam Conceito: Local Zones = extensões de Region para latência metro?","Como EC2 se compara com alternativas?"]}'::jsonb, 'Cloud Concepts', 'Cloud Concepts', 'medium', 'scenario', '["global-infra","local-zones"]'::jsonb, 'ai-draft', 'active', now(), now()),
    ('clf-c02-cc-068', 'aws-clf', 'Uma aplicação de AR para mobile precisa rodar inference de ML com latência sub-10ms diretamente na rede 5G da operadora, sem trafegar pela internet pública. Qual componente AWS atende?', '[{"id":"A","text":"AWS Wavelength"},{"id":"B","text":"Local Zone"},{"id":"C","text":"Edge Location"},{"id":"D","text":"Outposts"}]'::jsonb, 'A', '{"summary":"Wavelength roda EC2/EBS/EKS dentro de data centers de operadoras 5G (Verizon, KDDI, Vodafone) — tráfego do dispositivo nunca sai da rede 5G, latência sub-10ms para apps mobile ultra-sensíveis.","whyCorrect":"Wavelength roda EC2/EBS/EKS dentro de data centers de operadoras 5G (Verizon, KDDI, Vodafone) — tráfego do dispositivo nunca sai da rede 5G, latência sub-10ms para apps mobile ultra-sensíveis.","whyWrong":{"B":"Local Zone é metro mas via internet.","C":"Edge Location é cache estático.","D":"Outposts é AWS no DC do cliente."},"keyConcept":"Conceito: Wavelength = AWS no edge 5G.","tutorSeeds":["Pode explicar com mais detalhe: Conceito: Wavelength = AWS no edge 5G?","Quais cenários reais aplicam Conceito: Wavelength = AWS no edge 5G?","Como EC2 se compara com alternativas?"]}'::jsonb, 'Cloud Concepts', 'Cloud Concepts', 'medium', 'scenario', '["global-infra","wavelength","5g"]'::jsonb, 'ai-draft', 'active', now(), now()),
    ('clf-c02-cc-069', 'aws-clf', 'Qual quantidade típica MÍNIMA de Availability Zones existe em uma AWS Region nova lançada nos últimos anos?', '[{"id":"A","text":"1 AZ"},{"id":"B","text":"3 AZs"},{"id":"C","text":"10 AZs"},{"id":"D","text":"Varia entre 1 e 2 AZs"}]'::jsonb, 'B', '{"summary":"AWS lança Regions novas com mínimo de 3 AZs para garantir quorum em sistemas distribuídos (RDS Multi-AZ, Aurora, DynamoDB global tables) e resiliência.","whyCorrect":"AWS lança Regions novas com mínimo de 3 AZs para garantir quorum em sistemas distribuídos (RDS Multi-AZ, Aurora, DynamoDB global tables) e resiliência. Algumas regions têm 4-6 AZs.","whyWrong":{"A":"Regions AWS modernas exigem MÍNIMO de 3 AZs — não 1. Com 1 AZ não há resiliência multi-AZ nativa nem quorum para sistemas distribuídos (RDS Multi-AZ, Aurora). Algumas Regions antigas (pré-2018) lançaram com 2 AZs, mas o padrão atual é 3+.","C":"10 AZs não é mínimo nem típico — é número que apenas Regions muito grandes podem ter (us-east-1 tem 6, us-west-2 tem 4). O MÍNIMO para nova Region é 3 AZs para garantir quorum e Multi-AZ HA.","D":"A política atual da AWS é mínimo de 3 AZs para Regions novas — não varia entre 1 e 2. Regions antigas (pré-2018) podem ter 2 AZs por motivos históricos, mas qualquer lançamento moderno tem 3+."},"keyConcept":"Conceito: 3+ AZs é padrão moderno.","tutorSeeds":["Pode explicar com mais detalhe: Conceito: 3+ AZs é padrão moderno?","Quais cenários reais aplicam Conceito: 3+ AZs é padrão moderno?","Como AWS se compara com alternativas?"]}'::jsonb, 'Cloud Concepts', 'Cloud Concepts', 'medium', 'recall', '["global-infra","az","regions"]'::jsonb, 'ai-draft', 'active', now(), now()),
    ('clf-c02-cc-070', 'aws-clf', 'Quais critérios devem orientar a escolha de uma AWS Region para um workload?', '[{"id":"A","text":"Latência aos usuários, compliance/soberania de dados, disponibilidade de serviços específicos, preço, sustentabilidade"},{"id":"B","text":"Apenas o preço mais baixo"},{"id":"C","text":"Sempre a Region mais antiga (us-east-1) por estabilidade"},{"id":"D","text":"Sempre a Region geograficamente mais próxima ao escritório"}]'::jsonb, 'A', '{"summary":"Decisão multi-fatorial: (1) latência aos usuários reais, (2) compliance/soberania (GDPR, LGPD), (3) services disponibilizados na Region (nem todos lançam simultaneamente), (4) preço (varia por Region), (5) mix de energia renovável.","whyCorrect":"Decisão multi-fatorial: (1) latência aos usuários reais, (2) compliance/soberania (GDPR, LGPD), (3) services disponibilizados na Region (nem todos lançam simultaneamente), (4) preço (varia por Region), (5) mix de energia renovável.","whyWrong":{"C":"Single-factor decisions falham. us-east-1 é maior mas tem histórico de outages grandes.","D":"Proximidade ao escritório é irrelevante","B":"Escolher Region apenas pelo preço mais baixo ignora fatores críticos: latência ao usuário (UX), compliance/soberania (GDPR pode exigir EU), disponibilidade de serviços (nem todos lançam em todas as Regions simultaneamente), sustentabilidade. Pricing isolado é critério incompleto e potencialmente ilegal (LGPD)."},"keyConcept":"Conceito: matriz de decisão.","tutorSeeds":["Pode explicar com mais detalhe: Conceito: matriz de decisão?","Quais cenários reais aplicam Conceito: matriz de decisão?","Como GDPR se compara com alternativas?"]}'::jsonb, 'Cloud Concepts', 'Cloud Concepts', 'medium', 'best-practice', '["global-infra","region-selection"]'::jsonb, 'ai-draft', 'active', now(), now()),
    ('clf-c02-cc-071', 'aws-clf', 'Uma empresa configura RDS Multi-AZ. Qual é o benefício PRINCIPAL desse setup em termos de Global Infrastructure?', '[{"id":"A","text":"Reduz latência para usuários em outros continentes"},{"id":"B","text":"Failover automático para uma standby replica em outra AZ caso a AZ primária falhe"},{"id":"C","text":"Reduz custo do RDS pela metade"},{"id":"D","text":"Permite escalar leitura ilimitadamente"}]'::jsonb, 'B', '{"summary":"Multi-AZ = standby síncrona em AZ diferente; failover automático em ~60-120s se primária cair.","whyCorrect":"Multi-AZ = standby síncrona em AZ diferente; failover automático em ~60-120s se primária cair. Foco é alta disponibilidade dentro de uma Region.","whyWrong":{"A":"Latência cross-continente exige cross-Region (Read Replicas globais ou Aurora Global).","C":"Custo dobra (não cai).","D":"Multi-AZ no RDS NÃO escala leitura — a standby é síncrona e NÃO atende reads (exceto em Aurora). Para escalar leitura, o construto é Read Replicas (assíncronas, podem ser em mesma Region ou cross-Region). Multi-AZ foca exclusivamente em HA via failover, não em scale-out."},"keyConcept":"Conceito: Multi-AZ = HA intra-Region; cross-Region = DR/disaster recovery.","tutorSeeds":["Pode explicar com mais detalhe: Conceito: Multi-AZ = HA intra-Region; cross-Region = DR/disaster recovery?","Quais cenários reais aplicam Conceito: Multi-AZ = HA intra-Region; cross-Region = DR/disaster recovery?","Como AZ se compara com alternativas?"]}'::jsonb, 'Cloud Concepts', 'Cloud Concepts', 'medium', 'best-practice', '["global-infra","multi-az","rds"]'::jsonb, 'ai-draft', 'active', now(), now()),
    ('clf-c02-cc-072', 'aws-clf', 'Uma equipe de mídia precisa que vídeos sejam servidos com baixa latência globalmente, MAS o origin S3 fica em us-east-1. Qual padrão de Global Infrastructure resolve?', '[{"id":"A","text":"Amazon CloudFront com Edge Locations em frente do origin S3"},{"id":"B","text":"Replicar o S3 manualmente em todas as 30+ Regions"},{"id":"C","text":"Usar AWS Outposts em cada país"},{"id":"D","text":"Mudar para AWS Wavelength"}]'::jsonb, 'A', '{"summary":"CloudFront cacheia conteúdo em Edge Locations próximas dos usuários — primeira request pega de us-east-1, subsequentes da edge.","whyCorrect":"CloudFront cacheia conteúdo em Edge Locations próximas dos usuários — primeira request pega de us-east-1, subsequentes da edge. Reduz latência global sem replicar manualmente.","whyWrong":{"B":"Replicar S3 em 30+ Regions é caro/complexo [extra: cross-Region replication é para DR, não CDN.]","C":"Outposts é DC do cliente.","D":"Wavelength é 5G edge."},"keyConcept":"Conceito: estático global → CloudFront.","tutorSeeds":["Pode explicar com mais detalhe: Conceito: estático global → CloudFront?","Quais cenários reais aplicam Conceito: estático global → CloudFront?"]}'::jsonb, 'Cloud Concepts', 'Cloud Concepts', 'easy', 'best-practice', '["global-infra","cloudfront","edge"]'::jsonb, 'ai-draft', 'active', now(), now()),
    ('clf-c02-cc-073', 'aws-clf', 'Uma empresa de banco precisa que dados de clientes brasileiros NUNCA saiam do território nacional por exigência da LGPD/BACEN. Qual ação de Global Infrastructure atende esse requisito?', '[{"id":"A","text":"Deploy em sa-east-1 (São Paulo) e configurar IAM/policies para impedir replicação cross-region"},{"id":"B","text":"Deploy em us-east-1 e confiar na criptografia"},{"id":"C","text":"Deploy em qualquer Region e usar CloudFront"},{"id":"D","text":"Soberania de dados não é configurável na AWS"}]'::jsonb, 'A', '{"summary":"Region sa-east-1 fica fisicamente no Brasil.","whyCorrect":"Region sa-east-1 fica fisicamente no Brasil. Combinar com SCPs (Organizations) e bucket policies que negam cross-region replication garante que dados permaneçam locais.","whyWrong":{"B":"us-east-1 é EUA criptografia não muda jurisdição.","C":"CloudFront tem edges no exterior.","D":"Soberania É configurável via Region selection + guardrails."},"keyConcept":"Conceito: Region selection é o controle primário de soberania.","tutorSeeds":["Pode explicar com mais detalhe: Conceito: Region selection é o controle primário de soberania?","Quais cenários reais aplicam Conceito: Region selection é o controle primário de soberania?","Como SCPs se compara com alternativas?"]}'::jsonb, 'Cloud Concepts', 'Cloud Concepts', 'medium', 'scenario', '["global-infra","data-sovereignty","lgpd"]'::jsonb, 'ai-draft', 'active', now(), now()),
    ('clf-c02-cc-074', 'aws-clf', 'Qual diferença existe entre ''Edge Location'' e ''Regional Edge Cache'' no CloudFront?', '[{"id":"A","text":"São o mesmo conceito, nomes diferentes"},{"id":"B","text":"Edge Locations são o primeiro tier de cache próximo do usuário; Regional Edge Caches são uma camada intermediária maior entre Edge Locations e o origin, melhorando hit ratio para conteúdo menos popular"},{"id":"C","text":"Regional Edge Cache só existe em us-east-1"},{"id":"D","text":"Edge Locations só servem conteúdo dinâmico"}]'::jsonb, 'B', '{"summary":"CloudFront tem 2 tiers: ~600+ Edge Locations + ~13 Regional Edge Caches.","whyCorrect":"CloudFront tem 2 tiers: ~600+ Edge Locations + ~13 Regional Edge Caches. Quando miss na Edge, vai para Regional Edge Cache (maior, retém objetos mais tempo); só vai para origin se miss nos dois. Aumenta hit ratio e reduz egress.","whyWrong":{"D":"Edge Locations servem dinâmico e estático.","A":"Edge Locations e Regional Edge Caches são CONCEITOS DISTINTOS com papéis diferentes no CloudFront — não são sinônimos. Edge Locations (~600+) são o tier mais próximo do usuário; Regional Edge Caches (~13) são o tier intermediário com cache maior e duração mais longa.","C":"Regional Edge Caches estão distribuídos globalmente em ~13 localizações estratégicas (não apenas em us-east-1). Eles cobrem regiões geográficas amplas servindo múltiplas Edge Locations. Concentrar em us-east-1 derrotaria o propósito de reduzir latência global."},"keyConcept":"Conceito: 2-tier cache hierarchy.","tutorSeeds":["Pode explicar com mais detalhe: Conceito: 2-tier cache hierarchy?","Quais cenários reais aplicam Conceito: 2-tier cache hierarchy?"]}'::jsonb, 'Cloud Concepts', 'Cloud Concepts', 'hard', 'recall', '["global-infra","cloudfront","edge-cache"]'::jsonb, 'ai-draft', 'active', now(), now()),
    ('clf-c02-cc-075', 'aws-clf', 'Uma equipe precisa de DR cross-region para um workload crítico em us-east-1. Qual padrão Global Infrastructure é apropriado?', '[{"id":"A","text":"Replicação para us-west-2 (Region geograficamente isolada, falhas independentes)"},{"id":"B","text":"Adicionar mais AZs em us-east-1"},{"id":"C","text":"Habilitar CloudFront na frente da app"},{"id":"D","text":"Comprar mais Reserved Instances"}]'::jsonb, 'A', '{"summary":"DR cross-region protege contra falha de uma Region inteira (eventos raros mas catastróficos: us-east-1 já teve outages multi-AZ).","whyCorrect":"DR cross-region protege contra falha de uma Region inteira (eventos raros mas catastróficos: us-east-1 já teve outages multi-AZ). Patterns: Pilot Light, Warm Standby, Multi-Region Active-Active.","whyWrong":{"B":"Mais AZs em us-east-1 não protege contra falha de Region.","C":"CloudFront não é DR.","D":"Reserved Instances são compromisso de pricing — não fornecem disaster recovery. RIs em us-east-1 continuam afetadas se us-east-1 cair. DR cross-region exige replicação de dados, infra e capacidade em outra Region, ortogonal a pricing model."},"keyConcept":"Conceito: HA = multi-AZ; DR = multi-Region.","tutorSeeds":["Pode explicar com mais detalhe: Conceito: HA = multi-AZ; DR = multi-Region?","Quais cenários reais aplicam Conceito: HA = multi-AZ; DR = multi-Region?","Como DR se compara com alternativas?"]}'::jsonb, 'Cloud Concepts', 'Cloud Concepts', 'medium', 'best-practice', '["global-infra","dr","cross-region"]'::jsonb, 'ai-draft', 'active', now(), now()),
    ('clf-c02-cc-076', 'aws-clf', 'Após uma migração, a equipe relata que usuários em São Paulo veem latência de 200ms em uma app rodando em us-east-1. Qual ajuste de Global Infrastructure resolve mais diretamente?', '[{"id":"A","text":"Replicar a app em sa-east-1 (São Paulo) ou usar CloudFront/Global Accelerator"},{"id":"B","text":"Aumentar o tamanho da instância EC2"},{"id":"C","text":"Habilitar EBS encryption"},{"id":"D","text":"Adicionar uma read replica RDS na mesma Region us-east-1"}]'::jsonb, 'A', '{"summary":"Latência geográfica é problema físico (velocidade da luz).","whyCorrect":"Latência geográfica é problema físico (velocidade da luz). Solução: aproximar compute do usuário via Region local (sa-east-1) ou edge (CloudFront para estático, Global Accelerator para dinâmico).","whyWrong":{"B":"Instância maior não reduz RTT cross-continent.","C":"Encryption adiciona ~0ms.","D":"Replica na mesma Region não muda latência para SP."},"keyConcept":"Conceito: latência geográfica → arquitetura geográfica.","tutorSeeds":["Pode explicar com mais detalhe: Conceito: latência geográfica → arquitetura geográfica?","Quais cenários reais aplicam Conceito: latência geográfica → arquitetura geográfica?"]}'::jsonb, 'Cloud Concepts', 'Cloud Concepts', 'medium', 'troubleshoot', '["global-infra","latency","regions"]'::jsonb, 'ai-draft', 'active', now(), now()),
    ('clf-c02-cc-077', 'aws-clf', 'Qual afirmação é VERDADEIRA sobre custos de transferência de dados entre componentes da Global Infrastructure?', '[{"id":"A","text":"Tráfego entre AZs dentro de uma Region é gratuito"},{"id":"B","text":"Tráfego entre AZs dentro de uma Region é cobrado (geralmente $0.01/GB cada direção); cross-Region e egress para internet também são cobrados"},{"id":"C","text":"Toda transferência de dados na AWS é gratuita"},{"id":"D","text":"Apenas tráfego entrando na AWS (ingress) é cobrado"}]'::jsonb, 'B', '{"summary":"Modelo geral: ingress (entrada) gratuito; egress (saída para internet) cobrado; entre AZs cobrado (~$0.01/GB cada lado, ou seja $0.02 round-trip); cross-Region cobrado; mesma AZ via IP privado gratuito; CloudFront tem tarifa própria.","whyCorrect":"Modelo geral: ingress (entrada) gratuito; egress (saída para internet) cobrado; entre AZs cobrado (~$0.01/GB cada lado, ou seja $0.02 round-trip); cross-Region cobrado; mesma AZ via IP privado gratuito; CloudFront tem tarifa própria.","whyWrong":{"A":"Inter-AZ NÃO é gratuito (erro comum). Nem tudo é gratuito.","D":"Egress é o cobrado, não ingress.","C":"Nem toda transferência é gratuita — esta opção contradiz a realidade do pricing AWS. AWS cobra: egress para internet, cross-AZ, cross-Region, NAT Gateway traffic. Apenas alguns padrões são free (ingress, traffic dentro da mesma AZ via IP privado, alguns endpoints específicos). É um vetor frequente de cost surprise."},"keyConcept":"Conceito crítico para arquitetura: minimizar cross-AZ chatty traffic.","tutorSeeds":["Pode explicar com mais detalhe: Conceito crítico para arquitetura: minimizar cross-AZ chatty traffic?","Quais cenários reais aplicam Conceito crítico para arquitetura: minimizar cross-AZ chatty traffic?","Como AZs se compara com alternativas?"]}'::jsonb, 'Cloud Concepts', 'Cloud Concepts', 'hard', 'recall', '["global-infra","data-transfer","cost"]'::jsonb, 'ai-draft', 'active', now(), now()),
    ('clf-c02-cc-078', 'aws-clf', 'Após implementar uma arquitetura multi-Region active-active, a equipe nota custos altos de cross-Region replication. Qual princípio de Cloud Concepts ajuda a justificar (ou repensar) esse investimento?', '[{"id":"A","text":"Cost optimization é o único pilar que importa"},{"id":"B","text":"Reliability vs Cost trade-off — multi-Region active-active aumenta resiliência ao custo de complexidade e data transfer; só vale se SLO justifica"},{"id":"C","text":"Multi-Region active-active é sempre obrigatório"},{"id":"D","text":"Cross-Region replication é gratuita"}]'::jsonb, 'B', '{"summary":"Multi-Region active-active vale para workloads tier-0 com SLO de 99.99%+, payments globais, etc.","whyCorrect":"Multi-Region active-active vale para workloads tier-0 com SLO de 99.99%+, payments globais, etc. Para workloads tier-2/3, multi-AZ + backup cross-Region já basta. Decisão é trade-off Reliability × Cost × Complexity.","whyWrong":{"A":"Cost não é o único pilar.","C":"Active-active não é universal.","D":"Replication cobra."},"keyConcept":"Conceito: Well-Architected reconhece trade-offs entre pilares.","tutorSeeds":["Pode explicar com mais detalhe: Conceito: Well-Architected reconhece trade-offs entre pilares?","Quais cenários reais aplicam Conceito: Well-Architected reconhece trade-offs entre pilares?","Como SLO se compara com alternativas?"]}'::jsonb, 'Cloud Concepts', 'Cloud Concepts', 'hard', 'troubleshoot', '["global-infra","multi-region","trade-off"]'::jsonb, 'ai-draft', 'active', now(), now()),
    ('clf-c02-cc-079', 'aws-clf', 'Uma empresa global tem usuários em 5 continentes e quer reduzir latência de uma API DINÂMICA (não cacheável) hospedada em us-east-1, sem replicar a app. Qual serviço Global Infrastructure resolve?', '[{"id":"A","text":"Amazon CloudFront com TTL=0"},{"id":"B","text":"AWS Global Accelerator (IPs anycast que entram na rede AWS no edge mais próximo e fazem path interno otimizado)"},{"id":"C","text":"Adicionar AZs em us-east-1"},{"id":"D","text":"AWS Outposts em cada continente"}]'::jsonb, 'B', '{"summary":"Global Accelerator dá IPs estáticos anycast nos Edge Locations da AWS.","whyCorrect":"Global Accelerator dá IPs estáticos anycast nos Edge Locations da AWS. Tráfego do usuário entra na rede AWS o mais cedo possível e viaja via backbone otimizado (não internet pública) até us-east-1. Ideal para tráfego dinâmico.","whyWrong":{"A":"CloudFront com TTL=0 não cacheia (overhead sem benefício).","C":"Mais AZs em us-east-1 não ajuda usuários remotos.","D":"Outposts é DC do cliente."},"keyConcept":"Conceito: estático → CloudFront; dinâmico → Global Accelerator.","tutorSeeds":["Pode explicar com mais detalhe: Conceito: estático → CloudFront; dinâmico → Global Accelerator?","Quais cenários reais aplicam Conceito: estático → CloudFront; dinâmico → Global Accelerator?","Como IPs se compara com alternativas?"]}'::jsonb, 'Cloud Concepts', 'Cloud Concepts', 'hard', 'scenario', '["global-infra","global-accelerator","dynamic"]'::jsonb, 'ai-draft', 'active', now(), now()),
    ('clf-c02-cc-080', 'aws-clf', 'Uma equipe quer aplicar o princípio do Well-Architected ''design for failure'' considerando falhas em níveis múltiplos da Global Infrastructure. Qual ordem de mitigação é correta do menor ao maior blast radius?', '[{"id":"A","text":"Failure de instância (Auto Scaling) → Failure de AZ (Multi-AZ) → Failure de Region (Multi-Region DR)"},{"id":"B","text":"Failure de Region → Failure de AZ → Failure de instância"},{"id":"C","text":"Apenas considerar failure de Region é suficiente"},{"id":"D","text":"Falhas em AWS são impossíveis, não precisa planejar"}]'::jsonb, 'A', '{"summary":"Ordem natural: instância (mais comum, mitigada por ASG + health checks) → AZ (rara mas acontece, mitigada por Multi-AZ) → Region (eventos raros catastróficos, mitigada por Multi-Region DR).","whyCorrect":"Ordem natural: instância (mais comum, mitigada por ASG + health checks) → AZ (rara mas acontece, mitigada por Multi-AZ) → Region (eventos raros catastróficos, mitigada por Multi-Region DR). Cada camada tem custo crescente.","whyWrong":{"C":"Considerar só Region ignora falhas mais frequentes.","D":"AWS tem falhas (us-east-1 outages históricas)","B":"A ordem está invertida — Region failure (raro, catastrófico, máximo blast radius) deve ser endereçado por ÚLTIMO no design, depois de instance e AZ failures. Começar por Region é over-engineering para problemas mais comuns. Defesa em profundidade trata o menor blast radius primeiro (instância) e escala para fora."},"keyConcept":"Conceito: defesa em profundidade na Global Infrastructure.","tutorSeeds":["Pode explicar com mais detalhe: Conceito: defesa em profundidade na Global Infrastructure?","Quais cenários reais aplicam Conceito: defesa em profundidade na Global Infrastructure?","Como ASG se compara com alternativas?"]}'::jsonb, 'Cloud Concepts', 'Cloud Concepts', 'hard', 'best-practice', '["global-infra","reliability","blast-radius"]'::jsonb, 'ai-draft', 'active', now(), now()),
    ('clf-c02-cc-v2-001', 'aws-clf', 'Uma empresa quer reduzir a pegada de carbono dos seus workloads AWS. Após uma análise, decidem mover jobs batch que rodam de madrugada para a região eu-west-1 (Irlanda, alta % de energia renovável) em vez de manter em us-east-1. Qual pilar do Well-Architected Framework guia essa decisão?', '[{"id":"A","text":"Cost Optimization"},{"id":"B","text":"Sustainability"},{"id":"C","text":"Operational Excellence"},{"id":"D","text":"Performance Efficiency"}]'::jsonb, 'B', '{"summary":"O pilar Sustainability (adicionado em 2021) orienta escolhas que minimizem impacto ambiental, incluindo Region Selection por matriz energética.","whyCorrect":"Sustainability tem como design principle ''Select Regions based on both business needs and sustainability goals''. Regiões com maior fração de energia renovável (eu-west-1, eu-north-1, ca-central-1) reduzem a pegada de carbono do workload. É o único pilar que trata explicitamente de impacto ambiental.","whyWrong":{"A":"Cost Optimization seria correto se o critério principal fosse preço por hora — eu-west-1 normalmente é mais cara que us-east-1, então ''mover por custo'' contradiz a premissa.","C":"Operational Excellence trataria de runbooks, observabilidade e processos. Move workload por questão operacional (proximidade do time de operação, por exemplo) é OE, não a premissa aqui.","D":"Performance Efficiency justificaria mudança de região para reduzir latência ao usuário final ou para acesso a tipos de instância específicos — não é o motivo descrito."},"keyConcept":"Well-Architected — Pilar Sustainability (6º pilar, 2021)","compareWith":["Cost Optimization vs Sustainability","Performance Efficiency"],"realWorldContext":"Empresas com metas ESG/Net Zero (ex: compromisso de carbono neutro até 2030) usam esse critério ao escolher região AWS.","commonMistakes":"Confundir ''região mais barata'' (Cost) com ''região mais verde'' (Sustainability) — nem sempre coincidem.","tutorSeeds":["Quais regiões AWS têm maior fração de energia renovável publicada?","Como o Customer Carbon Footprint Tool ajuda a medir essa pegada?"]}'::jsonb, 'Cloud Concepts', 'Cloud Concepts', 'medium', 'scenario', '["well-architected","sustainability","region-selection"]'::jsonb, 'ai-draft', 'active', now(), now()),
    ('clf-c02-cc-v2-002', 'aws-clf', 'No pilar Sustainability, qual métrica é mais alinhada ao design principle ''maximize utilization'' para reduzir impacto ambiental?', '[{"id":"A","text":"Taxa média de utilização de CPU acima de 60% nas instâncias EC2"},{"id":"B","text":"Tempo médio de resposta em ms das APIs"},{"id":"C","text":"Disponibilidade mensal em % (SLA)"},{"id":"D","text":"Custo por transação em USD"}]'::jsonb, 'A', '{"summary":"Utilização alta de CPU/memória significa menos hardware ocioso por unidade de trabalho — é o KPI direto de ''maximize utilization''.","whyCorrect":"Sustainability define explicitamente: ''right size each workload to maximize utilization''. Instâncias com 10% de CPU desperdiçam energia para o mesmo trabalho; consolidar para 60-80% reduz a quantidade de hardware ativo proporcional ao output, diminuindo emissões.","whyWrong":{"B":"Latência é métrica do pilar Performance Efficiency, não Sustainability. Reduzir latência pode até aumentar consumo (mais réplicas, mais cache).","C":"Disponibilidade é métrica do pilar Reliability (SLA, RTO, RPO). Aumentar disponibilidade frequentemente aumenta footprint (Multi-AZ, Multi-Region).","D":"Custo por transação é métrica de Cost Optimization. Correlacionado mas não idêntico — workload pode ser barato e ainda ineficiente energeticamente (instância subutilizada com Savings Plan)."},"keyConcept":"Sustainability — proxy metrics: utilization, transactions per kWh","compareWith":["Performance Efficiency (latência)","Cost Optimization (USD/transação)"],"realWorldContext":"Customer Carbon Footprint Tool reporta kgCO2eq por serviço; combinado com utilização permite calcular kgCO2 por transação."}'::jsonb, 'Cloud Concepts', 'Cloud Concepts', 'medium', 'best-practice', '["well-architected","sustainability","utilization"]'::jsonb, 'ai-draft', 'active', now(), now()),
    ('clf-c02-cc-v2-003', 'aws-clf', 'Uma equipe implementa retrospectivas mensais, post-mortems sem culpa após incidentes e atualiza runbooks automaticamente quando descobre um novo modo de falha. Esse comportamento é a essência de qual design principle do pilar Operational Excellence?', '[{"id":"A","text":"Perform operations as code"},{"id":"B","text":"Make frequent, small, reversible changes"},{"id":"C","text":"Learn from all operational failures"},{"id":"D","text":"Anticipate failure"}]'::jsonb, 'C', '{"summary":"''Learn from all operational failures'' é o feedback loop que post-mortems e atualização de runbooks materializam.","whyCorrect":"Operational Excellence lista 5 design principles; ''Learn from all operational failures'' significa compartilhar aprendizados entre times, transformar incidente em melhoria de processo/automação. Post-mortem blameless + runbook update é o padrão canônico desse princípio.","whyWrong":{"A":"''Perform operations as code'' significa IaC (CloudFormation/CDK) e runbooks executáveis — comportamento relacionado mas o cenário descreve aprendizado, não codificação.","B":"''Make frequent, small, reversible changes'' é sobre deploy contínuo, feature flags, blue/green — não é o foco do cenário (que é retrospectiva e post-mortem).","D":"''Anticipate failure'' descreve game days e chaos engineering — proativo, enquanto o cenário descreve reativo (aprender após falha já ocorrida)."},"keyConcept":"Operational Excellence — design principles (5)","compareWith":["Anticipate failure (proativo)","Learn from failures (reativo)"],"realWorldContext":"Empresas como Etsy, Netflix popularizaram blameless post-mortems como ritual de OE.","tutorSeeds":["Qual a diferença entre game day e chaos engineering?","Como medir maturidade de OE numa equipe?"]}'::jsonb, 'Cloud Concepts', 'Cloud Concepts', 'easy', 'scenario', '["well-architected","operational-excellence","feedback-loops"]'::jsonb, 'ai-draft', 'active', now(), now()),
    ('clf-c02-cc-v2-004', 'aws-clf', 'Uma aplicação crítica precisa sobreviver à perda de um data center inteiro com RTO < 1 minuto. A equipe debate entre Multi-AZ e Multi-Region. Considerando o pilar Reliability, qual afirmação é a mais precisa para escolher Multi-AZ em vez de Multi-Region?', '[{"id":"A","text":"Multi-AZ protege contra falhas de hardware/AZ inteira com latência sub-ms entre AZs; Multi-Region protege contra falha de Região inteira mas adiciona latência inter-region (dezenas a centenas de ms)"},{"id":"B","text":"Multi-AZ é gratuito; Multi-Region cobra por replicação"},{"id":"C","text":"Multi-AZ replica entre Local Zones; Multi-Region replica entre Availability Zones"},{"id":"D","text":"Multi-AZ exige Direct Connect; Multi-Region não"}]'::jsonb, 'A', '{"summary":"Multi-AZ resolve falhas de AZ com latência sub-ms; Multi-Region resolve falha regional mas paga preço em latência e complexidade.","whyCorrect":"AZs dentro de uma região são interconectadas por fibra dedicada da AWS com latência sub-ms (single-digit ms no pior caso), o que viabiliza replicação síncrona (ex: RDS Multi-AZ). Multi-Region cruza fibra de longa distância (10-200ms entre us-east-1 e sa-east-1, por exemplo), inviabilizando replicação síncrona forte e exigindo arquitetura active-passive ou eventual consistency.","whyWrong":{"B":"Multi-AZ tem custo (instância stand-by, storage replicado); não é gratuito. A diferença real é latência, não preço binário.","C":"Invertido e errado: Multi-AZ replica entre AZs (Availability Zones); Local Zones são extensões regionais para latência ultra-baixa em metrópoles, não unidades de DR.","D":"Direct Connect é serviço de conectividade on-prem→AWS, nada a ver com Multi-AZ vs Multi-Region."},"keyConcept":"Reliability — failure domains (AZ vs Region)","compareWith":["RDS Multi-AZ (síncrono)","RDS Read Replica cross-region (async)"],"realWorldContext":"Bancos brasileiros usam Multi-AZ em sa-east-1 para core e Multi-Region (us-east-1) para DR de catástrofe regional.","tutorSeeds":["Por que replicação síncrona inter-region é praticamente inviável?","Quando Multi-AZ não é suficiente?"]}'::jsonb, 'Cloud Concepts', 'Cloud Concepts', 'medium', 'scenario', '["well-architected","reliability","multi-az","multi-region"]'::jsonb, 'ai-draft', 'active', now(), now()),
    ('clf-c02-cc-v2-005', 'aws-clf', 'Uma startup brasileira atende usuários no Brasil e gasta R$ 80k/mês em sa-east-1. O CFO sugere migrar tudo para us-east-1 (até 30% mais barato). Considerando o trade-off entre Cost Optimization e Performance Efficiency, qual é a perda esperada?', '[{"id":"A","text":"Latência ao usuário final sobe ~120ms (RTT BR↔Virginia), degradando UX em chamadas API síncronas"},{"id":"B","text":"A Sustainability Pillar proíbe esse tipo de movimento"},{"id":"C","text":"Não há diferença prática — todas as regiões AWS têm a mesma latência"},{"id":"D","text":"Os dados do cliente ficam ilegíveis fora do Brasil"}]'::jsonb, 'A', '{"summary":"Mover de sa-east-1 para us-east-1 reduz custo mas adiciona ~120ms de RTT, degradando Performance Efficiency.","whyCorrect":"A latência São Paulo↔Virginia é ~115-130ms RTT (fibra submarina). Para APIs síncronas (login, checkout) isso é perceptível ao usuário; para batch noturno, irrelevante. É o trade-off clássico Cost vs Performance que o Well-Architected Framework força a explicitar.","whyWrong":{"B":"Sustainability não proíbe escolhas — apenas orienta. Curiosamente, us-east-1 historicamente tinha menor fração de renovável que eu-west-1, mas isso não ''proíbe'' o movimento.","C":"Falso. Latência inter-region varia de 10ms (regiões próximas) a 250ms+ (extremos como sa-east-1↔ap-southeast-2).","D":"Dados não ficam ''ilegíveis'' — criptografia funciona em qualquer região. O ponto sensível seria conformidade LGPD/residência, não legibilidade."},"keyConcept":"Region selection — 5 fatores (latência, custo, compliance, features, sustainability)","compareWith":["Cost Optimization","Data residency (LGPD)"],"realWorldContext":"Decisão recorrente em fintechs BR — manter core em sa-east-1 (latência + Bacen) e usar us-east-1 para analytics/ML (custo)."}'::jsonb, 'Cloud Concepts', 'Cloud Concepts', 'medium', 'scenario', '["well-architected","performance-efficiency","region-selection"]'::jsonb, 'ai-draft', 'active', now(), now()),
    ('clf-c02-cc-v2-006', 'aws-clf', 'Uma equipe quer aplicar ''Stop guessing capacity'' no pilar Performance Efficiency. Qual mecanismo AWS é a manifestação mais direta desse princípio?', '[{"id":"A","text":"Reserved Instances de 3 anos com upfront total"},{"id":"B","text":"EC2 Auto Scaling com target tracking baseado em métricas reais (CPU, requests)"},{"id":"C","text":"AWS Budgets com alertas em $X mensais"},{"id":"D","text":"Trusted Advisor com checagem semanal"}]'::jsonb, 'B', '{"summary":"Auto Scaling provisiona capacidade dinamicamente em função da demanda real — fim do ''chute'' de capacidade.","whyCorrect":"''Stop guessing capacity'' é resolvido por elasticidade: o sistema responde a métricas reais (CPU > 70% adiciona instância, < 30% remove). Target tracking é a forma mais alinhada porque mantém o sistema na meta sem oversize prévio.","whyWrong":{"A":"Reserved Instance de 3 anos é o oposto — você compromete capacidade fixa antecipadamente, exatamente o ''guessing'' que se quer evitar.","C":"Budgets é controle financeiro reativo (alerta quando gasto passa limite); não ajusta capacidade.","D":"Trusted Advisor é advisory (recomenda right-sizing), mas é manual e periódico — não é elasticidade automática."},"keyConcept":"Elasticity — provisionamento reativo à demanda","compareWith":["Reserved Instance (commitment)","Auto Scaling (elasticity)"],"realWorldContext":"Black Friday em e-commerce — sem Auto Scaling, ou super-provisiona (caro) ou cai (perda de receita).","tutorSeeds":["Qual a diferença entre scalability e elasticity?","Quando usar target tracking vs step scaling?"]}'::jsonb, 'Cloud Concepts', 'Cloud Concepts', 'easy', 'best-practice', '["well-architected","performance-efficiency","elasticity"]'::jsonb, 'ai-draft', 'active', now(), now()),
    ('clf-c02-cc-v2-007', 'aws-clf', 'Uma empresa adota ''mechanical sympathy'' do pilar Performance Efficiency escolhendo Graviton (ARM) em vez de x86 para um workload Java stateless. Qual benefício esperado alinha-se diretamente a esse princípio?', '[{"id":"A","text":"Garantia de compatibilidade binária 100% com qualquer software"},{"id":"B","text":"Melhor relação preço/desempenho por escolher a tecnologia certa para o workload"},{"id":"C","text":"Backup automático cross-region"},{"id":"D","text":"Conformidade automática com LGPD"}]'::jsonb, 'B', '{"summary":"Mechanical sympathy: escolher hardware/instance type que mais combina com o workload. Graviton oferece até 40% melhor preço/desempenho para workloads compatíveis.","whyCorrect":"''Use the technologies that align with what you are trying to achieve'' — Graviton (ARM Neoverse) é otimizado para workloads stateless e Java/Go modernos, entregando ~40% melhor preço/desempenho. É a aplicação direta do design principle.","whyWrong":{"A":"Graviton (ARM) NÃO é binário-compatível com x86; software precisa de build ARM. A ''compatibilidade 100%'' é falsa e contradiz o ponto.","C":"Backup cross-region é tema de Reliability/DR, não de mechanical sympathy.","D":"LGPD é compliance, não relacionado à escolha de arquitetura de CPU."},"keyConcept":"Performance Efficiency — mechanical sympathy","compareWith":["Graviton vs x86 (Intel/AMD)","Inferentia vs GPU"],"realWorldContext":"Snap, Twitter (X), Pinterest migraram fleets significativas para Graviton com ganhos relevantes de custo."}'::jsonb, 'Cloud Concepts', 'Cloud Concepts', 'medium', 'scenario', '["well-architected","performance-efficiency","graviton"]'::jsonb, 'ai-draft', 'active', now(), now()),
    ('clf-c02-cc-v2-008', 'aws-clf', 'Qual design principle do pilar Security do Well-Architected Framework é diretamente representado pela prática de cifrar dados tanto em repouso (KMS, EBS encryption) quanto em trânsito (TLS, VPN)?', '[{"id":"A","text":"Apply security at all layers"},{"id":"B","text":"Protect data in transit and at rest"},{"id":"C","text":"Enable traceability"},{"id":"D","text":"Prepare for security events"}]'::jsonb, 'B', '{"summary":"''Protect data in transit and at rest'' é o princípio que mapeia 1:1 a prática descrita.","whyCorrect":"Esse design principle exige cifrar dados sensíveis em ambos os estados — repouso (KMS, S3 SSE, EBS encryption) e trânsito (TLS, VPN, mTLS). É o nome literal do princípio.","whyWrong":{"A":"''Apply security at all layers'' (defense in depth) é mais amplo — inclui edge (WAF), VPC (SGs, NACLs), instância (host), app, dados. Cifragem é parte, não o todo.","C":"''Enable traceability'' fala de CloudTrail, Config, GuardDuty — auditoria, não cifragem.","D":"''Prepare for security events'' é incident response — runbooks, automação de containment."},"keyConcept":"Security — design principles (7)","compareWith":["Defense in depth","Least privilege","Encryption"],"realWorldContext":"PCI-DSS, HIPAA e LGPD todos exigem cifragem em trânsito e repouso para dados sensíveis."}'::jsonb, 'Cloud Concepts', 'Cloud Concepts', 'easy', 'recall', '["well-architected","security","encryption"]'::jsonb, 'ai-draft', 'active', now(), now()),
    ('clf-c02-cc-v2-009', 'aws-clf', 'Após um incidente, a equipe percebe que não tinha logs suficientes para reconstruir quem fez o quê. Habilitar CloudTrail em todas as contas e ingerir no Security Hub é a aplicação direta de qual design principle do pilar Security?', '[{"id":"A","text":"Implement a strong identity foundation"},{"id":"B","text":"Enable traceability"},{"id":"C","text":"Automate security best practices"},{"id":"D","text":"Keep people away from data"}]'::jsonb, 'B', '{"summary":"''Enable traceability'' = monitor, alert, audit ações e mudanças — exatamente o que CloudTrail + Security Hub entregam.","whyCorrect":"Esse princípio exige logs de ação (CloudTrail), logs de configuração (Config), detecção (GuardDuty) e agregação (Security Hub) para reconstruir eventos. Falta de logs no incidente é falha clara nesse princípio.","whyWrong":{"A":"''Strong identity foundation'' é IAM/SSO/MFA — quem é o caller; não é sobre rastreio do que ele fez.","C":"''Automate security best practices'' é IaC/automação (Security Hub auto-remediation) — relacionado mas o cenário descreve a falta de visibilidade, não de automação.","D":"''Keep people away from data'' é segregação (acesso via APIs, não bastion); o cenário não trata de acesso humano direto."},"keyConcept":"Security — traceability (audit, monitor, alert)","compareWith":["CloudTrail (API calls)","Config (resource state)","GuardDuty (threats)"],"realWorldContext":"Post-mortem típico após incidente sempre exige timeline reconstruída via CloudTrail Lake."}'::jsonb, 'Cloud Concepts', 'Cloud Concepts', 'easy', 'scenario', '["well-architected","security","logging"]'::jsonb, 'ai-draft', 'active', now(), now()),
    ('clf-c02-cc-v2-010', 'aws-clf', 'O pilar Reliability tem o design principle ''Test recovery procedures''. Qual prática operacional é a manifestação mais fiel desse princípio?', '[{"id":"A","text":"Game days que injetam falhas controladas em produção/staging para validar runbooks de recuperação"},{"id":"B","text":"Aumentar a vida útil dos backups para 7 anos"},{"id":"C","text":"Mover todos os recursos para a região mais barata"},{"id":"D","text":"Adquirir Reserved Instances de 3 anos"}]'::jsonb, 'A', '{"summary":"Game days exercitam runbooks de DR em condições próximas do real — única forma de garantir que a recuperação realmente funciona.","whyCorrect":"''Test recovery procedures'' diferencia ter um runbook de saber que ele funciona. Game days (chaos engineering) injetam falhas (terminar AZ, derrubar RDS, latência) e verificam se o sistema/equipe recupera no RTO acordado. Sem teste, runbook é teatro.","whyWrong":{"B":"Reter backups por mais tempo é retenção, não teste de recuperação. Backup sem restore testado é falsa segurança.","C":"Custo de região não tem relação com testar recuperação.","D":"Reserved Instance é financeiro/comprometimento, não DR test."},"keyConcept":"Reliability — test recovery, chaos engineering","compareWith":["Game day","Chaos engineering","DR drill"],"realWorldContext":"Netflix popularizou com Chaos Monkey/Simian Army; AWS oferece Fault Injection Service (FIS) para esses experimentos."}'::jsonb, 'Cloud Concepts', 'Cloud Concepts', 'medium', 'best-practice', '["well-architected","reliability","game-days"]'::jsonb, 'ai-draft', 'active', now(), now()),
    ('clf-c02-cc-v2-011', 'aws-clf', 'Uma equipe quer aplicar ''Automatically recover from failure'' (Reliability). Qual mecanismo AWS é o exemplo mais direto desse princípio?', '[{"id":"A","text":"EC2 Auto Recovery (substitui instância falha automaticamente, mantém IP)"},{"id":"B","text":"AWS Budgets com alerta em 80%"},{"id":"C","text":"Trusted Advisor checks semanais"},{"id":"D","text":"AWS Marketplace subscription"}]'::jsonb, 'A', '{"summary":"EC2 Auto Recovery (e Auto Scaling self-healing) substitui automaticamente instâncias falhas — recuperação sem intervenção humana.","whyCorrect":"''Automatically recover from failure'' = sistema detecta falha (CloudWatch alarm), age (substitui instância, falha-over RDS) sem humano. EC2 Auto Recovery, Auto Scaling self-healing e RDS Multi-AZ failover são manifestações canônicas.","whyWrong":{"B":"Budgets alerta sobre gasto, não recupera falha.","C":"Trusted Advisor recomenda melhorias; não age automaticamente.","D":"Marketplace é catálogo de software — irrelevante."},"keyConcept":"Reliability — auto-recovery / self-healing","compareWith":["EC2 Auto Recovery","ASG health checks","RDS Multi-AZ failover"],"realWorldContext":"Health checks de ASG + ELB removem instância unhealthy do tráfego e provisionam nova em minutos."}'::jsonb, 'Cloud Concepts', 'Cloud Concepts', 'easy', 'scenario', '["well-architected","reliability","auto-recovery"]'::jsonb, 'ai-draft', 'active', now(), now()),
    ('clf-c02-cc-v2-012', 'aws-clf', 'Qual design principle do pilar Cost Optimization é a base para a prática de tagging consistente em todos os recursos AWS?', '[{"id":"A","text":"Adopt a consumption model"},{"id":"B","text":"Measure overall efficiency"},{"id":"C","text":"Analyze and attribute expenditure"},{"id":"D","text":"Stop spending money on undifferentiated heavy lifting"}]'::jsonb, 'C', '{"summary":"''Analyze and attribute expenditure'' exige saber quem/qual workload gera cada custo — tags são o mecanismo.","whyCorrect":"Sem tags consistentes (Environment, CostCenter, Project, Owner), o Cost and Usage Report não consegue atribuir gasto a equipes/produtos. Tagging é pré-requisito desse design principle e habilita showback/chargeback (FinOps).","whyWrong":{"A":"''Adopt a consumption model'' = pay-as-you-go vs comprar capacidade. Tagging não é o mecanismo desse princípio.","B":"''Measure overall efficiency'' = output de negócio / custo (ex: USD por pedido). Tags ajudam mas o princípio é a métrica, não o tag em si.","D":"''Stop spending on undifferentiated heavy lifting'' = usar managed services em vez de operar infra própria. Não é tagging."},"keyConcept":"Cost Optimization — cost allocation tags","compareWith":["AWS Cost Categories","Cost Allocation Tags","AWS Budgets per tag"],"realWorldContext":"Empresas com 50+ contas usam SCPs para enforce de tags obrigatórios (tag policies em Organizations).","tutorSeeds":["Como ativar cost allocation tags no Billing console?","Qual a diferença entre AWS-generated tags e user-defined tags?"]}'::jsonb, 'Cloud Concepts', 'Cloud Concepts', 'medium', 'best-practice', '["well-architected","cost-optimization","tagging"]'::jsonb, 'ai-draft', 'active', now(), now()),
    ('clf-c02-cc-v2-013', 'aws-clf', 'O design principle ''Adopt a consumption model'' (Cost Optimization) implica diretamente em qual mudança de pensamento?', '[{"id":"A","text":"Comprar capacidade pico antecipada para evitar throttling"},{"id":"B","text":"Pagar apenas pelos recursos efetivamente consumidos, desligando-os quando não usados"},{"id":"C","text":"Substituir todos os recursos por Reserved Instances de 3 anos"},{"id":"D","text":"Manter um buffer fixo de 30% sempre provisionado"}]'::jsonb, 'B', '{"summary":"''Adopt a consumption model'' = pague pelo uso real, desligue o que não usa (dev nights/weekends, scale-down).","whyCorrect":"O princípio é literalmente: ''pay only for the computing resources you require''. Implica em automação de start/stop em horários não úteis, serverless on-demand, scale-down agressivo. É a aplicação prática do pay-as-you-go.","whyWrong":{"A":"Comprar capacidade pico é o anti-padrão do data center tradicional — contradiz ''consumption model''.","C":"Reserved Instance de 3 anos é commitment-based, não consumption-based; faz sentido para baseline mas não é o princípio em si.","D":"Buffer fixo de 30% é overprovisioning — gasta com capacidade ociosa."},"keyConcept":"Cost Optimization — consumption model","compareWith":["On-Demand vs Reserved vs Savings Plans vs Spot"],"realWorldContext":"Lambda, Fargate, Aurora Serverless são exemplos extremos de consumption — você paga só pelo request/ms."}'::jsonb, 'Cloud Concepts', 'Cloud Concepts', 'easy', 'recall', '["well-architected","cost-optimization","consumption-model"]'::jsonb, 'ai-draft', 'active', now(), now()),
    ('clf-c02-cc-v2-014', 'aws-clf', 'Uma equipe está fazendo Well-Architected Review e identifica que o workload tem alta utilização (Sustainability), bom RTO (Reliability), mas gasta 2x mais que o necessário. Qual ferramenta AWS é mais alinhada para guiar a remediação no pilar Cost Optimization?', '[{"id":"A","text":"AWS Compute Optimizer + Cost Explorer Rightsizing recommendations"},{"id":"B","text":"AWS GuardDuty"},{"id":"C","text":"AWS Config Conformance Pack"},{"id":"D","text":"Amazon Inspector"}]'::jsonb, 'A', '{"summary":"Compute Optimizer + Cost Explorer Rightsizing identificam instâncias super-dimensionadas — exatamente o problema de ''gasta 2x mais''.","whyCorrect":"Compute Optimizer usa ML para analisar métricas (CPU, memória, rede) e recomendar instance type/size ideal. Cost Explorer rightsizing complementa identificando instâncias ociosas. É o caminho direto para reduzir custo sem perder performance.","whyWrong":{"B":"GuardDuty é detecção de ameaças (Security), não custo.","C":"Config Conformance Pack avalia compliance de configuração — pode incluir regras de custo, mas é mais amplo e indireto.","D":"Inspector é vulnerability scanning — Security, não Cost."},"keyConcept":"Cost Optimization — rightsizing tooling","compareWith":["Compute Optimizer","Cost Explorer","Trusted Advisor cost checks"],"realWorldContext":"Empresas costumam encontrar 20-30% de economia só em rightsizing inicial."}'::jsonb, 'Cloud Concepts', 'Cloud Concepts', 'medium', 'scenario', '["well-architected","cost-optimization","rightsizing"]'::jsonb, 'ai-draft', 'active', now(), now()),
    ('clf-c02-cc-v2-015', 'aws-clf', 'Uma empresa com 300 aplicações on-prem está planejando migração para AWS. Avaliam que 40 apps são SaaS comerciais (Salesforce, Workday) que podem ser substituídos. Qual estratégia das 6 Rs aplica-se?', '[{"id":"A","text":"Rehost (lift-and-shift)"},{"id":"B","text":"Replatform (lift-tinker-and-shift)"},{"id":"C","text":"Repurchase (drop-and-shop)"},{"id":"D","text":"Refactor / Re-architect"}]'::jsonb, 'C', '{"summary":"Repurchase = trocar app on-prem por SaaS comercial equivalente (CRM próprio → Salesforce).","whyCorrect":"Repurchase (também chamado ''drop-and-shop'') significa abandonar o software atual em favor de um SaaS de terceiros. CRM próprio vira Salesforce; ERP vira Workday; HR vira BambooHR. É a estratégia certa quando há SaaS maduro substituindo o legado.","whyWrong":{"A":"Rehost = lift-and-shift, mover VM como está para EC2. Aplicaria se a empresa quisesse manter o software, só mudar de infra.","B":"Replatform = pequenas otimizações na migração (Oracle on-prem → RDS for Oracle). Mantém o software, troca a infra/plataforma.","D":"Refactor = reescrever para cloud-native. Aplicaria se decidissem reescrever o CRM para serverless em vez de comprar SaaS."},"keyConcept":"Migration — 6 Rs (Retire, Retain, Rehost, Relocate, Replatform, Repurchase, Refactor)","compareWith":["Repurchase vs Refactor","Rehost vs Replatform"],"realWorldContext":"Empresas frequentemente fazem mix: rehost 60%, replatform 25%, repurchase 10%, refactor 5%.","tutorSeeds":["Como o MAP (Migration Acceleration Program) financia esses movimentos?","Qual a diferença entre Retire e Retain?"]}'::jsonb, 'Cloud Concepts', 'Cloud Concepts', 'easy', 'scenario', '["migration","6rs","repurchase"]'::jsonb, 'ai-draft', 'active', now(), now()),
    ('clf-c02-cc-v2-016', 'aws-clf', 'Durante o assessment de migração, identifica-se que 15 apps são legacy (mainframe COBOL) sem uso ativo nos últimos 18 meses, mas ainda ligados. A estratégia recomendada nas 6 Rs é:', '[{"id":"A","text":"Retire (desligar)"},{"id":"B","text":"Retain (manter como está, revisitar no futuro)"},{"id":"C","text":"Rehost (mover para EC2 sem alteração)"},{"id":"D","text":"Refactor (reescrever em Lambda)"}]'::jsonb, 'A', '{"summary":"Retire = desligar apps sem uso real. Frequentemente 10-20% do portfólio cai aqui no assessment.","whyCorrect":"Apps sem uso por 18 meses são candidatos óbvios a Retire. Migrar (qualquer ''R'') consome esforço; desligar economiza tudo. O assessment de portfolio sempre prioriza identificar Retire antes de planejar as outras estratégias.","whyWrong":{"B":"Retain seria para apps que precisam continuar on-prem por compliance/legacy não migrável ainda — mas aqui o app não tem uso, então retain é desperdício.","C":"Rehost gastaria esforço de migração para algo que ninguém usa.","D":"Refactor é o maior investimento; jamais para app sem uso."},"keyConcept":"Migration — Retire vs Retain","compareWith":["Retire (desligar)","Retain (manter sem migrar)"],"realWorldContext":"Portfolio assessment típico (TSO Logic, Migration Evaluator) sempre destaca % de Retire potencial — economia imediata."}'::jsonb, 'Cloud Concepts', 'Cloud Concepts', 'easy', 'scenario', '["migration","6rs","retire"]'::jsonb, 'ai-draft', 'active', now(), now()),
    ('clf-c02-cc-v2-017', 'aws-clf', 'Uma equipe usa AWS Application Migration Service (MGN) para migrar 50 VMs VMware on-prem para EC2 com mudanças mínimas. Qual das 6 Rs essa abordagem materializa?', '[{"id":"A","text":"Rehost (lift-and-shift)"},{"id":"B","text":"Refactor"},{"id":"C","text":"Repurchase"},{"id":"D","text":"Retire"}]'::jsonb, 'A', '{"summary":"AWS MGN replica VMs em block-level e converte em instâncias EC2 — automatiza rehost em escala.","whyCorrect":"MGN (antigo CloudEndure Migration) faz replicação contínua de VMs on-prem para EC2 e permite cutover com downtime mínimo. Como mantém o SO/app inalterados, é a definição de Rehost (lift-and-shift).","whyWrong":{"B":"Refactor exigiria reescrever o app (ex: monolito → microservices). MGN não toca o app.","C":"Repurchase exigiria trocar por SaaS. MGN não compra nada novo.","D":"Retire desliga; MGN migra."},"keyConcept":"Migration — MGN (Application Migration Service)","compareWith":["MGN (rehost)","DMS (database migration)","DataSync (file transfer)"],"realWorldContext":"MGN é a ferramenta padrão de rehost em massa — usada em programas MAP grandes."}'::jsonb, 'Cloud Concepts', 'Cloud Concepts', 'easy', 'scenario', '["migration","6rs","rehost","mgn"]'::jsonb, 'ai-draft', 'active', now(), now()),
    ('clf-c02-cc-v2-018', 'aws-clf', 'O AWS Migration Acceleration Program (MAP) é estruturado em 3 fases. A fase em que se prioriza apps, define business case e cria landing zone é:', '[{"id":"A","text":"Assess"},{"id":"B","text":"Mobilize"},{"id":"C","text":"Migrate & Modernize"},{"id":"D","text":"Operate"}]'::jsonb, 'B', '{"summary":"MAP tem 3 fases: Assess (avaliar prontidão), Mobilize (planejar + landing zone), Migrate & Modernize (executar).","whyCorrect":"Mobilize é a fase intermediária onde se define o business case detalhado, prioriza waves de apps, cria a landing zone (Control Tower, redes, contas), capacita o time e remove blockers organizacionais. É o ''plano de batalha'' antes da migração começar.","whyWrong":{"A":"Assess é a fase inicial — descobrir o portfólio, calcular TCO, identificar 6 Rs por app. Vem ANTES de mobilize.","C":"Migrate & Modernize é a execução em waves — vem DEPOIS de mobilize.","D":"Operate não é fase formal do MAP; é o estado pós-migração (BAU em cloud)."},"keyConcept":"AWS MAP — Assess / Mobilize / Migrate & Modernize","compareWith":["Assess (descobrir)","Mobilize (planejar)","Migrate (executar)"],"realWorldContext":"MAP fornece créditos AWS e Professional Services para reduzir custo da migração em troca de commitment de gasto pós-migração."}'::jsonb, 'Cloud Concepts', 'Cloud Concepts', 'hard', 'recall', '["migration","map","phases"]'::jsonb, 'ai-draft', 'active', now(), now()),
    ('clf-c02-cc-v2-019', 'aws-clf', 'Uma empresa quer agrupar e visualizar o progresso de migração de centenas de servidores em waves. Qual serviço AWS é desenhado especificamente para isso?', '[{"id":"A","text":"AWS Migration Hub"},{"id":"B","text":"AWS Systems Manager"},{"id":"C","text":"AWS Trusted Advisor"},{"id":"D","text":"AWS CloudFormation StackSets"}]'::jsonb, 'A', '{"summary":"Migration Hub é o painel único para acompanhar progresso de migração através de MGN, DMS, Application Discovery Service.","whyCorrect":"Migration Hub agrega dados de discovery, tracking de waves, status de cada server/app, e integra com MGN, DMS e parceiros. É o ''mission control'' de migração — desenhado exatamente para o cenário descrito.","whyWrong":{"B":"Systems Manager é gestão operacional de fleet (patching, Run Command, Parameter Store) — pós-migração, não para tracking de migração.","C":"Trusted Advisor faz checks de best practices em conta — não trata de migração.","D":"StackSets é deploy multi-account de CFN templates — útil para landing zone, não para tracking."},"keyConcept":"Migration Hub — visualização unificada","compareWith":["Migration Hub (tracking)","MGN (execução)","ADS (discovery)"],"realWorldContext":"Em programas MAP grandes (1000+ servers), Migration Hub é onde o CIO acompanha % de waves concluídas semanalmente."}'::jsonb, 'Cloud Concepts', 'Cloud Concepts', 'medium', 'best-practice', '["migration","migration-hub"]'::jsonb, 'ai-draft', 'active', now(), now()),
    ('clf-c02-cc-v2-020', 'aws-clf', 'Uma empresa quer migrar Oracle on-prem para Aurora PostgreSQL na AWS. Qual combinação correta de estratégia (6 Rs) + serviço de migração?', '[{"id":"A","text":"Rehost + MGN"},{"id":"B","text":"Refactor + AWS Schema Conversion Tool (SCT) + Database Migration Service (DMS)"},{"id":"C","text":"Repurchase + AWS Marketplace"},{"id":"D","text":"Retire + AWS Backup"}]'::jsonb, 'B', '{"summary":"Trocar engine de Oracle para PostgreSQL exige refactor de schema/PL-SQL e migração de dados — SCT + DMS é o caminho canônico.","whyCorrect":"Mudar de Oracle para Aurora PostgreSQL muda a engine (SQL dialect, stored procedures, tipos) — isso é Refactor (não Replatform que mantém engine). SCT converte schema e código PL/SQL para PL/pgSQL; DMS replica dados continuamente até cutover.","whyWrong":{"A":"Rehost manteria Oracle (rodando em EC2). Não cobre a mudança de engine para PostgreSQL.","C":"Repurchase seria trocar por SaaS comercial (ex: trocar CRM por Salesforce). Não se aplica a database engine swap.","D":"Retire desliga; o cenário quer manter o sistema, só trocar o backend de DB."},"keyConcept":"Migration — heterogeneous DB migration (SCT + DMS)","compareWith":["Replatform (Oracle → RDS for Oracle)","Refactor (Oracle → Aurora PostgreSQL)"],"realWorldContext":"Movimento clássico de empresas fugindo de licenças Oracle — economia significativa de licensing.","tutorSeeds":["Por que mudar engine é Refactor e não Replatform?","Como DMS faz CDC (change data capture)?"]}'::jsonb, 'Cloud Concepts', 'Cloud Concepts', 'hard', 'scenario', '["migration","refactor","dms","sct"]'::jsonb, 'ai-draft', 'active', now(), now()),
    ('clf-c02-cc-v2-021', 'aws-clf', 'Uma empresa avalia TCO (Total Cost of Ownership) de manter on-prem vs migrar para AWS. Qual componente é tipicamente subestimado no on-prem ao comparar com AWS pay-as-you-go?', '[{"id":"A","text":"Custo de energia, refrigeração, espaço de rack, segurança física e equipe de operação 24x7"},{"id":"B","text":"Custo das licenças de software"},{"id":"C","text":"Custo dos servidores físicos"},{"id":"D","text":"Custo da internet corporativa"}]'::jsonb, 'A', '{"summary":"Os ''custos invisíveis'' (energia, refrigeração, espaço, equipe de ops) são os mais subestimados no TCO on-prem.","whyCorrect":"Hardware é fácil de contabilizar (nota fiscal). Já energia (kWh), refrigeração (HVAC), espaço físico (m² ou rack-units), segurança física, e principalmente headcount de operação 24x7 (sysadmin, network engineer, DC tech) somam frequentemente 2-3x o valor do hardware ao longo do ciclo de vida. AWS embute tudo isso no preço por hora.","whyWrong":{"B":"Licenças de software são tipicamente bem contabilizadas porque vêm em contratos anuais visíveis ao financeiro.","C":"Servidores físicos são item de imobilizado registrado contabilmente — visível.","D":"Internet corporativa é OpEx mensal recorrente, geralmente bem tracked."},"keyConcept":"TCO — custos diretos vs indiretos","compareWith":["TCO (total cost)","ROI (retorno do investimento)"],"realWorldContext":"AWS Pricing Calculator e Migration Evaluator ajudam a quantificar esses custos invisíveis para business case.","tutorSeeds":["Qual a diferença entre TCO e ROI?","Como o Migration Evaluator coleta dados on-prem?"]}'::jsonb, 'Cloud Concepts', 'Cloud Concepts', 'medium', 'scenario', '["pricing","tco","on-prem"]'::jsonb, 'ai-draft', 'active', now(), now()),
    ('clf-c02-cc-v2-022', 'aws-clf', 'Qual a diferença prática mais importante entre Reserved Instances (RI) e Savings Plans (SP)?', '[{"id":"A","text":"RI é commitment a tipo/family específicos de instância; Savings Plans (Compute) é commitment em $/hora flexível através de family, size, region e até serviço (EC2/Fargate/Lambda)"},{"id":"B","text":"RI é mais barato em 100% dos casos"},{"id":"C","text":"Savings Plans só funciona em sa-east-1"},{"id":"D","text":"RI exige upfront total obrigatório; SP nunca exige upfront"}]'::jsonb, 'A', '{"summary":"Compute Savings Plans dá flexibilidade que RI clássicas não dão — mesmo desconto, sem amarração a instance type.","whyCorrect":"Standard RI compromete você com instance family + region (e às vezes size). Compute Savings Plans compromete em $/hora gasto em compute, e o desconto aplica automaticamente em EC2 (qualquer family/size/region), Fargate e Lambda. É commitment financeiro, não técnico — daí flexibilidade superior.","whyWrong":{"B":"RI Standard tem desconto ligeiramente maior (~72%) que Compute SP (~66%) em troca da rigidez. ''Mais barato em 100% dos casos'' é falso e ignora o trade-off.","C":"Savings Plans funciona em todas as regiões.","D":"Ambos oferecem 3 opções: All Upfront, Partial Upfront, No Upfront. Não é um critério distintivo."},"keyConcept":"Pricing — commitment-based discounts","compareWith":["Standard RI","Convertible RI","Compute SP","EC2 Instance SP"],"realWorldContext":"Recomendação atual da AWS: Savings Plans é o default por flexibilidade; RI permanece para casos específicos (ex: RDS reservations não existem como SP)."}'::jsonb, 'Cloud Concepts', 'Cloud Concepts', 'hard', 'best-practice', '["pricing","ri","savings-plans"]'::jsonb, 'ai-draft', 'active', now(), now()),
    ('clf-c02-cc-v2-023', 'aws-clf', 'Spot Instances oferecem até 90% de desconto vs On-Demand. Qual workload é o caso de uso INCORRETO para Spot?', '[{"id":"A","text":"Batch processing tolerante a interrupção (ETL noturno, ML training com checkpointing)"},{"id":"B","text":"Renderização de vídeo em fleet de instâncias paralelas"},{"id":"C","text":"Banco de dados de produção single-instance hospedando estado crítico"},{"id":"D","text":"CI/CD runners stateless"}]'::jsonb, 'C', '{"summary":"Spot pode ser interrompida com 2 min de aviso — inviável para banco de dados stateful single-instance.","whyCorrect":"Banco de dados de produção single-instance perderia conexões, transações in-flight e potencialmente dados se interrompido. Spot é desenhado para workloads tolerantes a interrupção, sem estado crítico local. Database stateful é o anti-padrão.","whyWrong":{"A":"Batch tolerante a interrupção com checkpointing é o caso de uso canônico de Spot — perdeu instância, retoma do último checkpoint.","B":"Renderização em fleet stateless é ideal para Spot — perde um frame, refaz; cada nó é independente.","D":"CI/CD runners stateless são perfeitos — se interrompido, job é retomado em outro runner."},"keyConcept":"Spot — workloads tolerantes a interrupção","compareWith":["Spot (interrompível)","On-Demand (estável)","Reserved (commitment)"],"realWorldContext":"Empresas como Pinterest e Lyft rodam grande parte do ML training em Spot Fleet com economia de 60-80%."}'::jsonb, 'Cloud Concepts', 'Cloud Concepts', 'easy', 'scenario', '["pricing","spot","interruption"]'::jsonb, 'ai-draft', 'active', now(), now()),
    ('clf-c02-cc-v2-024', 'aws-clf', 'O conceito ''Right Sizing'' no AWS Cost Optimization Hub refere-se primariamente a:', '[{"id":"A","text":"Ajustar tipo/tamanho de instância ao perfil real de uso (CPU/memória) — frequentemente reduzir de m5.2xlarge para m5.xlarge"},{"id":"B","text":"Aumentar instâncias para evitar throttling"},{"id":"C","text":"Mudar todas as instâncias para o maior tipo disponível"},{"id":"D","text":"Apagar instâncias antigas após 1 ano"}]'::jsonb, 'A', '{"summary":"Right sizing = casar tipo/tamanho de instância ao uso real, geralmente reduzindo para evitar desperdício.","whyCorrect":"Right sizing analisa métricas (CPU médio < 20%, memória < 30%) e recomenda instância menor ou family diferente (ex: compute-heavy → general purpose). É a primeira otimização de custo recomendada — frequentemente 20-30% de economia imediata.","whyWrong":{"B":"''Aumentar para evitar throttling'' é resposta a problema de performance, não right sizing. Right sizing pode aumentar OU reduzir, mas com base em dados.","C":"Mudar tudo para o maior tipo é over-provisioning extremo — oposto de right sizing.","D":"Apagar instâncias antigas é cleanup; right sizing ajusta dimensão de instâncias ativas."},"keyConcept":"Cost Optimization — right sizing","compareWith":["Right sizing","Scheduling (stop/start)","Spot conversion"],"realWorldContext":"Compute Optimizer e Cost Explorer Rightsizing Recommendations são as ferramentas nativas."}'::jsonb, 'Cloud Concepts', 'Cloud Concepts', 'easy', 'recall', '["pricing","rightsizing","cost-optimization-hub"]'::jsonb, 'ai-draft', 'active', now(), now()),
    ('clf-c02-cc-v2-025', 'aws-clf', 'Uma equipe quer estimar o custo de uma arquitetura ANTES de provisionar (estimativa para business case). Qual ferramenta é a correta?', '[{"id":"A","text":"AWS Pricing Calculator"},{"id":"B","text":"AWS Cost Explorer"},{"id":"C","text":"AWS Budgets"},{"id":"D","text":"Cost and Usage Report (CUR)"}]'::jsonb, 'A', '{"summary":"Pricing Calculator é PRÉ-provisionamento (estimativa); as outras ferramentas são PÓS (consumo real).","whyCorrect":"Pricing Calculator permite montar uma arquitetura virtual (10 EC2 m5.large + RDS db.m5.xlarge + 500GB S3...) e calcular custo mensal estimado. É a ferramenta para business case, RFPs, comparação de cenários — antes de gastar 1 centavo.","whyWrong":{"B":"Cost Explorer analisa gasto histórico e tendências — só funciona com consumo real já gerado.","C":"Budgets define limites e alertas sobre consumo real — não estima.","D":"CUR é o arquivo detalhado de consumo real (por hora, por recurso) — também post-fact."},"keyConcept":"Pricing tooling — pre-provisioning vs post-consumption","compareWith":["Pricing Calculator (estimar)","Cost Explorer (analisar)","Budgets (controlar)"],"realWorldContext":"Toda proposta comercial de migração AWS começa com Pricing Calculator para gerar TCO comparativo."}'::jsonb, 'Cloud Concepts', 'Cloud Concepts', 'easy', 'recall', '["pricing","calculator"]'::jsonb, 'ai-draft', 'active', now(), now()),
    ('clf-c02-cc-v2-026', 'aws-clf', 'O AWS Cost Optimization Hub (lançado em 2023) tem qual propósito diferenciado em relação ao Cost Explorer?', '[{"id":"A","text":"Consolida recomendações de economia (rightsizing, idle, savings plans, graviton) de várias ferramentas AWS num único console, com priorização e potencial de economia quantificado"},{"id":"B","text":"Substitui o billing console"},{"id":"C","text":"Faz pagamento automático da fatura"},{"id":"D","text":"É um marketplace de cursos de finanças"}]'::jsonb, 'A', '{"summary":"Cost Optimization Hub agrega recomendações de Compute Optimizer, Trusted Advisor, Savings Plans e Reservations num único painel priorizado.","whyCorrect":"Antes do Hub, você precisava abrir Compute Optimizer (rightsizing), Trusted Advisor (idle), Savings Plans recommendations e RIs separadamente. O Hub unifica tudo num só lugar, mostra valor potencial de economia em $/mês e prioriza ações de maior impacto.","whyWrong":{"B":"Billing console continua existindo para faturas e pagamento.","C":"Pagamento de fatura é função do Billing, não do Hub.","D":"Hub não tem nada a ver com cursos — é console de recomendações."},"keyConcept":"AWS Cost Optimization Hub — consolidação","compareWith":["Cost Explorer","Trusted Advisor","Compute Optimizer"],"realWorldContext":"FinOps teams agora começam o dia revisando o Hub para identificar quick wins."}'::jsonb, 'Cloud Concepts', 'Cloud Concepts', 'hard', 'recall', '["pricing","cost-optimization-hub"]'::jsonb, 'ai-draft', 'active', now(), now()),
    ('clf-c02-cc-v2-027', 'aws-clf', 'Qual a diferença correta entre TCO e ROI no contexto de migração para nuvem?', '[{"id":"A","text":"TCO mede o custo total acumulado de uma solução ao longo do tempo; ROI mede o retorno (benefício / investimento) gerado pela mesma solução"},{"id":"B","text":"São sinônimos"},{"id":"C","text":"TCO mede latência; ROI mede throughput"},{"id":"D","text":"TCO mede uptime; ROI mede MTTR"}]'::jsonb, 'A', '{"summary":"TCO = custo total. ROI = (ganho - custo) / custo. TCO é input do cálculo de ROI.","whyCorrect":"TCO soma todos os custos (hardware, software, energia, pessoal, manutenção) ao longo de um período. ROI compara o benefício gerado (receita adicional, custo evitado, produtividade) contra o investimento. Migrar para AWS pode reduzir TCO E aumentar ROI ao mesmo tempo.","whyWrong":{"B":"São complementares mas distintos.","C":"Latência/throughput são métricas de performance, não financeiras.","D":"Uptime/MTTR são métricas de reliability, não financeiras."},"keyConcept":"Financial — TCO vs ROI","compareWith":["TCO (total cost)","ROI (return on investment)","Payback period"],"realWorldContext":"Business case típico mostra: ''AWS reduz TCO em 30% E acelera time-to-market em 50% → ROI positivo em 18 meses''."}'::jsonb, 'Cloud Concepts', 'Cloud Concepts', 'easy', 'recall', '["pricing","tco","roi"]'::jsonb, 'ai-draft', 'active', now(), now()),
    ('clf-c02-cc-v2-028', 'aws-clf', 'AWS Pricing API permite:', '[{"id":"A","text":"Consultar programaticamente preços de serviços AWS para ferramentas de FinOps e calculadoras internas, em JSON"},{"id":"B","text":"Mudar o preço dos serviços AWS"},{"id":"C","text":"Receber descontos automáticos"},{"id":"D","text":"Pagar fatura via API"}]'::jsonb, 'A', '{"summary":"AWS Pricing API expõe o catálogo de preços em JSON — usado para automatizar estimativas e dashboards FinOps.","whyCorrect":"É uma API somente leitura que retorna preços públicos de serviços, instance types, regiões. Ferramentas como Cloudability, Vantage, ou scripts internos usam para gerar estimativas dinâmicas. Não muda preço — só consulta.","whyWrong":{"B":"Preços são definidos pela AWS, não pelo cliente via API.","C":"Descontos são via Savings Plans, RIs, Enterprise Agreement — não via API.","D":"Pagamento de fatura é via Billing console / método de pagamento, não Pricing API."},"keyConcept":"Pricing API — programmatic price catalog","compareWith":["Pricing Calculator (UI)","Pricing API (programático)"],"realWorldContext":"Vendors de FinOps tooling como Vantage e Cloudability puxam preços via essa API para gerar recomendações."}'::jsonb, 'Cloud Concepts', 'Cloud Concepts', 'hard', 'recall', '["pricing","pricing-api"]'::jsonb, 'ai-draft', 'active', now(), now()),
    ('clf-c02-cc-v2-029', 'aws-clf', 'FinOps tem 3 princípios fundamentais. Qual reflete corretamente um deles aplicado em AWS?', '[{"id":"A","text":"Todos da empresa participam: engenharia, finanças e negócio colaboram em decisões de custo (não só finance dita)"},{"id":"B","text":"Apenas o time financeiro decide gastos de cloud"},{"id":"C","text":"Engenharia não deve ver dados de custo"},{"id":"D","text":"Cloud é gratuito por padrão"}]'::jsonb, 'A', '{"summary":"FinOps é cultura cross-funcional: engenheiros veem custo do que constroem, finanças entende cloud, negócio vê ROI por feature.","whyCorrect":"Princípio FinOps Foundation: ''Teams need to collaborate''. Engenharia, finanças e produto compartilham dashboards de custo, definem KPIs juntos (USD por pedido, custo por cliente). Sem isso, finanças reclama de fatura e engenharia ignora.","whyWrong":{"B":"Anti-padrão FinOps clássico — finance dita sem entender cloud, engenharia ignora sem ver impacto.","C":"FinOps prega o contrário: ''tornar custo visível para quem decide'' (engenheiros que provisionam).","D":"Cloud cobra por uso; afirmação falsa."},"keyConcept":"FinOps — collaboration, ownership, real-time decisions","compareWith":["FinOps","Cloud Financial Management (AWS)"],"realWorldContext":"Empresas maduras têm ''FinOps practitioner'' role e cost dashboards expostos em times de engenharia.","tutorSeeds":["Quais são as 3 fases do FinOps lifecycle (Inform/Optimize/Operate)?"]}'::jsonb, 'Cloud Concepts', 'Cloud Concepts', 'medium', 'best-practice', '["finops","cloud-financial-management"]'::jsonb, 'ai-draft', 'active', now(), now()),
    ('clf-c02-cc-v2-030', 'aws-clf', 'Qual é a diferença entre showback e chargeback em cloud financial management?', '[{"id":"A","text":"Showback mostra custo atribuído por equipe/produto sem cobrança interna; chargeback efetivamente debita o orçamento do business unit consumidor"},{"id":"B","text":"São sinônimos exatos"},{"id":"C","text":"Showback é cobrar 2x; chargeback é cobrar 1x"},{"id":"D","text":"Showback é privado; chargeback é público na internet"}]'::jsonb, 'A', '{"summary":"Showback informa sem cobrar; chargeback transfere o custo para o orçamento da BU consumidora.","whyCorrect":"Showback é o estágio inicial: o time vê ''você consumiu USD 12k este mês'' mas o pagamento sai do orçamento central de TI. Chargeback evolui isso: o orçamento da BU é efetivamente debitado, criando pressão real de otimização. Empresas costumam começar em showback e migrar para chargeback conforme maturidade.","whyWrong":{"B":"São conceitualmente diferentes — show vs charge.","C":"Não tem nada a ver com cobrar 2x.","D":"Não é sobre privacidade da informação."},"keyConcept":"FinOps — showback vs chargeback","compareWith":["Showback (visibility)","Chargeback (financial accountability)"],"realWorldContext":"Cost Allocation Tags + Cost Categories permitem implementar tanto showback quanto chargeback baseado em tags por BU/projeto."}'::jsonb, 'Cloud Concepts', 'Cloud Concepts', 'medium', 'recall', '["finops","showback","chargeback"]'::jsonb, 'ai-draft', 'active', now(), now()),
    ('clf-c02-cc-v2-031', 'aws-clf', 'Uma empresa quer implementar tagging strategy robusta. Qual prática é a mais aderente aos princípios de cloud financial management?', '[{"id":"A","text":"Tags obrigatórios enforced via Tag Policies (Organizations) + SCP que nega criação de recursos sem tags requeridas (Environment, CostCenter, Owner)"},{"id":"B","text":"Cada engenheiro escolhe livremente seus próprios tags"},{"id":"C","text":"Nenhum tag — agrupar tudo manualmente no Excel"},{"id":"D","text":"Apenas tagear instâncias EC2; demais serviços não precisam"}]'::jsonb, 'A', '{"summary":"Tagging requer enforcement automático (Tag Policies + SCP), não confiança em disciplina manual.","whyCorrect":"Tag Policies definem schema (chaves válidas + valores permitidos); SCP em Organizations pode negar criação de recurso sem tags requeridas (ec2:RunInstances com condition aws:RequestTag/Environment). Combinação garante 100% de cobertura — sem isso, tagging vira esforço fútil.","whyWrong":{"B":"Tags livres geram caos: ''env=prod'' vs ''Environment=production'' vs ''ENV=PROD'' tornam relatórios inúteis.","C":"Não tagear inviabiliza atribuição de custo — anti-padrão absoluto.","D":"Restringir a EC2 deixa lacunas enormes (S3, Lambda, RDS, DynamoDB)."},"keyConcept":"Tagging governance — enforce + standardize","compareWith":["Tag Policies","SCP","AWS Config rules (tag compliance)"],"realWorldContext":"Tag spread (variações de chave/valor) é o problema #1 de FinOps em empresas grandes."}'::jsonb, 'Cloud Concepts', 'Cloud Concepts', 'medium', 'best-practice', '["finops","tagging","governance"]'::jsonb, 'ai-draft', 'active', now(), now()),
    ('clf-c02-cc-v2-032', 'aws-clf', 'Cost Categories no AWS Cost Management servem para:', '[{"id":"A","text":"Agrupar dimensões de custo (contas, serviços, tags) em categorias lógicas customizadas (ex: ''Plataforma Pagamentos'', ''Marketing Stack'') para reports e Budgets"},{"id":"B","text":"Substituir o conceito de conta AWS"},{"id":"C","text":"Aplicar descontos automáticos"},{"id":"D","text":"Mover instâncias entre regiões"}]'::jsonb, 'A', '{"summary":"Cost Categories cria dimensões lógicas próprias para enxergar custo de jeitos que não dependem de hierarquia de contas/serviço.","whyCorrect":"Cost Categories permite definir regras (ex: ''se conta = X OU tag Product = checkout, então categoria = Pagamentos'') e usar essa categoria em Cost Explorer, Budgets e CUR. Resolve casos em que a estrutura organizacional não bate com a hierarquia de contas AWS.","whyWrong":{"B":"Não substitui conta — é camada lógica sobre contas e tags.","C":"Não aplica desconto — apenas agrupa custo.","D":"Não move recursos."},"keyConcept":"Cost Categories — lógicas custom de agrupamento","compareWith":["Cost Allocation Tags","Cost Categories","Organizational Units"]}'::jsonb, 'Cloud Concepts', 'Cloud Concepts', 'hard', 'recall', '["finops","cost-categories"]'::jsonb, 'ai-draft', 'active', now(), now()),
    ('clf-c02-cc-v2-033', 'aws-clf', 'Uma empresa precisa ter dados de cidadãos UE armazenados fisicamente no continente europeu por GDPR. Qual critério de seleção de Region é mais relevante?', '[{"id":"A","text":"Compliance & data residency — escolher região europeia (eu-central-1, eu-west-1, etc.) que ofereça residência de dados"},{"id":"B","text":"Escolher a região mais barata globalmente"},{"id":"C","text":"Escolher a região com mais serviços em GA"},{"id":"D","text":"Escolher a região mais recente lançada"}]'::jsonb, 'A', '{"summary":"GDPR/LGPD/data residency dominam a decisão quando há requisito legal.","whyCorrect":"Region selection tem 5 fatores: latência, custo, compliance, features disponíveis, sustainability. Em casos de regulação (GDPR), compliance/data residency é hard constraint — outros fatores são secundários. Dados em região UE são pré-requisito legal.","whyWrong":{"B":"Custo é fator, mas não passa por cima de obrigação legal.","C":"Disponibilidade de serviços importa para arquitetura, não para residência.","D":"Idade da região é irrelevante; algumas regiões antigas são as melhores escolhas."},"keyConcept":"Region selection — 5 fatores","compareWith":["Latência","Custo","Compliance","Features","Sustainability"],"realWorldContext":"Empresas SaaS oferecem ''EU-only deployment'' como SKU separado para clientes regulados."}'::jsonb, 'Cloud Concepts', 'Cloud Concepts', 'easy', 'scenario', '["global-infrastructure","region-selection","compliance"]'::jsonb, 'ai-draft', 'active', now(), now()),
    ('clf-c02-cc-v2-034', 'aws-clf', 'Qual é a diferença correta entre Availability Zone (AZ), Local Zone (LZ) e Wavelength Zone (WL)?', '[{"id":"A","text":"AZ = data center isolado dentro de uma região (sub-ms entre AZs); LZ = extensão metropolitana para latência ultra-baixa em metrópoles (sub-10ms ao usuário); WL = AZ embutido na rede 5G de telecoms (ultra-baixa latência mobile)"},{"id":"B","text":"Todos são sinônimos"},{"id":"C","text":"AZ é em satélite; LZ é submarino; WL é em terra"},{"id":"D","text":"AZ é só compute; LZ é só storage; WL é só database"}]'::jsonb, 'A', '{"summary":"AZ é o tijolo base regional; LZ aproxima compute/storage de metrópoles; WL coloca compute dentro da rede 5G.","whyCorrect":"Cada uma resolve um problema de latência diferente. AZ = isolamento de falha + sub-ms para HA intra-region. LZ (ex: LA, Boston, Miami) = colocar compute/storage perto de usuário em cidade sem região (sub-10ms). WL = compute integrada à rede 5G da Verizon/Vodafone/KDDI — ideal para AR/VR mobile, gaming low-latency.","whyWrong":{"B":"São conceitos distintos com propósitos distintos.","C":"Nenhum é satélite/submarino — todos são infra terrestre.","D":"Todos oferecem compute + storage (não exclusivos por serviço)."},"keyConcept":"Global Infrastructure — AZ vs LZ vs WL","compareWith":["AZ (sub-ms intra-region)","LZ (sub-10ms metro)","WL (5G mobile)"],"realWorldContext":"Netflix/Disney usam LZ para reduzir latência em mercados sem região; gaming usa WL via parceria com operadoras 5G."}'::jsonb, 'Cloud Concepts', 'Cloud Concepts', 'medium', 'recall', '["global-infrastructure","az","local-zones","wavelength"]'::jsonb, 'ai-draft', 'active', now(), now()),
    ('clf-c02-cc-v2-035', 'aws-clf', 'AWS Outposts entrega:', '[{"id":"A","text":"Hardware AWS gerenciado dentro do data center do cliente (on-prem), permitindo rodar serviços AWS (EC2, EBS, RDS) localmente com a mesma API/consistência da cloud"},{"id":"B","text":"Backup grátis ilimitado"},{"id":"C","text":"Cluster de Kubernetes gratuito"},{"id":"D","text":"VPN automática para todos"}]'::jsonb, 'A', '{"summary":"Outposts é hardware AWS instalado no DC do cliente — cloud APIs operando on-prem para baixa latência ou data residency local.","whyCorrect":"Outposts vem como rack(s) entregue(s) e instalado(s) pela AWS no DC do cliente. Você usa as mesmas APIs (EC2, EBS, S3 on Outposts, RDS) que na cloud, controlado pelo control plane regional. Casos típicos: latência sub-ms a sistemas legados, data residency super-estrita (sem internet permitida).","whyWrong":{"B":"Outposts não é backup nem gratuito — tem custo recorrente significativo.","C":"EKS pode rodar em Outposts, mas Outposts não é ''Kubernetes grátis''.","D":"Não é serviço de VPN."},"keyConcept":"Hybrid — Outposts (AWS no on-prem)","compareWith":["Outposts (hardware on-prem)","Wavelength (5G)","Local Zones (metro)"],"realWorldContext":"Hospitais, plantas industriais e exchanges financeiras usam Outposts quando latência ou compliance proíbem ir para Region."}'::jsonb, 'Cloud Concepts', 'Cloud Concepts', 'medium', 'recall', '["global-infrastructure","outposts","hybrid"]'::jsonb, 'ai-draft', 'active', now(), now()),
    ('clf-c02-cc-v2-036', 'aws-clf', 'Qual é a diferença prática entre Outposts e Wavelength?', '[{"id":"A","text":"Outposts vive dentro do DC do cliente; Wavelength vive dentro do data center da operadora de telecom 5G, otimizado para aplicações mobile com latência ultra-baixa"},{"id":"B","text":"Outposts é só em satélite; Wavelength é em terra"},{"id":"C","text":"Outposts é gratuito; Wavelength cobra USD 1/mês"},{"id":"D","text":"Outposts é só para banco; Wavelength é só para varejo"}]'::jsonb, 'A', '{"summary":"Outposts vai no DC do cliente; Wavelength vai no DC da operadora 5G (Verizon, Vodafone, etc.).","whyCorrect":"Ambos são extensões da AWS, mas localizações distintas: Outposts atende cenários on-prem (latência a sistemas locais, residência de dados); Wavelength atende mobile/5G (apps em smartphones precisam de latência sub-10ms ao backend — colocar backend dentro da rede 5G da operadora elimina hops).","whyWrong":{"B":"Nenhum é satélite — Outposts e WL são instalações físicas terrestres.","C":"Ambos têm custo; nenhum é gratuito.","D":"Não há restrição por setor."},"keyConcept":"Outposts vs Wavelength — local of placement","compareWith":["Outposts (customer DC)","Wavelength (telco DC)"],"realWorldContext":"AR/VR mobile, gaming online e edge AI mobile são casos típicos de Wavelength."}'::jsonb, 'Cloud Concepts', 'Cloud Concepts', 'hard', 'scenario', '["global-infrastructure","outposts","wavelength"]'::jsonb, 'ai-draft', 'active', now(), now()),
    ('clf-c02-cc-v2-037', 'aws-clf', 'AWS Local Zones (ex: us-west-2-lax-1a em Los Angeles) são úteis principalmente quando:', '[{"id":"A","text":"O usuário final está numa metrópole sem Region completa próxima e precisa latência sub-10ms a serviços de compute/storage (ex: media editing, real-time gaming, ML inference local)"},{"id":"B","text":"Precisa de backup off-site barato"},{"id":"C","text":"Quer rodar batch noturno barato"},{"id":"D","text":"Precisa de auto-scaling tradicional"}]'::jsonb, 'A', '{"summary":"Local Zone aproxima compute/storage ao usuário urbano, alcançando sub-10ms onde a Region mais próxima ficaria a 30-50ms.","whyCorrect":"Local Zones existem em cidades como LA, Boston, Miami, Houston, etc. Cada uma é como uma extensão da region pai (us-west-2 para LAX). Ideal para workloads sensíveis a latência local: edição de vídeo colaborativa, gaming, ML inference em dispositivos da metrópole.","whyWrong":{"B":"Backup off-site é caso de S3 cross-region ou Glacier — LZ é caro para isso.","C":"Batch noturno é insensível a latência — usar Region é mais barato.","D":"Auto-scaling funciona em Region; não é diferencial da LZ."},"keyConcept":"Local Zones — latência metro","compareWith":["AZ (intra-region)","Local Zone (metro)","Wavelength (5G)"],"realWorldContext":"Estúdios em Hollywood usam us-west-2-lax para edição de vídeo colaborativa em tempo real."}'::jsonb, 'Cloud Concepts', 'Cloud Concepts', 'medium', 'scenario', '["global-infrastructure","local-zones"]'::jsonb, 'ai-draft', 'active', now(), now()),
    ('clf-c02-cc-v2-038', 'aws-clf', 'Quantas Availability Zones, no mínimo, cada AWS Region tem?', '[{"id":"A","text":"3 AZs isoladas fisicamente (geralmente, mínimo de 3 para resiliência)"},{"id":"B","text":"1 AZ por Region"},{"id":"C","text":"100 AZs por Region"},{"id":"D","text":"AZs são opcionais e podem não existir"}]'::jsonb, 'A', '{"summary":"Cada Region AWS tem no mínimo 3 AZs isoladas (algumas têm 6+).","whyCorrect":"AWS exige mínimo de 3 AZs por Region para viabilizar quorum-based replication (databases distribuídos), HA real e tolerância a falha de AZ inteira. Algumas Regions (us-east-1, eu-west-1) têm 6+ AZs.","whyWrong":{"B":"1 AZ por Region seria SPOF — não é o design AWS.","C":"Nenhuma Region tem 100 AZs; é número exagerado.","D":"AZs são o tijolo fundamental — sempre existem."},"keyConcept":"Global Infrastructure — AZ count per Region","compareWith":["3 AZs (mínimo)","Multi-AZ services (RDS, ELB)"]}'::jsonb, 'Cloud Concepts', 'Cloud Concepts', 'easy', 'recall', '["global-infrastructure","az"]'::jsonb, 'ai-draft', 'active', now(), now()),
    ('clf-c02-cc-v2-039', 'aws-clf', 'Edge Locations (CloudFront PoPs) servem para:', '[{"id":"A","text":"Cache de conteúdo e terminação TLS próximos ao usuário final, melhorando latência e reduzindo carga em origem"},{"id":"B","text":"Hospedar bancos de dados primários"},{"id":"C","text":"Rodar workloads de ML training"},{"id":"D","text":"Substituir AZs"}]'::jsonb, 'A', '{"summary":"Edge Locations são PoPs do CloudFront/Route 53/Global Accelerator — caching + DNS + entrada de tráfego perto do usuário.","whyCorrect":"Edge Locations existem em 400+ cidades; CloudFront usa para servir conteúdo cacheado (imagens, vídeos, JS, JSON) próximos ao usuário. Beneficia latência (primeira resposta) e custo (menos egress da origem).","whyWrong":{"B":"Bancos primários ficam em Region (RDS, Aurora) — edge não tem capacidade nem propósito.","C":"ML training pesado roda em GPU clusters em Region, não no edge.","D":"Edge complementa AZs/Regions, não substitui."},"keyConcept":"Edge Locations — CloudFront PoPs","compareWith":["Region","AZ","Edge Location"],"realWorldContext":"Streaming (Netflix, Prime Video) e e-commerce dependem fortemente do edge para reduzir TTFB."}'::jsonb, 'Cloud Concepts', 'Cloud Concepts', 'easy', 'recall', '["global-infrastructure","edge","cloudfront"]'::jsonb, 'ai-draft', 'active', now(), now()),
    ('clf-c02-cc-v2-040', 'aws-clf', 'Uma empresa quer entender ''cloud computing service models''. Qual exemplo NÃO é representativo de PaaS (Platform as a Service) em AWS?', '[{"id":"A","text":"AWS Elastic Beanstalk"},{"id":"B","text":"AWS App Runner"},{"id":"C","text":"Amazon EC2"},{"id":"D","text":"AWS Lambda (na visão broad de PaaS / FaaS)"}]'::jsonb, 'C', '{"summary":"EC2 é IaaS clássico (instância de VM crua); Beanstalk/App Runner/Lambda são PaaS (deploy de código, AWS gerencia o resto).","whyCorrect":"EC2 expõe a VM diretamente — você gerencia SO, patching, runtime, scaling. É o exemplo canônico de IaaS na AWS. PaaS, por contraste, esconde o SO/runtime e foca em deploy de aplicação (Beanstalk faz isso para apps web; App Runner para containers; Lambda para funções).","whyWrong":{"A":"Beanstalk é PaaS — você faz upload do código (Java, Python, Node) e ele provisiona EC2+ELB+ASG por baixo. Exemplo válido.","B":"App Runner é PaaS para containers — você dá imagem, AWS gerencia tudo (rede, scaling, deploy).","D":"Lambda é frequentemente classificado como FaaS (subconjunto de PaaS na taxonomia ampla); válido como exemplo de ''gerenciado pela plataforma''."},"keyConcept":"Cloud service models — IaaS vs PaaS vs SaaS","compareWith":["EC2 (IaaS)","Beanstalk/App Runner/Lambda (PaaS)","WorkMail/Connect (SaaS)"],"realWorldContext":"Decisão típica: usar Beanstalk para acelerar deploy vs EC2 puro para controle granular."}'::jsonb, 'Cloud Concepts', 'Cloud Concepts', 'medium', 'scenario', '["service-models","iaas","paas"]'::jsonb, 'ai-draft', 'active', now(), now()),
    ('clf-c02-cc-v2-041', 'aws-clf', 'Qual exemplo de SaaS em AWS é correto?', '[{"id":"A","text":"Amazon WorkMail e Amazon Chime — software de produtividade entregue como serviço, sem você gerenciar infra"},{"id":"B","text":"Amazon EC2"},{"id":"C","text":"AWS Lambda"},{"id":"D","text":"Amazon VPC"}]'::jsonb, 'A', '{"summary":"WorkMail (email) e Chime (videoconferência) são software finais — o usuário consome o app, AWS gerencia tudo embaixo.","whyCorrect":"SaaS = software pronto para uso final, sem provisionar infra/runtime/deployment. WorkMail e Chime se enquadram (concorrem com Gmail/Zoom). Connect (call center) também é exemplo.","whyWrong":{"B":"EC2 é IaaS — você administra VM.","C":"Lambda é PaaS/FaaS — você administra código.","D":"VPC é IaaS de rede — infra crua."},"keyConcept":"Cloud service models — SaaS","compareWith":["WorkMail/Chime/Connect (SaaS)","Beanstalk (PaaS)","EC2 (IaaS)"]}'::jsonb, 'Cloud Concepts', 'Cloud Concepts', 'easy', 'recall', '["service-models","saas"]'::jsonb, 'ai-draft', 'active', now(), now()),
    ('clf-c02-cc-v2-042', 'aws-clf', 'Migrando de on-prem para IaaS na AWS, qual responsabilidade do cliente é a maior área de mudança comparada a SaaS?', '[{"id":"A","text":"Em IaaS o cliente ainda gerencia SO, patching, runtime, app, dados; em SaaS o cliente só gerencia configuração e dados próprios"},{"id":"B","text":"IaaS e SaaS têm o mesmo modelo de responsabilidade"},{"id":"C","text":"Em IaaS a AWS gerencia tudo até o app"},{"id":"D","text":"Em SaaS o cliente gerencia o kernel"}]'::jsonb, 'A', '{"summary":"Quanto mais ''as a Service'', menor a parcela do cliente: IaaS = muita responsabilidade; SaaS = quase nenhuma.","whyCorrect":"IaaS abstrai hardware/virtualização mas o cliente ainda mantém SO, patches, runtimes, app e dados. SaaS entrega tudo pronto — cliente só configura settings e gerencia seus dados/usuários. PaaS fica no meio (cliente gerencia código + dados; AWS gerencia SO/runtime).","whyWrong":{"B":"Modelos são distintos em responsabilidade — esse é um dos conceitos centrais.","C":"Em IaaS a AWS gerencia até hypervisor; SO e acima é com o cliente.","D":"Em SaaS o cliente não toca em kernel — só usa o software."},"keyConcept":"Service models — shared responsibility por camada","compareWith":["IaaS responsibility","PaaS responsibility","SaaS responsibility"]}'::jsonb, 'Cloud Concepts', 'Cloud Concepts', 'medium', 'best-practice', '["service-models","shared-responsibility"]'::jsonb, 'ai-draft', 'active', now(), now()),
    ('clf-c02-cc-v2-043', 'aws-clf', 'Qual exemplo abaixo é INCORRETO ao classificar serviço AWS em modelo de implantação cloud?', '[{"id":"A","text":"Cloud nativo: app feito 100% em AWS managed services (Lambda, DynamoDB, API Gateway)"},{"id":"B","text":"Hybrid: app que estende para AWS via Outposts ou Direct Connect mantendo parte on-prem"},{"id":"C","text":"On-prem only: app totalmente em DC físico próprio, sem nuvem"},{"id":"D","text":"Multi-cloud: apenas quando o app roda exclusivamente em mainframe"}]'::jsonb, 'D', '{"summary":"Multi-cloud = usar 2+ provedores cloud (AWS + Azure, ou AWS + GCP), nada a ver com mainframe.","whyCorrect":"A definição de Multi-cloud é distribuir cargas entre múltiplos provedores cloud para evitar lock-in, atender compliance, ou usar diferenciais (BigQuery no GCP + AWS para resto). ''Mainframe'' é hardware on-prem, oposto de cloud.","whyWrong":{"A":"Definição correta de cloud nativo.","B":"Definição correta de hybrid (cloud + on-prem coexistindo).","C":"Definição correta de on-prem only."},"keyConcept":"Deployment models — cloud / hybrid / on-prem / multi-cloud","compareWith":["Cloud-native","Hybrid","Multi-cloud"]}'::jsonb, 'Cloud Concepts', 'Cloud Concepts', 'medium', 'scenario', '["service-models","deployment-models"]'::jsonb, 'ai-draft', 'active', now(), now()),
    ('clf-c02-cc-v2-044', 'aws-clf', 'AWS Wavelength é particularmente útil para qual caso?', '[{"id":"A","text":"Aplicações mobile com latência ultra-baixa via 5G — AR/VR, gaming online, veículos autônomos conectados"},{"id":"B","text":"Backup off-site mensal"},{"id":"C","text":"Big Data analytics noturno"},{"id":"D","text":"Email corporativo"}]'::jsonb, 'A', '{"summary":"Wavelength integra compute AWS à rede 5G — reduz latência mobile-to-cloud para single-digit ms.","whyCorrect":"Em 5G, o gargalo de latência sai do core e vai para o backbone até a Region; Wavelength elimina esses hops colocando compute no edge da rede do telco. AR/VR mobile, gaming e veículos autônomos exigem essa latência ultra-baixa.","whyWrong":{"B":"Backup tolera segundos/minutos — Wavelength é overkill caro.","C":"Big Data noturno não é sensível a latência.","D":"Email é insensível a latência."},"keyConcept":"Wavelength — 5G edge compute","compareWith":["Wavelength","Local Zones","Outposts"]}'::jsonb, 'Cloud Concepts', 'Cloud Concepts', 'easy', 'scenario', '["global-infrastructure","wavelength","5g"]'::jsonb, 'ai-draft', 'active', now(), now()),
    ('clf-c02-cc-v2-045', 'aws-clf', 'Uma equipe precisa rodar workload com latência sub-ms entre componentes (HFT — high-frequency trading). Em vez de Multi-AZ, escolhem Cluster Placement Group dentro de uma AZ. Qual conceito justifica essa escolha?', '[{"id":"A","text":"Placement groups (Cluster) co-localizam instâncias em rack próximo dentro da AZ — minimiza latência inter-instância e maximiza throughput de rede"},{"id":"B","text":"Placement groups aumentam o tamanho de disco"},{"id":"C","text":"Placement groups dão desconto financeiro automático"},{"id":"D","text":"Placement groups movem instâncias para outra Region"}]'::jsonb, 'A', '{"summary":"Cluster Placement Group co-localiza instâncias em hardware próximo dentro da mesma AZ — latência mínima e bandwidth máximo.","whyCorrect":"Para HFT, HPC, ML training cluster, latência inter-nó é crítica. Cluster Placement Group instrui a AWS a alocar as instâncias em rack próximo (mesmo data center hall) na mesma AZ, com até 100 Gbps de rede. Trade-off: aumenta risco se a AZ inteira falhar.","whyWrong":{"B":"Não tem relação com tamanho de disco — é colocação física.","C":"Não é mecanismo de pricing.","D":"Não move entre regions — opera dentro de AZ."},"keyConcept":"Placement Groups — Cluster vs Spread vs Partition","compareWith":["Cluster (low latency)","Spread (anti-affinity)","Partition (big data)"],"realWorldContext":"HFT e ML training de modelos grandes (LLMs) dependem fortemente de Cluster Placement."}'::jsonb, 'Cloud Concepts', 'Cloud Concepts', 'hard', 'scenario', '["global-infrastructure","placement-groups"]'::jsonb, 'ai-draft', 'active', now(), now()),
    ('clf-c02-cc-v2-046', 'aws-clf', 'Qual afirmação sobre AWS Region pairs (regiões geograficamente próximas) é correta?', '[{"id":"A","text":"AWS oferece pares de regiões frequentemente usadas em conjunto para DR — ex: us-east-1 ↔ us-west-2, eu-west-1 ↔ eu-central-1, sa-east-1 ↔ us-east-1 — com latência conhecida e replicação otimizada"},{"id":"B","text":"Todas as regiões AWS são automaticamente pareadas 1:1 e fundidas operacionalmente"},{"id":"C","text":"Regions pairs implicam failover automático sem configuração do cliente"},{"id":"D","text":"Region pair é o mesmo que AZ pair"}]'::jsonb, 'A', '{"summary":"Region pairs são pares populares para DR, mas o cliente que escolhe e configura o pareamento; não é automático.","whyCorrect":"Não existe ''pair oficial'' obrigatório como no Azure, mas há pares praticados pelo mercado por latência/compliance (us-east-1 ↔ us-west-2 nos EUA; sa-east-1 ↔ us-east-1 para BR). O cliente é responsável por configurar a replicação.","whyWrong":{"B":"Regions são isoladas por design; não há fusão automática.","C":"Failover é responsabilidade do cliente — configurar Route 53 health checks, replicação, runbooks.","D":"Region pair é entre regions (geograficamente distantes); AZ é dentro de region (sub-ms)."},"keyConcept":"Region pairs — DR pattern (cliente-driven)","compareWith":["Multi-AZ","Multi-Region","Region pair (convenção)"]}'::jsonb, 'Cloud Concepts', 'Cloud Concepts', 'hard', 'best-practice', '["global-infrastructure","region-pairs","dr"]'::jsonb, 'ai-draft', 'active', now(), now()),
    ('clf-c02-cc-v2-047', 'aws-clf', 'Uma empresa brasileira atende usuários BR e Argentina. Em qual região AWS é mais aderente colocar workload primário considerando latência regional?', '[{"id":"A","text":"sa-east-1 (São Paulo) — mais próxima geográfica, latência aceitável para BR e AR"},{"id":"B","text":"ap-northeast-1 (Tokyo)"},{"id":"C","text":"eu-north-1 (Estocolmo)"},{"id":"D","text":"af-south-1 (Cape Town)"}]'::jsonb, 'A', '{"summary":"sa-east-1 é a região AWS mais próxima de usuários no Brasil e Argentina.","whyCorrect":"sa-east-1 (São Paulo) entrega ~20ms para BR e ~40ms para AR. Alternativas no Hemisfério Norte ou Oriente adicionam 100-300ms RTT — degradação severa de UX.","whyWrong":{"B":"Tokyo está a >250ms do BR — inviável para apps interativos.","C":"Estocolmo a 200ms+ do BR — também inviável.","D":"Cape Town tem latência razoável (~150ms BR), mas pior que sa-east-1."},"keyConcept":"Region selection — latência geográfica","compareWith":["sa-east-1 (BR)","us-east-1 (US East)","eu-west-1 (EU)"]}'::jsonb, 'Cloud Concepts', 'Cloud Concepts', 'easy', 'scenario', '["global-infrastructure","region-selection"]'::jsonb, 'ai-draft', 'active', now(), now()),
    ('clf-c02-cc-v2-048', 'aws-clf', 'Sobre seleção de Region considerando ''feature availability'', qual afirmação é correta?', '[{"id":"A","text":"Nem todos os serviços AWS lançam simultaneamente em todas as regiões — alguns serviços novos podem demorar meses/anos para chegar em regiões menores, impactando arquitetura"},{"id":"B","text":"Todos os serviços AWS estão sempre disponíveis em todas as regiões no dia do lançamento"},{"id":"C","text":"Region selection nunca depende de features"},{"id":"D","text":"Serviços AWS só funcionam em us-east-1"}]'::jsonb, 'A', '{"summary":"Feature parity entre regions varia — us-east-1 e us-west-2 recebem novidades primeiro; regiões menores demoram.","whyCorrect":"us-east-1 (Virginia) é a ''home region'' onde quase tudo lança primeiro; outras regiões grandes (us-west-2, eu-west-1) seguem em meses; regiões menores (sa-east-1, ap-south-1) podem levar mais tempo. Isso é critério real em region selection — workload que precisa de X feature pode forçar escolha de region específica.","whyWrong":{"B":"Falso — disparidade é fato conhecido.","C":"Feature availability é um dos 5 critérios canônicos de region selection.","D":"Múltiplas regiões oferecem serviços; us-east-1 é só uma delas."},"keyConcept":"Region selection — feature availability","compareWith":["Latência","Custo","Compliance","Features","Sustainability"],"realWorldContext":"Bedrock e novidades de IA lançam primeiro em us-east-1/us-west-2; clientes BR precisam decidir entre latência e features novas."}'::jsonb, 'Cloud Concepts', 'Cloud Concepts', 'medium', 'best-practice', '["global-infrastructure","region-selection","feature-parity"]'::jsonb, 'ai-draft', 'active', now(), now()),
    ('clf-c02-cc-v2-049', 'aws-clf', 'O AWS Cloud Adoption Framework (CAF) é organizado em 6 perspectivas. Qual delas trata de governança, riscos, conformidade e auditoria?', '[{"id":"A","text":"Governance Perspective"},{"id":"B","text":"Business Perspective"},{"id":"C","text":"Platform Perspective"},{"id":"D","text":"Operations Perspective"}]'::jsonb, 'A', '{"summary":"CAF tem 6 perspectivas: Business, People, Governance, Platform, Security, Operations. Governance cobre risco, compliance, controle financeiro.","whyCorrect":"Governance Perspective trata diretamente de portfolio management, AWS Organizations, risk management, finance, data management — temas de governança corporativa.","whyWrong":{"B":"Business Perspective foca em valor de negócio, ROI, alinhamento de produto.","C":"Platform Perspective trata de arquitetura, padrões técnicos, modernização.","D":"Operations Perspective trata de runbooks, observabilidade, incident response."},"keyConcept":"AWS CAF — 6 perspectives","compareWith":["Business","People","Governance","Platform","Security","Operations"]}'::jsonb, 'Cloud Concepts', 'Cloud Concepts', 'easy', 'recall', '["caf","perspectives"]'::jsonb, 'ai-draft', 'active', now(), now()),
    ('clf-c02-cc-v2-050', 'aws-clf', 'Qual perspectiva do AWS CAF é a mais alinhada com programa de upskilling/reskilling dos funcionários, criação de Cloud Center of Excellence (CCoE) e mudança cultural?', '[{"id":"A","text":"People Perspective"},{"id":"B","text":"Security Perspective"},{"id":"C","text":"Platform Perspective"},{"id":"D","text":"Operations Perspective"}]'::jsonb, 'A', '{"summary":"People Perspective cobre cultura, organização, treinamento, mudança — o lado humano da adoção.","whyCorrect":"People Perspective inclui capabilities: culture, organization design, transformation leadership, workforce transformation. Programas de upskilling e formação de CCoE caem aqui literalmente.","whyWrong":{"B":"Security trata de IAM, threat detection, compliance técnica — não cultura/treinamento amplo.","C":"Platform é arquitetura técnica, não cultura.","D":"Operations é processos operacionais, não jornada do funcionário."},"keyConcept":"AWS CAF — People Perspective","compareWith":["People (cultura)","Governance (risco)","Operations (processos)"],"realWorldContext":"Programas como AWS Skill Builder, AWS Academy e formação de CCoE são execução direta dessa perspectiva."}'::jsonb, 'Cloud Concepts', 'Cloud Concepts', 'easy', 'scenario', '["caf","people"]'::jsonb, 'ai-draft', 'active', now(), now()),
    ('clf-c02-cc-v2-051', 'aws-clf', 'Uma equipe pergunta como modernizar arquitetura, adotar IaC, definir padrões de microservices. Qual perspectiva do CAF é mais aderente?', '[{"id":"A","text":"Platform Perspective"},{"id":"B","text":"People Perspective"},{"id":"C","text":"Business Perspective"},{"id":"D","text":"Security Perspective"}]'::jsonb, 'A', '{"summary":"Platform Perspective trata de plataforma técnica: arquitetura, padrões de modernização, IaC, CI/CD.","whyCorrect":"Platform Perspective inclui capabilities: platform architecture, data architecture, platform engineering, modern application development. IaC, microservices patterns, plataforma de developers caem aqui.","whyWrong":{"B":"People é cultura.","C":"Business é valor para o negócio, ROI.","D":"Security é controles de segurança."},"keyConcept":"AWS CAF — Platform Perspective","compareWith":["Platform (técnico)","Operations (operacional)"]}'::jsonb, 'Cloud Concepts', 'Cloud Concepts', 'easy', 'scenario', '["caf","platform"]'::jsonb, 'ai-draft', 'active', now(), now()),
    ('clf-c02-cc-v2-052', 'aws-clf', 'O CAF descreve estágios de maturidade de adoção. Qual sequência é correta?', '[{"id":"A","text":"Envision → Align → Launch → Scale"},{"id":"B","text":"Build → Deploy → Operate → Retire"},{"id":"C","text":"Plan → Code → Test → Ship"},{"id":"D","text":"Buy → Train → Migrate → Sunset"}]'::jsonb, 'A', '{"summary":"CAF Transformation Phases: Envision (visão), Align (alinhar capabilities), Launch (pilotos), Scale (escalar pela organização).","whyCorrect":"Esses são os 4 estágios oficiais de transformação no CAF — começa identificando oportunidades, alinha as 6 perspectivas, executa pilotos para validar, e escala lições aprendidas em larga escala.","whyWrong":{"B":"Build/Deploy/Operate/Retire é ciclo de vida de software, não fases CAF.","C":"Plan/Code/Test/Ship é DevOps, não CAF.","D":"Não é terminologia CAF."},"keyConcept":"AWS CAF — Transformation Phases","compareWith":["Envision","Align","Launch","Scale"]}'::jsonb, 'Cloud Concepts', 'Cloud Concepts', 'hard', 'recall', '["caf","transformation-phases"]'::jsonb, 'ai-draft', 'active', now(), now()),
    ('clf-c02-cc-v2-053', 'aws-clf', 'Qual afirmação sobre Security Perspective do CAF é correta?', '[{"id":"A","text":"Trata de controles de segurança (IAM, threat detection, response, compliance) como capability transversal à transformação cloud"},{"id":"B","text":"É exclusivamente sobre firewall físico"},{"id":"C","text":"Trata apenas de backup de dados"},{"id":"D","text":"Não está incluída no CAF"}]'::jsonb, 'A', '{"summary":"Security Perspective cobre identidade, detecção, resposta, controles preventivos — visão holística de segurança.","whyCorrect":"Security Perspective inclui capabilities: identity and access, threat detection, infrastructure protection, data protection, incident response, application security. É uma das 6 perspectivas oficiais.","whyWrong":{"B":"Firewall físico é pequeno subset; perspective é muito mais ampla.","C":"Backup é capability menor; perspective cobre muito mais.","D":"Está sim incluída — é uma das 6 perspectivas."},"keyConcept":"AWS CAF — Security Perspective"}'::jsonb, 'Cloud Concepts', 'Cloud Concepts', 'easy', 'recall', '["caf","security"]'::jsonb, 'ai-draft', 'active', now(), now()),
    ('clf-c02-cc-v2-054', 'aws-clf', 'Operations Perspective do CAF trata especificamente de:', '[{"id":"A","text":"Capabilities operacionais: observability, event management, incident/problem management, performance/capacity management, application performance monitoring"},{"id":"B","text":"Apenas treinamento de funcionários"},{"id":"C","text":"Apenas compliance de auditoria"},{"id":"D","text":"Apenas escolha de instance type"}]'::jsonb, 'A', '{"summary":"Operations Perspective é o ''como manter saudável em produção'' — observabilidade, incidente, capacidade.","whyCorrect":"Operations Perspective define capabilities operacionais para garantir disponibilidade e qualidade de serviço em produção: observability, event/incident/problem/change management, performance, continuity.","whyWrong":{"B":"Treinamento é People Perspective.","C":"Compliance é Governance Perspective.","D":"Escolha de instance é parte de Platform Perspective."},"keyConcept":"AWS CAF — Operations Perspective"}'::jsonb, 'Cloud Concepts', 'Cloud Concepts', 'medium', 'recall', '["caf","operations"]'::jsonb, 'ai-draft', 'active', now(), now()),
    ('clf-c02-cc-v2-055', 'aws-clf', 'Business Perspective no CAF tem qual foco principal?', '[{"id":"A","text":"Garantir que investimentos em cloud entreguem outcomes mensuráveis de negócio (receita, custo, time-to-market), alinhando estratégia + portfolio + investment management"},{"id":"B","text":"Configurar IAM users"},{"id":"C","text":"Escolher instance type"},{"id":"D","text":"Definir SCPs"}]'::jsonb, 'A', '{"summary":"Business Perspective conecta cloud a outcomes de negócio: KPIs, portfolio, value realization, estratégia.","whyCorrect":"Capabilities: strategy management, portfolio management, innovation management, product management, strategic partnerships, data monetization, business insights. Foco em valor.","whyWrong":{"B":"IAM é Security Perspective.","C":"Instance choice é Platform.","D":"SCPs é Governance/Security."},"keyConcept":"AWS CAF — Business Perspective"}'::jsonb, 'Cloud Concepts', 'Cloud Concepts', 'medium', 'recall', '["caf","business"]'::jsonb, 'ai-draft', 'active', now(), now()),
    ('clf-c02-cc-v2-056', 'aws-clf', 'Uma estratégia de DR define RTO de 4 horas e RPO de 1 hora. Qual padrão DR é o melhor encaixe (sem over-engineering)?', '[{"id":"A","text":"Pilot Light — réplicas mínimas em outra region (DB replicado, app desligado); ao falhar, sobe capacidade rapidamente"},{"id":"B","text":"Backup & Restore — backups em outra region, restaurar do zero"},{"id":"C","text":"Warm Standby — cópia funcional reduzida sempre rodando"},{"id":"D","text":"Multi-Site Active-Active — duas regions em produção full simultaneamente"}]'::jsonb, 'A', '{"summary":"Pilot Light é o padrão para RTO horas + RPO sub-hora — DB replicado em standby, app desligado mas pronto para subir.","whyCorrect":"Pilot Light mantém os componentes críticos mínimos sempre rodando (banco com replicação contínua → RPO baixo) e desliga compute (app, workers). Em falha, sobe compute rapidamente — atinge RTO de horas. Mais barato que Warm Standby, mais rápido que Backup & Restore.","whyWrong":{"B":"Backup & Restore tipicamente RTO 24h+; não atende 4h sem rasgar o budget.","C":"Warm Standby atende RTO menor (minutos) mas é mais caro — over-engineering se 4h basta.","D":"Multi-Site Active-Active atende RTO < 1min e RPO próximo de zero; muito caro para RTO 4h."},"keyConcept":"DR strategies — 4 padrões oficiais","compareWith":["Backup & Restore (24h+)","Pilot Light (horas)","Warm Standby (minutos)","Active-Active (segundos)"],"realWorldContext":"Whitepaper oficial ''Disaster Recovery of Workloads on AWS'' formaliza esses 4 padrões.","tutorSeeds":["Como o DRS (Elastic Disaster Recovery) acelera pilot light?","Qual a diferença entre RTO e RPO?"]}'::jsonb, 'Cloud Concepts', 'Cloud Concepts', 'hard', 'scenario', '["dr","rto-rpo","pilot-light"]'::jsonb, 'ai-draft', 'active', now(), now()),
    ('clf-c02-cc-v2-057', 'aws-clf', 'Qual definição é correta para RTO e RPO?', '[{"id":"A","text":"RTO = tempo máximo aceitável para restaurar serviço após falha. RPO = janela máxima aceitável de perda de dados (tempo entre último backup e o evento)"},{"id":"B","text":"RTO e RPO são sinônimos"},{"id":"C","text":"RTO = retention period; RPO = retention period offset"},{"id":"D","text":"RTO é em USD; RPO é em latência"}]'::jsonb, 'A', '{"summary":"RTO = quão rápido recupera. RPO = quanto dado pode perder.","whyCorrect":"RTO (Recovery Time Objective) é tempo de downtime aceitável. RPO (Recovery Point Objective) é a quantidade de dados que podemos perder, medida em tempo. Backup a cada 1h → RPO máximo 1h. São conceitos ortogonais e ambos guiam escolha de padrão DR.","whyWrong":{"B":"São distintos.","C":"Retention é período de retenção de backup — conceito diferente.","D":"Não são em USD nem latência."},"keyConcept":"DR — RTO vs RPO","compareWith":["RTO (downtime)","RPO (data loss window)","MTTR (mean time to recover)"]}'::jsonb, 'Cloud Concepts', 'Cloud Concepts', 'easy', 'recall', '["dr","rto-rpo"]'::jsonb, 'ai-draft', 'active', now(), now()),
    ('clf-c02-cc-v2-058', 'aws-clf', 'Uma fintech crítica precisa RTO < 1 minuto e RPO próximo de zero para o core bancário. Qual estratégia DR é a adequada?', '[{"id":"A","text":"Multi-Site Active-Active — ambas regions operam em produção; falha em uma é absorvida pela outra com falha-over instantâneo via Route 53"},{"id":"B","text":"Backup & Restore com snapshots semanais"},{"id":"C","text":"Pilot Light"},{"id":"D","text":"Snapshot diário via Backup"}]'::jsonb, 'A', '{"summary":"Multi-Site Active-Active é o único padrão que entrega RTO < 1 min e RPO ~ 0 — preço: complexidade e custo dobrados.","whyCorrect":"Em Active-Active, ambas regions atendem tráfego em produção (load balanced via Route 53 ou Global Accelerator). Em falha de uma, a outra absorve tráfego sem precisar ''subir'' nada — RTO é o tempo de DNS/health check (~30s). Replicação síncrona/quasi-síncrona alcança RPO próximo a zero.","whyWrong":{"B":"Backup semanal teria RPO de até 7 dias — incompatível com fintech.","C":"Pilot Light tem RTO de horas; não atende 1 min.","D":"Snapshot diário = RPO até 24h."},"keyConcept":"DR — Multi-Site Active-Active","compareWith":["Pilot Light","Warm Standby","Active-Active"],"realWorldContext":"Bancos centrais, exchanges e pagamentos críticos justificam custo de Active-Active."}'::jsonb, 'Cloud Concepts', 'Cloud Concepts', 'medium', 'scenario', '["dr","multi-site","active-active"]'::jsonb, 'ai-draft', 'active', now(), now()),
    ('clf-c02-cc-v2-059', 'aws-clf', 'Qual diferença prática entre Pilot Light e Warm Standby?', '[{"id":"A","text":"Pilot Light mantém apenas core mínimo rodando (DB replicado, compute desligado); Warm Standby mantém uma cópia funcional reduzida em escala (DB + algumas instâncias ativas), pronta para escalar imediatamente"},{"id":"B","text":"São sinônimos exatos"},{"id":"C","text":"Pilot Light é cross-cloud; Warm Standby é dentro de uma region"},{"id":"D","text":"Pilot Light é só Lambda; Warm Standby é só EC2"}]'::jsonb, 'A', '{"summary":"Pilot Light = compute desligado; Warm Standby = compute reduzido sempre ativo. Diferença é tempo de start.","whyCorrect":"Pilot Light tem RTO maior (precisa subir compute do zero, talvez 30-60 min); Warm Standby tem RTO menor (poucos minutos para escalar de tamanho reduzido para full). Warm Standby custa mais (compute rodando idle), mas dispensa procedimento de boot.","whyWrong":{"B":"São padrões distintos.","C":"Ambos são intra-AWS, geralmente entre regions.","D":"Não há limitação por tipo de compute."},"keyConcept":"DR — escala dos componentes em standby","compareWith":["Pilot Light (RTO horas)","Warm Standby (RTO minutos)"]}'::jsonb, 'Cloud Concepts', 'Cloud Concepts', 'hard', 'recall', '["dr","pilot-light","warm-standby"]'::jsonb, 'ai-draft', 'active', now(), now()),
    ('clf-c02-cc-v2-060', 'aws-clf', 'AWS Elastic Disaster Recovery (DRS) é positionado para qual cenário?', '[{"id":"A","text":"Implementar Pilot Light/Warm Standby para servers (físicos, virtuais ou EC2) com replicação contínua block-level para uma region de recovery, e failover em minutos"},{"id":"B","text":"Substituir IAM"},{"id":"C","text":"Backup de S3 objects apenas"},{"id":"D","text":"Migrar de Oracle para PostgreSQL"}]'::jsonb, 'A', '{"summary":"DRS replica continuamente servers para AWS e habilita failover/recovery em minutos.","whyCorrect":"DRS (antigo CloudEndure Disaster Recovery) replica volumes em block-level para storage staging em AWS; em falha do source, instanciações EC2 são lançadas no target em minutos — atendendo Pilot Light/Warm Standby. Suporta source on-prem, em outras clouds, ou EC2.","whyWrong":{"B":"Não substitui IAM (gestão de identidade).","C":"S3 backup é AWS Backup; DRS é para servers.","D":"Mudança de engine de DB é SCT + DMS."},"keyConcept":"DR tooling — AWS Elastic Disaster Recovery (DRS)","compareWith":["DRS (DR)","MGN (migração one-time)","AWS Backup (snapshot)"]}'::jsonb, 'Cloud Concepts', 'Cloud Concepts', 'medium', 'scenario', '["dr","drs","elastic-disaster-recovery"]'::jsonb, 'ai-draft', 'active', now(), now()),
    ('clf-c02-cc-v2-061', 'aws-clf', 'Uma empresa migrou para AWS e descobre que custos crescem 15% ao mês sem crescimento equivalente de receita. Ao investigar, encontram instâncias zombie (idle 0% CPU 24/7) e volumes EBS unattached. Qual prática é a aplicação direta de cloud economics nesse cenário?', '[{"id":"A","text":"Eliminar capacity idle — recursos não utilizados em cloud ainda geram custo (diferente de DC físico onde idle apenas desperdiça energia, não fatura)"},{"id":"B","text":"Manter os recursos pois ''já foram pagos''"},{"id":"C","text":"Não mexer porque a empresa tem Reserved Instances"},{"id":"D","text":"Migrar para multi-cloud para diluir custo"}]'::jsonb, 'A', '{"summary":"Em cloud, recurso idle continua faturando — diferente do CapEx on-prem que é sunk cost. Eliminação é ação direta de economics.","whyCorrect":"On-prem, hardware idle desperdiça energia mas não cobra hora a hora; cloud cobra por tempo provisionado independente de uso. Idle = perda direta de dinheiro. Identificar (Trusted Advisor, Cost Explorer) e eliminar é uma das primeiras ações de FinOps.","whyWrong":{"B":"Cloud não tem ''já foram pagos'' — pay-as-you-go.","C":"RI cobre baseline; idle gera waste mesmo com RI (você paga RI E não usa).","D":"Multi-cloud aumenta complexidade, não resolve idle."},"keyConcept":"Cloud economics — eliminar idle capacity","compareWith":["On-prem (CapEx sunk cost)","Cloud (OpEx contínuo)"],"realWorldContext":"Trusted Advisor ''Idle Load Balancers'' e ''Unattached EBS'' são checks gratuitos comuns."}'::jsonb, 'Cloud Concepts', 'Cloud Concepts', 'easy', 'scenario', '["cloud-economics","idle-capacity"]'::jsonb, 'ai-draft', 'active', now(), now()),
    ('clf-c02-cc-v2-062', 'aws-clf', 'O princípio de ''economies of scale'' aplicado à AWS significa que:', '[{"id":"A","text":"Como AWS atende milhões de clientes, seu custo unitário (servidor, rede, energia) é menor que o de qualquer cliente individual — esse desconto é repassado em preços que tendem a cair ao longo do tempo"},{"id":"B","text":"AWS dá desconto progressivo individual baseado em volume de cada cliente"},{"id":"C","text":"Quanto maior a empresa cliente, mais barato fica por hora"},{"id":"D","text":"AWS subsidiza clientes pequenos cobrando mais dos grandes"}]'::jsonb, 'A', '{"summary":"Economies of scale: AWS compra hardware/energia em escala global e repassa preço unitário baixo a todos os clientes.","whyCorrect":"AWS já fez 100+ reduções de preço desde 2006 — reflexo direto desse princípio. Fornecedores que tentassem replicar a infra AWS pagariam preço muito maior por servidor/kWh.","whyWrong":{"B":"Há descontos por commitment (RI, SP, EDP), mas o princípio de economies of scale fala do preço base de tabela, não desconto individual.","C":"Preço por hora é igual independente do tamanho do cliente (na tabela pública).","D":"AWS não subsidia entre clientes — é o mesmo preço público."},"keyConcept":"Cloud economics — economies of scale","compareWith":["Economies of scale (base price)","EDP (volume discount contratual)"]}'::jsonb, 'Cloud Concepts', 'Cloud Concepts', 'medium', 'recall', '["cloud-economics","economies-of-scale"]'::jsonb, 'ai-draft', 'active', now(), now()),
    ('clf-c02-cc-v2-063', 'aws-clf', 'Por que pay-as-you-go beneficia especialmente startups vs CapEx tradicional?', '[{"id":"A","text":"Elimina compra antecipada de capacidade; startup paga só pelo uso real e escala conforme tração — reduzindo investimento inicial e risco de over/under-provisioning"},{"id":"B","text":"Garante lucro à startup"},{"id":"C","text":"Pay-as-you-go é mais caro que CapEx em 100% dos casos"},{"id":"D","text":"Startups não devem usar cloud"}]'::jsonb, 'A', '{"summary":"Pay-as-you-go elimina barreira de entrada CapEx; startup começa com USD 100/mês e cresce com a receita.","whyCorrect":"Sem cloud, startup precisaria de USD 100k+ adiantados em servidores. Com cloud, paga USD 50-500/mês inicialmente e escala junto com clientes. Reduz risco financeiro e permite experimentar/pivotar sem hardware encalhado.","whyWrong":{"B":"Cloud não ''garante lucro'' — apenas reduz custo de infra inicial.","C":"Pay-as-you-go pode ser mais caro em workload estável de longo prazo (vs RI/SP); ''mais caro em 100% dos casos'' é falso.","D":"Absurdo — startups são os maiores beneficiários de cloud."},"keyConcept":"Cloud economics — pay-as-you-go e barreira de entrada","compareWith":["CapEx (compra antecipada)","OpEx (pago pelo uso)"]}'::jsonb, 'Cloud Concepts', 'Cloud Concepts', 'easy', 'scenario', '["cloud-economics","pay-as-you-go"]'::jsonb, 'ai-draft', 'active', now(), now()),
    ('clf-c02-cc-v2-064', 'aws-clf', 'Uma startup tem workload com pico de 1000 req/s à noite e 50 req/s de manhã. Qual prática de cloud economics endereça esse padrão?', '[{"id":"A","text":"Auto Scaling + Spot Instances para picos previsíveis — paga só pelo necessário em cada hora, evitando provisionar para o pior caso"},{"id":"B","text":"Provisionar 1000 req/s 24x7 para garantir performance"},{"id":"C","text":"Manter zero capacidade reserva"},{"id":"D","text":"Comprar Reserved Instance para o pico"}]'::jsonb, 'A', '{"summary":"Match supply to demand — Auto Scaling escala baseado em métricas; Spot reduz custo do pico variável.","whyCorrect":"Cloud economics prega ''match supply to demand''. Workload com variação 20x precisa de Auto Scaling para evitar pagar pico durante baseline. Spot complementa para picos previsíveis com custo reduzido.","whyWrong":{"B":"Provisionar pico 24x7 desperdiça 95% do tempo — anti-padrão de cloud economics.","C":"Zero reserva causa scaling lag — degradação de UX durante ramp up.","D":"RI para pico só faz sentido se o pico for previsível 24x7 — não é o caso."},"keyConcept":"Cloud economics — match supply to demand","compareWith":["Static provisioning","Auto Scaling","Spot Fleet"]}'::jsonb, 'Cloud Concepts', 'Cloud Concepts', 'medium', 'scenario', '["cloud-economics","auto-scaling","spot"]'::jsonb, 'ai-draft', 'active', now(), now()),
    ('clf-c02-cc-v2-065', 'aws-clf', 'Qual é o custo escondido mais comum de não fazer governança de cloud (Cost Optimization Hub + tagging) em empresas grandes?', '[{"id":"A","text":"Cloud sprawl — equipes provisionando recursos sem accountability, gerando 20-40% de desperdício invisível na fatura mensal"},{"id":"B","text":"AWS bloqueia novas contas automaticamente"},{"id":"C","text":"Tempo de boot da EC2 aumenta"},{"id":"D","text":"Não há custo escondido"}]'::jsonb, 'A', '{"summary":"Cloud sprawl é o crescimento descontrolado de recursos sem visibilidade — 20-40% de desperdício é típico em empresas sem FinOps.","whyCorrect":"Sem tagging + accountability, equipes provisionam recursos para testes, esquecem, deixam ligados. Sem cost attribution, ninguém é responsável. Estudos de FinOps Foundation mostram 20-40% de waste em empresas imaturas.","whyWrong":{"B":"AWS não bloqueia contas por falta de governança.","C":"Tempo de boot não tem relação com governança.","D":"Cloud sprawl é o custo escondido clássico — afirmar inexistência é falso."},"keyConcept":"Cloud economics — cloud sprawl","compareWith":["Cloud sprawl","FinOps governance","Tagging strategy"]}'::jsonb, 'Cloud Concepts', 'Cloud Concepts', 'medium', 'scenario', '["cloud-economics","cloud-sprawl"]'::jsonb, 'ai-draft', 'active', now(), now()),
    ('clf-c02-cc-v2-066', 'aws-clf', 'Qual é o efeito de longo prazo, segundo cloud economics, de migrar de DC próprio (CapEx pesado) para AWS (OpEx)?', '[{"id":"A","text":"Aumento de flexibilidade financeira e maior capacidade de experimentação — falhas são mais baratas (provisionar e desligar) e aprendizado acelera"},{"id":"B","text":"Perda total de controle sobre dados"},{"id":"C","text":"Custo sempre maior em qualquer cenário"},{"id":"D","text":"Empresa fica obrigada a usar apenas AWS para sempre"}]'::jsonb, 'A', '{"summary":"CapEx→OpEx libera capital + reduz custo de experimentação — efeito de longo prazo é cultura mais ágil.","whyCorrect":"Provisionar e descartar com cliques transforma economia de fail-fast. Em CapEx, errar significa hardware encalhado por anos. Em OpEx, errar é desligar a instância. Resultado: mais experimentos, mais inovação.","whyWrong":{"B":"Controle de dados continua do cliente (Shared Responsibility).","C":"Cenários têm trade-offs; nem sempre cloud é mais caro nem mais barato.","D":"Não há lock-in obrigatório — cliente pode migrar para outra cloud ou voltar para on-prem."},"keyConcept":"Cloud economics — CapEx vs OpEx (efeito cultural)","compareWith":["CapEx (compromisso longo)","OpEx (flexibilidade)"]}'::jsonb, 'Cloud Concepts', 'Cloud Concepts', 'medium', 'best-practice', '["cloud-economics","capex-opex","experimentation"]'::jsonb, 'ai-draft', 'active', now(), now()),
    ('clf-c02-cc-v2-067', 'aws-clf', 'Uma estratégia DR ''Backup & Restore'' é adequada para qual perfil de workload?', '[{"id":"A","text":"Workloads não-críticos (intranet interna, dev/test, relatórios mensais) onde RTO de 24h+ é aceitável e custo é prioridade"},{"id":"B","text":"Core bancário tier-1"},{"id":"C","text":"Trading platform de bolsa"},{"id":"D","text":"Sistema de prontuário hospitalar em UTI"}]'::jsonb, 'A', '{"summary":"Backup & Restore é mais barato mas RTO em horas/dia — só para workloads que toleram downtime longo.","whyCorrect":"Backup & Restore mantém só snapshots em outra region. Restaurar exige criar VPC, infra, banco do snapshot — leva horas. Aceitável para intranet, dev/test, BI mensal onde 24-48h de downtime não inviabiliza o negócio.","whyWrong":{"B":"Core bancário tier-1 exige Multi-Site Active-Active.","C":"Trading exige RTO de segundos — Active-Active.","D":"Prontuário UTI é tier-1 — RTO em horas inaceitável (risco de vida)."},"keyConcept":"DR — Backup & Restore (RTO em horas)","compareWith":["Backup & Restore","Pilot Light","Warm Standby","Active-Active"]}'::jsonb, 'Cloud Concepts', 'Cloud Concepts', 'easy', 'scenario', '["dr","backup-restore"]'::jsonb, 'ai-draft', 'active', now(), now()),
    ('clf-c02-cc-v2-068', 'aws-clf', 'Uma empresa adota DR Multi-Region usando read replicas cross-region do Aurora + S3 Cross-Region Replication + Route 53 com health checks. Qual padrão DR esse stack mais se aproxima?', '[{"id":"A","text":"Pilot Light ou Warm Standby — a depender de se há capacity de compute também rodando (warm) ou só DB replicado (pilot)"},{"id":"B","text":"Backup & Restore"},{"id":"C","text":"Single-Site Single-AZ"},{"id":"D","text":"Local Zones DR"}]'::jsonb, 'A', '{"summary":"Réplica contínua de dados + Route 53 com health checks é o padrão Pilot Light/Warm Standby (sem compute ativo = pilot; com compute ativo = warm).","whyCorrect":"Réplica de DB contínua atinge RPO baixo; Route 53 health check faz failover de DNS. Se compute estiver desligado no DR site = Pilot Light. Se compute estiver rodando em escala reduzida = Warm Standby. RTO típico: minutos a horas.","whyWrong":{"B":"Backup & Restore não usa replicação contínua; usa snapshots periódicos.","C":"Single-Site Single-AZ é o oposto de DR — sem redundância.","D":"Local Zones DR não é padrão DR clássico (LZ é para latência metro)."},"keyConcept":"DR padrões — identificar pela ferramenta","compareWith":["Pilot Light","Warm Standby"]}'::jsonb, 'Cloud Concepts', 'Cloud Concepts', 'hard', 'scenario', '["dr","pilot-light","warm-standby"]'::jsonb, 'ai-draft', 'active', now(), now()),
    ('clf-c02-cc-v2-069', 'aws-clf', 'Sobre a estratégia de migração ''Relocate'' (sétima R, oficial desde 2020), qual descrição é correta?', '[{"id":"A","text":"Mover infraestrutura virtualizada para AWS sem comprar hardware nem mudar OS (ex: VMware Cloud on AWS, vSphere → AWS sem refactor) — versão ainda mais ''lift'' que Rehost"},{"id":"B","text":"Sinônimo de Retire"},{"id":"C","text":"Mover dados entre buckets S3"},{"id":"D","text":"Sinônimo de Refactor"}]'::jsonb, 'A', '{"summary":"Relocate move VMs/clusters inteiros para AWS sem alterar hypervisor (VMware Cloud on AWS é caso clássico).","whyCorrect":"Relocate (7ª R) é mais ''lift'' ainda que Rehost — mantém até o hypervisor (VMware) operando dentro da AWS via VMware Cloud on AWS. Ideal para datacenters VMware que querem sair de hardware próprio mas não querem re-instanciar VMs em EC2.","whyWrong":{"B":"Retire é desligar, oposto.","C":"S3 transfer é DataSync, não migração de portfolio.","D":"Refactor é reescrever, oposto de relocate."},"keyConcept":"Migration — 7 Rs (Retire/Retain/Rehost/Relocate/Replatform/Repurchase/Refactor)","compareWith":["Rehost (EC2)","Relocate (VMware Cloud)"]}'::jsonb, 'Cloud Concepts', 'Cloud Concepts', 'hard', 'recall', '["migration","7rs","relocate"]'::jsonb, 'ai-draft', 'active', now(), now()),
    ('clf-c02-cc-v2-070', 'aws-clf', 'Uma empresa quer migrar 500GB de banco MySQL on-prem para RDS MySQL na AWS com downtime mínimo. Qual serviço é a escolha canônica?', '[{"id":"A","text":"AWS Database Migration Service (DMS) com CDC (change data capture) para sincronizar continuamente até o cutover"},{"id":"B","text":"AWS Snowball Edge"},{"id":"C","text":"AWS Direct Connect com cópia manual"},{"id":"D","text":"AWS S3 Glacier"}]'::jsonb, 'A', '{"summary":"DMS faz carga inicial + CDC contínuo — downtime de cutover cai para minutos.","whyCorrect":"DMS suporta full load + ongoing replication via CDC. Você liga DMS, ele copia 500GB iniciais, depois replica mudanças continuamente. Cutover: pausa app, espera DMS drenar, vira DNS para RDS. Downtime tipicamente sub-5min.","whyWrong":{"B":"Snowball Edge é para volumes massivos (TB-PB) sem conectividade; 500GB cabe em conexão normal e DMS.","C":"Direct Connect é conectividade dedicada, não ferramenta de migração de DB.","D":"Glacier é archive storage, não migração de DB."},"keyConcept":"Migration — DMS + CDC","compareWith":["DMS (DB)","MGN (server)","DataSync (file)"]}'::jsonb, 'Cloud Concepts', 'Cloud Concepts', 'medium', 'scenario', '["migration","dms","cdc"]'::jsonb, 'ai-draft', 'active', now(), now()),
    ('clf-c02-cc-v2-071', 'aws-clf', 'Uma empresa precisa mover 5 PB de dados de DC on-prem para S3 e tem apenas 100 Mbps de internet (transferência tomaria meses). Qual serviço resolve melhor?', '[{"id":"A","text":"AWS Snowball Edge ou Snowmobile — dispositivos físicos enviados ao cliente para copiar dados localmente e devolvidos à AWS"},{"id":"B","text":"AWS DataSync via internet"},{"id":"C","text":"Upload manual via console S3"},{"id":"D","text":"AWS Lambda"}]'::jsonb, 'A', '{"summary":"Para PBs com banda limitada, dispositivos físicos (Snow Family) são mais rápidos que internet.","whyCorrect":"Em 100 Mbps, 5 PB levaria ~12 anos. Snowball Edge (até 80 TB cada) ou Snowmobile (truck com 100 PB) movem dados em dias, não anos. AWS calcula tempo break-even: quando supera ~2 semanas via rede, Snow vence.","whyWrong":{"B":"DataSync via internet ainda esbarra nos 100 Mbps — não resolve.","C":"Upload manual é inviável em volume.","D":"Lambda não transfere dados massivos."},"keyConcept":"Migration — Snow Family","compareWith":["Snowcone (8TB)","Snowball Edge (80TB)","Snowmobile (100PB)"]}'::jsonb, 'Cloud Concepts', 'Cloud Concepts', 'medium', 'scenario', '["migration","snowball","data-transfer"]'::jsonb, 'ai-draft', 'active', now(), now()),
    ('clf-c02-cc-v2-072', 'aws-clf', 'Application Discovery Service (ADS) é usado em qual fase do programa MAP?', '[{"id":"A","text":"Assess — coleta inventário on-prem (servers, dependências, performance) para alimentar 6 Rs decisions e TCO"},{"id":"B","text":"Operate"},{"id":"C","text":"Decommission"},{"id":"D","text":"Backup"}]'::jsonb, 'A', '{"summary":"ADS coleta inventário detalhado para decidir o que migrar e como — fase Assess do MAP.","whyCorrect":"ADS instala agente (ou usa agentless) nos servers on-prem para descobrir CPU, memória, network connections, dependências entre apps. Esses dados feed Migration Hub e Migration Evaluator para business case e priorização de waves.","whyWrong":{"B":"Operate é pós-migração, não descoberta.","C":"Decommission é fim do ciclo, não descoberta.","D":"ADS não é backup."},"keyConcept":"Migration — ADS na fase Assess","compareWith":["ADS (discovery)","Migration Evaluator (TCO)","Migration Hub (tracking)"]}'::jsonb, 'Cloud Concepts', 'Cloud Concepts', 'hard', 'recall', '["migration","ads","assess"]'::jsonb, 'ai-draft', 'active', now(), now()),
    ('clf-c02-cc-v2-073', 'aws-clf', 'Qual estratégia das 6 Rs é frequentemente a MAIS rápida de executar (menor esforço de engenharia) mas resulta em menor ''cloud-nativeness''?', '[{"id":"A","text":"Rehost (lift-and-shift) — mover VM como está; rápido mas não aproveita managed services"},{"id":"B","text":"Refactor — reescrever para serverless"},{"id":"C","text":"Repurchase"},{"id":"D","text":"Retire"}]'::jsonb, 'A', '{"summary":"Rehost é o caminho mais rápido para a cloud (semanas), mas mantém arquitetura legada — você não ''usa'' cloud, só ''roda em'' cloud.","whyCorrect":"Rehost via MGN move VM-as-is para EC2 em dias/semanas, com risco baixo. Trade-off: você não ganha benefícios de managed services (RDS auto-failover, Lambda escala) — fica com VM tradicional rodando em EC2. Muitas empresas fazem rehost primeiro e modernizam depois.","whyWrong":{"B":"Refactor é o oposto — mais cloud-native, mais lento (meses-anos).","C":"Repurchase pode ser rápido (subscribe SaaS), mas exige migração de dados/integração.","D":"Retire é instantâneo, mas só se aplica a apps inúteis."},"keyConcept":"Migration — speed vs cloud-nativeness trade-off","compareWith":["Rehost (rápido)","Refactor (cloud-native)"]}'::jsonb, 'Cloud Concepts', 'Cloud Concepts', 'easy', 'best-practice', '["migration","rehost","trade-offs"]'::jsonb, 'ai-draft', 'active', now(), now()),
    ('clf-c02-cc-v2-074', 'aws-clf', 'Qual perspectiva do AWS CAF é responsável por desenhar e operar a landing zone (multi-account architecture, baseline de redes, guardrails)?', '[{"id":"A","text":"Platform Perspective (em colaboração com Governance e Security)"},{"id":"B","text":"People Perspective"},{"id":"C","text":"Business Perspective"},{"id":"D","text":"Não está coberto pelo CAF"}]'::jsonb, 'A', '{"summary":"Landing zone é capability principal de Platform Perspective, com Governance e Security definindo guardrails.","whyCorrect":"Platform Perspective inclui ''platform architecture'' e ''platform engineering'' — landing zone (Control Tower, Organizations, Account Factory, baseline VPCs) cai aqui. Governance define políticas (SCPs); Security define controles (GuardDuty, Security Hub baseline).","whyWrong":{"B":"People é cultura, não arquitetura.","C":"Business é estratégia, não arquitetura.","D":"Está coberto — é tema central de Platform."},"keyConcept":"CAF — landing zone em Platform Perspective","compareWith":["Platform (arquitetura)","Governance (políticas)","Security (controles)"]}'::jsonb, 'Cloud Concepts', 'Cloud Concepts', 'hard', 'best-practice', '["caf","landing-zone","platform"]'::jsonb, 'ai-draft', 'active', now(), now()),
    ('clf-c02-cc-v2-075', 'aws-clf', 'Sobre ''Stop guessing capacity'' aplicado a databases gerenciados, qual serviço é o exemplo mais alinhado?', '[{"id":"A","text":"Aurora Serverless v2 — escala automaticamente CPU/memória do DB em segundos baseado em carga real, sem provisionar instance size fixo"},{"id":"B","text":"RDS db.r5.24xlarge sempre provisionado em capacity máxima"},{"id":"C","text":"EC2 i3.metal com DB instalado manualmente"},{"id":"D","text":"DynamoDB com capacity 1000 RCU/WCU fixo"}]'::jsonb, 'A', '{"summary":"Aurora Serverless v2 escala vertical/horizontal de DB sem intervenção — manifesto de ''stop guessing capacity'' em databases.","whyCorrect":"Aurora Serverless v2 mede carga e ajusta ACU (Aurora Capacity Units) em segundos. Sem chutar instance size. Workloads imprevisíveis (apps SaaS multi-tenant, dev/test, sazonais) usam para evitar over/under-provisioning.","whyWrong":{"B":"Provisionar capacity máxima é guessing extremo — opposite of the principle.","C":"EC2 i3.metal com DB instalado é unmanaged e ainda exige guessing.","D":"DynamoDB Provisioned capacity fixa também exige guessing — DynamoDB On-Demand seria alinhado."},"keyConcept":"Performance Efficiency — serverless databases","compareWith":["Aurora Serverless v2","DynamoDB On-Demand"]}'::jsonb, 'Cloud Concepts', 'Cloud Concepts', 'medium', 'scenario', '["well-architected","performance-efficiency","aurora-serverless"]'::jsonb, 'ai-draft', 'active', now(), now()),
    ('clf-c02-cc-v2-076', 'aws-clf', 'Sobre o pilar Cost Optimization, qual prática melhor descreve ''Stop spending money on undifferentiated heavy lifting''?', '[{"id":"A","text":"Substituir operação manual de banco (patching, backup, replicação) por RDS managed, liberando o time para focar em lógica de negócio"},{"id":"B","text":"Comprar mais servidores físicos"},{"id":"C","text":"Contratar mais sysadmins"},{"id":"D","text":"Construir o próprio sistema operacional"}]'::jsonb, 'A', '{"summary":"Managed services eliminam operação de baixo valor — o time foca em diferencial competitivo.","whyCorrect":"''Undifferentiated heavy lifting'' são tarefas que não diferenciam seu produto (patching, backup, replicação de DB) mas consomem recursos. RDS, Lambda, DynamoDB absorvem isso. Custo reduzido + velocidade aumentada.","whyWrong":{"B":"Comprar mais servers é exatamente o oposto — assumir mais heavy lifting.","C":"Mais sysadmins amplifica heavy lifting humano.","D":"Construir OS próprio é maximum undifferentiated heavy lifting."},"keyConcept":"Cost Optimization — managed services","compareWith":["Self-managed (heavy lifting)","Managed (focus on business)"]}'::jsonb, 'Cloud Concepts', 'Cloud Concepts', 'easy', 'best-practice', '["well-architected","cost-optimization","managed-services"]'::jsonb, 'ai-draft', 'active', now(), now()),
    ('clf-c02-cc-v2-077', 'aws-clf', 'Uma equipe configura RDS Multi-AZ e em testes confirma failover automático em ~60s. Isso é a aplicação direta de qual design principle do Reliability Pillar?', '[{"id":"A","text":"Automatically recover from failure"},{"id":"B","text":"Foundations: limit-management"},{"id":"C","text":"Scale horizontally"},{"id":"D","text":"Manage change in automation"}]'::jsonb, 'A', '{"summary":"RDS Multi-AZ é auto-recovery clássico — falha do primary, secundário promove sem intervenção.","whyCorrect":"Multi-AZ mantém standby síncrono em outra AZ. CloudWatch detecta falha, RDS faz failover (60-120s) e endpoint passa a apontar para o novo primary. Cliente nem percebe (além de breve interrupção de conexão).","whyWrong":{"B":"Foundations trata de quotas/limits — não é o foco aqui.","C":"Scale horizontally é sobre adicionar réplicas para throughput, não failover.","D":"Manage change in automation é IaC/deployment automation, não auto-recovery."},"keyConcept":"Reliability — automatically recover from failure","compareWith":["Multi-AZ (failover automático)","Read Replica (scaling)"]}'::jsonb, 'Cloud Concepts', 'Cloud Concepts', 'easy', 'scenario', '["well-architected","reliability","rds-multi-az"]'::jsonb, 'ai-draft', 'active', now(), now()),
    ('clf-c02-cc-v2-078', 'aws-clf', 'Qual afirmação sobre ''Throughput'' vs ''Latency'' no contexto de Performance Efficiency é correta?', '[{"id":"A","text":"Throughput é volume de trabalho por unidade de tempo (req/s, MB/s); Latency é o tempo de resposta de uma operação individual (ms). Sistemas podem ter alto throughput e alta latência simultaneamente (ex: batch)"},{"id":"B","text":"São sinônimos exatos"},{"id":"C","text":"Throughput é medido em ms; Latency em req/s"},{"id":"D","text":"Alta throughput sempre implica baixa latency"}]'::jsonb, 'A', '{"summary":"Throughput e latência são ortogonais. Pipeline batch ETL pode ter alto throughput e alta latência por job.","whyCorrect":"Throughput = vazão (quantos req/s). Latency = tempo de uma req individual. Sistemas podem ser otimizados para um sem afetar o outro positivamente — batch ETL processa TB/h (alto throughput) mas cada job leva 30 min (alta latência por job). API REST otimiza latência (ms por req).","whyWrong":{"B":"São métricas distintas.","C":"Invertido: throughput é vol/tempo; latency é tempo.","D":"Falso — podem ser independentes (batch é exemplo)."},"keyConcept":"Performance — throughput vs latency","compareWith":["Throughput (vol/s)","Latency (s/req)"]}'::jsonb, 'Cloud Concepts', 'Cloud Concepts', 'medium', 'recall', '["well-architected","performance-efficiency","metrics"]'::jsonb, 'ai-draft', 'active', now(), now()),
    ('clf-c02-cc-v2-079', 'aws-clf', 'Qual é um exemplo de PaaS em AWS que NÃO é Beanstalk, Lambda ou App Runner?', '[{"id":"A","text":"Amazon Lightsail — bundles pré-configurados de compute + storage + networking + DNS com pricing fixo simples; abstrai detalhes de VPC/EC2 para devs solo"},{"id":"B","text":"Amazon Glacier"},{"id":"C","text":"Amazon VPC"},{"id":"D","text":"Amazon Route 53"}]'::jsonb, 'A', '{"summary":"Lightsail é o ''easy mode'' da AWS — bundles fixos abstraindo complexidade. Frequentemente classificado como PaaS-leve.","whyCorrect":"Lightsail entrega VPS-like com compute + storage + networking + DNS em bundle de preço fixo. Esconde VPC, SGs, route tables — dev solo só vê ''Instance LAMP $5/mês''. É PaaS-style para small workloads.","whyWrong":{"B":"Glacier é storage archive — IaaS de storage.","C":"VPC é IaaS de rede.","D":"Route 53 é DNS gerenciado — mais perto de SaaS-leve, mas não é o exemplo canônico de PaaS."},"keyConcept":"Service models — Lightsail (PaaS-leve)","compareWith":["Lightsail (bundles)","EC2 (granular)"]}'::jsonb, 'Cloud Concepts', 'Cloud Concepts', 'hard', 'scenario', '["service-models","lightsail","paas"]'::jsonb, 'ai-draft', 'active', now(), now()),
    ('clf-c02-cc-v2-080', 'aws-clf', 'Sobre seleção de Region considerando ''sustainability'', qual estatística reportada pela AWS é mais relevante para FinOps + ESG?', '[{"id":"A","text":"Customer Carbon Footprint Tool reporta emissões em kgCO2eq por serviço/region/mês, permitindo correlacionar custo e pegada de carbono"},{"id":"B","text":"AWS publica o número total de funcionários"},{"id":"C","text":"AWS divulga lucro por região"},{"id":"D","text":"AWS proíbe medição de emissões"}]'::jsonb, 'A', '{"summary":"Customer Carbon Footprint Tool (CCFT) é a métrica oficial AWS de emissões — input direto para metas ESG.","whyCorrect":"CCFT, lançado em 2022 no Billing console, reporta emissões em kgCO2eq por serviço, region, mês. Permite empresas com metas Net Zero reportar Scope 3 (emissões de fornecedores) com dados verificáveis.","whyWrong":{"B":"Headcount não é métrica sustentável relevante para FinOps.","C":"Lucro por region não é divulgado por AWS e não é métrica sustentável.","D":"Falso — AWS publica e incentiva medição de emissões."},"keyConcept":"Sustainability — Customer Carbon Footprint Tool (CCFT)","compareWith":["CCFT (medir)","Region selection (otimizar)"]}'::jsonb, 'Cloud Concepts', 'Cloud Concepts', 'hard', 'scenario', '["well-architected","sustainability","carbon-footprint"]'::jsonb, 'ai-draft', 'active', now(), now()),
    ('clf-c02-001', 'aws-clf', 'Uma startup quer reduzir o tempo que a equipe gasta com patching de SO, troca de discos e renovação de hardware, focando apenas no produto. Qual benefício da nuvem AWS endereça esse objetivo de forma mais direta?', '[{"id":"A","text":"Economias de escala globais"},{"id":"B","text":"Foco no diferencial do negócio em vez de heavy lifting indiferenciado"},{"id":"C","text":"Elasticidade automática de capacidade"},{"id":"D","text":"Alcance global em minutos"}]'::jsonb, 'B', '{"summary":"AWS gerencia hardware, hypervisor, patching base e datacenter — é exatamente o ''undifferentiated heavy lifting'' que o framework descreve como vantagem da nuvem.","whyCorrect":"AWS gerencia hardware, hypervisor, patching base e datacenter — é exatamente o ''undifferentiated heavy lifting'' que o framework descreve como vantagem da nuvem.","whyWrong":{"A":"Economias de escala é benefício financeiro, não operacional.","C":"Elasticidade é sobre variação de carga, não sobre manutenção.","D":"Alcance global é sobre latência/expansão."},"keyConcept":"Princípio ''stop spending money running and maintaining data centers'' do Well-Architected.","tutorSeeds":["Pode explicar com mais detalhe: Princípio ''stop spending money running and maintaining data centers'' do Well-Architected?","Quais cenários reais aplicam Princípio ''stop spending money running and maintaining data centers'' do Well-Architected?","Como AWS se compara com alternativas?"]}'::jsonb, 'Cloud Concepts', 'Cloud Concepts', 'easy', 'recall', '["benefits","well-architected","operational-excellence"]'::jsonb, 'ai-draft', 'active', now(), now()),
    ('clf-c02-002', 'aws-clf', 'Uma empresa migra workloads para AWS e a equipe de segurança pergunta quem é responsável por aplicar patches no sistema operacional de uma instância Amazon EC2 que roda Amazon Linux 2023. Pelo Shared Responsibility Model, quem é o responsável?', '[{"id":"A","text":"AWS, pois fornece a AMI base"},{"id":"B","text":"AWS, pois a instância roda em hardware AWS"},{"id":"C","text":"O cliente, pois EC2 é IaaS e o SO é responsabilidade do cliente"},{"id":"D","text":"Compartilhada igualmente entre AWS e cliente"}]'::jsonb, 'C', '{"summary":"Em EC2 (IaaS), AWS é responsável pela ''security OF the cloud'' (hardware, host hypervisor, rede física); o cliente é responsável pela ''security IN the cloud'' — guest OS, patches, configuração de SG, dados, IAM in-instance.","whyCorrect":"Em EC2 (IaaS), AWS é responsável pela ''security OF the cloud'' (hardware, host hypervisor, rede física); o cliente é responsável pela ''security IN the cloud'' — guest OS, patches, configuração de SG, dados, IAM in-instance.","whyWrong":{"A":"AWS fornece a AMI base do Amazon Linux 2023, mas a partir do momento em que a instância é lançada, qualquer patch do guest OS (yum/dnf update, kernel patches, security fixes) é responsabilidade do cliente. A AMI é só o ponto de partida — não há atualização automática pela AWS na instância em execução. Esta opção seria correta para serviços fully managed como RDS ou Lambda.","B":"Rodar em hardware AWS torna a AWS responsável pelo hardware, hypervisor e rede física (''security OF the cloud''), mas não pelo guest OS que o cliente escolhe e administra. A camada hypervisor → guest é a linha divisória do shared responsibility model para EC2. Patching do SO fica do lado do cliente independentemente de onde o hardware roda.","D":"O Shared Responsibility Model não divide responsabilidades ''igualmente'' — a divisão é por camada, não por percentual. Para cada serviço, AWS cobre algumas camadas (sempre o hardware/infra física) e o cliente cobre outras (sempre seus dados e IAM). Em EC2 especificamente, patching do guest OS está 100% no cliente, não compartilhado."},"keyConcept":"Regra: quanto mais managed o serviço, mais responsabilidade fica com AWS.","tutorSeeds":["Pode explicar com mais detalhe: Regra: quanto mais managed o serviço, mais responsabilidade fica com AWS?","Quais cenários reais aplicam Regra: quanto mais managed o serviço, mais responsabilidade fica com AWS?","Como EC2 se compara com alternativas?"]}'::jsonb, 'Security & Compliance', 'Security & Compliance', 'easy', 'scenario', '["shared-responsibility","ec2","patching"]'::jsonb, 'ai-draft', 'active', now(), now()),
    ('clf-c02-003', 'aws-clf', 'Uma equipe precisa hospedar um site estático (HTML, CSS, JS, imagens) com baixo custo, alta durabilidade e acesso público global. Qual combinação de serviços AWS atende melhor a esse requisito?', '[{"id":"A","text":"Amazon EC2 com Auto Scaling atrás de um Application Load Balancer"},{"id":"B","text":"Amazon S3 com hosting estático e Amazon CloudFront na frente"},{"id":"C","text":"AWS Lambda com API Gateway e Amazon DynamoDB"},{"id":"D","text":"AWS Elastic Beanstalk em um ambiente single-instance"}]'::jsonb, 'B', '{"summary":"S3 oferece 11 9s de durabilidade e custo por GB baixíssimo; CloudFront entrega de edge locations próximas do usuário, reduzindo latência e custo de egress.","whyCorrect":"S3 oferece 11 9s de durabilidade e custo por GB baixíssimo; CloudFront entrega de edge locations próximas do usuário, reduzindo latência e custo de egress.","whyWrong":{"C":"Lambda+API Gateway é para APIs dinâmicas.","D":"Elastic Beanstalk é PaaS para apps que rodam código no servidor.","A":"EC2+ALB envolve instâncias rodando 24/7 com custo fixo de compute mais o ALB ($16+/mês mínimo), tudo isso só para servir arquivos estáticos. Há patching, monitoramento de saúde, configuração de web server (nginx/Apache) — overhead operacional alto para um caso onde S3 entrega o mesmo resultado por centavos. Esta opção faria sentido se houvesse processamento server-side."},"keyConcept":"Padrão recomendado AWS: S3 + CloudFront para sites estáticos.","tutorSeeds":["Pode explicar com mais detalhe: Padrão recomendado AWS: S3 + CloudFront para sites estáticos?","Quais cenários reais aplicam Padrão recomendado AWS: S3 + CloudFront para sites estáticos?","Como GB se compara com alternativas?"]}'::jsonb, 'Cloud Technology & Services', 'Cloud Technology & Services', 'easy', 'best-practice', '["s3","cloudfront","static-hosting"]'::jsonb, 'ai-draft', 'active', now(), now()),
    ('clf-c02-004', 'aws-clf', 'Uma empresa quer prever o gasto da AWS dos próximos 12 meses com base no histórico atual de uso e receber alertas quando ultrapassar um valor definido. Qual combinação de ferramentas atende essas duas necessidades?', '[{"id":"A","text":"AWS Trusted Advisor para previsão e AWS Config para alertas"},{"id":"B","text":"AWS Cost Explorer para previsão e AWS Budgets para alertas"},{"id":"C","text":"AWS Pricing Calculator para previsão e Amazon CloudWatch para alertas"},{"id":"D","text":"AWS Cost and Usage Report para previsão e AWS Organizations para alertas"}]'::jsonb, 'B', '{"summary":"Cost Explorer tem feature de forecast baseado em histórico; AWS Budgets envia notificações via SNS quando custo ou uso ultrapassa threshold.","whyCorrect":"Cost Explorer tem feature de forecast baseado em histórico; AWS Budgets envia notificações via SNS quando custo ou uso ultrapassa threshold.","whyWrong":{"A":"Trusted Advisor recomenda otimizações, não prevê Config trata compliance, não custo. [extra: CUR é dado bruto para BI]","C":"Pricing Calculator estima cenários hipotéticos (pré-uso), não baseado em histórico.","D":"Organizations é gestão de contas."},"keyConcept":"Forecast vem do Cost Explorer; alertas com ação vêm do Budgets.","tutorSeeds":["Pode explicar com mais detalhe: Forecast vem do Cost Explorer; alertas com ação vêm do Budgets?","Quais cenários reais aplicam Forecast vem do Cost Explorer; alertas com ação vêm do Budgets?","Como AWS Budgets se compara com alternativas?"]}'::jsonb, 'Billing, Pricing & Support', 'Billing, Pricing & Support', 'medium', 'scenario', '["cost-explorer","budgets","forecast"]'::jsonb, 'ai-draft', 'active', now(), now()),
    ('clf-c02-005', 'aws-clf', 'Uma empresa precisa criar uma rede privada virtual na AWS e definir explicitamente o range de IPs, sub-redes e rotas, isolada de outras contas. Qual serviço entrega esse isolamento de rede no nível mais fundamental?', '[{"id":"A","text":"Amazon VPC"},{"id":"B","text":"AWS Direct Connect"},{"id":"C","text":"AWS Transit Gateway"},{"id":"D","text":"Amazon Route 53"}]'::jsonb, 'A', '{"summary":"VPC é a primitiva de rede isolada — CIDR escolhido, subnets, route tables, IGW/NGW, SGs e NACLs vivem dentro dela.","whyCorrect":"VPC é a primitiva de rede isolada — CIDR escolhido, subnets, route tables, IGW/NGW, SGs e NACLs vivem dentro dela.","whyWrong":{"B":"Direct Connect é conectividade dedicada on-prem ↔ AWS, não cria a rede em si.","C":"Transit Gateway interliga VPCs e on-prem, mas depende das VPCs existirem antes.","D":"Route 53 é DNS, não rede."},"keyConcept":"VPC é foundation de qualquer arquitetura de rede AWS.","tutorSeeds":["Pode explicar com mais detalhe: VPC é foundation de qualquer arquitetura de rede AWS?","Quais cenários reais aplicam VPC é foundation de qualquer arquitetura de rede AWS?","Como VPC se compara com alternativas?"]}'::jsonb, 'Cloud Technology & Services', 'Cloud Technology & Services', 'easy', 'recall', '["vpc","networking","isolation"]'::jsonb, 'ai-draft', 'active', now(), now()),
    ('clf-c02-006', 'aws-clf', 'Uma empresa tem cargas de trabalho previsíveis rodando 24/7 em Amazon EC2 por pelo menos 1 ano e quer reduzir custo em troca de compromisso de uso. Qual modelo de pricing entrega o maior desconto para esse perfil?', '[{"id":"A","text":"On-Demand Instances"},{"id":"B","text":"Spot Instances"},{"id":"C","text":"Savings Plans ou Reserved Instances de 1 ou 3 anos"},{"id":"D","text":"Dedicated Hosts no-tenancy"}]'::jsonb, 'C', '{"summary":"Compute Savings Plans e Standard RIs oferecem até ~72% de desconto vs On-Demand em troca de compromisso de gasto/horas por 1 ou 3 anos — encaixe perfeito em workload estável 24/7.","whyCorrect":"Compute Savings Plans e Standard RIs oferecem até ~72% de desconto vs On-Demand em troca de compromisso de gasto/horas por 1 ou 3 anos — encaixe perfeito em workload estável 24/7.","whyWrong":{"A":"On-Demand é o preço cheio, sem compromisso. [extra: incompatível com workload crítico 24/7.]","B":"Spot tem desconto maior (~90%) mas pode ser interrompido","D":"Dedicated Hosts é caro e endereça compliance/licenciamento, não desconto."},"keyConcept":"Regra: workload previsível e longo prazo → Savings Plans/RI; workload tolerante a interrupção → Spot.","tutorSeeds":["Pode explicar com mais detalhe: Regra: workload previsível e longo prazo → Savings Plans/RI; workload tolerante a interrupção → Spot?","Quais cenários reais aplicam Regra: workload previsível e longo prazo → Savings Plans/RI; workload tolerante a interrupção → Spot?","Como RIs se compara com alternativas?"]}'::jsonb, 'Billing, Pricing & Support', 'Billing, Pricing & Support', 'medium', 'best-practice', '["savings-plans","reserved-instances","pricing"]'::jsonb, 'ai-draft', 'active', now(), now()),
    ('clf-c02-007', 'aws-clf', 'Um administrador precisa conceder a um aplicativo rodando em Amazon EC2 acesso a um bucket do Amazon S3 sem armazenar access keys na instância. Qual é a abordagem recomendada pela AWS?', '[{"id":"A","text":"Criar um IAM user com policy de S3 e colocar suas access keys em variáveis de ambiente"},{"id":"B","text":"Anexar uma IAM role à instância EC2 via instance profile com a policy de S3 necessária"},{"id":"C","text":"Conceder permissões via security group apontando para o bucket"},{"id":"D","text":"Habilitar Block Public Access no bucket e o EC2 acessa automaticamente"}]'::jsonb, 'B', '{"summary":"IAM roles via instance profile entregam credenciais temporárias rotacionadas automaticamente pelo metadata service — zero secret em disco.","whyCorrect":"IAM roles via instance profile entregam credenciais temporárias rotacionadas automaticamente pelo metadata service — zero secret em disco.","whyWrong":{"A":"IAM users com access keys hardcoded é exatamente o anti-pattern","C":"security groups controlam tráfego TCP/UDP, não permissões IAM","D":"Block Public Access é defesa contra exposição pública, não autorização."},"keyConcept":"Regra: cargas de trabalho devem usar roles, nunca long-lived keys.","tutorSeeds":["Pode explicar com mais detalhe: Regra: cargas de trabalho devem usar roles, nunca long-lived keys?","Quais cenários reais aplicam Regra: cargas de trabalho devem usar roles, nunca long-lived keys?","Como IAM se compara com alternativas?"]}'::jsonb, 'Security & Compliance', 'Security & Compliance', 'medium', 'best-practice', '["iam","ec2","instance-profile","least-privilege"]'::jsonb, 'ai-draft', 'active', now(), now()),
    ('clf-c02-008', 'aws-clf', 'Uma empresa armazena 200 TB de logs de auditoria que devem ser mantidos por 7 anos para compliance, com acesso raro mas recuperação em minutos quando solicitado. Qual classe do Amazon S3 minimiza custo dentro desses requisitos?', '[{"id":"A","text":"S3 Standard"},{"id":"B","text":"S3 Standard-IA"},{"id":"C","text":"S3 Glacier Instant Retrieval"},{"id":"D","text":"S3 Glacier Deep Archive"}]'::jsonb, 'C', '{"summary":"Glacier Instant Retrieval é a classe mais barata que ainda entrega recuperação em milissegundos — ideal para ''acesso raro mas quando precisar, é rápido''.","whyCorrect":"Glacier Instant Retrieval é a classe mais barata que ainda entrega recuperação em milissegundos — ideal para ''acesso raro mas quando precisar, é rápido''.","whyWrong":{"A":"Standard é cara para acesso raro. Standard-IA é mais barata mas ainda paga por GB de armazenamento bem acima de Glacier.","D":"Deep Archive é a mais barata absoluta mas tem recuperação em 12 horas","B":"Standard-IA é para acesso infrequente com recuperação em milissegundos, mas seu custo por GB de armazenamento é significativamente maior que Glacier Instant Retrieval. Para 200 TB mantidos por 7 anos, a diferença é grande. Standard-IA seria correto se o acesso fosse ''algumas vezes por mês''; para ''acesso raro'' (≤1x/quarter), Glacier IR ganha em custo mantendo a recuperação em ms."},"keyConcept":"Regra de escolha: frequência de acesso + tempo aceitável de recuperação.","tutorSeeds":["Pode explicar com mais detalhe: Regra de escolha: frequência de acesso + tempo aceitável de recuperação?","Quais cenários reais aplicam Regra de escolha: frequência de acesso + tempo aceitável de recuperação?"]}'::jsonb, 'Cloud Technology & Services', 'Cloud Technology & Services', 'medium', 'scenario', '["s3","storage-classes","glacier","cost-optimization"]'::jsonb, 'ai-draft', 'active', now(), now()),
    ('clf-c02-009', 'aws-clf', 'Uma equipe quer implementar políticas de governança centralizadas que limitem quais regiões e serviços contas-filhas podem usar, sem precisar configurar cada conta individualmente. Qual recurso da AWS entrega isso?', '[{"id":"A","text":"IAM permissions boundaries em cada conta"},{"id":"B","text":"Service Control Policies (SCPs) em AWS Organizations"},{"id":"C","text":"AWS Config rules em cada conta"},{"id":"D","text":"Resource-based policies em cada serviço"}]'::jsonb, 'B', '{"summary":"SCPs são aplicadas no nível da Organization ou OU e definem o ceiling máximo de permissões para todas as contas dentro — bloqueio centralizado sem tocar cada conta.","whyCorrect":"SCPs são aplicadas no nível da Organization ou OU e definem o ceiling máximo de permissões para todas as contas dentro — bloqueio centralizado sem tocar cada conta.","whyWrong":{"A":"Permissions boundaries são per-principal dentro de uma conta, não centralizadas.","C":"Config rules detectam drift e geram findings, não bloqueiam ações em tempo real.","D":"Resource-based policies são por recurso, não governança transversal."},"keyConcept":"Padrão de multi-account governance AWS: Organizations + SCPs + Control Tower.","tutorSeeds":["Pode explicar com mais detalhe: Padrão de multi-account governance AWS: Organizations + SCPs + Control Tower?","Quais cenários reais aplicam Padrão de multi-account governance AWS: Organizations + SCPs + Control Tower?","Como SCPs se compara com alternativas?"]}'::jsonb, 'Security & Compliance', 'Security & Compliance', 'hard', 'scenario', '["organizations","scp","governance","multi-account"]'::jsonb, 'ai-draft', 'active', now(), now()),
    ('clf-c02-010', 'aws-clf', 'Após uma migração, a equipe relata que um workload web em EC2 ficou intermitentemente inacessível durante picos de tráfego, mesmo com Auto Scaling configurado. As métricas do CloudWatch mostram CPU em 95% sustentado. Qual ajuste atende melhor o problema?', '[{"id":"A","text":"Aumentar o tamanho do EBS volume das instâncias"},{"id":"B","text":"Ajustar a política de scaling para escalar com base em CPU >70% e diminuir cooldown"},{"id":"C","text":"Migrar para instâncias t2.micro para reduzir custo"},{"id":"D","text":"Substituir o Application Load Balancer por um Network Load Balancer"}]'::jsonb, 'B', '{"summary":"CPU saturada antes do scaling agir indica threshold alto demais ou cooldown longo — baixar gatilho para 70% e reduzir cooldown permite reação antes da saturação.","whyCorrect":"CPU saturada antes do scaling agir indica threshold alto demais ou cooldown longo — baixar gatilho para 70% e reduzir cooldown permite reação antes da saturação.","whyWrong":{"C":"EBS resolve I/O, não CPU. t2.micro é menor, agravaria.","A":"EBS volume size afeta capacidade de armazenamento e (em alguns tipos) IOPS de disco. O sintoma aqui é CPU saturada em 95%, não fila de I/O — aumentar EBS não adiciona ciclos de CPU. Esta opção seria correta se a métrica problemática fosse VolumeQueueLength ou throttling de I/O.","D":"ALB opera em L7 (HTTP/HTTPS) e NLB em L4 (TCP/UDP) — a diferença é protocolo e features, não capacidade de compute das instâncias backend. Mesmo com NLB, as instâncias EC2 continuariam saturadas em 95% de CPU. O LB distribui tráfego, mas não gera capacidade adicional. Esta opção seria correta se o problema fosse latência de TLS termination ou jitter."},"keyConcept":"Conceito: scaling reativo precisa de threshold abaixo do ponto de saturação e cooldown compatível com tempo de boot da AMI.","tutorSeeds":["Pode explicar com mais detalhe: Conceito: scaling reativo precisa de threshold abaixo do ponto de saturação e cooldown compatível com tempo de boot da AMI?","Quais cenários reais aplicam Conceito: scaling reativo precisa de threshold abaixo do ponto de saturação e cooldown compatível com tempo de boot da AMI?","Como CPU se compara com alternativas?"]}'::jsonb, 'Cloud Technology & Services', 'Cloud Technology & Services', 'medium', 'troubleshoot', '["ec2","auto-scaling","cloudwatch"]'::jsonb, 'ai-draft', 'active', now(), now()),
    ('clf-c02-011', 'aws-clf', 'Uma empresa precisa decidir entre Basic, Developer, Business e Enterprise Support para sua conta AWS. O requisito principal é ter acesso 24x7 a engenheiros AWS para casos de produção e a um Technical Account Manager (TAM) dedicado. Qual plano atende?', '[{"id":"A","text":"AWS Basic Support"},{"id":"B","text":"AWS Developer Support"},{"id":"C","text":"AWS Business Support"},{"id":"D","text":"AWS Enterprise Support"}]'::jsonb, 'D', '{"summary":"TAM dedicado é exclusivo de Enterprise (e Enterprise On-Ramp em escopo limitado); 24x7 a engenheiros para produção e SLA agressivo de business-critical também.","whyCorrect":"TAM dedicado é exclusivo de Enterprise (e Enterprise On-Ramp em escopo limitado); 24x7 a engenheiros para produção e SLA agressivo de business-critical também.","whyWrong":{"A":"Basic não tem suporte técnico via case.","B":"Developer é horário comercial e sem TAM.","C":"Business tem 24x7 mas sem TAM dedicado."},"keyConcept":"Regra: precisa de TAM → Enterprise (ou On-Ramp como entry).","tutorSeeds":["Pode explicar com mais detalhe: Regra: precisa de TAM → Enterprise (ou On-Ramp como entry)?","Quais cenários reais aplicam Regra: precisa de TAM → Enterprise (ou On-Ramp como entry)?","Como TAM se compara com alternativas?"]}'::jsonb, 'Billing, Pricing & Support', 'Billing, Pricing & Support', 'easy', 'recall', '["support-plans","tam","enterprise"]'::jsonb, 'ai-draft', 'active', now(), now()),
    ('clf-c02-012', 'aws-clf', 'Uma equipe de segurança quer detectar comportamento anômalo em chamadas de API e em DNS na conta AWS (por exemplo, instâncias EC2 acessando endpoints conhecidos de malware) usando machine learning. Qual serviço entrega essa detecção sem precisar instalar agentes?', '[{"id":"A","text":"AWS Shield Advanced"},{"id":"B","text":"Amazon Inspector"},{"id":"C","text":"Amazon GuardDuty"},{"id":"D","text":"AWS WAF"}]'::jsonb, 'C', '{"summary":"GuardDuty analisa CloudTrail, VPC Flow Logs e DNS logs com ML para detectar reconnaissance, comprometimento de instâncias e exfiltração — sem agentes.","whyCorrect":"GuardDuty analisa CloudTrail, VPC Flow Logs e DNS logs com ML para detectar reconnaissance, comprometimento de instâncias e exfiltração — sem agentes.","whyWrong":{"A":"Shield Advanced é proteção contra DDoS.","B":"Inspector escaneia vulnerabilidades em EC2/ECR/Lambda (CVEs, network reachability).","D":"AWS WAF inspeciona requisições HTTP/HTTPS em camada 7 (SQL injection, XSS, regras OWASP) acopladas a ALB, CloudFront ou API Gateway — ele bloqueia ataques web na borda da aplicação. Não analisa chamadas de API da conta AWS nem tráfego DNS de instâncias EC2, e não usa ML para detectar anomalia de comportamento. WAF seria correto para proteger uma aplicação web pública contra ataques de aplicação."},"keyConcept":"Cada serviço cobre uma camada — GuardDuty é o threat detection ML-based da AWS.","tutorSeeds":["Pode explicar com mais detalhe: Cada serviço cobre uma camada — GuardDuty é o threat detection ML-based da AWS?","Quais cenários reais aplicam Cada serviço cobre uma camada — GuardDuty é o threat detection ML-based da AWS?","Como VPC se compara com alternativas?"]}'::jsonb, 'Security & Compliance', 'Security & Compliance', 'medium', 'scenario', '["guardduty","threat-detection","security"]'::jsonb, 'ai-draft', 'active', now(), now()),
    ('clf-c02-013', 'aws-clf', 'Uma equipe quer rodar containers Docker sem provisionar nem gerenciar EC2 hosts (serverless de container), pagando apenas pelo vCPU/memória consumidos por task. Qual combinação AWS atende?', '[{"id":"A","text":"Amazon ECS ou EKS com AWS Fargate como capacity provider"},{"id":"B","text":"Amazon ECS com launch type EC2"},{"id":"C","text":"Amazon EC2 com Docker instalado manualmente"},{"id":"D","text":"AWS Lambda com container images"}]'::jsonb, 'A', '{"summary":"Fargate roda containers ECS/EKS sem expor EC2 hosts ao cliente — billing por vCPU·s + memória·s da task.","whyCorrect":"Fargate roda containers ECS/EKS sem expor EC2 hosts ao cliente — billing por vCPU·s + memória·s da task.","whyWrong":{"B":"ECS launch type EC2 expõe hosts EC2 (cliente patcha).","C":"EC2+Docker manual é IaaS puro.","D":"Lambda com container images existe mas é função, não orquestração de container long-running com modelo task/pod."},"keyConcept":"Regra: container serverless = Fargate; função serverless = Lambda.","tutorSeeds":["Pode explicar com mais detalhe: Regra: container serverless = Fargate; função serverless = Lambda?","Quais cenários reais aplicam Regra: container serverless = Fargate; função serverless = Lambda?","Como ECS se compara com alternativas?"]}'::jsonb, 'Cloud Technology & Services', 'Cloud Technology & Services', 'medium', 'best-practice', '["fargate","ecs","eks","containers"]'::jsonb, 'ai-draft', 'active', now(), now()),
    ('clf-c02-014', 'aws-clf', 'Uma empresa global quer reduzir a latência de uma API hospedada na regiao us-east-1 para usuários na Ásia e Europa, sem mover a infra. A API serve respostas em sua maioria dinâmicas (não-cacheáveis), mas se beneficia de TLS terminado próximo do usuário e roteamento por anycast. Qual serviço atende melhor?', '[{"id":"A","text":"Amazon CloudFront com TTL=0"},{"id":"B","text":"AWS Global Accelerator"},{"id":"C","text":"Amazon Route 53 com latency-based routing"},{"id":"D","text":"Adicionar uma read replica RDS por região"}]'::jsonb, 'B', '{"summary":"Global Accelerator dá IPs anycast que entram na rede AWS no edge mais próximo, terminam TLS e fazem path interno otimizado até us-east-1 — perfeito para tráfego dinâmico não-cacheável.","whyCorrect":"Global Accelerator dá IPs anycast que entram na rede AWS no edge mais próximo, terminam TLS e fazem path interno otimizado até us-east-1 — perfeito para tráfego dinâmico não-cacheável.","whyWrong":{"A":"CloudFront é otimizado para conteúdo cacheável [extra: com TTL=0 não cacheia mas adiciona hop.]","C":"Route 53 latency routing só vale se houver endpoints em múltiplas regiões.","D":"RDS replica exige refatorar a app e replicação, fora de escopo."},"keyConcept":"Regra: estático/cacheável → CloudFront; dinâmico/anycast → Global Accelerator.","tutorSeeds":["Pode explicar com mais detalhe: Regra: estático/cacheável → CloudFront; dinâmico/anycast → Global Accelerator?","Quais cenários reais aplicam Regra: estático/cacheável → CloudFront; dinâmico/anycast → Global Accelerator?","Como IPs se compara com alternativas?"]}'::jsonb, 'Cloud Technology & Services', 'Cloud Technology & Services', 'hard', 'scenario', '["global-accelerator","cloudfront","latency"]'::jsonb, 'ai-draft', 'active', now(), now()),
    ('clf-c02-015', 'aws-clf', 'Após habilitar AWS CloudTrail em uma conta, a equipe não consegue ver eventos de API S3 GetObject/PutObject no log trail padrão. Qual ajuste resolve isso?', '[{"id":"A","text":"Aumentar a retenção do bucket destino do CloudTrail"},{"id":"B","text":"Habilitar Data Events para S3 (objetos) no trail; por padrão só Management Events são registrados"},{"id":"C","text":"Mudar a região do trail para us-east-1"},{"id":"D","text":"Habilitar versioning no bucket monitorado"}]'::jsonb, 'B', '{"summary":"CloudTrail por padrão captura Management Events (operações no plano de controle: CreateBucket, PutBucketPolicy).","whyCorrect":"CloudTrail por padrão captura Management Events (operações no plano de controle: CreateBucket, PutBucketPolicy). Operações no plano de dados (GetObject/PutObject) são Data Events e precisam ser habilitadas explicitamente — têm custo adicional.","whyWrong":{"A":"Retenção não afeta o que é capturado. Versioning é feature do S3, não do CloudTrail.","C":"Região não filtra Data Events.","D":"Versioning no S3 mantém múltiplas versões de objetos para proteção contra delete/overwrite acidental — é feature de durabilidade dos dados, não de auditoria de API. CloudTrail é independente do versioning: ele registra a operação (GetObject, PutObject) se Data Events estiverem habilitados, com ou sem versioning. Versioning seria a resposta para ''proteger objetos contra deleção acidental''."},"keyConcept":"Conceito: Management vs Data Events vs Insights — saber o que cada um cobre.","tutorSeeds":["Pode explicar com mais detalhe: Conceito: Management vs Data Events vs Insights — saber o que cada um cobre?","Quais cenários reais aplicam Conceito: Management vs Data Events vs Insights — saber o que cada um cobre?"]}'::jsonb, 'Security & Compliance', 'Security & Compliance', 'hard', 'troubleshoot', '["cloudtrail","audit","s3","data-events"]'::jsonb, 'ai-draft', 'active', now(), now()),
    ('clf-c02-sec-001', 'aws-clf', 'Uma fintech migra um serviço crítico para Amazon EC2 rodando Ubuntu 22.04. Durante revisão de segurança, o auditor pergunta quem aplica patches do kernel quando uma CVE crítica é divulgada. Considerando o AWS Shared Responsibility Model para EC2, qual é a divisão correta?', '[{"id":"A","text":"AWS aplica patches automaticamente em todas as AMIs em execução"},{"id":"B","text":"O cliente é responsável pelo patching do guest OS, incluindo kernel"},{"id":"C","text":"AWS patcha o kernel; o cliente patcha apenas userland"},{"id":"D","text":"Patching é coberto pelo plano de suporte Business ou superior"}]'::jsonb, 'B', '{"summary":"Em EC2 o guest OS — incluindo kernel, libs e apps — é responsabilidade do cliente (''security IN the cloud''); AWS cuida do hardware, hypervisor e patches do host.","whyCorrect":"Em EC2 o guest OS — incluindo kernel, libs e apps — é responsabilidade do cliente (''security IN the cloud''); AWS cuida do hardware, hypervisor e patches do host.","whyWrong":{"A":"AWS não toca em instâncias em execução do cliente","C":"não há split entre kernel e userland","D":"planos de suporte não incluem patching operacional."},"keyConcept":"Regra: quanto menos managed o serviço, mais responsabilidade do cliente — EC2 é IaaS.","tutorSeeds":["Pode explicar com mais detalhe: Regra: quanto menos managed o serviço, mais responsabilidade do cliente — EC2 é IaaS?","Quais cenários reais aplicam Regra: quanto menos managed o serviço, mais responsabilidade do cliente — EC2 é IaaS?","Como EC2 se compara com alternativas?"]}'::jsonb, 'Security & Compliance', 'Security & Compliance', 'easy', 'scenario', '["shared-responsibility","ec2","patching"]'::jsonb, 'ai-draft', 'active', now(), now()),
    ('clf-c02-sec-002', 'aws-clf', 'Uma empresa usa Amazon RDS for PostgreSQL em modo Multi-AZ. Quem é responsável pela aplicação de patches do engine PostgreSQL e do sistema operacional subjacente da instância RDS?', '[{"id":"A","text":"O cliente, pois é IaaS"},{"id":"B","text":"AWS para SO e engine; o cliente apenas agenda a janela de manutenção"},{"id":"C","text":"O cliente, conectando-se via SSH à instância RDS"},{"id":"D","text":"AWS apenas para SO; engine PostgreSQL é do cliente"}]'::jsonb, 'B', '{"summary":"RDS é managed service: AWS gerencia SO subjacente, patches de engine e replicação Multi-AZ; cliente escolhe versão, agenda janela e gerencia dados/schema.","whyCorrect":"RDS é managed service: AWS gerencia SO subjacente, patches de engine e replicação Multi-AZ; cliente escolhe versão, agenda janela e gerencia dados/schema.","whyWrong":{"A":"RDS não é IaaS","D":"patches de engine são responsabilidade da AWS dentro da versão escolhida.","C":"Em Amazon RDS, o cliente NÃO tem acesso SSH ao host — a AWS bloqueia esse acesso porque o SO é managed. Toda interação é via endpoint do banco (porta 5432 do PostgreSQL) ou via Parameter Groups/Option Groups. Esta opção seria correta para um banco rodando em EC2 self-managed, onde o cliente tem SSH e patcha tudo."},"keyConcept":"Regra: managed DB → AWS cuida do plumbing, cliente cuida do dado.","tutorSeeds":["Pode explicar com mais detalhe: Regra: managed DB → AWS cuida do plumbing, cliente cuida do dado?","Quais cenários reais aplicam Regra: managed DB → AWS cuida do plumbing, cliente cuida do dado?","Como RDS se compara com alternativas?"]}'::jsonb, 'Security & Compliance', 'Security & Compliance', 'easy', 'scenario', '["shared-responsibility","rds","managed-service"]'::jsonb, 'ai-draft', 'active', now(), now()),
    ('clf-c02-sec-003', 'aws-clf', 'Uma equipe de desenvolvimento deploya uma função AWS Lambda escrita em Python 3.12 que processa eventos do Amazon SQS. Pelo Shared Responsibility Model, qual responsabilidade permanece com o cliente?', '[{"id":"A","text":"Patching do runtime Python 3.12 fornecido pela AWS"},{"id":"B","text":"Patching do sistema operacional onde a função executa"},{"id":"C","text":"Código da função, dependências em camadas e permissões IAM da execution role"},{"id":"D","text":"Manter o firewall do host onde a função roda"}]'::jsonb, 'C', '{"summary":"Em Lambda, AWS gerencia SO, runtime e infra; cliente é responsável pelo código, libs empacotadas, configuração e IAM.","whyCorrect":"Em Lambda, AWS gerencia SO, runtime e infra; cliente é responsável pelo código, libs empacotadas, configuração e IAM.","whyWrong":{"D":"cliente não tem acesso ao host nem firewall dele.","A":"O runtime Python 3.12 em Lambda é fornecido e mantido pela AWS — patches de segurança do interpreter Python e libs nativas são aplicados pelo serviço automaticamente. O cliente apenas escolhe a versão do runtime; quando uma versão é deprecated, a AWS notifica e exige upgrade. Esta opção seria correta para Python instalado manualmente em EC2.","B":"Lambda é fully managed — o cliente não tem acesso nem visibilidade do SO subjacente onde a função executa (Firecracker microVM). AWS patcha o SO, kernel e runtime sem intervenção do cliente. Esta opção seria correta para EC2 (IaaS), onde o cliente é dono do guest OS."},"keyConcept":"Regra: serverless → cliente cuida só do ''in the function''.","tutorSeeds":["Pode explicar com mais detalhe: Regra: serverless → cliente cuida só do ''in the function''?","Quais cenários reais aplicam Regra: serverless → cliente cuida só do ''in the function''?","Como AWS se compara com alternativas?"]}'::jsonb, 'Security & Compliance', 'Security & Compliance', 'medium', 'scenario', '["shared-responsibility","lambda","serverless"]'::jsonb, 'ai-draft', 'active', now(), now()),
    ('clf-c02-sec-004', 'aws-clf', 'Uma empresa armazena documentos em Amazon S3 e questiona quem é responsável por classificar dados sensíveis e aplicar controles de acesso aos objetos. Qual afirmação está correta sob o Shared Responsibility Model?', '[{"id":"A","text":"AWS classifica automaticamente todos os objetos com Macie sem custo"},{"id":"B","text":"O cliente é responsável por classificar dados e definir políticas de acesso"},{"id":"C","text":"AWS gera bucket policies padrão alinhadas à LGPD"},{"id":"D","text":"Classificação é responsabilidade compartilhada 50/50"}]'::jsonb, 'B', '{"summary":"Dado, classificação, bucket policy, IAM policy, encryption settings e Block Public Access são responsabilidade do cliente; AWS garante durabilidade, disponibilidade e infra do S3.","whyCorrect":"Dado, classificação, bucket policy, IAM policy, encryption settings e Block Public Access são responsabilidade do cliente; AWS garante durabilidade, disponibilidade e infra do S3.","whyWrong":{"A":"Macie ajuda mas é serviço opcional e pago, não automático global","C":"AWS não cria policies por compliance específico","D":"Classificação e controle de acesso a dados nunca são 50/50 — são 100% responsabilidade do cliente. O cliente conhece o conteúdo dos dados (PII, PHI, financeiros) e o modelo de autorização do seu negócio; a AWS não tem contexto de domínio para classificar. A AWS oferece ferramentas (Macie, IAM Access Analyzer) mas a decisão e configuração são do cliente."},"keyConcept":"Princípio: ''security IN the cloud'' = dados e configurações.","tutorSeeds":["Pode explicar com mais detalhe: Princípio: ''security IN the cloud'' = dados e configurações?","Quais cenários reais aplicam Princípio: ''security IN the cloud'' = dados e configurações?","Como IAM se compara com alternativas?"]}'::jsonb, 'Security & Compliance', 'Security & Compliance', 'easy', 'best-practice', '["shared-responsibility","s3","data-classification"]'::jsonb, 'ai-draft', 'active', now(), now()),
    ('clf-c02-sec-005', 'aws-clf', 'Uma equipe roda containers em AWS Fargate (ECS) e questiona quem patcha o host EC2 onde a task roda. Qual a divisão correta sob o Shared Responsibility Model?', '[{"id":"A","text":"Cliente patcha o host EC2 do Fargate via SSM"},{"id":"B","text":"AWS é responsável pelo host e pelo runtime do container; cliente cuida da imagem e do código"},{"id":"C","text":"AWS patcha a imagem do container automaticamente"},{"id":"D","text":"Não há host porque Fargate é Lambda em outro nome"}]'::jsonb, 'B', '{"summary":"Em Fargate o cliente não enxerga nem patcha o host; AWS cuida do hypervisor, kernel e runtime de container.","whyCorrect":"Em Fargate o cliente não enxerga nem patcha o host; AWS cuida do hypervisor, kernel e runtime de container. Cliente é dono da imagem, código, dependências e IAM da task role.","whyWrong":{"A":"Cliente não acessa o host","D":"Fargate ≠ Lambda (modelo task/pod, não função).","C":"AWS não patcha imagens de container do cliente — a imagem (Dockerfile, libs, app code) é 100% responsabilidade do cliente. AWS apenas executa a imagem fornecida. Para manter imagens atualizadas, o cliente usa ECR image scanning, automated rebuilds com base images patched, ou Inspector for ECR. Esta opção confundiria runtime do Fargate (managed) com o conteúdo da imagem (cliente)."},"keyConcept":"Regra: serverless container → AWS cuida abaixo da imagem.","tutorSeeds":["Pode explicar com mais detalhe: Regra: serverless container → AWS cuida abaixo da imagem?","Quais cenários reais aplicam Regra: serverless container → AWS cuida abaixo da imagem?","Como AWS se compara com alternativas?"]}'::jsonb, 'Security & Compliance', 'Security & Compliance', 'medium', 'scenario', '["shared-responsibility","fargate","containers"]'::jsonb, 'ai-draft', 'active', now(), now()),
    ('clf-c02-sec-006', 'aws-clf', 'Um auditor pergunta quem é responsável pela segurança física dos datacenters onde rodam workloads AWS de uma empresa brasileira na região sa-east-1. Qual a resposta correta?', '[{"id":"A","text":"O cliente, pois contratou a região sa-east-1"},{"id":"B","text":"AWS, pois faz parte da ''security OF the cloud''"},{"id":"C","text":"Compartilhada: AWS controla acesso físico, cliente audita o local presencialmente"},{"id":"D","text":"Cliente, se contratar plano Enterprise Support"}]'::jsonb, 'B', '{"summary":"Segurança física, controle de acesso a datacenters, energia, refrigeração e descarte de hardware são 100% AWS — ''security OF the cloud''.","whyCorrect":"Segurança física, controle de acesso a datacenters, energia, refrigeração e descarte de hardware são 100% AWS — ''security OF the cloud''.","whyWrong":{"C":"planos de suporte não dão acesso físico","A":"Contratar uma região AWS é apenas escolher onde os workloads rodam — não transfere a responsabilidade da segurança física dos datacenters para o cliente. AWS mantém controle exclusivo do acesso físico em todas as regiões (comerciais, GovCloud, China). O cliente paga por uso, mas o controle físico permanece com a AWS.","D":"Planos de suporte (Basic, Developer, Business, Enterprise) afetam o nível de assistência técnica recebida — não alteram o Shared Responsibility Model. Mesmo em Enterprise Support, a segurança física continua 100% AWS; nenhum plano dá ao cliente acesso aos datacenters."},"keyConcept":"Princípio fundacional do Shared Responsibility Model.","tutorSeeds":["Pode explicar com mais detalhe: Princípio fundacional do Shared Responsibility Model?","Quais cenários reais aplicam Princípio fundacional do Shared Responsibility Model?","Como AWS se compara com alternativas?"]}'::jsonb, 'Security & Compliance', 'Security & Compliance', 'easy', 'recall', '["shared-responsibility","physical-security"]'::jsonb, 'ai-draft', 'active', now(), now()),
    ('clf-c02-sec-007', 'aws-clf', 'Uma empresa usa Amazon DynamoDB em modo on-demand. Quem é responsável por escalar a infraestrutura subjacente e por configurar criptografia em repouso, respectivamente?', '[{"id":"A","text":"AWS escala; cliente habilita encryption (já vem ligada por padrão)"},{"id":"B","text":"Cliente escala; cliente habilita encryption"},{"id":"C","text":"AWS escala; AWS habilita encryption e bloqueia o cliente de mudar"},{"id":"D","text":"Cliente escala via Auto Scaling Group; AWS habilita encryption"}]'::jsonb, 'A', '{"summary":"DynamoDB on-demand escala throughput automaticamente (AWS-managed); encryption at rest é habilitada por padrão e o cliente pode escolher entre AWS owned, AWS managed ou customer managed KMS keys.","whyCorrect":"DynamoDB on-demand escala throughput automaticamente (AWS-managed); encryption at rest é habilitada por padrão e o cliente pode escolher entre AWS owned, AWS managed ou customer managed KMS keys.","whyWrong":{"B":"Cliente não escala DynamoDB on-demand","C":"cliente pode mudar a key.","D":"DynamoDB é serverless — não há Auto Scaling Groups, instâncias EC2 ou capacidade visível para o cliente escalar. Em modo on-demand, o próprio DynamoDB ajusta throughput automaticamente; em provisioned, o cliente define RCU/WCU mas não toca em servidor. Auto Scaling Group é construto exclusivo do EC2."},"keyConcept":"Regra: managed → AWS cuida da infra; configurações de segurança são do cliente (mas defaults seguros).","tutorSeeds":["Pode explicar com mais detalhe: Regra: managed → AWS cuida da infra; configurações de segurança são do cliente (mas defaults seguros)?","Quais cenários reais aplicam Regra: managed → AWS cuida da infra; configurações de segurança são do cliente (mas defaults seguros)?","Como AWS-managed se compara com alternativas?"]}'::jsonb, 'Security & Compliance', 'Security & Compliance', 'medium', 'scenario', '["shared-responsibility","dynamodb","encryption"]'::jsonb, 'ai-draft', 'active', now(), now()),
    ('clf-c02-sec-008', 'aws-clf', 'Em uma arquitetura híbrida via AWS Direct Connect, a equipe questiona quem é responsável pela criptografia do tráfego que sai do datacenter on-premises até chegar ao roteador AWS. Qual a resposta correta?', '[{"id":"A","text":"AWS criptografa automaticamente todo tráfego do Direct Connect"},{"id":"B","text":"O cliente, usando MACsec ou um VPN sobre o Direct Connect"},{"id":"C","text":"Compartilhada: AWS criptografa na ida, cliente na volta"},{"id":"D","text":"Não é necessário pois o link é dedicado e fisicamente isolado"}]'::jsonb, 'B', '{"summary":"Direct Connect é link dedicado mas não criptografado por padrão; cliente pode habilitar MACsec (em portas suportadas) ou rodar um Site-to-Site VPN sobre o DX para encryption in transit.","whyCorrect":"Direct Connect é link dedicado mas não criptografado por padrão; cliente pode habilitar MACsec (em portas suportadas) ou rodar um Site-to-Site VPN sobre o DX para encryption in transit.","whyWrong":{"A":"AWS não criptografa o tráfego do cliente sem solicitação","D":"''dedicado'' não significa criptografado.","C":"Direct Connect é um link L2/L3 simétrico — não há diferença de tratamento entre ''ida'' e ''volta''. Se há criptografia, ela cobre o tráfego bidirecionalmente (MACsec opera nas portas do link; VPN sobre DX cifra ambos os sentidos). Esta opção é tecnicamente incoerente."},"keyConcept":"Regra: encryption in transit em DX → cliente.","tutorSeeds":["Pode explicar com mais detalhe: Regra: encryption in transit em DX → cliente?","Quais cenários reais aplicam Regra: encryption in transit em DX → cliente?","Como MACsec se compara com alternativas?"]}'::jsonb, 'Security & Compliance', 'Security & Compliance', 'hard', 'scenario', '["shared-responsibility","direct-connect","encryption-in-transit"]'::jsonb, 'ai-draft', 'active', now(), now()),
    ('clf-c02-sec-009', 'aws-clf', 'Uma empresa argumenta que, por usar AWS, não precisa mais se preocupar com IAM, criptografia ou bucket policies, pois ''a AWS cuida da segurança''. Qual afirmação descreve melhor o erro desse raciocínio?', '[{"id":"A","text":"AWS só cuida da segurança se o cliente assinar Enterprise Support"},{"id":"B","text":"AWS é responsável pela ''security OF the cloud''; cliente pela ''security IN the cloud''"},{"id":"C","text":"AWS cuida de tudo, mas só em regiões com compliance HIPAA"},{"id":"D","text":"O cliente é responsável por tudo; AWS é apenas provedor de hardware"}]'::jsonb, 'B', '{"summary":"Configurações como IAM, encryption, bucket policy, SG e classificação de dados são sempre do cliente — independente do plano de suporte ou região.","whyCorrect":"Configurações como IAM, encryption, bucket policy, SG e classificação de dados são sempre do cliente — independente do plano de suporte ou região.","whyWrong":{"C":"HIPAA não muda divisão","D":"AWS faz muito mais que hardware (managed services).","A":"Plano de suporte (Basic, Developer, Business, Enterprise) afeta SLA, acesso a TAM e Trusted Advisor — não muda o Shared Responsibility Model. Mesmo em Enterprise Support, o cliente continua responsável por IAM, encryption e configurações. Suporte não é serviço de configuração de segurança da conta do cliente."},"keyConcept":"Princípio fundamental: dois lados, cada um com seu escopo.","tutorSeeds":["Pode explicar com mais detalhe: Princípio fundamental: dois lados, cada um com seu escopo?","Quais cenários reais aplicam Princípio fundamental: dois lados, cada um com seu escopo?","Como IAM se compara com alternativas?"]}'::jsonb, 'Security & Compliance', 'Security & Compliance', 'easy', 'best-practice', '["shared-responsibility","fundamentals"]'::jsonb, 'ai-draft', 'active', now(), now()),
    ('clf-c02-sec-010', 'aws-clf', 'Uma equipe usa Amazon S3 com SSE-S3 (chaves gerenciadas pela AWS). Quem é responsável pela rotação das chaves de criptografia e quem garante a durabilidade dos dados criptografados?', '[{"id":"A","text":"Cliente roda script de rotação; AWS garante durabilidade"},{"id":"B","text":"AWS rotaciona as chaves; AWS garante durabilidade"},{"id":"C","text":"Cliente rotaciona; cliente faz backup cross-region"},{"id":"D","text":"AWS rotaciona; cliente garante durabilidade ativando versioning"}]'::jsonb, 'B', '{"summary":"Em SSE-S3 a AWS gerencia totalmente as chaves (criação, rotação, proteção); a durabilidade 11 9s do S3 também é garantida pela AWS independentemente da classe de encryption.","whyCorrect":"Em SSE-S3 a AWS gerencia totalmente as chaves (criação, rotação, proteção); a durabilidade 11 9s do S3 também é garantida pela AWS independentemente da classe de encryption.","whyWrong":{"D":"backups e versioning são camadas adicionais opcionais, não substituem durabilidade nativa.","A":"Em SSE-S3, a AWS rotaciona as chaves automaticamente — não há script do cliente. O cliente não tem visibilidade nem controle das chaves. Esta opção descreveria uma má interpretação do modelo SSE-S3. Para o cliente rotacionar manualmente, seria necessário SSE-KMS com CMK customer-managed.","C":"Durabilidade dos 11 9s do S3 é garantida pela AWS independente de configuração do cliente — o objeto é replicado entre AZs internamente. Cross-region replication é defesa adicional contra desastre regional, mas não é prerequisito de durabilidade. SSE-S3 não exige nem é compatível com ''rotação manual''."},"keyConcept":"Regra: SSE-S3 = zero gestão de chaves para o cliente.","tutorSeeds":["Pode explicar com mais detalhe: Regra: SSE-S3 = zero gestão de chaves para o cliente?","Quais cenários reais aplicam Regra: SSE-S3 = zero gestão de chaves para o cliente?","Como SSE-S3 se compara com alternativas?"]}'::jsonb, 'Security & Compliance', 'Security & Compliance', 'medium', 'recall', '["shared-responsibility","s3","encryption","sse-s3"]'::jsonb, 'ai-draft', 'active', now(), now()),
    ('clf-c02-sec-011', 'aws-clf', 'Uma empresa criou um IAM user para o admin Maria e anexou diretamente a policy AdministratorAccess. Qual problema essa abordagem viola em relação às boas práticas AWS de IAM?', '[{"id":"A","text":"Princípio do menor privilégio, dando acesso amplo sem necessidade demonstrada"},{"id":"B","text":"IAM users não podem receber policies diretamente"},{"id":"C","text":"AdministratorAccess só funciona em IAM groups"},{"id":"D","text":"Maria precisa ser raiz da conta para usar essa policy"}]'::jsonb, 'A', '{"summary":"Conceder AdministratorAccess sem justificativa contraria ''grant least privilege''; o ideal é dar permissões específicas via groups/roles e revisar regularmente.","whyCorrect":"Conceder AdministratorAccess sem justificativa contraria ''grant least privilege''; o ideal é dar permissões específicas via groups/roles e revisar regularmente.","whyWrong":{"B":"IAM users aceitam policies inline e managed direto","C":"AdministratorAccess funciona em users/groups/roles","D":"Para usar a policy AdministratorAccess (ou qualquer outra), Maria precisa ser apenas um IAM principal (user ou role) — não tem nenhuma relação com o usuário root da conta. Root é o credential owner da conta AWS e existe apenas um por conta. Esta opção mistura conceitos: IAM users podem receber qualquer policy independentemente do root."},"keyConcept":"Best practice: usar IAM Identity Center ou roles temporárias em vez de usuários permanentes com admin.","tutorSeeds":["Pode explicar com mais detalhe: Best practice: usar IAM Identity Center ou roles temporárias em vez de usuários permanentes com admin?","Quais cenários reais aplicam Best practice: usar IAM Identity Center ou roles temporárias em vez de usuários permanentes com admin?"]}'::jsonb, 'Security & Compliance', 'Security & Compliance', 'easy', 'best-practice', '["iam","least-privilege","best-practices"]'::jsonb, 'ai-draft', 'active', now(), now()),
    ('clf-c02-sec-012', 'aws-clf', 'A equipe de segurança recebeu recomendação para proteger o usuário root da conta AWS. Além de não usá-lo para tarefas do dia a dia, qual controle adicional é mais crítico aplicar imediatamente?', '[{"id":"A","text":"Habilitar MFA no usuário root"},{"id":"B","text":"Criar access keys do root e guardar em Secrets Manager"},{"id":"C","text":"Conceder ao root a policy AdministratorAccess"},{"id":"D","text":"Excluir o usuário root após criar um IAM admin"}]'::jsonb, 'A', '{"summary":"MFA no root é controle número um — root tem poder total e irrevogável (fechar conta, mudar billing); MFA reduz drasticamente risco de comprometimento.","whyCorrect":"MFA no root é controle número um — root tem poder total e irrevogável (fechar conta, mudar billing); MFA reduz drasticamente risco de comprometimento.","whyWrong":{"B":"AWS recomenda fortemente NÃO criar access keys do root root já tem permissões totais por design root não pode ser excluído.","C":"O usuário root já tem implicitamente acesso TOTAL e irrevogável à conta — atribuir AdministratorAccess é redundante e não adiciona segurança. Pior: criar/manter access keys e policies para root é justamente o anti-padrão que a AWS desaconselha. Root deve ter MFA, senha forte e ser usado raramente.","D":"Não é possível excluir o usuário root — ele é inerente à conta AWS e existe enquanto a conta existir. A ''best practice'' não é deletar, mas trancar: MFA, senha aleatória forte, sem access keys, usado apenas para tarefas exclusivas (mudar billing, fechar conta). Para tarefas do dia a dia, criar IAM admins via Identity Center."},"keyConcept":"Best practice: root só para tarefas exclusivas (mudar plano de suporte, billing), com MFA e senha forte.","tutorSeeds":["Pode explicar com mais detalhe: Best practice: root só para tarefas exclusivas (mudar plano de suporte, billing), com MFA e senha forte?","Quais cenários reais aplicam Best practice: root só para tarefas exclusivas (mudar plano de suporte, billing), com MFA e senha forte?","Como MFA se compara com alternativas?"]}'::jsonb, 'Security & Compliance', 'Security & Compliance', 'easy', 'best-practice', '["iam","root-user","mfa"]'::jsonb, 'ai-draft', 'active', now(), now()),
    ('clf-c02-sec-013', 'aws-clf', 'Uma empresa tem 200 colaboradores que precisam de acesso a múltiplas contas AWS de produção e desenvolvimento. Em vez de criar IAM users em cada conta, qual serviço AWS oferece SSO centralizado com integração ao provedor de identidade corporativo?', '[{"id":"A","text":"AWS IAM Identity Center (sucessor do AWS SSO)"},{"id":"B","text":"Amazon Cognito User Pools"},{"id":"C","text":"AWS Directory Service Simple AD"},{"id":"D","text":"AWS Secrets Manager com rotação automática"}]'::jsonb, 'A', '{"summary":"IAM Identity Center integra com Active Directory, Okta, Google Workspace via SAML 2.0 e fornece acesso centralizado a múltiplas contas AWS via permission sets.","whyCorrect":"IAM Identity Center integra com Active Directory, Okta, Google Workspace via SAML 2.0 e fornece acesso centralizado a múltiplas contas AWS via permission sets.","whyWrong":{"B":"Cognito é para autenticação de usuários finais em apps","C":"Simple AD é diretório managed para EC2/RDS, não SSO multi-account","D":"Secrets Manager guarda segredos, não autentica humanos."},"keyConcept":"Padrão AWS para identidade corporativa multi-account.","tutorSeeds":["Pode explicar com mais detalhe: Padrão AWS para identidade corporativa multi-account?","Quais cenários reais aplicam Padrão AWS para identidade corporativa multi-account?","Como IAM se compara com alternativas?"]}'::jsonb, 'Security & Compliance', 'Security & Compliance', 'medium', 'scenario', '["iam","identity-center","sso","multi-account"]'::jsonb, 'ai-draft', 'active', now(), now()),
    ('clf-c02-sec-014', 'aws-clf', 'Um desenvolvedor precisa que uma aplicação em EC2 publique mensagens em uma fila SQS. Qual é a forma mais segura recomendada pela AWS para conceder essa permissão?', '[{"id":"A","text":"Criar IAM user e armazenar access keys em arquivo no disco da instância"},{"id":"B","text":"Anexar uma IAM role à instância via instance profile com permissão sqs:SendMessage"},{"id":"C","text":"Liberar a fila SQS publicamente via resource policy"},{"id":"D","text":"Compartilhar a senha do IAM admin com a aplicação"}]'::jsonb, 'B', '{"summary":"Instance profiles entregam credenciais temporárias rotacionadas via IMDS — sem secret persistente.","whyCorrect":"Instance profiles entregam credenciais temporárias rotacionadas via IMDS — sem secret persistente.","whyWrong":{"A":"Access keys em disco são anti-pattern","C":"fila pública viola least privilege e expõe ao mundo","D":"Compartilhar credenciais de admin com uma aplicação é o pior anti-padrão de segurança: dá poder ilimitado, é difícil rotacionar, vaza facilmente em logs/disco e auditoria fica impossível (chamadas aparecem como o admin humano, não como a app). Aplicações devem usar credenciais de IAM role com escopo mínimo via instance profile."},"keyConcept":"Regra: workloads usam roles, nunca long-lived keys.","tutorSeeds":["Pode explicar com mais detalhe: Regra: workloads usam roles, nunca long-lived keys?","Quais cenários reais aplicam Regra: workloads usam roles, nunca long-lived keys?","Como IMDS se compara com alternativas?"]}'::jsonb, 'Security & Compliance', 'Security & Compliance', 'easy', 'best-practice', '["iam","instance-profile","ec2","least-privilege"]'::jsonb, 'ai-draft', 'active', now(), now()),
    ('clf-c02-sec-015', 'aws-clf', 'Uma empresa quer que desenvolvedores tenham acesso temporário a recursos AWS apenas durante o expediente, com elevação por aprovação. Qual recurso IAM se encaixa melhor para credenciais temporárias com escopo limitado?', '[{"id":"A","text":"IAM roles assumidas via AWS STS (sts:AssumeRole)"},{"id":"B","text":"IAM users com senha que expira a cada 8 horas"},{"id":"C","text":"Access keys do root user rotacionadas diariamente"},{"id":"D","text":"Service-linked roles criadas automaticamente pelos serviços"}]'::jsonb, 'A', '{"summary":"Roles via STS retornam credenciais temporárias (15min a 12h), com policies anexadas e auditáveis no CloudTrail.","whyCorrect":"Roles via STS retornam credenciais temporárias (15min a 12h), com policies anexadas e auditáveis no CloudTrail.","whyWrong":{"C":"root nunca deve ter access keys","D":"service-linked roles servem para o próprio serviço AWS atuar em nome do cliente, não para humanos.","B":"IAM users com senha de expiração curta ainda são credenciais long-lived (a chave/senha persiste no disco/cofre do usuário) e não fornecem escopo limitado por sessão. Para acesso temporário com escopo e elevação por aprovação, o padrão é roles assumidas via STS, que retornam credenciais com TTL curto e auditoria por sessão. Senhas curtas são fricção sem ganho real de segurança."},"keyConcept":"Padrão de just-in-time access.","tutorSeeds":["Pode explicar com mais detalhe: Padrão de just-in-time access?","Quais cenários reais aplicam Padrão de just-in-time access?","Como STS se compara com alternativas?"]}'::jsonb, 'Security & Compliance', 'Security & Compliance', 'medium', 'scenario', '["iam","sts","temporary-credentials"]'::jsonb, 'ai-draft', 'active', now(), now()),
    ('clf-c02-sec-016', 'aws-clf', 'Uma startup tem 5 desenvolvedores que precisam das mesmas permissões em S3 e CloudWatch Logs. Qual é a abordagem mais eficiente de gerenciar essas permissões no IAM?', '[{"id":"A","text":"Anexar policies inline iguais em cada IAM user manualmente"},{"id":"B","text":"Criar um IAM group com a policy necessária e adicionar os 5 users ao group"},{"id":"C","text":"Criar 5 roles iguais e fazer os users assumirem cada um a sua"},{"id":"D","text":"Compartilhar credenciais de um único IAM user entre os 5"}]'::jsonb, 'B', '{"summary":"IAM groups permitem agrupar users e anexar policies uma vez — mudanças propagam para todos os membros.","whyCorrect":"IAM groups permitem agrupar users e anexar policies uma vez — mudanças propagam para todos os membros.","whyWrong":{"A":"Inline por user duplica esforço","C":"5 roles iguais é overkill","D":"compartilhar credenciais viola accountability e CloudTrail mostraria mesmo identificador."},"keyConcept":"Best practice: groups para permissões por função/role organizacional.","tutorSeeds":["Pode explicar com mais detalhe: Best practice: groups para permissões por função/role organizacional?","Quais cenários reais aplicam Best practice: groups para permissões por função/role organizacional?","Como IAM se compara com alternativas?"]}'::jsonb, 'Security & Compliance', 'Security & Compliance', 'easy', 'best-practice', '["iam","groups","best-practices"]'::jsonb, 'ai-draft', 'active', now(), now()),
    ('clf-c02-sec-017', 'aws-clf', 'Uma equipe quer garantir que, mesmo se um desenvolvedor anexar uma policy ampla a si próprio, não consiga ultrapassar um teto máximo de permissões definido pela governança. Qual recurso IAM endereça esse cap individual por usuário/role?', '[{"id":"A","text":"IAM permissions boundary"},{"id":"B","text":"Service Control Policy (SCP) na Organization"},{"id":"C","text":"Resource-based policy no bucket S3"},{"id":"D","text":"IAM Access Analyzer rules"}]'::jsonb, 'A', '{"summary":"Permissions boundary é o teto efetivo de permissões para um principal (user ou role); só é permitido o que estiver na interseção da permission policy E da boundary.","whyCorrect":"Permissions boundary é o teto efetivo de permissões para um principal (user ou role); só é permitido o que estiver na interseção da permission policy E da boundary.","whyWrong":{"C":"resource-based policy é por recurso","D":"Access Analyzer detecta exposição, não cria caps.","B":"SCP define o teto para TODAS as IAM identities de UMA conta (ou OU) — não permite cap diferenciado por usuário individual dentro da mesma conta. Para limitar Maria especificamente sem afetar João, a ferramenta correta é permissions boundary anexada ao principal de Maria. SCPs são broadside (escopo conta/OU); boundaries são per-principal."},"keyConcept":"Use case clássico: delegar criação de IAM users a devs com boundary que limita o que eles podem dar.","tutorSeeds":["Pode explicar com mais detalhe: Use case clássico: delegar criação de IAM users a devs com boundary que limita o que eles podem dar?","Quais cenários reais aplicam Use case clássico: delegar criação de IAM users a devs com boundary que limita o que eles podem dar?"]}'::jsonb, 'Security & Compliance', 'Security & Compliance', 'hard', 'scenario', '["iam","permissions-boundary","delegation"]'::jsonb, 'ai-draft', 'active', now(), now()),
    ('clf-c02-sec-018', 'aws-clf', 'Uma policy IAM contém um Allow para s3:* e a SCP da Organization nega s3:DeleteBucket. Quando o usuário tenta deletar um bucket, o que acontece?', '[{"id":"A","text":"A ação é permitida pois a IAM policy é mais específica"},{"id":"B","text":"A ação é negada — Deny explícito da SCP sempre prevalece"},{"id":"C","text":"Depende do tag aplicado ao bucket"},{"id":"D","text":"Aplica a policy criada mais recentemente"}]'::jsonb, 'B', '{"summary":"Avaliação IAM é: Deny explícito > Allow explícito > Deny implícito.","whyCorrect":"Avaliação IAM é: Deny explícito > Allow explícito > Deny implícito. SCP com Deny corta o galho independente do que a IAM policy permita.","whyWrong":{"A":"IAM policy não ''sobrepõe'' SCP tags só influenciam se a policy usa condition keys","C":"Tags não alteram automaticamente a precedência de Deny — só importam se a policy contiver Condition explicitamente referenciando a tag. Sem essa condition, o Deny da SCP em s3:DeleteBucket aplica-se a todos os buckets, independente de tag. Esta opção seria relevante apenas com ABAC bem definido.","D":"Avaliação IAM não tem semântica de ''policy mais recente vence'' — a ordem cronológica é irrelevante. O motor avalia todas as policies aplicáveis e aplica precedence: Deny explícito > Allow explícito > Deny implícito (default). Não há tiebreak por data."},"keyConcept":"Regra: efeito efetivo = interseção entre IAM, SCP, permission boundary, resource policy e session policies.","tutorSeeds":["Pode explicar com mais detalhe: Regra: efeito efetivo = interseção entre IAM, SCP, permission boundary, resource policy e session policies?","Quais cenários reais aplicam Regra: efeito efetivo = interseção entre IAM, SCP, permission boundary, resource policy e session policies?","Como IAM se compara com alternativas?"]}'::jsonb, 'Security & Compliance', 'Security & Compliance', 'hard', 'scenario', '["iam","scp","policy-evaluation"]'::jsonb, 'ai-draft', 'active', now(), now()),
    ('clf-c02-sec-019', 'aws-clf', 'Após um quase-incidente, a equipe decidiu exigir MFA para qualquer ação em IAM users com permissões administrativas. Qual mecanismo IAM aplica essa exigência de MFA na própria policy?', '[{"id":"A","text":"Adicionar Condition aws:MultiFactorAuthPresent na policy"},{"id":"B","text":"Habilitar MFA no console e a policy é aplicada automaticamente"},{"id":"C","text":"Usar uma SCP global com Deny se IP for público"},{"id":"D","text":"Marcar a policy como ''MFA-only'' na role"}]'::jsonb, 'A', '{"summary":"Condition keys aws:MultiFactorAuthPresent / aws:MultiFactorAuthAge permitem exigir MFA por ação na policy.","whyCorrect":"Condition keys aws:MultiFactorAuthPresent / aws:MultiFactorAuthAge permitem exigir MFA por ação na policy.","whyWrong":{"B":"Habilitar MFA não força uso para chamadas de API sem condition","D":"não existe atributo ''MFA-only'' nativo em role.","C":"SCP com Deny baseado em IP público é controle de origem de rede, não de presença de MFA — bloqueia chamadas vindas de fora da empresa mas permite chamadas internas sem MFA. Não atende o requisito ''exigir MFA para ações administrativas''. SCP de IP seria correto para ''permitir só de IPs corporativos''."},"keyConcept":"Padrão: combinar MFA Required no IAM + sts:GetSessionToken com MFA token.","tutorSeeds":["Pode explicar com mais detalhe: Padrão: combinar MFA Required no IAM + sts:GetSessionToken com MFA token?","Quais cenários reais aplicam Padrão: combinar MFA Required no IAM + sts:GetSessionToken com MFA token?","Como MFA se compara com alternativas?"]}'::jsonb, 'Security & Compliance', 'Security & Compliance', 'hard', 'best-practice', '["iam","mfa","condition-keys"]'::jsonb, 'ai-draft', 'active', now(), now()),
    ('clf-c02-sec-020', 'aws-clf', 'Uma desenvolvedora precisa que uma função Lambda leia objetos de um bucket S3 em outra conta AWS. Qual abordagem cumpre o cross-account access de forma idiomática?', '[{"id":"A","text":"Lambda execution role com sts:AssumeRole numa role da outra conta + bucket policy permitindo essa role"},{"id":"B","text":"Tornar o bucket público para facilitar a leitura"},{"id":"C","text":"Compartilhar access keys do IAM user da outra conta com a Lambda"},{"id":"D","text":"Replicar o bucket inteiro para a conta da Lambda"}]'::jsonb, 'A', '{"summary":"Padrão cross-account: role na conta destino com trust policy aceitando a role da origem; a Lambda assume essa role via STS e usa as credenciais temporárias.","whyCorrect":"Padrão cross-account: role na conta destino com trust policy aceitando a role da origem; a Lambda assume essa role via STS e usa as credenciais temporárias. Bucket policy adicional permite a role destino.","whyWrong":{"B":"Bucket público é furo de segurança replicação é overkill para leitura.","C":"access keys cruzadas viola least privilege e accountability","D":"Cross-Region/Cross-Account Replication copia o bucket inteiro para a conta da Lambda — caro (custo de armazenamento duplicado), introduz lag de replicação e duplica superfície de ataque. Para apenas LER objetos sob demanda, o padrão correto é cross-account com role assumida; replicação seria justificada por requisito de DR ou data residency, não por acesso pontual."},"keyConcept":"Regra: cross-account = role assumida, não credenciais compartilhadas.","tutorSeeds":["Pode explicar com mais detalhe: Regra: cross-account = role assumida, não credenciais compartilhadas?","Quais cenários reais aplicam Regra: cross-account = role assumida, não credenciais compartilhadas?","Como STS se compara com alternativas?"]}'::jsonb, 'Security & Compliance', 'Security & Compliance', 'medium', 'scenario', '["iam","cross-account","sts","lambda"]'::jsonb, 'ai-draft', 'active', now(), now()),
    ('clf-c02-sec-021', 'aws-clf', 'Uma policy IAM tem efeito Allow para ec2:* mas o usuário recebe AccessDenied ao tentar iniciar uma instância. CloudTrail mostra que a chamada foi explicitamente negada por uma SCP. O que isso indica?', '[{"id":"A","text":"A SCP é avaliada antes da IAM policy e impede a ação no nível da conta"},{"id":"B","text":"A IAM policy está mal escrita e precisa de aspas duplas"},{"id":"C","text":"O usuário não habilitou MFA"},{"id":"D","text":"EC2 está fora de suporte naquela região"}]'::jsonb, 'A', '{"summary":"SCPs definem o teto máximo de permissões para principals dentro da conta; qualquer Deny da SCP bloqueia mesmo que IAM permita.","whyCorrect":"SCPs definem o teto máximo de permissões para principals dentro da conta; qualquer Deny da SCP bloqueia mesmo que IAM permita.","whyWrong":{"D":"suporte de serviço não negaria via SCP.","B":"AccessDenied por SCP é uma decisão de autorização do plano IAM/Organizations — não tem relação com sintaxe JSON da policy. Se houvesse erro de sintaxe, a policy não seria salva pelo IAM. CloudTrail registra ''explicitly denied by SCP'', que é diagnostic definitivo de bloqueio por Organization-level policy.","C":"MFA está ausente da causa raiz: a SCP nega explicitamente a ação, independentemente de MFA. Habilitar MFA não removeria o Deny da SCP. Esta opção seria relevante se o erro fosse ''this action requires MFA'', vindo de uma policy com aws:MultiFactorAuthPresent condition."},"keyConcept":"Regra: efeito final é interseção entre todos os layers de policy (SCP ∩ IAM ∩ boundary ∩ resource ∩ session).","tutorSeeds":["Pode explicar com mais detalhe: Regra: efeito final é interseção entre todos os layers de policy (SCP ∩ IAM ∩ boundary ∩ resource ∩ session)?","Quais cenários reais aplicam Regra: efeito final é interseção entre todos os layers de policy (SCP ∩ IAM ∩ boundary ∩ resource ∩ session)?","Como SCPs se compara com alternativas?"]}'::jsonb, 'Security & Compliance', 'Security & Compliance', 'medium', 'troubleshoot', '["iam","scp","troubleshoot"]'::jsonb, 'ai-draft', 'active', now(), now()),
    ('clf-c02-sec-022', 'aws-clf', 'Um time de auditoria pede um relatório listando quando cada IAM user fez login, rotacionou access key e quais tinham MFA. Qual ferramenta nativa AWS gera esse relatório consolidado?', '[{"id":"A","text":"IAM Credential Report"},{"id":"B","text":"AWS Config Conformance Pack"},{"id":"C","text":"Amazon Inspector findings"},{"id":"D","text":"CloudTrail Insights events"}]'::jsonb, 'A', '{"summary":"Credential Report é CSV gerado sob demanda com status de senha, MFA, access keys (idade, último uso) por user.","whyCorrect":"Credential Report é CSV gerado sob demanda com status de senha, MFA, access keys (idade, último uso) por user.","whyWrong":{"B":"Config Conformance Pack avalia compliance via rules","C":"Inspector cuida de vulnerabilidades em workloads","D":"CloudTrail Insights detecta anomalias de API call volume."},"keyConcept":"Regra: relatório consolidado de credenciais → IAM Credential Report.","tutorSeeds":["Pode explicar com mais detalhe: Regra: relatório consolidado de credenciais → IAM Credential Report?","Quais cenários reais aplicam Regra: relatório consolidado de credenciais → IAM Credential Report?","Como CSV se compara com alternativas?"]}'::jsonb, 'Security & Compliance', 'Security & Compliance', 'medium', 'scenario', '["iam","credential-report","audit"]'::jsonb, 'ai-draft', 'active', now(), now()),
    ('clf-c02-sec-023', 'aws-clf', 'A equipe quer revisar se há roles IAM com permissões nunca usadas para refinar least privilege. Qual recurso AWS analisa CloudTrail e sugere remoção de permissões não exercitadas?', '[{"id":"A","text":"IAM Access Analyzer — Unused Access findings"},{"id":"B","text":"AWS Trusted Advisor — categoria Service Limits"},{"id":"C","text":"Amazon Macie — sensitive data discovery"},{"id":"D","text":"AWS Shield Advanced — DDoS metrics"}]'::jsonb, 'A', '{"summary":"IAM Access Analyzer tem feature Unused Access (roles, permissions, credentials) que cruza CloudTrail com policies para flagging de privilégios não usados.","whyCorrect":"IAM Access Analyzer tem feature Unused Access (roles, permissions, credentials) que cruza CloudTrail com policies para flagging de privilégios não usados.","whyWrong":{"B":"Trusted Advisor cobre custo/perf/segurança em alto nível mas não policy refinement","C":"Macie é classificação de dados","D":"Shield é DDoS."},"keyConcept":"Use case: refinar least privilege com base em uso real.","tutorSeeds":["Pode explicar com mais detalhe: Use case: refinar least privilege com base em uso real?","Quais cenários reais aplicam Use case: refinar least privilege com base em uso real?","Como IAM se compara com alternativas?"]}'::jsonb, 'Security & Compliance', 'Security & Compliance', 'medium', 'best-practice', '["iam","access-analyzer","least-privilege"]'::jsonb, 'ai-draft', 'active', now(), now()),
    ('clf-c02-sec-024', 'aws-clf', 'Uma policy IAM customer-managed foi criada com ''Resource'': ''*'' para acesso a S3. A equipe de segurança classifica isso como risco. Qual prática reduz esse risco mantendo a funcionalidade?', '[{"id":"A","text":"Trocar Resource:* por ARNs específicos dos buckets necessários"},{"id":"B","text":"Adicionar versão 2012-10-17 à policy"},{"id":"C","text":"Mudar Effect de Allow para Allow-Specific"},{"id":"D","text":"Encriptar a policy com KMS"}]'::jsonb, 'A', '{"summary":"Resource:* dá permissão em todos os buckets da conta; limitar a ARNs específicos aplica least privilege ao nível de recurso.","whyCorrect":"Resource:* dá permissão em todos os buckets da conta; limitar a ARNs específicos aplica least privilege ao nível de recurso.","whyWrong":{"B":"Version 2012-10-17 é apenas formato","C":"não há ''Allow-Specific''","D":"Policies IAM são objetos JSON públicos dentro da conta — não há mecanismo de criptografá-las com KMS, e isso não reduziria o risco da Resource:* (a permissão continua sendo amplíssima). Risco de Resource:* é semântico (escopo da permissão), não de confidencialidade do documento da policy."},"keyConcept":"Padrão: restringir Action E Resource ao mínimo necessário.","tutorSeeds":["Pode explicar com mais detalhe: Padrão: restringir Action E Resource ao mínimo necessário?","Quais cenários reais aplicam Padrão: restringir Action E Resource ao mínimo necessário?","Como ARNs se compara com alternativas?"]}'::jsonb, 'Security & Compliance', 'Security & Compliance', 'easy', 'best-practice', '["iam","least-privilege","resource-arn"]'::jsonb, 'ai-draft', 'active', now(), now()),
    ('clf-c02-sec-025', 'aws-clf', 'Uma empresa quer permitir que pipelines do GitHub Actions deployem para a AWS sem armazenar access keys long-lived nos secrets do repositório. Qual mecanismo IAM resolve isso?', '[{"id":"A","text":"OIDC provider no IAM + role assumida pelo GitHub Actions"},{"id":"B","text":"Criar IAM user dedicado com policy ampla e armazenar keys em GitHub Secrets"},{"id":"C","text":"Compartilhar a senha do root via secret encriptado"},{"id":"D","text":"Configurar GitHub Actions como service-linked role"}]'::jsonb, 'A', '{"summary":"Configurar token.actions.githubusercontent.com como OIDC provider no IAM permite que jobs do GitHub Actions assumam roles via STS — sem keys persistentes.","whyCorrect":"Configurar token.actions.githubusercontent.com como OIDC provider no IAM permite que jobs do GitHub Actions assumam roles via STS — sem keys persistentes.","whyWrong":{"B":"Keys long-lived em secrets é o anti-pattern que se quer eliminar","C":"root jamais","D":"service-linked role é para serviços AWS internos atuarem em nome do cliente."},"keyConcept":"Padrão moderno: federated identity para CI/CD.","tutorSeeds":["Pode explicar com mais detalhe: Padrão moderno: federated identity para CI/CD?","Quais cenários reais aplicam Padrão moderno: federated identity para CI/CD?","Como OIDC se compara com alternativas?"]}'::jsonb, 'Security & Compliance', 'Security & Compliance', 'hard', 'scenario', '["iam","oidc","federation","ci-cd"]'::jsonb, 'ai-draft', 'active', now(), now()),
    ('clf-c02-sec-026', 'aws-clf', 'Uma empresa tem 30 contas AWS organizadas em diferentes departamentos. Qual serviço AWS permite gerenciar todas centralmente, com consolidated billing, criação automatizada de contas e aplicação de políticas?', '[{"id":"A","text":"AWS Organizations"},{"id":"B","text":"AWS IAM Identity Center"},{"id":"C","text":"AWS Resource Access Manager"},{"id":"D","text":"AWS Config Aggregator"}]'::jsonb, 'A', '{"summary":"Organizations é o serviço de multi-account: consolidated billing, OUs, SCPs, criação programática de contas.","whyCorrect":"Organizations é o serviço de multi-account: consolidated billing, OUs, SCPs, criação programática de contas.","whyWrong":{"B":"IAM Identity Center cuida de acesso de pessoas","D":"Config Aggregator agrega findings de Config.","C":"AWS Resource Access Manager (RAM) compartilha recursos específicos (Subnets, Transit Gateways, License Manager configurations) entre contas — não gerencia hierarquia multi-account, billing consolidado, criação de contas ou SCPs. RAM seria a resposta para ''compartilhar uma subnet entre duas contas''; gerenciamento multi-account central é Organizations."},"keyConcept":"Padrão: Organizations é a base; outros serviços se integram a ele.","tutorSeeds":["Pode explicar com mais detalhe: Padrão: Organizations é a base; outros serviços se integram a ele?","Quais cenários reais aplicam Padrão: Organizations é a base; outros serviços se integram a ele?","Como OUs se compara com alternativas?"]}'::jsonb, 'Security & Compliance', 'Security & Compliance', 'easy', 'recall', '["organizations","multi-account"]'::jsonb, 'ai-draft', 'active', now(), now()),
    ('clf-c02-sec-027', 'aws-clf', 'Uma equipe de governança quer bloquear a criação de recursos fora das regiões sa-east-1 e us-east-1 em todas as contas-membro. Qual mecanismo dentro do AWS Organizations atende?', '[{"id":"A","text":"Service Control Policy com Deny aws:RequestedRegion ≠ sa-east-1, us-east-1"},{"id":"B","text":"IAM policy em cada conta-membro proibindo regiões"},{"id":"C","text":"AWS Config rule custom em cada conta"},{"id":"D","text":"Marcar tag ''AllowedRegion'' nos recursos"}]'::jsonb, 'A', '{"summary":"SCPs aplicam tetos globais; uma SCP com Deny baseada em aws:RequestedRegion bloqueia chamadas para regiões fora da lista, sem precisar mexer em cada conta.","whyCorrect":"SCPs aplicam tetos globais; uma SCP com Deny baseada em aws:RequestedRegion bloqueia chamadas para regiões fora da lista, sem precisar mexer em cada conta.","whyWrong":{"B":"IAM por conta exige aplicar 30 vezes e admins podem remover","C":"Config detecta após o fato e não bloqueia","D":"Tags são apenas metadados — não bloqueiam criação por si só. Para tag forçar comportamento, seria necessário uma SCP com Condition aws:RequestTag, e mesmo assim só funciona em CreateX que aceitem tags. Para bloqueio limpo por região em todas as APIs, SCP com aws:RequestedRegion é mais robusto e simples."},"keyConcept":"Padrão: controle preventivo multi-account → SCP.","tutorSeeds":["Pode explicar com mais detalhe: Padrão: controle preventivo multi-account → SCP?","Quais cenários reais aplicam Padrão: controle preventivo multi-account → SCP?","Como SCPs se compara com alternativas?"]}'::jsonb, 'Security & Compliance', 'Security & Compliance', 'medium', 'scenario', '["organizations","scp","governance","regions"]'::jsonb, 'ai-draft', 'active', now(), now()),
    ('clf-c02-sec-028', 'aws-clf', 'Uma empresa nova precisa configurar rapidamente uma landing zone multi-account com guardrails, log archive, conta de auditoria e baseline de segurança. Qual serviço AWS automatiza esse setup?', '[{"id":"A","text":"AWS Control Tower"},{"id":"B","text":"AWS CloudFormation StackSets manualmente"},{"id":"C","text":"AWS Trusted Advisor checks"},{"id":"D","text":"AWS Systems Manager Quick Setup"}]'::jsonb, 'A', '{"summary":"Control Tower provisiona landing zone com Organizations, IAM Identity Center, log archive, audit account, guardrails preventivos (SCPs) e detectivos (Config rules).","whyCorrect":"Control Tower provisiona landing zone com Organizations, IAM Identity Center, log archive, audit account, guardrails preventivos (SCPs) e detectivos (Config rules).","whyWrong":{"B":"StackSets puro exige construir tudo manualmente","C":"Trusted Advisor é checagem, não setup","D":"SSM Quick Setup faz baseline pontual, não landing zone completa."},"keyConcept":"Padrão: ambiente multi-account novo → Control Tower como fast path.","tutorSeeds":["Pode explicar com mais detalhe: Padrão: ambiente multi-account novo → Control Tower como fast path?","Quais cenários reais aplicam Padrão: ambiente multi-account novo → Control Tower como fast path?","Como IAM se compara com alternativas?"]}'::jsonb, 'Security & Compliance', 'Security & Compliance', 'medium', 'best-practice', '["control-tower","landing-zone","governance"]'::jsonb, 'ai-draft', 'active', now(), now()),
    ('clf-c02-sec-029', 'aws-clf', 'Em uma Organization existem OUs separadas para Prod, Dev e Sandbox. A equipe quer permissões diferentes por OU. Onde aplicar uma SCP que afete apenas as contas-membro da OU Sandbox?', '[{"id":"A","text":"Anexar a SCP diretamente à OU Sandbox"},{"id":"B","text":"Anexar a SCP à root da Organization"},{"id":"C","text":"Anexar a SCP a cada IAM user das contas Sandbox"},{"id":"D","text":"Aplicar via Resource Access Manager"}]'::jsonb, 'A', '{"summary":"SCPs podem ser anexadas à root, OU ou conta individual; escopo herda para baixo.","whyCorrect":"SCPs podem ser anexadas à root, OU ou conta individual; escopo herda para baixo. Anexar à OU Sandbox afeta exatamente suas contas-filhas.","whyWrong":{"B":"Anexar na root afeta tudo SCPs não vão em IAM users (são policies da Organization, não IAM)","C":"SCPs são anexadas a containers organizacionais (root, OU, conta) — NÃO a IAM users diretamente. SCP define o teto de uma conta inteira; IAM users dessa conta recebem permissões via IAM policy/groups/roles, e a SCP é aplicada implicitamente. Anexar SCP a user não existe na API.","D":"Resource Access Manager (RAM) compartilha RECURSOS (subnets, TGW) entre contas — não aplica policies de permissão. RAM não tem mecanismo de Deny por OU. Para limitar permissões em uma OU, a ferramenta é SCP em Organizations; RAM é orthogonal."},"keyConcept":"Padrão: aplique SCP no menor escopo que cumpre o requisito.","tutorSeeds":["Pode explicar com mais detalhe: Padrão: aplique SCP no menor escopo que cumpre o requisito?","Quais cenários reais aplicam Padrão: aplique SCP no menor escopo que cumpre o requisito?","Como SCPs se compara com alternativas?"]}'::jsonb, 'Security & Compliance', 'Security & Compliance', 'medium', 'scenario', '["organizations","scp","ou"]'::jsonb, 'ai-draft', 'active', now(), now()),
    ('clf-c02-sec-030', 'aws-clf', 'Uma empresa pediu para o time desabilitar ''todos os serviços que não são EC2 e S3'' nas contas Sandbox. Qual estratégia de SCP é mais segura e fácil de manter?', '[{"id":"A","text":"Deny list — começar com FullAWSAccess e adicionar Denies para serviços indesejados"},{"id":"B","text":"Allow list — começar com Deny implícito e permitir apenas EC2 e S3"},{"id":"C","text":"Configurar firewall na VPC bloqueando outros serviços"},{"id":"D","text":"Pedir aos devs que não usem outros serviços"}]'::jsonb, 'B', '{"summary":"Allow list (FullAWSAccess removida + permissões explícitas) garante que serviços novos não fiquem permitidos por padrão, evitando shadow IT em sandboxes.","whyCorrect":"Allow list (FullAWSAccess removida + permissões explícitas) garante que serviços novos não fiquem permitidos por padrão, evitando shadow IT em sandboxes.","whyWrong":{"A":"Deny list manual exige atualizar a cada novo serviço AWS lançado, fácil de furar","C":"firewall não controla APIs control plane","D":"Confiar em disciplina humana (''não usem outros serviços'') não é um controle — é um pedido. Em sandboxes, devs vão experimentar livremente sem barreira técnica, e violações só serão descobertas depois (e via auditoria, não prevenção). O pedido da empresa exige guardrail preventivo: SCP allow-list."},"keyConcept":"Best practice em sandboxes restritivos: allow list explícita.","tutorSeeds":["Pode explicar com mais detalhe: Best practice em sandboxes restritivos: allow list explícita?","Quais cenários reais aplicam Best practice em sandboxes restritivos: allow list explícita?","Como IT se compara com alternativas?"]}'::jsonb, 'Security & Compliance', 'Security & Compliance', 'hard', 'best-practice', '["organizations","scp","allow-list"]'::jsonb, 'ai-draft', 'active', now(), now()),
    ('clf-c02-sec-031', 'aws-clf', 'Uma empresa quer aplicar baselines de segurança detectivos (regras de Config) em todas as contas de uma OU, criando dashboard centralizado de não-conformidades. Qual recurso atende?', '[{"id":"A","text":"AWS Config Conformance Packs implantados via Organizations"},{"id":"B","text":"AWS WAF web ACLs replicadas"},{"id":"C","text":"Amazon Inspector network reachability findings"},{"id":"D","text":"AWS Shield Advanced protections"}]'::jsonb, 'A', '{"summary":"Conformance Packs agrupam rules de Config + remediation; via Organizations podem ser implantados em múltiplas contas com agregação centralizada.","whyCorrect":"Conformance Packs agrupam rules de Config + remediation; via Organizations podem ser implantados em múltiplas contas com agregação centralizada.","whyWrong":{"C":"Inspector é vulnerabilidades","D":"Shield é DDoS.","B":"AWS WAF protege aplicações web em ALB/CloudFront/API Gateway contra ataques L7 (SQLi, XSS, OWASP Top 10) — não é serviço de configuration assessment nem cobre múltiplas contas para baselines de Config. Web ACLs replicadas seriam para proteger múltiplos endpoints HTTP, não para garantir compliance arquitetural."},"keyConcept":"Padrão: detective controls multi-account → Config + Organizations.","tutorSeeds":["Pode explicar com mais detalhe: Padrão: detective controls multi-account → Config + Organizations?","Quais cenários reais aplicam Padrão: detective controls multi-account → Config + Organizations?"]}'::jsonb, 'Security & Compliance', 'Security & Compliance', 'hard', 'scenario', '["organizations","config","conformance-pack"]'::jsonb, 'ai-draft', 'active', now(), now()),
    ('clf-c02-sec-032', 'aws-clf', 'A equipe de finance pediu para juntar o billing de 12 contas AWS sob uma única invoice e aproveitar volume discounts agregados. Qual feature do AWS Organizations entrega isso?', '[{"id":"A","text":"Consolidated Billing"},{"id":"B","text":"Cost Anomaly Detection"},{"id":"C","text":"Service Quotas centralizadas"},{"id":"D","text":"Reserved Instance Marketplace"}]'::jsonb, 'A', '{"summary":"Consolidated Billing une o faturamento da Organization na payer account e permite agregação de uso para volume tiering e compartilhamento de Savings Plans/RIs.","whyCorrect":"Consolidated Billing une o faturamento da Organization na payer account e permite agregação de uso para volume tiering e compartilhamento de Savings Plans/RIs.","whyWrong":{"B":"Cost Anomaly Detection acha gastos atípicos","C":"Service Quotas é limite","D":"RI Marketplace é venda de RIs."},"keyConcept":"Padrão: multi-account billing → Organizations consolidated.","tutorSeeds":["Pode explicar com mais detalhe: Padrão: multi-account billing → Organizations consolidated?","Quais cenários reais aplicam Padrão: multi-account billing → Organizations consolidated?","Como RIs se compara com alternativas?"]}'::jsonb, 'Security & Compliance', 'Security & Compliance', 'easy', 'scenario', '["organizations","billing","consolidated"]'::jsonb, 'ai-draft', 'active', now(), now()),
    ('clf-c02-sec-033', 'aws-clf', 'Uma empresa começou com uma única conta AWS e cresceu para ter dev, staging e prod misturados. Qual benefício principal a separação em múltiplas contas via Organizations entrega?', '[{"id":"A","text":"Isolamento de blast radius e fronteiras de billing/segurança claras"},{"id":"B","text":"Redução de latência entre serviços"},{"id":"C","text":"Aumento automático de quotas em 10x"},{"id":"D","text":"Aceleração de boot de instâncias EC2"}]'::jsonb, 'A', '{"summary":"Contas são fronteiras hard de isolamento: incidente em dev não afeta prod; billing por ambiente fica claro; SCPs por OU aplicam guardrails diferentes.","whyCorrect":"Contas são fronteiras hard de isolamento: incidente em dev não afeta prod; billing por ambiente fica claro; SCPs por OU aplicam guardrails diferentes.","whyWrong":{"B":"Latência depende da região, não da conta","C":"quotas são por conta mas não 10x automático","D":"boot independe de Organization."},"keyConcept":"Padrão AWS: multi-account by design, não single account com tags.","tutorSeeds":["Pode explicar com mais detalhe: Padrão AWS: multi-account by design, não single account com tags?","Quais cenários reais aplicam Padrão AWS: multi-account by design, não single account com tags?","Como SCPs se compara com alternativas?"]}'::jsonb, 'Security & Compliance', 'Security & Compliance', 'medium', 'best-practice', '["organizations","multi-account","blast-radius"]'::jsonb, 'ai-draft', 'active', now(), now()),
    ('clf-c02-sec-034', 'aws-clf', 'A equipe quer compartilhar uma subnet de uma VPC central com várias contas-membro da Organization, sem replicar a VPC. Qual serviço AWS entrega esse compartilhamento de recursos cross-account?', '[{"id":"A","text":"AWS Resource Access Manager (RAM)"},{"id":"B","text":"AWS Direct Connect Gateway"},{"id":"C","text":"VPC Peering em estrela"},{"id":"D","text":"Amazon CloudFront com Origin Access"}]'::jsonb, 'A', '{"summary":"RAM permite compartilhar recursos suportados (subnets, Transit Gateway, License Manager configs, Route 53 Resolver rules) cross-account sem duplicar.","whyCorrect":"RAM permite compartilhar recursos suportados (subnets, Transit Gateway, License Manager configs, Route 53 Resolver rules) cross-account sem duplicar.","whyWrong":{"B":"DX Gateway interliga on-prem com várias VPCs/regiões","C":"VPC peering conecta VPCs mas não ''compartilha subnet''","D":"CloudFront é CDN."},"keyConcept":"Padrão: shared services VPC com subnets via RAM.","tutorSeeds":["Pode explicar com mais detalhe: Padrão: shared services VPC com subnets via RAM?","Quais cenários reais aplicam Padrão: shared services VPC com subnets via RAM?","Como RAM se compara com alternativas?"]}'::jsonb, 'Security & Compliance', 'Security & Compliance', 'hard', 'scenario', '["organizations","ram","multi-account","networking"]'::jsonb, 'ai-draft', 'active', now(), now()),
    ('clf-c02-sec-035', 'aws-clf', 'Uma empresa precisa baixar relatórios SOC 2 Type II, ISO 27001 e PCI DSS Attestation of Compliance da AWS para enviar ao seu auditor. Qual serviço AWS entrega esses documentos no portal de gestão?', '[{"id":"A","text":"AWS Artifact"},{"id":"B","text":"AWS Trust Center"},{"id":"C","text":"AWS Audit Manager"},{"id":"D","text":"AWS Security Hub"}]'::jsonb, 'A', '{"summary":"AWS Artifact é o portal self-service para download de relatórios de compliance da AWS (SOC, ISO, PCI, FedRAMP, HIPAA BAA, etc.).","whyCorrect":"AWS Artifact é o portal self-service para download de relatórios de compliance da AWS (SOC, ISO, PCI, FedRAMP, HIPAA BAA, etc.).","whyWrong":{"B":"Trust Center é página pública com posicionamento de segurança","C":"Audit Manager automatiza coleta de evidências do cliente (não relatórios AWS)","D":"Security Hub agrega findings."},"keyConcept":"Regra: ''preciso de relatório AWS para auditor'' → Artifact.","tutorSeeds":["Pode explicar com mais detalhe: Regra: ''preciso de relatório AWS para auditor'' → Artifact?","Quais cenários reais aplicam Regra: ''preciso de relatório AWS para auditor'' → Artifact?","Como AWS Artifact se compara com alternativas?"]}'::jsonb, 'Security & Compliance', 'Security & Compliance', 'easy', 'scenario', '["compliance","artifact","audit"]'::jsonb, 'ai-draft', 'active', now(), now()),
    ('clf-c02-sec-036', 'aws-clf', 'Uma empresa de saúde precisa armazenar PHI (protected health information) e questiona se a AWS oferece HIPAA compliance. Qual afirmação descreve corretamente a postura AWS para HIPAA?', '[{"id":"A","text":"AWS assina BAA com clientes elegíveis e oferece serviços HIPAA-eligible específicos"},{"id":"B","text":"Todas as contas AWS são automaticamente HIPAA-compliant"},{"id":"C","text":"HIPAA é cobrada como add-on no plano Enterprise"},{"id":"D","text":"AWS só atende HIPAA na região us-gov-west-1"}]'::jsonb, 'A', '{"summary":"AWS oferece BAA (Business Associate Agreement) via Artifact; lista de serviços HIPAA-eligible é publicada e o cliente deve usar apenas esses para PHI.","whyCorrect":"AWS oferece BAA (Business Associate Agreement) via Artifact; lista de serviços HIPAA-eligible é publicada e o cliente deve usar apenas esses para PHI.","whyWrong":{"B":"serviços HIPAA-eligible existem em várias regiões comerciais.","C":"não é add-on de plano","D":"AWS atende HIPAA em todas as regiões comerciais (incluindo us-east-1, sa-east-1, eu-west-1, etc.) para serviços HIPAA-eligible. us-gov-west-1 é GovCloud (US), destinada a workloads US-government com requisitos FedRAMP High/ITAR — HIPAA não é vinculado a GovCloud. A elegibilidade HIPAA segue a lista de serviços HIPAA-eligible, não a região."},"keyConcept":"Regra: HIPAA = shared responsibility — AWS fornece infraestrutura compliant + BAA, cliente configura corretamente.","tutorSeeds":["Pode explicar com mais detalhe: Regra: HIPAA = shared responsibility — AWS fornece infraestrutura compliant + BAA, cliente configura corretamente?","Quais cenários reais aplicam Regra: HIPAA = shared responsibility — AWS fornece infraestrutura compliant + BAA, cliente configura corretamente?","Como AWS se compara com alternativas?"]}'::jsonb, 'Security & Compliance', 'Security & Compliance', 'medium', 'scenario', '["compliance","hipaa","baa"]'::jsonb, 'ai-draft', 'active', now(), now()),
    ('clf-c02-sec-037', 'aws-clf', 'Uma empresa US-government precisa workloads em ambiente que atenda FedRAMP High e ITAR. Qual região AWS é projetada especificamente para essas exigências?', '[{"id":"A","text":"AWS GovCloud (US)"},{"id":"B","text":"us-east-1 com encryption ativada"},{"id":"C","text":"Qualquer região comercial com Shield Advanced"},{"id":"D","text":"AWS Outposts on-premises"}]'::jsonb, 'A', '{"summary":"GovCloud (US) é region isolada operada por US persons, projetada para FedRAMP High, DoD SRG IL2-5, ITAR e CJIS.","whyCorrect":"GovCloud (US) é region isolada operada por US persons, projetada para FedRAMP High, DoD SRG IL2-5, ITAR e CJIS.","whyWrong":{"C":"Shield não muda jurisdição","D":"Outposts estende AWS para on-prem mas não substitui GovCloud.","B":"us-east-1 é região comercial AWS — pode atender FedRAMP Moderate e SOC, mas não atende FedRAMP High nem ITAR (que exige operação por US persons em ambiente isolado). Habilitar encryption é controle do cliente e não muda a postura de compliance da região. Para FedRAMP High + ITAR, GovCloud é a única opção."},"keyConcept":"Regra: requisitos US-government estritos → GovCloud.","tutorSeeds":["Pode explicar com mais detalhe: Regra: requisitos US-government estritos → GovCloud?","Quais cenários reais aplicam Regra: requisitos US-government estritos → GovCloud?","Como US se compara com alternativas?"]}'::jsonb, 'Security & Compliance', 'Security & Compliance', 'medium', 'scenario', '["compliance","govcloud","fedramp"]'::jsonb, 'ai-draft', 'active', now(), now()),
    ('clf-c02-sec-038', 'aws-clf', 'Um cliente quer entender se a AWS é PCI DSS Level 1 Service Provider para hospedar parte do ambiente de processamento de cartões. Onde obter o Attestation of Compliance (AoC) PCI da AWS?', '[{"id":"A","text":"AWS Artifact, na seção Reports"},{"id":"B","text":"Solicitando ao Technical Account Manager por email"},{"id":"C","text":"Publicado abertamente no site da AWS sem login"},{"id":"D","text":"AWS Security Hub findings PCI"}]'::jsonb, 'A', '{"summary":"PCI AoC e Responsibility Summary são distribuídos via AWS Artifact sob NDA clicável, disponíveis a qualquer cliente AWS.","whyCorrect":"PCI AoC e Responsibility Summary são distribuídos via AWS Artifact sob NDA clicável, disponíveis a qualquer cliente AWS.","whyWrong":{"D":"Security Hub PCI standard cuida de avaliar seu próprio ambiente, não fornece o AoC da AWS.","B":"Solicitar via TAM por email não é o canal padrão e seria fricção desnecessária — o AoC PCI é documento self-service via Artifact, disponível em qualquer plano de suporte. TAM ajuda em casos especiais (relatórios customizados ou esclarecimentos), mas o AoC em si está sempre disponível para download imediato.","C":"AoC PCI e demais relatórios de compliance contêm informações sensíveis sobre controles AWS e são distribuídos sob NDA clicável — não são publicados abertamente sem autenticação. Cliente precisa estar logado em AWS Artifact e aceitar termos para baixar. Apenas resumos públicos (lista de programas) ficam abertos."},"keyConcept":"Regra: documentos de compliance AWS → Artifact.","tutorSeeds":["Pode explicar com mais detalhe: Regra: documentos de compliance AWS → Artifact?","Quais cenários reais aplicam Regra: documentos de compliance AWS → Artifact?","Como PCI se compara com alternativas?"]}'::jsonb, 'Security & Compliance', 'Security & Compliance', 'easy', 'scenario', '["compliance","pci","artifact"]'::jsonb, 'ai-draft', 'active', now(), now()),
    ('clf-c02-sec-039', 'aws-clf', 'Um cliente brasileiro precisa entender quais programas de compliance internacional a AWS atende (ex.: ISO 27001, ISO 27017, ISO 27018, SOC 1/2/3). Onde encontrar a lista oficial atualizada?', '[{"id":"A","text":"Página AWS Compliance Programs em aws.amazon.com/compliance/programs"},{"id":"B","text":"Console do IAM, na aba ''Compliance''"},{"id":"C","text":"AWS CloudTrail event history"},{"id":"D","text":"Lista hardcoded no AWS CLI"}]'::jsonb, 'A', '{"summary":"A página /compliance/programs da AWS é a fonte canônica e atualizada dos programas reconhecidos (ISO, SOC, PCI, HIPAA, FedRAMP, IRAP, K-ISMS, etc.).","whyCorrect":"A página /compliance/programs da AWS é a fonte canônica e atualizada dos programas reconhecidos (ISO, SOC, PCI, HIPAA, FedRAMP, IRAP, K-ISMS, etc.).","whyWrong":{"B":"CloudTrail registra chamadas, não compliance","D":"AWS CLI não embute essa lista.","C":"CloudTrail event history registra chamadas de API feitas na conta do cliente (quem fez o quê e quando) — não é catálogo de compliance da AWS. CloudTrail seria útil para auditar quem mudou IAM/policies na sua conta, não para descobrir se a AWS é certificada ISO 27017."},"keyConcept":"Padrão: compliance posture → site oficial AWS Compliance.","tutorSeeds":["Pode explicar com mais detalhe: Padrão: compliance posture → site oficial AWS Compliance?","Quais cenários reais aplicam Padrão: compliance posture → site oficial AWS Compliance?","Como AWS se compara com alternativas?"]}'::jsonb, 'Security & Compliance', 'Security & Compliance', 'easy', 'recall', '["compliance","iso","soc"]'::jsonb, 'ai-draft', 'active', now(), now()),
    ('clf-c02-sec-040', 'aws-clf', 'Após ler o relatório SOC 2 da AWS via Artifact, o auditor pergunta se o cliente pode reaproveitar os controles AWS sem testá-los novamente em seu próprio ambiente. Qual é o entendimento correto?', '[{"id":"A","text":"Os controles AWS cobrem ''OF the cloud''; cliente ainda precisa testar seus controles ''IN the cloud''"},{"id":"B","text":"SOC 2 da AWS automaticamente certifica o ambiente do cliente"},{"id":"C","text":"O cliente fica isento de auditoria se usar serviços managed"},{"id":"D","text":"AWS Artifact gera relatório SOC 2 customizado para o cliente"}]'::jsonb, 'A', '{"summary":"Relatórios da AWS atestam controles AWS (físico, hypervisor, processos); cliente deve auditar IAM, encryption, logging, configurações no seu lado para certificar a própria empresa.","whyCorrect":"Relatórios da AWS atestam controles AWS (físico, hypervisor, processos); cliente deve auditar IAM, encryption, logging, configurações no seu lado para certificar a própria empresa.","whyWrong":{"C":"Auditoria do cliente não é substituída managed services não isentam responsabilidade do cliente","D":"Artifact distribui relatórios padrão, não gera customizados.","B":"Relatórios SOC 2 da AWS atestam controles da AWS — não auditam nem certificam o ambiente do cliente. Para o cliente se certificar SOC 2, ele precisa contratar auditor próprio que avalia controles ''IN the cloud'' (IAM, encryption, logging configurados pelo cliente), podendo herdar controles AWS como evidência parcial."},"keyConcept":"Princípio: inheritance parcial de controles, não total.","tutorSeeds":["Pode explicar com mais detalhe: Princípio: inheritance parcial de controles, não total?","Quais cenários reais aplicam Princípio: inheritance parcial de controles, não total?","Como AWS se compara com alternativas?"]}'::jsonb, 'Security & Compliance', 'Security & Compliance', 'hard', 'best-practice', '["compliance","soc2","shared-responsibility"]'::jsonb, 'ai-draft', 'active', now(), now()),
    ('clf-c02-sec-041', 'aws-clf', 'Uma empresa armazena dados sensíveis em S3 e quer criptografia em repouso usando chaves gerenciadas pela AWS sem custo extra de KMS. Qual opção atende?', '[{"id":"A","text":"SSE-S3 (server-side encryption com chaves S3-managed)"},{"id":"B","text":"SSE-KMS com customer managed key"},{"id":"C","text":"SSE-C com chaves fornecidas pelo cliente"},{"id":"D","text":"Client-side encryption antes do upload"}]'::jsonb, 'A', '{"summary":"SSE-S3 usa chaves totalmente gerenciadas pelo S3, AES-256, sem custo adicional além do armazenamento.","whyCorrect":"SSE-S3 usa chaves totalmente gerenciadas pelo S3, AES-256, sem custo adicional além do armazenamento.","whyWrong":{"D":"client-side encryption exige libs e gestão pelo cliente.","B":"SSE-KMS com customer managed key adiciona custo de KMS: $1/mês por CMK + $0.03 por 10.000 requests de cifragem/decifragem — o que pode ser significativo em buckets de alto throughput. SSE-KMS oferece audit detalhado e controle de policy, mas o requisito explícito é ''sem custo extra de KMS''.","C":"SSE-C exige que o cliente FORNEÇA a chave em cada PUT/GET via header — é o cliente quem gerencia o material criptográfico (rotação, armazenamento, distribuição). Adiciona complexidade operacional grande e não usa ''chaves gerenciadas pela AWS'' como o requisito pede. SSE-C seria correto para ''cliente quer manter chaves fora da AWS mas usar S3''."},"keyConcept":"Regra: opção padrão sem custo extra → SSE-S3; auditoria/controle mais fino → SSE-KMS.","tutorSeeds":["Pode explicar com mais detalhe: Regra: opção padrão sem custo extra → SSE-S3; auditoria/controle mais fino → SSE-KMS?","Quais cenários reais aplicam Regra: opção padrão sem custo extra → SSE-S3; auditoria/controle mais fino → SSE-KMS?","Como SSE-S3 se compara com alternativas?"]}'::jsonb, 'Security & Compliance', 'Security & Compliance', 'easy', 'scenario', '["encryption","s3","sse-s3"]'::jsonb, 'ai-draft', 'active', now(), now()),
    ('clf-c02-sec-042', 'aws-clf', 'A equipe precisa auditar cada chamada de Encrypt/Decrypt de uma chave KMS específica usada para proteger dados financeiros. Qual combinação entrega essa visibilidade?', '[{"id":"A","text":"Customer managed CMK no KMS + CloudTrail registrando KMS data events"},{"id":"B","text":"AWS-managed key (aws/s3) + AWS Config"},{"id":"C","text":"SSE-S3 + AWS Trusted Advisor"},{"id":"D","text":"AWS Shield Advanced + GuardDuty"}]'::jsonb, 'A', '{"summary":"Customer managed CMK dá controle de policy e rotação; CloudTrail registra automaticamente todas as KMS API calls (Encrypt, Decrypt, GenerateDataKey, etc.) — auditoria completa.","whyCorrect":"Customer managed CMK dá controle de policy e rotação; CloudTrail registra automaticamente todas as KMS API calls (Encrypt, Decrypt, GenerateDataKey, etc.) — auditoria completa.","whyWrong":{"B":"AWS-managed keys têm controle limitado Config detecta config drift mas não chamadas","C":"Trusted Advisor é dicas","D":"Shield/GuardDuty cobrem outras camadas."},"keyConcept":"Padrão: auditoria fina de uso de chave → CMK + CloudTrail.","tutorSeeds":["Pode explicar com mais detalhe: Padrão: auditoria fina de uso de chave → CMK + CloudTrail?","Quais cenários reais aplicam Padrão: auditoria fina de uso de chave → CMK + CloudTrail?","Como CMK se compara com alternativas?"]}'::jsonb, 'Security & Compliance', 'Security & Compliance', 'medium', 'scenario', '["encryption","kms","cmk","audit"]'::jsonb, 'ai-draft', 'active', now(), now()),
    ('clf-c02-sec-043', 'aws-clf', 'Uma equipe precisa de FIPS 140-2 Level 3 com HSM single-tenant dedicado, sob controle exclusivo do cliente para geração de chaves de TLS. Qual serviço AWS atende?', '[{"id":"A","text":"AWS CloudHSM"},{"id":"B","text":"AWS KMS com AWS managed key"},{"id":"C","text":"AWS Secrets Manager"},{"id":"D","text":"AWS Certificate Manager Private CA"}]'::jsonb, 'A', '{"summary":"CloudHSM é HSM dedicado FIPS 140-2 Level 3 onde o cliente controla 100% das chaves (AWS não tem acesso).","whyCorrect":"CloudHSM é HSM dedicado FIPS 140-2 Level 3 onde o cliente controla 100% das chaves (AWS não tem acesso).","whyWrong":{"C":"Secrets Manager guarda segredos, não é HSM","D":"ACM Private CA emite certificados, não substitui HSM.","B":"AWS managed key no KMS (aws/serviço) é multi-tenant — a chave é compartilhada logicamente com outros clientes da AWS e a key policy é controlada pela AWS, não pelo cliente. Não atende o requisito de HSM single-tenant sob controle exclusivo. KMS standard é FIPS 140-2 Level 3 em alguns endpoints, mas não é dedicated HSM."},"keyConcept":"Regra: HSM dedicado single-tenant → CloudHSM; gestão de chaves padrão → KMS.","tutorSeeds":["Pode explicar com mais detalhe: Regra: HSM dedicado single-tenant → CloudHSM; gestão de chaves padrão → KMS?","Quais cenários reais aplicam Regra: HSM dedicado single-tenant → CloudHSM; gestão de chaves padrão → KMS?","Como HSM se compara com alternativas?"]}'::jsonb, 'Security & Compliance', 'Security & Compliance', 'hard', 'scenario', '["encryption","cloudhsm","fips"]'::jsonb, 'ai-draft', 'active', now(), now()),
    ('clf-c02-sec-044', 'aws-clf', 'Um arquiteto quer ativar encryption at rest em todos os volumes EBS criados na conta, sem depender da equipe lembrar de marcar a opção. Qual configuração resolve?', '[{"id":"A","text":"Ativar EBS encryption by default na região via console/CLI"},{"id":"B","text":"Configurar uma SCP que negue ec2:CreateVolume"},{"id":"C","text":"Adicionar uma tag ''Encrypted=true'' em cada volume"},{"id":"D","text":"Habilitar AWS Shield Advanced na conta"}]'::jsonb, 'A', '{"summary":"EBS encryption by default é setting por região: a partir daí, todo novo volume e snapshot são criptografados com a chave default ou customer-managed.","whyCorrect":"EBS encryption by default é setting por região: a partir daí, todo novo volume e snapshot são criptografados com a chave default ou customer-managed.","whyWrong":{"B":"SCP negando CreateVolume impede criação, não força encryption","D":"Shield é DDoS.","C":"Tag em volume é apenas metadata — não cifra dados nem altera o flag ''Encrypted'' do volume. Mesmo com a tag ''Encrypted=true'', se a opção de criptografia não foi marcada na criação, o volume permanecerá em plaintext. Para garantir encryption sem confiar em processo manual, é necessário EBS encryption by default no nível da região."},"keyConcept":"Padrão: ''encryption by default'' como guardrail.","tutorSeeds":["Pode explicar com mais detalhe: Padrão: ''encryption by default'' como guardrail?","Quais cenários reais aplicam Padrão: ''encryption by default'' como guardrail?","Como EBS se compara com alternativas?"]}'::jsonb, 'Security & Compliance', 'Security & Compliance', 'medium', 'best-practice', '["encryption","ebs","by-default"]'::jsonb, 'ai-draft', 'active', now(), now()),
    ('clf-c02-sec-045', 'aws-clf', 'Uma empresa precisa decidir entre SSE-KMS e SSE-S3 para um bucket. O requisito é poder revogar acesso em massa a todos os objetos cifrados desativando uma única chave. Qual opção atende?', '[{"id":"A","text":"SSE-KMS com customer managed CMK"},{"id":"B","text":"SSE-S3 (S3-managed key)"},{"id":"C","text":"SSE-C (chave do cliente em cada request)"},{"id":"D","text":"Plaintext com bucket policy restritiva"}]'::jsonb, 'A', '{"summary":"CMK no KMS pode ser disabled/scheduled for deletion — desativá-la torna todos os objetos efetivamente ilegíveis até reativação.","whyCorrect":"CMK no KMS pode ser disabled/scheduled for deletion — desativá-la torna todos os objetos efetivamente ilegíveis até reativação.","whyWrong":{"C":"SSE-S3 não dá controle de chave ao cliente SSE-C exige enviar chave em cada request (não dá kill switch central)","D":"plaintext não cifra.","B":"SSE-S3 usa chaves totalmente gerenciadas pelo S3 — o cliente não tem visibilidade da chave nem pode desativá-la. Não há ''kill switch'' criptográfico em SSE-S3. Para revogar acesso em massa, seria necessário uma CMK que o cliente possa disable; isso requer SSE-KMS com customer managed key."},"keyConcept":"Padrão: ''kill switch'' criptográfico = CMK no KMS.","tutorSeeds":["Pode explicar com mais detalhe: Padrão: ''kill switch'' criptográfico = CMK no KMS?","Quais cenários reais aplicam Padrão: ''kill switch'' criptográfico = CMK no KMS?","Como CMK se compara com alternativas?"]}'::jsonb, 'Security & Compliance', 'Security & Compliance', 'hard', 'scenario', '["encryption","kms","cmk","revocation"]'::jsonb, 'ai-draft', 'active', now(), now()),
    ('clf-c02-sec-046', 'aws-clf', 'Em transit, o time precisa garantir que conexões a um Application Load Balancer só aceitem TLS 1.2 ou superior. Onde aplicar essa restrição?', '[{"id":"A","text":"Em uma security policy do listener HTTPS do ALB"},{"id":"B","text":"Numa SCP da Organization"},{"id":"C","text":"No IAM policy do usuário criador do ALB"},{"id":"D","text":"No security group anexado ao ALB"}]'::jsonb, 'A', '{"summary":"ELB Security Policies definem versões de TLS e cipher suites aceitas no listener HTTPS; escolher ELBSecurityPolicy-TLS13-* ou TLS-1-2-* restringe versões.","whyCorrect":"ELB Security Policies definem versões de TLS e cipher suites aceitas no listener HTTPS; escolher ELBSecurityPolicy-TLS13-* ou TLS-1-2-* restringe versões.","whyWrong":{"B":"SCPs aplicam restrições a chamadas de API (control plane) — não filtram protocolos de tráfego de rede de aplicação. Uma SCP poderia, no máximo, restringir QUEM cria o listener com qual SSL policy via Condition, mas não inspeciona pacotes TLS. Restrição de versão TLS é configuração do listener, não do plano IAM.","C":"IAM policy do criador do ALB controla quem PODE criar/modificar o LB — não define qual versão de TLS o ALB aceitará no listener. Quem cria o ALB poderia escolher qualquer ELB Security Policy. A restrição TLS 1.2+ é configurada explicitamente no listener (ssl_policy), não inferida do criador.","D":"Security Group filtra IP/portas/CIDRs em camada 4 (TCP/UDP) — não tem visibilidade da versão de TLS dentro do payload TCP. SG decide se conexão na porta 443 é permitida; o que acontece dentro do TLS handshake é responsabilidade do listener do ALB."},"keyConcept":"Padrão: TLS hardening → security policy do listener.","tutorSeeds":["Pode explicar com mais detalhe: Padrão: TLS hardening → security policy do listener?","Quais cenários reais aplicam Padrão: TLS hardening → security policy do listener?","Como ELB se compara com alternativas?"]}'::jsonb, 'Security & Compliance', 'Security & Compliance', 'medium', 'scenario', '["encryption","tls","alb"]'::jsonb, 'ai-draft', 'active', now(), now()),
    ('clf-c02-sec-047', 'aws-clf', 'Uma equipe quer rotacionar automaticamente as chaves KMS customer-managed anualmente sem alterar aplicações. Qual opção do KMS atende?', '[{"id":"A","text":"Habilitar Automatic Key Rotation na CMK simétrica"},{"id":"B","text":"Deletar e recriar a CMK manualmente a cada ano"},{"id":"C","text":"Rotacionar via AWS Secrets Manager"},{"id":"D","text":"AWS rotaciona automaticamente sem precisar habilitar"}]'::jsonb, 'A', '{"summary":"CMKs simétricas suportam automatic key rotation anual: o KMS gera novo material criptográfico mantendo o mesmo Key ID e ARN; aplicações continuam funcionando, dados antigos continuam decifráveis.","whyCorrect":"CMKs simétricas suportam automatic key rotation anual: o KMS gera novo material criptográfico mantendo o mesmo Key ID e ARN; aplicações continuam funcionando, dados antigos continuam decifráveis.","whyWrong":{"B":"Recriar manualmente quebra apps que referenciam o ARN antigo [extra: rotação não é default]","C":"Secrets Manager rotaciona segredos, não CMKs","D":"exige habilitar."},"keyConcept":"Regra: CMK simétrica + rotation = um clique.","tutorSeeds":["Pode explicar com mais detalhe: Regra: CMK simétrica + rotation = um clique?","Quais cenários reais aplicam Regra: CMK simétrica + rotation = um clique?","Como CMKs se compara com alternativas?"]}'::jsonb, 'Security & Compliance', 'Security & Compliance', 'medium', 'best-practice', '["encryption","kms","rotation"]'::jsonb, 'ai-draft', 'active', now(), now()),
    ('clf-c02-sec-048', 'aws-clf', 'Uma startup quer cifrar dados em uma tabela DynamoDB usando chave que só ela controla, para conformidade contratual com cliente enterprise. Qual configuração atende?', '[{"id":"A","text":"DynamoDB encryption com customer managed KMS key"},{"id":"B","text":"Desabilitar a encryption nativa e cifrar via Lambda trigger"},{"id":"C","text":"Usar SSE-C com chave em cada PutItem"},{"id":"D","text":"Habilitar Macie no bucket de origem"}]'::jsonb, 'A', '{"summary":"DynamoDB suporta 3 níveis: AWS owned (default), AWS managed (aws/dynamodb), customer managed CMK — este último dá controle total de policy, rotação e revogação.","whyCorrect":"DynamoDB suporta 3 níveis: AWS owned (default), AWS managed (aws/dynamodb), customer managed CMK — este último dá controle total de policy, rotação e revogação.","whyWrong":{"B":"Não é possível desabilitar encryption em DynamoDB (sempre ligada)","D":"Macie é descoberta em S3.","C":"SSE-C (server-side encryption com customer-provided key) não é suportado pelo DynamoDB — é uma opção exclusiva do S3. DynamoDB suporta apenas as três opções de KMS (AWS owned, AWS managed, customer managed). Para chave sob controle exclusivo do cliente, a resposta é customer managed CMK no KMS."},"keyConcept":"Regra: chave sob controle do cliente → customer managed CMK.","tutorSeeds":["Pode explicar com mais detalhe: Regra: chave sob controle do cliente → customer managed CMK?","Quais cenários reais aplicam Regra: chave sob controle do cliente → customer managed CMK?","Como AWS se compara com alternativas?"]}'::jsonb, 'Security & Compliance', 'Security & Compliance', 'medium', 'scenario', '["encryption","dynamodb","cmk"]'::jsonb, 'ai-draft', 'active', now(), now()),
    ('clf-c02-sec-049', 'aws-clf', 'Um app uploadou arquivos para S3 mas o cliente exige que a AWS jamais tenha acesso ao material criptográfico das chaves. Qual abordagem atende esse requisito?', '[{"id":"A","text":"Client-side encryption antes do upload, com chaves gerenciadas fora da AWS"},{"id":"B","text":"SSE-S3 com AES-256"},{"id":"C","text":"SSE-KMS com aws/s3 key"},{"id":"D","text":"Ativar Block Public Access no bucket"}]'::jsonb, 'A', '{"summary":"Client-side encryption (ex.: AWS Encryption SDK com chave em CloudHSM ou KMS External Key Store) cifra antes do upload; o S3 recebe apenas ciphertext.","whyCorrect":"Client-side encryption (ex.: AWS Encryption SDK com chave em CloudHSM ou KMS External Key Store) cifra antes do upload; o S3 recebe apenas ciphertext.","whyWrong":{"D":"Block Public Access controla exposição, não confidencialidade frente à AWS.","B":"SSE-S3 usa AES-256 com chaves gerenciadas pela AWS — a AWS tem acesso ao material criptográfico (é quem rotaciona). Não atende o requisito ''AWS jamais ter acesso ao material das chaves''. SSE-S3 é o oposto: zero gestão de chave pelo cliente.","C":"SSE-KMS com a chave aws/s3 (AWS managed key) é multi-tenant e o material criptográfico fica sob controle da AWS — não atende ''AWS jamais ter acesso''. Mesmo SSE-KMS com customer managed key tem a chave dentro do KMS AWS (a menos que use External Key Store). Client-side encryption é a única forma de garantir que apenas ciphertext chegue à AWS."},"keyConcept":"Padrão: ''AWS never sees plaintext keys'' → client-side ou KMS XKS.","tutorSeeds":["Pode explicar com mais detalhe: Padrão: ''AWS never sees plaintext keys'' → client-side ou KMS XKS?","Quais cenários reais aplicam Padrão: ''AWS never sees plaintext keys'' → client-side ou KMS XKS?","Como AWS Encryption se compara com alternativas?"]}'::jsonb, 'Security & Compliance', 'Security & Compliance', 'hard', 'scenario', '["encryption","client-side","kms-xks"]'::jsonb, 'ai-draft', 'active', now(), now()),
    ('clf-c02-sec-050', 'aws-clf', 'Em transit entre serviços AWS na mesma região, parte do tráfego (ex.: dentro de Nitro System) já é cifrado por padrão. Qual a melhor postura para um arquiteto seguir?', '[{"id":"A","text":"Confiar na encryption AWS-side mas habilitar TLS em todas as conexões app-level também"},{"id":"B","text":"Desligar TLS para reduzir overhead de CPU"},{"id":"C","text":"Usar somente IPv6 que é cifrado por design"},{"id":"D","text":"Confiar no SG do EC2 como única camada"}]'::jsonb, 'A', '{"summary":"Defense in depth: AWS cifra parte do tráfego intra-region, mas o cliente é responsável por encryption in transit no nível de aplicação (TLS, mTLS) para garantir confidencialidade ponta-a-ponta independente da camada AWS.","whyCorrect":"Defense in depth: AWS cifra parte do tráfego intra-region, mas o cliente é responsável por encryption in transit no nível de aplicação (TLS, mTLS) para garantir confidencialidade ponta-a-ponta independente da camada AWS.","whyWrong":{"B":"Desligar TLS reduz overhead mas viola compliance","C":"IPv6 não é cifrado por design","D":"Security Group filtra acesso de rede (IP/porta) — não fornece confidencialidade do payload. SG impede conexões não autorizadas mas não cifra dados em trânsito; um atacante na mesma subnet com SG permissivo veria tráfego plaintext. SG é uma camada de defesa, mas não substitui TLS para encryption in transit."},"keyConcept":"Padrão: in transit encryption em todos os hops controláveis.","tutorSeeds":["Pode explicar com mais detalhe: Padrão: in transit encryption em todos os hops controláveis?","Quais cenários reais aplicam Padrão: in transit encryption em todos os hops controláveis?","Como AWS se compara com alternativas?"]}'::jsonb, 'Security & Compliance', 'Security & Compliance', 'medium', 'best-practice', '["encryption","in-transit","tls","defense-in-depth"]'::jsonb, 'ai-draft', 'active', now(), now()),
    ('clf-c02-sec-051', 'aws-clf', 'Uma equipe precisa armazenar credenciais de banco de dados que serão rotacionadas automaticamente a cada 30 dias, com integração nativa ao RDS. Qual serviço atende melhor?', '[{"id":"A","text":"AWS Secrets Manager"},{"id":"B","text":"AWS Systems Manager Parameter Store (Standard, SecureString)"},{"id":"C","text":"Variáveis de ambiente do EC2"},{"id":"D","text":"Bucket S3 privado com SSE-KMS"}]'::jsonb, 'A', '{"summary":"Secrets Manager faz rotação automática nativa para RDS, Redshift, DocumentDB (Lambda built-in) e suporta rotação custom; entrega via API IAM-protegida.","whyCorrect":"Secrets Manager faz rotação automática nativa para RDS, Redshift, DocumentDB (Lambda built-in) e suporta rotação custom; entrega via API IAM-protegida.","whyWrong":{"B":"Parameter Store SecureString armazena segredos mas não rotaciona automaticamente sem build custom","C":"Variáveis de ambiente em EC2 ficam em plaintext acessíveis a qualquer processo da instância (incluindo logs e core dumps); não rotacionam automaticamente; não auditam acessos; e qualquer comprometimento do host expõe credenciais. É anti-padrão para qualquer secret sensível, especialmente credenciais de banco.","D":"Bucket S3 com SSE-KMS dá at-rest encryption e IAM-based access, mas não tem rotação automática nativa integrada ao RDS — exigiria pipeline custom (Lambda + EventBridge) para girar senha no RDS e atualizar o objeto. Reinventaria o que Secrets Manager já oferece pronto. S3 seria correto para artefatos grandes, não para secrets pequenos com rotação."},"keyConcept":"Regra: rotação automática + integração managed → Secrets Manager; segredos simples sem rotação → Parameter Store.","tutorSeeds":["Pode explicar com mais detalhe: Regra: rotação automática + integração managed → Secrets Manager; segredos simples sem rotação → Parameter Store?","Quais cenários reais aplicam Regra: rotação automática + integração managed → Secrets Manager; segredos simples sem rotação → Parameter Store?","Como RDS se compara com alternativas?"]}'::jsonb, 'Security & Compliance', 'Security & Compliance', 'medium', 'scenario', '["secrets","secrets-manager","rotation"]'::jsonb, 'ai-draft', 'active', now(), now()),
    ('clf-c02-sec-052', 'aws-clf', 'Uma startup quer guardar API keys de terceiros gratuitamente, sem necessidade de rotação automática nem high-throughput. Qual opção é mais econômica?', '[{"id":"A","text":"AWS Systems Manager Parameter Store SecureString (Standard tier)"},{"id":"B","text":"AWS Secrets Manager"},{"id":"C","text":"AWS CloudHSM dedicado"},{"id":"D","text":"DynamoDB com SSE-KMS"}]'::jsonb, 'A', '{"summary":"Parameter Store Standard SecureString é gratuito (até quota), cifrado via KMS, simples de usar para segredos estáticos.","whyCorrect":"Parameter Store Standard SecureString é gratuito (até quota), cifrado via KMS, simples de usar para segredos estáticos.","whyWrong":{"B":"Secrets Manager cobra por segredo/mês + chamadas [extra: desnecessário sem rotação]","C":"CloudHSM é caro e overkill","D":"DynamoDB exige montar acesso e cifrar manualmente."},"keyConcept":"Regra: ''segredo simples sem rotação'' → Parameter Store Standard.","tutorSeeds":["Pode explicar com mais detalhe: Regra: ''segredo simples sem rotação'' → Parameter Store Standard?","Quais cenários reais aplicam Regra: ''segredo simples sem rotação'' → Parameter Store Standard?","Como KMS se compara com alternativas?"]}'::jsonb, 'Security & Compliance', 'Security & Compliance', 'easy', 'best-practice', '["secrets","parameter-store","cost"]'::jsonb, 'ai-draft', 'active', now(), now()),
    ('clf-c02-sec-053', 'aws-clf', 'Uma aplicação em Lambda precisa ler uma senha do banco de dados a cada cold start. A equipe está preocupada com custo de chamadas ao Secrets Manager. Qual abordagem reduz custo mantendo segurança?', '[{"id":"A","text":"Usar AWS Parameters and Secrets Lambda Extension (cache local) ou cache em memória entre invocações"},{"id":"B","text":"Hardcoded em variável de ambiente sem encryption"},{"id":"C","text":"Embedded na imagem da Lambda em texto plano"},{"id":"D","text":"Lido do IAM user access key armazenado no S3"}]'::jsonb, 'A', '{"summary":"A Lambda extension da AWS cacheia segredos localmente; warm starts reaproveitam o cache, reduzindo chamadas ao Secrets Manager.","whyCorrect":"A Lambda extension da AWS cacheia segredos localmente; warm starts reaproveitam o cache, reduzindo chamadas ao Secrets Manager. Em memória do container Lambda também funciona entre invocações warm.","whyWrong":{"B":"env vars sem encryption violam best practice","C":"embedded em imagem não rotaciona","D":"access key no S3 é múltiplo anti-pattern."},"keyConcept":"Padrão: cache + rotação na origem.","tutorSeeds":["Pode explicar com mais detalhe: Padrão: cache + rotação na origem?","Quais cenários reais aplicam Padrão: cache + rotação na origem?","Como AWS se compara com alternativas?"]}'::jsonb, 'Security & Compliance', 'Security & Compliance', 'hard', 'best-practice', '["secrets","secrets-manager","lambda","cost-optimization"]'::jsonb, 'ai-draft', 'active', now(), now()),
    ('clf-c02-sec-054', 'aws-clf', 'Após audit, descobriu-se uma senha hardcoded em código no GitHub público. Qual sequência de resposta é a mais correta?', '[{"id":"A","text":"Rotacionar credenciais imediatamente, remover do histórico Git e migrar para Secrets Manager"},{"id":"B","text":"Tornar o repositório privado e ignorar o leak"},{"id":"C","text":"Aguardar rotação automática semestral"},{"id":"D","text":"Adicionar a credencial a um .gitignore"}]'::jsonb, 'A', '{"summary":"Credencial exposta deve ser tratada como comprometida — rotacionar imediatamente, varrer logs CloudTrail por uso indevido, remover do histórico (git filter-repo) e migrar para um secret store.","whyCorrect":"Credencial exposta deve ser tratada como comprometida — rotacionar imediatamente, varrer logs CloudTrail por uso indevido, remover do histórico (git filter-repo) e migrar para um secret store.","whyWrong":{"B":"Tornar privado não remove o histórico já público","C":"aguardar é negligência","D":"gitignore não retira o commit do histórico."},"keyConcept":"Padrão de incident response: contain, eradicate, recover.","tutorSeeds":["Pode explicar com mais detalhe: Padrão de incident response: contain, eradicate, recover?","Quais cenários reais aplicam Padrão de incident response: contain, eradicate, recover?"]}'::jsonb, 'Security & Compliance', 'Security & Compliance', 'medium', 'troubleshoot', '["secrets","incident-response","rotation"]'::jsonb, 'ai-draft', 'active', now(), now()),
    ('clf-c02-sec-055', 'aws-clf', 'Uma equipe quer cross-account access a um segredo do Secrets Manager (segredo na conta A, app na conta B). Qual configuração atende sem replicar o segredo?', '[{"id":"A","text":"Resource policy no secret + KMS key policy permitindo a role da conta B"},{"id":"B","text":"Tornar o secret público"},{"id":"C","text":"Replicar o secret manualmente via script diário"},{"id":"D","text":"Compartilhar IAM user credentials da conta A com a conta B"}]'::jsonb, 'A', '{"summary":"Cross-account a um secret exige resource policy no próprio secret permitindo o principal da outra conta E a KMS key policy permitir Decrypt para esse principal (KMS é parte essencial).","whyCorrect":"Cross-account a um secret exige resource policy no próprio secret permitindo o principal da outra conta E a KMS key policy permitir Decrypt para esse principal (KMS é parte essencial).","whyWrong":{"B":"Secret público é catastrofe","C":"Replicar secret via script diário introduz janela de inconsistência (até 24h de drift entre contas), duplica superfície de ataque (secret em duas contas), exige IAM cross-account no script e ainda paga 2x storage. É anti-padrão quando Secrets Manager suporta cross-account nativamente via resource policy.","D":"Compartilhar IAM user credentials é o pior anti-padrão de cross-account: credenciais long-lived em outra conta, sem audit de quem usou, sem rotação fácil. O modelo idiomático AWS para cross-account é sempre role assumida via STS ou, no caso de secrets, resource policy + KMS key policy."},"keyConcept":"Padrão: resource policy + KMS key policy juntas.","tutorSeeds":["Pode explicar com mais detalhe: Padrão: resource policy + KMS key policy juntas?","Quais cenários reais aplicam Padrão: resource policy + KMS key policy juntas?","Como KMS se compara com alternativas?"]}'::jsonb, 'Security & Compliance', 'Security & Compliance', 'hard', 'scenario', '["secrets","cross-account","kms"]'::jsonb, 'ai-draft', 'active', now(), now()),
    ('clf-c02-sec-056', 'aws-clf', 'Uma equipe configurou um Security Group permitindo TCP 22 de qualquer IP (0.0.0.0/0) para administração SSH. Qual problema isso representa e qual ajuste é recomendado?', '[{"id":"A","text":"Exposição global do SSH; restringir a IPs corporativos ou usar AWS Systems Manager Session Manager"},{"id":"B","text":"Nenhum, pois SG é stateful e bloqueia ataques"},{"id":"C","text":"Resolve com Block Public Access do S3"},{"id":"D","text":"É padrão recomendado pela AWS"}]'::jsonb, 'A', '{"summary":"Expor SSH ao mundo aumenta drasticamente brute force e exploração; melhor restringir CIDR ou eliminar o SG SSH usando Session Manager (acesso sem porta aberta, audit no CloudTrail).","whyCorrect":"Expor SSH ao mundo aumenta drasticamente brute force e exploração; melhor restringir CIDR ou eliminar o SG SSH usando Session Manager (acesso sem porta aberta, audit no CloudTrail).","whyWrong":{"B":"SG stateful trata fluxo de retorno, não bloqueia ataques na porta aberta","C":"Block Public Access é S3","D":"AWS não recomenda SSH aberto ao mundo em nenhuma documentação oficial — pelo contrário, todos os Well-Architected Security pillars e Trusted Advisor sinalizam 0.0.0.0/0 em porta 22 como risco. AWS recomenda Session Manager (sem porta SSH aberta) ou, no mínimo, restrição a IPs corporativos."},"keyConcept":"Padrão: zero open SSH; Session Manager > Bastion > IP allowlist.","tutorSeeds":["Pode explicar com mais detalhe: Padrão: zero open SSH; Session Manager > Bastion > IP allowlist?","Quais cenários reais aplicam Padrão: zero open SSH; Session Manager > Bastion > IP allowlist?","Como SSH se compara com alternativas?"]}'::jsonb, 'Security & Compliance', 'Security & Compliance', 'easy', 'best-practice', '["network","security-group","ssh","session-manager"]'::jsonb, 'ai-draft', 'active', now(), now()),
    ('clf-c02-sec-057', 'aws-clf', 'Qual é a diferença operacional principal entre Security Group e Network ACL em uma VPC AWS?', '[{"id":"A","text":"SG é stateful (associado a ENI); NACL é stateless (subnet-level, regras de allow e deny ordenadas)"},{"id":"B","text":"SG é subnet-level; NACL é ENI-level"},{"id":"C","text":"SG só permite TCP; NACL permite todos protocolos"},{"id":"D","text":"SG é gratuito; NACL é pago"}]'::jsonb, 'A', '{"summary":"SG: stateful (respostas automáticas), anexado a ENI/instância, apenas allows.","whyCorrect":"SG: stateful (respostas automáticas), anexado a ENI/instância, apenas allows. NACL: stateless (precisa regras de ida e volta), aplicada na subnet, allows e denies por número.","whyWrong":{"C":"ambos suportam protocolos","B":"É o oposto: SG é anexado a ENI/instância (instance-level), enquanto NACL é aplicada na subnet (subnet-level). A confusão é comum porque ambos atuam em rede, mas o escopo é distinto: SG protege workload específico; NACL protege todos os recursos da subnet uniformemente.","D":"Tanto Security Groups quanto Network ACLs são features gratuitas da VPC — não há cobrança por criar, anexar ou processar regras. O que tem custo é o uso de NAT Gateway, VPC Endpoints, Traffic Mirroring etc., mas não SG/NACL em si."},"keyConcept":"Regra: SG = primeira linha (instance-level), NACL = filtro coarse-grained (subnet-level).","tutorSeeds":["Pode explicar com mais detalhe: Regra: SG = primeira linha (instance-level), NACL = filtro coarse-grained (subnet-level)?","Quais cenários reais aplicam Regra: SG = primeira linha (instance-level), NACL = filtro coarse-grained (subnet-level)?","Como SG se compara com alternativas?"]}'::jsonb, 'Security & Compliance', 'Security & Compliance', 'medium', 'recall', '["network","security-group","nacl","vpc"]'::jsonb, 'ai-draft', 'active', now(), now()),
    ('clf-c02-sec-058', 'aws-clf', 'Uma equipe quer proteger uma aplicação web em ALB contra SQL injection, XSS e bots maliciosos com regras gerenciadas pela AWS. Qual serviço atende?', '[{"id":"A","text":"AWS WAF com AWS Managed Rules"},{"id":"B","text":"AWS Shield Standard apenas"},{"id":"C","text":"Amazon Inspector"},{"id":"D","text":"VPC Flow Logs"}]'::jsonb, 'A', '{"summary":"WAF inspeciona HTTP(S) em ALB/CloudFront/API GW/AppSync; AWS Managed Rules cobrem OWASP Top 10, bots conhecidos, IP reputation.","whyCorrect":"WAF inspeciona HTTP(S) em ALB/CloudFront/API GW/AppSync; AWS Managed Rules cobrem OWASP Top 10, bots conhecidos, IP reputation.","whyWrong":{"B":"Shield Standard cobre DDoS L3/L4, não SQLi/XSS","C":"Inspector é vulnerability scan","D":"Flow Logs apenas registra tráfego, não filtra."},"keyConcept":"Padrão: SQLi/XSS/bots → WAF; DDoS → Shield; reachability/CVE → Inspector.","tutorSeeds":["Pode explicar com mais detalhe: Padrão: SQLi/XSS/bots → WAF; DDoS → Shield; reachability/CVE → Inspector?","Quais cenários reais aplicam Padrão: SQLi/XSS/bots → WAF; DDoS → Shield; reachability/CVE → Inspector?","Como WAF se compara com alternativas?"]}'::jsonb, 'Security & Compliance', 'Security & Compliance', 'easy', 'scenario', '["network","waf","managed-rules"]'::jsonb, 'ai-draft', 'active', now(), now()),
    ('clf-c02-sec-059', 'aws-clf', 'Uma startup sofre ataque DDoS volumétrico de 200 Gbps direcionado à sua aplicação no CloudFront. Qual nível de proteção a AWS oferece automaticamente e qual upgrade pode acelerar resposta?', '[{"id":"A","text":"Shield Standard é automático e gratuito; Shield Advanced adiciona SLA, 24x7 DRT e proteções avançadas"},{"id":"B","text":"GuardDuty bloqueia DDoS automaticamente"},{"id":"C","text":"WAF Bot Control é a única defesa contra DDoS"},{"id":"D","text":"Trusted Advisor envia patch contra DDoS"}]'::jsonb, 'A', '{"summary":"Shield Standard cobre DDoS L3/L4 grátis e automaticamente para todos os clientes AWS; Shield Advanced (pago) adiciona proteções L7, custo absorvido por DDoS scaling, Shield Response Team e dashboards.","whyCorrect":"Shield Standard cobre DDoS L3/L4 grátis e automaticamente para todos os clientes AWS; Shield Advanced (pago) adiciona proteções L7, custo absorvido por DDoS scaling, Shield Response Team e dashboards.","whyWrong":{"B":"GuardDuty detecta, não mitiga DDoS volumétrico","C":"WAF Bot Control é específico para bots, não DDoS volumétrico","D":"Trusted Advisor é dicas de configuração."},"keyConcept":"Padrão: DDoS volumétrico → Shield Standard/Advanced.","tutorSeeds":["Pode explicar com mais detalhe: Padrão: DDoS volumétrico → Shield Standard/Advanced?","Quais cenários reais aplicam Padrão: DDoS volumétrico → Shield Standard/Advanced?","Como DDoS se compara com alternativas?"]}'::jsonb, 'Security & Compliance', 'Security & Compliance', 'medium', 'scenario', '["network","shield","ddos"]'::jsonb, 'ai-draft', 'active', now(), now()),
    ('clf-c02-sec-060', 'aws-clf', 'Uma empresa quer que instâncias EC2 em subnet privada acessem o S3 sem passar pela internet nem por NAT Gateway. Qual recurso atende?', '[{"id":"A","text":"VPC Gateway Endpoint para S3"},{"id":"B","text":"Internet Gateway dedicada"},{"id":"C","text":"VPN Site-to-Site"},{"id":"D","text":"Elastic IP no S3"}]'::jsonb, 'A', '{"summary":"VPC Endpoints para S3 (Gateway type) e DynamoDB permitem acesso privado via PrivateLink-like, sem internet, sem custo de Gateway Endpoint e sem NAT — só uma rota na route table.","whyCorrect":"VPC Endpoints para S3 (Gateway type) e DynamoDB permitem acesso privado via PrivateLink-like, sem internet, sem custo de Gateway Endpoint e sem NAT — só uma rota na route table.","whyWrong":{"B":"IGW seria o oposto de ''sem internet''","C":"VPN Site-to-Site conecta on-premises a VPC — não é o caminho para uma instância EC2 alcançar S3. Mesmo se configurada, ainda passaria por internet ou exigiria DX. O padrão AWS-native para acesso privado a S3 desde uma VPC é VPC Gateway Endpoint, sem custo, com simples entrada na route table.","D":"Elastic IP é endereço IPv4 público alocado a uma ENI (EC2, NAT GW, ENI específica) — não pode ser anexado a S3, que é um serviço regional sem ENI. Conceitualmente incoerente: S3 não tem ''IP'' a alocar. Para acesso privado, o construto é Endpoint, não EIP."},"keyConcept":"Padrão: S3/DynamoDB privados → Gateway Endpoint; outros serviços → Interface Endpoint (PrivateLink).","tutorSeeds":["Pode explicar com mais detalhe: Padrão: S3/DynamoDB privados → Gateway Endpoint; outros serviços → Interface Endpoint (PrivateLink)?","Quais cenários reais aplicam Padrão: S3/DynamoDB privados → Gateway Endpoint; outros serviços → Interface Endpoint (PrivateLink)?","Como VPC se compara com alternativas?"]}'::jsonb, 'Security & Compliance', 'Security & Compliance', 'medium', 'scenario', '["network","vpc-endpoint","privatelink","s3"]'::jsonb, 'ai-draft', 'active', now(), now()),
    ('clf-c02-sec-061', 'aws-clf', 'Uma equipe configurou NACL com regra 100 allow TCP 443 e regra 200 deny TCP 443. O que acontece com tráfego HTTPS chegando?', '[{"id":"A","text":"É permitido — NACL avalia regras por ordem de número, menor primeiro"},{"id":"B","text":"É negado — deny sempre prevalece"},{"id":"C","text":"É enfileirado para revisão manual"},{"id":"D","text":"Vai para o SG decidir"}]'::jsonb, 'A', '{"summary":"NACL processa regras em ordem numérica crescente e a primeira que dá match é aplicada — regra 100 (allow) vence regra 200 (deny).","whyCorrect":"NACL processa regras em ordem numérica crescente e a primeira que dá match é aplicada — regra 100 (allow) vence regra 200 (deny).","whyWrong":{"B":"Ao contrário de SG/IAM, NACL não tem ''deny implícito'' nem ''deny sempre prevalece''","C":"NACL é stateless e processa regras automaticamente em ordem numérica — não há mecanismo de ''enfileirar para revisão manual''. Avaliação é em microssegundos, sem human-in-the-loop. Esta opção é tecnicamente incoerente com o funcionamento de NACL.","D":"SG é avaliado independentemente da NACL — ambos precisam permitir o tráfego para que ele passe. A NACL decide com base nas próprias regras (allow 100 ganha), e só depois o SG é consultado. Não há delegação de decisão da NACL para o SG; cada camada decide separadamente."},"keyConcept":"Regra: NACL avaliação = primeira match por número crescente; default deny no final.","tutorSeeds":["Pode explicar com mais detalhe: Regra: NACL avaliação = primeira match por número crescente; default deny no final?","Quais cenários reais aplicam Regra: NACL avaliação = primeira match por número crescente; default deny no final?","Como NACL se compara com alternativas?"]}'::jsonb, 'Security & Compliance', 'Security & Compliance', 'hard', 'troubleshoot', '["network","nacl","rule-evaluation"]'::jsonb, 'ai-draft', 'active', now(), now()),
    ('clf-c02-sec-062', 'aws-clf', 'Uma equipe precisa centralizar inspeção de tráfego entre VPCs e on-prem com firewall stateful gerenciado, IPS/IDS managed e regras Suricata. Qual serviço AWS atende?', '[{"id":"A","text":"AWS Network Firewall"},{"id":"B","text":"AWS Shield Advanced"},{"id":"C","text":"Amazon GuardDuty"},{"id":"D","text":"AWS Direct Connect Gateway"}]'::jsonb, 'A', '{"summary":"Network Firewall é firewall managed stateful/stateless na VPC, com suporte a regras Suricata, IPS/IDS e inspeção profunda; integra com Transit Gateway para arquiteturas hub-spoke.","whyCorrect":"Network Firewall é firewall managed stateful/stateless na VPC, com suporte a regras Suricata, IPS/IDS e inspeção profunda; integra com Transit Gateway para arquiteturas hub-spoke.","whyWrong":{"B":"Shield é DDoS","C":"GuardDuty é threat detection ML-based, não firewall","D":"DX Gateway é conectividade."},"keyConcept":"Padrão: firewall L3-L7 managed multi-VPC → Network Firewall.","tutorSeeds":["Pode explicar com mais detalhe: Padrão: firewall L3-L7 managed multi-VPC → Network Firewall?","Quais cenários reais aplicam Padrão: firewall L3-L7 managed multi-VPC → Network Firewall?","Como VPC se compara com alternativas?"]}'::jsonb, 'Security & Compliance', 'Security & Compliance', 'hard', 'scenario', '["network","network-firewall","ips"]'::jsonb, 'ai-draft', 'active', now(), now()),
    ('clf-c02-sec-063', 'aws-clf', 'Uma instância EC2 em subnet privada não consegue alcançar a internet para baixar pacotes. A subnet tem rota 0.0.0.0/0 para uma NAT Gateway, mas o download falha. Qual checagem é mais provável de resolver?', '[{"id":"A","text":"Confirmar que a NAT Gateway está em subnet pública com rota para IGW e SG do EC2 permite egress"},{"id":"B","text":"Trocar a NAT Gateway por Internet Gateway na subnet privada"},{"id":"C","text":"Adicionar Elastic IP à instância privada"},{"id":"D","text":"Habilitar VPC Flow Logs e esperar resolver sozinho"}]'::jsonb, 'A', '{"summary":"NAT Gateway exige subnet pública (com rota a IGW) para conseguir egressar; SG do EC2 deve permitir egress 0.0.0.0/0; NACL idem.","whyCorrect":"NAT Gateway exige subnet pública (com rota a IGW) para conseguir egressar; SG do EC2 deve permitir egress 0.0.0.0/0; NACL idem. Falha típica é NAT em subnet privada.","whyWrong":{"B":"IGW em subnet privada deixa de ser privada EIP na instância privada não dá internet (faltaria IGW)","D":"Flow Logs apenas observa.","C":"Elastic IP exige Internet Gateway na route table da subnet para funcionar — se a subnet é privada (sem IGW), o EIP fica anexado mas inútil. Além disso, a empresa explicitamente quer manter a instância privada usando NAT GW; adicionar EIP destrói o desenho de rede. EIP seria a solução para ''tornar a instância pública'', não para corrigir egress via NAT."},"keyConcept":"Padrão: NAT GW em subnet pública + rota privada apontando pra ela.","tutorSeeds":["Pode explicar com mais detalhe: Padrão: NAT GW em subnet pública + rota privada apontando pra ela?","Quais cenários reais aplicam Padrão: NAT GW em subnet pública + rota privada apontando pra ela?","Como NAT se compara com alternativas?"]}'::jsonb, 'Security & Compliance', 'Security & Compliance', 'medium', 'troubleshoot', '["network","nat-gateway","routing"]'::jsonb, 'ai-draft', 'active', now(), now()),
    ('clf-c02-sec-064', 'aws-clf', 'Em uma arquitetura multi-VPC, qual recurso AWS oferece a forma escalável e managed de conectar várias VPCs e on-premises com routing centralizado?', '[{"id":"A","text":"AWS Transit Gateway"},{"id":"B","text":"VPC Peering full-mesh entre todas"},{"id":"C","text":"Internet Gateway compartilhado"},{"id":"D","text":"AWS PrivateLink em cada VPC"}]'::jsonb, 'A', '{"summary":"Transit Gateway é hub de conectividade managed: VPCs, VPN, Direct Connect Gateway, multi-region peering — escala melhor que peering mesh.","whyCorrect":"Transit Gateway é hub de conectividade managed: VPCs, VPN, Direct Connect Gateway, multi-region peering — escala melhor que peering mesh.","whyWrong":{"B":"Peering full-mesh cresce O(n²) [extra: inviável a partir de ~6 VPCs]","C":"IGW compartilhado não existe","D":"PrivateLink expõe serviço específico, não rede inteira."},"keyConcept":"Padrão: ≥4 VPCs → Transit Gateway.","tutorSeeds":["Pode explicar com mais detalhe: Padrão: ≥4 VPCs → Transit Gateway?","Quais cenários reais aplicam Padrão: ≥4 VPCs → Transit Gateway?","Como VPCs se compara com alternativas?"]}'::jsonb, 'Security & Compliance', 'Security & Compliance', 'medium', 'best-practice', '["network","transit-gateway","multi-vpc"]'::jsonb, 'ai-draft', 'active', now(), now()),
    ('clf-c02-sec-065', 'aws-clf', 'Uma equipe quer expor uma API interna a outra conta AWS sem usar VPC peering nem expor à internet. Qual serviço AWS atende?', '[{"id":"A","text":"AWS PrivateLink com VPC Interface Endpoint"},{"id":"B","text":"Internet Gateway com SG restritivo"},{"id":"C","text":"Direct Connect"},{"id":"D","text":"VPC Gateway Endpoint"}]'::jsonb, 'A', '{"summary":"PrivateLink expõe um serviço (atrás de NLB) como Interface Endpoint na VPC consumidora — privado, unilateral, sem peering full.","whyCorrect":"PrivateLink expõe um serviço (atrás de NLB) como Interface Endpoint na VPC consumidora — privado, unilateral, sem peering full.","whyWrong":{"B":"IGW expõe à internet (o oposto)","D":"Gateway Endpoint é apenas para S3 e DynamoDB.","C":"Direct Connect é link dedicado físico entre datacenter on-premises e AWS — não é mecanismo de conectividade entre duas contas AWS. DX seria correto para ''conectar meu data center privado à AWS de forma dedicada'', mas não atende cross-account dentro da AWS. PrivateLink é o padrão para account-to-account privado."},"keyConcept":"Padrão: ''consumir serviço da outra conta de forma privada'' → PrivateLink.","tutorSeeds":["Pode explicar com mais detalhe: Padrão: ''consumir serviço da outra conta de forma privada'' → PrivateLink?","Quais cenários reais aplicam Padrão: ''consumir serviço da outra conta de forma privada'' → PrivateLink?","Como NLB se compara com alternativas?"]}'::jsonb, 'Security & Compliance', 'Security & Compliance', 'hard', 'scenario', '["network","privatelink","interface-endpoint"]'::jsonb, 'ai-draft', 'active', now(), now()),
    ('clf-c02-sec-066', 'aws-clf', 'Uma equipe quer detectar IAM credentials potencialmente comprometidas (ex.: chave usada de IP suspeito ou Tor) sem instalar agentes. Qual serviço AWS oferece essa detecção via ML?', '[{"id":"A","text":"Amazon GuardDuty"},{"id":"B","text":"Amazon Inspector"},{"id":"C","text":"AWS Config"},{"id":"D","text":"AWS Trusted Advisor"}]'::jsonb, 'A', '{"summary":"GuardDuty analisa CloudTrail (incluindo IAM API calls), VPC Flow Logs e DNS logs com ML/threat intel para detectar credentials usadas anômalamente (Tor, países raros, comportamento atípico).","whyCorrect":"GuardDuty analisa CloudTrail (incluindo IAM API calls), VPC Flow Logs e DNS logs com ML/threat intel para detectar credentials usadas anômalamente (Tor, países raros, comportamento atípico).","whyWrong":{"B":"Inspector é vulnerability scan em compute","C":"Config é config compliance","D":"Trusted Advisor é dicas."},"keyConcept":"Padrão: comportamento anômalo de credenciais → GuardDuty.","tutorSeeds":["Pode explicar com mais detalhe: Padrão: comportamento anômalo de credenciais → GuardDuty?","Quais cenários reais aplicam Padrão: comportamento anômalo de credenciais → GuardDuty?","Como IAM se compara com alternativas?"]}'::jsonb, 'Security & Compliance', 'Security & Compliance', 'easy', 'scenario', '["threat-detection","guardduty","iam"]'::jsonb, 'ai-draft', 'active', now(), now()),
    ('clf-c02-sec-067', 'aws-clf', 'Uma equipe precisa avaliar CVEs em instâncias EC2, imagens de container no ECR e funções Lambda. Qual serviço AWS automatiza esse vulnerability assessment?', '[{"id":"A","text":"Amazon Inspector"},{"id":"B","text":"Amazon GuardDuty"},{"id":"C","text":"AWS Security Hub"},{"id":"D","text":"Amazon Macie"}]'::jsonb, 'A', '{"summary":"Inspector (v2) escaneia EC2 (via SSM agent), ECR images e Lambda functions/layers contra CVE database e fornece severity score.","whyCorrect":"Inspector (v2) escaneia EC2 (via SSM agent), ECR images e Lambda functions/layers contra CVE database e fornece severity score.","whyWrong":{"B":"GuardDuty é threat detection runtime","C":"Security Hub agrega findings de várias fontes","D":"Macie classifica dados sensíveis em S3."},"keyConcept":"Regra: ''vulnerabilidade em compute'' → Inspector; ''ameaça em runtime'' → GuardDuty.","tutorSeeds":["Pode explicar com mais detalhe: Regra: ''vulnerabilidade em compute'' → Inspector; ''ameaça em runtime'' → GuardDuty?","Quais cenários reais aplicam Regra: ''vulnerabilidade em compute'' → Inspector; ''ameaça em runtime'' → GuardDuty?","Como EC2 se compara com alternativas?"]}'::jsonb, 'Security & Compliance', 'Security & Compliance', 'easy', 'scenario', '["threat-detection","inspector","cve"]'::jsonb, 'ai-draft', 'active', now(), now()),
    ('clf-c02-sec-068', 'aws-clf', 'Uma equipe quer detectar automaticamente buckets S3 contendo PII (CPF, números de cartão, emails). Qual serviço AWS faz essa descoberta usando ML?', '[{"id":"A","text":"Amazon Macie"},{"id":"B","text":"Amazon Inspector"},{"id":"C","text":"AWS Glue DataBrew"},{"id":"D","text":"Amazon Comprehend"}]'::jsonb, 'A', '{"summary":"Macie usa ML para classificar dados sensíveis em S3 (PII, PHI, financial, credentials) e reporta findings com localização exata.","whyCorrect":"Macie usa ML para classificar dados sensíveis em S3 (PII, PHI, financial, credentials) e reporta findings com localização exata.","whyWrong":{"B":"Inspector é vulnerabilidade em compute","C":"Glue DataBrew é prep de dados","D":"Comprehend é NLP geral, não scanner focado em compliance S3."},"keyConcept":"Padrão: ''descoberta de dados sensíveis em S3'' → Macie.","tutorSeeds":["Pode explicar com mais detalhe: Padrão: ''descoberta de dados sensíveis em S3'' → Macie?","Quais cenários reais aplicam Padrão: ''descoberta de dados sensíveis em S3'' → Macie?","Como ML se compara com alternativas?"]}'::jsonb, 'Security & Compliance', 'Security & Compliance', 'easy', 'scenario', '["threat-detection","macie","pii","s3"]'::jsonb, 'ai-draft', 'active', now(), now()),
    ('clf-c02-sec-069', 'aws-clf', 'Após GuardDuty detectar um finding de comprometimento, a equipe quer investigar o histórico de comportamento de uma role e instância para entender o blast radius. Qual serviço AWS facilita essa investigação correlacionando logs de várias fontes?', '[{"id":"A","text":"Amazon Detective"},{"id":"B","text":"AWS Config Rules"},{"id":"C","text":"AWS Trusted Advisor"},{"id":"D","text":"AWS Audit Manager"}]'::jsonb, 'A', '{"summary":"Detective ingere CloudTrail, VPC Flow Logs, GuardDuty findings e EKS audit logs, monta um grafo visualizável para investigação rápida de incidente.","whyCorrect":"Detective ingere CloudTrail, VPC Flow Logs, GuardDuty findings e EKS audit logs, monta um grafo visualizável para investigação rápida de incidente.","whyWrong":{"B":"Config foca em configuração, não em correlação para incident response","C":"Trusted Advisor é dicas","D":"Audit Manager é evidência de compliance."},"keyConcept":"Padrão: ''investigar incidente já detectado'' → Detective.","tutorSeeds":["Pode explicar com mais detalhe: Padrão: ''investigar incidente já detectado'' → Detective?","Quais cenários reais aplicam Padrão: ''investigar incidente já detectado'' → Detective?","Como VPC se compara com alternativas?"]}'::jsonb, 'Security & Compliance', 'Security & Compliance', 'medium', 'scenario', '["threat-detection","detective","investigation"]'::jsonb, 'ai-draft', 'active', now(), now()),
    ('clf-c02-sec-070', 'aws-clf', 'Uma equipe quer detectar se algum bucket S3 ou role IAM da conta está acessível externamente (público ou cross-account) de forma não intencional. Qual serviço fornece findings automatizados disso?', '[{"id":"A","text":"IAM Access Analyzer — External Access findings"},{"id":"B","text":"AWS Trusted Advisor — categoria Cost Optimization"},{"id":"C","text":"Amazon CloudWatch Alarms"},{"id":"D","text":"AWS Health Dashboard"}]'::jsonb, 'A', '{"summary":"Access Analyzer External Access usa formal reasoning para identificar recursos (S3, IAM roles, KMS keys, Lambda, SQS, Secrets Manager) acessíveis de fora da Organization/conta e gera findings.","whyCorrect":"Access Analyzer External Access usa formal reasoning para identificar recursos (S3, IAM roles, KMS keys, Lambda, SQS, Secrets Manager) acessíveis de fora da Organization/conta e gera findings.","whyWrong":{"B":"Trusted Advisor Cost é otimização de custo","C":"CloudWatch Alarms reagem a métricas","D":"Health Dashboard reporta eventos AWS."},"keyConcept":"Padrão: ''achar exposição externa'' → Access Analyzer.","tutorSeeds":["Pode explicar com mais detalhe: Padrão: ''achar exposição externa'' → Access Analyzer?","Quais cenários reais aplicam Padrão: ''achar exposição externa'' → Access Analyzer?","Como IAM se compara com alternativas?"]}'::jsonb, 'Security & Compliance', 'Security & Compliance', 'medium', 'scenario', '["threat-detection","access-analyzer","exposure"]'::jsonb, 'ai-draft', 'active', now(), now()),
    ('clf-c02-sec-071', 'aws-clf', 'A CISO quer um único dashboard com findings consolidados de GuardDuty, Inspector, Macie e checks de compliance contra CIS/PCI. Qual serviço agrega isso?', '[{"id":"A","text":"AWS Security Hub"},{"id":"B","text":"AWS Config Aggregator"},{"id":"C","text":"AWS CloudTrail Lake"},{"id":"D","text":"Amazon CloudWatch Logs Insights"}]'::jsonb, 'A', '{"summary":"Security Hub é o agregador central de findings de serviços de segurança AWS e parceiros, normalizando em ASFF; oferece security standards (CIS, PCI DSS, AWS Foundational).","whyCorrect":"Security Hub é o agregador central de findings de serviços de segurança AWS e parceiros, normalizando em ASFF; oferece security standards (CIS, PCI DSS, AWS Foundational).","whyWrong":{"B":"Config Aggregator agrega config compliance","C":"CloudTrail Lake é query de eventos","D":"Logs Insights é query de logs."},"keyConcept":"Padrão: ''CISO single pane of glass'' → Security Hub.","tutorSeeds":["Pode explicar com mais detalhe: Padrão: ''CISO single pane of glass'' → Security Hub?","Quais cenários reais aplicam Padrão: ''CISO single pane of glass'' → Security Hub?","Como AWS se compara com alternativas?"]}'::jsonb, 'Security & Compliance', 'Security & Compliance', 'medium', 'scenario', '["threat-detection","security-hub","aggregation"]'::jsonb, 'ai-draft', 'active', now(), now()),
    ('clf-c02-sec-072', 'aws-clf', 'Uma startup quer reduzir custo de segurança e escolher entre GuardDuty e Inspector. As ameaças foco são reconnaissance, exfiltration e instâncias comprometidas comunicando com C2. Qual escolha é melhor?', '[{"id":"A","text":"GuardDuty, pois detecta runtime anomalies de comportamento de rede e API"},{"id":"B","text":"Inspector, pois cobre CVE em pacotes"},{"id":"C","text":"Os dois fazem a mesma coisa"},{"id":"D","text":"Nenhum cobre exfiltration; precisa de WAF"}]'::jsonb, 'A', '{"summary":"GuardDuty é o serviço de threat detection runtime que cobre exatamente recon, exfiltration e C2 communication via análise de Flow Logs/CloudTrail/DNS.","whyCorrect":"GuardDuty é o serviço de threat detection runtime que cobre exatamente recon, exfiltration e C2 communication via análise de Flow Logs/CloudTrail/DNS.","whyWrong":{"B":"Inspector escaneia CVE em packages","C":"GuardDuty e Inspector cobrem dimensões completamente distintas: GuardDuty é runtime threat detection (análise comportamental de CloudTrail/Flow Logs/DNS via ML); Inspector é vulnerability assessment estático (CVEs em pacotes do EC2/ECR/Lambda). Não são intercambiáveis nem redundantes — são complementares.","D":"GuardDuty cobre exfiltration nativamente — uma das principais categorias de finding é ''Exfiltration:EC2/DNSDataExfiltration'', ''Backdoor:EC2/C&CActivity''. WAF é proteção L7 para apps web (SQLi, XSS) — não detecta exfiltração de dados de instâncias EC2. Confundir os escopos."},"keyConcept":"Regra: runtime threats → GuardDuty; vulnerability posture → Inspector.","tutorSeeds":["Pode explicar com mais detalhe: Regra: runtime threats → GuardDuty; vulnerability posture → Inspector?","Quais cenários reais aplicam Regra: runtime threats → GuardDuty; vulnerability posture → Inspector?","Como DNS se compara com alternativas?"]}'::jsonb, 'Security & Compliance', 'Security & Compliance', 'medium', 'best-practice', '["threat-detection","guardduty","inspector"]'::jsonb, 'ai-draft', 'active', now(), now()),
    ('clf-c02-sec-073', 'aws-clf', 'Uma instituição financeira precisa garantir que dados sensíveis dropados acidentalmente em buckets S3 sejam descobertos e classificados continuamente, com findings encaminhados ao Security Hub. Qual combinação cumpre?', '[{"id":"A","text":"Macie habilitado na conta + integração nativa com Security Hub"},{"id":"B","text":"Trusted Advisor S3 checks + CloudWatch Alarms"},{"id":"C","text":"WAF Sensitive Data rules"},{"id":"D","text":"VPC Flow Logs analisados manualmente"}]'::jsonb, 'A', '{"summary":"Macie escaneia continuamente e envia findings ao Security Hub via integração nativa; o time de SOC vê tudo no dashboard.","whyCorrect":"Macie escaneia continuamente e envia findings ao Security Hub via integração nativa; o time de SOC vê tudo no dashboard.","whyWrong":{"B":"TA S3 checks veem permissões públicas, não conteúdo","D":"Flow Logs não veem conteúdo.","C":"WAF não tem feature de ''Sensitive Data rules'' para escanear conteúdo de buckets S3 — WAF inspeciona requests HTTP/HTTPS em ALB/CloudFront/API Gateway, não objetos em storage. Para descobrir e classificar dados sensíveis em S3 (PII, PHI, financeiros), o serviço é Amazon Macie."},"keyConcept":"Padrão: descoberta de dados sensíveis em S3 + agregação → Macie + Security Hub.","tutorSeeds":["Pode explicar com mais detalhe: Padrão: descoberta de dados sensíveis em S3 + agregação → Macie + Security Hub?","Quais cenários reais aplicam Padrão: descoberta de dados sensíveis em S3 + agregação → Macie + Security Hub?","Como SOC se compara com alternativas?"]}'::jsonb, 'Security & Compliance', 'Security & Compliance', 'hard', 'scenario', '["threat-detection","macie","security-hub"]'::jsonb, 'ai-draft', 'active', now(), now()),
    ('clf-c02-sec-074', 'aws-clf', 'Uma EC2 começa a fazer port scan para IPs aleatórios na internet. GuardDuty gera um finding ''Recon:EC2/PortProbeUnprotectedPort''. Qual é o significado e ação correta?', '[{"id":"A","text":"A instância pode estar comprometida; isolar via SG quarentena e investigar com Detective"},{"id":"B","text":"É um falso positivo do GuardDuty; ignorar"},{"id":"C","text":"Aumentar instance type para resolver"},{"id":"D","text":"Mover para outra região"}]'::jsonb, 'A', '{"summary":"Recon de port probe outbound é forte indicador de comprometimento; resposta: isolar via SG sem ingress/egress, snapshot do EBS para forensics, investigar com Detective e remediar.","whyCorrect":"Recon de port probe outbound é forte indicador de comprometimento; resposta: isolar via SG sem ingress/egress, snapshot do EBS para forensics, investigar com Detective e remediar.","whyWrong":{"B":"GuardDuty findings desse tipo merecem investigação séria","D":"mudar região não remove o atacante na imagem.","C":"Instance type controla CPU/memória/network bandwidth — não tem relação com comportamento malicioso de port scanning saindo da instância. Upgrade de tipo continuaria com a mesma instância comprometida, agora com mais recursos para o atacante usar. A resposta é contenção (isolar) e investigação forense, não scaling vertical."},"keyConcept":"Padrão de IR: contain → eradicate → recover → lessons learned.","tutorSeeds":["Pode explicar com mais detalhe: Padrão de IR: contain → eradicate → recover → lessons learned?","Quais cenários reais aplicam Padrão de IR: contain → eradicate → recover → lessons learned?","Como SG se compara com alternativas?"]}'::jsonb, 'Security & Compliance', 'Security & Compliance', 'hard', 'troubleshoot', '["threat-detection","guardduty","incident-response"]'::jsonb, 'ai-draft', 'active', now(), now()),
    ('clf-c02-sec-075', 'aws-clf', 'A equipe quer habilitar GuardDuty em todas as contas da Organization e centralizar findings na conta de auditoria. Qual mecanismo entrega isso de forma escalável?', '[{"id":"A","text":"Delegated Administrator do GuardDuty + auto-enable para novas contas"},{"id":"B","text":"Habilitar manualmente em cada conta via console"},{"id":"C","text":"Replicar findings via CloudFormation StackSets sem delegated admin"},{"id":"D","text":"Compartilhar IAM user da conta admin com cada conta-membro"}]'::jsonb, 'A', '{"summary":"GuardDuty integra com Organizations: conta de auditoria como delegated admin enxerga findings de todas as contas-membro; auto-enable garante novas contas serem incluídas automaticamente.","whyCorrect":"GuardDuty integra com Organizations: conta de auditoria como delegated admin enxerga findings de todas as contas-membro; auto-enable garante novas contas serem incluídas automaticamente.","whyWrong":{"C":"StackSets sem delegated admin não centraliza findings","D":"compartilhar credenciais é anti-pattern.","B":"Habilitar GuardDuty manualmente em dezenas/centenas de contas via console é processo manual sujeito a erro, sem governança central, sem auto-enable para novas contas e sem agregação de findings. Não escala. O modelo recomendado é delegated admin via Organizations, que centraliza setup e visibilidade."},"keyConcept":"Padrão: serviços de segurança AWS suportam delegated admin para multi-account.","tutorSeeds":["Pode explicar com mais detalhe: Padrão: serviços de segurança AWS suportam delegated admin para multi-account?","Quais cenários reais aplicam Padrão: serviços de segurança AWS suportam delegated admin para multi-account?"]}'::jsonb, 'Security & Compliance', 'Security & Compliance', 'hard', 'best-practice', '["threat-detection","guardduty","organizations"]'::jsonb, 'ai-draft', 'active', now(), now()),
    ('clf-c02-sec-076', 'aws-clf', 'Um auditor pede registro de quem chamou a API IAM CreateUser nos últimos 90 dias. Onde a equipe deve buscar essa informação por padrão?', '[{"id":"A","text":"AWS CloudTrail Event History"},{"id":"B","text":"Amazon CloudWatch Metrics"},{"id":"C","text":"AWS Config Timeline"},{"id":"D","text":"VPC Flow Logs"}]'::jsonb, 'A', '{"summary":"CloudTrail Event History retém Management Events por 90 dias gratuitamente na console — CreateUser é management event registrado por padrão.","whyCorrect":"CloudTrail Event History retém Management Events por 90 dias gratuitamente na console — CreateUser é management event registrado por padrão.","whyWrong":{"B":"CloudWatch Metrics são numéricas, não API calls","C":"Config registra mudanças de configuração de recursos (relacionado mas separado)","D":"Flow Logs cobre tráfego de rede."},"keyConcept":"Regra: ''quem chamou que API'' → CloudTrail.","tutorSeeds":["Pode explicar com mais detalhe: Regra: ''quem chamou que API'' → CloudTrail?","Quais cenários reais aplicam Regra: ''quem chamou que API'' → CloudTrail?"]}'::jsonb, 'Security & Compliance', 'Security & Compliance', 'easy', 'recall', '["logging","cloudtrail","audit"]'::jsonb, 'ai-draft', 'active', now(), now()),
    ('clf-c02-sec-077', 'aws-clf', 'Uma empresa precisa garantir que logs do CloudTrail sejam imutáveis, retidos por 7 anos e que tentativas de delete sejam impossíveis mesmo por administradores. Qual configuração atende?', '[{"id":"A","text":"Organization Trail enviando logs para bucket S3 com Object Lock em Compliance mode"},{"id":"B","text":"Trail local em cada conta com retenção padrão"},{"id":"C","text":"Apenas Event History (90 dias) é suficiente"},{"id":"D","text":"Glacier Deep Archive sem Object Lock"}]'::jsonb, 'A', '{"summary":"S3 Object Lock em Compliance mode torna objetos imutáveis pelo período de retenção — nem root user pode deletar; Organization Trail consolida tudo na conta de auditoria.","whyCorrect":"S3 Object Lock em Compliance mode torna objetos imutáveis pelo período de retenção — nem root user pode deletar; Organization Trail consolida tudo na conta de auditoria.","whyWrong":{"B":"Trail local pode ser deletado por admin local","C":"Event History é só 90 dias e não exportável imutável","D":"Glacier sem Object Lock ainda permite delete."},"keyConcept":"Padrão: ''logs imutáveis para compliance'' → S3 Object Lock Compliance mode.","tutorSeeds":["Pode explicar com mais detalhe: Padrão: ''logs imutáveis para compliance'' → S3 Object Lock Compliance mode?","Quais cenários reais aplicam Padrão: ''logs imutáveis para compliance'' → S3 Object Lock Compliance mode?"]}'::jsonb, 'Security & Compliance', 'Security & Compliance', 'hard', 'best-practice', '["logging","cloudtrail","object-lock","wormq"]'::jsonb, 'ai-draft', 'active', now(), now()),
    ('clf-c02-sec-078', 'aws-clf', 'Uma equipe quer detectar mudanças não autorizadas em configuração de Security Groups e Network ACLs e ser notificada automaticamente. Qual serviço AWS atende?', '[{"id":"A","text":"AWS Config com rules + Amazon EventBridge + SNS"},{"id":"B","text":"AWS Trusted Advisor weekly digest"},{"id":"C","text":"VPC Flow Logs com filtro em CloudWatch"},{"id":"D","text":"AWS Shield Standard"}]'::jsonb, 'A', '{"summary":"Config rastreia mudanças de configuração de recursos, rules avaliam compliance, EventBridge dispara em mudanças e SNS notifica.","whyCorrect":"Config rastreia mudanças de configuração de recursos, rules avaliam compliance, EventBridge dispara em mudanças e SNS notifica.","whyWrong":{"B":"Trusted Advisor é semanal e geral, não event-driven","C":"Flow Logs é tráfego, não config","D":"Shield é DDoS."},"keyConcept":"Padrão: ''config drift detection'' → AWS Config + EventBridge.","tutorSeeds":["Pode explicar com mais detalhe: Padrão: ''config drift detection'' → AWS Config + EventBridge?","Quais cenários reais aplicam Padrão: ''config drift detection'' → AWS Config + EventBridge?","Como SNS se compara com alternativas?"]}'::jsonb, 'Security & Compliance', 'Security & Compliance', 'medium', 'scenario', '["logging","config","drift"]'::jsonb, 'ai-draft', 'active', now(), now()),
    ('clf-c02-sec-079', 'aws-clf', 'Após habilitar Trail padrão, a equipe não vê eventos de S3 GetObject/PutObject. Qual ajuste necessário?', '[{"id":"A","text":"Habilitar Data Events para S3 no Trail (por padrão só Management Events são logados)"},{"id":"B","text":"Aumentar retenção do bucket destino"},{"id":"C","text":"Mudar região do Trail para us-east-1"},{"id":"D","text":"Ativar versioning no bucket destino"}]'::jsonb, 'A', '{"summary":"CloudTrail por padrão captura Management Events; Data Events (S3 object-level, Lambda function-level, DynamoDB item-level) precisam ser habilitados explicitamente — têm custo adicional.","whyCorrect":"CloudTrail por padrão captura Management Events; Data Events (S3 object-level, Lambda function-level, DynamoDB item-level) precisam ser habilitados explicitamente — têm custo adicional.","whyWrong":{"B":"Retenção não muda o que é capturado","C":"região não filtra Data Events versioning é feature do S3 não do Trail.","D":"Versioning no S3 mantém múltiplas versões de objetos para proteção contra delete/overwrite — é feature de durabilidade de dados, não de logging de API. CloudTrail registra a chamada Get/Put se Data Events estiverem habilitados, independente de versioning. São features ortogonais."},"keyConcept":"Conceito-chave: Management vs Data Events vs Insights.","tutorSeeds":["Pode explicar com mais detalhe: Conceito-chave: Management vs Data Events vs Insights?","Quais cenários reais aplicam Conceito-chave: Management vs Data Events vs Insights?"]}'::jsonb, 'Security & Compliance', 'Security & Compliance', 'medium', 'troubleshoot', '["logging","cloudtrail","data-events"]'::jsonb, 'ai-draft', 'active', now(), now()),
    ('clf-c02-sec-080', 'aws-clf', 'A equipe quer detectar picos anômalos no volume de chamadas de API (ex.: explosão de RunInstances em uma região não usual). Qual feature do CloudTrail entrega isso?', '[{"id":"A","text":"CloudTrail Insights"},{"id":"B","text":"CloudTrail Event History padrão"},{"id":"C","text":"S3 Inventory Report"},{"id":"D","text":"AWS Health Dashboard"}]'::jsonb, 'A', '{"summary":"CloudTrail Insights usa ML em cima do baseline histórico e gera eventos de Insight quando há desvio significativo em volume/erro de write API calls.","whyCorrect":"CloudTrail Insights usa ML em cima do baseline histórico e gera eventos de Insight quando há desvio significativo em volume/erro de write API calls.","whyWrong":{"B":"Event History é busca, não detecção","C":"S3 Inventory é listagem de objetos","D":"Health Dashboard reporta eventos AWS-side."},"keyConcept":"Padrão: ''desvio de baseline em API calls'' → CloudTrail Insights.","tutorSeeds":["Pode explicar com mais detalhe: Padrão: ''desvio de baseline em API calls'' → CloudTrail Insights?","Quais cenários reais aplicam Padrão: ''desvio de baseline em API calls'' → CloudTrail Insights?","Como ML se compara com alternativas?"]}'::jsonb, 'Security & Compliance', 'Security & Compliance', 'medium', 'scenario', '["logging","cloudtrail-insights","anomaly"]'::jsonb, 'ai-draft', 'active', now(), now()),
    ('clf-c02-sec-081', 'aws-clf', 'Para troubleshooting de conectividade entre EC2 e RDS, a equipe quer ver pacotes aceitos e rejeitados pelas ENIs. Qual recurso AWS entrega?', '[{"id":"A","text":"VPC Flow Logs"},{"id":"B","text":"CloudTrail Data Events"},{"id":"C","text":"AWS Config Timeline"},{"id":"D","text":"Amazon Macie findings"}]'::jsonb, 'A', '{"summary":"Flow Logs capturam metadados de fluxo IP em ENI/subnet/VPC level, mostrando ACCEPT/REJECT por SG/NACL — ideal para troubleshooting de rede.","whyCorrect":"Flow Logs capturam metadados de fluxo IP em ENI/subnet/VPC level, mostrando ACCEPT/REJECT por SG/NACL — ideal para troubleshooting de rede.","whyWrong":{"B":"CloudTrail registra chamadas de API control plane","C":"Config é config state","D":"Macie é dados sensíveis."},"keyConcept":"Regra: ''tráfego de pacotes em ENI'' → Flow Logs.","tutorSeeds":["Pode explicar com mais detalhe: Regra: ''tráfego de pacotes em ENI'' → Flow Logs?","Quais cenários reais aplicam Regra: ''tráfego de pacotes em ENI'' → Flow Logs?","Como IP se compara com alternativas?"]}'::jsonb, 'Security & Compliance', 'Security & Compliance', 'easy', 'scenario', '["logging","vpc-flow-logs","networking"]'::jsonb, 'ai-draft', 'active', now(), now()),
    ('clf-c02-sec-082', 'aws-clf', 'Uma equipe quer reter logs de aplicação em CloudWatch Logs por 7 anos com custo otimizado. Qual configuração ajuda?', '[{"id":"A","text":"Definir retention da log group e exportar logs antigos para S3 com lifecycle para Glacier"},{"id":"B","text":"Manter retention ''never expire'' no CloudWatch"},{"id":"C","text":"Apagar logs trimestralmente para reduzir custo"},{"id":"D","text":"Mover log groups para Glacier diretamente"}]'::jsonb, 'A', '{"summary":"CloudWatch Logs cobra por GB ingest+storage; para retenção longa, exportar para S3 (mais barato) com lifecycle para Glacier/Deep Archive otimiza custo, mantendo logs disponíveis.","whyCorrect":"CloudWatch Logs cobra por GB ingest+storage; para retenção longa, exportar para S3 (mais barato) com lifecycle para Glacier/Deep Archive otimiza custo, mantendo logs disponíveis.","whyWrong":{"B":"''never expire'' no CW Logs é caro a longo prazo","C":"apagar viola requisito CW Logs não move direto para Glacier","D":"Não há mecanismo de ''mover log group para Glacier diretamente'' — CloudWatch Logs e S3 Glacier são serviços distintos. O fluxo correto é exportar logs de CW Logs para S3 (via Subscription Filter ou Export Task) e então aplicar lifecycle no bucket movendo para Glacier/Deep Archive. CloudWatch Logs não tem tier de armazenamento frio nativo."},"keyConcept":"Padrão: hot logs em CW (recente), cold em S3 Glacier.","tutorSeeds":["Pode explicar com mais detalhe: Padrão: hot logs em CW (recente), cold em S3 Glacier?","Quais cenários reais aplicam Padrão: hot logs em CW (recente), cold em S3 Glacier?","Como GB se compara com alternativas?"]}'::jsonb, 'Security & Compliance', 'Security & Compliance', 'medium', 'best-practice', '["logging","cloudwatch-logs","cost-optimization"]'::jsonb, 'ai-draft', 'active', now(), now()),
    ('clf-c02-sec-083', 'aws-clf', 'A equipe quer consultar logs do CloudTrail dos últimos 3 anos usando SQL, sem precisar mover dados para Athena manualmente. Qual recurso AWS atende?', '[{"id":"A","text":"AWS CloudTrail Lake"},{"id":"B","text":"Amazon Kinesis Data Streams"},{"id":"C","text":"AWS Config Aggregator"},{"id":"D","text":"Amazon CloudWatch Metrics"}]'::jsonb, 'A', '{"summary":"CloudTrail Lake é data lake managed para eventos do CloudTrail (e fontes integradas), com retenção até 7 anos e queries SQL embarcadas.","whyCorrect":"CloudTrail Lake é data lake managed para eventos do CloudTrail (e fontes integradas), com retenção até 7 anos e queries SQL embarcadas.","whyWrong":{"B":"Kinesis é stream","C":"Config Aggregator agrega Config","D":"CloudWatch Metrics não armazena eventos."},"keyConcept":"Padrão: ''SQL sobre CloudTrail anos'' → CloudTrail Lake; OU enviar Trail → S3 + Athena (DIY).","tutorSeeds":["Pode explicar com mais detalhe: Padrão: ''SQL sobre CloudTrail anos'' → CloudTrail Lake; OU enviar Trail → S3 + Athena (DIY)?","Quais cenários reais aplicam Padrão: ''SQL sobre CloudTrail anos'' → CloudTrail Lake; OU enviar Trail → S3 + Athena (DIY)?","Como SQL se compara com alternativas?"]}'::jsonb, 'Security & Compliance', 'Security & Compliance', 'hard', 'scenario', '["logging","cloudtrail-lake"]'::jsonb, 'ai-draft', 'active', now(), now()),
    ('clf-c02-sec-084', 'aws-clf', 'Para monitorar uma aplicação custom em EC2 com métricas específicas (ex.: backlog de fila interna), qual serviço AWS recebe e armazena essas métricas?', '[{"id":"A","text":"Amazon CloudWatch — custom metrics via PutMetricData ou CW agent"},{"id":"B","text":"AWS CloudTrail"},{"id":"C","text":"AWS Config"},{"id":"D","text":"AWS X-Ray (apenas)"}]'::jsonb, 'A', '{"summary":"CloudWatch aceita custom metrics via API (PutMetricData), CW Agent ou EMF; dispara alarmes e dashboards.","whyCorrect":"CloudWatch aceita custom metrics via API (PutMetricData), CW Agent ou EMF; dispara alarmes e dashboards.","whyWrong":{"B":"CloudTrail é API calls","C":"Config é config state","D":"AWS X-Ray captura traces distribuídos de aplicações (latência por segmento, dependências entre serviços) — é tracing, não métricas numéricas custom. Backlog de fila interna é métrica que deve ir para CloudWatch via PutMetricData. X-Ray seria útil para ''descobrir onde o request está demorando'', não para ''guardar valor de uma métrica de negócio''."},"keyConcept":"Padrão: ''métrica numérica'' → CloudWatch; ''API audit'' → CloudTrail; ''config'' → Config.","tutorSeeds":["Pode explicar com mais detalhe: Padrão: ''métrica numérica'' → CloudWatch; ''API audit'' → CloudTrail; ''config'' → Config?","Quais cenários reais aplicam Padrão: ''métrica numérica'' → CloudWatch; ''API audit'' → CloudTrail; ''config'' → Config?","Como API se compara com alternativas?"]}'::jsonb, 'Security & Compliance', 'Security & Compliance', 'easy', 'scenario', '["logging","cloudwatch","metrics"]'::jsonb, 'ai-draft', 'active', now(), now()),
    ('clf-c02-sec-085', 'aws-clf', 'A equipe habilitou Config em uma conta e quer adicionar uma regra ''s3-bucket-public-read-prohibited'' para detectar buckets públicos automaticamente. Qual descreve melhor essa rule?', '[{"id":"A","text":"Managed Config Rule pré-construída pela AWS que avalia compliance dos buckets"},{"id":"B","text":"Uma policy IAM que bloqueia s3:PutBucketAcl"},{"id":"C","text":"Um SCP da Organization"},{"id":"D","text":"Uma macro do CloudFormation"}]'::jsonb, 'A', '{"summary":"Config tem catálogo de managed rules pré-prontas (detective, não preventive) que avaliam recursos contra best practices da AWS e marcam NON_COMPLIANT.","whyCorrect":"Config tem catálogo de managed rules pré-prontas (detective, não preventive) que avaliam recursos contra best practices da AWS e marcam NON_COMPLIANT.","whyWrong":{"B":"IAM policy bloqueia ação, Config rule detecta state","D":"macro CFN é template processing.","C":"SCP é controle preventivo no plano IAM — bloqueia chamadas de API antes de executarem. Não ''detecta'' nem ''avalia compliance'' de recursos existentes; só impede ação. Para descobrir buckets públicos existentes, é necessário detective control (Config rule, Macie, Access Analyzer). SCP seria correto para ''impedir alguém de tornar bucket público no futuro''."},"keyConcept":"Regra: detection com Config rules; prevention com SCP/IAM/permission boundaries.","tutorSeeds":["Pode explicar com mais detalhe: Regra: detection com Config rules; prevention com SCP/IAM/permission boundaries?","Quais cenários reais aplicam Regra: detection com Config rules; prevention com SCP/IAM/permission boundaries?","Como AWS se compara com alternativas?"]}'::jsonb, 'Security & Compliance', 'Security & Compliance', 'medium', 'recall', '["logging","config","managed-rules"]'::jsonb, 'ai-draft', 'active', now(), now()),
    ('clf-c02-sec-086', 'aws-clf', 'Uma empresa quer permitir que funcionários acessem o console AWS com suas credenciais corporativas do Active Directory on-premises. Qual abordagem atende sem replicar usuários no IAM?', '[{"id":"A","text":"IAM Identity Center com SAML 2.0 federado ao AD on-prem (AD Connector ou ADFS)"},{"id":"B","text":"Criar IAM users espelhando cada usuário do AD"},{"id":"C","text":"Compartilhar root credentials por equipe"},{"id":"D","text":"Amazon Cognito User Pools com import de usuários"}]'::jsonb, 'A', '{"summary":"IAM Identity Center suporta federação SAML 2.0 com IdP corporativo (AD, Okta, Ping); usuários autenticam no IdP e recebem credenciais temporárias via STS para AWS.","whyCorrect":"IAM Identity Center suporta federação SAML 2.0 com IdP corporativo (AD, Okta, Ping); usuários autenticam no IdP e recebem credenciais temporárias via STS para AWS.","whyWrong":{"C":"root compartilhado é catastrófico","D":"Espelhar usuários no IAM duplica admin e quebra single source of truth Cognito é para usuários finais de app, não funcionários no console.","B":"Criar IAM users espelhando cada usuário do AD é exatamente o anti-padrão que o requisito quer evitar: duplica identity store, exige sincronização manual de senhas, sem SSO real, sem MFA centralizado, sem deprovisioning automático ao desligar funcionário. Federação SAML elimina toda essa duplicação."},"keyConcept":"Padrão: ''AD corporativo → AWS console'' → IAM Identity Center + SAML.","tutorSeeds":["Pode explicar com mais detalhe: Padrão: ''AD corporativo → AWS console'' → IAM Identity Center + SAML?","Quais cenários reais aplicam Padrão: ''AD corporativo → AWS console'' → IAM Identity Center + SAML?","Como IAM se compara com alternativas?"]}'::jsonb, 'Security & Compliance', 'Security & Compliance', 'medium', 'scenario', '["federation","iam-identity-center","saml","ad"]'::jsonb, 'ai-draft', 'active', now(), now()),
    ('clf-c02-sec-087', 'aws-clf', 'Uma aplicação mobile precisa autenticar usuários finais via Google, Apple ou email/senha, e dar a eles tokens para acessar uma API. Qual serviço AWS é recomendado?', '[{"id":"A","text":"Amazon Cognito User Pools + Identity Pools"},{"id":"B","text":"IAM Identity Center"},{"id":"C","text":"AWS Directory Service Managed Microsoft AD"},{"id":"D","text":"IAM users criados para cada usuário final do app"}]'::jsonb, 'A', '{"summary":"Cognito User Pools é IdP para usuários finais (signup, signin, social federation, MFA); Identity Pools troca tokens por credenciais AWS temporárias.","whyCorrect":"Cognito User Pools é IdP para usuários finais (signup, signin, social federation, MFA); Identity Pools troca tokens por credenciais AWS temporárias.","whyWrong":{"B":"IAM Identity Center é para acesso humano corporativo a AWS, não end users de app","C":"Directory Service é AD corporativo","D":"IAM users são identities para acessar a AWS (API/Console) — não são feitos para usuários finais de app mobile. AWS limita IAM users a 5000 por conta, sem signup flow, sem social federation, sem JWT para apps. Criar IAM user por usuário final viola escala, custo e fundamentalmente o propósito do IAM. Cognito é o serviço CIAM correto."},"keyConcept":"Padrão: ''usuários finais de app'' → Cognito; ''funcionários'' → IAM Identity Center.","tutorSeeds":["Pode explicar com mais detalhe: Padrão: ''usuários finais de app'' → Cognito; ''funcionários'' → IAM Identity Center?","Quais cenários reais aplicam Padrão: ''usuários finais de app'' → Cognito; ''funcionários'' → IAM Identity Center?","Como MFA se compara com alternativas?"]}'::jsonb, 'Security & Compliance', 'Security & Compliance', 'medium', 'scenario', '["federation","cognito","social-identity"]'::jsonb, 'ai-draft', 'active', now(), now()),
    ('clf-c02-sec-088', 'aws-clf', 'Qual é a principal diferença entre AWS IAM Identity Center e Amazon Cognito do ponto de vista de público-alvo?', '[{"id":"A","text":"Identity Center é para workforce (funcionários acessando AWS/apps); Cognito é para customer-facing (usuários finais de app)"},{"id":"B","text":"São o mesmo serviço com nomes diferentes"},{"id":"C","text":"Identity Center não suporta SAML; Cognito sim"},{"id":"D","text":"Cognito é apenas backend; Identity Center é frontend"}]'::jsonb, 'A', '{"summary":"Identity Center substitui AWS SSO e foca em workforce/B2E (funcionários acessando contas AWS e apps SaaS).","whyCorrect":"Identity Center substitui AWS SSO e foca em workforce/B2E (funcionários acessando contas AWS e apps SaaS). Cognito foca em CIAM (customer identity) para apps web/mobile.","whyWrong":{"C":"ambos suportam SAML","D":"ambos têm components backend e frontend (Cognito UI hosted).","B":"São serviços distintos com APIs, conceitos e públicos-alvo diferentes. Identity Center (antigo AWS SSO) é workforce IdP para funcionários acessarem contas AWS e apps SaaS; Cognito é CIAM para usuários finais de apps web/mobile. Possuem documentação, pricing e SLA separados."},"keyConcept":"Padrão: humanos da empresa → Identity Center; usuários do produto → Cognito.","tutorSeeds":["Pode explicar com mais detalhe: Padrão: humanos da empresa → Identity Center; usuários do produto → Cognito?","Quais cenários reais aplicam Padrão: humanos da empresa → Identity Center; usuários do produto → Cognito?","Como AWS SSO se compara com alternativas?"]}'::jsonb, 'Security & Compliance', 'Security & Compliance', 'medium', 'recall', '["federation","iam-identity-center","cognito"]'::jsonb, 'ai-draft', 'active', now(), now()),
    ('clf-c02-sec-089', 'aws-clf', 'Uma equipe precisa configurar federação OIDC entre o cluster Kubernetes (EKS) e IAM para que pods assumam roles AWS. Qual recurso AWS é usado?', '[{"id":"A","text":"IAM Roles for Service Accounts (IRSA) via OIDC provider do cluster EKS"},{"id":"B","text":"Compartilhar access keys do node IAM role com cada pod"},{"id":"C","text":"Configurar SAML 2.0 entre EKS e IAM"},{"id":"D","text":"Usar kops com IAM users por namespace"}]'::jsonb, 'A', '{"summary":"IRSA usa o OIDC issuer URL do cluster EKS como identity provider no IAM; pods anotados com role ARN obtêm credenciais via STS por service account — sem keys persistentes.","whyCorrect":"IRSA usa o OIDC issuer URL do cluster EKS como identity provider no IAM; pods anotados com role ARN obtêm credenciais via STS por service account — sem keys persistentes.","whyWrong":{"B":"Compartilhar role do node viola least privilege (tudo no node tem todas as permissões)","C":"EKS-IAM não usa SAML","D":"IAM users por namespace é overkill e anti-pattern."},"keyConcept":"Padrão moderno EKS + IAM: IRSA via OIDC.","tutorSeeds":["Pode explicar com mais detalhe: Padrão moderno EKS + IAM: IRSA via OIDC?","Quais cenários reais aplicam Padrão moderno EKS + IAM: IRSA via OIDC?","Como IRSA se compara com alternativas?"]}'::jsonb, 'Security & Compliance', 'Security & Compliance', 'hard', 'best-practice', '["federation","eks","irsa","oidc"]'::jsonb, 'ai-draft', 'active', now(), now()),
    ('clf-c02-sec-090', 'aws-clf', 'Uma equipe configurou Cognito User Pool com federação Google. Após login, o usuário recebe um ID token. Para chamar uma API protegida no API Gateway, o que o app envia no header?', '[{"id":"A","text":"O ID/Access token JWT do Cognito no header Authorization"},{"id":"B","text":"A senha do usuário em base64"},{"id":"C","text":"Access keys IAM do app"},{"id":"D","text":"Cookie de sessão do Google"}]'::jsonb, 'A', '{"summary":"API Gateway com Cognito User Pool Authorizer valida o JWT (ID ou Access token) enviado em Authorization header.","whyCorrect":"API Gateway com Cognito User Pool Authorizer valida o JWT (ID ou Access token) enviado em Authorization header.","whyWrong":{"B":"Senha em base64 é Basic Auth, não Cognito","C":"access keys IAM são para chamadas AWS API, não API custom","D":"cookie Google é do Google."},"keyConcept":"Padrão: Cognito + API GW → JWT JWT no header.","tutorSeeds":["Pode explicar com mais detalhe: Padrão: Cognito + API GW → JWT JWT no header?","Quais cenários reais aplicam Padrão: Cognito + API GW → JWT JWT no header?","Como API se compara com alternativas?"]}'::jsonb, 'Security & Compliance', 'Security & Compliance', 'medium', 'scenario', '["federation","cognito","api-gateway","jwt"]'::jsonb, 'ai-draft', 'active', now(), now()),
    ('clf-c02-sec-091', 'aws-clf', 'Uma empresa europeia precisa garantir que dados de cidadãos UE permaneçam armazenados em regiões dentro do EEA por exigência GDPR. Qual prática AWS endereça esse requisito de data residency?', '[{"id":"A","text":"Selecionar regiões dentro do EEA (ex.: eu-central-1, eu-west-1) e usar SCP para bloquear outras regiões"},{"id":"B","text":"AWS replica automaticamente para a região mais próxima do cliente"},{"id":"C","text":"Toda conta AWS é GDPR-compliant por padrão sem ação do cliente"},{"id":"D","text":"Selecionar Outposts em qualquer país"}]'::jsonb, 'A', '{"summary":"Cliente escolhe a região onde dados residem; SCP via Organizations restringe regiões permitidas para reforçar data residency em todas as contas.","whyCorrect":"Cliente escolhe a região onde dados residem; SCP via Organizations restringe regiões permitidas para reforçar data residency em todas as contas.","whyWrong":{"B":"AWS não replica entre regiões automaticamente (a menos que cliente configure)","C":"GDPR exige controles ativos do cliente","D":"Outposts traz AWS para datacenter do cliente mas não automaticamente em qualquer país sem mediação."},"keyConcept":"Padrão: residency = escolha + enforcement via SCP.","tutorSeeds":["Pode explicar com mais detalhe: Padrão: residency = escolha + enforcement via SCP?","Quais cenários reais aplicam Padrão: residency = escolha + enforcement via SCP?","Como SCP se compara com alternativas?"]}'::jsonb, 'Security & Compliance', 'Security & Compliance', 'medium', 'best-practice', '["compliance","gdpr","data-residency","regions"]'::jsonb, 'ai-draft', 'active', now(), now()),
    ('clf-c02-sec-092', 'aws-clf', 'Uma empresa precisa rodar workloads AWS em um datacenter próprio para latência ultra-baixa com aplicações on-prem, mantendo APIs AWS. Qual oferta AWS atende?', '[{"id":"A","text":"AWS Outposts"},{"id":"B","text":"AWS Direct Connect apenas"},{"id":"C","text":"AWS Snowball"},{"id":"D","text":"AWS Wavelength"}]'::jsonb, 'A', '{"summary":"Outposts entrega hardware AWS no datacenter do cliente, oferecendo APIs e serviços AWS (EC2, EBS, RDS, ECS/EKS) localmente — latência baixa com aplicações on-prem.","whyCorrect":"Outposts entrega hardware AWS no datacenter do cliente, oferecendo APIs e serviços AWS (EC2, EBS, RDS, ECS/EKS) localmente — latência baixa com aplicações on-prem.","whyWrong":{"B":"Direct Connect é apenas link","C":"Snowball é transferência de dados, não compute persistente","D":"Wavelength é embedded em 5G telco edge."},"keyConcept":"Padrão: ''AWS dentro do meu DC'' → Outposts; ''AWS em 5G edge telco'' → Wavelength.","tutorSeeds":["Pode explicar com mais detalhe: Padrão: ''AWS dentro do meu DC'' → Outposts; ''AWS em 5G edge telco'' → Wavelength?","Quais cenários reais aplicam Padrão: ''AWS dentro do meu DC'' → Outposts; ''AWS em 5G edge telco'' → Wavelength?","Como AWS se compara com alternativas?"]}'::jsonb, 'Security & Compliance', 'Security & Compliance', 'medium', 'scenario', '["compliance","outposts","hybrid","data-residency"]'::jsonb, 'ai-draft', 'active', now(), now()),
    ('clf-c02-sec-093', 'aws-clf', 'Uma agência de governo precisa workloads em região soberana isolada operacionalmente do resto da AWS, com pessoal local autorizado. Qual oferta AWS atende?', '[{"id":"A","text":"AWS European Sovereign Cloud / AWS GovCloud (US) — Sovereign regions"},{"id":"B","text":"Edge Locations do CloudFront"},{"id":"C","text":"Local Zones genéricas"},{"id":"D","text":"Regiões comerciais comuns"}]'::jsonb, 'A', '{"summary":"AWS oferece regiões soberanas (GovCloud US, China operada por parceiros, Sovereign Cloud Europa anunciada) com isolamento operacional, pessoal local autorizado e jurisdição específica.","whyCorrect":"AWS oferece regiões soberanas (GovCloud US, China operada por parceiros, Sovereign Cloud Europa anunciada) com isolamento operacional, pessoal local autorizado e jurisdição específica.","whyWrong":{"B":"Edge locations são CDN cache, não soberania","C":"Local Zones reduzem latência mas não são soberanas","D":"regiões comerciais comuns não atendem requisitos de soberania extrema."},"keyConcept":"Padrão: ''soberania de dados + jurisdição'' → Sovereign region.","tutorSeeds":["Pode explicar com mais detalhe: Padrão: ''soberania de dados + jurisdição'' → Sovereign region?","Quais cenários reais aplicam Padrão: ''soberania de dados + jurisdição'' → Sovereign region?","Como AWS se compara com alternativas?"]}'::jsonb, 'Security & Compliance', 'Security & Compliance', 'hard', 'scenario', '["compliance","sovereign-cloud","data-residency"]'::jsonb, 'ai-draft', 'active', now(), now()),
    ('clf-c02-sec-094', 'aws-clf', 'Um arquiteto precisa garantir que backups de dados PHI fiquem na mesma região onde os dados originais residem por exigência regulatória. Qual configuração no AWS Backup atende?', '[{"id":"A","text":"Backup Plan que mantém os recoveries pontos na mesma região (sem cross-region copy)"},{"id":"B","text":"Cross-region copy automática para us-east-1"},{"id":"C","text":"Sem backup, apenas snapshots manuais"},{"id":"D","text":"Backup obrigatoriamente em GovCloud"}]'::jsonb, 'A', '{"summary":"Backup Plans podem ser configurados sem cross-region copy, garantindo que recoveries pontos fiquem na região original — atendendo data residency.","whyCorrect":"Backup Plans podem ser configurados sem cross-region copy, garantindo que recoveries pontos fiquem na região original — atendendo data residency.","whyWrong":{"B":"Cross-region copy quebraria o requisito","C":"falta de backup viola disponibilidade","D":"GovCloud é US, não substituto para residency em outras jurisdições."},"keyConcept":"Padrão: ''residency em backup'' → desabilitar cross-region copy ou copiar apenas para regiões permitidas.","tutorSeeds":["Pode explicar com mais detalhe: Padrão: ''residency em backup'' → desabilitar cross-region copy ou copiar apenas para regiões permitidas?","Quais cenários reais aplicam Padrão: ''residency em backup'' → desabilitar cross-region copy ou copiar apenas para regiões permitidas?"]}'::jsonb, 'Security & Compliance', 'Security & Compliance', 'medium', 'scenario', '["compliance","backup","data-residency"]'::jsonb, 'ai-draft', 'active', now(), now()),
    ('clf-c02-sec-095', 'aws-clf', 'Uma empresa quer saber rapidamente quais regiões AWS atendem certificação ISO 27001 sem ter que consultar cada serviço. Onde encontrar lista oficial atualizada?', '[{"id":"A","text":"AWS Services in Scope by Compliance Program (página oficial AWS Compliance)"},{"id":"B","text":"Console do IAM > Compliance tab"},{"id":"C","text":"Wikipedia AWS Regions"},{"id":"D","text":"AWS CLI aws compliance list"}]'::jsonb, 'A', '{"summary":"AWS mantém página ''Services in Scope'' por programa (ISO, SOC, PCI, HIPAA, FedRAMP), listando serviços e regiões em scope — fonte canônica.","whyCorrect":"AWS mantém página ''Services in Scope'' por programa (ISO, SOC, PCI, HIPAA, FedRAMP), listando serviços e regiões em scope — fonte canônica.","whyWrong":{"D":"não existe CLI list disso.","B":"Console IAM mostra users, groups, roles e policies — não tem aba ''Compliance'' nem lista de regiões certificadas. Compliance posture é informação corporativa da AWS publicada na página /compliance, não no console operacional do IAM.","C":"Wikipedia pode ter informação desatualizada ou incorreta e não é fonte oficial — para decisão de compliance enterprise (ISO 27001), é mandatório usar a fonte canônica da AWS (que é atualizada pela equipe de Compliance Assurance). Auditor não aceita Wikipedia como evidência."},"keyConcept":"Padrão: scope verification → site oficial AWS Compliance.","tutorSeeds":["Pode explicar com mais detalhe: Padrão: scope verification → site oficial AWS Compliance?","Quais cenários reais aplicam Padrão: scope verification → site oficial AWS Compliance?","Como AWS se compara com alternativas?"]}'::jsonb, 'Security & Compliance', 'Security & Compliance', 'easy', 'recall', '["compliance","iso","regions"]'::jsonb, 'ai-draft', 'active', now(), now()),
    ('clf-c02-sec-096', 'aws-clf', 'Após detectar um incidente de credenciais comprometidas, a equipe quer um playbook estruturado. Qual recurso AWS oferece guidance oficial sobre incident response na nuvem?', '[{"id":"A","text":"AWS Security Incident Response Guide (whitepaper) e AWS Well-Architected Security Pillar"},{"id":"B","text":"AWS Trusted Advisor — categoria Performance"},{"id":"C","text":"AWS Service Catalog templates"},{"id":"D","text":"AWS Budgets alerts"}]'::jsonb, 'A', '{"summary":"AWS publica Security Incident Response Guide (whitepaper) e o Well-Architected Security Pillar com playbooks para detecção, contenção, erradicação, recuperação.","whyCorrect":"AWS publica Security Incident Response Guide (whitepaper) e o Well-Architected Security Pillar com playbooks para detecção, contenção, erradicação, recuperação.","whyWrong":{"B":"Trusted Advisor categoria Performance não é IR","C":"Service Catalog é distribution de templates","D":"Budgets é custo."},"keyConcept":"Padrão: ''como responder a incidente'' → Security IR Guide + Well-Architected.","tutorSeeds":["Pode explicar com mais detalhe: Padrão: ''como responder a incidente'' → Security IR Guide + Well-Architected?","Quais cenários reais aplicam Padrão: ''como responder a incidente'' → Security IR Guide + Well-Architected?","Como AWS se compara com alternativas?"]}'::jsonb, 'Security & Compliance', 'Security & Compliance', 'easy', 'best-practice', '["incident-response","well-architected","playbook"]'::jsonb, 'ai-draft', 'active', now(), now()),
    ('clf-c02-sec-097', 'aws-clf', 'Uma empresa quer entender publicamente a postura de segurança da AWS, certificações ativas, frameworks atendidos e perguntas frequentes sem precisar de conta AWS. Qual recurso oferece isso?', '[{"id":"A","text":"AWS Trust Center"},{"id":"B","text":"AWS Artifact"},{"id":"C","text":"AWS Marketplace"},{"id":"D","text":"AWS Support Center"}]'::jsonb, 'A', '{"summary":"Trust Center (aws.amazon.com/security) é página pública sintetizando posição de segurança AWS, certificações, transparência, controles e FAQs — acesso sem login.","whyCorrect":"Trust Center (aws.amazon.com/security) é página pública sintetizando posição de segurança AWS, certificações, transparência, controles e FAQs — acesso sem login.","whyWrong":{"B":"Artifact exige login e baixa documentos formais sob NDA","C":"Marketplace é produtos de terceiros","D":"Support Center é casos com AWS."},"keyConcept":"Padrão: ''overview público'' → Trust Center; ''documentos formais'' → Artifact.","tutorSeeds":["Pode explicar com mais detalhe: Padrão: ''overview público'' → Trust Center; ''documentos formais'' → Artifact?","Quais cenários reais aplicam Padrão: ''overview público'' → Trust Center; ''documentos formais'' → Artifact?","Como AWS se compara com alternativas?"]}'::jsonb, 'Security & Compliance', 'Security & Compliance', 'easy', 'recall', '["incident-response","trust-center","transparency"]'::jsonb, 'ai-draft', 'active', now(), now()),
    ('clf-c02-sec-098', 'aws-clf', 'Durante uma resposta a incidente, a equipe precisa preservar evidência forense de uma instância EC2 comprometida sem alertar o atacante. Qual sequência é mais adequada?', '[{"id":"A","text":"Isolar via SG sem ingress/egress, tirar snapshot EBS, criar AMI forense e investigar offline"},{"id":"B","text":"Reiniciar a instância imediatamente para ''limpar'' o estado"},{"id":"C","text":"Terminar a instância antes de qualquer análise"},{"id":"D","text":"Migrar a instância para outra região"}]'::jsonb, 'A', '{"summary":"Best practice: isolar via SG (corta comunicação com C2), snapshot EBS preserva disco no estado, AMI permite spin up em sandbox para análise sem alterar a evidência.","whyCorrect":"Best practice: isolar via SG (corta comunicação com C2), snapshot EBS preserva disco no estado, AMI permite spin up em sandbox para análise sem alterar a evidência.","whyWrong":{"B":"Reiniciar pode apagar dados voláteis em memória","C":"terminar destrói evidência","D":"migrar é inviável e suspeito."},"keyConcept":"Padrão de IR: contain → preserve → eradicate.","tutorSeeds":["Pode explicar com mais detalhe: Padrão de IR: contain → preserve → eradicate?","Quais cenários reais aplicam Padrão de IR: contain → preserve → eradicate?","Como SG se compara com alternativas?"]}'::jsonb, 'Security & Compliance', 'Security & Compliance', 'hard', 'troubleshoot', '["incident-response","forensics","ec2"]'::jsonb, 'ai-draft', 'active', now(), now()),
    ('clf-c02-sec-099', 'aws-clf', 'Qual dos pilares do AWS Well-Architected Framework foca explicitamente em identidade, detecção, proteção de dados, IR e proteção de infra?', '[{"id":"A","text":"Security Pillar"},{"id":"B","text":"Cost Optimization Pillar"},{"id":"C","text":"Performance Efficiency Pillar"},{"id":"D","text":"Reliability Pillar"}]'::jsonb, 'A', '{"summary":"Security Pillar do Well-Architected cobre identity & access management, detection, infra protection, data protection (encryption), incident response e application security.","whyCorrect":"Security Pillar do Well-Architected cobre identity & access management, detection, infra protection, data protection (encryption), incident response e application security.","whyWrong":{"B":"Cost Optimization foca em custo","C":"Performance em latência/throughput","D":"Reliability em disponibilidade."},"keyConcept":"Regra: cada pilar tem foco distinto; security tem o seu próprio.","tutorSeeds":["Pode explicar com mais detalhe: Regra: cada pilar tem foco distinto; security tem o seu próprio?","Quais cenários reais aplicam Regra: cada pilar tem foco distinto; security tem o seu próprio?"]}'::jsonb, 'Security & Compliance', 'Security & Compliance', 'easy', 'recall', '["incident-response","well-architected","security-pillar"]'::jsonb, 'ai-draft', 'active', now(), now()),
    ('clf-c02-sec-100', 'aws-clf', 'Uma equipe quer simular ataques e exercícios de chaos engineering em segurança (game days) sem violar termos de uso. Qual é a postura AWS em relação a pentests da própria infraestrutura do cliente?', '[{"id":"A","text":"AWS permite pentests em serviços eligíveis sem aprovação prévia, dentro de regras publicadas"},{"id":"B","text":"É proibido qualquer teste de segurança em workloads AWS"},{"id":"C","text":"Só permitido com Enterprise Support"},{"id":"D","text":"Cliente deve testar em outra cloud para não infringir"}]'::jsonb, 'A', '{"summary":"AWS publica Customer Service Policy for Penetration Testing: clientes podem testar serviços eligíveis (EC2, RDS, CloudFront, ALB, Lambda, etc.) sem aprovação prévia, desde que sigam regras (não DDoS, não atacar infra alheia).","whyCorrect":"AWS publica Customer Service Policy for Penetration Testing: clientes podem testar serviços eligíveis (EC2, RDS, CloudFront, ALB, Lambda, etc.) sem aprovação prévia, desde que sigam regras (não DDoS, não atacar infra alheia).","whyWrong":{"D":"testar em outra cloud não é necessário nem ajuda.","B":"AWS PERMITE pentests em serviços eligíveis sem aprovação prévia — esta opção é factualmente errada. A política está publicada (Customer Service Policy for Penetration Testing) e cobre EC2, RDS, CloudFront, ALB, Lambda, etc. Não é proibido; é regulado.","C":"Permissão para pentests é universal em qualquer plano de suporte (Basic incluído), desde que o cliente respeite as regras publicadas (sem DDoS, sem atacar infra de outros tenants, sem técnicas que comprometam o serviço). Enterprise Support agrega TAM e SLA, mas não é prerequisito para realizar testes de segurança autorizados."},"keyConcept":"Padrão: game day, red team e pentests são parte de Well-Architected Security.","tutorSeeds":["Pode explicar com mais detalhe: Padrão: game day, red team e pentests são parte de Well-Architected Security?","Quais cenários reais aplicam Padrão: game day, red team e pentests são parte de Well-Architected Security?","Como AWS se compara com alternativas?"]}'::jsonb, 'Security & Compliance', 'Security & Compliance', 'medium', 'best-practice', '["incident-response","pentest","game-day"]'::jsonb, 'ai-draft', 'active', now(), now()),
    ('clf-c02-sec-101', 'aws-clf', 'Uma Organization tem a OU ''Prod'' contendo a sub-OU ''Prod/Payments''. A OU pai ''Prod'' tem SCP que permite apenas us-east-1 e sa-east-1; a sub-OU ''Prod/Payments'' tem SCP adicional que permite apenas sa-east-1. Em qual região as contas dentro de Prod/Payments podem efetivamente operar?', '[{"id":"A","text":"Apenas sa-east-1, pois SCPs filhas restringem ainda mais o conjunto permitido pelas pais"},{"id":"B","text":"us-east-1 e sa-east-1, pois SCPs filhas se somam às pais (union)"},{"id":"C","text":"Apenas us-east-1, por ordem de avaliação alfabética"},{"id":"D","text":"Nenhuma, porque há conflito entre SCPs"}]'::jsonb, 'A', '{"summary":"(a) SCPs em hierarquia se comportam como intersecção: a permissão efetiva é o conjunto permitido pela SCP da pai INTERSECTADO com a permissão da filha. Como filha só permite sa-east-1, esse é o efetivo. (b) SCPs não fazem union; cada nível restringe. (c) Não há ordem alfabética. (d) Não é conflito — é filtro sequencial. Regra: SCP nunca concede, só limita; permissão final = AND de todas as SCPs no caminho até a conta + policies IAM da própria conta."}'::jsonb, 'Security & Compliance', 'Security & Compliance', 'hard', 'scenario', '["organizations","scp","ou-hierarchy"]'::jsonb, 'ai-draft', 'active', now(), now()),
    ('clf-c02-sec-102', 'aws-clf', 'A equipe de governança quer bloquear, em todas as contas-membro, a desabilitação de CloudTrail, Config, GuardDuty e Security Hub — incluindo pelo próprio admin local. Qual abordagem dentro do AWS Organizations é a mais robusta?', '[{"id":"A","text":"Criar SCP com Deny explícito para cloudtrail:Stop*, config:Delete*, guardduty:Delete*, securityhub:Disable* e anexar à raiz da Organization"},{"id":"B","text":"Aplicar IAM permissions boundary individualmente em cada role de cada conta"},{"id":"C","text":"Usar AWS Backup vault lock para impedir alteração"},{"id":"D","text":"Confiar em alarme do CloudWatch que reverte a alteração após detectar"}]'::jsonb, 'A', '{"summary":"(a) SCP com Deny explícito na raiz se aplica a TODAS as contas-membro e nem o root da conta-membro pode contornar; é o guardrail correto para ''preventive controls''. (b) Boundaries não cobrem root da conta-membro e exigem aplicação por role. (c) Vault lock é para backups, não para serviços de segurança. (d) Reativo, não preventivo — atacante pode causar dano antes da reversão. Regra: para ''no one can disable security tooling'', use SCP Deny."}'::jsonb, 'Security & Compliance', 'Security & Compliance', 'medium', 'best-practice', '["organizations","scp","preventive-controls"]'::jsonb, 'ai-draft', 'active', now(), now()),
    ('clf-c02-sec-103', 'aws-clf', 'Uma SCP usa a condition key aws:PrincipalOrgID para permitir s3:GetObject apenas quando a request vier de principals da própria Organization. Qual é o efeito prático dessa SCP?', '[{"id":"A","text":"Bloqueia downloads de buckets compartilhados com qualquer principal externo, mesmo cross-account dentro da própria Organization"},{"id":"B","text":"Permite o acesso somente quando o caller é um principal de uma conta dentro da mesma Organization, bloqueando contas externas"},{"id":"C","text":"Funciona apenas para usuários IAM, não para roles"},{"id":"D","text":"Substitui a necessidade de bucket policies"}]'::jsonb, 'B', '{"summary":"(a) aws:PrincipalOrgID compara o OrgID do caller; contas DENTRO da mesma Organization (mesmo cross-account) são permitidas. (b) Correto — é o mecanismo padrão de ''org boundary'' que evita exfiltração para contas fora da Organization. (c) Funciona para qualquer principal (user, role, root). (d) Não substitui — SCP limita ações no lado do caller; bucket policy controla acesso no recurso. Regra: aws:PrincipalOrgID na SCP é o cerco principal contra cross-Org data exfiltration."}'::jsonb, 'Security & Compliance', 'Security & Compliance', 'medium', 'scenario', '["organizations","scp","condition-keys","principalorgid"]'::jsonb, 'ai-draft', 'active', now(), now()),
    ('clf-c02-sec-104', 'aws-clf', 'Uma equipe quer impedir que qualquer principal — em todas as contas — crie recursos sem a tag obrigatória ''CostCenter''. Qual mecanismo do AWS Organizations entrega isso de forma preventiva?', '[{"id":"A","text":"Tag Policy aplicada à raiz"},{"id":"B","text":"SCP com condition aws:RequestTag/CostCenter e StringEquals/Null check"},{"id":"C","text":"AWS Config rule ''required-tags''"},{"id":"D","text":"IAM permissions boundary"}]'::jsonb, 'B', '{"summary":"(a) Tag Policies validam consistência/formato mas NÃO bloqueiam criação por padrão — apenas reportam. (b) SCP com Deny + condition aws:RequestTag/CostCenter is null bloqueia preventivamente CreateBucket, RunInstances, etc. sem a tag. (c) Config é detectivo (reporta drift após criação), não preventivo. (d) Boundary é por principal, não por Organization. Regra: Tag Policy = padronização; SCP = enforcement. Use ambos em conjunto para enforcement real de tagging."}'::jsonb, 'Security & Compliance', 'Security & Compliance', 'hard', 'best-practice', '["organizations","scp","tag-enforcement"]'::jsonb, 'ai-draft', 'active', now(), now()),
    ('clf-c02-sec-105', 'aws-clf', 'Em Control Tower, a equipe vê que os guardrails são divididos entre ''preventive'' e ''detective''. Qual é a diferença operacional principal entre eles?', '[{"id":"A","text":"Preventive usa Config rules; detective usa SCPs"},{"id":"B","text":"Preventive usa SCPs para bloquear ações antes de ocorrerem; detective usa Config rules para reportar não-conformidade depois"},{"id":"C","text":"Preventive só funciona em prod; detective em dev"},{"id":"D","text":"Não há diferença real — são sinônimos"}]'::jsonb, 'B', '{"summary":"(a) Inverso. (b) Correto: Control Tower expõe SCPs sob nome amigável como ''preventive guardrails'' (impedem a chamada) e Config rules como ''detective guardrails'' (detectam não-conformidade pós-fato). (c) Não há divisão por ambiente. (d) São conceitos distintos. Regra: defesa em profundidade — preventive bloqueia, detective audita o que escapou, remediation corrige."}'::jsonb, 'Security & Compliance', 'Security & Compliance', 'easy', 'recall', '["control-tower","guardrails","preventive-detective"]'::jsonb, 'ai-draft', 'active', now(), now()),
    ('clf-c02-sec-106', 'aws-clf', 'Uma empresa quer aplicar uma SCP que NEGUE qualquer ação se a request não vier de um IP corporativo (faixas conhecidas). Qual é o risco crítico desse padrão e como mitigar?', '[{"id":"A","text":"Risco: bloqueia chamadas legítimas de serviços AWS internos (Lambda, CloudFormation) que não saem do IP corporativo; mitigar com condition aws:ViaAWSService"},{"id":"B","text":"Nenhum risco — SCPs com IP-based denies são best practice universal"},{"id":"C","text":"Risco apenas de custo, sem impacto funcional"},{"id":"D","text":"Risco de lock-out do CloudFront — adicionar exception para *.cloudfront.net"}]'::jsonb, 'A', '{"summary":"(a) Correto. Serviços AWS (CloudFormation, Lambda, AutoScaling) chamam APIs em nome do principal a partir de IPs do plano de controle AWS — não do seu range corporativo. Usar aws:ViaAWSService = true como exceção, ou aws:SourceIp combinado com aws:CalledVia. (b) Errado, lockout iminente. (c) Impacto funcional severo. (d) CloudFront não é o problema; é qualquer serviço-proxy. Regra: IP-based SCPs precisam de exceções para serviços managed e console."}'::jsonb, 'Security & Compliance', 'Security & Compliance', 'hard', 'troubleshoot', '["organizations","scp","condition-keys","via-aws-service"]'::jsonb, 'ai-draft', 'active', now(), now()),
    ('clf-c02-sec-107', 'aws-clf', 'Em uma Organization recém-criada, ao habilitar ''all features'' (em vez de ''consolidated billing only''), o que muda em termos de capacidade de governança?', '[{"id":"A","text":"Nada — é apenas uma flag de billing"},{"id":"B","text":"Habilita SCPs, integração com serviços (Config, GuardDuty, Security Hub) e delegated administrator"},{"id":"C","text":"Cria automaticamente contas Audit e Log Archive"},{"id":"D","text":"Migra a Organization para GovCloud"}]'::jsonb, 'B', '{"summary":"(a) Há mudança funcional grande, não apenas billing. (b) ''All features'' destrava SCPs, trusted access para serviços (habilitando coleta org-wide), delegated administrator e RAM cross-account. (c) Quem cria essas contas é Control Tower, não ''all features'' sozinho. (d) Sem migração de partição. Regra: para qualquer guardrail real, ''all features'' é pré-requisito; ''consolidated billing only'' é modo legado."}'::jsonb, 'Security & Compliance', 'Security & Compliance', 'medium', 'recall', '["organizations","all-features"]'::jsonb, 'ai-draft', 'active', now(), now()),
    ('clf-c02-sec-108', 'aws-clf', 'A equipe quer delegar a administração do GuardDuty e Security Hub para uma conta específica de segurança, sem dar a ela acesso administrativo total à Organization. Qual mecanismo do AWS Organizations resolve isso?', '[{"id":"A","text":"Conceder AdministratorAccess à conta de segurança"},{"id":"B","text":"Delegated administrator para os serviços específicos (GuardDuty, Security Hub) via Organizations"},{"id":"C","text":"Mover a conta de segurança para a raiz da Organization"},{"id":"D","text":"Habilitar IAM Identity Center na conta de segurança"}]'::jsonb, 'B', '{"summary":"(a) Quebra least privilege e dá controle excessivo. (b) Correto — Organizations permite designar uma ''delegated administrator account'' por serviço (GuardDuty, Security Hub, Detective, Macie, Config). A conta delegada administra esse serviço org-wide sem precisar de poder geral. (c) Mover conta não muda autoridade. (d) Identity Center é para SSO, não delegação de serviço. Regra: ''delegated admin per service'' é o pattern moderno de separation of duties."}'::jsonb, 'Security & Compliance', 'Security & Compliance', 'medium', 'best-practice', '["organizations","delegated-administrator"]'::jsonb, 'ai-draft', 'active', now(), now()),
    ('clf-c02-sec-109', 'aws-clf', 'Em IAM Identity Center, a equipe cria um ''permission set'' chamado ''ReadOnlyProd'' e o atribui ao grupo ''Auditores'' nas contas-membro Prod. O que tecnicamente acontece quando um auditor assume esse acesso?', '[{"id":"A","text":"Identity Center cria um IAM user permanente em cada conta destino"},{"id":"B","text":"Identity Center provisiona automaticamente uma IAM role correspondente em cada conta destino e o usuário recebe credenciais temporárias via STS ao escolher a conta no portal"},{"id":"C","text":"O usuário usa a access key root da conta destino"},{"id":"D","text":"Não há provisionamento — Identity Center é só uma UI sobre IAM users"}]'::jsonb, 'B', '{"summary":"(a) Não cria IAM users — usa roles. (b) Correto. Permission set vira IAM role com prefixo ''AWSReservedSSO_<name>_<hash>'' provisionada em cada conta atribuída. O login no AWS access portal devolve credenciais temporárias via AssumeRoleWithSAML. (c) Nunca usa root. (d) Há provisionamento real de roles nas contas. Regra: permission sets são templates de roles materializadas por conta — auditável via CloudTrail como AssumeRole normal."}'::jsonb, 'Security & Compliance', 'Security & Compliance', 'medium', 'scenario', '["iam-identity-center","permission-sets","sts"]'::jsonb, 'ai-draft', 'active', now(), now()),
    ('clf-c02-sec-110', 'aws-clf', 'Uma empresa usa Okta como IdP corporativo. Quer que (i) usuários e grupos do Okta sejam refletidos em Identity Center automaticamente e (ii) login no portal AWS use credenciais do Okta. Quais protocolos cobrem cada requisito?', '[{"id":"A","text":"(i) SAML 2.0; (ii) SCIM"},{"id":"B","text":"(i) SCIM; (ii) SAML 2.0"},{"id":"C","text":"(i) OAuth2; (ii) OpenID Connect"},{"id":"D","text":"(i) LDAP; (ii) Kerberos"}]'::jsonb, 'B', '{"summary":"(a) Inverso. (b) Correto: SCIM (System for Cross-domain Identity Management) faz o provisionamento de usuários/grupos do Okta → Identity Center; SAML 2.0 é usado no fluxo de autenticação (assertion do IdP). (c) OIDC é alternativa para apps, não o padrão Identity Center. (d) LDAP/Kerberos são para AD on-prem, não SaaS IdP. Regra: SCIM = sync de diretório; SAML = auth de sessão."}'::jsonb, 'Security & Compliance', 'Security & Compliance', 'medium', 'recall', '["iam-identity-center","scim","saml"]'::jsonb, 'ai-draft', 'active', now(), now()),
    ('clf-c02-sec-111', 'aws-clf', 'A equipe quer dar acesso aos engenheiros tanto a contas AWS quanto a aplicações SaaS internas (Slack, Salesforce) pelo mesmo portal. Qual capacidade do IAM Identity Center atende?', '[{"id":"A","text":"Application assignments — Identity Center suporta apps SAML/OIDC custom além de contas AWS"},{"id":"B","text":"Apenas contas AWS são suportadas; SaaS precisa de outro produto"},{"id":"C","text":"Cognito User Pool federado"},{"id":"D","text":"AWS App Runner"}]'::jsonb, 'A', '{"summary":"(a) Correto — Identity Center suporta ''cloud applications'' (catálogo curado: Salesforce, ServiceNow, etc.) e ''customer managed applications'' via SAML 2.0/OIDC. Mesmo portal, SSO único. (b) Suporta sim. (c) Cognito é para identidade de end-users de app, público diferente. (d) App Runner é compute. Regra: Identity Center centraliza acesso humano para AWS + SaaS corporativo."}'::jsonb, 'Security & Compliance', 'Security & Compliance', 'easy', 'best-practice', '["iam-identity-center","saas-sso"]'::jsonb, 'ai-draft', 'active', now(), now()),
    ('clf-c02-sec-112', 'aws-clf', 'Após habilitar Identity Center na conta de management, a equipe tenta atribuir um permission set a uma conta-membro mas vê erro. A organização está com Identity Center na região us-east-1, e a engenheira tentou atribuir via console em sa-east-1. Qual a explicação mais provável?', '[{"id":"A","text":"Identity Center é global mas opera em uma região ''home''; toda administração precisa ocorrer nessa região home"},{"id":"B","text":"Permission sets só funcionam em us-east-1"},{"id":"C","text":"É bug — basta retry"},{"id":"D","text":"A conta-membro precisa estar na mesma região do Identity Center"}]'::jsonb, 'A', '{"summary":"(a) Correto. Identity Center tem uma região ''home'' escolhida na habilitação; administração (criar permission sets, atribuir contas) ocorre nessa região. Usuários logam de qualquer lugar; contas-membro podem ser em qualquer região. (b) Funcionam em qualquer região após provisionados. (c) Não é bug. (d) Recurso é regional na home, mas independente da região da workload. Regra: 1 Identity Center por Organization, 1 home region — escolha bem (não é trivial mudar)."}'::jsonb, 'Security & Compliance', 'Security & Compliance', 'medium', 'troubleshoot', '["iam-identity-center","home-region"]'::jsonb, 'ai-draft', 'active', now(), now()),
    ('clf-c02-sec-113', 'aws-clf', 'Em IAM Identity Center, qual configuração de duração de sessão e MFA é mais alinhada a least privilege para acesso a contas de produção?', '[{"id":"A","text":"Sessão de 12h sem MFA obrigatório"},{"id":"B","text":"Sessão curta (1h) com MFA obrigatório a cada autenticação e re-autenticação periódica"},{"id":"C","text":"Sessão permanente com cookies"},{"id":"D","text":"Sem sessão — usuário usa access keys long-lived"}]'::jsonb, 'B', '{"summary":"(a) Sessão longa amplia janela de comprometimento. (b) Sessão curta + MFA reduz blast radius de credenciais roubadas; Identity Center suporta MFA forçado e duração de sessão configurável por permission set (1h–12h). (c) Não existe. (d) Access keys long-lived são antipadrão. Regra: produção = MFA forçado + sessão curta + permission sets dedicados read-only por padrão, elevation para write sob demanda."}'::jsonb, 'Security & Compliance', 'Security & Compliance', 'easy', 'best-practice', '["iam-identity-center","session","mfa"]'::jsonb, 'ai-draft', 'active', now(), now()),
    ('clf-c02-sec-114', 'aws-clf', 'Em uma KMS customer-managed key, a equipe configurou key policy permitindo s3 e usuários X e Y. Mesmo assim, um usuário X recebe AccessDenied ao Decrypt. CloudTrail mostra que a chamada foi bloqueada por falta de permissão. A IAM policy do X tem kms:Decrypt em *. Qual a causa mais provável?', '[{"id":"A","text":"KMS exige que TANTO a key policy quanto a IAM policy permitam a ação; key policy precisa listar o principal explicitamente"},{"id":"B","text":"É necessário esperar 24h para a IAM policy propagar para o KMS"},{"id":"C","text":"kms:Decrypt em IAM policy é ignorado — apenas a key policy importa"},{"id":"D","text":"O usuário precisa ser root da conta"}]'::jsonb, 'A', '{"summary":"(a) Correto. KMS tem modelo único: por padrão, o principal precisa de Allow tanto na key policy QUANTO na IAM policy. Se a key policy só lista ''root'' da conta, então IAM policies da conta funcionam (key policy delega); mas se key policy lista principals explicitamente, somente esses passam. (b) Não há delay desse tipo. (c) Falso — ambos contam. (d) Não é root. Regra: chave KMS começa restrita; sempre revisar key policy + IAM policy juntas."}'::jsonb, 'Security & Compliance', 'Security & Compliance', 'hard', 'troubleshoot', '["kms","key-policy","iam-policy"]'::jsonb, 'ai-draft', 'active', now(), now()),
    ('clf-c02-sec-115', 'aws-clf', 'Uma equipe quer permitir que um serviço efêmero (Lambda) use uma chave KMS apenas durante a vida de uma operação específica, sem editar a key policy. Qual recurso do KMS atende?', '[{"id":"A","text":"KMS grant — concessão de uso temporário escopada por operação (encrypt, decrypt, etc.) e principal, sem alterar key policy"},{"id":"B","text":"Alias secundária"},{"id":"C","text":"Multi-region key"},{"id":"D","text":"Editar a IAM policy do Lambda apenas"}]'::jsonb, 'A', '{"summary":"(a) Correto. Grants permitem delegar uso temporário de uma KMS key com escopo fino (operações, encryption context, principal grantee) sem mexer na key policy — ideal para integrações de serviços AWS (RDS, EBS, Lambda) que provisionam grants automaticamente quando você ''autoriza'' a chave. (b) Alias é só nome. (c) Multi-region é replicação. (d) IAM policy sozinha não basta se a key policy não delega. Regra: grants = least privilege temporário programático."}'::jsonb, 'Security & Compliance', 'Security & Compliance', 'medium', 'recall', '["kms","grants"]'::jsonb, 'ai-draft', 'active', now(), now()),
    ('clf-c02-sec-116', 'aws-clf', 'Uma aplicação está em duas regiões (sa-east-1 e us-east-1) e precisa que objetos cifrados em uma região sejam descriptografados na outra sem latência de re-encrypt. Qual feature do KMS atende?', '[{"id":"A","text":"AWS KMS multi-region keys — réplicas com mesmo key ID/material e key policies independentes por região"},{"id":"B","text":"Aliases globais"},{"id":"C","text":"CloudHSM cluster cross-region"},{"id":"D","text":"Reencrypt automático via S3 Replication"}]'::jsonb, 'A', '{"summary":"(a) Correto. Multi-region keys (MRK) têm mesmo key ID em múltiplas regiões e compartilham material criptográfico; um objeto cifrado em sa-east-1 com a MRK pode ser decifrado em us-east-1 com a réplica MRK local — sem viagem cross-region. Cada réplica tem key policy/grants próprios. (b) Aliases são regionais. (c) CloudHSM é diferente; mais complexo, single-tenant. (d) S3 Replication com SSE-KMS faz re-encrypt (latência + custo extra). Regra: MRK = active-active cross-region."}'::jsonb, 'Security & Compliance', 'Security & Compliance', 'medium', 'best-practice', '["kms","multi-region-keys","drm"]'::jsonb, 'ai-draft', 'active', now(), now()),
    ('clf-c02-sec-117', 'aws-clf', 'A equipe de segurança quer que apenas operações de Decrypt em uma KMS key só sejam permitidas quando o cliente fornecer um ''encryption context'' específico (ex.: {''tenant'':''acme''}). Qual recurso do KMS atende?', '[{"id":"A","text":"Encryption context — pares chave/valor passados em Encrypt/Decrypt; aplicáveis como condition (kms:EncryptionContext) na key policy/grant"},{"id":"B","text":"Tags da chave"},{"id":"C","text":"Alias da chave"},{"id":"D","text":"Resource-based policy do S3"}]'::jsonb, 'A', '{"summary":"(a) Correto. Encryption context é AAD (additional authenticated data) — não cifra nada, mas é validado no decrypt e pode ser usado em condições (kms:EncryptionContext:tenant = ''acme''). Útil para multi-tenancy e auditoria contextual via CloudTrail. (b) Tags são para billing/organização. (c) Alias é nome amigável. (d) S3 não controla isso. Regra: encryption context = guardrail contextual em criptografia, sem custo de chave extra."}'::jsonb, 'Security & Compliance', 'Security & Compliance', 'hard', 'scenario', '["kms","encryption-context","multitenancy"]'::jsonb, 'ai-draft', 'active', now(), now()),
    ('clf-c02-sec-118', 'aws-clf', 'Uma empresa precisa que o material criptográfico das KMS keys seja gerado e armazenado em HSM próprio on-prem (nunca AWS), porém ainda quer usar KMS como interface unificada. Qual feature atende?', '[{"id":"A","text":"AWS KMS External Key Store (XKS) — KMS proxia operações criptográficas para HSM externo via XKS proxy"},{"id":"B","text":"KMS imported key material padrão"},{"id":"C","text":"Multi-region key"},{"id":"D","text":"CloudHSM cluster"}]'::jsonb, 'A', '{"summary":"(a) Correto. XKS (External Key Store) permite manter o material em HSM controlado pelo cliente fora da AWS; KMS atua como proxy invocando o XKS proxy do cliente. Atende soberania extrema, BYOK plus. (b) Imported key material armazena no KMS (não fora). (c) MRK é replicação interna AWS. (d) CloudHSM é HSM gerenciado dentro da AWS, não fora. Regra: XKS = controle absoluto fora da AWS; CloudHSM = HSM dentro da AWS; imported key = origem externa mas armazenado em KMS."}'::jsonb, 'Security & Compliance', 'Security & Compliance', 'hard', 'scenario', '["kms","xks","byok","sovereignty"]'::jsonb, 'ai-draft', 'active', now(), now()),
    ('clf-c02-sec-119', 'aws-clf', 'Em uma KMS customer-managed key, a equipe quer deletar a chave. Qual comportamento padrão do KMS protege contra delete acidental e qual o impacto operacional?', '[{"id":"A","text":"KMS exige janela de pending deletion entre 7 e 30 dias (default 30); durante o período a chave fica ''disabled'' e qualquer tentativa de uso falha"},{"id":"B","text":"Delete é imediato; só pode ser revertido via Support ticket"},{"id":"C","text":"Não há proteção; o cliente é responsável por backup"},{"id":"D","text":"Chaves nunca podem ser deletadas, só desabilitadas"}]'::jsonb, 'A', '{"summary":"(a) Correto. PendingDeletion entre 7–30 dias permite cancelamento. Durante a janela a chave está disabled — todas as operações criptográficas falham, então convém disable + monitorar CloudTrail por dias antes de schedular delete real. (b) Não é imediato. (c) Há proteção (a janela). (d) Podem ser deletadas após período. Regra: nunca delete sem antes desabilitar + monitorar ausência de uso por semanas — dados cifrados ficam irrecuperáveis após delete."}'::jsonb, 'Security & Compliance', 'Security & Compliance', 'medium', 'best-practice', '["kms","key-deletion","pending-window"]'::jsonb, 'ai-draft', 'active', now(), now()),
    ('clf-c02-sec-120', 'aws-clf', 'Qual é a diferença entre AWS managed key (alias prefixo aws/) e customer managed key (CMK) em termos de capacidade do cliente?', '[{"id":"A","text":"AWS managed key: cliente NÃO pode editar key policy nem rotation schedule; CMK: cliente controla key policy, rotation, grants, aliases e pode habilitar/desabilitar/deletar"},{"id":"B","text":"São iguais, só mudam o nome"},{"id":"C","text":"CMK é mais lento"},{"id":"D","text":"AWS managed key custa mais"}]'::jsonb, 'A', '{"summary":"(a) Correto. AWS managed (aws/s3, aws/rds, etc.) são geridas pela AWS — sem controle de policy ou rotation customizado (rotation automática anual fixa). CMKs permitem total controle: key policy, grants, multi-region, manual key material, rotation customizada, deletion. (b) Diferentes em controle e billing. (c) Performance equivalente. (d) AWS managed são frequentemente sem custo (no caso S3 SSE-S3 não usa KMS, mas SSE-KMS com aws/s3 isenta cost de KMS para algumas integrações; CMKs sempre custam $1/mês/chave). Regra: compliance e auditoria fina exigem CMK."}'::jsonb, 'Security & Compliance', 'Security & Compliance', 'easy', 'recall', '["kms","aws-managed","customer-managed"]'::jsonb, 'ai-draft', 'active', now(), now()),
    ('clf-c02-sec-121', 'aws-clf', 'Em IAM Identity Center, a equipe usa ABAC (attribute-based access control) baseado em atributos vindos do IdP (Okta) como ''Department=Finance''. Como isso funciona na prática para permitir acesso só a recursos com tag ''Department=Finance''?', '[{"id":"A","text":"Identity Center mapeia atributos do IdP para session tags da role provisionada; policy compara aws:PrincipalTag/Department com aws:ResourceTag/Department"},{"id":"B","text":"Identity Center cria IAM users por departamento"},{"id":"C","text":"ABAC só funciona com Cognito"},{"id":"D","text":"Precisa de Lambda authorizer no STS"}]'::jsonb, 'A', '{"summary":"(a) Correto. Identity Center propaga atributos do IdP como session tags via SAML/SCIM; policies usam Condition: StringEquals: ''aws:ResourceTag/Department'': ''${aws:PrincipalTag/Department}''. Escala — uma policy serve N departamentos. (b) ABAC evita explosão de users/roles. (c) Funciona com Identity Center, Cognito e federações em geral. (d) Não há Lambda authorizer no STS. Regra: ABAC = uma policy, N principals, baseada em tags; ideal para multi-tenancy."}'::jsonb, 'Security & Compliance', 'Security & Compliance', 'hard', 'scenario', '["iam-identity-center","abac","session-tags"]'::jsonb, 'ai-draft', 'active', now(), now()),
    ('clf-c02-sec-122', 'aws-clf', 'A equipe quer reduzir custo de KMS: tem 100 chaves CMK customer-managed mas grande parte é redundante. Qual otimização é segura?', '[{"id":"A","text":"Consolidar chaves por domínio funcional (ex.: ''prod-payments-kms''), schedulando delete das ociosas após auditoria de uso via CloudTrail"},{"id":"B","text":"Deletar todas imediatamente e recriar conforme necessário"},{"id":"C","text":"Mover todas para CloudHSM"},{"id":"D","text":"Desabilitar rotation para baratear"}]'::jsonb, 'A', '{"summary":"(a) Correto. CMKs custam $1/chave/mês + API calls; consolidar reduz custo mantendo separação por blast radius/compliance. Auditar via CloudTrail (kms:Encrypt, Decrypt) por 30-90 dias antes do delete e desabilitar primeiro. (b) Delete imediato sem auditoria torna dados cifrados irrecuperáveis. (c) CloudHSM é muito mais caro. (d) Rotation não muda preço; e desabilitar reduz segurança. Regra: otimize KMS com data-driven consolidation, nunca delete cego."}'::jsonb, 'Security & Compliance', 'Security & Compliance', 'medium', 'best-practice', '["kms","cost-optimization","consolidation"]'::jsonb, 'ai-draft', 'active', now(), now()),
    ('clf-c02-sec-123', 'aws-clf', 'Uma empresa de saúde quer construir pipeline HIPAA-ready em AWS. Além de assinar o BAA com a AWS, qual prática técnica é OBRIGATÓRIA para considerar a workload em conformidade?', '[{"id":"A","text":"Usar apenas serviços listados como HIPAA-eligible pela AWS e cifrar PHI em repouso e em trânsito"},{"id":"B","text":"Mover toda a workload para GovCloud"},{"id":"C","text":"Habilitar Shield Advanced"},{"id":"D","text":"Usar somente regiões US"}]'::jsonb, 'A', '{"summary":"(a) Correto. BAA cobre apenas serviços HIPAA-eligible (lista oficial publicada e atualizada pela AWS). PHI fora desses serviços ou sem encryption viola o BAA. (b) GovCloud é para US gov workloads, não exigência HIPAA. (c) Shield é DDoS, não relacionado. (d) HIPAA não exige região US — pode usar qualquer região onde o serviço é HIPAA-eligible. Regra: HIPAA on AWS = BAA + serviços elegíveis + encryption + logging + IAM least privilege; cliente faz a maior parte do trabalho."}'::jsonb, 'Security & Compliance', 'Security & Compliance', 'medium', 'scenario', '["compliance","hipaa","phi","baa"]'::jsonb, 'ai-draft', 'active', now(), now()),
    ('clf-c02-sec-124', 'aws-clf', 'Uma empresa processa cartões e quer reduzir o escopo PCI DSS. Qual abordagem arquitetural na AWS reduz dramaticamente o escopo de auditoria?', '[{"id":"A","text":"Tokenizar PAN (Primary Account Number) o mais cedo possível e isolar o ambiente CDE (cardholder data environment) em conta AWS dedicada"},{"id":"B","text":"Habilitar Macie em todos os buckets"},{"id":"C","text":"Usar GovCloud"},{"id":"D","text":"Habilitar Shield Standard"}]'::jsonb, 'A', '{"summary":"(a) Correto. Tokenização substitui PAN por token irreversível fora do CDE — drasticamente reduz onde dados sensíveis trafegam. Conta dedicada isola por blast radius, IAM, network. Padrão recomendado em PCI DSS scope reduction. (b) Macie ajuda descoberta de dados, não reduz escopo por si. (c) GovCloud não é exigência PCI. (d) Shield Standard é automático e não relacionado. Regra: PCI scope reduction = tokenize + segment + isolate (network + account)."}'::jsonb, 'Security & Compliance', 'Security & Compliance', 'hard', 'best-practice', '["compliance","pci-dss","tokenization","scope-reduction"]'::jsonb, 'ai-draft', 'active', now(), now()),
    ('clf-c02-sec-125', 'aws-clf', 'Um cidadão UE invoca o direito ao esquecimento (GDPR Art. 17). A empresa armazena dados pessoais em S3, DynamoDB e logs do CloudWatch. Qual abordagem garante deleção em todos os repositórios?', '[{"id":"A","text":"Inventariar todos os locais (data map), executar deletes verificáveis e revisar políticas de retenção/logs com data lifecycle e Object Lock configurado corretamente"},{"id":"B","text":"Mover a conta para uma região fora da UE"},{"id":"C","text":"Pedir à AWS que execute o delete via Support"},{"id":"D","text":"Marcar os registros como ''deleted'' sem removê-los"}]'::jsonb, 'A', '{"summary":"(a) Correto. GDPR right to be forgotten é responsabilidade do cliente (data controller); AWS só fornece a infra. Exige data discovery (Macie pode ajudar), processo de deleção em cada repositório, atenção a backups e logs, retenção justificada por base legal. (b) Não muda obrigação. (c) AWS não conhece os dados — não pode deletar registros aplicacionais. (d) ''Soft delete'' não atende GDPR. Regra: data residency + lifecycle + inventário = pré-requisito de GDPR compliance."}'::jsonb, 'Security & Compliance', 'Security & Compliance', 'medium', 'scenario', '["compliance","gdpr","right-to-be-forgotten"]'::jsonb, 'ai-draft', 'active', now(), now()),
    ('clf-c02-sec-126', 'aws-clf', 'Qual é a diferença essencial entre relatórios SOC 1, SOC 2 e SOC 3 disponíveis no AWS Artifact?', '[{"id":"A","text":"SOC 1 = controles financeiros (auditoria SOX); SOC 2 = segurança/disponibilidade/confidencialidade (detalhado, sob NDA); SOC 3 = versão pública/resumida do SOC 2"},{"id":"B","text":"SOC 1 é para startups; SOC 2 para enterprise; SOC 3 para governo"},{"id":"C","text":"Todos cobrem PCI"},{"id":"D","text":"São idênticos, mudam apenas idioma"}]'::jsonb, 'A', '{"summary":"(a) Correto. SOC 1 cobre controles relevantes a relatórios financeiros (importa para auditoria SOX do cliente). SOC 2 cobre os 5 trust principles (Security, Availability, Processing Integrity, Confidentiality, Privacy) com detalhe — NDA. SOC 3 é o SOC 2 público sumarizado, livre de NDA. (b) Não há corte por tamanho. (c) PCI é outro programa. (d) São documentos distintos. Regra: para auditoria de cliente cobrem aspectos diferentes; SOC 3 = marketing público; SOC 2 = relatório real (mais útil)."}'::jsonb, 'Security & Compliance', 'Security & Compliance', 'medium', 'recall', '["compliance","soc1","soc2","soc3","artifact"]'::jsonb, 'ai-draft', 'active', now(), now()),
    ('clf-c02-sec-127', 'aws-clf', 'Uma empresa brasileira quer atender LGPD na AWS. Qual é a interpretação correta da responsabilidade entre AWS (operador) e cliente (controlador) sob a LGPD?', '[{"id":"A","text":"Cliente é controlador (decide finalidade e meios do tratamento); AWS atua como operador (processa segundo instruções do controlador via Service Terms e DPA)"},{"id":"B","text":"AWS é controladora dos dados do cliente"},{"id":"C","text":"AWS atua como ANPD"},{"id":"D","text":"Não há LGPD em AWS"}]'::jsonb, 'A', '{"summary":"(a) Correto. Espelho do GDPR: cliente = controlador (responde a titulares, define base legal); AWS = operador (subordinada às instruções contratuais via Service Terms e DPA). Bases legais, transparência, atendimento a direitos = do cliente. (b) AWS não é controladora. (c) ANPD é órgão regulador, não papel da AWS. (d) AWS atende LGPD via DPA + certificações. Regra: cloud não move responsabilidade legal — só transfere parte das obrigações técnicas via shared responsibility."}'::jsonb, 'Security & Compliance', 'Security & Compliance', 'easy', 'scenario', '["compliance","lgpd","controller-processor"]'::jsonb, 'ai-draft', 'active', now(), now()),
    ('clf-c02-sec-128', 'aws-clf', 'Em uma VPC, a equipe quer permitir que EC2 em subnet privada chame DynamoDB diretamente, sem internet nem NAT, e quer aplicar policy para que só uma tabela específica seja acessível pelo endpoint. Qual configuração atende?', '[{"id":"A","text":"Gateway VPC endpoint para DynamoDB com endpoint policy restringindo Resource ao ARN da tabela"},{"id":"B","text":"Interface endpoint (PrivateLink) com security group"},{"id":"C","text":"Transit Gateway com route 0.0.0.0/0"},{"id":"D","text":"VPN site-to-site para a DynamoDB"}]'::jsonb, 'A', '{"summary":"(a) Correto. DynamoDB e S3 têm Gateway endpoints (não Interface) — são entradas em route table que direcionam tráfego para o serviço sem custo extra. Endpoint policy é um documento JSON IAM-like aplicado ao endpoint que limita ações/recursos. (b) DynamoDB não usa Interface endpoint; é Gateway. (c) Transit Gateway é para VPC↔VPC/on-prem. (d) VPN é over-the-internet ou DX. Regra: DynamoDB/S3 = Gateway endpoint (grátis); demais = Interface endpoint (PrivateLink, $/hora + por GB)."}'::jsonb, 'Security & Compliance', 'Security & Compliance', 'medium', 'scenario', '["network","vpc-endpoint","gateway-endpoint","dynamodb"]'::jsonb, 'ai-draft', 'active', now(), now()),
    ('clf-c02-sec-129', 'aws-clf', 'Uma equipe expõe um serviço interno em uma VPC para clientes de outras contas/VPCs sem peering nem internet. Qual é a forma idiomática usando PrivateLink?', '[{"id":"A","text":"Criar VPC Endpoint Service (com NLB) na VPC provider; consumidores criam Interface Endpoint para esse serviço"},{"id":"B","text":"Compartilhar a subnet via RAM"},{"id":"C","text":"Criar VPC peering com cada cliente"},{"id":"D","text":"Publicar a API em CloudFront"}]'::jsonb, 'A', '{"summary":"(a) Correto. PrivateLink fluxo: provider cria NLB (ou GWLB) + VPC Endpoint Service; consumidores criam Interface Endpoint, que aparece como ENI privada na VPC consumidora apontando para o serviço. Cross-account, sem expor à internet, sem rotas complexas. (b) RAM compartilha subnet mas exige decisão arquitetural diferente. (c) Peering polui CIDRs e não escala. (d) CloudFront é público. Regra: PrivateLink = SaaS interno cross-VPC/account, modelo 1-way."}'::jsonb, 'Security & Compliance', 'Security & Compliance', 'hard', 'best-practice', '["network","privatelink","endpoint-service","nlb"]'::jsonb, 'ai-draft', 'active', now(), now()),
    ('clf-c02-sec-130', 'aws-clf', 'A equipe quer criar uma WAF rule customizada que bloqueie requisições POST em /login com mais de 10 tentativas por IP em 5 minutos. Qual rule type do AWS WAF atende diretamente?', '[{"id":"A","text":"Rate-based rule com escopo de path /login e action Block"},{"id":"B","text":"Managed rule group da AWS"},{"id":"C","text":"Bot Control"},{"id":"D","text":"Geo match"}]'::jsonb, 'A', '{"summary":"(a) Correto. Rate-based rules do WAF contam requisições por IP em janelas (a partir de 1 min até 1 dia) e disparam quando passa o threshold; pode escopear por path/method via statements aninhados. Ideal para brute force em login. (b) Managed rules são patterns pré-feitos (SQLi, XSS) — não fazem rate. (c) Bot Control detecta bots, custo extra. (d) Geo match filtra país, não rate. Regra: rate-based = anti brute force, anti scraping; combine com managed rules para defesa em camadas."}'::jsonb, 'Security & Compliance', 'Security & Compliance', 'medium', 'scenario', '["network","waf","rate-based-rule","brute-force"]'::jsonb, 'ai-draft', 'active', now(), now()),
    ('clf-c02-sec-131', 'aws-clf', 'Uma WAF Web ACL tem 3 regras com priorities 100, 200, 300, sendo a 200 um ''Block'' e a 300 um ''Allow''. Uma requisição combina com a regra 200 e também com a 300. O que acontece?', '[{"id":"A","text":"WAF avalia regras em ordem de priority crescente; a primeira regra que casa com action terminating (Allow/Block) decide — neste caso, Block (priority 200)"},{"id":"B","text":"Allow sempre vence"},{"id":"C","text":"WAF avalia todas e deny ganha"},{"id":"D","text":"É indeterminado"}]'::jsonb, 'A', '{"summary":"(a) Correto. WAF processa em ordem de priority numérica crescente; Allow e Block são terminating actions (param a avaliação). Count não é terminating. Como 200 < 300, Block 200 é atingido primeiro e decide. (b) Não há precedência por action. (c) Não é deny-wins; é ordem-de-priority. (d) Determinístico. Regra: para depurar WAF olhe rule priority e use Count antes de aplicar Block (modo dry-run)."}'::jsonb, 'Security & Compliance', 'Security & Compliance', 'medium', 'troubleshoot', '["network","waf","rule-priority"]'::jsonb, 'ai-draft', 'active', now(), now()),
    ('clf-c02-sec-132', 'aws-clf', 'Uma equipe quer inspeção profunda de tráfego entre VPCs com IPS/IDS e regras Suricata customizadas. Comparativamente, qual é a diferença entre AWS Network Firewall e Security Groups/NACLs?', '[{"id":"A","text":"Network Firewall é stateful L3-L7 com Suricata-compatible rules e IPS/IDS; SG/NACL operam L3/L4 sem deep packet inspection nem signatures"},{"id":"B","text":"São idênticos, mudam apenas o preço"},{"id":"C","text":"Network Firewall é só para CloudFront"},{"id":"D","text":"SG já faz IPS"}]'::jsonb, 'A', '{"summary":"(a) Correto. Network Firewall é appliance managed L3-L7 — suporta Suricata rules, IPS/IDS, domain filtering, TLS SNI inspection. SG/NACL filtram apenas por 5-tuple (IP, port, proto). Network Firewall vive em subnet própria de inspection VPC, normalmente em hub-and-spoke com Transit Gateway. (b) Categorias diferentes. (c) Não é só CloudFront. (d) SG não faz IPS. Regra: SG/NACL = guarda de porta; Network Firewall = sentinela profunda."}'::jsonb, 'Security & Compliance', 'Security & Compliance', 'medium', 'recall', '["network","network-firewall","ips","suricata"]'::jsonb, 'ai-draft', 'active', now(), now()),
    ('clf-c02-sec-133', 'aws-clf', 'Em um Interface VPC Endpoint para SQS, a equipe quer impedir que esse endpoint seja usado para acessar filas de outra Organization. Qual mecanismo aplica?', '[{"id":"A","text":"Endpoint policy com condition aws:PrincipalOrgID = OrgID local; chamadas para filas de fora da Org são bloqueadas no endpoint"},{"id":"B","text":"Security Group do endpoint"},{"id":"C","text":"NACL da subnet"},{"id":"D","text":"WAF"}]'::jsonb, 'A', '{"summary":"(a) Correto. Endpoint policies são policies IAM-like aplicadas no VPC endpoint que limitam o que passa por ele — independentes de IAM policies do principal. Usar aws:PrincipalOrgID restringe ao perímetro organizacional. (b) SG controla rede (IP/port), não identidade. (c) NACL idem. (d) WAF é para HTTP em ALB/CloudFront. Regra: endpoint policy = data perimeter no nível do túnel privado — combinar com SCP aws:ResourceOrgID para defesa em profundidade."}'::jsonb, 'Security & Compliance', 'Security & Compliance', 'hard', 'scenario', '["network","endpoint-policy","data-perimeter"]'::jsonb, 'ai-draft', 'active', now(), now()),
    ('clf-c02-sec-134', 'aws-clf', 'Uma equipe usa CloudFront com WAF. Quer bloquear requests de países específicos. Qual é a opção mais eficiente — bloquear no WAF (geo match rule) ou no CloudFront (geo restriction)?', '[{"id":"A","text":"Ambos funcionam; CloudFront geo restriction bloqueia mais cedo (sem custo de WAF), mas WAF geo match é necessário se quiser combinar geo com outras condições (path, header, rate)"},{"id":"B","text":"Apenas WAF funciona com CloudFront"},{"id":"C","text":"Geo restriction não existe no CloudFront"},{"id":"D","text":"Bloqueio geo é ilegal"}]'::jsonb, 'A', '{"summary":"(a) Correto. CloudFront geo restriction é binário (allowlist/denylist por país) e gratuito — bom para banimentos globais simples. WAF geo match permite combinações (geo + path + rate + header) e logging detalhado, com custo por WCU. (b) Falso. (c) Existe. (d) Pode ter implicações legais mas é técnica permitida. Regra: bloqueio simples = CloudFront; bloqueio condicional/contextual = WAF."}'::jsonb, 'Security & Compliance', 'Security & Compliance', 'easy', 'best-practice', '["network","waf","cloudfront","geo-blocking"]'::jsonb, 'ai-draft', 'active', now(), now()),
    ('clf-c02-sec-135', 'aws-clf', 'Em uma arquitetura hub-and-spoke com Transit Gateway, a equipe quer rotear todo o tráfego inter-VPC por uma ''inspection VPC'' com AWS Network Firewall antes do destino. Qual configuração no TGW garante isso?', '[{"id":"A","text":"TGW route tables com static routes direcionando spokes para a inspection VPC e a inspection VPC como única que tem rota para os demais spokes"},{"id":"B","text":"VPC peering full mesh"},{"id":"C","text":"Security Group cross-VPC"},{"id":"D","text":"PrivateLink full mesh"}]'::jsonb, 'A', '{"summary":"(a) Correto. TGW suporta múltiplas route tables; pattern ''centralized inspection'' faz spokes apontar default route 0.0.0.0/0 (ou peer-cidrs) para a inspection VPC, que após inspeção devolve ao TGW com rota para o destino real (via outra TGW route table separada). (b) Peering bypassa firewall. (c) SGs não roteiam. (d) PrivateLink não inspeciona. Regra: TGW + multiple route tables = service insertion para firewall central."}'::jsonb, 'Security & Compliance', 'Security & Compliance', 'hard', 'scenario', '["network","transit-gateway","inspection-vpc"]'::jsonb, 'ai-draft', 'active', now(), now()),
    ('clf-c02-sec-136', 'aws-clf', 'GuardDuty emitiu um finding ''UnauthorizedAccess:IAMUser/MaliciousIPCaller.Custom'' indicando que uma access key está sendo usada de um IP em threat intel customizado. A equipe quer que esse finding dispare automaticamente revogação da access key. Qual fluxo é idiomático?', '[{"id":"A","text":"EventBridge rule capturando o finding do GuardDuty → Lambda que chama iam:UpdateAccessKey (Inactive) ou SSM runbook"},{"id":"B","text":"GuardDuty desativa a chave automaticamente"},{"id":"C","text":"CloudTrail revoga após 5 falhas"},{"id":"D","text":"Macie processa o finding"}]'::jsonb, 'A', '{"summary":"(a) Correto. GuardDuty publica findings em EventBridge; rule filtra por type e dispara remediação automatizada — Lambda, SSM Automation runbook ou Step Functions. Auto-remediation é o pattern security-as-code central da AWS. (b) GuardDuty é detection only — não muda nada. (c) CloudTrail é log only. (d) Macie é descoberta de PII, não IAM. Regra: GuardDuty + EventBridge + Lambda/SSM = ciclo detect→respond."}'::jsonb, 'Security & Compliance', 'Security & Compliance', 'medium', 'best-practice', '["threat-detection","guardduty","eventbridge","auto-remediation"]'::jsonb, 'ai-draft', 'active', now(), now()),
    ('clf-c02-sec-137', 'aws-clf', 'Security Hub agrega findings de GuardDuty, Inspector, Macie, IAM Access Analyzer e checks de compliance contra standards. Qual é o benefício específico de habilitar ''cross-region aggregation''?', '[{"id":"A","text":"Concentra findings de todas as regiões habilitadas em uma região agregadora, evitando que a equipe SOC monitore múltiplas dashboards regionais"},{"id":"B","text":"Reduz o custo do GuardDuty"},{"id":"C","text":"Habilita auto-remediation universal"},{"id":"D","text":"Cria backup dos findings em outra região"}]'::jsonb, 'A', '{"summary":"(a) Correto. Security Hub é regional por padrão; cross-region aggregation define uma região agregadora que recebe findings de todas as linked regions, dando visão única ao SOC. Combinado com delegated admin Org-wide, gera ''pane of glass'' multi-conta multi-região. (b) Não muda preço base. (c) Auto-remediation depende de EventBridge + Lambda. (d) Não é DR. Regra: aggregation = visibilidade; não é DR nem custo-reduction."}'::jsonb, 'Security & Compliance', 'Security & Compliance', 'medium', 'recall', '["threat-detection","security-hub","cross-region-aggregation"]'::jsonb, 'ai-draft', 'active', now(), now()),
    ('clf-c02-sec-138', 'aws-clf', 'Após GuardDuty + Security Hub mostrarem múltiplos findings ligados a uma role IAM suspeita, a equipe quer entender em uma timeline o que essa role fez nos últimos 30 dias (logins, AssumeRole, chamadas de API, IPs, VPCs envolvidas). Qual serviço foi feito exatamente para essa investigação correlacionada?', '[{"id":"A","text":"Amazon Detective — constrói grafo de behavior usando CloudTrail, VPC Flow Logs, GuardDuty findings e DNS logs"},{"id":"B","text":"Athena com queries manuais sobre CloudTrail"},{"id":"C","text":"Macie"},{"id":"D","text":"Inspector"}]'::jsonb, 'A', '{"summary":"(a) Correto. Detective ingere CloudTrail mgmt, VPC Flow, GuardDuty findings e DNS query logs continuamente, monta grafo de entidades (roles, instâncias, IPs) e oferece timeline ad-hoc — sem ETL. Pivot rápido por entidade. (b) Athena funciona mas exige ETL e conhecimento de schema; Detective é purpose-built. (c) Macie é descoberta de PII em S3. (d) Inspector é scan de CVEs. Regra: GuardDuty detecta; Security Hub centraliza; Detective investiga."}'::jsonb, 'Security & Compliance', 'Security & Compliance', 'medium', 'scenario', '["threat-detection","detective","investigation"]'::jsonb, 'ai-draft', 'active', now(), now()),
    ('clf-c02-sec-139', 'aws-clf', 'Uma equipe quer suprimir automaticamente um finding específico do Security Hub (ex.: ''EC2.6 - VPC flow logs should be enabled'' em VPCs sandbox curtas) sem desligar a regra para o resto. Qual mecanismo atende?', '[{"id":"A","text":"Suppression rule no Security Hub com filtro por tag/account/finding-id; findings que casam ficam com workflow status SUPPRESSED automaticamente"},{"id":"B","text":"Desabilitar a control do standard inteiro"},{"id":"C","text":"Apagar a VPC sandbox"},{"id":"D","text":"Editar manualmente o status a cada novo finding"}]'::jsonb, 'A', '{"summary":"(a) Correto. Automation rules + insight filters em Security Hub permitem regras de supressão escopadas; mantém visibilidade onde importa, reduz ruído nos contextos esperados. (b) Desativar control inteira perde sinal global. (c) Não escala. (d) Manual = inviável. Regra: triage Security Hub começa por automation rules para reduzir noise sem perder cobertura."}'::jsonb, 'Security & Compliance', 'Security & Compliance', 'easy', 'best-practice', '["threat-detection","security-hub","suppression"]'::jsonb, 'ai-draft', 'active', now(), now()),
    ('clf-c02-sec-140', 'aws-clf', 'Para responder a um incidente de comprometimento em produção, a equipe precisa preservar evidências sem alertar o atacante e sem desligar a instância EC2 (perderia memória). Qual sequência é recomendada pelo AWS Security IR playbook?', '[{"id":"A","text":"Isolar a instância via Security Group de quarentena, snapshot do EBS, captura de memória via SSM, então analisar offline"},{"id":"B","text":"Stop imediato da instância"},{"id":"C","text":"Terminate + delete do volume"},{"id":"D","text":"Reboot para limpar artefatos"}]'::jsonb, 'A', '{"summary":"(a) Correto. Quarentena via SG sem regras de saída evita alerta ao atacante mas mantém visibilidade; EBS snapshot preserva disco; memory capture via SSM document preserva volátil para forense. (b) Stop limpa memória. (c) Terminate destrói evidência. (d) Reboot apaga estado e alerta atacante. Regra: ordem forense — isolar → snapshot disco → memória → analisar; nunca destruir evidência primeiro."}'::jsonb, 'Security & Compliance', 'Security & Compliance', 'medium', 'best-practice', '["incident-response","forensics","evidence"]'::jsonb, 'ai-draft', 'active', now(), now()),
    ('clf-c02-sec-141', 'aws-clf', 'Uma equipe quer rodar SQL ad-hoc sobre 5 anos de eventos do CloudTrail consolidados de 20 contas, com retenção longa e custo otimizado para queries esporádicas. Qual serviço atende sem ETL?', '[{"id":"A","text":"CloudTrail Lake — managed data lake do CloudTrail com SQL queries (event data store), retenção até 10 anos e organização-wide"},{"id":"B","text":"CloudWatch Logs Insights"},{"id":"C","text":"S3 Select"},{"id":"D","text":"Athena com Glue crawler manual"}]'::jsonb, 'A', '{"summary":"(a) Correto. CloudTrail Lake é purpose-built para audit queries — event data store consolida múltiplas contas/regiões, SQL nativo, retenção até 10 anos, sem manter Athena/Glue. (b) Insights é para application logs, não optimizado para CloudTrail. (c) S3 Select é por objeto. (d) Athena funciona mas exige ETL/crawler/schema próprio. Regra: CloudTrail Lake = audit data lake managed; menos custo operacional para SQL frequente sobre CloudTrail."}'::jsonb, 'Security & Compliance', 'Security & Compliance', 'medium', 'scenario', '["logging","cloudtrail-lake","audit"]'::jsonb, 'ai-draft', 'active', now(), now()),
    ('clf-c02-sec-142', 'aws-clf', 'Após habilitar CloudTrail Insights, a equipe percebe que recebeu alerta de ''unusual activity'' para uma região nunca usada com volume alto de RunInstances. Como CloudTrail Insights chega a essa conclusão tecnicamente?', '[{"id":"A","text":"Insights analisa baseline histórico (7 dias) de chamadas de API write e emite InsightEvent quando o volume desvia significativamente; útil para detectar cryptojacking, abuso pós-comprometimento e drift operacional"},{"id":"B","text":"Insights faz threat intel match contra IPs ruins"},{"id":"C","text":"Insights usa GuardDuty internamente"},{"id":"D","text":"Insights compara contra outras contas da Organization"}]'::jsonb, 'A', '{"summary":"(a) Correto. CloudTrail Insights compara volume de chamadas write APIs com uma baseline de 7 dias por conta/região; quando desvia (ex.: pico de RunInstances) gera InsightEvent. Cobertura focada em mgmt events write. (b) Não usa threat intel — usa baseline estatística. (c) Independente do GuardDuty. (d) Compara contra a própria conta, não outras. Regra: Insights = anomaly detection em volume de APIs, complementar ao GuardDuty (que olha behavior + threat intel)."}'::jsonb, 'Security & Compliance', 'Security & Compliance', 'medium', 'scenario', '["logging","cloudtrail-insights","anomaly-detection"]'::jsonb, 'ai-draft', 'active', now(), now()),
    ('clf-c02-sec-143', 'aws-clf', 'Em uma Organization com 50 contas, a equipe quer centralizar logs do CloudTrail em um único bucket S3 na conta de log archive, com replicação cross-region para DR e proteção contra delete por root. Qual configuração é adequada?', '[{"id":"A","text":"Organization Trail com S3 destination na conta log archive, bucket com Object Lock (Compliance mode), SSE-KMS com CMK da conta log e replication para outra região"},{"id":"B","text":"Trail por conta com destino na própria conta"},{"id":"C","text":"Habilitar apenas CloudWatch Logs em cada conta"},{"id":"D","text":"GuardDuty replica logs automaticamente"}]'::jsonb, 'A', '{"summary":"(a) Correto. Organization Trail é criado na conta de management e captura eventos de todas as contas-membro, entregando a um único bucket. Object Lock Compliance mode impede delete mesmo por root durante retenção. KMS adiciona controle de acesso à chave; replication garante DR. (b) Trail por conta = fragmentação. (c) CloudWatch Logs é runtime, não audit central. (d) GuardDuty não replica logs. Regra: centralized audit = Org Trail + Object Lock + KMS + replication."}'::jsonb, 'Security & Compliance', 'Security & Compliance', 'hard', 'best-practice', '["logging","cloudtrail","organization-trail","object-lock"]'::jsonb, 'ai-draft', 'active', now(), now()),
    ('clf-c02-sec-144', 'aws-clf', 'AWS Config tem o recurso ''aggregator''. Em qual cenário ele é essencial?', '[{"id":"A","text":"Quando se quer ver compliance e configuração de recursos de múltiplas contas e regiões em um único dashboard agregado, sem trocar de console"},{"id":"B","text":"Para reduzir o custo do Config"},{"id":"C","text":"Para habilitar remediation automatic em todas as contas"},{"id":"D","text":"Para criar conformance packs"}]'::jsonb, 'A', '{"summary":"(a) Correto. Config aggregator coleta dados de configuração e compliance de múltiplas accounts/regions em uma conta agregadora (Org-wide com 1 clique). Permite queries SQL Advanced em todo o inventário (ex.: ''todas as EC2s sem encryption em todas as contas''). (b) Não muda preço base. (c) Remediation é por conta, via SSM. (d) Conformance packs são independentes. Regra: aggregator = inventory + compliance Org-wide; complemento natural ao Org Trail centralizado."}'::jsonb, 'Security & Compliance', 'Security & Compliance', 'easy', 'recall', '["logging","config","aggregator"]'::jsonb, 'ai-draft', 'active', now(), now()),
    ('clf-c02-sec-145', 'aws-clf', 'A equipe quer aplicar 100 Config rules opinativas (CIS, PCI, NIST) em todas as 20 contas de uma Organization sem replicar manualmente. Qual recurso atende?', '[{"id":"A","text":"Conformance pack deployado via Config Organization rules — empacota rules + remediation actions em template aplicado às contas-membro"},{"id":"B","text":"Lambda em cada conta criando rules via API"},{"id":"C","text":"SCP no Organizations"},{"id":"D","text":"CloudFormation StackSet sem Config"}]'::jsonb, 'A', '{"summary":"(a) Correto. Conformance pack = template YAML com Config rules + remediation; deploy Org-wide via Config Organization rules ou StackSet. AWS publica packs prontos para CIS, PCI-DSS, NIST 800-53, HIPAA. (b) Reinventa a roda. (c) SCP é preventive, não detective; categoria diferente. (d) StackSet sem Config rules não cria as próprias rules. Regra: Config rules em escala = conformance packs; pode-se rolar pack ''CIS'' em segundos para toda Org."}'::jsonb, 'Security & Compliance', 'Security & Compliance', 'medium', 'best-practice', '["logging","config","conformance-pack"]'::jsonb, 'ai-draft', 'active', now(), now()),
    ('clf-c02-sec-146', 'aws-clf', 'Em CloudWatch Logs, a equipe precisa entregar logs cross-account para uma conta de log archive na mesma Organization. Qual é o mecanismo nativo?', '[{"id":"A","text":"Subscription filter + destination cross-account; logs streamados para Kinesis Data Streams/Firehose ou Lambda na conta destino"},{"id":"B","text":"CloudTrail"},{"id":"C","text":"S3 replication"},{"id":"D","text":"AWS Backup"}]'::jsonb, 'A', '{"summary":"(a) Correto. Subscription filters em log groups encaminham eventos em tempo real para destinations (Kinesis, Firehose, Lambda) — suportam cross-account via destination policy. Pattern para centralização real-time de application logs. (b) CloudTrail é para AWS API events. (c) S3 replication é de objetos, não logs vivos. (d) Backup é para snapshots. Regra: para logs centralizados real-time use subscription filters; para audit Org-wide use Org Trail."}'::jsonb, 'Security & Compliance', 'Security & Compliance', 'hard', 'scenario', '["logging","cloudwatch-logs","cross-account","subscription-filter"]'::jsonb, 'ai-draft', 'active', now(), now()),
    ('clf-c02-sec-147', 'aws-clf', 'Uma empresa quer permitir login no console AWS via conta de Active Directory on-prem (federation) com SAML assertion para roles específicas. Qual API STS é invocada para trocar a SAML assertion por credenciais AWS temporárias?', '[{"id":"A","text":"sts:AssumeRoleWithSAML"},{"id":"B","text":"sts:AssumeRoleWithWebIdentity"},{"id":"C","text":"sts:GetSessionToken"},{"id":"D","text":"sts:GetFederationToken"}]'::jsonb, 'A', '{"summary":"(a) Correto. AssumeRoleWithSAML troca uma SAML 2.0 assertion (vinda de IdP como AD FS, Okta, Azure AD) por credenciais STS temporárias, especificando a IAM role a assumir. (b) WithWebIdentity é para OIDC (Google, Cognito, OIDC providers — ex.: GitHub Actions). (c) GetSessionToken só funciona para IAM users adicionando MFA, não federation. (d) GetFederationToken é para identity broker custom, não SAML. Regra: SAML → AssumeRoleWithSAML; OIDC → AssumeRoleWithWebIdentity."}'::jsonb, 'Security & Compliance', 'Security & Compliance', 'medium', 'recall', '["federation","sts","saml","assumerolewithsaml"]'::jsonb, 'ai-draft', 'active', now(), now()),
    ('clf-c02-sec-148', 'aws-clf', 'Uma empresa quer permitir que pipelines em GitHub Actions assumam role na AWS sem long-lived access keys nos secrets. Qual configuração no IAM é necessária?', '[{"id":"A","text":"Configurar GitHub Actions como OIDC identity provider no IAM e criar role com trust policy que valida o OIDC token (claims sub, repo, branch)"},{"id":"B","text":"Criar IAM user dedicado e armazenar access keys no GitHub"},{"id":"C","text":"Habilitar Identity Center"},{"id":"D","text":"Usar Cognito User Pool"}]'::jsonb, 'A', '{"summary":"(a) Correto. GitHub Actions tem OIDC provider (token.actions.githubusercontent.com); registra-se no IAM como Identity Provider, cria-se role com trust policy condicionando aws:RequestTag e token.actions.githubusercontent.com:sub a um repo/branch específico. AssumeRoleWithWebIdentity → credenciais temporárias. (b) Long-lived keys são anti-padrão. (c) Identity Center é para humanos. (d) Cognito é para end-users de apps. Regra: CI/CD em AWS = OIDC short-lived; sem keys persistentes."}'::jsonb, 'Security & Compliance', 'Security & Compliance', 'medium', 'best-practice', '["federation","oidc","github-actions","ci-cd"]'::jsonb, 'ai-draft', 'active', now(), now()),
    ('clf-c02-sec-149', 'aws-clf', 'Uma role IAM tem trust policy que permite federation via OIDC do EKS (IRSA — IAM Roles for Service Accounts). Qual claim do JWT é validado para garantir que apenas um pod específico em um namespace específico assuma a role?', '[{"id":"A","text":"system:serviceaccount:<namespace>:<sa-name> validado em condition StringEquals para a claim sub"},{"id":"B","text":"O nome do node EC2"},{"id":"C","text":"O ARN do cluster"},{"id":"D","text":"MFA TOTP"}]'::jsonb, 'A', '{"summary":"(a) Correto. IRSA emite JWT cujo ''sub'' claim é ''system:serviceaccount:<ns>:<sa>''; a trust policy da role valida essa condition contra o ARN do OIDC provider do cluster. Garante least privilege fino — pod com SA específica em namespace específico. (b) Node-level não é granular. (c) Cluster ARN é parte do provider URL mas não é a granularidade fina. (d) MFA não se aplica a workload. Regra: IRSA = granular IAM por pod via OIDC; substitui IAM em node (kiam/kube2iam legados)."}'::jsonb, 'Security & Compliance', 'Security & Compliance', 'hard', 'scenario', '["federation","eks","irsa","oidc"]'::jsonb, 'ai-draft', 'active', now(), now()),
    ('clf-c02-sec-150', 'aws-clf', 'Em uma trust policy IAM que permite federation via SAML, qual é a finalidade do elemento Condition com SAML:aud e SAML:iss?', '[{"id":"A","text":"Garantir que a SAML assertion foi emitida pelo IdP esperado (iss) e destinada à AWS (aud), prevenindo replay de assertions de outros IdPs"},{"id":"B","text":"Definir o tempo de vida da sessão"},{"id":"C","text":"Especificar a região AWS permitida"},{"id":"D","text":"Definir o tamanho das credenciais"}]'::jsonb, 'A', '{"summary":"(a) Correto. SAML:iss valida o issuer (URL do IdP); SAML:aud valida o audience (deve ser https://signin.aws.amazon.com/saml ou conta-específico). Sem isso, assertion de outro IdP poderia ser apresentada. (b) Duração é DurationSeconds em AssumeRoleWithSAML. (c) Região não tem relação. (d) Tamanho é parâmetro fixo. Regra: trust policy SAML sempre valida iss + aud; principio ''verify the source''."}'::jsonb, 'Security & Compliance', 'Security & Compliance', 'hard', 'best-practice', '["federation","saml","trust-policy"]'::jsonb, 'ai-draft', 'active', now(), now()),
    ('clf-c02-sec-151', 'aws-clf', 'Uma empresa SaaS multi-tenant quer dar a cada cliente acesso a recursos AWS específicos sem criar IAM role por tenant. Qual padrão de identity federation atende escala?', '[{"id":"A","text":"ABAC com session tags via AssumeRole — tag tenant_id é propagada para a sessão e policies comparam ${aws:PrincipalTag/tenant_id} com ${aws:ResourceTag/tenant_id}"},{"id":"B","text":"Criar 1 role por tenant"},{"id":"C","text":"Compartilhar mesma role para todos sem segregação"},{"id":"D","text":"Não há solução nativa"}]'::jsonb, 'A', '{"summary":"(a) Correto. ABAC com session tags escala para milhares de tenants: aplicação chama AssumeRole com Tags=[{Key:''tenant_id'', Value:''acme''}], a sessão herda a tag, policies comparam tag do principal com tag do recurso. 1 role + N tenants. (b) Não escala. (c) Quebra isolamento. (d) ABAC é nativo. Regra: ABAC = scaling pattern para multi-tenancy em AWS; tag everything coerentemente."}'::jsonb, 'Security & Compliance', 'Security & Compliance', 'hard', 'scenario', '["federation","abac","session-tags","multitenancy"]'::jsonb, 'ai-draft', 'active', now(), now()),
    ('clf-c02-sec-152', 'aws-clf', 'Uma empresa precisa que workloads regulados pela ANPD (LGPD) sejam executadas exclusivamente em região sa-east-1 (São Paulo). Qual combinação de controles preventivos garante data residency?', '[{"id":"A","text":"SCP com aws:RequestedRegion = sa-east-1 + bucket policies S3 condicionando s3:LocationConstraint + Config rule para detectar drift"},{"id":"B","text":"Apenas habilitar sa-east-1 e desabilitar console em outras regiões"},{"id":"C","text":"GovCloud"},{"id":"D","text":"Outposts em sa-east-1"}]'::jsonb, 'A', '{"summary":"(a) Correto. Defesa em camadas: SCP impede chamadas a serviços fora da região (preventive Org-wide); bucket policies impedem criação em outras regiões; Config detecta recursos que escaparam. (b) Não é possível ''desabilitar'' regiões — pode bloquear via STS region opt-out mas não cobre tudo. (c) GovCloud é US-only. (d) Outposts é para latência hybrid, não residência sozinho. Regra: residency = SCP + policy de recurso + monitoring; layered approach."}'::jsonb, 'Security & Compliance', 'Security & Compliance', 'medium', 'best-practice', '["data-residency","scp","lgpd","regions"]'::jsonb, 'ai-draft', 'active', now(), now()),
    ('clf-c02-sec-153', 'aws-clf', 'AWS European Sovereign Cloud é uma região soberana anunciada para clientes europeus. Qual é a diferença operacional principal em relação a regiões ''standard'' da AWS?', '[{"id":"A","text":"Operada por entidade legal europeia com pessoal residente na UE, isolada do plano de controle global da AWS; dados, metadados e operações permanecem dentro da UE"},{"id":"B","text":"É apenas uma região com nome diferente, mesmo controle global"},{"id":"C","text":"Só hospeda Lambda"},{"id":"D","text":"Não permite uso de S3"}]'::jsonb, 'A', '{"summary":"(a) Correto. Sovereign Cloud (assim como GovCloud para US gov) é fisicamente e operacionalmente isolada do resto da AWS — entidade legal local, staff local, controle de acesso restrito. Atende requisitos de soberania mais rigorosos que regiões padrão. (b) Há diferença operacional substancial. (c) Catálogo de serviços é amplo, não restrito. (d) S3 está presente. Regra: sovereign region = isolamento legal + operacional, não só geográfico."}'::jsonb, 'Security & Compliance', 'Security & Compliance', 'easy', 'recall', '["data-residency","sovereign-cloud","europe"]'::jsonb, 'ai-draft', 'active', now(), now()),
    ('clf-c02-sec-154', 'aws-clf', 'Uma empresa usa Outposts (rack AWS instalado no datacenter próprio) para data residency local. Quem é responsável pela segurança física do rack Outposts e quem pelos dados nele armazenados?', '[{"id":"A","text":"Cliente é responsável pela segurança física do site onde o rack está; AWS gerencia o rack remotamente; dados em repouso/trânsito seguem shared responsibility model habitual"},{"id":"B","text":"AWS envia pessoal para 24x7 onsite"},{"id":"C","text":"Cliente gerencia o hypervisor manualmente"},{"id":"D","text":"Outposts é apenas software, sem hardware físico"}]'::jsonb, 'A', '{"summary":"(a) Correto. Outposts coloca hardware AWS no DC do cliente; AWS faz delivery, setup inicial e management remoto via control plane; cliente é responsável por segurança física do site (controle de acesso, energia, climatização). Dados seguem shared responsibility como em regiões standard. (b) AWS não tem pessoal onsite contínuo. (c) Não há acesso ao hypervisor. (d) É hardware físico. Regra: Outposts = AWS managed compute no seu DC; site security = cliente."}'::jsonb, 'Security & Compliance', 'Security & Compliance', 'medium', 'scenario', '["data-residency","outposts","shared-responsibility"]'::jsonb, 'ai-draft', 'active', now(), now()),
    ('clf-c02-sec-155', 'aws-clf', 'Uma empresa quer garantir que SnowFamily devices usados para transferir dados sensíveis para a AWS estejam encriptados em todo o ciclo. Como funciona a proteção criptográfica em Snowball Edge?', '[{"id":"A","text":"Dados em repouso são cifrados com AES-256 com chave gerenciada pelo KMS da conta; chaves nunca persistem no device, são reaplicadas a cada uso e zeradas no retorno"},{"id":"B","text":"Cliente precisa instalar TrueCrypt manualmente"},{"id":"C","text":"Snowball usa TLS apenas, sem encryption em repouso"},{"id":"D","text":"Encryption é opcional"}]'::jsonb, 'A', '{"summary":"(a) Correto. Snowball Edge cifra dados com AES-256 em repouso; chave KMS provisionada pela job, baixada efêmera para o device, zerada quando volta para AWS. Tampering = device inutilizável. (b) Não exige software extra. (c) Encryption é ponta-a-ponta. (d) Não é opcional. Regra: Snow* devices = encryption obrigatória + tamper-resistance + chain of custody."}'::jsonb, 'Security & Compliance', 'Security & Compliance', 'easy', 'recall', '["data-residency","snowball","encryption-at-rest"]'::jsonb, 'ai-draft', 'active', now(), now()),
    ('clf-c02-sec-156', 'aws-clf', 'Inspector v2 escaneia EC2, ECR e Lambda continuamente. Qual a diferença operacional em relação ao Inspector classic v1?', '[{"id":"A","text":"v2 é continuous (não exige scheduling de assessments), Org-integrated via delegated admin, e suporta ECR/Lambda; v1 era on-demand e só EC2"},{"id":"B","text":"v2 é mais lento"},{"id":"C","text":"v2 só roda em EC2"},{"id":"D","text":"v1 e v2 são iguais"}]'::jsonb, 'A', '{"summary":"(a) Correto. Inspector v2 é always-on, automático, Org-wide via delegated admin, e adicionou ECR (CVE em imagens) + Lambda code/dep scan. v1 dependia de scheduling agentes em EC2 e cobria só CIS benchmarks/CVE de EC2. (b) Performance similar/melhor. (c) Cobre ECR/Lambda. (d) São arquiteturas diferentes. Regra: para certificação CLF-C02 e prática moderna, Inspector = v2 (continuous, multi-resource, Org-aware)."}'::jsonb, 'Security & Compliance', 'Security & Compliance', 'easy', 'recall', '["threat-detection","inspector","v2"]'::jsonb, 'ai-draft', 'active', now(), now()),
    ('clf-c02-sec-157', 'aws-clf', 'Após GuardDuty detectar ''Backdoor:EC2/C&CActivity.B'', a equipe quer correlacionar com eventos S3 anômalos (exfiltration). Qual feature do GuardDuty entrega detecção específica em data plane S3?', '[{"id":"A","text":"GuardDuty S3 Protection (analisa S3 data events e CloudTrail mgmt para padrões anômalos como exfiltration, anonymous access)"},{"id":"B","text":"S3 Object Lock"},{"id":"C","text":"S3 Replication monitoring"},{"id":"D","text":"Athena"}]'::jsonb, 'A', '{"summary":"(a) Correto. GuardDuty S3 Protection analisa S3 data events (GetObject, PutObject) e mgmt events para detectar exfiltration patterns, acesso de IP malicioso, anonymous access, mudanças em bucket policy. Custo extra ativável. (b) Object Lock é WORM, não detecção. (c) Replication não monitora threats. (d) Athena exige queries manuais. Regra: GuardDuty modular — S3 Protection, EKS Audit, Malware, RDS Login — habilitar conforme o blast radius da conta."}'::jsonb, 'Security & Compliance', 'Security & Compliance', 'medium', 'scenario', '["threat-detection","guardduty","s3-protection"]'::jsonb, 'ai-draft', 'active', now(), now()),
    ('clf-c02-sec-158', 'aws-clf', 'Compliance — Qual recurso AWS substitui a necessidade de o cliente assinar NDAs ad-hoc para baixar relatórios de auditoria SOC, ISO e PCI?', '[{"id":"A","text":"AWS Artifact — portal self-service onde cliente aceita NDA online e baixa relatórios sob NDA AWS-customer"},{"id":"B","text":"AWS Trust Center"},{"id":"C","text":"AWS Health Dashboard"},{"id":"D","text":"AWS Marketplace"}]'::jsonb, 'A', '{"summary":"(a) Correto. Artifact é o portal central de compliance documents — agreements (BAA, GDPR DPA) e reports (SOC 1/2/3, ISO 27001, PCI AoC). Cliente aceita NDA digitalmente; download imediato. (b) Trust Center é portal público de marketing/posture; sem reports sob NDA. (c) Health é status de serviços. (d) Marketplace é catálogo de SaaS. Regra: Artifact = papelada de compliance; Trust Center = transparência pública."}'::jsonb, 'Security & Compliance', 'Security & Compliance', 'easy', 'recall', '["compliance","artifact","audit"]'::jsonb, 'ai-draft', 'active', now(), now()),
    ('clf-c02-sec-159', 'aws-clf', 'Uma equipe quer construir runbook automatizado de IR: ao detectar comprometimento, isolar EC2, snapshot, criar ticket no Jira e notificar Slack. Qual combinação de serviços AWS é apropriada?', '[{"id":"A","text":"EventBridge captura o finding → Step Functions orquestra: SSM Automation isola+snapshot → Lambda chama Jira API → SNS publica para Slack"},{"id":"B","text":"GuardDuty executa o runbook diretamente"},{"id":"C","text":"Security Hub aciona EC2 nativamente"},{"id":"D","text":"CloudTrail dispara o playbook"}]'::jsonb, 'A', '{"summary":"(a) Correto. Pattern canônico de SOAR na AWS: EventBridge (trigger) → Step Functions (orquestração com retries/branches) → SSM Automation (actions com runbook reutilizável) → Lambda (integrações externas) → SNS/EventBridge (notifications). Versionável como IaC. (b) GuardDuty não executa actions. (c) Security Hub agrega/dispara via EventBridge, não direto. (d) CloudTrail só registra. Regra: IR automation = EventBridge + Step Functions + SSM + Lambda; manter como código."}'::jsonb, 'Security & Compliance', 'Security & Compliance', 'hard', 'best-practice', '["incident-response","automation","step-functions","ssm"]'::jsonb, 'ai-draft', 'active', now(), now()),
    ('clf-c02-sec-160', 'aws-clf', 'Uma empresa quer reduzir custo de logs do CloudWatch que crescem 50GB/mês. Logs precisam ficar disponíveis para query rápida só por 7 dias; depois disso, basta archival para auditoria. Qual estratégia atende?', '[{"id":"A","text":"Log group com retention de 7 dias + subscription filter para Firehose → S3 com Glacier lifecycle; queries esporádicas via Athena"},{"id":"B","text":"Manter retention infinito em CloudWatch Logs"},{"id":"C","text":"Mover todos os logs para DynamoDB"},{"id":"D","text":"Desabilitar logs após 7 dias manualmente"}]'::jsonb, 'A', '{"summary":"(a) Correto. CloudWatch Logs caro para retenção longa; arquitetura típica: retention curta no log group para queries rápidas (Logs Insights), Firehose stream contínuo para S3 com Glacier lifecycle (centavos por GB), Athena para queries históricas raras. Redução de custo de ordens de magnitude. (b) CW Logs ilimitado é antieconômico. (c) DynamoDB é caro e errado para logs. (d) Manual = inviável. Regra: tier hot/warm/cold — CW Logs hot, S3 Standard warm, Glacier cold."}'::jsonb, 'Security & Compliance', 'Security & Compliance', 'medium', 'best-practice', '["logging","cloudwatch-logs","cost-optimization","s3-glacier"]'::jsonb, 'ai-draft', 'active', now(), now()),
    ('clf-c02-tech-001', 'aws-clf', 'Uma equipe precisa escolher um tipo de instância EC2 para um workload de processamento de imagens com alto uso de CPU mas pouca memória. Qual família de instância é a mais adequada?', '[{"id":"A","text":"Família M (uso geral, balanceada)"},{"id":"B","text":"Família R (memory-optimized)"},{"id":"C","text":"Família C (compute-optimized)"},{"id":"D","text":"Família T (burstable performance)"}]'::jsonb, 'C', '{"summary":"Família C (Compute-Optimized) tem maior razão vCPU/preço, ideal para CPU-bound workloads como processamento de mídia, batch e HPC leve.","whyCorrect":"Família C (Compute-Optimized) tem maior razão vCPU/preço, ideal para CPU-bound workloads como processamento de mídia, batch e HPC leve.","whyWrong":{"A":"M é balanceada [extra: desperdiça custo quando não usa toda a RAM]","B":"R é memory-optimized para in-memory DB","D":"T é burstable, sofre throttling em uso sustentado."},"keyConcept":"Regra: matchear família ao gargalo dominante (C=CPU, R=RAM, M=balanceada, T=picos curtos).","tutorSeeds":["Pode explicar com mais detalhe: Regra: matchear família ao gargalo dominante (C=CPU, R=RAM, M=balanceada, T=picos curtos)?","Quais cenários reais aplicam Regra: matchear família ao gargalo dominante (C=CPU, R=RAM, M=balanceada, T=picos curtos)?","Como CPU-bound se compara com alternativas?"]}'::jsonb, 'Cloud Technology & Services', 'Cloud Technology & Services', 'easy', 'scenario', '["ec2","instance-types","compute"]'::jsonb, 'ai-draft', 'active', now(), now()),
    ('clf-c02-tech-002', 'aws-clf', 'Um time provisiona instâncias EC2 t3.medium para uma API com tráfego constante de CPU em torno de 40%. Após algumas horas, a latência aumenta significativamente. O que mais provavelmente está acontecendo?', '[{"id":"A","text":"A AMI está corrompida e precisa ser recriada"},{"id":"B","text":"Os CPU credits da instância burstable se esgotaram e ela está em throttling"},{"id":"C","text":"Falta de Elastic IP causando perda de pacotes"},{"id":"D","text":"EBS gp2 atingiu IOPS máximas"}]'::jsonb, 'B', '{"summary":"Instâncias T (burstable) acumulam CPU credits quando ociosas e gastam quando passam do baseline; uso sustentado acima do baseline (~20% para t3.medium em modo standard) drena credits e leva a throttling.","whyCorrect":"Instâncias T (burstable) acumulam CPU credits quando ociosas e gastam quando passam do baseline; uso sustentado acima do baseline (~20% para t3.medium em modo standard) drena credits e leva a throttling.","whyWrong":{"A":"AMI corrompida normalmente impede o boot","C":"Elastic IP não afeta latência interna","D":"gp2 atinge IOPS máximas em workloads de I/O pesado em disco, mas o sintoma descrito (CPU 40% constante levando a latência) é claro caso de drenagem de CPU credits da família T (burstable). Throttling de EBS aparece como VolumeQueueLength alta, não como latência de aplicação CPU-bound. Esta opção seria correta se a queixa fosse ''I/O wait alto''."},"keyConcept":"Regra: workloads com CPU sustentada > 20% → trocar para família M ou C, ou habilitar T3 Unlimited.","tutorSeeds":["Pode explicar com mais detalhe: Regra: workloads com CPU sustentada > 20% → trocar para família M ou C, ou habilitar T3 Unlimited?","Quais cenários reais aplicam Regra: workloads com CPU sustentada > 20% → trocar para família M ou C, ou habilitar T3 Unlimited?","Como CPU se compara com alternativas?"]}'::jsonb, 'Cloud Technology & Services', 'Cloud Technology & Services', 'medium', 'troubleshoot', '["ec2","burstable","performance"]'::jsonb, 'ai-draft', 'active', now(), now()),
    ('clf-c02-tech-003', 'aws-clf', 'Uma empresa quer pré-instalar uma stack customizada (SO patched + agents internos + libs) e bootar novas instâncias EC2 rapidamente com essa configuração. Qual recurso AWS endereça esse caso?', '[{"id":"A","text":"Launch Template apenas"},{"id":"B","text":"Custom AMI (Amazon Machine Image)"},{"id":"C","text":"User data script que instala tudo no boot"},{"id":"D","text":"Systems Manager State Manager"}]'::jsonb, 'B', '{"summary":"AMI captura snapshot do volume root + metadata — novas instâncias bootam em segundos já com a stack pronta, sem reinstalar nada.","whyCorrect":"AMI captura snapshot do volume root + metadata — novas instâncias bootam em segundos já com a stack pronta, sem reinstalar nada.","whyWrong":{"A":"Launch Template referencia uma AMI mas não a substitui","C":"user data instala no boot (lento e propenso a falhas)","D":"SSM State Manager garante configuração após o boot, não acelera."},"keyConcept":"Regra: imutável + rápido = AMI; mutável + dinâmico = user data/SSM.","tutorSeeds":["Pode explicar com mais detalhe: Regra: imutável + rápido = AMI; mutável + dinâmico = user data/SSM?","Quais cenários reais aplicam Regra: imutável + rápido = AMI; mutável + dinâmico = user data/SSM?","Como AMI se compara com alternativas?"]}'::jsonb, 'Cloud Technology & Services', 'Cloud Technology & Services', 'easy', 'best-practice', '["ec2","ami","automation"]'::jsonb, 'ai-draft', 'active', now(), now()),
    ('clf-c02-tech-004', 'aws-clf', 'Uma equipe precisa de storage efêmero de altíssima performance (NVMe local) para cache de um job de ML que pode ser recriado a qualquer momento. Qual opção atende?', '[{"id":"A","text":"EBS gp3 attachado à instância"},{"id":"B","text":"EBS io2 Block Express"},{"id":"C","text":"Instance Store (storage local efêmero)"},{"id":"D","text":"EFS montado via NFS"}]'::jsonb, 'C', '{"summary":"Instance Store é storage físico ligado ao host — latência mínima e IOPS altíssimas — mas o dado é perdido se a instância para/falha.","whyCorrect":"Instance Store é storage físico ligado ao host — latência mínima e IOPS altíssimas — mas o dado é perdido se a instância para/falha. Ideal para cache/scratch onde a recriação é trivial.","whyWrong":{"B":"gp3/io2 são block storage em rede (resiliente, lento comparado a NVMe local)","A":"EBS gp3 é persistente e baseado em rede (network-attached) — tem latência maior que NVMe local e custa por GB+IOPS provisionados. Para cache de ML que pode ser recriado, EBS é overkill: paga por persistência que não importa e perde performance vs Instance Store. EBS seria correto para dados que devem sobreviver a stop/terminate.","D":"EFS é file system NFS compartilhado e elástico — latência ainda maior que EBS (acessa via rede TCP), throughput variável e custo por GB armazenado. Adequado para acesso compartilhado entre múltiplas instâncias, não para cache local de altíssima performance. EFS seria a resposta se múltiplas instâncias precisassem ler/escrever o mesmo cache."},"keyConcept":"Regra: ephemeral + speed = Instance Store; persistent = EBS; shared = EFS.","tutorSeeds":["Pode explicar com mais detalhe: Regra: ephemeral + speed = Instance Store; persistent = EBS; shared = EFS?","Quais cenários reais aplicam Regra: ephemeral + speed = Instance Store; persistent = EBS; shared = EFS?","Como IOPS se compara com alternativas?"]}'::jsonb, 'Cloud Technology & Services', 'Cloud Technology & Services', 'medium', 'scenario', '["ec2","instance-store","ebs"]'::jsonb, 'ai-draft', 'active', now(), now()),
    ('clf-c02-tech-005', 'aws-clf', 'Uma aplicação web tem tráfego previsível durante o dia e zero à noite. A equipe quer ajustar automaticamente o número de instâncias EC2. Qual serviço deve ser usado?', '[{"id":"A","text":"AWS Auto Scaling Group (ASG) com scaling policies"},{"id":"B","text":"Elastic Load Balancer com health checks"},{"id":"C","text":"AWS Lambda invocando a EC2 API"},{"id":"D","text":"Aumentar instance type via vertical scaling"}]'::jsonb, 'A', '{"summary":"ASG mantém capacidade desejada, faz scaling horizontal por métricas (CPU, request count, scheduled), substitui instâncias unhealthy e integra com ELB.","whyCorrect":"ASG mantém capacidade desejada, faz scaling horizontal por métricas (CPU, request count, scheduled), substitui instâncias unhealthy e integra com ELB.","whyWrong":{"C":"Lambda custom funciona mas reinventa a roda","D":"vertical scaling exige stop/start e não automatiza.","B":"ELB faz LOAD BALANCING (distribui tráfego entre targets healthy) e health checks — não decide quando criar/destruir instâncias. ELB sozinho não escala capacidade; precisa do ASG para isso. ELB seria correto para ''distribuir requisições entre as instâncias existentes'', mas o requisito é ''ajustar AUTOMATICAMENTE o NÚMERO de instâncias''."},"keyConcept":"Regra: capacidade dinâmica horizontal = ASG; distribuição = ELB; ambos juntos = padrão recomendado.","tutorSeeds":["Pode explicar com mais detalhe: Regra: capacidade dinâmica horizontal = ASG; distribuição = ELB; ambos juntos = padrão recomendado?","Quais cenários reais aplicam Regra: capacidade dinâmica horizontal = ASG; distribuição = ELB; ambos juntos = padrão recomendado?","Como ASG se compara com alternativas?"]}'::jsonb, 'Cloud Technology & Services', 'Cloud Technology & Services', 'easy', 'scenario', '["ec2","auto-scaling","elasticity"]'::jsonb, 'ai-draft', 'active', now(), now()),
    ('clf-c02-tech-006', 'aws-clf', 'Uma aplicação HTTP precisa rotear tráfego para diferentes target groups baseado no path da URL (/api/* vs /static/*). Qual tipo de Elastic Load Balancer atende?', '[{"id":"A","text":"Network Load Balancer (NLB)"},{"id":"B","text":"Application Load Balancer (ALB)"},{"id":"C","text":"Gateway Load Balancer (GWLB)"},{"id":"D","text":"Classic Load Balancer (CLB)"}]'::jsonb, 'B', '{"summary":"ALB opera na camada 7 (HTTP/HTTPS) e suporta routing avançado por path, host, header e query string.","whyCorrect":"ALB opera na camada 7 (HTTP/HTTPS) e suporta routing avançado por path, host, header e query string.","whyWrong":{"C":"GWLB é para appliances de inspeção","A":"Network Load Balancer opera em camada 4 (TCP/UDP) — não inspeciona conteúdo HTTP nem faz routing por path/host/header. NLB encaminha conexões TCP/UDP por target group baseado em listener (porta), não por URL path. NLB seria correto para ''load balancing TCP de altíssima performance'' ou ''IP estático''.","D":"Classic Load Balancer é a geração legada do ELB — suporta L4/L7 básico mas NÃO faz path-based routing nativo (apenas listener por porta). AWS recomenda migrar de CLB para ALB/NLB. CLB seria ''legado'' não-recomendado mesmo para casos simples atuais."},"keyConcept":"Regra: L7 + roteamento por conteúdo = ALB; L4 + ultra performance = NLB; appliance insertion = GWLB.","tutorSeeds":["Pode explicar com mais detalhe: Regra: L7 + roteamento por conteúdo = ALB; L4 + ultra performance = NLB; appliance insertion = GWLB?","Quais cenários reais aplicam Regra: L7 + roteamento por conteúdo = ALB; L4 + ultra performance = NLB; appliance insertion = GWLB?","Como ALB se compara com alternativas?"]}'::jsonb, 'Cloud Technology & Services', 'Cloud Technology & Services', 'easy', 'scenario', '["elb","alb","networking"]'::jsonb, 'ai-draft', 'active', now(), now()),
    ('clf-c02-tech-007', 'aws-clf', 'Um serviço de gaming precisa de latência ultrabaixa via TCP e IP estático para registro em firewalls de clientes. Qual ELB é o mais adequado?', '[{"id":"A","text":"Application Load Balancer (ALB)"},{"id":"B","text":"Network Load Balancer (NLB)"},{"id":"C","text":"Gateway Load Balancer (GWLB)"},{"id":"D","text":"Classic Load Balancer (CLB)"}]'::jsonb, 'B', '{"summary":"NLB opera em L4 (TCP/UDP/TLS), entrega latência de milissegundos baixos e oferece Elastic IPs estáticos por AZ — perfeito para clientes que precisam allowlist de IPs.","whyCorrect":"NLB opera em L4 (TCP/UDP/TLS), entrega latência de milissegundos baixos e oferece Elastic IPs estáticos por AZ — perfeito para clientes que precisam allowlist de IPs.","whyWrong":{"C":"GWLB é para tráfego de inspeção","A":"ALB opera em L7 (HTTP/HTTPS) com latência adicional pelo TLS termination e processamento de headers — tipicamente 20-50ms a mais que NLB. ALB também NÃO oferece IPs estáticos por AZ (usa DNS A records que mudam). Para gaming TCP com latência crítica e IP allowlisting, NLB é o construto correto.","D":"Classic Load Balancer é geração legada e não recomendada para novos workloads. Mesmo se usado, latência e performance ficam aquém do NLB moderno; não tem IPs estáticos garantidos. AWS recomenda NLB para TCP de alta performance, deprecando CLB para casos novos."},"keyConcept":"Regra: TCP + IP estático + alta performance = NLB.","tutorSeeds":["Pode explicar com mais detalhe: Regra: TCP + IP estático + alta performance = NLB?","Quais cenários reais aplicam Regra: TCP + IP estático + alta performance = NLB?","Como NLB se compara com alternativas?"]}'::jsonb, 'Cloud Technology & Services', 'Cloud Technology & Services', 'medium', 'scenario', '["elb","nlb","networking"]'::jsonb, 'ai-draft', 'active', now(), now()),
    ('clf-c02-tech-008', 'aws-clf', 'Uma empresa de segurança quer inserir um appliance virtual de firewall de terceiros no caminho do tráfego que passa por sua VPC. Qual serviço facilita essa inserção transparente?', '[{"id":"A","text":"Application Load Balancer com regras avançadas"},{"id":"B","text":"Network Load Balancer com TLS termination"},{"id":"C","text":"Gateway Load Balancer (GWLB)"},{"id":"D","text":"AWS WAF"}]'::jsonb, 'C', '{"summary":"GWLB usa o protocolo GENEVE para encaminhar tráfego transparentemente a appliances virtuais (IDS/IPS/firewall) com escala automática e healthchecks.","whyCorrect":"GWLB usa o protocolo GENEVE para encaminhar tráfego transparentemente a appliances virtuais (IDS/IPS/firewall) com escala automática e healthchecks.","whyWrong":{"A":"ALB inspeciona HTTP em L7 e roteia para targets — não tem mecanismo de inserir um appliance virtual transparentemente no path do tráfego de uma VPC. ALB faria sentido para ''distribuir tráfego HTTP entre múltiplos servidores web'', não para passar todo tráfego de uma subnet por um firewall third-party.","B":"NLB opera em L4 distribuindo conexões TCP/UDP — não tem mecanismo de transparent traffic insertion via GENEVE para appliances de segurança. NLB seria correto para load balancing de um firewall, mas não para inserir o firewall em todo o path de uma VPC de forma transparente.","D":"AWS WAF é firewall L7 managed pela AWS para proteger aplicações web em ALB/CloudFront/API Gateway contra OWASP Top 10 — NÃO é mecanismo para inserir appliance de terceiros. WAF tem regras nativas; GWLB encaminha tráfego a aparências externas (Palo Alto, Fortinet, Check Point, etc.)."},"keyConcept":"Regra: inserir appliances de terceiros no path = GWLB.","tutorSeeds":["Pode explicar com mais detalhe: Regra: inserir appliances de terceiros no path = GWLB?","Quais cenários reais aplicam Regra: inserir appliances de terceiros no path = GWLB?","Como GWLB se compara com alternativas?"]}'::jsonb, 'Cloud Technology & Services', 'Cloud Technology & Services', 'hard', 'scenario', '["elb","gwlb","security"]'::jsonb, 'ai-draft', 'active', now(), now()),
    ('clf-c02-tech-009', 'aws-clf', 'Sobre EC2 Auto Scaling Groups, qual afirmação é VERDADEIRA?', '[{"id":"A","text":"ASGs garantem que o número de instâncias seja exatamente o Desired Capacity, substituindo instâncias unhealthy"},{"id":"B","text":"ASGs fazem somente scaling vertical (mudam o tipo da instância)"},{"id":"C","text":"ASGs requerem obrigatoriamente um ALB associado"},{"id":"D","text":"ASGs só funcionam dentro de uma única AZ"}]'::jsonb, 'A', '{"summary":"ASG mantém Desired Capacity; instâncias que falham healthcheck (EC2 ou ELB) são terminadas e substituídas.","whyCorrect":"ASG mantém Desired Capacity; instâncias que falham healthcheck (EC2 ou ELB) são terminadas e substituídas. Suporta scaling horizontal automático em múltiplas AZs para HA.","whyWrong":{"B":"ASG é horizontal (mais/menos instâncias), não vertical","C":"ASG NÃO requer ALB obrigatoriamente — pode operar sozinho, com NLB, ou com qualquer combinação. ELB é integração comum mas opcional. ASG funciona com qualquer arquitetura, incluindo workers SQS sem balanceador algum.","D":"ASG SUPORTA múltiplas AZs — na verdade, é a configuração recomendada para HA. ASG distribui instâncias entre AZs configuradas e mantém balanceamento. Limitar a uma AZ é antipattern. ASG cross-AZ é base do design ''resilient by default''."},"keyConcept":"Regra: ASG = self-healing + horizontal scaling + multi-AZ.","tutorSeeds":["Pode explicar com mais detalhe: Regra: ASG = self-healing + horizontal scaling + multi-AZ?","Quais cenários reais aplicam Regra: ASG = self-healing + horizontal scaling + multi-AZ?","Como ASG se compara com alternativas?"]}'::jsonb, 'Cloud Technology & Services', 'Cloud Technology & Services', 'easy', 'recall', '["ec2","auto-scaling","high-availability"]'::jsonb, 'ai-draft', 'active', now(), now()),
    ('clf-c02-tech-010', 'aws-clf', 'Uma empresa quer pagar menos por instâncias EC2 aceitando interrupções com aviso de 2 minutos para workloads tolerantes a falha (batch, CI runners). Qual opção de compra escolher?', '[{"id":"A","text":"On-Demand"},{"id":"B","text":"Reserved Instances de 3 anos"},{"id":"C","text":"Spot Instances"},{"id":"D","text":"Dedicated Hosts"}]'::jsonb, 'C', '{"summary":"Spot oferece até 90% de desconto sobre On-Demand mas pode ser interrompido com aviso de 2 min — ideal para batch, fault-tolerant, CI, render farms.","whyCorrect":"Spot oferece até 90% de desconto sobre On-Demand mas pode ser interrompido com aviso de 2 min — ideal para batch, fault-tolerant, CI, render farms.","whyWrong":{"A":"On-Demand é flexível e caro","B":"RIs comprometem 1/3 anos por desconto sem interrupção","D":"Dedicated Host é para compliance/licensing."},"keyConcept":"Regra: workload interruptível = Spot.","tutorSeeds":["Pode explicar com mais detalhe: Regra: workload interruptível = Spot?","Quais cenários reais aplicam Regra: workload interruptível = Spot?","Como CI se compara com alternativas?"]}'::jsonb, 'Cloud Technology & Services', 'Cloud Technology & Services', 'easy', 'best-practice', '["ec2","spot","cost-optimization"]'::jsonb, 'ai-draft', 'active', now(), now()),
    ('clf-c02-tech-011', 'aws-clf', 'Um time precisa manter um snapshot de uma instância EC2 antes de aplicar updates arriscados, para poder restaurar em minutos se algo der errado. Qual abordagem é correta?', '[{"id":"A","text":"Snapshot do volume EBS, armazenado em S3 automaticamente"},{"id":"B","text":"Backup manual copiando arquivos via SCP"},{"id":"C","text":"Export para Instance Store"},{"id":"D","text":"Replicar para outra Region via VPC peering"}]'::jsonb, 'A', '{"summary":"EBS Snapshots são incrementais, armazenados internamente em S3 gerenciado pela AWS, e permitem restaurar volume idêntico em minutos (ou criar AMI a partir deles).","whyCorrect":"EBS Snapshots são incrementais, armazenados internamente em S3 gerenciado pela AWS, e permitem restaurar volume idêntico em minutos (ou criar AMI a partir deles).","whyWrong":{"B":"SCP é manual e lento VPC peering é network, não backup.","C":"Instance Store é efêmero (você perderia o backup)","D":"VPC peering conecta VPCs para tráfego de rede privado — não é mecanismo de backup. Replicar ''via VPC peering'' não faz sentido conceitualmente; replicação é via snapshot copy entre Regions (sem peering envolvido). Esta opção mistura conceitos não relacionados."},"keyConcept":"Regra: EBS snapshot = backup de bloco padrão na AWS.","tutorSeeds":["Pode explicar com mais detalhe: Regra: EBS snapshot = backup de bloco padrão na AWS?","Quais cenários reais aplicam Regra: EBS snapshot = backup de bloco padrão na AWS?","Como EBS se compara com alternativas?"]}'::jsonb, 'Cloud Technology & Services', 'Cloud Technology & Services', 'easy', 'scenario', '["ec2","ebs","backup"]'::jsonb, 'ai-draft', 'active', now(), now()),
    ('clf-c02-tech-012', 'aws-clf', 'Uma equipe precisa fazer um workload de Windows Server licenciado por core físico em conformidade com a licença BYOL do fornecedor. Qual modelo de compra EC2 é necessário?', '[{"id":"A","text":"Reserved Instance Standard"},{"id":"B","text":"Spot Instance com hibernation"},{"id":"C","text":"Dedicated Host"},{"id":"D","text":"On-Demand t3.large"}]'::jsonb, 'C', '{"summary":"Dedicated Host dá visibilidade do servidor físico (sockets, cores) — necessário para licenças BYOL ligadas a hardware (Windows, Oracle, SQL Server).","whyCorrect":"Dedicated Host dá visibilidade do servidor físico (sockets, cores) — necessário para licenças BYOL ligadas a hardware (Windows, Oracle, SQL Server).","whyWrong":{"B":"RI/Spot/On-Demand rodam em hardware compartilhado abstrato (Dedicated Instance compartilha host mas não expõe specs) Spot não serve para licenças estáveis.","A":"Reserved Instance Standard é commitment de pricing (1-3 anos) por desconto em On-Demand — NÃO dá visibilidade do hardware físico (sockets/cores) necessária para BYOL. RIs rodam em tenancy padrão (multi-tenant) onde cliente não vê o hardware. RIs seriam corretas para ''reduzir custo de uso steady-state em workload sem requisitos de licenciamento''.","D":"On-Demand t3.large é multi-tenant em hardware compartilhado — cliente não vê sockets/cores, AWS pode mover a instância entre hosts. Não atende requisito de BYOL por core físico. On-Demand seria correto se não houvesse exigência de licenciamento por hardware."},"keyConcept":"Regra: BYOL por core/socket = Dedicated Host.","tutorSeeds":["Pode explicar com mais detalhe: Regra: BYOL por core/socket = Dedicated Host?","Quais cenários reais aplicam Regra: BYOL por core/socket = Dedicated Host?","Como BYOL se compara com alternativas?"]}'::jsonb, 'Cloud Technology & Services', 'Cloud Technology & Services', 'hard', 'scenario', '["ec2","dedicated-host","licensing"]'::jsonb, 'ai-draft', 'active', now(), now()),
    ('clf-c02-tech-013', 'aws-clf', 'Uma startup quer rodar uma função simples acionada por upload em S3 sem gerenciar servidor algum. A função roda em milissegundos. Qual serviço é o mais adequado?', '[{"id":"A","text":"Amazon EC2 com user data"},{"id":"B","text":"AWS Lambda"},{"id":"C","text":"AWS Fargate"},{"id":"D","text":"Amazon EKS"}]'::jsonb, 'B', '{"summary":"Lambda é FaaS: sem servidor para gerenciar, paga por requisições + GB-segundo, integrado nativamente com S3 events.","whyCorrect":"Lambda é FaaS: sem servidor para gerenciar, paga por requisições + GB-segundo, integrado nativamente com S3 events.","whyWrong":{"C":"Fargate é serverless mas para containers de longa duração","A":"EC2 com user data exige provisionar instância, mantê-la rodando 24/7 (custo fixo), gerenciar OS, escalar para o pico — não é serverless. Para função simples acionada por evento, EC2 é overkill e antipadrão (paga ociosa). EC2 seria correto para apps que precisam de processo long-running.","D":"Amazon EKS é Kubernetes managed — exige cluster, nodes (ou Fargate), pods, deployments. Para ''função simples acionada por upload'', criar um cluster K8s é desproporcional ao problema. EKS seria correto para arquitetura microsserviços complexa, não para uma função pontual."},"keyConcept":"Regra: event-driven + curta duração = Lambda.","tutorSeeds":["Pode explicar com mais detalhe: Regra: event-driven + curta duração = Lambda?","Quais cenários reais aplicam Regra: event-driven + curta duração = Lambda?","Como GB-segundo se compara com alternativas?"]}'::jsonb, 'Cloud Technology & Services', 'Cloud Technology & Services', 'easy', 'scenario', '["lambda","serverless","s3-events"]'::jsonb, 'ai-draft', 'active', now(), now()),
    ('clf-c02-tech-014', 'aws-clf', 'Sobre o modelo de billing do AWS Lambda, qual afirmação é VERDADEIRA?', '[{"id":"A","text":"Cobra por hora de execução, similar a EC2"},{"id":"B","text":"Cobra por número de invocações e por GB-segundo de duração"},{"id":"C","text":"Cobra fixo mensal por função criada"},{"id":"D","text":"Cobra por largura de banda de saída apenas"}]'::jsonb, 'B', '{"summary":"Lambda cobra (1) por número de requisições e (2) por GB-segundo (memória configurada × tempo arredondado em ms).","whyCorrect":"Lambda cobra (1) por número de requisições e (2) por GB-segundo (memória configurada × tempo arredondado em ms). Há free tier mensal generoso.","whyWrong":{"C":"Não há cobrança por hora nem mensal por função","D":"banda também é cobrada mas não é o modelo principal.","A":"Lambda NÃO cobra por hora de execução — cobra por número de invocações + GB-segundo (memória × tempo arredondado ao ms). Diferença fundamental do modelo EC2: Lambda paga só pela execução real, com granularidade de ms. Modelo por hora seria EC2/Fargate baseline."},"keyConcept":"Regra: Lambda = pay-per-use real, escala a zero.","tutorSeeds":["Pode explicar com mais detalhe: Regra: Lambda = pay-per-use real, escala a zero?","Quais cenários reais aplicam Regra: Lambda = pay-per-use real, escala a zero?","Como GB-segundo se compara com alternativas?"]}'::jsonb, 'Cloud Technology & Services', 'Cloud Technology & Services', 'easy', 'recall', '["lambda","pricing","serverless"]'::jsonb, 'ai-draft', 'active', now(), now()),
    ('clf-c02-tech-015', 'aws-clf', 'Um time observa que a primeira invocação de uma função Lambda após período de inatividade leva ~3 segundos, enquanto subsequentes levam 50 ms. Qual fenômeno está ocorrendo?', '[{"id":"A","text":"Throttling por concurrency limit"},{"id":"B","text":"Cold start (init do ambiente de execução)"},{"id":"C","text":"Falha de rede temporária no VPC"},{"id":"D","text":"Erro de permissão IAM cacheado"}]'::jsonb, 'B', '{"summary":"Cold start ocorre quando Lambda precisa criar um novo execution environment: download do código, init do runtime e execução do código global (fora do handler).","whyCorrect":"Cold start ocorre quando Lambda precisa criar um novo execution environment: download do código, init do runtime e execução do código global (fora do handler). Subsequentes reusam o environment quente.","whyWrong":{"A":"Throttling rejeita invocações com 429","C":"erro de rede causa timeout, não slow-start","D":"IAM dá erro de permissão, não latência variável."},"keyConcept":"Regra: mitigação = Provisioned Concurrency, SnapStart (Java) ou reduzir init code.","tutorSeeds":["Pode explicar com mais detalhe: Regra: mitigação = Provisioned Concurrency, SnapStart (Java) ou reduzir init code?","Quais cenários reais aplicam Regra: mitigação = Provisioned Concurrency, SnapStart (Java) ou reduzir init code?"]}'::jsonb, 'Cloud Technology & Services', 'Cloud Technology & Services', 'medium', 'troubleshoot', '["lambda","cold-start","performance"]'::jsonb, 'ai-draft', 'active', now(), now()),
    ('clf-c02-tech-016', 'aws-clf', 'Uma equipe quer compartilhar uma biblioteca pesada (pandas, numpy) entre 15 funções Lambda sem incluir nos zips. Qual recurso resolve?', '[{"id":"A","text":"Lambda Layers"},{"id":"B","text":"EFS montado em todas as funções"},{"id":"C","text":"S3 com download no init"},{"id":"D","text":"Aumentar memory para 10GB"}]'::jsonb, 'A', '{"summary":"Lambda Layers permitem empacotar dependências e libs e reusar em múltiplas funções; cada função pode usar até 5 layers.","whyCorrect":"Lambda Layers permitem empacotar dependências e libs e reusar em múltiplas funções; cada função pode usar até 5 layers.","whyWrong":{"C":"S3 no init dobra cold start","D":"aumentar memória não resolve compartilhamento.","B":"EFS montado em Lambda funciona mas é mais complexo: exige VPC config (Lambda dentro de subnet privada), Mount Target em cada AZ, ENI, latência maior, e EFS tem custo por GB armazenado + throughput. Para libs estáticas como pandas/numpy, Layers são solução nativa, sem custo extra de mount. EFS seria correto para dados grandes mutáveis compartilhados."},"keyConcept":"Regra: dependências compartilhadas = Layers; dados grandes mutáveis = EFS.","tutorSeeds":["Pode explicar com mais detalhe: Regra: dependências compartilhadas = Layers; dados grandes mutáveis = EFS?","Quais cenários reais aplicam Regra: dependências compartilhadas = Layers; dados grandes mutáveis = EFS?"]}'::jsonb, 'Cloud Technology & Services', 'Cloud Technology & Services', 'easy', 'scenario', '["lambda","layers","dependencies"]'::jsonb, 'ai-draft', 'active', now(), now()),
    ('clf-c02-tech-017', 'aws-clf', 'Uma equipe quer rodar uma aplicação em container Docker que sobe sob demanda, sem gerenciar EC2 nem nodes Kubernetes, com billing por uso. Qual serviço é o mais adequado?', '[{"id":"A","text":"Amazon ECS com launch type EC2"},{"id":"B","text":"AWS Fargate"},{"id":"C","text":"Amazon EKS no modo self-managed"},{"id":"D","text":"AWS Batch com EC2"}]'::jsonb, 'B', '{"summary":"Fargate é serverless containers — você define CPU/RAM, ele provisiona e cobra por vCPU-s + GB-s.","whyCorrect":"Fargate é serverless containers — você define CPU/RAM, ele provisiona e cobra por vCPU-s + GB-s. Sem nodes para gerenciar. Funciona com ECS ou EKS.","whyWrong":{"C":"EKS self-managed exige operar nodes","D":"Batch é para workloads de batch específicos.","A":"ECS com launch type EC2 exige o cliente gerenciar o cluster de instâncias EC2 (provisioning, scaling, patching dos hosts) — não é ''sem gerenciar EC2''. Cliente paga pelas EC2 mesmo ociosas e é responsável por capacidade. Seria correto se o cliente preferisse controle total sobre os hosts (custo otimizado para workloads steady)."},"keyConcept":"Regra: containers serverless = Fargate.","tutorSeeds":["Pode explicar com mais detalhe: Regra: containers serverless = Fargate?","Quais cenários reais aplicam Regra: containers serverless = Fargate?","Como CPU se compara com alternativas?"]}'::jsonb, 'Cloud Technology & Services', 'Cloud Technology & Services', 'easy', 'scenario', '["fargate","containers","serverless"]'::jsonb, 'ai-draft', 'active', now(), now()),
    ('clf-c02-tech-018', 'aws-clf', 'Uma empresa quer hospedar uma webapp Node.js direto do código fonte, com auto-scaling, HTTPS e domínio custom — sem gerenciar containers ou ELB. Qual serviço é o mais simples?', '[{"id":"A","text":"AWS App Runner"},{"id":"B","text":"AWS Lambda com API Gateway"},{"id":"C","text":"Amazon EC2 com Nginx"},{"id":"D","text":"Amazon EKS com ingress NGINX"}]'::jsonb, 'A', '{"summary":"App Runner deploya direto de repositório Git ou imagem ECR, oferece HTTPS, auto-scaling, custom domain e logs — fully managed, sem ELB ou cluster para gerenciar.","whyCorrect":"App Runner deploya direto de repositório Git ou imagem ECR, oferece HTTPS, auto-scaling, custom domain e logs — fully managed, sem ELB ou cluster para gerenciar.","whyWrong":{"B":"Lambda+APIGW exige reestruturar app em handler stateless","C":"EC2 com Nginx exige provisionar instância, configurar Nginx, certificados TLS (manual ou via cert-manager), Auto Scaling, ALB, patching de OS — exatamente o oposto de ''sem gerenciar containers ou ELB''. Trabalho operacional alto para webapp simples.","D":"EKS com ingress NGINX é stack Kubernetes complexa — cluster, ingress controller, manifest YAML, certificados, scaling de nodes ou Fargate profiles. Curva de aprendizado e operação altíssimas para uma webapp Node.js. EKS seria correto para arquitetura microsserviços com requisitos K8s específicos."},"keyConcept":"Regra: webapp simples sem ops = App Runner.","tutorSeeds":["Pode explicar com mais detalhe: Regra: webapp simples sem ops = App Runner?","Quais cenários reais aplicam Regra: webapp simples sem ops = App Runner?","Como ECR se compara com alternativas?"]}'::jsonb, 'Cloud Technology & Services', 'Cloud Technology & Services', 'medium', 'scenario', '["app-runner","serverless","webapp"]'::jsonb, 'ai-draft', 'active', now(), now()),
    ('clf-c02-tech-019', 'aws-clf', 'Sobre AWS Lambda, qual limitação é VERDADEIRA?', '[{"id":"A","text":"Tempo máximo de execução por invocação é 15 minutos"},{"id":"B","text":"Suporta apenas linguagens interpretadas (Python, Node.js)"},{"id":"C","text":"Memória mínima é 1 GB"},{"id":"D","text":"Não suporta variáveis de ambiente"}]'::jsonb, 'A', '{"summary":"Lambda timeout é configurável de 1s a 900s (15 min).","whyCorrect":"Lambda timeout é configurável de 1s a 900s (15 min). Para mais que isso usa-se Step Functions, Fargate ou ECS.","whyWrong":{"B":"Suporta Python, Node.js, Java, .NET, Go, Ruby + custom runtimes via container images","C":"memória vai de 128 MB a 10 GB","D":"Lambda SUPORTA variáveis de ambiente (até 4KB total, key/value), com encryption opcional via KMS. São amplamente usadas para configuração (database URL, feature flags). Esta opção é factualmente falsa. A limitação verdadeira é o timeout máximo de 15 minutos."},"keyConcept":"Regra: workload > 15 min = não-Lambda.","tutorSeeds":["Pode explicar com mais detalhe: Regra: workload > 15 min = não-Lambda?","Quais cenários reais aplicam Regra: workload > 15 min = não-Lambda?","Como ECS se compara com alternativas?"]}'::jsonb, 'Cloud Technology & Services', 'Cloud Technology & Services', 'easy', 'recall', '["lambda","limits","serverless"]'::jsonb, 'ai-draft', 'active', now(), now()),
    ('clf-c02-tech-020', 'aws-clf', 'Uma equipe distribui sua aplicação Lambda como container image (até 10 GB) em vez de ZIP. Qual afirmação é VERDADEIRA?', '[{"id":"A","text":"Lambda não suporta container images"},{"id":"B","text":"Container images permitem até 10 GB, hospedadas em Amazon ECR"},{"id":"C","text":"Containers só rodam via ECS, nunca via Lambda"},{"id":"D","text":"Lambda containers requerem cluster Kubernetes"}]'::jsonb, 'B', '{"summary":"Lambda suporta container images até 10 GB (vs 250 MB unzipped do ZIP); imagens vão em ECR e o Lambda puxa no deploy.","whyCorrect":"Lambda suporta container images até 10 GB (vs 250 MB unzipped do ZIP); imagens vão em ECR e o Lambda puxa no deploy. Útil para ML models, dependências grandes ou parity com dev local.","whyWrong":{"C":"ZIP é limitado mas containers contornam","D":"Lambda não usa Kubernetes.","A":"Lambda SUPORTA container images desde 2020 (re:Invent) — é factualmente errado dizer que não suporta. Container images podem ser até 10GB (vs 250MB para ZIP), distribuídas via ECR, com base images da AWS ou customizadas."},"keyConcept":"Regra: deps grandes (>250 MB) ou parity com Docker dev = container Lambda.","tutorSeeds":["Pode explicar com mais detalhe: Regra: deps grandes (>250 MB) ou parity com Docker dev = container Lambda?","Quais cenários reais aplicam Regra: deps grandes (>250 MB) ou parity com Docker dev = container Lambda?","Como GB se compara com alternativas?"]}'::jsonb, 'Cloud Technology & Services', 'Cloud Technology & Services', 'medium', 'recall', '["lambda","containers","ecr"]'::jsonb, 'ai-draft', 'active', now(), now()),
    ('clf-c02-tech-021', 'aws-clf', 'Uma equipe quer reduzir latência de cold start de uma função Lambda crítica que serve uma API customer-facing. Qual recurso ajuda mais?', '[{"id":"A","text":"Aumentar timeout para 15 minutos"},{"id":"B","text":"Habilitar Provisioned Concurrency"},{"id":"C","text":"Reduzir memória para 128 MB"},{"id":"D","text":"Trocar Python por Java"}]'::jsonb, 'B', '{"summary":"Provisioned Concurrency mantém N environments pré-inicializados e quentes, eliminando cold start (custo extra fixo, paga mesmo ocioso).","whyCorrect":"Provisioned Concurrency mantém N environments pré-inicializados e quentes, eliminando cold start (custo extra fixo, paga mesmo ocioso).","whyWrong":{"A":"Aumentar timeout não afeta init","C":"reduzir memória aumenta tempo de execução e cold start","D":"Java geralmente tem cold start pior que Python."},"keyConcept":"Regra: latência crítica + tráfego previsível = Provisioned Concurrency; SnapStart (Java) é alternativa específica.","tutorSeeds":["Pode explicar com mais detalhe: Regra: latência crítica + tráfego previsível = Provisioned Concurrency; SnapStart (Java) é alternativa específica?","Quais cenários reais aplicam Regra: latência crítica + tráfego previsível = Provisioned Concurrency; SnapStart (Java) é alternativa específica?"]}'::jsonb, 'Cloud Technology & Services', 'Cloud Technology & Services', 'medium', 'troubleshoot', '["lambda","provisioned-concurrency","performance"]'::jsonb, 'ai-draft', 'active', now(), now()),
    ('clf-c02-tech-022', 'aws-clf', 'Uma empresa migra uma aplicação Java legada com tempo de boot de 20 segundos para Lambda containers. Os cold starts ficaram inviáveis. Qual feature reduz cold start de aplicações Java/.NET especificamente?', '[{"id":"A","text":"Lambda SnapStart"},{"id":"B","text":"Lambda Layers"},{"id":"C","text":"Lambda Insights"},{"id":"D","text":"Lambda Destinations"}]'::jsonb, 'A', '{"summary":"SnapStart cria snapshots do execution environment já inicializado para Java (e mais runtimes evolvendo) — restaura em ms, reduzindo cold start em até 10x.","whyCorrect":"SnapStart cria snapshots do execution environment já inicializado para Java (e mais runtimes evolvendo) — restaura em ms, reduzindo cold start em até 10x.","whyWrong":{"B":"Layers compartilham deps mas não inicializam","C":"Insights é monitoring","D":"Destinations é roteamento de async results."},"keyConcept":"Regra: Java cold start = SnapStart; Node/Python = otimizar init code + Provisioned Concurrency.","tutorSeeds":["Pode explicar com mais detalhe: Regra: Java cold start = SnapStart; Node/Python = otimizar init code + Provisioned Concurrency?","Quais cenários reais aplicam Regra: Java cold start = SnapStart; Node/Python = otimizar init code + Provisioned Concurrency?"]}'::jsonb, 'Cloud Technology & Services', 'Cloud Technology & Services', 'hard', 'troubleshoot', '["lambda","snapstart","java"]'::jsonb, 'ai-draft', 'active', now(), now()),
    ('clf-c02-tech-023', 'aws-clf', 'Uma equipe tem 200 microsserviços e usa Kubernetes em outras clouds. Quer continuar com Kubernetes mas usar AWS. Qual serviço escolher?', '[{"id":"A","text":"Amazon ECS"},{"id":"B","text":"AWS Lambda"},{"id":"C","text":"Amazon EKS"},{"id":"D","text":"AWS Batch"}]'::jsonb, 'C', '{"summary":"EKS é Kubernetes managed pela AWS — control plane HA gerenciado, kubectl/Helm padrão, portabilidade entre clouds.","whyCorrect":"EKS é Kubernetes managed pela AWS — control plane HA gerenciado, kubectl/Helm padrão, portabilidade entre clouds.","whyWrong":{"B":"Lambda é FaaS","D":"Batch é workload-specific.","A":"Amazon ECS é orquestrador de containers proprietário da AWS — NÃO usa Kubernetes API/kubectl. Migrar para ECS exigiria reescrever manifests YAML para task definitions, perder portabilidade entre clouds e reaprender ferramentas. ECS seria correto para equipe AWS-only que quer simplicidade, mas o requisito explícito é manter Kubernetes."},"keyConcept":"Regra: Kubernetes-first ou multi-cloud = EKS; AWS-only e simplicidade = ECS.","tutorSeeds":["Pode explicar com mais detalhe: Regra: Kubernetes-first ou multi-cloud = EKS; AWS-only e simplicidade = ECS?","Quais cenários reais aplicam Regra: Kubernetes-first ou multi-cloud = EKS; AWS-only e simplicidade = ECS?","Como EKS se compara com alternativas?"]}'::jsonb, 'Cloud Technology & Services', 'Cloud Technology & Services', 'easy', 'best-practice', '["eks","kubernetes","containers"]'::jsonb, 'ai-draft', 'active', now(), now()),
    ('clf-c02-tech-024', 'aws-clf', 'Uma startup pequena quer orquestrar containers Docker na AWS sem aprender Kubernetes. Qual serviço é o mais simples?', '[{"id":"A","text":"Amazon EKS"},{"id":"B","text":"Amazon ECS"},{"id":"C","text":"AWS App Mesh"},{"id":"D","text":"Amazon EMR"}]'::jsonb, 'B', '{"summary":"ECS é orquestrador nativo AWS, integrado com IAM, VPC, ALB, CloudWatch — curva de aprendizado muito menor que Kubernetes.","whyCorrect":"ECS é orquestrador nativo AWS, integrado com IAM, VPC, ALB, CloudWatch — curva de aprendizado muito menor que Kubernetes. Suporta EC2 ou Fargate.","whyWrong":{"C":"App Mesh é service mesh, não orquestrador","A":"Amazon EKS é Kubernetes managed — exige aprender API K8s, kubectl, manifests, ingress controllers, networking CNI. Curva de aprendizado alta para startup pequena sem expertise. EKS seria correto se a equipe JÁ usasse Kubernetes em outra cloud ou tivesse requisito de portabilidade.","D":"Amazon EMR é serviço de big data managed para Hadoop/Spark/Hive — não é orquestrador de containers Docker. EMR seria correto para ''processar 100TB de dados com Spark'', não para rodar microsserviços containerizados. Conceitos completamente distintos."},"keyConcept":"Regra: simplicidade + AWS-only = ECS; padrão K8s = EKS.","tutorSeeds":["Pode explicar com mais detalhe: Regra: simplicidade + AWS-only = ECS; padrão K8s = EKS?","Quais cenários reais aplicam Regra: simplicidade + AWS-only = ECS; padrão K8s = EKS?","Como ECS se compara com alternativas?"]}'::jsonb, 'Cloud Technology & Services', 'Cloud Technology & Services', 'easy', 'scenario', '["ecs","containers","orchestration"]'::jsonb, 'ai-draft', 'active', now(), now()),
    ('clf-c02-tech-025', 'aws-clf', 'Uma equipe usa Amazon ECS e precisa decidir entre launch type EC2 e Fargate. Qual cenário favorece Fargate?', '[{"id":"A","text":"Workload com GPUs para deep learning training"},{"id":"B","text":"Aplicações stateless de tráfego variável onde a equipe quer zero gestão de hosts"},{"id":"C","text":"Sistemas que requerem acesso root ao host EC2"},{"id":"D","text":"Workloads que excedem 120 GB de memória por task"}]'::jsonb, 'B', '{"summary":"Fargate elimina gestão de capacidade (sem nodes, sem patching), ideal para microsserviços com tráfego variável.","whyCorrect":"Fargate elimina gestão de capacidade (sem nodes, sem patching), ideal para microsserviços com tráfego variável.","whyWrong":{"C":"host root só em EC2 mode","A":"GPU workloads (deep learning training) requerem instâncias EC2 com GPU específicas (P3, P4, G5) — Fargate NÃO suporta GPU. Para training, launch type EC2 com EKS/ECS e instâncias GPU é mandatório. Fargate seria a escolha errada aqui.","D":"Fargate tem limites de recursos por task: até 16 vCPU e 120GB de memória atualmente. Workloads que excedem 120GB de memória por task NÃO cabem em Fargate, exigindo EC2 launch type com instâncias maiores (R5, X1, etc.). Limite arquitetural de Fargate."},"keyConcept":"Regra: gestão zero = Fargate; controle total/GPU/hardware specific = EC2.","tutorSeeds":["Pode explicar com mais detalhe: Regra: gestão zero = Fargate; controle total/GPU/hardware specific = EC2?","Quais cenários reais aplicam Regra: gestão zero = Fargate; controle total/GPU/hardware specific = EC2?"]}'::jsonb, 'Cloud Technology & Services', 'Cloud Technology & Services', 'medium', 'best-practice', '["ecs","fargate","ec2"]'::jsonb, 'ai-draft', 'active', now(), now()),
    ('clf-c02-tech-026', 'aws-clf', 'Uma equipe precisa de um registry privado de imagens Docker integrado com IAM e EKS/ECS. Qual serviço usar?', '[{"id":"A","text":"Amazon S3 com bucket de imagens"},{"id":"B","text":"Amazon ECR (Elastic Container Registry)"},{"id":"C","text":"AWS CodeArtifact"},{"id":"D","text":"Docker Hub"}]'::jsonb, 'B', '{"summary":"ECR é registry de imagens OCI/Docker gerenciado pela AWS, com IAM, lifecycle policies, vulnerability scanning e integração nativa com ECS/EKS/Lambda containers.","whyCorrect":"ECR é registry de imagens OCI/Docker gerenciado pela AWS, com IAM, lifecycle policies, vulnerability scanning e integração nativa com ECS/EKS/Lambda containers.","whyWrong":{"C":"CodeArtifact é para pacotes (npm, Maven, etc.)","D":"Docker Hub é externo (rate limits, sem IAM nativo).","A":"Amazon S3 é object storage geral — pode armazenar arquivos de imagem Docker como objetos, mas falta TUDO que um registry oferece: API Docker, scanning de vulnerabilidades, lifecycle por tag, signed URLs específicos para pull, integração nativa com ECS/EKS. S3 seria hack inviável; ECR é o produto purpose-built."},"keyConcept":"Regra: imagens AWS-native + IAM = ECR.","tutorSeeds":["Pode explicar com mais detalhe: Regra: imagens AWS-native + IAM = ECR?","Quais cenários reais aplicam Regra: imagens AWS-native + IAM = ECR?","Como ECR se compara com alternativas?"]}'::jsonb, 'Cloud Technology & Services', 'Cloud Technology & Services', 'easy', 'scenario', '["ecr","containers","registry"]'::jsonb, 'ai-draft', 'active', now(), now()),
    ('clf-c02-tech-027', 'aws-clf', 'Uma equipe quer migrar do ECS para EKS gradualmente, mantendo cargas em Fargate sem nodes. Isso é possível?', '[{"id":"A","text":"Não — Fargate só funciona com ECS"},{"id":"B","text":"Sim — EKS Fargate executa pods Kubernetes em Fargate sem nodes EC2"},{"id":"C","text":"Sim, mas requer cluster EKS Anywhere on-prem"},{"id":"D","text":"Não — EKS exige obrigatoriamente node groups EC2"}]'::jsonb, 'B', '{"summary":"EKS Fargate permite rodar pods em Fargate (serverless), sem precisar provisionar nodes EC2 — paga por vCPU/memória do pod.","whyCorrect":"EKS Fargate permite rodar pods em Fargate (serverless), sem precisar provisionar nodes EC2 — paga por vCPU/memória do pod. Pode coexistir com node groups.","whyWrong":{"A":"Fargate funciona com ECS e EKS EKS aceita Fargate-only para muitos casos.","C":"EKS Anywhere é on-prem","D":"EKS NÃO exige node groups EC2 obrigatoriamente — Fargate profiles permitem rodar pods diretamente em Fargate sem nodes. Esta opção é factualmente incorreta. Combinações são possíveis: cluster EKS com node groups EC2 + Fargate profiles coexistindo, ou cluster 100% Fargate."},"keyConcept":"Regra: pods serverless = EKS Fargate; flexibilidade total = EKS managed node groups.","tutorSeeds":["Pode explicar com mais detalhe: Regra: pods serverless = EKS Fargate; flexibilidade total = EKS managed node groups?","Quais cenários reais aplicam Regra: pods serverless = EKS Fargate; flexibilidade total = EKS managed node groups?","Como EKS se compara com alternativas?"]}'::jsonb, 'Cloud Technology & Services', 'Cloud Technology & Services', 'hard', 'scenario', '["eks","fargate","kubernetes"]'::jsonb, 'ai-draft', 'active', now(), now()),
    ('clf-c02-tech-028', 'aws-clf', 'Uma empresa quer armazenar 5 PB de arquivos imutáveis acessados raramente (uma vez por mês) mas com retrieval em segundos quando preciso. Qual storage class S3 é a mais adequada por custo?', '[{"id":"A","text":"S3 Standard"},{"id":"B","text":"S3 Standard-IA (Infrequent Access)"},{"id":"C","text":"S3 Glacier Deep Archive"},{"id":"D","text":"S3 One Zone-IA"}]'::jsonb, 'B', '{"summary":"Standard-IA tem custo de storage menor que Standard e mantém latência de ms (retrieval imediato), com taxa de acesso por GB.","whyCorrect":"Standard-IA tem custo de storage menor que Standard e mantém latência de ms (retrieval imediato), com taxa de acesso por GB. Ideal para arquivos acessados ~1x/mês.","whyWrong":{"A":"Standard é caro para acesso raro","C":"Glacier Deep Archive tem retrieval em horas","D":"One Zone-IA é mais barato mas single AZ (risco se houver falha de AZ)."},"keyConcept":"Regra: latência ms + acesso raro = Standard-IA.","tutorSeeds":["Pode explicar com mais detalhe: Regra: latência ms + acesso raro = Standard-IA?","Quais cenários reais aplicam Regra: latência ms + acesso raro = Standard-IA?","Como IA se compara com alternativas?"]}'::jsonb, 'Cloud Technology & Services', 'Cloud Technology & Services', 'medium', 'scenario', '["s3","storage-class","cost-optimization"]'::jsonb, 'ai-draft', 'active', now(), now()),
    ('clf-c02-tech-029', 'aws-clf', 'Uma equipe quer arquivar logs de compliance que precisam ser mantidos por 7 anos e acessados quase nunca (talvez uma vez no período), com tolerância de retrieval em até 12 horas. Qual storage class minimiza custo?', '[{"id":"A","text":"S3 Standard-IA"},{"id":"B","text":"S3 Glacier Flexible Retrieval"},{"id":"C","text":"S3 Glacier Deep Archive"},{"id":"D","text":"S3 One Zone-IA"}]'::jsonb, 'C', '{"summary":"Glacier Deep Archive é a classe mais barata da AWS — projetada para retenção long-term (7+ anos) com retrieval em até 12h, ideal para compliance/legal hold.","whyCorrect":"Glacier Deep Archive é a classe mais barata da AWS — projetada para retenção long-term (7+ anos) com retrieval em até 12h, ideal para compliance/legal hold.","whyWrong":{"A":"Standard-IA é caro para esse volume","B":"Glacier Flexible Retrieval (antes ''Glacier'') é intermediário (minutos-horas)","D":"One Zone-IA não atende compliance multi-AZ."},"keyConcept":"Regra: ''tape replacement'' = Deep Archive.","tutorSeeds":["Pode explicar com mais detalhe: Regra: ''tape replacement'' = Deep Archive?","Quais cenários reais aplicam Regra: ''tape replacement'' = Deep Archive?","Como AWS se compara com alternativas?"]}'::jsonb, 'Cloud Technology & Services', 'Cloud Technology & Services', 'medium', 'scenario', '["s3","glacier","compliance"]'::jsonb, 'ai-draft', 'active', now(), now()),
    ('clf-c02-tech-030', 'aws-clf', 'Uma empresa não sabe prever padrão de acesso de seus objetos S3 (alguns vão ser acessados, outros não) e quer otimização automática sem retrieval fees imprevisíveis. Qual storage class usar?', '[{"id":"A","text":"S3 Standard"},{"id":"B","text":"S3 Intelligent-Tiering"},{"id":"C","text":"S3 Glacier Instant Retrieval"},{"id":"D","text":"S3 Standard-IA"}]'::jsonb, 'B', '{"summary":"Intelligent-Tiering monitora padrão de acesso por objeto e move automaticamente entre tiers (Frequent/Infrequent/Archive Instant/Archive/Deep Archive), sem retrieval fees nas tiers principais — pequena fee de monitoring por objeto.","whyCorrect":"Intelligent-Tiering monitora padrão de acesso por objeto e move automaticamente entre tiers (Frequent/Infrequent/Archive Instant/Archive/Deep Archive), sem retrieval fees nas tiers principais — pequena fee de monitoring por objeto.","whyWrong":{"A":"Standard é caro se a maioria é frio Standard-IA cobra retrieval (caro se errar prediction)","C":"Glacier IR é para arquivamento previsível.","D":"S3 Standard-IA é para acesso infrequente PREVISÍVEL (objeto X é raramente acessado) — exige decisão antecipada sobre cada objeto e cobra retrieval fee + minimum 30 dias de storage. Quando o padrão de acesso é DESCONHECIDO, decisão antecipada pode estar errada (objeto frequente em IA pagaria muito retrieval). Intelligent-Tiering elimina essa aposta."},"keyConcept":"Regra: padrão desconhecido = Intelligent-Tiering.","tutorSeeds":["Pode explicar com mais detalhe: Regra: padrão desconhecido = Intelligent-Tiering?","Quais cenários reais aplicam Regra: padrão desconhecido = Intelligent-Tiering?"]}'::jsonb, 'Cloud Technology & Services', 'Cloud Technology & Services', 'medium', 'best-practice', '["s3","intelligent-tiering","cost-optimization"]'::jsonb, 'ai-draft', 'active', now(), now()),
    ('clf-c02-tech-031', 'aws-clf', 'Uma equipe quer mover objetos automaticamente de S3 Standard para Glacier Deep Archive após 90 dias, e deletar após 7 anos. Qual feature S3 implementa isso?', '[{"id":"A","text":"S3 Replication"},{"id":"B","text":"S3 Lifecycle policies"},{"id":"C","text":"S3 Inventory"},{"id":"D","text":"S3 Event Notifications"}]'::jsonb, 'B', '{"summary":"Lifecycle policies definem transições entre storage classes e expirações com base em idade do objeto, prefix ou tag — exatamente o caso descrito.","whyCorrect":"Lifecycle policies definem transições entre storage classes e expirações com base em idade do objeto, prefix ou tag — exatamente o caso descrito.","whyWrong":{"A":"Replication copia para outro bucket","C":"Inventory gera relatórios","D":"Event Notifications dispara Lambda/SNS em eventos."},"keyConcept":"Regra: gerência automática de ciclo de vida = Lifecycle policies.","tutorSeeds":["Pode explicar com mais detalhe: Regra: gerência automática de ciclo de vida = Lifecycle policies?","Quais cenários reais aplicam Regra: gerência automática de ciclo de vida = Lifecycle policies?"]}'::jsonb, 'Cloud Technology & Services', 'Cloud Technology & Services', 'easy', 'scenario', '["s3","lifecycle","automation"]'::jsonb, 'ai-draft', 'active', now(), now()),
    ('clf-c02-tech-032', 'aws-clf', 'Uma empresa precisa proteger objetos S3 contra exclusão acidental ou maliciosa, mantendo versões anteriores para recovery. Qual feature deve ser habilitada?', '[{"id":"A","text":"S3 Versioning"},{"id":"B","text":"S3 Block Public Access"},{"id":"C","text":"S3 Transfer Acceleration"},{"id":"D","text":"S3 Requester Pays"}]'::jsonb, 'A', '{"summary":"Versioning preserva, recupera e restaura cada versão de cada objeto; DELETE cria delete marker em vez de remover, permitindo undelete.","whyCorrect":"Versioning preserva, recupera e restaura cada versão de cada objeto; DELETE cria delete marker em vez de remover, permitindo undelete. Combinado com MFA Delete adiciona camada extra.","whyWrong":{"B":"Block Public Access bloqueia acesso anônimo (não relacionado a versões)","C":"Transfer Acceleration acelera upload","D":"Requester Pays cobra do solicitante."},"keyConcept":"Regra: proteção contra delete acidental = Versioning + MFA Delete.","tutorSeeds":["Pode explicar com mais detalhe: Regra: proteção contra delete acidental = Versioning + MFA Delete?","Quais cenários reais aplicam Regra: proteção contra delete acidental = Versioning + MFA Delete?","Como DELETE se compara com alternativas?"]}'::jsonb, 'Cloud Technology & Services', 'Cloud Technology & Services', 'easy', 'scenario', '["s3","versioning","data-protection"]'::jsonb, 'ai-draft', 'active', now(), now()),
    ('clf-c02-tech-033', 'aws-clf', 'Uma empresa global tem usuários no Brasil e na Alemanha. Eles querem servir os mesmos objetos S3 com baixa latência em ambas as regiões. Qual feature usar?', '[{"id":"A","text":"S3 Cross-Region Replication (CRR)"},{"id":"B","text":"S3 Same-Region Replication (SRR)"},{"id":"C","text":"S3 Transfer Acceleration"},{"id":"D","text":"S3 Object Lock"}]'::jsonb, 'A', '{"summary":"CRR replica objetos automaticamente para bucket em outra Region — permite servir conteúdo localmente em cada Region, reduzindo latência e atendendo data residency.","whyCorrect":"CRR replica objetos automaticamente para bucket em outra Region — permite servir conteúdo localmente em cada Region, reduzindo latência e atendendo data residency.","whyWrong":{"B":"SRR é dentro da mesma Region (compliance/logs)","C":"Transfer Acceleration acelera upload via edge","D":"Object Lock é WORM."},"keyConcept":"Regra: dois ou mais regiões com cópia = CRR; CDN global = CloudFront.","tutorSeeds":["Pode explicar com mais detalhe: Regra: dois ou mais regiões com cópia = CRR; CDN global = CloudFront?","Quais cenários reais aplicam Regra: dois ou mais regiões com cópia = CRR; CDN global = CloudFront?","Como CRR se compara com alternativas?"]}'::jsonb, 'Cloud Technology & Services', 'Cloud Technology & Services', 'medium', 'scenario', '["s3","crr","replication"]'::jsonb, 'ai-draft', 'active', now(), now()),
    ('clf-c02-tech-034', 'aws-clf', 'Sobre Amazon S3, qual afirmação está CORRETA sobre a durabilidade?', '[{"id":"A","text":"S3 Standard tem durabilidade de 99.9% (three nines)"},{"id":"B","text":"S3 Standard tem durabilidade de 99.999999999% (eleven nines) por objeto/ano"},{"id":"C","text":"S3 não garante durabilidade — é responsabilidade do cliente replicar"},{"id":"D","text":"S3 tem durabilidade apenas se Versioning estiver habilitado"}]'::jsonb, 'B', '{"summary":"S3 Standard (e outras classes regionais) oferece 11 noves de durabilidade — equivalente a perda esperada de ~1 objeto a cada 10 milhões em 10 mil anos.","whyCorrect":"S3 Standard (e outras classes regionais) oferece 11 noves de durabilidade — equivalente a perda esperada de ~1 objeto a cada 10 milhões em 10 mil anos. AWS replica objetos em múltiplas AZs internamente.","whyWrong":{"A":"classes One Zone têm a mesma durabilidade desde que a AZ não falhe.","D":"Durabilidade é nativa, não depende de Versioning","C":"S3 GARANTE durabilidade nativamente — replicação interna entre múltiplas AZs com checksums automáticos. Cliente não precisa replicar manualmente para ter 11 nines de durabilidade. Esta opção contradiz documentação oficial. Cliente pode adicionar Cross-Region Replication para DR, mas isso é além dos 11 nines básicos."},"keyConcept":"Regra: durabilidade S3 = 11 nines, padrão da indústria.","tutorSeeds":["Pode explicar com mais detalhe: Regra: durabilidade S3 = 11 nines, padrão da indústria?","Quais cenários reais aplicam Regra: durabilidade S3 = 11 nines, padrão da indústria?","Como AWS se compara com alternativas?"]}'::jsonb, 'Cloud Technology & Services', 'Cloud Technology & Services', 'easy', 'recall', '["s3","durability","data-protection"]'::jsonb, 'ai-draft', 'active', now(), now()),
    ('clf-c02-tech-035', 'aws-clf', 'Um usuário tenta acessar diretamente uma URL S3 pública e recebe ''403 Forbidden'', apesar de o objeto existir. Quais são as causas mais prováveis?', '[{"id":"A","text":"Bucket está em outra Region e S3 não suporta cross-region"},{"id":"B","text":"Block Public Access está habilitado ou a bucket policy / ACL não permite o acesso"},{"id":"C","text":"S3 retorna 403 quando o bucket está em estado de Glacier"},{"id":"D","text":"O objeto não tem extensão de arquivo"}]'::jsonb, 'B', '{"summary":"Causas mais comuns de 403 em S3: (1) S3 Block Public Access ativado a nível de bucket/account, (2) bucket policy nega o acesso, (3) ACL não concede permissão.","whyCorrect":"Causas mais comuns de 403 em S3: (1) S3 Block Public Access ativado a nível de bucket/account, (2) bucket policy nega o acesso, (3) ACL não concede permissão. AWS retorna 403 também para evitar leak de existência.","whyWrong":{"A":"Buckets são acessíveis cross-region por URL","C":"Glacier retorna ''InvalidObjectState'' para GET","D":"extensão não afeta."},"keyConcept":"Regra: 403 = problema de permissão, não de localização.","tutorSeeds":["Pode explicar com mais detalhe: Regra: 403 = problema de permissão, não de localização?","Quais cenários reais aplicam Regra: 403 = problema de permissão, não de localização?","Como ACL se compara com alternativas?"]}'::jsonb, 'Cloud Technology & Services', 'Cloud Technology & Services', 'medium', 'troubleshoot', '["s3","permissions","troubleshoot"]'::jsonb, 'ai-draft', 'active', now(), now()),
    ('clf-c02-tech-036', 'aws-clf', 'Uma equipe quer montar um filesystem NFS compartilhado por dezenas de instâncias EC2 Linux, com escalabilidade automática de tamanho e pagamento por GB usado. Qual serviço escolher?', '[{"id":"A","text":"Amazon EBS Multi-Attach"},{"id":"B","text":"Amazon EFS"},{"id":"C","text":"Amazon FSx for Windows File Server"},{"id":"D","text":"Amazon S3 montado via s3fs"}]'::jsonb, 'B', '{"summary":"EFS é filesystem NFS managed, montável por milhares de EC2/Lambda/ECS simultaneamente, escala elástica automática, regional (multi-AZ).","whyCorrect":"EFS é filesystem NFS managed, montável por milhares de EC2/Lambda/ECS simultaneamente, escala elástica automática, regional (multi-AZ).","whyWrong":{"A":"EBS Multi-Attach é limitado (mesma AZ, drives físicos, max 16 instâncias com io1/io2)","C":"FSx Windows é SMB","D":"s3fs não é POSIX-compliant."},"keyConcept":"Regra: NFS multi-AZ Linux = EFS.","tutorSeeds":["Pode explicar com mais detalhe: Regra: NFS multi-AZ Linux = EFS?","Quais cenários reais aplicam Regra: NFS multi-AZ Linux = EFS?","Como EFS se compara com alternativas?"]}'::jsonb, 'Cloud Technology & Services', 'Cloud Technology & Services', 'easy', 'scenario', '["efs","nfs","storage"]'::jsonb, 'ai-draft', 'active', now(), now()),
    ('clf-c02-tech-037', 'aws-clf', 'Uma empresa Windows precisa de compartilhamento SMB com integração Active Directory para instâncias EC2 Windows. Qual serviço escolher?', '[{"id":"A","text":"Amazon EFS"},{"id":"B","text":"Amazon FSx for Windows File Server"},{"id":"C","text":"Amazon S3 montado via Storage Gateway"},{"id":"D","text":"Amazon EBS gp3"}]'::jsonb, 'B', '{"summary":"FSx for Windows File Server entrega filesystem nativo Windows com SMB, integração AD, ACLs Windows, DFS — managed pela AWS.","whyCorrect":"FSx for Windows File Server entrega filesystem nativo Windows com SMB, integração AD, ACLs Windows, DFS — managed pela AWS.","whyWrong":{"C":"S3 via Storage Gateway funciona mas não é nativo Windows com AD","A":"Amazon EFS oferece NFS v4 — não SMB. EFS é purpose-built para clientes Linux/Unix com NFS. Não tem integração nativa com Active Directory para autenticação SMB nem ACLs Windows. EFS seria correto para ''compartilhamento NFS entre EC2 Linux''.","D":"Amazon EBS gp3 é volume block storage anexado a UMA instância EC2 (exceto Multi-Attach em casos específicos). Não é compartilhamento de arquivos — é disco virtual. Para compartilhar arquivos entre múltiplos hosts, é necessário um serviço de file system (EFS para NFS, FSx for Windows para SMB)."},"keyConcept":"Regra: SMB + AD = FSx for Windows; NFS Linux = EFS.","tutorSeeds":["Pode explicar com mais detalhe: Regra: SMB + AD = FSx for Windows; NFS Linux = EFS?","Quais cenários reais aplicam Regra: SMB + AD = FSx for Windows; NFS Linux = EFS?","Como FSx se compara com alternativas?"]}'::jsonb, 'Cloud Technology & Services', 'Cloud Technology & Services', 'easy', 'scenario', '["fsx","windows","smb"]'::jsonb, 'ai-draft', 'active', now(), now()),
    ('clf-c02-tech-038', 'aws-clf', 'Um cluster HPC precisa de filesystem paralelo de alta performance (sub-ms latency, centenas de GB/s) integrado com S3 para datasets de ML. Qual FSx variant escolher?', '[{"id":"A","text":"FSx for Windows"},{"id":"B","text":"FSx for Lustre"},{"id":"C","text":"FSx for NetApp ONTAP"},{"id":"D","text":"FSx for OpenZFS"}]'::jsonb, 'B', '{"summary":"FSx for Lustre é filesystem paralelo POSIX otimizado para HPC, ML training e media processing — sub-ms latency, milhões de IOPS, throughput em centenas de GB/s, integrado com S3 (lazy-load + write-back).","whyCorrect":"FSx for Lustre é filesystem paralelo POSIX otimizado para HPC, ML training e media processing — sub-ms latency, milhões de IOPS, throughput em centenas de GB/s, integrado com S3 (lazy-load + write-back).","whyWrong":{"A":"FSx Windows é SMB","C":"ONTAP é multiprotocolo enterprise","D":"OpenZFS é Linux geral mas não HPC-grade."},"keyConcept":"Regra: HPC/ML high-throughput = Lustre.","tutorSeeds":["Pode explicar com mais detalhe: Regra: HPC/ML high-throughput = Lustre?","Quais cenários reais aplicam Regra: HPC/ML high-throughput = Lustre?","Como FSx se compara com alternativas?"]}'::jsonb, 'Cloud Technology & Services', 'Cloud Technology & Services', 'hard', 'scenario', '["fsx","lustre","hpc"]'::jsonb, 'ai-draft', 'active', now(), now()),
    ('clf-c02-tech-039', 'aws-clf', 'Uma equipe precisa escolher um volume EBS para um banco de dados MySQL com alto IOPS sustentado (10k+ IOPS) e baixa latência consistente. Qual tipo de volume usar?', '[{"id":"A","text":"gp2 (General Purpose SSD v2)"},{"id":"B","text":"gp3 (General Purpose SSD v3)"},{"id":"C","text":"io2 / io2 Block Express (Provisioned IOPS SSD)"},{"id":"D","text":"st1 (Throughput Optimized HDD)"}]'::jsonb, 'C', '{"summary":"io2/io2 Block Express oferece IOPS provisionados até 256k, latência sub-ms e durabilidade 99.999% — designed para bancos de produção.","whyCorrect":"io2/io2 Block Express oferece IOPS provisionados até 256k, latência sub-ms e durabilidade 99.999% — designed para bancos de produção.","whyWrong":{"D":"st1 é HDD throughput (Hadoop/logs), não IOPS.","A":"gp2 (General Purpose SSD v2) tem IOPS atrelados ao tamanho do volume (3 IOPS/GB, max 16k IOPS), com burst credits que podem se esgotar — latência inconsistente sob carga sustentada. Para banco de produção com 10k+ IOPS sustentado, gp2 fica no limite. AWS recomenda migrar gp2 → gp3 ou io2.","B":"gp3 (General Purpose SSD v3) suporta até 16k IOPS (provisionado) e é mais barato que gp2 — bom para muitos workloads de banco, mas para REQUISITO ESPECÍFICO de 10k+ IOPS com latência sub-ms CONSISTENTE em produção crítica, io2 é a escolha purpose-built (até 256k IOPS, 99.999% durabilidade)."},"keyConcept":"Regra: IOPS extremos e latência crítica = io2; IOPS moderados + baixo custo = gp3.","tutorSeeds":["Pode explicar com mais detalhe: Regra: IOPS extremos e latência crítica = io2; IOPS moderados + baixo custo = gp3?","Quais cenários reais aplicam Regra: IOPS extremos e latência crítica = io2; IOPS moderados + baixo custo = gp3?","Como IOPS se compara com alternativas?"]}'::jsonb, 'Cloud Technology & Services', 'Cloud Technology & Services', 'medium', 'scenario', '["ebs","io2","performance"]'::jsonb, 'ai-draft', 'active', now(), now()),
    ('clf-c02-tech-040', 'aws-clf', 'Sobre Amazon EBS, qual afirmação está CORRETA?', '[{"id":"A","text":"Volumes EBS podem ser anexados a instâncias em qualquer Region"},{"id":"B","text":"Volumes EBS são bound a uma única Availability Zone"},{"id":"C","text":"Volumes EBS são globalmente replicados por padrão"},{"id":"D","text":"Volumes EBS não permitem snapshots"}]'::jsonb, 'B', '{"summary":"EBS volumes existem em uma AZ específica — só podem ser attachados a instâncias da mesma AZ.","whyCorrect":"EBS volumes existem em uma AZ específica — só podem ser attachados a instâncias da mesma AZ. Para mover entre AZs/Regions usa-se snapshot (copy snapshot para outra Region).","whyWrong":{"C":"Snapshots são padrão e armazenam no S3 gerenciado.","A":"EBS volumes NÃO podem ser anexados a instâncias em outras Regions — são objetos ZONAIS (existem em uma AZ específica de uma Region). Para mover volume entre Regions, é necessário criar snapshot e usar copy snapshot para Region destino, então restaurar. Cross-AZ exige snapshot dentro da mesma Region.","D":"EBS SUPORTA snapshots — é uma das principais features (snapshots são incrementais, armazenados em S3 managed, base para AMIs, replicáveis cross-Region). Esta opção é factualmente errada. Snapshots são padrão de backup AWS."},"keyConcept":"Regra: EBS = block storage zonal; snapshots = portáveis para Region.","tutorSeeds":["Pode explicar com mais detalhe: Regra: EBS = block storage zonal; snapshots = portáveis para Region?","Quais cenários reais aplicam Regra: EBS = block storage zonal; snapshots = portáveis para Region?","Como EBS se compara com alternativas?"]}'::jsonb, 'Cloud Technology & Services', 'Cloud Technology & Services', 'easy', 'recall', '["ebs","availability-zone","storage"]'::jsonb, 'ai-draft', 'active', now(), now()),
    ('clf-c02-tech-041', 'aws-clf', 'Uma empresa quer compartilhar o mesmo volume entre algumas EC2 da mesma AZ para um aplicativo cluster-aware. Qual feature suporta isso?', '[{"id":"A","text":"EBS Multi-Attach (suportado em io1/io2)"},{"id":"B","text":"EBS Standard cross-AZ"},{"id":"C","text":"EFS Provisioned"},{"id":"D","text":"Snapshot incremental compartilhado"}]'::jsonb, 'A', '{"summary":"EBS Multi-Attach permite anexar mesmo volume a até 16 instâncias na mesma AZ — requer io1/io2 Provisioned IOPS e file system cluster-aware (não ext4 simples).","whyCorrect":"EBS Multi-Attach permite anexar mesmo volume a até 16 instâncias na mesma AZ — requer io1/io2 Provisioned IOPS e file system cluster-aware (não ext4 simples).","whyWrong":{"B":"EBS Standard cross-AZ não existe como feature — EBS volumes são zonais e Multi-Attach requer ainda mesma AZ. Volumes não podem ser anexados cross-AZ; para isso seria necessário replicação manual ou um serviço de file system (EFS).","C":"EFS Provisioned é modo de throughput de EFS (provisionar throughput máximo independente de tamanho) — mas EFS é file system NFS, não block storage. Para o requisito de ''mesmo volume compartilhado'' em modo cluster-aware (com locking de disco), EBS Multi-Attach é o construto correto. EFS daria semântica POSIX de arquivos, não block-level.","D":"Snapshots incrementais são para backup/restore, não para compartilhamento simultâneo entre instâncias — snapshot é point-in-time, não live shared. Compartilhar ''um volume entre múltiplas instâncias para cluster app'' requer multi-attach real (EBS Multi-Attach), não cópias de snapshot."},"keyConcept":"Regra: shared block storage = EBS Multi-Attach; shared file = EFS.","tutorSeeds":["Pode explicar com mais detalhe: Regra: shared block storage = EBS Multi-Attach; shared file = EFS?","Quais cenários reais aplicam Regra: shared block storage = EBS Multi-Attach; shared file = EFS?","Como EBS se compara com alternativas?"]}'::jsonb, 'Cloud Technology & Services', 'Cloud Technology & Services', 'hard', 'scenario', '["ebs","multi-attach","cluster"]'::jsonb, 'ai-draft', 'active', now(), now()),
    ('clf-c02-tech-042', 'aws-clf', 'Sobre EFS storage classes, qual cenário favorece EFS Infrequent Access (EFS IA)?', '[{"id":"A","text":"Arquivos acessados muitas vezes por dia"},{"id":"B","text":"Arquivos acessados raramente (menos que mensalmente) que ainda precisam de NFS"},{"id":"C","text":"Workloads que exigem latência sub-millisegundo constante"},{"id":"D","text":"Arquivos que precisam ser deletados a cada hora"}]'::jsonb, 'B', '{"summary":"EFS IA tem custo de storage até 92% menor que Standard, mas cobra por acesso — ideal para arquivos NFS que ficam frios após período inicial.","whyCorrect":"EFS IA tem custo de storage até 92% menor que Standard, mas cobra por acesso — ideal para arquivos NFS que ficam frios após período inicial. Lifecycle management move automaticamente.","whyWrong":{"A":"arquivos efêmeros = não EFS.","C":"Acesso constante = Standard latência ultraconsistente = não-IA","D":"Arquivos deletados a cada hora têm vida útil muito curta — não fazem sentido em EFS IA que cobra por GB armazenado + retrieval fee. Para conteúdo de altíssima rotatividade, EFS Standard ou storage local seria mais apropriado. EFS IA é para arquivos antigos que ainda precisam estar online mas raramente são lidos."},"keyConcept":"Regra: EFS IA = arquivos antigos/raramente lidos que ainda precisam estar online.","tutorSeeds":["Pode explicar com mais detalhe: Regra: EFS IA = arquivos antigos/raramente lidos que ainda precisam estar online?","Quais cenários reais aplicam Regra: EFS IA = arquivos antigos/raramente lidos que ainda precisam estar online?","Como EFS se compara com alternativas?"]}'::jsonb, 'Cloud Technology & Services', 'Cloud Technology & Services', 'medium', 'scenario', '["efs","storage-class","cost-optimization"]'::jsonb, 'ai-draft', 'active', now(), now()),
    ('clf-c02-tech-043', 'aws-clf', 'Uma equipe upgrada de gp2 para gp3 num volume EBS de 1 TB. Qual benefício imediato esperar?', '[{"id":"A","text":"Baixar até 20% no custo + IOPS/throughput desacoplados do tamanho"},{"id":"B","text":"Aumento automático de durabilidade para 11 nines"},{"id":"C","text":"Replicação cross-Region automática"},{"id":"D","text":"Conversão automática para SSD NVMe local"}]'::jsonb, 'A', '{"summary":"gp3 oferece preço ~20% menor que gp2 e permite provisionar IOPS (até 16k) e throughput (até 1 GB/s) independente do tamanho do volume — em gp2, IOPS escalam com tamanho.","whyCorrect":"gp3 oferece preço ~20% menor que gp2 e permite provisionar IOPS (até 16k) e throughput (até 1 GB/s) independente do tamanho do volume — em gp2, IOPS escalam com tamanho.","whyWrong":{"B":"Durabilidade EBS já é alta (99.8%-99.999%)","C":"replication não é automática","D":"gp3 ainda é network storage, não local."},"keyConcept":"Regra: gp3 = gp2 mais barato e flexível.","tutorSeeds":["Pode explicar com mais detalhe: Regra: gp3 = gp2 mais barato e flexível?","Quais cenários reais aplicam Regra: gp3 = gp2 mais barato e flexível?","Como IOPS se compara com alternativas?"]}'::jsonb, 'Cloud Technology & Services', 'Cloud Technology & Services', 'medium', 'best-practice', '["ebs","gp3","cost-optimization"]'::jsonb, 'ai-draft', 'active', now(), now()),
    ('clf-c02-tech-044', 'aws-clf', 'Uma empresa quer migrar 5 PB de fitas LTO antigas para AWS sem upload via internet (que demoraria meses). Qual serviço Snow é o mais adequado?', '[{"id":"A","text":"AWS Snowcone"},{"id":"B","text":"AWS Snowball Edge"},{"id":"C","text":"AWS Snowmobile"},{"id":"D","text":"AWS DataSync"}]'::jsonb, 'C', '{"summary":"Snowmobile é um truck de 45 pés que transfere até 100 PB por viagem — projetado para migrações em escala de exabyte.","whyCorrect":"Snowmobile é um truck de 45 pés que transfere até 100 PB por viagem — projetado para migrações em escala de exabyte. Para 5 PB seria uma única viagem.","whyWrong":{"A":"Snowcone é dispositivo de poucos TB","B":"Snowball Edge faz até ~80 TB usável por aparelho","D":"DataSync é network-based (limitado pelo link)."},"keyConcept":"Regra: >10 PB e link insuficiente = Snowmobile; até dezenas de TB = Snowball; edge IoT = Snowcone.","tutorSeeds":["Pode explicar com mais detalhe: Regra: >10 PB e link insuficiente = Snowmobile; até dezenas de TB = Snowball; edge IoT = Snowcone?","Quais cenários reais aplicam Regra: >10 PB e link insuficiente = Snowmobile; até dezenas de TB = Snowball; edge IoT = Snowcone?","Como PB se compara com alternativas?"]}'::jsonb, 'Cloud Technology & Services', 'Cloud Technology & Services', 'medium', 'scenario', '["snow","migration","hybrid"]'::jsonb, 'ai-draft', 'active', now(), now()),
    ('clf-c02-tech-045', 'aws-clf', 'Uma empresa quer manter backups on-prem com cópia automática em S3 para DR, expondo o S3 como volumes iSCSI para os servidores antigos. Qual serviço AWS atende?', '[{"id":"A","text":"AWS Storage Gateway — Volume Gateway"},{"id":"B","text":"AWS Storage Gateway — File Gateway"},{"id":"C","text":"AWS Storage Gateway — Tape Gateway"},{"id":"D","text":"AWS DataSync"}]'::jsonb, 'A', '{"summary":"Volume Gateway expõe volumes iSCSI on-prem (cached ou stored), com snapshots para S3 — ideal para integrar servidores legados a backup cloud.","whyCorrect":"Volume Gateway expõe volumes iSCSI on-prem (cached ou stored), com snapshots para S3 — ideal para integrar servidores legados a backup cloud.","whyWrong":{"B":"File Gateway expõe NFS/SMB","C":"Tape Gateway emula VTL para backups de software de fita","D":"DataSync é replicação de arquivos online (não block iSCSI)."},"keyConcept":"Regra: legado iSCSI + S3 = Volume Gateway; NFS/SMB = File Gateway; tape software = Tape Gateway.","tutorSeeds":["Pode explicar com mais detalhe: Regra: legado iSCSI + S3 = Volume Gateway; NFS/SMB = File Gateway; tape software = Tape Gateway?","Quais cenários reais aplicam Regra: legado iSCSI + S3 = Volume Gateway; NFS/SMB = File Gateway; tape software = Tape Gateway?"]}'::jsonb, 'Cloud Technology & Services', 'Cloud Technology & Services', 'hard', 'scenario', '["storage-gateway","hybrid","iscsi"]'::jsonb, 'ai-draft', 'active', now(), now()),
    ('clf-c02-tech-046', 'aws-clf', 'Um datacenter on-prem usa software de backup que escreve para fitas físicas. A empresa quer eliminar fitas mas manter o software. Qual serviço AWS atende?', '[{"id":"A","text":"AWS Backup"},{"id":"B","text":"Storage Gateway — Tape Gateway (VTL)"},{"id":"C","text":"Storage Gateway — File Gateway"},{"id":"D","text":"AWS Snowmobile"}]'::jsonb, 'B', '{"summary":"Tape Gateway expõe Virtual Tape Library (VTL) compatível com NetBackup, Veeam, etc.","whyCorrect":"Tape Gateway expõe Virtual Tape Library (VTL) compatível com NetBackup, Veeam, etc. — as ''fitas'' virtuais são armazenadas em S3 e arquivadas em Glacier, sem mexer no software de backup.","whyWrong":{"A":"AWS Backup gerencia recursos AWS","C":"File Gateway é NFS/SMB","D":"Snowmobile é one-shot bulk migration."},"keyConcept":"Regra: software de backup com fitas → Tape Gateway.","tutorSeeds":["Pode explicar com mais detalhe: Regra: software de backup com fitas → Tape Gateway?","Quais cenários reais aplicam Regra: software de backup com fitas → Tape Gateway?","Como VTL se compara com alternativas?"]}'::jsonb, 'Cloud Technology & Services', 'Cloud Technology & Services', 'hard', 'scenario', '["storage-gateway","tape","hybrid"]'::jsonb, 'ai-draft', 'active', now(), now()),
    ('clf-c02-tech-047', 'aws-clf', 'Uma equipe edge precisa processar dados em locais sem conectividade boa (navios, mineradoras) e sincronizar com AWS quando online. Qual dispositivo Snow é o mais adequado para deploy edge leve?', '[{"id":"A","text":"Snowmobile"},{"id":"B","text":"Snowball Edge Storage Optimized"},{"id":"C","text":"Snowcone"},{"id":"D","text":"AWS Outposts"}]'::jsonb, 'C', '{"summary":"Snowcone é o menor dispositivo Snow (2,1 kg), ruggedized, com 8 TB e CPU/RAM para rodar EC2/Lambda em edge — ideal para uso portátil.","whyCorrect":"Snowcone é o menor dispositivo Snow (2,1 kg), ruggedized, com 8 TB e CPU/RAM para rodar EC2/Lambda em edge — ideal para uso portátil.","whyWrong":{"A":"Snowmobile é truck para mega-migrações","B":"Snowball Edge é maior, para datacenter","D":"Outposts é rack completo on-prem managed pela AWS."},"keyConcept":"Regra: portable edge minimal = Snowcone; edge mais robusto = Snowball Edge Compute.","tutorSeeds":["Pode explicar com mais detalhe: Regra: portable edge minimal = Snowcone; edge mais robusto = Snowball Edge Compute?","Quais cenários reais aplicam Regra: portable edge minimal = Snowcone; edge mais robusto = Snowball Edge Compute?","Como TB se compara com alternativas?"]}'::jsonb, 'Cloud Technology & Services', 'Cloud Technology & Services', 'medium', 'scenario', '["snow","edge","hybrid"]'::jsonb, 'ai-draft', 'active', now(), now()),
    ('clf-c02-tech-048', 'aws-clf', 'Uma fintech precisa de banco relacional gerenciado, com Multi-AZ failover automático, suporte a Oracle e patching pela AWS. Qual serviço escolher?', '[{"id":"A","text":"Amazon Aurora"},{"id":"B","text":"Amazon RDS (engine Oracle)"},{"id":"C","text":"Amazon DynamoDB"},{"id":"D","text":"Amazon Redshift"}]'::jsonb, 'B', '{"summary":"RDS suporta engines: MySQL, PostgreSQL, MariaDB, Oracle, SQL Server e Aurora (MySQL/PG-compatível).","whyCorrect":"RDS suporta engines: MySQL, PostgreSQL, MariaDB, Oracle, SQL Server e Aurora (MySQL/PG-compatível). Multi-AZ provisiona standby sync com failover automático.","whyWrong":{"A":"Aurora não suporta Oracle","C":"DynamoDB é NoSQL key-value","D":"Redshift é data warehouse OLAP."},"keyConcept":"Regra: engine comercial gerenciado = RDS; cloud-native MySQL/PG = Aurora.","tutorSeeds":["Pode explicar com mais detalhe: Regra: engine comercial gerenciado = RDS; cloud-native MySQL/PG = Aurora?","Quais cenários reais aplicam Regra: engine comercial gerenciado = RDS; cloud-native MySQL/PG = Aurora?","Como RDS se compara com alternativas?"]}'::jsonb, 'Cloud Technology & Services', 'Cloud Technology & Services', 'easy', 'scenario', '["rds","oracle","multi-az"]'::jsonb, 'ai-draft', 'active', now(), now()),
    ('clf-c02-tech-049', 'aws-clf', 'Sobre Amazon Aurora, qual afirmação é VERDADEIRA?', '[{"id":"A","text":"Aurora é compatível com MySQL e PostgreSQL, mas não com Oracle ou SQL Server"},{"id":"B","text":"Aurora é compatível com todos os engines do RDS"},{"id":"C","text":"Aurora é NoSQL document-oriented"},{"id":"D","text":"Aurora não suporta replicas de leitura"}]'::jsonb, 'A', '{"summary":"Aurora é engine cloud-native AWS, wire-compatible com MySQL ou PostgreSQL, com storage distribuído auto-scaling (até 128 TB), 6 cópias em 3 AZs, até 15 read replicas.","whyCorrect":"Aurora é engine cloud-native AWS, wire-compatible com MySQL ou PostgreSQL, com storage distribuído auto-scaling (até 128 TB), 6 cópias em 3 AZs, até 15 read replicas.","whyWrong":{"C":"não é NoSQL","D":"Não suporta Oracle/SQL Server (use RDS para isso) suporta muitas replicas com baixa latência.","B":"Aurora é compatível APENAS com MySQL e PostgreSQL — não suporta Oracle, SQL Server, MariaDB ou outros engines. RDS suporta 6 engines (incluindo Aurora MySQL/PG, Oracle, SQL Server, MariaDB, IBM Db2). Aurora é subconjunto especializado, não substituto universal de RDS."},"keyConcept":"Regra: ''managed MySQL/PG cloud-native premium'' = Aurora.","tutorSeeds":["Pode explicar com mais detalhe: Regra: ''managed MySQL/PG cloud-native premium'' = Aurora?","Quais cenários reais aplicam Regra: ''managed MySQL/PG cloud-native premium'' = Aurora?","Como AWS se compara com alternativas?"]}'::jsonb, 'Cloud Technology & Services', 'Cloud Technology & Services', 'easy', 'recall', '["aurora","rds","relational"]'::jsonb, 'ai-draft', 'active', now(), now()),
    ('clf-c02-tech-050', 'aws-clf', 'Sobre RDS Multi-AZ vs Read Replicas, qual afirmação é CORRETA?', '[{"id":"A","text":"Read Replicas fornecem failover automático sync; Multi-AZ é só para escalar leituras"},{"id":"B","text":"Multi-AZ é para alta disponibilidade (failover sync); Read Replicas são para escalar leituras (replicação async)"},{"id":"C","text":"Os dois recursos são idênticos, apenas nomes diferentes"},{"id":"D","text":"Read Replicas não podem existir em outra Region"}]'::jsonb, 'B', '{"summary":"Multi-AZ mantém standby sync na outra AZ — failover automático em ~60-120s sem mudar endpoint.","whyCorrect":"Multi-AZ mantém standby sync na outra AZ — failover automático em ~60-120s sem mudar endpoint. Read Replicas são async (potencial lag), com endpoint próprio, para offloading de read traffic; podem ser cross-Region.","whyWrong":{"A":"Read Replicas não fazem failover automático (precisa promoção manual) Multi-AZ não atende leitura no standby (em RDS legado).","C":"Multi-AZ e Read Replicas são features DISTINTAS com propósitos diferentes — não são sinônimos. Multi-AZ usa replicação síncrona para failover automático (HA), com endpoint único. Read Replicas usam replicação assíncrona para escalar leitura, com endpoints separados. Podem coexistir.","D":"Read Replicas PODEM ser cross-Region — feature suportada nativamente em RDS para DR e atender leitores em outra geografia. Esta opção é factualmente errada. Cross-Region Read Replica é padrão recomendado para baixa latência global de leitura."},"keyConcept":"Regra: HA = Multi-AZ; Read scale = Read Replicas; ambos podem coexistir.","tutorSeeds":["Pode explicar com mais detalhe: Regra: HA = Multi-AZ; Read scale = Read Replicas; ambos podem coexistir?","Quais cenários reais aplicam Regra: HA = Multi-AZ; Read scale = Read Replicas; ambos podem coexistir?","Como AZ se compara com alternativas?"]}'::jsonb, 'Cloud Technology & Services', 'Cloud Technology & Services', 'medium', 'best-practice', '["rds","multi-az","read-replica"]'::jsonb, 'ai-draft', 'active', now(), now()),
    ('clf-c02-tech-051', 'aws-clf', 'Um DBA precisa customizar parâmetros do engine MySQL (innodb_buffer_pool_size, etc.) numa instância RDS. Qual recurso usar?', '[{"id":"A","text":"SSH na instância e editar my.cnf"},{"id":"B","text":"Custom DB Parameter Group"},{"id":"C","text":"Option Group"},{"id":"D","text":"Security Group"}]'::jsonb, 'B', '{"summary":"DB Parameter Group expõe parâmetros do engine de forma gerenciada — você cria custom group, aplica e reinicia (para parâmetros estáticos).","whyCorrect":"DB Parameter Group expõe parâmetros do engine de forma gerenciada — você cria custom group, aplica e reinicia (para parâmetros estáticos).","whyWrong":{"C":"Option Group habilita features adicionais do engine (TDE Oracle, SQL Server SSAS, etc.), não tuning","D":"Security Group é firewall.","A":"RDS é managed service — cliente NÃO tem acesso SSH à instância do banco. Editar my.cnf diretamente seria impossível. Para customizar parâmetros do engine, AWS expõe Parameter Groups (interface gerenciada), aplicáveis por console/CLI/API. SSH seria caminho em MySQL self-managed em EC2, não em RDS."},"keyConcept":"Regra: tuning = Parameter Group; features extras = Option Group.","tutorSeeds":["Pode explicar com mais detalhe: Regra: tuning = Parameter Group; features extras = Option Group?","Quais cenários reais aplicam Regra: tuning = Parameter Group; features extras = Option Group?","Como DB se compara com alternativas?"]}'::jsonb, 'Cloud Technology & Services', 'Cloud Technology & Services', 'medium', 'scenario', '["rds","parameter-group","tuning"]'::jsonb, 'ai-draft', 'active', now(), now()),
    ('clf-c02-tech-052', 'aws-clf', 'Uma equipe quer habilitar Transparent Data Encryption (TDE) num RDS Oracle. Qual recurso configurar?', '[{"id":"A","text":"DB Parameter Group"},{"id":"B","text":"Option Group"},{"id":"C","text":"Subnet Group"},{"id":"D","text":"KMS Key Policy somente"}]'::jsonb, 'B', '{"summary":"Option Group habilita features específicas do engine — TDE, OLS, Native Network Encryption para Oracle, ou TDE/SSRS para SQL Server.","whyCorrect":"Option Group habilita features específicas do engine — TDE, OLS, Native Network Encryption para Oracle, ou TDE/SSRS para SQL Server.","whyWrong":{"A":"Parameter Group é tuning","C":"Subnet Group define AZs/subnets para Multi-AZ","D":"KMS Key Policy controla quem pode usar a chave KMS — mas TDE no Oracle (e SQL Server) precisa primeiro ser HABILITADO via Option Group no RDS. Sem opção TDE adicionada ao Option Group, o engine não conhece a feature. KMS é parte do enabling (chave usada para criptografar), mas não habilita TDE sozinho."},"keyConcept":"Regra: features de engine = Option Group; tuning = Parameter Group.","tutorSeeds":["Pode explicar com mais detalhe: Regra: features de engine = Option Group; tuning = Parameter Group?","Quais cenários reais aplicam Regra: features de engine = Option Group; tuning = Parameter Group?","Como TDE se compara com alternativas?"]}'::jsonb, 'Cloud Technology & Services', 'Cloud Technology & Services', 'hard', 'scenario', '["rds","option-group","tde"]'::jsonb, 'ai-draft', 'active', now(), now()),
    ('clf-c02-tech-053', 'aws-clf', 'Sobre Amazon Aurora Serverless v2, qual afirmação é VERDADEIRA?', '[{"id":"A","text":"Aurora Serverless v2 escala capacidade automaticamente em segundos, sem provisionar instâncias"},{"id":"B","text":"Aurora Serverless v2 só roda em horário comercial"},{"id":"C","text":"Aurora Serverless v2 é incompatível com Multi-AZ"},{"id":"D","text":"Aurora Serverless v2 só suporta SQL Server"}]'::jsonb, 'A', '{"summary":"Aurora Serverless v2 ajusta capacidade (ACUs) em segundos baseado em carga, sem disruption — ideal para workloads variáveis ou imprevisíveis.","whyCorrect":"Aurora Serverless v2 ajusta capacidade (ACUs) em segundos baseado em carga, sem disruption — ideal para workloads variáveis ou imprevisíveis. Suporta Multi-AZ, MySQL e PostgreSQL.","whyWrong":{"B":"Roda 24/7 [extra: pode pausar a zero ACU em alguns cenários]","C":"Multi-AZ é suportado","D":"SQL Server não é Aurora."},"keyConcept":"Regra: workload variável = Serverless v2; carga previsível = Provisioned.","tutorSeeds":["Pode explicar com mais detalhe: Regra: workload variável = Serverless v2; carga previsível = Provisioned?","Quais cenários reais aplicam Regra: workload variável = Serverless v2; carga previsível = Provisioned?","Como ACUs se compara com alternativas?"]}'::jsonb, 'Cloud Technology & Services', 'Cloud Technology & Services', 'medium', 'recall', '["aurora","serverless","scaling"]'::jsonb, 'ai-draft', 'active', now(), now()),
    ('clf-c02-tech-054', 'aws-clf', 'Uma empresa precisa de DR cross-Region para um Aurora MySQL com RPO < 1s e RTO < 1min. Qual feature usar?', '[{"id":"A","text":"Snapshots manuais copiados para outra Region"},{"id":"B","text":"Aurora Global Database"},{"id":"C","text":"RDS Multi-AZ standard"},{"id":"D","text":"AWS Backup com schedule"}]'::jsonb, 'B', '{"summary":"Aurora Global Database replica via storage layer dedicado (não binlog) para outra Region com lag típico < 1s; failover de Region em < 1 min.","whyCorrect":"Aurora Global Database replica via storage layer dedicado (não binlog) para outra Region com lag típico < 1s; failover de Region em < 1 min.","whyWrong":{"A":"Snapshots têm RPO de horas","C":"Multi-AZ é zonal","D":"Backup é point-in-time, RTO em minutos-horas."},"keyConcept":"Regra: DR cross-Region Aurora com RPO/RTO baixos = Global Database.","tutorSeeds":["Pode explicar com mais detalhe: Regra: DR cross-Region Aurora com RPO/RTO baixos = Global Database?","Quais cenários reais aplicam Regra: DR cross-Region Aurora com RPO/RTO baixos = Global Database?"]}'::jsonb, 'Cloud Technology & Services', 'Cloud Technology & Services', 'hard', 'scenario', '["aurora","global-database","dr"]'::jsonb, 'ai-draft', 'active', now(), now()),
    ('clf-c02-tech-055', 'aws-clf', 'Uma equipe tem RDS PostgreSQL e quer restaurar o estado da DB para um momento exato de ontem (point-in-time). Que feature suporta?', '[{"id":"A","text":"RDS Automated Backups com Point-in-Time Recovery (PITR)"},{"id":"B","text":"Snapshots manuais a cada hora"},{"id":"C","text":"Read Replica lag"},{"id":"D","text":"RDS Multi-AZ failover"}]'::jsonb, 'A', '{"summary":"Automated Backups capturam snapshot diário + transaction logs em S3, permitindo restaurar para qualquer segundo dentro do retention (até 35 dias) — cria nova instância.","whyCorrect":"Automated Backups capturam snapshot diário + transaction logs em S3, permitindo restaurar para qualquer segundo dentro do retention (até 35 dias) — cria nova instância.","whyWrong":{"B":"Snapshots manuais permitem restaurar só pra aquele ponto","C":"Read Replica é replicação, não backup","D":"Multi-AZ failover não restaura passado."},"keyConcept":"Regra: PITR = automated backups habilitados.","tutorSeeds":["Pode explicar com mais detalhe: Regra: PITR = automated backups habilitados?","Quais cenários reais aplicam Regra: PITR = automated backups habilitados?"]}'::jsonb, 'Cloud Technology & Services', 'Cloud Technology & Services', 'easy', 'scenario', '["rds","backup","pitr"]'::jsonb, 'ai-draft', 'active', now(), now()),
    ('clf-c02-tech-056', 'aws-clf', 'Uma equipe migrou de RDS MySQL para Aurora MySQL e notou throughput 5x maior nas mesmas instâncias. Por que Aurora tende a ser mais rápido?', '[{"id":"A","text":"Aurora reescreve queries automaticamente"},{"id":"B","text":"Aurora usa storage distribuído otimizado, redo log offloaded e cache compartilhado entre nodes"},{"id":"C","text":"Aurora roda em chips quânticos"},{"id":"D","text":"Aurora compila MySQL em assembly customizado"}]'::jsonb, 'B', '{"summary":"Aurora separa compute de storage; o storage layer aplica redo logs distribuídos em 6 cópias 3 AZs, com cache compartilhado entre instâncias do cluster — reduz drasticamente I/O e network do compute.","whyCorrect":"Aurora separa compute de storage; o storage layer aplica redo logs distribuídos em 6 cópias 3 AZs, com cache compartilhado entre instâncias do cluster — reduz drasticamente I/O e network do compute.","whyWrong":{"A":"Não reescreve queries","D":"é fork do MySQL com mods, não compilação especial.","C":"Aurora roda em hardware AWS convencional (Intel/AMD/Graviton, x86_64 ou ARM64) — não usa ''chips quânticos''. Esta opção é absurda. Performance vem de redesign arquitetural (separação compute/storage, redo log offload, distributed log-structured storage), não de hardware exótico."},"keyConcept":"Regra: Aurora = ''MySQL/PG reimaginado para cloud''.","tutorSeeds":["Pode explicar com mais detalhe: Regra: Aurora = ''MySQL/PG reimaginado para cloud''?","Quais cenários reais aplicam Regra: Aurora = ''MySQL/PG reimaginado para cloud''?","Como AZs se compara com alternativas?"]}'::jsonb, 'Cloud Technology & Services', 'Cloud Technology & Services', 'hard', 'scenario', '["aurora","architecture","performance"]'::jsonb, 'ai-draft', 'active', now(), now()),
    ('clf-c02-tech-057', 'aws-clf', 'Uma equipe roda DynamoDB e tem padrão de tráfego imprevisível (picos abruptos). Quer evitar throttling sem provisionar capacity ociosa. Qual modo de capacity escolher?', '[{"id":"A","text":"Provisioned mode com auto scaling"},{"id":"B","text":"On-Demand mode"},{"id":"C","text":"Reserved Capacity"},{"id":"D","text":"DAX Cluster apenas"}]'::jsonb, 'B', '{"summary":"On-Demand cobra por request (RRU/WRU) sem provisionar — escala instantaneamente para picos.","whyCorrect":"On-Demand cobra por request (RRU/WRU) sem provisionar — escala instantaneamente para picos. Ideal para cargas imprevisíveis ou novos workloads.","whyWrong":{"A":"Provisioned auto scaling tem janela de adaptação e pode throttlar em picos abruptos DAX é cache, não capacity mode.","C":"Reserved Capacity é discount em Provisioned","D":"DAX (DynamoDB Accelerator) é cache em memória in-front de DynamoDB — reduz latência de leitura para microssegundos, mas NÃO substitui o modo de capacity da tabela. Cliente ainda precisa escolher Provisioned ou On-Demand para o storage layer. DAX seria adição complementar, não resposta ao problema de capacity."},"keyConcept":"Regra: imprevisível = On-Demand; previsível e steady = Provisioned (mais barato).","tutorSeeds":["Pode explicar com mais detalhe: Regra: imprevisível = On-Demand; previsível e steady = Provisioned (mais barato)?","Quais cenários reais aplicam Regra: imprevisível = On-Demand; previsível e steady = Provisioned (mais barato)?","Como RRU se compara com alternativas?"]}'::jsonb, 'Cloud Technology & Services', 'Cloud Technology & Services', 'medium', 'best-practice', '["dynamodb","on-demand","capacity"]'::jsonb, 'ai-draft', 'active', now(), now()),
    ('clf-c02-tech-058', 'aws-clf', 'Sobre Amazon DynamoDB, qual afirmação é VERDADEIRA?', '[{"id":"A","text":"É um banco relacional gerenciado, com SQL completo"},{"id":"B","text":"É um banco NoSQL key-value e document, com latência single-digit ms em qualquer escala"},{"id":"C","text":"É um data warehouse columnar para BI"},{"id":"D","text":"É um banco grafo otimizado para social networks"}]'::jsonb, 'B', '{"summary":"DynamoDB é NoSQL serverless (key-value + document), com latência ms consistente, escala automática, replicação multi-AZ e features como Global Tables, Streams, TTL, transações.","whyCorrect":"DynamoDB é NoSQL serverless (key-value + document), com latência ms consistente, escala automática, replicação multi-AZ e features como Global Tables, Streams, TTL, transações.","whyWrong":{"A":"Não é relacional (use RDS/Aurora)","C":"não é warehouse (use Redshift)","D":"grafo é Neptune."},"keyConcept":"Regra: NoSQL hyperscale serverless AWS = DynamoDB.","tutorSeeds":["Pode explicar com mais detalhe: Regra: NoSQL hyperscale serverless AWS = DynamoDB?","Quais cenários reais aplicam Regra: NoSQL hyperscale serverless AWS = DynamoDB?","Como AZ se compara com alternativas?"]}'::jsonb, 'Cloud Technology & Services', 'Cloud Technology & Services', 'easy', 'recall', '["dynamodb","nosql","key-value"]'::jsonb, 'ai-draft', 'active', now(), now()),
    ('clf-c02-tech-059', 'aws-clf', 'Um time precisa de cache in-memory sub-millissegundo na frente de um RDS MySQL para reduzir carga em queries repetitivas. Qual serviço usar?', '[{"id":"A","text":"Amazon ElastiCache (Redis ou Memcached)"},{"id":"B","text":"Amazon S3 com CloudFront"},{"id":"C","text":"DynamoDB DAX"},{"id":"D","text":"Amazon Athena"}]'::jsonb, 'A', '{"summary":"ElastiCache é cache in-memory gerenciado: Redis (rich datatypes, replicação, persistence, pub/sub) ou Memcached (simples, multi-thread).","whyCorrect":"ElastiCache é cache in-memory gerenciado: Redis (rich datatypes, replicação, persistence, pub/sub) ou Memcached (simples, multi-thread). Ideal para session store, leaderboards, cache de DB.","whyWrong":{"B":"S3+CloudFront é cache de objetos estáticos","C":"DAX é específico para DynamoDB","D":"Athena é query em S3."},"keyConcept":"Regra: cache em memória AWS = ElastiCache.","tutorSeeds":["Pode explicar com mais detalhe: Regra: cache em memória AWS = ElastiCache?","Quais cenários reais aplicam Regra: cache em memória AWS = ElastiCache?","Como DB se compara com alternativas?"]}'::jsonb, 'Cloud Technology & Services', 'Cloud Technology & Services', 'easy', 'scenario', '["elasticache","redis","cache"]'::jsonb, 'ai-draft', 'active', now(), now()),
    ('clf-c02-tech-060', 'aws-clf', 'Uma empresa precisa de cache para DynamoDB que entregue microssegundos de latência sem alterar muito a aplicação. Qual serviço usar?', '[{"id":"A","text":"ElastiCache for Redis"},{"id":"B","text":"DynamoDB Accelerator (DAX)"},{"id":"C","text":"CloudFront na frente da DynamoDB"},{"id":"D","text":"Athena query cache"}]'::jsonb, 'B', '{"summary":"DAX é cache in-memory write-through dedicado para DynamoDB — API compatível, reduz latência de leitura para microssegundos com mudança mínima de código.","whyCorrect":"DAX é cache in-memory write-through dedicado para DynamoDB — API compatível, reduz latência de leitura para microssegundos com mudança mínima de código.","whyWrong":{"A":"Redis funciona mas exige código de cache manual","C":"CloudFront não cacheia chamadas API DynamoDB diretamente","D":"Athena é query analytics."},"keyConcept":"Regra: cache nativo DynamoDB = DAX.","tutorSeeds":["Pode explicar com mais detalhe: Regra: cache nativo DynamoDB = DAX?","Quais cenários reais aplicam Regra: cache nativo DynamoDB = DAX?","Como DAX se compara com alternativas?"]}'::jsonb, 'Cloud Technology & Services', 'Cloud Technology & Services', 'medium', 'scenario', '["dynamodb","dax","cache"]'::jsonb, 'ai-draft', 'active', now(), now()),
    ('clf-c02-tech-061', 'aws-clf', 'Uma empresa quer rodar queries SQL ad-hoc sobre logs em S3 sem provisionar cluster nem ETL. Qual serviço escolher?', '[{"id":"A","text":"Amazon Redshift"},{"id":"B","text":"Amazon Athena"},{"id":"C","text":"Amazon EMR"},{"id":"D","text":"Amazon RDS"}]'::jsonb, 'B', '{"summary":"Athena é query engine serverless baseado em Presto/Trino — query SQL direto sobre S3 (CSV, JSON, Parquet) pagando por TB scaneado.","whyCorrect":"Athena é query engine serverless baseado em Presto/Trino — query SQL direto sobre S3 (CSV, JSON, Parquet) pagando por TB scaneado. Zero infra.","whyWrong":{"A":"Redshift exige cluster","C":"Amazon EMR é cluster Hadoop/Spark/Hive managed — exige provisionar cluster (master, core, task nodes), pagar por instâncias ativas, e operacionalizar jobs Spark/Hive. Para ''queries SQL ad-hoc sem cluster'', EMR é overhead enorme. EMR seria correto para ''pipeline ETL pesado com Spark sobre 100TB''.","D":"Amazon RDS é banco relacional gerenciado para OLTP — não escala para queries analíticas sobre TBs em S3. Carregaria os logs no banco (caro e demorado) antes de poder query-lar. RDS seria correto para ''banco transacional de aplicação'', não para análise de logs."},"keyConcept":"Regra: SQL ad-hoc on S3 + zero infra = Athena; warehouse petabyte = Redshift; ETL/big data complexo = EMR.","tutorSeeds":["Pode explicar com mais detalhe: Regra: SQL ad-hoc on S3 + zero infra = Athena; warehouse petabyte = Redshift; ETL/big data complexo = EMR?","Quais cenários reais aplicam Regra: SQL ad-hoc on S3 + zero infra = Athena; warehouse petabyte = Redshift; ETL/big data complexo = EMR?","Como SQL se compara com alternativas?"]}'::jsonb, 'Cloud Technology & Services', 'Cloud Technology & Services', 'easy', 'scenario', '["athena","s3","analytics"]'::jsonb, 'ai-draft', 'active', now(), now()),
    ('clf-c02-tech-062', 'aws-clf', 'Uma empresa precisa de data warehouse para BI sobre 100 TB de dados estruturados com queries analíticas complexas e usuários concorrentes. Qual serviço escolher?', '[{"id":"A","text":"Amazon Aurora"},{"id":"B","text":"Amazon Redshift"},{"id":"C","text":"Amazon DynamoDB"},{"id":"D","text":"Amazon Neptune"}]'::jsonb, 'B', '{"summary":"Redshift é data warehouse columnar massively parallel (MPP), otimizado para queries analíticas em PB-scale com integração BI (QuickSight, Tableau).","whyCorrect":"Redshift é data warehouse columnar massively parallel (MPP), otimizado para queries analíticas em PB-scale com integração BI (QuickSight, Tableau). Pode também usar Spectrum para queries em S3.","whyWrong":{"A":"Aurora é OLTP transacional","C":"DynamoDB é NoSQL","D":"Neptune é grafo."},"keyConcept":"Regra: OLAP/warehouse = Redshift; OLTP = RDS/Aurora; NoSQL = DynamoDB; grafo = Neptune.","tutorSeeds":["Pode explicar com mais detalhe: Regra: OLAP/warehouse = Redshift; OLTP = RDS/Aurora; NoSQL = DynamoDB; grafo = Neptune?","Quais cenários reais aplicam Regra: OLAP/warehouse = Redshift; OLTP = RDS/Aurora; NoSQL = DynamoDB; grafo = Neptune?","Como MPP se compara com alternativas?"]}'::jsonb, 'Cloud Technology & Services', 'Cloud Technology & Services', 'easy', 'scenario', '["redshift","warehouse","analytics"]'::jsonb, 'ai-draft', 'active', now(), now()),
    ('clf-c02-tech-063', 'aws-clf', 'Uma rede social precisa armazenar e consultar relacionamentos de amizade (grafos de seguidores). Qual banco AWS é o mais adequado?', '[{"id":"A","text":"Amazon Aurora"},{"id":"B","text":"Amazon DocumentDB"},{"id":"C","text":"Amazon Neptune"},{"id":"D","text":"Amazon Timestream"}]'::jsonb, 'C', '{"summary":"Neptune é graph database managed, suporta Gremlin, openCypher e SPARQL — ideal para social networks, fraud detection, recomendações e knowledge graphs.","whyCorrect":"Neptune é graph database managed, suporta Gremlin, openCypher e SPARQL — ideal para social networks, fraud detection, recomendações e knowledge graphs.","whyWrong":{"A":"Aurora é relacional","B":"DocumentDB é compatível com MongoDB (document)","D":"Timestream é time-series."},"keyConcept":"Regra: grafo na AWS = Neptune.","tutorSeeds":["Pode explicar com mais detalhe: Regra: grafo na AWS = Neptune?","Quais cenários reais aplicam Regra: grafo na AWS = Neptune?","Como SPARQL se compara com alternativas?"]}'::jsonb, 'Cloud Technology & Services', 'Cloud Technology & Services', 'easy', 'scenario', '["neptune","graph","database"]'::jsonb, 'ai-draft', 'active', now(), now()),
    ('clf-c02-tech-064', 'aws-clf', 'Uma equipe usa MongoDB on-prem e quer migrar para AWS mantendo APIs e drivers MongoDB sem refactoring. Qual serviço escolher?', '[{"id":"A","text":"Amazon DynamoDB"},{"id":"B","text":"Amazon DocumentDB (with MongoDB compatibility)"},{"id":"C","text":"Amazon Aurora PostgreSQL"},{"id":"D","text":"Amazon ElastiCache for Redis"}]'::jsonb, 'B', '{"summary":"DocumentDB é document store compatível com MongoDB API (drivers e tools mongo) — managed, escalável, com Multi-AZ.","whyCorrect":"DocumentDB é document store compatível com MongoDB API (drivers e tools mongo) — managed, escalável, com Multi-AZ.","whyWrong":{"A":"DynamoDB tem outra API","C":"Aurora é SQL","D":"Redis é cache."},"keyConcept":"Regra: workload Mongo lift-and-shift = DocumentDB; greenfield NoSQL na AWS = DynamoDB.","tutorSeeds":["Pode explicar com mais detalhe: Regra: workload Mongo lift-and-shift = DocumentDB; greenfield NoSQL na AWS = DynamoDB?","Quais cenários reais aplicam Regra: workload Mongo lift-and-shift = DocumentDB; greenfield NoSQL na AWS = DynamoDB?","Como API se compara com alternativas?"]}'::jsonb, 'Cloud Technology & Services', 'Cloud Technology & Services', 'medium', 'scenario', '["documentdb","mongodb","nosql"]'::jsonb, 'ai-draft', 'active', now(), now()),
    ('clf-c02-tech-065', 'aws-clf', 'Sobre DynamoDB Global Tables, qual afirmação é VERDADEIRA?', '[{"id":"A","text":"Global Tables fornecem replicação multi-Region active-active automática"},{"id":"B","text":"Global Tables só permitem leitura em outra Region (read-only replica)"},{"id":"C","text":"Global Tables requerem cluster ElastiCache"},{"id":"D","text":"Global Tables só estão disponíveis para Provisioned mode"}]'::jsonb, 'A', '{"summary":"Global Tables replicam writes em múltiplas Regions com last-writer-wins, permitindo apps multi-Region active-active com leitura/escrita local.","whyCorrect":"Global Tables replicam writes em múltiplas Regions com last-writer-wins, permitindo apps multi-Region active-active com leitura/escrita local.","whyWrong":{"B":"Não é só leitura","C":"não precisa ElastiCache","D":"funciona com On-Demand e Provisioned."},"keyConcept":"Regra: app global low-latency = Global Tables.","tutorSeeds":["Pode explicar com mais detalhe: Regra: app global low-latency = Global Tables?","Quais cenários reais aplicam Regra: app global low-latency = Global Tables?"]}'::jsonb, 'Cloud Technology & Services', 'Cloud Technology & Services', 'medium', 'recall', '["dynamodb","global-tables","multi-region"]'::jsonb, 'ai-draft', 'active', now(), now()),
    ('clf-c02-tech-066', 'aws-clf', 'Sobre Amazon VPC, qual afirmação é VERDADEIRA?', '[{"id":"A","text":"VPC é um data center virtual logicamente isolado, com CIDR próprio, subnets, route tables e gateways controlados pelo cliente"},{"id":"B","text":"VPC é um serviço de DNS gerenciado"},{"id":"C","text":"VPC só funciona dentro de uma única AZ"},{"id":"D","text":"VPC requer pagamento por GB de tráfego dentro do CIDR"}]'::jsonb, 'A', '{"summary":"VPC é a rede virtual lógica isolada do cliente em uma Region; cliente define CIDR, subnets (por AZ), route tables, Internet Gateway, NAT, NACLs e Security Groups.","whyCorrect":"VPC é a rede virtual lógica isolada do cliente em uma Region; cliente define CIDR, subnets (por AZ), route tables, Internet Gateway, NAT, NACLs e Security Groups.","whyWrong":{"D":"tráfego dentro da VPC não é cobrado por GB (cross-AZ tem fee).","B":"VPC NÃO é serviço DNS — é rede virtual isolada (CIDR, subnets, routing, gateways). DNS em AWS é Route 53 (público) ou Route 53 Resolver (dentro da VPC). Esta opção confunde dois serviços completamente distintos.","C":"VPC abrange uma REGION inteira — pode ter subnets em MÚLTIPLAS AZs dentro da Region. Multi-AZ é base do design HA em VPC. Esta opção é factualmente errada; VPC é regional, não zonal."},"keyConcept":"Regra: VPC = sandbox de rede regional do cliente.","tutorSeeds":["Pode explicar com mais detalhe: Regra: VPC = sandbox de rede regional do cliente?","Quais cenários reais aplicam Regra: VPC = sandbox de rede regional do cliente?","Como VPC se compara com alternativas?"]}'::jsonb, 'Cloud Technology & Services', 'Cloud Technology & Services', 'easy', 'recall', '["vpc","networking","fundamentals"]'::jsonb, 'ai-draft', 'active', now(), now()),
    ('clf-c02-tech-067', 'aws-clf', 'Uma empresa quer que instâncias EC2 em subnet privada acessem a internet (para baixar updates) sem serem alcançáveis a partir da internet. Qual recurso usar?', '[{"id":"A","text":"Internet Gateway na subnet privada"},{"id":"B","text":"NAT Gateway numa subnet pública, com route table das privadas apontando para ele"},{"id":"C","text":"VPC Peering"},{"id":"D","text":"Direct Connect"}]'::jsonb, 'B', '{"summary":"NAT Gateway permite tráfego outbound iniciado pela subnet privada para a internet, mas NÃO permite inbound iniciado de fora — ideal para updates, API calls externas.","whyCorrect":"NAT Gateway permite tráfego outbound iniciado pela subnet privada para a internet, mas NÃO permite inbound iniciado de fora — ideal para updates, API calls externas.","whyWrong":{"A":"Internet Gateway exige IP público e expõe inbound também","C":"Peering conecta VPCs","D":"Direct Connect conecta on-prem."},"keyConcept":"Regra: ''sair sem ser alcançado'' = NAT Gateway; ''ser alcançado'' = IGW + Elastic IP/ALB.","tutorSeeds":["Pode explicar com mais detalhe: Regra: ''sair sem ser alcançado'' = NAT Gateway; ''ser alcançado'' = IGW + Elastic IP/ALB?","Quais cenários reais aplicam Regra: ''sair sem ser alcançado'' = NAT Gateway; ''ser alcançado'' = IGW + Elastic IP/ALB?","Como NAT se compara com alternativas?"]}'::jsonb, 'Cloud Technology & Services', 'Cloud Technology & Services', 'easy', 'scenario', '["vpc","nat-gateway","networking"]'::jsonb, 'ai-draft', 'active', now(), now()),
    ('clf-c02-tech-068', 'aws-clf', 'Uma empresa tem duas VPCs em Regions diferentes e quer comunicação privada entre elas (sem trânsito pela internet). Qual recurso usar?', '[{"id":"A","text":"Inter-Region VPC Peering"},{"id":"B","text":"Public Internet com TLS"},{"id":"C","text":"Direct Connect"},{"id":"D","text":"AWS Outposts"}]'::jsonb, 'A', '{"summary":"VPC Peering (incluindo inter-Region) cria conexão 1-para-1 privada usando backbone AWS, sem trafegar pela internet.","whyCorrect":"VPC Peering (incluindo inter-Region) cria conexão 1-para-1 privada usando backbone AWS, sem trafegar pela internet. Não é transitivo (peering A↔B + B↔C não dá A↔C).","whyWrong":{"B":"Internet pública não atende ''sem internet''","C":"Direct Connect conecta on-prem à AWS","D":"Outposts é rack on-prem."},"keyConcept":"Regra: 2 VPCs + comunicação privada = Peering; muitas VPCs = Transit Gateway.","tutorSeeds":["Pode explicar com mais detalhe: Regra: 2 VPCs + comunicação privada = Peering; muitas VPCs = Transit Gateway?","Quais cenários reais aplicam Regra: 2 VPCs + comunicação privada = Peering; muitas VPCs = Transit Gateway?","Como VPC se compara com alternativas?"]}'::jsonb, 'Cloud Technology & Services', 'Cloud Technology & Services', 'medium', 'scenario', '["vpc","peering","networking"]'::jsonb, 'ai-draft', 'active', now(), now()),
    ('clf-c02-tech-069', 'aws-clf', 'Uma empresa tem 30 VPCs e duas conexões VPN, e a malha de peering virou inviável. Qual serviço simplifica esse cenário?', '[{"id":"A","text":"VPC Peering em malha completa"},{"id":"B","text":"AWS Transit Gateway"},{"id":"C","text":"Internet Gateway compartilhado"},{"id":"D","text":"AWS Site-to-Site VPN extra"}]'::jsonb, 'B', '{"summary":"Transit Gateway é hub-and-spoke regional que conecta VPCs, VPNs e Direct Connect — uma única conexão central em vez de malha quadrática de peerings.","whyCorrect":"Transit Gateway é hub-and-spoke regional que conecta VPCs, VPNs e Direct Connect — uma única conexão central em vez de malha quadrática de peerings.","whyWrong":{"A":"Malha peering O(n²) é inviável > 10 VPCs","C":"Internet Gateway dá saída para internet pública — não conecta VPCs entre si. IGW não resolve mesh de peering; é mecanismo de egress para internet, conceito ortogonal a connectivity entre VPCs.","D":"VPN Site-to-Site adicional não simplifica o problema — cada VPN ainda conecta DC on-prem a UMA VPC, perpetuando a complexidade de gerenciar N conexões. Para 30 VPCs interconectadas, o hub é a solução escalável (Transit Gateway), não mais túneis VPN ponto-a-ponto."},"keyConcept":"Regra: >5 VPCs e VPNs = Transit Gateway.","tutorSeeds":["Pode explicar com mais detalhe: Regra: >5 VPCs e VPNs = Transit Gateway?","Quais cenários reais aplicam Regra: >5 VPCs e VPNs = Transit Gateway?","Como VPCs se compara com alternativas?"]}'::jsonb, 'Cloud Technology & Services', 'Cloud Technology & Services', 'medium', 'best-practice', '["vpc","transit-gateway","networking"]'::jsonb, 'ai-draft', 'active', now(), now()),
    ('clf-c02-tech-070', 'aws-clf', 'Uma empresa precisa de conexão dedicada de 10 Gbps com baixa latência consistente entre seu datacenter e AWS, sem usar a internet. Qual serviço atende?', '[{"id":"A","text":"Site-to-Site VPN"},{"id":"B","text":"AWS Direct Connect"},{"id":"C","text":"AWS Client VPN"},{"id":"D","text":"Internet Gateway com TLS"}]'::jsonb, 'B', '{"summary":"Direct Connect é link físico dedicado (1/10/100 Gbps) entre datacenter do cliente e AWS, com latência baixa consistente e bypass da internet.","whyCorrect":"Direct Connect é link físico dedicado (1/10/100 Gbps) entre datacenter do cliente e AWS, com latência baixa consistente e bypass da internet. Provisionamento leva semanas.","whyWrong":{"A":"Site-to-Site VPN usa internet pública (latência variável)","C":"Client VPN é para usuários remotos individuais","D":"IGW+TLS ainda é internet."},"keyConcept":"Regra: bandwidth dedicada/baixa latência = Direct Connect; rápido e barato = VPN.","tutorSeeds":["Pode explicar com mais detalhe: Regra: bandwidth dedicada/baixa latência = Direct Connect; rápido e barato = VPN?","Quais cenários reais aplicam Regra: bandwidth dedicada/baixa latência = Direct Connect; rápido e barato = VPN?","Como AWS se compara com alternativas?"]}'::jsonb, 'Cloud Technology & Services', 'Cloud Technology & Services', 'easy', 'scenario', '["direct-connect","hybrid","networking"]'::jsonb, 'ai-draft', 'active', now(), now()),
    ('clf-c02-tech-071', 'aws-clf', 'Uma startup precisa de VPN site-to-site rápida de configurar, encriptada, para POC com seu on-prem. Qual serviço escolher?', '[{"id":"A","text":"AWS Direct Connect"},{"id":"B","text":"AWS Site-to-Site VPN"},{"id":"C","text":"AWS Outposts"},{"id":"D","text":"Storage Gateway"}]'::jsonb, 'B', '{"summary":"Site-to-Site VPN cria túnel IPsec entre Virtual Private Gateway/TGW e Customer Gateway do cliente — provisionado em minutos, encriptado, usa internet pública.","whyCorrect":"Site-to-Site VPN cria túnel IPsec entre Virtual Private Gateway/TGW e Customer Gateway do cliente — provisionado em minutos, encriptado, usa internet pública.","whyWrong":{"A":"Direct Connect leva semanas e é caro","C":"Outposts é hardware AWS no datacenter","D":"Storage Gateway é storage."},"keyConcept":"Regra: POC + rápido = VPN; produção/throughput = Direct Connect (ou DX+VPN).","tutorSeeds":["Pode explicar com mais detalhe: Regra: POC + rápido = VPN; produção/throughput = Direct Connect (ou DX+VPN)?","Quais cenários reais aplicam Regra: POC + rápido = VPN; produção/throughput = Direct Connect (ou DX+VPN)?","Como VPN se compara com alternativas?"]}'::jsonb, 'Cloud Technology & Services', 'Cloud Technology & Services', 'easy', 'best-practice', '["vpn","hybrid","networking"]'::jsonb, 'ai-draft', 'active', now(), now()),
    ('clf-c02-tech-072', 'aws-clf', 'Uma equipe quer servir arquivos estáticos (imagens, JS, CSS) de S3 com baixa latência globalmente. Qual serviço usar?', '[{"id":"A","text":"Amazon CloudFront"},{"id":"B","text":"AWS Global Accelerator"},{"id":"C","text":"S3 Transfer Acceleration"},{"id":"D","text":"Route 53 com latency-based routing"}]'::jsonb, 'A', '{"summary":"CloudFront é CDN com 600+ edge locations: cacheia conteúdo estático/dinâmico perto dos usuários, suporta HTTPS, OAC para S3, custom origins.","whyCorrect":"CloudFront é CDN com 600+ edge locations: cacheia conteúdo estático/dinâmico perto dos usuários, suporta HTTPS, OAC para S3, custom origins.","whyWrong":{"B":"Global Accelerator é para TCP/UDP não-cacheável (gaming, APIs)","C":"Transfer Acceleration acelera upload, não distribuição","D":"Route 53 é DNS, não cache."},"keyConcept":"Regra: conteúdo cacheável global = CloudFront.","tutorSeeds":["Pode explicar com mais detalhe: Regra: conteúdo cacheável global = CloudFront?","Quais cenários reais aplicam Regra: conteúdo cacheável global = CloudFront?","Como CDN se compara com alternativas?"]}'::jsonb, 'Cloud Technology & Services', 'Cloud Technology & Services', 'easy', 'scenario', '["cloudfront","cdn","networking"]'::jsonb, 'ai-draft', 'active', now(), now()),
    ('clf-c02-tech-073', 'aws-clf', 'Sobre Amazon Route 53, qual afirmação é VERDADEIRA?', '[{"id":"A","text":"É um serviço de CDN com edge locations"},{"id":"B","text":"É um serviço DNS gerenciado com routing policies (simple, weighted, latency, failover, geolocation, multivalue)"},{"id":"C","text":"É um firewall L7"},{"id":"D","text":"É um serviço de load balancing intra-VPC"}]'::jsonb, 'B', '{"summary":"Route 53 é DNS authoritativo + registrar + health checks, com 7 routing policies para load balancing, failover e geo.","whyCorrect":"Route 53 é DNS authoritativo + registrar + health checks, com 7 routing policies para load balancing, failover e geo.","whyWrong":{"C":"firewall L7 é WAF","D":"LB intra-VPC é ELB.","A":"Route 53 é serviço DNS (porta 53, daí o nome) — NÃO é CDN. Route 53 retorna endereços IP/DNS conforme routing policies, mas não cacheia conteúdo. CDN com edge locations é Amazon CloudFront. Esta opção confunde dois serviços diferentes da AWS."},"keyConcept":"Regra: DNS na AWS = Route 53; nome reflete porta 53.","tutorSeeds":["Pode explicar com mais detalhe: Regra: DNS na AWS = Route 53; nome reflete porta 53?","Quais cenários reais aplicam Regra: DNS na AWS = Route 53; nome reflete porta 53?","Como DNS se compara com alternativas?"]}'::jsonb, 'Cloud Technology & Services', 'Cloud Technology & Services', 'easy', 'recall', '["route53","dns","networking"]'::jsonb, 'ai-draft', 'active', now(), now()),
    ('clf-c02-tech-074', 'aws-clf', 'Uma empresa quer rotear usuários para a Region mais próxima geograficamente automaticamente. Qual routing policy do Route 53 usar?', '[{"id":"A","text":"Simple routing"},{"id":"B","text":"Weighted routing"},{"id":"C","text":"Latency-based routing"},{"id":"D","text":"Failover routing"}]'::jsonb, 'C', '{"summary":"Latency-based routing escolhe Region com menor latência medida ao DNS resolver do cliente — geralmente a mais próxima geograficamente, mas mais preciso que geo.","whyCorrect":"Latency-based routing escolhe Region com menor latência medida ao DNS resolver do cliente — geralmente a mais próxima geograficamente, mas mais preciso que geo.","whyWrong":{"A":"Simple é 1 record Geolocation routing usa localização do client mas pode não refletir latência real.","B":"Weighted distribui por peso (canary deploys, A/B)","D":"Failover ativa standby"},"keyConcept":"Regra: ''mais rápido por cliente'' = Latency.","tutorSeeds":["Pode explicar com mais detalhe: Regra: ''mais rápido por cliente'' = Latency?","Quais cenários reais aplicam Regra: ''mais rápido por cliente'' = Latency?","Como DNS se compara com alternativas?"]}'::jsonb, 'Cloud Technology & Services', 'Cloud Technology & Services', 'medium', 'scenario', '["route53","latency-routing","dns"]'::jsonb, 'ai-draft', 'active', now(), now()),
    ('clf-c02-tech-075', 'aws-clf', 'Uma empresa quer servir 90% do tráfego para a versão production e 10% para uma nova versão para canary testing via DNS. Qual routing policy usar?', '[{"id":"A","text":"Failover routing"},{"id":"B","text":"Weighted routing"},{"id":"C","text":"Geolocation routing"},{"id":"D","text":"Multivalue routing"}]'::jsonb, 'B', '{"summary":"Weighted routing permite distribuir tráfego entre records pelo peso (ex: 90/10) — perfeito para canary, A/B, blue/green deploys.","whyCorrect":"Weighted routing permite distribuir tráfego entre records pelo peso (ex: 90/10) — perfeito para canary, A/B, blue/green deploys.","whyWrong":{"A":"Failover é ativo-passivo Multivalue retorna múltiplos values para client failover.","C":"Geolocation é por país/continente","D":"Multivalue routing retorna múltiplos IPs em resposta DNS (até 8) e o cliente DNS escolhe um — distribui sem peso explícito (round-robin de facto). Não dá controle de proporção (90/10). Multivalue seria correto para ''load balancing simples de múltiplos endpoints igualmente capazes'', não para canary com proporção específica."},"keyConcept":"Regra: split por porcentagem = Weighted.","tutorSeeds":["Pode explicar com mais detalhe: Regra: split por porcentagem = Weighted?","Quais cenários reais aplicam Regra: split por porcentagem = Weighted?"]}'::jsonb, 'Cloud Technology & Services', 'Cloud Technology & Services', 'medium', 'scenario', '["route53","weighted-routing","canary"]'::jsonb, 'ai-draft', 'active', now(), now()),
    ('clf-c02-tech-076', 'aws-clf', 'Sobre Security Group vs Network ACL em VPC, qual afirmação é VERDADEIRA?', '[{"id":"A","text":"Security Group é stateful (no nível da ENI) e por padrão nega tudo inbound; NACL é stateless (no nível da subnet)"},{"id":"B","text":"Os dois são stateless idênticos"},{"id":"C","text":"NACL é stateful e Security Group stateless"},{"id":"D","text":"Security Group está no nível da Region, NACL no nível global"}]'::jsonb, 'A', '{"summary":"SG: stateful (return traffic auto-permitido), no nível da ENI/instância, default deny inbound + allow outbound, só regras allow.","whyCorrect":"SG: stateful (return traffic auto-permitido), no nível da ENI/instância, default deny inbound + allow outbound, só regras allow. NACL: stateless (precisa regra ida E volta), nível subnet, default permite tudo, suporta allow e deny ordenadas.","whyWrong":{"B":"Não são idênticos","C":"SG é stateful","D":"Security Group é objeto regional (atrelado a VPC, que é regional) e NACL também é regional (atrelado a subnet, que é zonal dentro de Region). Nenhum dos dois é ''global''. Esta opção é factualmente errada — os dois são construtos de VPC, dentro do escopo de uma Region."},"keyConcept":"Regra: SG = firewall de host; NACL = firewall de subnet.","tutorSeeds":["Pode explicar com mais detalhe: Regra: SG = firewall de host; NACL = firewall de subnet?","Quais cenários reais aplicam Regra: SG = firewall de host; NACL = firewall de subnet?","Como SG se compara com alternativas?"]}'::jsonb, 'Cloud Technology & Services', 'Cloud Technology & Services', 'medium', 'recall', '["vpc","security-group","nacl"]'::jsonb, 'ai-draft', 'active', now(), now()),
    ('clf-c02-tech-077', 'aws-clf', 'Uma equipe quer permitir que EC2 em subnet privada acesse S3 sem que o tráfego saia para a internet. Qual recurso usar?', '[{"id":"A","text":"NAT Gateway"},{"id":"B","text":"VPC Gateway Endpoint para S3"},{"id":"C","text":"Internet Gateway"},{"id":"D","text":"Direct Connect"}]'::jsonb, 'B', '{"summary":"Gateway Endpoints (S3 e DynamoDB) permitem acesso privado pela backbone AWS, sem NAT, sem internet, sem cobrança de data transfer extra.","whyCorrect":"Gateway Endpoints (S3 e DynamoDB) permitem acesso privado pela backbone AWS, sem NAT, sem internet, sem cobrança de data transfer extra.","whyWrong":{"C":"NAT envia para internet (cara)","D":"Direct Connect é on-prem.","A":"NAT Gateway permite que EC2 em subnet privada saia para INTERNET (incluindo S3 público) — mas o tráfego ainda sai da VPC para internet, gera custo de NAT (~$0.045/h + $0.045/GB) e expõe SLA da rota internet. VPC Gateway Endpoint mantém tráfego inteiramente dentro da rede AWS, sem internet, sem custo de NAT."},"keyConcept":"Regra: S3/DynamoDB privado = Gateway Endpoint; outros serviços = Interface Endpoint (PrivateLink).","tutorSeeds":["Pode explicar com mais detalhe: Regra: S3/DynamoDB privado = Gateway Endpoint; outros serviços = Interface Endpoint (PrivateLink)?","Quais cenários reais aplicam Regra: S3/DynamoDB privado = Gateway Endpoint; outros serviços = Interface Endpoint (PrivateLink)?","Como AWS se compara com alternativas?"]}'::jsonb, 'Cloud Technology & Services', 'Cloud Technology & Services', 'medium', 'best-practice', '["vpc","vpc-endpoint","s3"]'::jsonb, 'ai-draft', 'active', now(), now()),
    ('clf-c02-tech-078', 'aws-clf', 'Sobre Amazon CloudFront, qual afirmação é VERDADEIRA?', '[{"id":"A","text":"Suporta TLS/HTTPS, custom domains, cache de conteúdo estático e dinâmico, signed URLs e integração com WAF, Shield, S3"},{"id":"B","text":"Suporta apenas conteúdo estático em S3"},{"id":"C","text":"Não suporta cache de conteúdo dinâmico"},{"id":"D","text":"Só funciona em uma Region por distribution"}]'::jsonb, 'A', '{"summary":"CloudFront é CDN global completo: edge locations em 90+ países, suporta múltiplas origins (S3, ALB, EC2, on-prem), signed URLs/cookies, Lambda@Edge/CloudFront Functions, WAF, Shield Standard incluído.","whyCorrect":"CloudFront é CDN global completo: edge locations em 90+ países, suporta múltiplas origins (S3, ALB, EC2, on-prem), signed URLs/cookies, Lambda@Edge/CloudFront Functions, WAF, Shield Standard incluído.","whyWrong":{"B":"Suporta qualquer HTTP origin, estático ou dinâmico","C":"CloudFront SUPORTA cache de conteúdo dinâmico — desde 2017 oferece TTL configurável, Cache Behaviors por path, query string forwarding, e Lambda@Edge para lógica dinâmica. Apps dinâmicos podem cachear respostas por segundos para reduzir load no origin. Esta opção contradiz a documentação atual.","D":"CloudFront É CDN global — uma distribution serve usuários de TODAS as edge locations do mundo, sem restrição a uma Region. Origin pode estar em uma Region, mas edge locations distribuem o conteúdo globalmente. Esta opção é factualmente errada."},"keyConcept":"Regra: CDN AWS = CloudFront, multi-purpose.","tutorSeeds":["Pode explicar com mais detalhe: Regra: CDN AWS = CloudFront, multi-purpose?","Quais cenários reais aplicam Regra: CDN AWS = CloudFront, multi-purpose?","Como CDN se compara com alternativas?"]}'::jsonb, 'Cloud Technology & Services', 'Cloud Technology & Services', 'easy', 'recall', '["cloudfront","cdn","features"]'::jsonb, 'ai-draft', 'active', now(), now()),
    ('clf-c02-tech-079', 'aws-clf', 'Uma equipe registra um domínio custom no Route 53 e quer apontar para um ALB. Que tipo de record usar?', '[{"id":"A","text":"Record A com IP fixo do ALB"},{"id":"B","text":"Alias record (apontando para o DNS name do ALB)"},{"id":"C","text":"MX record"},{"id":"D","text":"TXT record"}]'::jsonb, 'B', '{"summary":"Alias record é específico do Route 53: aponta para targets AWS (ALB, CloudFront, S3 static site, etc.) pelo nome DNS, sem charge de query e ajustando IP dinâmicos do recurso.","whyCorrect":"Alias record é específico do Route 53: aponta para targets AWS (ALB, CloudFront, S3 static site, etc.) pelo nome DNS, sem charge de query e ajustando IP dinâmicos do recurso.","whyWrong":{"A":"ALB não tem IP fixo record A direto quebra","C":"MX record (Mail Exchanger) aponta domínio para servidor de email (SMTP) — não para load balancer HTTP. Usado para configurar email recebimento (Google Workspace, M365). Não tem relação com ALB.","D":"TXT record contém texto arbitrário — usado para SPF, DKIM, verificações de domínio (Google site verification). Não é mecanismo de roteamento DNS para um host. Para apontar domínio a ALB, alias record é o correto."},"keyConcept":"Regra: zona apex → recurso AWS = Alias.","tutorSeeds":["Pode explicar com mais detalhe: Regra: zona apex → recurso AWS = Alias?","Quais cenários reais aplicam Regra: zona apex → recurso AWS = Alias?","Como AWS se compara com alternativas?"]}'::jsonb, 'Cloud Technology & Services', 'Cloud Technology & Services', 'medium', 'best-practice', '["route53","alias","alb"]'::jsonb, 'ai-draft', 'active', now(), now()),
    ('clf-c02-tech-080', 'aws-clf', 'Uma aplicação on-prem precisa de tráfego TCP com IP estático e roteamento via backbone AWS para reduzir latência para usuários globais, mesmo para conteúdo NÃO cacheável (jogo online, API). Qual serviço usar?', '[{"id":"A","text":"CloudFront"},{"id":"B","text":"AWS Global Accelerator"},{"id":"C","text":"Route 53 latency routing"},{"id":"D","text":"AWS PrivateLink"}]'::jsonb, 'B', '{"summary":"Global Accelerator entrega 2 IPs estáticos anycast e roteia tráfego TCP/UDP via backbone AWS desde a edge location mais próxima — ideal para conteúdo não-cacheável (gaming, voice, IoT, APIs).","whyCorrect":"Global Accelerator entrega 2 IPs estáticos anycast e roteia tráfego TCP/UDP via backbone AWS desde a edge location mais próxima — ideal para conteúdo não-cacheável (gaming, voice, IoT, APIs).","whyWrong":{"A":"CloudFront cacheia (não serve dinâmico mutável)","C":"Route 53 só responde DNS, não roteia","D":"PrivateLink é exposição privada de serviços."},"keyConcept":"Regra: TCP/UDP global low-latency não-cacheável = Global Accelerator; cacheável = CloudFront.","tutorSeeds":["Pode explicar com mais detalhe: Regra: TCP/UDP global low-latency não-cacheável = Global Accelerator; cacheável = CloudFront?","Quais cenários reais aplicam Regra: TCP/UDP global low-latency não-cacheável = Global Accelerator; cacheável = CloudFront?","Como IPs se compara com alternativas?"]}'::jsonb, 'Cloud Technology & Services', 'Cloud Technology & Services', 'medium', 'scenario', '["global-accelerator","edge","networking"]'::jsonb, 'ai-draft', 'active', now(), now()),
    ('clf-c02-tech-081', 'aws-clf', 'Uma empresa precisa rodar serviços AWS dentro do próprio datacenter on-prem para compliance e latência (manufatura). Qual serviço atende?', '[{"id":"A","text":"AWS Local Zones"},{"id":"B","text":"AWS Wavelength"},{"id":"C","text":"AWS Outposts"},{"id":"D","text":"AWS Direct Connect"}]'::jsonb, 'C', '{"summary":"Outposts é um rack/servidor AWS gerenciado pela AWS instalado no datacenter do cliente — APIs AWS native, EC2/EBS/EKS/RDS locais, conectado à parent Region.","whyCorrect":"Outposts é um rack/servidor AWS gerenciado pela AWS instalado no datacenter do cliente — APIs AWS native, EC2/EBS/EKS/RDS locais, conectado à parent Region.","whyWrong":{"A":"Local Zones são extensões da AWS em cidades específicas (não dentro do datacenter)","B":"Wavelength é em redes 5G de telcos","D":"Direct Connect é só network."},"keyConcept":"Regra: AWS dentro do meu DC = Outposts.","tutorSeeds":["Pode explicar com mais detalhe: Regra: AWS dentro do meu DC = Outposts?","Quais cenários reais aplicam Regra: AWS dentro do meu DC = Outposts?","Como AWS se compara com alternativas?"]}'::jsonb, 'Cloud Technology & Services', 'Cloud Technology & Services', 'medium', 'scenario', '["outposts","hybrid","edge"]'::jsonb, 'ai-draft', 'active', now(), now()),
    ('clf-c02-tech-082', 'aws-clf', 'Uma aplicação 5G precisa rodar workload com latência ultra-baixa na borda da rede móvel da operadora (telco edge). Qual serviço AWS usar?', '[{"id":"A","text":"AWS Local Zones"},{"id":"B","text":"AWS Wavelength"},{"id":"C","text":"AWS Outposts"},{"id":"D","text":"CloudFront"}]'::jsonb, 'B', '{"summary":"Wavelength integra zonas AWS dentro das redes 5G de telcos parceiras (Verizon, KDDI, etc.) — single-digit ms latency para dispositivos móveis.","whyCorrect":"Wavelength integra zonas AWS dentro das redes 5G de telcos parceiras (Verizon, KDDI, etc.) — single-digit ms latency para dispositivos móveis.","whyWrong":{"A":"Local Zones são em cidades específicas, fora da rede telco","C":"Outposts é no DC","D":"CloudFront é CDN HTTP."},"keyConcept":"Regra: mobile edge 5G = Wavelength; metropolitan low-latency = Local Zones.","tutorSeeds":["Pode explicar com mais detalhe: Regra: mobile edge 5G = Wavelength; metropolitan low-latency = Local Zones?","Quais cenários reais aplicam Regra: mobile edge 5G = Wavelength; metropolitan low-latency = Local Zones?","Como AWS se compara com alternativas?"]}'::jsonb, 'Cloud Technology & Services', 'Cloud Technology & Services', 'hard', 'scenario', '["wavelength","5g","edge"]'::jsonb, 'ai-draft', 'active', now(), now()),
    ('clf-c02-tech-083', 'aws-clf', 'Uma empresa precisa rodar workloads sensíveis a latência (gaming, real-time media) em São Paulo, mas a Region está em outra cidade. Qual recurso aproxima a infra do cliente?', '[{"id":"A","text":"AWS Local Zone"},{"id":"B","text":"AWS Snowball"},{"id":"C","text":"AWS Storage Gateway"},{"id":"D","text":"CloudFront edge location"}]'::jsonb, 'A', '{"summary":"Local Zones estendem a AWS para cidades metropolitanas específicas, com EC2, EBS, ELB e outros serviços localmente — ideal para latência single-digit ms em mídia, gaming e ML inferência.","whyCorrect":"Local Zones estendem a AWS para cidades metropolitanas específicas, com EC2, EBS, ELB e outros serviços localmente — ideal para latência single-digit ms em mídia, gaming e ML inferência.","whyWrong":{"B":"Snowball é storage migration","C":"Storage Gateway é hybrid storage","D":"CloudFront edge serve só conteúdo cacheável HTTP."},"keyConcept":"Regra: latência metro AWS-managed = Local Zone.","tutorSeeds":["Pode explicar com mais detalhe: Regra: latência metro AWS-managed = Local Zone?","Quais cenários reais aplicam Regra: latência metro AWS-managed = Local Zone?","Como AWS se compara com alternativas?"]}'::jsonb, 'Cloud Technology & Services', 'Cloud Technology & Services', 'medium', 'scenario', '["local-zones","edge","latency"]'::jsonb, 'ai-draft', 'active', now(), now()),
    ('clf-c02-tech-084', 'aws-clf', 'Uma equipe quer um sistema pub/sub onde uma mensagem é entregue a múltiplos subscribers (Lambda, SQS queue, email, SMS). Qual serviço escolher?', '[{"id":"A","text":"Amazon SQS"},{"id":"B","text":"Amazon SNS"},{"id":"C","text":"Amazon Kinesis Data Streams"},{"id":"D","text":"AWS Step Functions"}]'::jsonb, 'B', '{"summary":"SNS é pub/sub topic-based: 1 publish → fan-out para N subscribers (SQS, Lambda, HTTP, email, SMS, mobile push).","whyCorrect":"SNS é pub/sub topic-based: 1 publish → fan-out para N subscribers (SQS, Lambda, HTTP, email, SMS, mobile push).","whyWrong":{"C":"Kinesis é streaming ordered/durable de eventos","D":"Step Functions é orchestration workflow.","A":"SQS é fila ponto-a-ponto entre producer e UM grupo de consumers — não tem fan-out nativo para múltiplos subscribers heterogêneos (Lambda + email + SMS). Padrão clássico é SNS na frente fanning out para SQS + Lambda + email. SQS sozinho seria correto para ''worker queue com 1 conjunto de consumers''."},"keyConcept":"Regra: fan-out = SNS; fila de trabalho = SQS; stream contínuo = Kinesis.","tutorSeeds":["Pode explicar com mais detalhe: Regra: fan-out = SNS; fila de trabalho = SQS; stream contínuo = Kinesis?","Quais cenários reais aplicam Regra: fan-out = SNS; fila de trabalho = SQS; stream contínuo = Kinesis?","Como SNS se compara com alternativas?"]}'::jsonb, 'Cloud Technology & Services', 'Cloud Technology & Services', 'easy', 'scenario', '["sns","pub-sub","messaging"]'::jsonb, 'ai-draft', 'active', now(), now()),
    ('clf-c02-tech-085', 'aws-clf', 'Uma equipe precisa desacoplar producers e consumers numa pipeline de pedidos: producer enfileira mensagens e workers processam quando podem, garantindo at-least-once. Qual serviço usar?', '[{"id":"A","text":"Amazon SQS"},{"id":"B","text":"Amazon SNS"},{"id":"C","text":"AWS Lambda direto"},{"id":"D","text":"Amazon CloudWatch Events"}]'::jsonb, 'A', '{"summary":"SQS é managed message queue: producers enfileiram, consumers fazem poll/long-poll, mensagens visibility timeout, DLQ para falhas, at-least-once delivery (Standard) ou exactly-once (FIFO).","whyCorrect":"SQS é managed message queue: producers enfileiram, consumers fazem poll/long-poll, mensagens visibility timeout, DLQ para falhas, at-least-once delivery (Standard) ou exactly-once (FIFO).","whyWrong":{"C":"Lambda direto não armazena se consumer cair","B":"SNS é pub/sub (broadcast 1-para-N) — quando publica, TODOS subscribers recebem. Não é fila de trabalho onde N workers competem por mensagens. Para desacoplar producer e consumers de forma que workers processem on-demand (1 mensagem = 1 worker), SQS é o construto. SNS seria correto para ''notificar múltiplos sistemas do mesmo evento''.","D":"CloudWatch Events (atualmente EventBridge) é roteamento de eventos cron/state-change para targets — não é fila persistente onde workers fazem polling. Eventos têm retry curto e podem perder se target falhar. Para pipeline de pedidos com at-least-once garantido e desacoplamento, SQS é purpose-built."},"keyConcept":"Regra: queue desacoplada = SQS; broadcast = SNS; orquestração = Step Functions.","tutorSeeds":["Pode explicar com mais detalhe: Regra: queue desacoplada = SQS; broadcast = SNS; orquestração = Step Functions?","Quais cenários reais aplicam Regra: queue desacoplada = SQS; broadcast = SNS; orquestração = Step Functions?","Como SQS se compara com alternativas?"]}'::jsonb, 'Cloud Technology & Services', 'Cloud Technology & Services', 'easy', 'scenario', '["sqs","queue","messaging"]'::jsonb, 'ai-draft', 'active', now(), now()),
    ('clf-c02-tech-086', 'aws-clf', 'Sobre SQS Standard vs FIFO, qual afirmação é VERDADEIRA?', '[{"id":"A","text":"Standard garante ordem estrita; FIFO permite duplicatas"},{"id":"B","text":"Standard tem throughput quase ilimitado, best-effort ordering e at-least-once; FIFO garante ordem estrita e exactly-once com throughput limitado"},{"id":"C","text":"FIFO e Standard são idênticos, só preço difere"},{"id":"D","text":"FIFO suporta apenas mensagens texto, Standard suporta binárias"}]'::jsonb, 'B', '{"summary":"Standard: throughput ilimitado, best-effort ordering, at-least-once (raras duplicatas).","whyCorrect":"Standard: throughput ilimitado, best-effort ordering, at-least-once (raras duplicatas). FIFO: ordem estrita por message group, exactly-once, ~300 msg/s por API (3000 com batching), ''.fifo'' no nome obrigatório.","whyWrong":{"A":"Standard NÃO garante ordem FIFO existe pra isso.","C":"SQS Standard e FIFO têm SEMÂNTICAS FUNDAMENTALMENTE DIFERENTES — não são intercambiáveis. Standard: throughput ilimitado, ordem best-effort, at-least-once. FIFO: ordem estrita, exactly-once, throughput limitado (~300/3000 msg/s). Pricing também difere (FIFO mais caro por mensagem).","D":"Ambos Standard e FIFO suportam payloads de até 256KB (texto ou binário base64-encoded) — não há diferença em tipos de payload. Esta opção é factualmente errada. Para payloads maiores, usar Extended Client com S3."},"keyConcept":"Regra: ordem importa = FIFO; throughput importa = Standard.","tutorSeeds":["Pode explicar com mais detalhe: Regra: ordem importa = FIFO; throughput importa = Standard?","Quais cenários reais aplicam Regra: ordem importa = FIFO; throughput importa = Standard?","Como FIFO se compara com alternativas?"]}'::jsonb, 'Cloud Technology & Services', 'Cloud Technology & Services', 'medium', 'recall', '["sqs","fifo","messaging"]'::jsonb, 'ai-draft', 'active', now(), now()),
    ('clf-c02-tech-087', 'aws-clf', 'Uma equipe precisa rotear eventos de múltiplos serviços AWS SaaS para destinos diferentes (Lambda, SQS, ECS), com filtros baseados em conteúdo do evento. Qual serviço usar?', '[{"id":"A","text":"Amazon EventBridge"},{"id":"B","text":"Amazon SQS FIFO"},{"id":"C","text":"AWS Step Functions"},{"id":"D","text":"Amazon Kinesis Firehose"}]'::jsonb, 'A', '{"summary":"EventBridge é serverless event bus com schema registry, suporta eventos AWS, custom e SaaS (Zendesk, Datadog, etc.), regras com pattern matching filtram e roteiam para 20+ targets.","whyCorrect":"EventBridge é serverless event bus com schema registry, suporta eventos AWS, custom e SaaS (Zendesk, Datadog, etc.), regras com pattern matching filtram e roteiam para 20+ targets.","whyWrong":{"C":"Step Functions é workflow orchestration","D":"Firehose é ingestion para S3/Redshift.","B":"SQS FIFO é fila com ordem estrita e exactly-once — não é roteador de eventos com filtros. Não consume nativamente de SaaS partners (Zendesk, Datadog), não tem schema registry, não roteia para múltiplos targets baseado em pattern matching. FIFO seria correto para ''fila de pedidos com ordem garantida''."},"keyConcept":"Regra: event-driven multi-source com filtro = EventBridge; pub/sub simples AWS-native = SNS.","tutorSeeds":["Pode explicar com mais detalhe: Regra: event-driven multi-source com filtro = EventBridge; pub/sub simples AWS-native = SNS?","Quais cenários reais aplicam Regra: event-driven multi-source com filtro = EventBridge; pub/sub simples AWS-native = SNS?","Como AWS se compara com alternativas?"]}'::jsonb, 'Cloud Technology & Services', 'Cloud Technology & Services', 'medium', 'scenario', '["eventbridge","events","integration"]'::jsonb, 'ai-draft', 'active', now(), now()),
    ('clf-c02-tech-088', 'aws-clf', 'Uma equipe precisa orquestrar um workflow com 10 passos sequenciais, com retries, paralelismo, espera e ramificações condicionais entre Lambdas e ECS tasks. Qual serviço usar?', '[{"id":"A","text":"Amazon SQS com Lambda chain"},{"id":"B","text":"AWS Step Functions"},{"id":"C","text":"Amazon EventBridge"},{"id":"D","text":"AWS Batch"}]'::jsonb, 'B', '{"summary":"Step Functions é orquestrador serverless de workflows (state machines), com retries built-in, error handling, parallel, choice/branch, wait, integração nativa com 200+ serviços AWS.","whyCorrect":"Step Functions é orquestrador serverless de workflows (state machines), com retries built-in, error handling, parallel, choice/branch, wait, integração nativa com 200+ serviços AWS. Visual designer ASL JSON.","whyWrong":{"A":"Chain de SQS+Lambda funciona mas é frágil","C":"EventBridge é routing event-driven, sem state","D":"Batch é fila de batch jobs."},"keyConcept":"Regra: workflow stateful coordenado = Step Functions.","tutorSeeds":["Pode explicar com mais detalhe: Regra: workflow stateful coordenado = Step Functions?","Quais cenários reais aplicam Regra: workflow stateful coordenado = Step Functions?","Como AWS se compara com alternativas?"]}'::jsonb, 'Cloud Technology & Services', 'Cloud Technology & Services', 'medium', 'scenario', '["step-functions","workflow","orchestration"]'::jsonb, 'ai-draft', 'active', now(), now()),
    ('clf-c02-tech-089', 'aws-clf', 'Uma equipe quer que mensagens não processadas (após N retries) sejam isoladas para inspeção sem travar a queue principal. Qual feature SQS atende?', '[{"id":"A","text":"Visibility Timeout"},{"id":"B","text":"Dead Letter Queue (DLQ)"},{"id":"C","text":"Long Polling"},{"id":"D","text":"Message Group ID"}]'::jsonb, 'B', '{"summary":"DLQ é queue de quarentena: após maxReceiveCount tentativas, mensagem move para DLQ para análise/retry manual sem prejudicar o restante do fluxo.","whyCorrect":"DLQ é queue de quarentena: após maxReceiveCount tentativas, mensagem move para DLQ para análise/retry manual sem prejudicar o restante do fluxo.","whyWrong":{"A":"Visibility Timeout esconde mensagem temporariamente durante processamento","C":"Long Polling reduz polls vazios","D":"Message Group ID é FIFO."},"keyConcept":"Regra: ''poison pills'' = DLQ.","tutorSeeds":["Pode explicar com mais detalhe: Regra: ''poison pills'' = DLQ?","Quais cenários reais aplicam Regra: ''poison pills'' = DLQ?","Como DLQ se compara com alternativas?"]}'::jsonb, 'Cloud Technology & Services', 'Cloud Technology & Services', 'medium', 'best-practice', '["sqs","dlq","reliability"]'::jsonb, 'ai-draft', 'active', now(), now()),
    ('clf-c02-tech-090', 'aws-clf', 'Uma equipe precisa enviar SMS de notificação para clientes em vários países. Qual serviço AWS atende diretamente?', '[{"id":"A","text":"Amazon SES"},{"id":"B","text":"Amazon SNS (com endpoint SMS)"},{"id":"C","text":"Amazon Pinpoint"},{"id":"D","text":"Tanto SNS quanto Pinpoint suportam SMS"}]'::jsonb, 'D', '{"summary":"Tanto SNS quanto Pinpoint enviam SMS internacionalmente.","whyCorrect":"Tanto SNS quanto Pinpoint enviam SMS internacionalmente. SNS é simples e transacional. Pinpoint é solução de marketing/engajamento com segmentação, campanhas e analytics.","whyWrong":{"A":"Amazon SES (Simple Email Service) é serviço de envio/recebimento de EMAIL — não SMS. SES é purpose-built para email transacional e de marketing. Não tem capability de SMS. Esta opção confunde canal de comunicação.","B":"SNS COM endpoint SMS funciona para SMS, mas a pergunta tem D como opção mais completa (''Tanto SNS quanto Pinpoint suportam SMS'') que é factualmente correta — Pinpoint é o serviço purpose-built para marketing SMS multicanal, SNS é o transacional. A opção D engloba ambas as ferramentas.","C":"Pinpoint suporta SMS, mas D (''tanto SNS quanto Pinpoint'') é a resposta mais precisa — ambos os serviços enviam SMS, com casos de uso diferentes (SNS transacional simples, Pinpoint campanhas com analytics/segmentação). Citar só Pinpoint é incompleto."},"keyConcept":"Regra: SMS simples = SNS; SMS marketing/campanha = Pinpoint.","tutorSeeds":["Pode explicar com mais detalhe: Regra: SMS simples = SNS; SMS marketing/campanha = Pinpoint?","Quais cenários reais aplicam Regra: SMS simples = SNS; SMS marketing/campanha = Pinpoint?","Como SNS se compara com alternativas?"]}'::jsonb, 'Cloud Technology & Services', 'Cloud Technology & Services', 'hard', 'recall', '["sns","pinpoint","sms"]'::jsonb, 'ai-draft', 'active', now(), now()),
    ('clf-c02-tech-091', 'aws-clf', 'Uma equipe precisa de uma API REST gerenciada com authentication, rate limiting, throttling, caching e integração com Lambda. Qual serviço usar?', '[{"id":"A","text":"Amazon API Gateway"},{"id":"B","text":"Elastic Load Balancer ALB"},{"id":"C","text":"AWS AppSync"},{"id":"D","text":"AWS App Runner"}]'::jsonb, 'A', '{"summary":"API Gateway é managed service para REST, HTTP e WebSocket APIs: auth (IAM, Cognito, Lambda Authorizer), rate limiting, throttling, caching, Lambda/HTTP/SQS/etc.","whyCorrect":"API Gateway é managed service para REST, HTTP e WebSocket APIs: auth (IAM, Cognito, Lambda Authorizer), rate limiting, throttling, caching, Lambda/HTTP/SQS/etc. integration, versioning, custom domains.","whyWrong":{"C":"AppSync é para GraphQL","D":"App Runner é container hosting.","B":"Elastic Load Balancer ALB é load balancer HTTP/HTTPS — distribui tráfego entre targets. NÃO tem authentication nativa (apenas integração OIDC limitada), NÃO tem rate limiting, NÃO tem caching, NÃO tem usage plans. ALB seria correto para ''distribuir tráfego HTTP entre servidores'', mas API Gateway é purpose-built para APIs gerenciadas."},"keyConcept":"Regra: API REST gerenciada serverless = API Gateway.","tutorSeeds":["Pode explicar com mais detalhe: Regra: API REST gerenciada serverless = API Gateway?","Quais cenários reais aplicam Regra: API REST gerenciada serverless = API Gateway?","Como API se compara com alternativas?"]}'::jsonb, 'Cloud Technology & Services', 'Cloud Technology & Services', 'easy', 'scenario', '["api-gateway","rest","serverless"]'::jsonb, 'ai-draft', 'active', now(), now()),
    ('clf-c02-tech-092', 'aws-clf', 'Sobre API Gateway, qual afirmação é VERDADEIRA?', '[{"id":"A","text":"Suporta apenas REST APIs; HTTP e WebSocket não são suportados"},{"id":"B","text":"Suporta REST APIs, HTTP APIs (mais simples e baratas) e WebSocket APIs (conexões persistentes)"},{"id":"C","text":"É somente para uso interno em VPC"},{"id":"D","text":"Não suporta integração com Lambda"}]'::jsonb, 'B', '{"summary":"API Gateway tem 3 tipos: REST APIs (feature-rich, mais caras), HTTP APIs (mais baratas e rápidas, JWT auth nativo) e WebSocket APIs (chat, realtime).","whyCorrect":"API Gateway tem 3 tipos: REST APIs (feature-rich, mais caras), HTTP APIs (mais baratas e rápidas, JWT auth nativo) e WebSocket APIs (chat, realtime).","whyWrong":{"D":"Lambda é a integração principal.","A":"API Gateway suporta TRÊS tipos: REST APIs, HTTP APIs E WebSocket APIs — esta opção é factualmente errada. HTTP APIs (lançadas 2019) e WebSocket APIs (2018) são amplamente usados.","C":"API Gateway é PÚBLICO por padrão — APIs públicas têm endpoint *.execute-api.region.amazonaws.com acessível pela internet. Pode ser configurado como PRIVATE (acessível só via VPC endpoint) para uso interno, mas não é restrito a VPC. Esta opção generaliza incorretamente."},"keyConcept":"Regra: HTTP API para casos simples e econômicos; REST para features avançadas (caching, request validation); WebSocket para tempo real.","tutorSeeds":["Pode explicar com mais detalhe: Regra: HTTP API para casos simples e econômicos; REST para features avançadas (caching, request validation); WebSocket para tempo real?","Quais cenários reais aplicam Regra: HTTP API para casos simples e econômicos; REST para features avançadas (caching, request validation); WebSocket para tempo real?","Como API se compara com alternativas?"]}'::jsonb, 'Cloud Technology & Services', 'Cloud Technology & Services', 'medium', 'recall', '["api-gateway","rest","websocket"]'::jsonb, 'ai-draft', 'active', now(), now()),
    ('clf-c02-tech-093', 'aws-clf', 'Uma equipe desenvolve um app móvel que precisa de API GraphQL com subscriptions em tempo real, sincronização offline e auth via Cognito. Qual serviço escolher?', '[{"id":"A","text":"Amazon API Gateway REST"},{"id":"B","text":"AWS AppSync"},{"id":"C","text":"Amazon SNS WebSocket"},{"id":"D","text":"AWS Step Functions"}]'::jsonb, 'B', '{"summary":"AppSync é managed GraphQL: queries, mutations, subscriptions (real-time via WebSocket), conflict resolution para offline sync, integração nativa com Cognito, DynamoDB, Lambda, RDS.","whyCorrect":"AppSync é managed GraphQL: queries, mutations, subscriptions (real-time via WebSocket), conflict resolution para offline sync, integração nativa com Cognito, DynamoDB, Lambda, RDS.","whyWrong":{"A":"API Gateway é REST/HTTP/WS, não GraphQL nativo","D":"Step Functions é workflow.","C":"Amazon SNS é pub/sub para mensageria com targets simples (Lambda, SQS, email, SMS) — não tem schema GraphQL, não tem subscriptions GraphQL com filtros, não tem offline sync para mobile. SNS+WebSocket não existe como produto integrado. AppSync é o serviço purpose-built para GraphQL na AWS."},"keyConcept":"Regra: GraphQL na AWS = AppSync.","tutorSeeds":["Pode explicar com mais detalhe: Regra: GraphQL na AWS = AppSync?","Quais cenários reais aplicam Regra: GraphQL na AWS = AppSync?","Como RDS se compara com alternativas?"]}'::jsonb, 'Cloud Technology & Services', 'Cloud Technology & Services', 'medium', 'scenario', '["appsync","graphql","mobile"]'::jsonb, 'ai-draft', 'active', now(), now()),
    ('clf-c02-tech-094', 'aws-clf', 'Uma equipe escolhe entre API Gateway REST API e HTTP API para um novo endpoint Lambda. Qual cenário favorece HTTP API?', '[{"id":"A","text":"Necessidade de request/response transformations complexas, caching, usage plans"},{"id":"B","text":"API minimal, JWT auth (Cognito), latência baixa e custo reduzido, sem features avançadas"},{"id":"C","text":"API com WebSocket real-time"},{"id":"D","text":"API que requer X-Ray e API keys avançadas"}]'::jsonb, 'B', '{"summary":"HTTP API é versão minimal e mais barata (até ~70% menos que REST API), com latência menor, JWT auth nativo e integrações simples — ideal para APIs simples Lambda-backed.","whyCorrect":"HTTP API é versão minimal e mais barata (até ~70% menos que REST API), com latência menor, JWT auth nativo e integrações simples — ideal para APIs simples Lambda-backed.","whyWrong":{"A":"Features complexas (caching, request validation, transformations, usage plans, API keys, X-Ray, WAF Edge) = REST API","C":"WebSocket = WebSocket API.","D":"X-Ray e API keys avançadas são features mais ricas associadas a REST API (não HTTP API). REST API tem feature parity completa incluindo X-Ray nativo, Usage Plans com API Keys, request validators. Esta opção descreve cenário que favorece REST, não HTTP."},"keyConcept":"Regra: features avançadas = REST; simples e barato = HTTP.","tutorSeeds":["Pode explicar com mais detalhe: Regra: features avançadas = REST; simples e barato = HTTP?","Quais cenários reais aplicam Regra: features avançadas = REST; simples e barato = HTTP?","Como HTTP se compara com alternativas?"]}'::jsonb, 'Cloud Technology & Services', 'Cloud Technology & Services', 'hard', 'best-practice', '["api-gateway","http-api","cost-optimization"]'::jsonb, 'ai-draft', 'active', now(), now()),
    ('clf-c02-tech-095', 'aws-clf', 'Uma empresa quer construir um modelo de ML personalizado para detectar fraude e fazer deploy do endpoint inferencia. Qual serviço AWS é o mais adequado?', '[{"id":"A","text":"Amazon SageMaker"},{"id":"B","text":"Amazon Comprehend"},{"id":"C","text":"Amazon Rekognition"},{"id":"D","text":"Amazon Athena"}]'::jsonb, 'A', '{"summary":"SageMaker é plataforma end-to-end ML: build, train, tune e deploy de modelos customizados em endpoints managed, com notebooks Jupyter, AutoML (Autopilot), MLOps (Pipelines, Feature Store).","whyCorrect":"SageMaker é plataforma end-to-end ML: build, train, tune e deploy de modelos customizados em endpoints managed, com notebooks Jupyter, AutoML (Autopilot), MLOps (Pipelines, Feature Store).","whyWrong":{"B":"Comprehend é NLP pré-treinado (sentiment, entities)","C":"Rekognition é vision pré-treinado","D":"Athena é query SQL."},"keyConcept":"Regra: ML custom AWS = SageMaker; AI services pré-treinados = Comprehend/Rekognition/etc.","tutorSeeds":["Pode explicar com mais detalhe: Regra: ML custom AWS = SageMaker; AI services pré-treinados = Comprehend/Rekognition/etc?","Quais cenários reais aplicam Regra: ML custom AWS = SageMaker; AI services pré-treinados = Comprehend/Rekognition/etc?","Como ML se compara com alternativas?"]}'::jsonb, 'Cloud Technology & Services', 'Cloud Technology & Services', 'easy', 'scenario', '["sagemaker","ml","ai"]'::jsonb, 'ai-draft', 'active', now(), now()),
    ('clf-c02-tech-096', 'aws-clf', 'Uma empresa quer extrair sentiment, entidades e idioma de milhões de reviews de clientes em português, sem treinar modelo. Qual serviço usar?', '[{"id":"A","text":"Amazon Rekognition"},{"id":"B","text":"Amazon Comprehend"},{"id":"C","text":"Amazon Polly"},{"id":"D","text":"Amazon Translate"}]'::jsonb, 'B', '{"summary":"Comprehend é NLP managed: sentiment, entidades, key phrases, language, syntax, topic modeling — pré-treinado, sem necessidade de ML expertise.","whyCorrect":"Comprehend é NLP managed: sentiment, entidades, key phrases, language, syntax, topic modeling — pré-treinado, sem necessidade de ML expertise. Suporta português entre outros.","whyWrong":{"A":"Rekognition é image/video","C":"Polly é text-to-speech","D":"Translate é tradução."},"keyConcept":"Regra: NLP pré-treinado AWS = Comprehend.","tutorSeeds":["Pode explicar com mais detalhe: Regra: NLP pré-treinado AWS = Comprehend?","Quais cenários reais aplicam Regra: NLP pré-treinado AWS = Comprehend?","Como NLP se compara com alternativas?"]}'::jsonb, 'Cloud Technology & Services', 'Cloud Technology & Services', 'medium', 'scenario', '["comprehend","nlp","ai"]'::jsonb, 'ai-draft', 'active', now(), now()),
    ('clf-c02-tech-097', 'aws-clf', 'Uma empresa quer rodar jobs Spark e Hadoop em cluster managed para processar petabytes de dados. Qual serviço escolher?', '[{"id":"A","text":"Amazon Athena"},{"id":"B","text":"Amazon EMR"},{"id":"C","text":"Amazon Redshift"},{"id":"D","text":"AWS Glue"}]'::jsonb, 'B', '{"summary":"EMR (Elastic MapReduce) é cluster managed para Hadoop, Spark, Hive, Presto, HBase, Flink — em EC2, EKS ou serverless (EMR Serverless).","whyCorrect":"EMR (Elastic MapReduce) é cluster managed para Hadoop, Spark, Hive, Presto, HBase, Flink — em EC2, EKS ou serverless (EMR Serverless). Ideal para big data processing.","whyWrong":{"A":"Athena é serverless SQL ad-hoc","C":"Redshift é warehouse","D":"Glue é ETL serverless."},"keyConcept":"Regra: framework Hadoop/Spark control = EMR; ETL serverless = Glue; SQL on S3 = Athena.","tutorSeeds":["Pode explicar com mais detalhe: Regra: framework Hadoop/Spark control = EMR; ETL serverless = Glue; SQL on S3 = Athena?","Quais cenários reais aplicam Regra: framework Hadoop/Spark control = EMR; ETL serverless = Glue; SQL on S3 = Athena?","Como EMR se compara com alternativas?"]}'::jsonb, 'Cloud Technology & Services', 'Cloud Technology & Services', 'medium', 'scenario', '["emr","spark","big-data"]'::jsonb, 'ai-draft', 'active', now(), now()),
    ('clf-c02-tech-098', 'aws-clf', 'Uma equipe precisa de ETL serverless para mover/transformar dados entre S3, Redshift, RDS e criar um catalog. Qual serviço escolher?', '[{"id":"A","text":"AWS Glue"},{"id":"B","text":"Amazon EMR"},{"id":"C","text":"AWS Data Pipeline"},{"id":"D","text":"Amazon Athena"}]'::jsonb, 'A', '{"summary":"Glue é ETL serverless baseado em Spark, com Data Catalog (Hive metastore-compatible), crawlers que descobrem schemas, integração nativa com Athena/Redshift Spectrum/EMR.","whyCorrect":"Glue é ETL serverless baseado em Spark, com Data Catalog (Hive metastore-compatible), crawlers que descobrem schemas, integração nativa com Athena/Redshift Spectrum/EMR. Paga por DPU-hora.","whyWrong":{"C":"Data Pipeline é legado (descontinuado para novos casos)","D":"Athena é query, não ETL.","B":"Amazon EMR é cluster Spark/Hadoop managed — poderoso para ETL pesado mas exige gerenciar cluster (instâncias, scaling, configuração). NÃO é serverless por padrão (EMR Serverless existe mas é mais recente e específico). Para ETL com Data Catalog automático, Glue é purpose-built. EMR seria correto para ''controle total do Spark cluster com tuning específico''."},"keyConcept":"Regra: ETL serverless + catálogo = Glue.","tutorSeeds":["Pode explicar com mais detalhe: Regra: ETL serverless + catálogo = Glue?","Quais cenários reais aplicam Regra: ETL serverless + catálogo = Glue?","Como ETL se compara com alternativas?"]}'::jsonb, 'Cloud Technology & Services', 'Cloud Technology & Services', 'medium', 'scenario', '["glue","etl","analytics"]'::jsonb, 'ai-draft', 'active', now(), now()),
    ('clf-c02-tech-099', 'aws-clf', 'Uma equipe quer monitorar fila SQS e auto-escalar consumers ECS conforme o tamanho da fila. Qual abordagem é a mais idiomática?', '[{"id":"A","text":"CloudWatch metric ApproximateNumberOfMessagesVisible disparando ECS Service Auto Scaling"},{"id":"B","text":"Lambda fazendo polling de 1 em 1 segundo e ajustando ECS manualmente"},{"id":"C","text":"Aumentar a visibility timeout para 12 horas"},{"id":"D","text":"Habilitar SNS fan-out"}]'::jsonb, 'A', '{"summary":"Padrão idiomático: SQS emite metric ApproximateNumberOfMessagesVisible para CloudWatch → ECS Service Auto Scaling (target tracking ou step scaling) ajusta task count baseado em backlog.","whyCorrect":"Padrão idiomático: SQS emite metric ApproximateNumberOfMessagesVisible para CloudWatch → ECS Service Auto Scaling (target tracking ou step scaling) ajusta task count baseado em backlog.","whyWrong":{"B":"Polling custom reinventa","C":"visibility timeout não escala","D":"SNS fan-out é mecanismo de broadcast pub/sub — não escala consumers baseado em backlog de fila. Habilitar SNS na frente do SQS não muda quantidade de consumers ECS. Esta opção mistura conceitos: fan-out é distribuir 1 mensagem para N subscribers, não escalar workers."},"keyConcept":"Regra: backlog-driven scaling = CloudWatch metric + ASG/ECS Auto Scaling.","tutorSeeds":["Pode explicar com mais detalhe: Regra: backlog-driven scaling = CloudWatch metric + ASG/ECS Auto Scaling?","Quais cenários reais aplicam Regra: backlog-driven scaling = CloudWatch metric + ASG/ECS Auto Scaling?","Como SQS se compara com alternativas?"]}'::jsonb, 'Cloud Technology & Services', 'Cloud Technology & Services', 'hard', 'best-practice', '["sqs","auto-scaling","ecs"]'::jsonb, 'ai-draft', 'active', now(), now()),
    ('clf-c02-tech-100', 'aws-clf', 'Uma startup vai construir um app mobile com backend serverless: auth de usuário, API GraphQL, banco NoSQL escalável e storage de imagens. Qual combinação AWS é a mais idiomática?', '[{"id":"A","text":"Cognito + AppSync + DynamoDB + S3"},{"id":"B","text":"IAM Users + API Gateway REST + RDS MySQL + EBS"},{"id":"C","text":"Cognito + Lambda direto exposto na internet + Aurora + EFS"},{"id":"D","text":"Active Directory + EKS + Redshift + Glacier"}]'::jsonb, 'A', '{"summary":"Stack serverless mobile idiomática: Cognito (user pools + identity pools), AppSync (GraphQL com offline sync), DynamoDB (NoSQL scale-to-zero), S3 (object storage com pre-signed URLs).","whyCorrect":"Stack serverless mobile idiomática: Cognito (user pools + identity pools), AppSync (GraphQL com offline sync), DynamoDB (NoSQL scale-to-zero), S3 (object storage com pre-signed URLs). Todos managed, escalam automaticamente, pay-per-use.","whyWrong":{"B":"IAM Users não escala para milhões de end-users","C":"Expor Lambda diretamente sem API Gateway/AppSync é anti-padrão (Function URLs existem mas sem auth, throttling, request validation, custom domains adequados). Aurora é overkill para app mobile (paga cluster mínimo mesmo com tráfego baixo). EFS é file system NFS - desnecessário para storage de imagens (S3 é purpose-built, mais barato).","D":"Active Directory é IdP corporativo (workforce) — não é apropriado para usuários finais de app mobile (use Cognito). EKS é Kubernetes managed — overhead enorme para startup pequena (use serverless: AppSync/Lambda). Redshift é data warehouse petabyte — não banco operacional de app (use DynamoDB/Aurora). Glacier é archival — não storage ativo de imagens (use S3)."},"keyConcept":"Expor Lambda direto sem API Gateway/AppSync é antipadrão; EFS é overkill.","tutorSeeds":["Pode explicar com mais detalhe: Expor Lambda direto sem API Gateway/AppSync é antipadrão; EFS é overkill?","Quais cenários reais aplicam Expor Lambda direto sem API Gateway/AppSync é antipadrão; EFS é overkill?","Como URLs se compara com alternativas?"]}'::jsonb, 'Cloud Technology & Services', 'Cloud Technology & Services', 'hard', 'best-practice', '["serverless","mobile","architecture"]'::jsonb, 'ai-draft', 'active', now(), now()),
    ('clf-c02-tech-v2-001', 'aws-clf', 'Uma equipe configura um Auto Scaling Group e quer adicionar/remover instâncias com base em uma métrica de utilização média de CPU mantida em 60%, deixando o ASG calcular automaticamente quantas instâncias adicionar para atingir esse alvo. Qual tipo de scaling policy é o mais adequado?', '[{"id":"A","text":"Simple scaling policy com cooldown de 300s"},{"id":"B","text":"Step scaling policy com múltiplos degraus de CPU"},{"id":"C","text":"Target tracking scaling policy com métrica ASGAverageCPUUtilization = 60"},{"id":"D","text":"Scheduled scaling com cron diário"}]'::jsonb, 'C', '{"summary":"Target tracking calcula o delta de capacidade automaticamente para manter uma métrica no alvo.","whyCorrect":"Target tracking funciona como um termostato: você define a métrica (CPU média) e o valor alvo (60%) e o ASG ajusta a capacidade desejada subindo ou descendo para convergir. Internamente cria alarmes CloudWatch high/low automaticamente. Não exige cálculo manual de quantas instâncias adicionar.","whyWrong":{"A":"Simple scaling adiciona um número FIXO de instâncias quando o alarme dispara e aguarda o cooldown — não calcula delta dinamicamente para atingir um alvo de utilização.","B":"Step scaling adiciona quantidades diferentes em degraus (ex: +1 se CPU 60-70%, +3 se >70%), exigindo configuração manual dos limites e steps — mais complexo do que necessário quando o objetivo é manter um valor único.","D":"Scheduled scaling muda capacidade em horários conhecidos (cron) — não reage à carga real. Útil para padrões previsíveis, não para manter CPU em um alvo."},"keyConcept":"EC2 Auto Scaling — Target tracking vs Step vs Simple vs Scheduled scaling policies","compareWith":["Target tracking vs Step scaling","Reactive (CloudWatch metric) vs Predictive scaling"],"realWorldContext":"Padrão para 80% dos ASGs em produção — é a opção recomendada pela AWS por simplicidade e convergência.","commonMistakes":"Achar que target tracking serve para qualquer métrica — só funciona com métricas monotônicas (sobe = mais carga). Não use com latência média, por exemplo.","tutorSeeds":["Como o target tracking decide quantas instâncias adicionar?","Quando step scaling é melhor que target tracking?"]}'::jsonb, 'Cloud Technology & Services', 'Cloud Technology & Services', 'medium', 'scenario', '["auto-scaling","target-tracking","ec2","policy-types"]'::jsonb, 'ai-draft', 'active', now(), now()),
    ('clf-c02-tech-v2-002', 'aws-clf', 'Uma loja sabe que o pico de tráfego ocorre toda sexta-feira às 20h por causa de uma promoção semanal, e quer garantir que tenha 50 instâncias rodando antes do pico — não depois que ele já começou. Qual estratégia de scaling do ASG melhor atende?', '[{"id":"A","text":"Target tracking em CPU = 60%"},{"id":"B","text":"Scheduled scaling configurado para subir desired=50 toda sexta às 19h45"},{"id":"C","text":"Predictive scaling com modelo padrão da AWS"},{"id":"D","text":"Step scaling com threshold de CPU em 40%"}]'::jsonb, 'B', '{"summary":"Padrão recorrente em horário conhecido = scheduled scaling.","whyCorrect":"Scheduled scaling permite definir uma ação recorrente (cron) que altera MinSize/MaxSize/DesiredCapacity em um horário específico. Garantir 50 instâncias quentes ANTES do pico é exatamente isso — provisionamento proativo baseado em horário.","whyWrong":{"A":"Target tracking só reage depois que a CPU sobe — adiciona instâncias durante o pico, sofrendo cold start e potencial degradação no início.","C":"Predictive scaling é também válido (analisa histórico via ML), mas para um padrão tão claro e recorrente, scheduled é mais determinístico e simples. Predictive é melhor quando o padrão tem variação diária mais complexa.","D":"Step scaling continua sendo reativo — só dispara após o threshold ser atingido, não antes."},"keyConcept":"Auto Scaling proativo (scheduled/predictive) vs reativo (target/step/simple)","compareWith":["Scheduled scaling vs Predictive scaling","Proactive vs Reactive scaling"],"realWorldContext":"E-commerce com Black Friday, banco com folha de pagamento mensal, gaming com lançamento de evento.","commonMistakes":"Confiar só em target tracking para picos previsíveis — você paga em latência durante a rampa de boot.","tutorSeeds":["Como combinar scheduled + target tracking no mesmo ASG?","Quando predictive scaling supera scheduled?"]}'::jsonb, 'Cloud Technology & Services', 'Cloud Technology & Services', 'easy', 'best-practice', '["auto-scaling","scheduled-scaling","predictive"]'::jsonb, 'ai-draft', 'active', now(), now()),
    ('clf-c02-tech-v2-003', 'aws-clf', 'Uma aplicação web roda em ALB com target group de EC2. Após adicionar uma nova versão da AMI no Launch Template, novas instâncias entram saudáveis no ALB mas usuários ainda recebem respostas da versão antiga por alguns minutos. Qual recurso do ASG melhor resolve a transição controlada?', '[{"id":"A","text":"Instance refresh com MinHealthyPercentage configurado"},{"id":"B","text":"Suspender o processo Launch e relançar manualmente"},{"id":"C","text":"Setar cooldown de 0 segundos no ASG"},{"id":"D","text":"Trocar o ALB por NLB para forçar refresh"}]'::jsonb, 'A', '{"summary":"Instance refresh é o mecanismo nativo para rollout controlado de novas versões em ASG.","whyCorrect":"Instance refresh substitui instâncias gradualmente respeitando MinHealthyPercentage (ex: 90% saudáveis durante o processo) e warmup. Drena conexões via ALB deregistration delay, sobe a nova, marca saudável, depois encerra a antiga. É o blue/green nativo do ASG.","whyWrong":{"B":"Suspender Launch impede novas instâncias — não força substituição das atuais. Você ainda teria a mistura.","C":"Cooldown afeta espaçamento entre scaling actions reativas, não substituição de versão.","D":"Trocar ALB por NLB não tem relação alguma com versionamento de AMI."},"keyConcept":"ASG Instance Refresh — rollout controlado com MinHealthyPercentage e warmup","compareWith":["Instance refresh vs CodeDeploy Blue/Green","Rolling update vs All-at-once"],"realWorldContext":"Deploy de novas AMIs em ASGs de produção, golden image rotation, patching coordenado.","commonMistakes":"Achar que apenas trocar o Launch Template já recicla as instâncias — não recicla, só afeta novos launches.","tutorSeeds":["Como configurar warmup time corretamente?","Diferença entre instance refresh e simplesmente terminar instâncias?"]}'::jsonb, 'Cloud Technology & Services', 'Cloud Technology & Services', 'medium', 'troubleshoot', '["auto-scaling","instance-refresh","deployment"]'::jsonb, 'ai-draft', 'active', now(), now()),
    ('clf-c02-tech-v2-004', 'aws-clf', 'Uma fintech precisa de um load balancer que: termine TLS, faça roteamento por path (/api → backend A, /admin → backend B) e suporte autenticação via Cognito. Qual tipo de ELB atende?', '[{"id":"A","text":"Application Load Balancer (ALB)"},{"id":"B","text":"Network Load Balancer (NLB)"},{"id":"C","text":"Gateway Load Balancer (GWLB)"},{"id":"D","text":"Classic Load Balancer (CLB)"}]'::jsonb, 'A', '{"summary":"Roteamento L7 por path + auth via Cognito = ALB.","whyCorrect":"ALB opera na camada 7 (HTTP/HTTPS), oferece path-based, host-based e header-based routing, termina TLS, integra autenticação nativa com Cognito User Pools e provedores OIDC. É o único ELB com esses três recursos juntos.","whyWrong":{"B":"NLB opera em L4 (TCP/UDP/TLS passthrough) — não enxerga path HTTP, não faz auth Cognito. Termina TLS mas sem regras L7.","C":"GWLB é para inserir appliances de segurança no path do tráfego (firewalls, IDS) via GENEVE — não faz roteamento aplicacional.","D":"CLB é legado, suporta básico L4/L7 mas não path-based routing avançado nem integração com Cognito."},"keyConcept":"ELB types — L7 (ALB), L4 (NLB), bump-in-the-wire (GWLB), legacy (CLB)","compareWith":["ALB vs NLB vs GWLB vs CLB"],"realWorldContext":"Microsserviços com rotas REST diferentes apontando para serviços diferentes, autenticação centralizada.","commonMistakes":"Usar NLB para HTTP achando que ''é mais rápido'' — perde routing L7 e integração de auth.","tutorSeeds":["Quando NLB é preferível a ALB?","Como funciona auth Cognito no ALB internamente?"]}'::jsonb, 'Cloud Technology & Services', 'Cloud Technology & Services', 'easy', 'scenario', '["elb","alb","routing","cognito"]'::jsonb, 'ai-draft', 'active', now(), now()),
    ('clf-c02-tech-v2-005', 'aws-clf', 'Um serviço financeiro precisa de load balancer L4 com IP estático, suporte a milhões de RPS, preservação do IP de origem do cliente e endpoints UDP. Qual é o mais adequado?', '[{"id":"A","text":"Application Load Balancer com sticky sessions"},{"id":"B","text":"Network Load Balancer (NLB)"},{"id":"C","text":"Gateway Load Balancer"},{"id":"D","text":"API Gateway HTTP API"}]'::jsonb, 'B', '{"summary":"L4 + IP estático + UDP + escala extrema = NLB.","whyCorrect":"NLB opera na camada 4, fornece um IP estático por AZ (ou Elastic IP), preserva o IP de origem do cliente, suporta TCP/UDP/TLS e escala para milhões de requisições por segundo com latência ultra-baixa. É o único ELB que atende UDP.","whyWrong":{"A":"ALB é L7, não suporta UDP, não tem IP estático (usa DNS) e não preserva IP de origem nativamente (precisa de X-Forwarded-For).","C":"GWLB é para tráfego de inspeção via appliances, não para servir um endpoint público de aplicação.","D":"API Gateway HTTP API é para REST HTTPS, não L4 nem UDP."},"keyConcept":"NLB — L4, IP estático, preservação de IP de origem, UDP","compareWith":["NLB vs ALB para preservar IP cliente","NLB vs Global Accelerator para IP estático global"],"realWorldContext":"Gaming UDP, IoT MQTT, sistemas legados que exigem IP allowlist, brokers financeiros.","commonMistakes":"Achar que ALB também tem IP estático — não tem; somente NLB e Global Accelerator.","tutorSeeds":["Como NLB preserva o IP de origem para a EC2?","Quando combinar NLB com Global Accelerator?"]}'::jsonb, 'Cloud Technology & Services', 'Cloud Technology & Services', 'medium', 'scenario', '["nlb","elb","udp","static-ip"]'::jsonb, 'ai-draft', 'active', now(), now()),
    ('clf-c02-tech-v2-006', 'aws-clf', 'Uma aplicação HPC precisa que um conjunto de instâncias EC2 se comunique entre si com a menor latência de rede possível, dentro de uma mesma AZ. Qual placement group é mais adequado?', '[{"id":"A","text":"Cluster placement group"},{"id":"B","text":"Spread placement group"},{"id":"C","text":"Partition placement group"},{"id":"D","text":"Multi-AZ placement group"}]'::jsonb, 'A', '{"summary":"Cluster = instâncias próximas fisicamente para latência mínima.","whyCorrect":"Cluster placement group aloca instâncias em um único rack/AZ próximo, oferecendo alta vazão (até 10 Gbps unicast / 25 Gbps multi-flow) e latência mínima. É a escolha para HPC, MPI, simulações científicas.","whyWrong":{"B":"Spread separa cada instância em hardware distinto — maximiza disponibilidade, MINIMIZA proximidade. Latência maior. Limitado a 7 instâncias por AZ.","C":"Partition divide o grupo em até 7 partições isoladas — usado por sistemas distribuídos (Cassandra, HDFS) que toleram falha por partição. Não minimiza latência intra-partição como cluster.","D":"Multi-AZ placement group não existe — placement groups são por AZ por design."},"keyConcept":"Placement groups — Cluster (latência), Spread (HA), Partition (distribuído)","compareWith":["Cluster vs Spread vs Partition placement groups"],"realWorldContext":"Workloads MPI, simulações de fluidos, ML training distribuído com NCCL.","commonMistakes":"Usar cluster pensando que dá HA — é o oposto: tudo num rack significa falha correlacionada.","tutorSeeds":["Por que cluster placement group exige instâncias com Enhanced Networking?","Quando partition placement faz sentido para HDFS?"]}'::jsonb, 'Cloud Technology & Services', 'Cloud Technology & Services', 'medium', 'scenario', '["ec2","placement-group","hpc"]'::jsonb, 'ai-draft', 'active', now(), now()),
    ('clf-c02-tech-v2-007', 'aws-clf', 'Uma equipe usa um cluster Cassandra com 6 nós no EC2 e quer que falha de hardware afete no máximo 1 nó por vez. Qual placement group é o ideal?', '[{"id":"A","text":"Cluster placement group"},{"id":"B","text":"Spread placement group"},{"id":"C","text":"Partition placement group (6 partições)"},{"id":"D","text":"Nenhum, basta espalhar manualmente entre AZs"}]'::jsonb, 'C', '{"summary":"Partition placement isola failure domains — perfeito para Cassandra/HDFS/Kafka.","whyCorrect":"Partition placement group divide as instâncias em partições lógicas (até 7 por AZ), cada uma em hardware independente. Cassandra/HDFS/Kafka mapeiam suas réplicas para partições diferentes — uma falha de rack afeta no máximo uma partição, e o cluster sobrevive.","whyWrong":{"A":"Cluster concentra tudo no mesmo rack — falha derruba todos os nós ao mesmo tempo. O oposto do desejado.","B":"Spread também isola, mas limita a 7 instâncias por AZ no total, sem o conceito de mapeamento partição-a-réplica. Funciona para até 7 instâncias críticas; para 6 nós Cassandra, partition oferece visibilidade da topologia.","D":"Espalhar entre AZs ajuda mas não dá controle de partições dentro da AZ, e a latência cross-AZ degrada o cluster Cassandra."},"keyConcept":"Partition placement group — failure domains para sistemas distribuídos","compareWith":["Partition vs Spread","Partition placement para Cassandra/HDFS/Kafka"],"realWorldContext":"Operadores Kubernetes para StatefulSets, brokers Kafka, datanodes HDFS.","commonMistakes":"Não usar a topology API para alinhar réplicas com partições — sem isso, o ganho é parcial.","tutorSeeds":["Como Cassandra usa a partition placement metadata?","Limite de 7 partições por AZ — como contornar?"]}'::jsonb, 'Cloud Technology & Services', 'Cloud Technology & Services', 'hard', 'scenario', '["ec2","placement-group","partition","distributed-systems"]'::jsonb, 'ai-draft', 'active', now(), now()),
    ('clf-c02-tech-v2-008', 'aws-clf', 'Uma empresa tem workload steady-state que roda 24/7 por 3 anos e quer máximo desconto em EC2, aceitando compromisso de capacidade. Qual modelo de compra oferece o maior desconto?', '[{"id":"A","text":"Savings Plans Compute (1 ano, no upfront)"},{"id":"B","text":"Reserved Instances Standard 3 anos, all upfront"},{"id":"C","text":"Spot Instances com fallback para On-Demand"},{"id":"D","text":"On-Demand com cost allocation tags"}]'::jsonb, 'B', '{"summary":"Maior desconto previsível = RI Standard 3y all upfront (até ~72%).","whyCorrect":"Reserved Instances Standard de 3 anos com pagamento all upfront chegam a ~72% de desconto vs On-Demand. É o maior desconto entre opções comprometidas. O workload steady de 3 anos casa perfeitamente.","whyWrong":{"A":"Savings Plans 1 ano no upfront dá ~27% — bem menor que RI 3y all upfront. Savings Plans tem flexibilidade maior mas desconto menor para mesmo prazo.","C":"Spot oferece até 90% de desconto mas com interrupções de 2 minutos — não combina com workload 24/7 que exige disponibilidade contínua.","D":"On-Demand é a tarifa cheia — zero desconto, só visibilidade via tags."},"keyConcept":"Modelos de pricing EC2 — On-Demand, Savings Plans, RIs, Spot, Dedicated","compareWith":["RI Standard vs Convertible","Savings Plans Compute vs EC2 Instance","RI vs Spot"],"realWorldContext":"Bases de dados gerenciadas próprias, servidores LDAP, cargas que não tolerarão interrupção por 3 anos.","commonMistakes":"Confundir Savings Plans com RI — SP é mais flexível (família/region) mas com desconto ligeiramente menor por prazo equivalente.","tutorSeeds":["Diferença entre Savings Plans Compute e EC2 Instance SP?","Quando Convertible RI supera Standard RI?"]}'::jsonb, 'Cloud Technology & Services', 'Cloud Technology & Services', 'medium', 'best-practice', '["ec2","pricing","reserved-instances","savings-plans"]'::jsonb, 'ai-draft', 'active', now(), now()),
    ('clf-c02-tech-v2-009', 'aws-clf', 'Sobre o comportamento de health checks em um ALB com target group EC2, qual afirmação é VERDADEIRA?', '[{"id":"A","text":"Health checks são apenas TCP — ALB não suporta HTTP health check"},{"id":"B","text":"ALB roteia tráfego somente para targets marcados como healthy; targets unhealthy são removidos do pool e podem disparar replacement no ASG"},{"id":"C","text":"Targets unhealthy continuam recebendo 50% do tráfego para ''aquecimento''"},{"id":"D","text":"ALB health checks só funcionam com instâncias t3.medium ou maiores"}]'::jsonb, 'B', '{"summary":"Targets só recebem tráfego quando healthy; unhealthy aciona ASG replacement se configurado.","whyCorrect":"O ALB envia health checks HTTP/HTTPS (configuráveis: path, port, intervalo, threshold). Targets que falham N health checks consecutivos são marcados unhealthy e removidos do roteamento. Se o ASG usar ELB health check type, esses unhealthy disparam replacement automático da instância.","whyWrong":{"A":"ALB suporta HTTP/HTTPS health checks com path customizável — é o padrão.","C":"Targets unhealthy não recebem tráfego; aquecimento é feito por slow start (recurso separado do target group, opcional).","D":"Não há restrição de tipo de instância para health checks — qualquer EC2 que abra a porta funciona."},"keyConcept":"ALB health checks + ASG ELB health check type para auto-recovery","compareWith":["ELB health check vs EC2 status check no ASG","Health check vs Slow start"],"realWorldContext":"Self-healing — uma instância travada em deadlock é detectada e substituída sem intervenção humana.","commonMistakes":"Configurar threshold muito sensível (1 falha = unhealthy) e ter flapping de targets sob carga.","tutorSeeds":["Diferença entre health check do ALB e status check da EC2?","O que é slow start no target group?"]}'::jsonb, 'Cloud Technology & Services', 'Cloud Technology & Services', 'easy', 'recall', '["elb","alb","health-check","asg"]'::jsonb, 'ai-draft', 'active', now(), now()),
    ('clf-c02-tech-v2-010', 'aws-clf', 'Uma equipe migra um workload Linux que usa Hyper-V drivers específicos e quer rodar em hardware AWS dedicado, mantendo affinity com o mesmo host físico para licenciamento por socket. Qual opção é a correta?', '[{"id":"A","text":"Dedicated Instances"},{"id":"B","text":"Dedicated Hosts"},{"id":"C","text":"Spot Block"},{"id":"D","text":"Capacity Reservations"}]'::jsonb, 'B', '{"summary":"Visibility do hardware físico + affinity = Dedicated Hosts.","whyCorrect":"Dedicated Hosts dão visibilidade do servidor físico (sockets, cores), permitem host affinity (a instância sempre volta ao mesmo host após stop/start) e suportam BYOL com licenciamento por socket/core (Windows, Oracle, SQL Server). Único modelo que atende licenciamento por hardware físico.","whyWrong":{"A":"Dedicated Instances também rodam em hardware dedicado, mas SEM visibilidade do host físico nem affinity — não atende licenciamento por socket.","C":"Spot Block (descontinuado em alguns regions) não tem relação com hardware dedicado.","D":"Capacity Reservations reservam capacidade em uma AZ, mas em hardware compartilhado — sem visibilidade do host físico."},"keyConcept":"Dedicated Hosts vs Dedicated Instances — visibility e affinity","compareWith":["Dedicated Hosts vs Dedicated Instances","BYOL vs licença AWS-included"],"realWorldContext":"Migração de Oracle/SQL Server com licença per-core, compliance que exige tenant isolation.","commonMistakes":"Confundir Dedicated Instances com Hosts — ambos isolam tenant, só Hosts dão visibility/affinity.","tutorSeeds":["Como funciona host affinity após stop/start?","Quando Dedicated Instance é suficiente?"]}'::jsonb, 'Cloud Technology & Services', 'Cloud Technology & Services', 'hard', 'scenario', '["ec2","dedicated-hosts","licensing"]'::jsonb, 'ai-draft', 'active', now(), now()),
    ('clf-c02-tech-v2-011', 'aws-clf', 'Uma equipe pequena tem uma API REST stateless escrita em Python que recebe ~50 requisições por minuto durante o dia útil e zero à noite. A equipe quer o menor esforço operacional e o menor custo possível. Qual serviço é mais indicado?', '[{"id":"A","text":"AWS Lambda atrás de API Gateway HTTP API"},{"id":"B","text":"ECS Fargate com ALB"},{"id":"C","text":"EC2 t3.micro em ASG"},{"id":"D","text":"AWS App Runner com container Python"}]'::jsonb, 'A', '{"summary":"Tráfego intermitente e baixo + zero ops = Lambda + API Gateway HTTP API.","whyCorrect":"Lambda escala de 0 a N automaticamente, paga apenas por invocação + duração (free tier inclui 1M req/mês), zero servidor para gerenciar. API Gateway HTTP API é a opção mais barata e simples para expor Lambda. Para 50 req/min, custo mensal pode ficar em centavos.","whyWrong":{"B":"Fargate exige task rodando 24/7 (mesmo idle) custando ~$10-15/mês mínimo. Para 50 req/min essa task fica 99% idle pagando.","C":"EC2 mesmo t3.micro custa ~$7-8/mês e exige patching, ASG, ALB — overhead alto para volume baixo.","D":"App Runner tem scale-to-zero em alguns modos, mas custo de provisioned instance idle ainda existe; menos vantajoso que Lambda para esse perfil."},"keyConcept":"Lambda vs Fargate vs App Runner vs EC2 — escolha por padrão de carga","compareWith":["Lambda (pay-per-request) vs Fargate (pay-per-task-second)","Scale-to-zero capability"],"realWorldContext":"MVPs, APIs internas de baixo volume, webhooks, backends mobile early-stage.","commonMistakes":"Achar que Fargate é ''serverless igual Lambda'' — é serverless de container, mas paga continuamente.","tutorSeeds":["Quando Lambda fica mais caro que Fargate?","App Runner scale-to-zero — quando vale?"]}'::jsonb, 'Cloud Technology & Services', 'Cloud Technology & Services', 'easy', 'scenario', '["lambda","fargate","app-runner","serverless"]'::jsonb, 'ai-draft', 'active', now(), now()),
    ('clf-c02-tech-v2-012', 'aws-clf', 'Uma equipe migra um monolito Java de 800 MB com tempo de boot de 45 segundos para AWS. A função precisa de 2 vCPUs, 8 GB de RAM e tráfego constante (500 req/s, 24/7). Qual escolha minimiza custo e complexidade operacional?', '[{"id":"A","text":"AWS Lambda com SnapStart"},{"id":"B","text":"ECS Fargate com 2 tasks ALB-balanced"},{"id":"C","text":"API Gateway + Lambda com 10 GB de memória"},{"id":"D","text":"App Runner com 1 GB de memória"}]'::jsonb, 'B', '{"summary":"Tráfego constante + processo pesado de 8 GB = Fargate vence Lambda no custo.","whyCorrect":"Para tráfego constante e alta carga, Lambda fica caro (paga por invocação × duração × memória) — 500 req/s em Lambda com 8 GB seria ordem de centenas de dólares/dia. Fargate roda containers continuamente com custo fixo por task; 2 tasks atendem facilmente 500 req/s, e o boot único de 45s acontece só no deploy.","whyWrong":{"A":"SnapStart reduz cold start mas Lambda ainda custa por invocação — em tráfego constante de 500 req/s, é economicamente pior que Fargate. E SnapStart é apenas Java/Python/.NET, ajuda no startup mas não no custo de operação contínua.","C":"10 GB memória em Lambda + alto throughput = custo enorme. Lambda max memory é 10 GB mas isso não muda o problema econômico.","D":"App Runner com 1 GB não atende 8 GB de RAM do workload."},"keyConcept":"Crossover econômico Lambda → Fargate em workloads de alta utilização","compareWith":["Lambda vs Fargate por utilization","SnapStart escopo de uso"],"realWorldContext":"Aplicações JVM legadas, monolitos sendo modernizados parcialmente.","commonMistakes":"Usar Lambda ''por padrão'' sem analisar custo em tráfego constante — pode ser 5-10x mais caro que Fargate.","tutorSeeds":["Qual o ponto de crossover Lambda/Fargate por utilization?","Como SnapStart funciona internamente?"]}'::jsonb, 'Cloud Technology & Services', 'Cloud Technology & Services', 'hard', 'scenario', '["lambda","fargate","cost-optimization","serverless-tradeoffs"]'::jsonb, 'ai-draft', 'active', now(), now()),
    ('clf-c02-tech-v2-013', 'aws-clf', 'Uma equipe quer hospedar uma aplicação web Node.js a partir de um repositório GitHub, com deploy automático em git push, scale-to-zero opcional e HTTPS gerenciado, sem escrever Dockerfile. Qual serviço é mais alinhado?', '[{"id":"A","text":"AWS App Runner (com source code)"},{"id":"B","text":"AWS Elastic Beanstalk"},{"id":"C","text":"ECS com Fargate e CodePipeline"},{"id":"D","text":"Lambda com camada Node.js"}]'::jsonb, 'A', '{"summary":"Code-to-URL sem Dockerfile + scale-to-zero = App Runner.","whyCorrect":"App Runner aceita source code direto do GitHub (Node.js, Python, Java, etc.), constrói a imagem automaticamente, faz deploy contínuo a cada push, gerencia HTTPS e oferece scale-to-zero (provisioned 0 instances). É o serviço mais alinhado com ''do código à URL'' sem ops.","whyWrong":{"B":"Elastic Beanstalk também suporta source mas é mais antigo, sem scale-to-zero nativo e expõe mais da infra subjacente (EC2/ASG/ELB).","C":"ECS+Fargate+CodePipeline exige Dockerfile, definição de task, ALB — muito mais cerimônia.","D":"Lambda exige adaptar a aplicação ao modelo de evento (handler), não roda Node.js HTTP server contínuo facilmente sem Lambda Web Adapter."},"keyConcept":"App Runner — source-to-URL serverless para containers/source","compareWith":["App Runner vs Elastic Beanstalk","App Runner vs Fargate"],"realWorldContext":"Sites institucionais, dashboards internos, APIs de baixa-média carga, MVPs.","commonMistakes":"Achar que Elastic Beanstalk e App Runner são o mesmo — EB é PaaS expondo a infra; AR é fully managed.","tutorSeeds":["Quando App Runner não é suficiente (recursos)?","App Runner suporta VPC connector?"]}'::jsonb, 'Cloud Technology & Services', 'Cloud Technology & Services', 'easy', 'scenario', '["app-runner","serverless","deployment"]'::jsonb, 'ai-draft', 'active', now(), now()),
    ('clf-c02-tech-v2-014', 'aws-clf', 'Uma equipe usa Lambda e descobre que precisa processar arquivos de 800 MB. Qual abordagem é VIÁVEL respeitando os limites do Lambda?', '[{"id":"A","text":"Aumentar o /tmp ephemeral storage do Lambda até 10 GB para baixar o arquivo"},{"id":"B","text":"Aumentar a memória para 50 GB e processar in-memory"},{"id":"C","text":"Lambda não pode processar arquivos maiores que 6 MB em nenhuma circunstância"},{"id":"D","text":"Usar EFS mount com Lambda e processar streaming"}]'::jsonb, 'A', '{"summary":"/tmp do Lambda pode ser configurado até 10 GB — suficiente para 800 MB.","whyCorrect":"Lambda permite configurar ephemeral storage (/tmp) de 512 MB até 10 GB. Baixar 800 MB de S3 para /tmp, processar, e fazer upload de volta é totalmente viável dentro do timeout máximo de 15 min.","whyWrong":{"B":"Memória máxima do Lambda é 10 GB, não 50 GB. Mesmo assim 10 GB seria suficiente para 800 MB in-memory — mas o erro está em ''50 GB''.","C":"O limite de 6 MB se aplica a payload sync de invocação (request/response), não ao processamento de arquivos baixados de outras fontes.","D":"EFS com Lambda funciona também (resposta plausível!), mas o ENUNCIADO pede ''qual abordagem é viável'' e tanto /tmp quanto EFS funcionam. A diferença: D está correta tecnicamente mas /tmp é a abordagem mais simples e padrão. A questão tem só uma melhor — /tmp é mais simples, sem dependência de VPC/EFS. Note: na prova real CLF, o limite de 10 GB do /tmp é o conceito chave testado."},"keyConcept":"Lambda limits — /tmp 10 GB, memória 10 GB, timeout 15 min, payload sync 6 MB","compareWith":["/tmp ephemeral vs EFS para Lambda","Sync invocation payload vs object size processado"],"realWorldContext":"Processamento de imagens grandes, conversões de mídia, ML inference com modelos pesados.","commonMistakes":"Confundir payload limit (6 MB) com objetos processáveis (limite real é só /tmp/memória/timeout).","tutorSeeds":["Quando EFS supera /tmp para Lambda?","Custos de /tmp expandido?"]}'::jsonb, 'Cloud Technology & Services', 'Cloud Technology & Services', 'medium', 'best-practice', '["lambda","limits","ephemeral-storage"]'::jsonb, 'ai-draft', 'active', now(), now()),
    ('clf-c02-tech-v2-015', 'aws-clf', 'Sobre o modelo de concurrency do AWS Lambda, qual afirmação é VERDADEIRA?', '[{"id":"A","text":"Cada conta tem limite hard de 1000 execuções concorrentes que NÃO pode ser aumentado"},{"id":"B","text":"Reserved concurrency garante capacidade dedicada e também limita a função a esse valor máximo"},{"id":"C","text":"Provisioned concurrency é gratuita quando não invocada"},{"id":"D","text":"Concurrency é por região e por função, sem limite por conta"}]'::jsonb, 'B', '{"summary":"Reserved concurrency tem duplo papel: reserva E limita.","whyCorrect":"Reserved concurrency reserva N execuções para a função (garantia mínima) e também atua como teto máximo. Útil para isolar funções críticas (garantir capacidade) e para limitar funções que poderiam consumir todo o pool da conta (rate limit downstream).","whyWrong":{"A":"O limite default de 1000 por região POR CONTA pode ser aumentado via Service Quotas — não é hard.","C":"Provisioned concurrency cobra por inicialização mantida QUENTE, mesmo sem invocação. Justamente o trade-off: latência baixa em troca de custo continuo.","D":"Concurrency é por região POR CONTA (compartilhada entre funções), não ''sem limite por conta''."},"keyConcept":"Reserved vs Provisioned concurrency — duplo papel de reserved","compareWith":["Reserved concurrency vs Provisioned concurrency","Account limit vs function limit"],"realWorldContext":"Proteger RDS downstream contra avalanche de Lambdas via reserved=10.","commonMistakes":"Confundir reserved (só garante slot, paga por invocação) com provisioned (mantém quente, paga sempre).","tutorSeeds":["Como reserved concurrency protege downstream?","Quando provisioned vale o custo extra?"]}'::jsonb, 'Cloud Technology & Services', 'Cloud Technology & Services', 'medium', 'recall', '["lambda","concurrency","limits"]'::jsonb, 'ai-draft', 'active', now(), now()),
    ('clf-c02-tech-v2-016', 'aws-clf', 'Uma equipe quer minimizar latência de aplicação Lambda que serve uma API REST pública. Mediram p99 com cold start de 800ms. Querem reduzir para p99 < 100ms sem reescrever a função. Qual ação tem maior impacto?', '[{"id":"A","text":"Habilitar Provisioned Concurrency para a versão atual"},{"id":"B","text":"Aumentar memória de 512 MB para 1024 MB"},{"id":"C","text":"Mudar runtime de Python para Go"},{"id":"D","text":"Habilitar X-Ray tracing"}]'::jsonb, 'A', '{"summary":"Provisioned Concurrency mantém ambientes quentes — elimina cold start.","whyCorrect":"Provisioned Concurrency pré-inicializa N ambientes (containers Lambda) e os mantém quentes. Cold start cai para ~10-20ms (essencialmente inexistente). Para uma API com SLA agressivo, é a ação de maior impacto e sem mudar código.","whyWrong":{"B":"Aumentar memória reduz tempo de execução e cold start (proporcional a vCPU), mas ainda permanecerá cold start de centenas de ms em runtimes pesados — não chega a p99 < 100ms.","C":"Mudar runtime é reescrita — viola a restrição ''sem reescrever''. E ainda haveria cold starts (menores, mas presentes).","D":"X-Ray é observability, não reduz latência — pelo contrário, adiciona overhead leve."},"keyConcept":"Provisioned Concurrency — eliminação de cold start","compareWith":["Provisioned Concurrency vs SnapStart vs Lambda warmup tricks"],"realWorldContext":"APIs públicas com SLA, checkout flows, gateways de pagamento.","commonMistakes":"Provisioned em desenvolvimento — custo desnecessário; ative só em produção e em horários de alto tráfego (Application Auto Scaling).","tutorSeeds":["Como auto-scalar Provisioned Concurrency?","SnapStart vs Provisioned — quando usar cada?"]}'::jsonb, 'Cloud Technology & Services', 'Cloud Technology & Services', 'easy', 'troubleshoot', '["lambda","provisioned-concurrency","cold-start","performance"]'::jsonb, 'ai-draft', 'active', now(), now()),
    ('clf-c02-tech-v2-017', 'aws-clf', 'Uma startup avalia Fargate vs App Runner para uma API de baixa carga (10 req/s) em container. Qual diferença é VERDADEIRA?', '[{"id":"A","text":"App Runner faz scale-to-zero (provisioned 0); Fargate exige task rodando continuamente"},{"id":"B","text":"Fargate é serverless mas App Runner exige gerenciar EC2 host"},{"id":"C","text":"App Runner não suporta HTTPS; Fargate sim via ALB"},{"id":"D","text":"Fargate suporta deploy do source code, App Runner não"}]'::jsonb, 'A', '{"summary":"App Runner = scale-to-zero possível; Fargate = task contínua.","whyCorrect":"App Runner suporta modo ''provisioned instances = 0'' onde escala para zero em inatividade (com cold start na primeira req). Fargate exige pelo menos 1 task rodando para responder rápido — sem scale-to-zero nativo.","whyWrong":{"B":"App Runner é serverless também; ninguém gerencia EC2 em App Runner.","C":"App Runner provê HTTPS gerenciado nativamente — é uma das suas vantagens.","D":"App Runner suporta deploy DIRETO do source code (Node/Python/Java/etc), Fargate exige imagem container."},"keyConcept":"App Runner vs Fargate — scale-to-zero e source-to-URL","compareWith":["App Runner vs Fargate vs Lambda"],"realWorldContext":"APIs internas de uso esporádico, ambientes de dev/staging.","commonMistakes":"Achar que Fargate é a opção ''mais serverless'' — App Runner é mais alto nível.","tutorSeeds":["App Runner suporta WebSocket?","Quando Fargate vence App Runner em produção?"]}'::jsonb, 'Cloud Technology & Services', 'Cloud Technology & Services', 'medium', 'best-practice', '["app-runner","fargate","serverless-tradeoffs"]'::jsonb, 'ai-draft', 'active', now(), now()),
    ('clf-c02-tech-v2-018', 'aws-clf', 'Uma equipe usa Lambda integrado com SQS como event source. Mensagens estão sendo processadas múltiplas vezes inesperadamente. Qual é a causa MAIS provável?', '[{"id":"A","text":"A função Lambda retorna erro ou timeout, fazendo a mensagem voltar à fila após VisibilityTimeout"},{"id":"B","text":"SQS Standard sempre entrega exatamente uma vez; o problema é bug do código"},{"id":"C","text":"Lambda automaticamente duplica mensagens para garantir alta disponibilidade"},{"id":"D","text":"É necessário habilitar ''exactly-once delivery'' no Lambda (config padrão é ''at-least-many'')"}]'::jsonb, 'A', '{"summary":"Lambda + SQS = at-least-once. Erro/timeout = mensagem reaparece após VisibilityTimeout.","whyCorrect":"Lambda+SQS é at-least-once por design. Se a função falhar (erro ou timeout) antes de retornar sucesso, o batch não é deletado da fila e reaparece após o VisibilityTimeout, sendo reprocessado. Soluções: garantir idempotência, ajustar VisibilityTimeout >= timeout do Lambda × 6, configurar maxReceiveCount + DLQ.","whyWrong":{"B":"SQS Standard é at-least-once, não exactly-once. Só SQS FIFO oferece exactly-once dentro da janela de deduplicação.","C":"Lambda não ''duplica para HA'' — o que pode haver é processamento paralelo de batches diferentes, não duplicação intencional.","D":"Não existe flag ''exactly-once delivery'' no Lambda — a propriedade vem do tipo de fila (Standard vs FIFO) e da lógica idempotente da função."},"keyConcept":"Lambda + SQS — at-least-once delivery e VisibilityTimeout","compareWith":["SQS Standard vs FIFO entrega","VisibilityTimeout vs Lambda timeout"],"realWorldContext":"Processamento de pagamentos, ingestão de eventos — idempotência é mandatória.","commonMistakes":"Setar VisibilityTimeout < timeout Lambda — garante reprocessamento mesmo quando função ainda está rodando.","tutorSeeds":["Por que VisibilityTimeout >= 6× Lambda timeout?","Como implementar idempotência com DynamoDB?"]}'::jsonb, 'Cloud Technology & Services', 'Cloud Technology & Services', 'hard', 'troubleshoot', '["lambda","sqs","at-least-once","idempotency"]'::jsonb, 'ai-draft', 'active', now(), now()),
    ('clf-c02-tech-v2-019', 'aws-clf', 'Em Amazon ECS, qual é a diferença correta entre task definition e service?', '[{"id":"A","text":"Task definition é o ''blueprint'' (imagem, CPU, memória, env vars); service é o orquestrador que mantém N tasks rodando, integra com ALB e faz rolling updates"},{"id":"B","text":"Service é o blueprint estático; task definition orquestra deploy"},{"id":"C","text":"Task definition só funciona com EC2 launch type; service só com Fargate"},{"id":"D","text":"Ambos são iguais — apenas nomes diferentes para o mesmo recurso"}]'::jsonb, 'A', '{"summary":"Task definition = receita; Service = controller que mantém desired count.","whyCorrect":"Task definition descreve o quê (containers, CPU/mem, networking mode, volumes, env vars, IAM role, ports). Service usa essa task definition e mantém um desired count de tasks rodando, atualiza versões (rolling/blue-green via CodeDeploy), integra com target groups ALB/NLB e Service Discovery.","whyWrong":{"B":"Inverte os papéis — task def é blueprint, service é orquestrador.","C":"Task definitions e services funcionam em ambos launch types (EC2 e Fargate). O launch type é uma propriedade.","D":"São recursos distintos com responsabilidades distintas."},"keyConcept":"ECS — task definition (template) vs task (instância) vs service (controller)","compareWith":["ECS Task vs Pod do K8s","ECS Service vs Deployment do K8s"],"realWorldContext":"Microsserviços ECS com 20 services, cada um com sua task definition e auto-scaling independente.","commonMistakes":"Confundir task com task definition — task é a execução, task definition é o JSON do blueprint.","tutorSeeds":["O que é Task Family e versionamento de task definition?","ECS Service vs Standalone Task (RunTask)?"]}'::jsonb, 'Cloud Technology & Services', 'Cloud Technology & Services', 'medium', 'recall', '["ecs","task-definition","service"]'::jsonb, 'ai-draft', 'active', now(), now()),
    ('clf-c02-tech-v2-020', 'aws-clf', 'Uma equipe migra cargas Kubernetes para AWS e quer evitar gerenciar EC2 worker nodes. Quer rodar pods diretamente em capacidade serverless. Qual configuração é adequada?', '[{"id":"A","text":"EKS com Fargate profiles"},{"id":"B","text":"EKS com Managed Node Groups EC2"},{"id":"C","text":"EKS Self-Managed Nodes"},{"id":"D","text":"ECS com Fargate"}]'::jsonb, 'A', '{"summary":"EKS + Fargate profiles = pods serverless sem gerenciar nodes.","whyCorrect":"EKS Fargate profiles permitem que pods que matchem o seletor (namespace/labels) rodem em capacidade Fargate, sem worker nodes EC2. Você não gerencia EC2, patching, escalonamento de nodes — apenas pods.","whyWrong":{"B":"Managed Node Groups EC2 ainda exigem gerenciamento (AWS provê a infra mas você ainda lida com escalonamento de nodes, atualizações de AMI, instance types).","C":"Self-managed é o mais hands-on — você cria EC2, instala kubelet, junta no cluster.","D":"ECS Fargate atende serverless de containers, MAS NÃO é Kubernetes. A questão pede manter K8s."},"keyConcept":"EKS launch options — Fargate, Managed Node Groups, Self-managed","compareWith":["EKS Fargate vs Managed Node Groups","EKS vs ECS"],"realWorldContext":"Migração lift-and-shift de cluster K8s on-prem mantendo manifests, mas sem gerenciar nodes.","commonMistakes":"Esquecer limites do Fargate no EKS — sem DaemonSets, sem privileged pods, sem GPUs.","tutorSeeds":["O que Fargate profile NÃO suporta no EKS?","Como dimensionar mix Fargate + Managed nodes?"]}'::jsonb, 'Cloud Technology & Services', 'Cloud Technology & Services', 'medium', 'scenario', '["eks","fargate","serverless"]'::jsonb, 'ai-draft', 'active', now(), now()),
    ('clf-c02-tech-v2-021', 'aws-clf', 'Uma equipe usa Amazon ECR e quer detectar vulnerabilidades em imagens push (CVE de pacotes do SO e bibliotecas). Qual recurso oferece scan profundo contínuo?', '[{"id":"A","text":"ECR Basic Scanning (Clair)"},{"id":"B","text":"ECR Enhanced Scanning (Amazon Inspector)"},{"id":"C","text":"GuardDuty Malware Protection for ECR"},{"id":"D","text":"AWS Config managed rule ecr-image-scan"}]'::jsonb, 'B', '{"summary":"ECR Enhanced Scanning usa Amazon Inspector para scan contínuo e profundo (SO + linguagens).","whyCorrect":"Enhanced Scanning integra Amazon Inspector, faz scan contínuo de imagens (não só no push), detecta CVE em pacotes do SO (Alpine, Debian, etc.) e bibliotecas de aplicação (npm, pip, Maven, etc.). Cobertura muito mais profunda que Basic.","whyWrong":{"A":"Basic Scanning usa CoreOS Clair — só escaneia no push, só CVE de SO, sem cobertura de bibliotecas de linguagem.","C":"GuardDuty Malware Protection é para detecção de malware em volumes EBS (não para CVE de imagem container).","D":"Config rule pode VERIFICAR se scan está habilitado mas não realiza o scan em si."},"keyConcept":"ECR Basic vs Enhanced Scanning (Inspector integration)","compareWith":["ECR Basic vs Enhanced Scanning","Inspector EC2 vs Inspector ECR"],"realWorldContext":"Pipelines DevSecOps com gate de vulnerabilidades antes de promoção a prod.","commonMistakes":"Achar que Basic Scanning detecta CVE em libs Python/Node — só pega SO.","tutorSeeds":["Como configurar threshold de CVE no ECR?","Custos de Enhanced Scanning vs Basic?"]}'::jsonb, 'Cloud Technology & Services', 'Cloud Technology & Services', 'medium', 'best-practice', '["ecr","security","scanning","inspector"]'::jsonb, 'ai-draft', 'active', now(), now()),
    ('clf-c02-tech-v2-022', 'aws-clf', 'Uma equipe ECS Fargate quer compartilhar um volume entre dois containers da mesma task. Qual recurso suporta esse compartilhamento?', '[{"id":"A","text":"Bind mount (volume Docker padrão) na task definition"},{"id":"B","text":"EBS volume diretamente attached à task Fargate"},{"id":"C","text":"Instance Store da EC2 host"},{"id":"D","text":"S3 montado como filesystem via FUSE"}]'::jsonb, 'A', '{"summary":"Bind mounts compartilham dados efêmeros entre containers da mesma task Fargate.","whyCorrect":"Bind mounts (volume tipo ''bind'') montam um diretório efêmero da task em múltiplos containers da mesma task — perfeito para sidecar patterns onde, ex., um container baixa config e outro consome. Dados são perdidos quando a task termina.","whyWrong":{"B":"EBS attachado a Fargate é recente e suportado, mas o caso pede compartilhamento entre containers da MESMA task — bind mount é o padrão idiomático. EBS é para persistência além da vida da task.","C":"Instance Store de EC2 host não se aplica — Fargate não expõe host.","D":"S3 via FUSE não é nativo nem suportado para ECS Fargate task storage."},"keyConcept":"ECS volumes — bind mounts (efêmero compartilhado) vs EFS (persistente) vs EBS Fargate","compareWith":["Bind mount vs EFS volume vs EBS volume em ECS"],"realWorldContext":"Sidecar de log shipping lendo logs de container principal via volume compartilhado.","commonMistakes":"Esperar persistência em bind mount — dados morrem com a task.","tutorSeeds":["Quando usar EFS volume em ECS?","Limites de tamanho do bind mount no Fargate?"]}'::jsonb, 'Cloud Technology & Services', 'Cloud Technology & Services', 'hard', 'scenario', '["ecs","fargate","volumes","sidecar"]'::jsonb, 'ai-draft', 'active', now(), now()),
    ('clf-c02-tech-v2-023', 'aws-clf', 'Em EKS, uma equipe quer auto-escalar pods baseado em métricas customizadas (ex: msgs em fila SQS). Qual combinação é a padrão?', '[{"id":"A","text":"Horizontal Pod Autoscaler (HPA) + Metrics Server apenas"},{"id":"B","text":"HPA + KEDA (Kubernetes Event-Driven Autoscaling)"},{"id":"C","text":"Cluster Autoscaler do EKS"},{"id":"D","text":"AWS Auto Scaling Group no Managed Node Group"}]'::jsonb, 'B', '{"summary":"HPA + KEDA = autoscaling de pods por eventos externos (SQS, Kafka, etc.).","whyCorrect":"HPA nativo só escala em CPU/memória ou métricas via Metrics Server. KEDA estende HPA com scalers para 50+ fontes (SQS, Kafka, Prometheus, etc.), incluindo scale-to-zero. É o padrão de fato para event-driven autoscaling no K8s.","whyWrong":{"A":"Metrics Server só expõe CPU/memória dos pods — não enxerga SQS.","C":"Cluster Autoscaler ajusta o número de NODES, não pods.","D":"ASG do Managed Node Group escala nodes, não pods. E não enxerga SQS diretamente."},"keyConcept":"Kubernetes autoscaling — HPA (pods), VPA (recursos do pod), Cluster Autoscaler (nodes), KEDA (event-driven)","compareWith":["HPA vs KEDA","Cluster Autoscaler vs Karpenter"],"realWorldContext":"Workers consumindo de SQS que precisam escalar de 0 a 100 conforme depth da fila.","commonMistakes":"Confundir HPA com Cluster Autoscaler — operam em camadas diferentes.","tutorSeeds":["KEDA vs HPA com External Metrics — diferença prática?","Karpenter vs Cluster Autoscaler no EKS?"]}'::jsonb, 'Cloud Technology & Services', 'Cloud Technology & Services', 'hard', 'best-practice', '["eks","autoscaling","keda","hpa"]'::jsonb, 'ai-draft', 'active', now(), now()),
    ('clf-c02-tech-v2-024', 'aws-clf', 'Uma equipe ECS quer fazer service discovery entre microsserviços sem usar ALB. Cada serviço deve ser resolvível por nome DNS interno. Qual recurso AWS é o nativo para isso?', '[{"id":"A","text":"AWS Cloud Map (Service Discovery) integrado com ECS"},{"id":"B","text":"Route 53 público com health checks"},{"id":"C","text":"CloudFront com behaviors por serviço"},{"id":"D","text":"DynamoDB com lookup table"}]'::jsonb, 'A', '{"summary":"AWS Cloud Map = service discovery DNS nativo do ECS.","whyCorrect":"Cloud Map cria namespaces (públicos ou privados via Route 53) e registra automaticamente tasks ECS com nomes DNS, atualizando entries conforme tasks sobem/descem. Cliente faz lookup do nome e recebe IPs/portas atuais — sem ALB.","whyWrong":{"B":"Route 53 público não é apropriado para internal service discovery dinâmico de tasks que sobem/descem frequentemente — Cloud Map é a camada acima do Route 53 privado que automatiza isso.","C":"CloudFront é CDN, sem relação com service discovery.","D":"DynamoDB lookup é solução caseira — não nativa, exige código de cliente."},"keyConcept":"ECS Service Discovery via AWS Cloud Map","compareWith":["Cloud Map vs ALB para microsserviços","Cloud Map vs Service Mesh (App Mesh)"],"realWorldContext":"Comunicação service-to-service sem balanceador L7 intermediário (redução de hop + latência).","commonMistakes":"Achar que ALB é obrigatório para microsserviços — em meshes internos Cloud Map basta.","tutorSeeds":["Quando service mesh supera service discovery puro?","Cloud Map para EKS — mesmo modelo?"]}'::jsonb, 'Cloud Technology & Services', 'Cloud Technology & Services', 'medium', 'scenario', '["ecs","service-discovery","cloud-map"]'::jsonb, 'ai-draft', 'active', now(), now()),
    ('clf-c02-tech-v2-025', 'aws-clf', 'Uma empresa armazena 2 PB de dados em S3 mas não sabe quais objetos serão acessados em que frequência. Quer otimizar custo sem riscos de retrieval fees inesperados. Qual storage class é o melhor padrão?', '[{"id":"A","text":"S3 Standard"},{"id":"B","text":"S3 Intelligent-Tiering (com tier de Deep Archive opcional)"},{"id":"C","text":"S3 Glacier Flexible Retrieval"},{"id":"D","text":"S3 One Zone-IA"}]'::jsonb, 'B', '{"summary":"Padrão desconhecido + zero retrieval fees = Intelligent-Tiering.","whyCorrect":"Intelligent-Tiering monitora padrão de acesso por objeto e move automaticamente entre Frequent, Infrequent (30 dias sem acesso), Archive Instant (90 dias), Archive (90+ dias opt-in) e Deep Archive (180+ dias opt-in). Sem retrieval fees nos tiers padrão. Cobra pequena taxa de monitoramento por objeto.","whyWrong":{"A":"Standard é o mais caro para storage — não otimiza nada para 2 PB.","C":"Glacier Flexible Retrieval impõe minutos-horas de retrieval e retrieval fees — risco se padrão for misto.","D":"One Zone-IA pressupõe acesso infrequente E tolerância a perda de AZ. Sem saber o padrão, é arriscado."},"keyConcept":"S3 Intelligent-Tiering — auto-tiering sem retrieval fees nos tiers padrão","compareWith":["Standard vs Intelligent-Tiering vs Glacier","Auto-tiering vs Lifecycle manual"],"realWorldContext":"Data lakes, ML datasets, archives de empresa sem padrões claros.","commonMistakes":"Habilitar opt-in tiers (Archive/Deep Archive) sem entender retrieval times — pode quebrar SLA de leitura.","tutorSeeds":["Como funciona a taxa de monitoramento do IT?","Quando IT NÃO compensa (objetos < 128 KB)?"]}'::jsonb, 'Cloud Technology & Services', 'Cloud Technology & Services', 'medium', 'scenario', '["s3","intelligent-tiering","cost-optimization"]'::jsonb, 'ai-draft', 'active', now(), now()),
    ('clf-c02-tech-v2-026', 'aws-clf', 'Uma equipe precisa de um storage class S3 para dados temporários (logs intermediários) acessados algumas vezes por mês, podendo TOLERAR perda em caso de desastre de uma AZ específica. Qual é o mais econômico?', '[{"id":"A","text":"S3 Standard-IA"},{"id":"B","text":"S3 One Zone-IA"},{"id":"C","text":"S3 Glacier Instant Retrieval"},{"id":"D","text":"S3 Standard"}]'::jsonb, 'B', '{"summary":"Acesso infrequente + tolera falha de AZ = One Zone-IA (até 20% mais barato que Standard-IA).","whyCorrect":"S3 One Zone-IA armazena dados em uma única AZ (vs 3+ em outras classes). Para dados recriáveis ou temporários, custo é ~20% menor que Standard-IA. Acesso infrequente com retrieval rápido e baixas fees.","whyWrong":{"A":"Standard-IA também é IA mas multi-AZ — mais caro que One Zone-IA para o mesmo padrão de acesso.","C":"Glacier Instant Retrieval é até mais barato em storage mas tem retrieval fees mais altos e mínimo de 90 dias de armazenamento — penaliza dados temporários.","D":"Standard não otimiza para acesso infrequente."},"keyConcept":"One Zone-IA — trade durabilidade-de-AZ por custo","compareWith":["Standard-IA (3-AZ) vs One Zone-IA (1-AZ)","One Zone-IA vs Glacier IR"],"realWorldContext":"Backups secundários, logs de debug, intermediários de pipeline ETL.","commonMistakes":"Usar One Zone-IA para dados originais únicos — perda de AZ = dados perdidos para sempre.","tutorSeeds":["Por que One Zone-IA tem 99.5% disponibilidade vs 99.9% das outras?","Min storage duration de cada IA class?"]}'::jsonb, 'Cloud Technology & Services', 'Cloud Technology & Services', 'medium', 'scenario', '["s3","one-zone-ia","cost-optimization"]'::jsonb, 'ai-draft', 'active', now(), now()),
    ('clf-c02-tech-v2-027', 'aws-clf', 'Sobre S3 Glacier — Instant Retrieval, Flexible Retrieval e Deep Archive — qual afirmação está CORRETA?', '[{"id":"A","text":"Instant Retrieval entrega objetos em milissegundos (como S3 Standard), Flexible em minutos-horas, Deep Archive em horas (até 12h)"},{"id":"B","text":"Os três têm o mesmo tempo de retrieval (12h); só o preço difere"},{"id":"C","text":"Deep Archive não permite retrieval algum — só restore via Snowball"},{"id":"D","text":"Instant Retrieval e Flexible Retrieval são o mesmo serviço com nomes diferentes"}]'::jsonb, 'A', '{"summary":"Três tiers Glacier com retrieval crescente: ms / minutos-horas / horas.","whyCorrect":"Glacier Instant Retrieval (GIR) entrega em milissegundos como Standard — para dados acessados ~uma vez/trimestre. Flexible Retrieval (antigo Glacier) oferece Expedited (1-5 min), Standard (3-5h), Bulk (5-12h). Deep Archive é o mais barato com retrieval em ~12h (Standard) ou 48h (Bulk).","whyWrong":{"B":"Têm tempos muito diferentes — diferença central entre eles.","C":"Deep Archive permite retrieval via S3 (RestoreObject) — Snowball é opcional para grandes volumes.","D":"São distintos: IR é ms; Flexible é minutos-horas. Preços e SLAs diferentes."},"keyConcept":"Glacier tiers — IR (ms) / Flexible (min-h) / Deep Archive (h)","compareWith":["Glacier IR vs Standard-IA","Glacier Flexible vs Deep Archive"],"realWorldContext":"Compliance financeiro/saúde com retenção 7-10 anos = Deep Archive; arquivos ''cold'' com leitura ocasional rápida = IR.","commonMistakes":"Achar ''Glacier = lento'' indiscriminadamente — GIR é instantâneo.","tutorSeeds":["Minimum storage duration de cada tier Glacier?","Custos de retrieval comparados?"]}'::jsonb, 'Cloud Technology & Services', 'Cloud Technology & Services', 'medium', 'recall', '["s3","glacier","tiers","retrieval"]'::jsonb, 'ai-draft', 'active', now(), now()),
    ('clf-c02-tech-v2-028', 'aws-clf', 'Uma equipe configura S3 Lifecycle Policy para transitar objetos: Standard → Standard-IA (30 dias) → Glacier Flexible (90 dias) → expiration (365 dias). Qual restrição é VERDADEIRA?', '[{"id":"A","text":"Standard-IA exige objetos com pelo menos 30 dias E tamanho mínimo de 128 KB para a transição fazer sentido (min storage duration de 30 dias)"},{"id":"B","text":"Não há restrição — qualquer transição é livre"},{"id":"C","text":"Glacier exige que objetos tenham nascido em Glacier; transição é proibida"},{"id":"D","text":"Expiration não pode ocorrer antes de 1000 dias"}]'::jsonb, 'A', '{"summary":"S3-IA cobra min 30 dias de armazenamento + min 128 KB por objeto.","whyCorrect":"Standard-IA, One Zone-IA e Glacier IR têm minimum storage duration de 30 dias (cobrado mesmo se deletar antes) e minimum billable object size de 128 KB (objetos menores são cobrados como 128 KB). Glacier Flexible tem min de 90 dias; Deep Archive 180 dias. Por isso transitar objeto pequeno cedo pode AUMENTAR custo.","whyWrong":{"B":"Há restrições importantes de minimum storage e size.","C":"S3 transita normalmente para Glacier; não exige origem em Glacier.","D":"Expiration pode ocorrer em qualquer prazo configurado (1 dia em diante)."},"keyConcept":"S3 Lifecycle — minimum storage duration e min billable object size por tier","compareWith":["Min storage duration por storage class","Object size penalties em IA tiers"],"realWorldContext":"Logs muito pequenos (<128 KB) podem ficar mais caros em IA do que em Standard.","commonMistakes":"Transitar milhões de objetos pequenos para IA — explode o custo por causa do min 128 KB.","tutorSeeds":["Por que IA tiers cobram min 128 KB?","Como evitar custo extra com objetos pequenos?"]}'::jsonb, 'Cloud Technology & Services', 'Cloud Technology & Services', 'hard', 'best-practice', '["s3","lifecycle","minimum-duration","cost"]'::jsonb, 'ai-draft', 'active', now(), now()),
    ('clf-c02-tech-v2-029', 'aws-clf', 'Uma equipe ativa S3 Intelligent-Tiering em um bucket. Qual recurso adicional permite analisar e VISUALIZAR padrões de acesso para decidir lifecycle policies em outros buckets?', '[{"id":"A","text":"S3 Storage Lens"},{"id":"B","text":"S3 Inventory apenas"},{"id":"C","text":"S3 Analytics — Storage Class Analysis"},{"id":"D","text":"CloudWatch Metrics for S3"}]'::jsonb, 'C', '{"summary":"Storage Class Analysis observa padrão de acesso e recomenda lifecycle para Standard-IA.","whyCorrect":"S3 Analytics — Storage Class Analysis monitora padrões de acesso (idade do objeto vs acesso) e produz recomendações para transitar para Standard-IA. Output em CSV exportável e visualizável no console.","whyWrong":{"A":"Storage Lens dá analytics organizacional agregado (uso, custo, atividade) mas não recomenda transitions específicas como Analytics.","B":"Inventory lista objetos e metadados (CSV/Parquet) mas não analisa padrões de acesso.","D":"CloudWatch Metrics tem métricas de bucket (BucketSizeBytes, NumberOfObjects) mas não padrão de acesso por objeto."},"keyConcept":"S3 observability — Storage Lens (org-wide) vs Analytics (per-bucket access pattern) vs Inventory (object list)","compareWith":["Storage Lens vs Storage Class Analysis vs Inventory"],"realWorldContext":"FinOps team usando Analytics para justificar lifecycle policies a stakeholders.","commonMistakes":"Confundir Storage Lens com Storage Class Analysis — propósitos diferentes.","tutorSeeds":["Quando Storage Lens é melhor que Analytics?","Inventory uses case com Athena?"]}'::jsonb, 'Cloud Technology & Services', 'Cloud Technology & Services', 'hard', 'best-practice', '["s3","analytics","storage-class-analysis"]'::jsonb, 'ai-draft', 'active', now(), now()),
    ('clf-c02-tech-v2-030', 'aws-clf', 'Uma equipe quer impedir que objetos S3 sejam modificados ou deletados por X dias, mesmo por administradores root, para atender compliance financeira (SEC 17a-4). Qual recurso fornece WORM (Write Once Read Many) verificável?', '[{"id":"A","text":"S3 Object Lock em modo Compliance com retention period"},{"id":"B","text":"S3 Versioning + MFA Delete"},{"id":"C","text":"S3 Bucket Policy com Deny em DeleteObject"},{"id":"D","text":"IAM Policy com Effect: Deny em s3:DeleteObject"}]'::jsonb, 'A', '{"summary":"WORM verificável (até root) = S3 Object Lock modo Compliance.","whyCorrect":"Object Lock em modo Compliance impede DELETE/OVERWRITE de versão por X dias — nem root da conta pode contornar. Atende SEC 17a-4(f), FINRA, CFTC. Modo Governance é menos rígido (root pode contornar com bypass permission).","whyWrong":{"B":"Versioning + MFA Delete protege contra deleção acidental mas root pode desabilitar MFA Delete — não é WORM verificável.","C":"Bucket Policy pode ser editada por quem tem permissão de s3:PutBucketPolicy (admins) — não é imutável.","D":"IAM Deny pode ser revertido por admins; não atende WORM."},"keyConcept":"S3 Object Lock — Compliance (imutável) vs Governance (bypass possível)","compareWith":["Object Lock Compliance vs Governance","Object Lock vs Versioning vs MFA Delete"],"realWorldContext":"Bancos, corretoras, healthcare records (HIPAA), audit logs imutáveis.","commonMistakes":"Habilitar Object Lock e definir retention errada — não há como remover em Compliance até expirar.","tutorSeeds":["Como funciona Legal Hold em Object Lock?","Object Lock + Cross-Region Replication?"]}'::jsonb, 'Cloud Technology & Services', 'Cloud Technology & Services', 'hard', 'scenario', '["s3","object-lock","compliance","worm"]'::jsonb, 'ai-draft', 'active', now(), now()),
    ('clf-c02-tech-v2-031', 'aws-clf', 'Uma equipe migra para S3 e quer copiar 50 TB de dados on-prem para AWS em poucos dias, com link de internet de 1 Gbps lento e instável. Qual serviço minimiza o tempo?', '[{"id":"A","text":"S3 Transfer Acceleration via internet"},{"id":"B","text":"AWS Snowball Edge Storage Optimized (físico)"},{"id":"C","text":"AWS DataSync via VPN"},{"id":"D","text":"Upload manual via aws s3 cp em paralelo"}]'::jsonb, 'B', '{"summary":"50 TB com link ruim = enviar dispositivo físico (Snowball).","whyCorrect":"Snowball Edge Storage Optimized carrega até 80 TB por device. Você copia localmente (LAN), AWS transporta fisicamente, ingere em S3. Para 50 TB com 1 Gbps real (~500 Mbps efetivo), upload pela internet levaria ~10 dias — Snowball entrega em 1 semana incluindo logística.","whyWrong":{"A":"Transfer Acceleration ainda usa o seu link de saída — 1 Gbps lento e instável continua sendo o gargalo.","C":"DataSync acelera vs scripts manuais mas continua dependendo do link 1 Gbps — mesmo problema.","D":"aws s3 cp paralelo é o pior — a CLI nem aproveita Transfer Acceleration sem flag, e o link instável quebra uploads."},"keyConcept":"AWS Snow Family — Snowcone / Snowball Edge / Snowmobile para migração offline","compareWith":["Snowball vs DataSync vs Direct Connect vs S3 TA"],"realWorldContext":"Migração de datacenters legados sem boa conectividade, edge data ingestion de navios/minerações.","commonMistakes":"Insistir em rede para grandes volumes — fisicamente enviar disco vence até ~100 TB.","tutorSeeds":["Quando DataSync vence Snowball?","Snowmobile vs Snowball para escalas PB+?"]}'::jsonb, 'Cloud Technology & Services', 'Cloud Technology & Services', 'easy', 'scenario', '["s3","snowball","migration"]'::jsonb, 'ai-draft', 'active', now(), now()),
    ('clf-c02-tech-v2-032', 'aws-clf', 'Uma aplicação faz uploads de objetos S3 de 8 GB cada. A equipe quer maior throughput e resiliência a falhas durante upload. Qual técnica é recomendada?', '[{"id":"A","text":"Multipart Upload (paralelizar partes e retomar partes falhas)"},{"id":"B","text":"Aumentar timeout do cliente HTTP"},{"id":"C","text":"Comprimir o objeto antes (gzip)"},{"id":"D","text":"Trocar para S3 One Zone-IA"}]'::jsonb, 'A', '{"summary":"Objetos > 100 MB devem usar Multipart Upload por throughput e retomada.","whyCorrect":"Multipart Upload divide o objeto em partes (5 MB-5 GB cada), permite paralelismo (mais throughput) e retomada de partes que falharam sem reenviar tudo. AWS recomenda multipart para objetos > 100 MB; mandatório para > 5 GB.","whyWrong":{"B":"Timeout maior só atrasa o erro — não acelera nem dá resiliência a falhas de rede.","C":"Compressão pode ajudar mas não é a técnica idiomática de upload — e pode não comprimir se o conteúdo já for binário/compactado.","D":"Storage class não tem efeito sobre upload performance."},"keyConcept":"S3 Multipart Upload — paralelismo + retomada + objetos > 5 GB","compareWith":["PUT single-part vs Multipart Upload","Multipart vs Transfer Acceleration"],"realWorldContext":"Vídeos brutos de produção, datasets ML, backups de databases.","commonMistakes":"Não abortar multipart uploads incompletos — partes ficam cobrando indefinidamente; configure lifecycle rule para abort incomplete multipart uploads.","tutorSeeds":["Tamanho ótimo de cada parte para vazão máxima?","Multipart Upload + Transfer Acceleration juntos?"]}'::jsonb, 'Cloud Technology & Services', 'Cloud Technology & Services', 'easy', 'best-practice', '["s3","multipart-upload","performance"]'::jsonb, 'ai-draft', 'active', now(), now()),
    ('clf-c02-tech-v2-033', 'aws-clf', 'Uma equipe precisa de volume EBS para um banco de dados que sustenta 30.000 IOPS com latência sub-ms consistente e durabilidade extra (99.999%). Qual tipo é o adequado?', '[{"id":"A","text":"gp3"},{"id":"B","text":"io2 Block Express"},{"id":"C","text":"st1 (throughput optimized HDD)"},{"id":"D","text":"sc1 (cold HDD)"}]'::jsonb, 'B', '{"summary":"Alto IOPS + sub-ms + 99.999% durabilidade = io2 Block Express.","whyCorrect":"io2 Block Express suporta até 256.000 IOPS, 4.000 MB/s throughput, latência sub-ms, durabilidade 99.999% (vs 99.8-99.9% das outras famílias). Único EBS com esse SLA de durabilidade. Ideal para bancos críticos.","whyWrong":{"A":"gp3 suporta até 16.000 IOPS — insuficiente para 30.000. Durabilidade 99.8-99.9%.","C":"st1 é HDD throughput-optimized — não IOPS. Não cabe.","D":"sc1 é cold HDD para acesso esporádico — totalmente inadequado para DB."},"keyConcept":"EBS volume types — gp3 vs io2 vs io2 Block Express vs st1 vs sc1","compareWith":["io2 vs io2 Block Express","gp3 vs io2 cost-benefit"],"realWorldContext":"Oracle/SQL Server críticos, SAP HANA, NoSQL high-throughput.","commonMistakes":"Usar io2 ou gp3 quando 30k IOPS exige Block Express; ou superprovisionar gp3 pagando sem entregar.","tutorSeeds":["Por que io2 Block Express precisa de Nitro instances?","gp3 vs io2 — quando a diferença de preço compensa?"]}'::jsonb, 'Cloud Technology & Services', 'Cloud Technology & Services', 'hard', 'scenario', '["ebs","io2-block-express","performance","database"]'::jsonb, 'ai-draft', 'active', now(), now()),
    ('clf-c02-tech-v2-034', 'aws-clf', 'Uma equipe rodava banco em volume gp2 de 500 GB (1.500 IOPS baseline). Migrou para gp3 mantendo 500 GB e config padrão. Qual mudança de performance/custo é VERDADEIRA?', '[{"id":"A","text":"gp3 entrega 3.000 IOPS e 125 MB/s baseline INDEPENDENTE do tamanho, e é ~20% mais barato por GB que gp2"},{"id":"B","text":"gp3 entrega menos IOPS que gp2 nesse tamanho"},{"id":"C","text":"gp3 e gp2 são equivalentes em IOPS/preço"},{"id":"D","text":"gp3 só é vantajoso para volumes > 1 TB"}]'::jsonb, 'A', '{"summary":"gp3 desacopla IOPS/throughput do tamanho — 3k IOPS e 125 MB/s baseline em qualquer GB.","whyCorrect":"gp2 amarra IOPS a tamanho (3 IOPS/GB). gp3 oferece 3.000 IOPS e 125 MB/s baseline para qualquer tamanho, e custa ~20% menos por GB. Pode-se provisionar até 16.000 IOPS / 1.000 MB/s adicionais pagando extra. Ganho duplo: mais IOPS por menos custo no caso de 500 GB.","whyWrong":{"B":"gp3 com 3k baseline supera os 1.500 IOPS do gp2 a 500 GB.","C":"Há diferença real — desacoplamento de IOPS e preço menor.","D":"gp3 é vantajoso em quase todos tamanhos — especialmente em volumes pequenos onde gp2 oferece pouco IOPS."},"keyConcept":"gp3 vs gp2 — desacoplamento de IOPS/throughput do tamanho","compareWith":["gp3 vs gp2","gp3 baseline vs provisioned extra"],"realWorldContext":"Migração massiva de gp2 → gp3 para reduzir custo sem perder performance.","commonMistakes":"Não migrar volumes gp2 antigos — está deixando dinheiro na mesa.","tutorSeeds":["Como migrar gp2 → gp3 sem downtime?","Quando gp3 NÃO compensa vs gp2?"]}'::jsonb, 'Cloud Technology & Services', 'Cloud Technology & Services', 'easy', 'recall', '["ebs","gp3","gp2","cost-optimization"]'::jsonb, 'ai-draft', 'active', now(), now()),
    ('clf-c02-tech-v2-035', 'aws-clf', 'Uma equipe precisa de filesystem NFS compartilhado por 200 EC2 Linux em múltiplas AZs com burst de I/O imprevisível. Qual EFS performance mode + throughput mode é o adequado?', '[{"id":"A","text":"General Purpose performance mode + Elastic throughput"},{"id":"B","text":"Max I/O performance mode + Bursting throughput"},{"id":"C","text":"General Purpose + Provisioned (com 50 MB/s reservados)"},{"id":"D","text":"Max I/O + Provisioned"}]'::jsonb, 'A', '{"summary":"Workload imprevisível com 200 clients = General Purpose + Elastic.","whyCorrect":"General Purpose performance mode oferece latência mais baixa e é recomendado para a maioria dos casos. Elastic throughput escala automaticamente até 10 GB/s read / 3 GB/s write conforme demanda, ideal para padrões imprevisíveis. Sem necessidade de provisionar capacity antes.","whyWrong":{"B":"Max I/O é apenas para workloads MUITO paralelos (milhares de clients) e tem latência mais alta. Bursting tem créditos finitos.","C":"Provisioned é determinístico mas paga mesmo sem uso — pior para imprevisível.","D":"Max I/O + Provisioned combina overhead e custo desnecessário."},"keyConcept":"EFS performance modes (General Purpose vs Max I/O) e throughput modes (Bursting, Provisioned, Elastic)","compareWith":["EFS Elastic vs Provisioned vs Bursting"],"realWorldContext":"Web servers compartilhando assets, build farms, ML training data shared.","commonMistakes":"Escolher Max I/O ''para garantir'' — paga mais latência sem necessidade real.","tutorSeeds":["Quando Max I/O é realmente necessário?","Como funcionam burst credits do EFS?"]}'::jsonb, 'Cloud Technology & Services', 'Cloud Technology & Services', 'medium', 'scenario', '["efs","performance-mode","throughput-mode"]'::jsonb, 'ai-draft', 'active', now(), now()),
    ('clf-c02-tech-v2-036', 'aws-clf', 'Uma empresa de mídia precisa de filesystem paralelo de altíssima vazão (centenas de GB/s) integrado com S3 para um workload HPC de processamento de vídeo. Qual variante de FSx é a indicada?', '[{"id":"A","text":"FSx for Lustre com link a bucket S3"},{"id":"B","text":"FSx for Windows File Server"},{"id":"C","text":"FSx for NetApp ONTAP"},{"id":"D","text":"FSx for OpenZFS"}]'::jsonb, 'A', '{"summary":"HPC paralelo + S3 = FSx for Lustre.","whyCorrect":"FSx for Lustre é filesystem POSIX paralelo (Lustre) com vazão de até 1+ TB/s, latência sub-ms, projetado para HPC. Integração nativa com S3 (lazy load + write-back) — perfeito para datasets em S3 que precisam ser processados em paralelo.","whyWrong":{"B":"Windows File Server é SMB para cargas Windows — não HPC paralelo.","C":"NetApp ONTAP oferece NFS/SMB enterprise com snapshots, mas não é otimizado para HPC paralelo.","D":"OpenZFS oferece NFS performante com snapshots, mas escala/integração-S3 não é o foco como em Lustre."},"keyConcept":"FSx variants — Lustre (HPC), Windows (SMB), ONTAP (enterprise multi-protocol), OpenZFS (NFS performante)","compareWith":["FSx Lustre vs ONTAP vs Windows vs OpenZFS"],"realWorldContext":"Renderização de filmes, simulações financeiras, ML training de larga escala.","commonMistakes":"Usar EFS para HPC paralelo extremo — EFS não chega às centenas de GB/s do Lustre.","tutorSeeds":["Como funciona o link S3 ↔ Lustre?","Quando ONTAP é melhor que OpenZFS?"]}'::jsonb, 'Cloud Technology & Services', 'Cloud Technology & Services', 'medium', 'scenario', '["fsx","lustre","hpc"]'::jsonb, 'ai-draft', 'active', now(), now()),
    ('clf-c02-tech-v2-037', 'aws-clf', 'Uma equipe SAP usa NetApp on-prem e quer migrar para AWS mantendo features enterprise (snapshots, clones, dedupe, replicação SnapMirror, multi-protocolo NFS/SMB/iSCSI). Qual variante FSx é o match?', '[{"id":"A","text":"FSx for NetApp ONTAP"},{"id":"B","text":"FSx for OpenZFS"},{"id":"C","text":"FSx for Lustre"},{"id":"D","text":"EFS Standard"}]'::jsonb, 'A', '{"summary":"Workload NetApp lift-and-shift = FSx for ONTAP (mesmo ONTAP, multi-protocolo, SnapMirror).","whyCorrect":"FSx for NetApp ONTAP é literalmente o ONTAP da NetApp executado como serviço gerenciado AWS. Suporta NFS, SMB e iSCSI no mesmo filesystem, snapshots/FlexClone, deduplicação, compression, SnapMirror para on-prem. Migração lift-and-shift sem refactor.","whyWrong":{"B":"OpenZFS é NFS-only com snapshots, mas sem SMB nativo nem SnapMirror.","C":"Lustre é HPC, não enterprise multi-protocolo.","D":"EFS é NFS-only, não tem features ONTAP."},"keyConcept":"FSx ONTAP — ONTAP gerenciado AWS com features completas","compareWith":["FSx ONTAP vs OpenZFS","FSx ONTAP vs EFS para casos enterprise"],"realWorldContext":"Migração de SAP/Oracle de NetApp on-prem mantendo workflow.","commonMistakes":"Trocar NetApp por EFS — perde quase todas features que justificam NetApp.","tutorSeeds":["SnapMirror para hybrid cloud — como funciona?","FSx ONTAP custo vs benefício vs EFS?"]}'::jsonb, 'Cloud Technology & Services', 'Cloud Technology & Services', 'hard', 'scenario', '["fsx","netapp-ontap","enterprise"]'::jsonb, 'ai-draft', 'active', now(), now()),
    ('clf-c02-tech-v2-038', 'aws-clf', 'Sobre snapshots EBS, qual afirmação é VERDADEIRA?', '[{"id":"A","text":"Snapshots são incrementais e armazenados em S3 (gerenciado), permitindo restore em qualquer AZ da mesma Region"},{"id":"B","text":"Snapshots são full sempre — cada snapshot copia o volume inteiro"},{"id":"C","text":"Snapshots só funcionam em volumes io2"},{"id":"D","text":"Snapshots são armazenados no próprio volume EBS"}]'::jsonb, 'A', '{"summary":"EBS snapshots são incrementais, no S3 (managed), e restauráveis em qualquer AZ da Region.","whyCorrect":"Snapshots EBS são incrementais — primeiro é full, subsequentes só copiam blocos modificados. Armazenados em buckets S3 gerenciados pela AWS (não visíveis no seu console). Você pode restaurar para qualquer AZ na mesma Region (e copiar cross-Region para DR).","whyWrong":{"B":"São incrementais, não full — isso permite snapshots frequentes baratos.","C":"Funcionam para todos os tipos EBS (gp2/gp3/io1/io2/st1/sc1).","D":"Não ficam no volume — ficam em storage S3 gerenciado."},"keyConcept":"EBS Snapshots — incremental, S3-backed, AZ-mobile","compareWith":["Snapshot vs AMI","Snapshot incremental vs Glacier archive"],"realWorldContext":"Backups noturnos automatizados via Data Lifecycle Manager, restore para outra AZ pós-falha.","commonMistakes":"Deletar snapshot inicial sem entender que blocos derivados foram preservados — a AWS preserva blocos necessários automaticamente.","tutorSeeds":["Por que deletar um snapshot incremental não corrompe os outros?","EBS Snapshot Archive — quando usar?"]}'::jsonb, 'Cloud Technology & Services', 'Cloud Technology & Services', 'medium', 'recall', '["ebs","snapshot","backup"]'::jsonb, 'ai-draft', 'active', now(), now()),
    ('clf-c02-tech-v2-039', 'aws-clf', 'Uma equipe usa S3 e configura Cross-Region Replication (CRR). Após criar a regra, objetos antigos não estão sendo replicados. Qual é a causa?', '[{"id":"A","text":"CRR só replica objetos criados/modificados APÓS a habilitação; existentes precisam de S3 Batch Replication"},{"id":"B","text":"CRR não suporta replicação de objetos antigos em nenhuma circunstância"},{"id":"C","text":"É necessário ativar versionamento no bucket DESTINO apenas"},{"id":"D","text":"CRR replica automaticamente todos os objetos imediatamente"}]'::jsonb, 'A', '{"summary":"CRR só pega objetos novos; existentes exigem S3 Batch Replication.","whyCorrect":"S3 Replication (CRR/SRR) replica apenas objetos criados ou modificados APÓS a habilitação da regra. Para replicar objetos pré-existentes, use S3 Batch Replication (jobs em massa que aplicam regras a objetos antigos).","whyWrong":{"B":"Existe solução — Batch Replication.","C":"Versionamento deve estar habilitado em AMBOS os buckets (origem e destino), não só destino.","D":"Replicação é assíncrona e só para objetos novos."},"keyConcept":"S3 Replication — escopo (novos) + S3 Batch Replication (existentes)","compareWith":["CRR vs SRR","Live replication vs Batch replication"],"realWorldContext":"Migração entre regions, DR cross-region, compliance de localização de dados.","commonMistakes":"Habilitar CRR e achar que bucket existente fica sincronizado — não fica até rodar Batch.","tutorSeeds":["Custo de S3 Batch Replication?","RTC (Replication Time Control) — quando usar?"]}'::jsonb, 'Cloud Technology & Services', 'Cloud Technology & Services', 'medium', 'troubleshoot', '["s3","crr","replication"]'::jsonb, 'ai-draft', 'active', now(), now()),
    ('clf-c02-tech-v2-040', 'aws-clf', 'Uma equipe quer expor um bucket S3 ao on-prem como filesystem NFS, fazendo cache local e write-back para S3. Qual variante de Storage Gateway é a correta?', '[{"id":"A","text":"File Gateway (Amazon S3 File Gateway)"},{"id":"B","text":"Volume Gateway (Cached mode)"},{"id":"C","text":"Tape Gateway"},{"id":"D","text":"FSx File Gateway"}]'::jsonb, 'A', '{"summary":"NFS/SMB on-prem + S3 backend = S3 File Gateway.","whyCorrect":"S3 File Gateway expõe NFS v3/v4.1 e SMB ao on-prem, armazena arquivos como objetos S3 (1 arquivo = 1 objeto), com cache local de blocos frequentes. Write-back assíncrono para S3.","whyWrong":{"B":"Volume Gateway expõe iSCSI block storage (não NFS) — usa snapshots EBS no backend.","C":"Tape Gateway emula library VTL para software de backup legado — não NFS.","D":"FSx File Gateway é para FSx Windows on-prem, não para S3."},"keyConcept":"Storage Gateway variants — S3 File, Volume (cached/stored), Tape, FSx File","compareWith":["S3 File Gateway vs Volume Gateway","Tape Gateway vs Snowball Tape"],"realWorldContext":"Apps legados on-prem que esperam NFS mas a empresa quer cloud storage atrás.","commonMistakes":"Achar que Volume Gateway é NFS — é iSCSI block.","tutorSeeds":["Diferença Volume Gateway cached vs stored mode?","S3 File Gateway escreve objetos retroativamente?"]}'::jsonb, 'Cloud Technology & Services', 'Cloud Technology & Services', 'medium', 'scenario', '["storage-gateway","s3-file-gateway","hybrid"]'::jsonb, 'ai-draft', 'active', now(), now()),
    ('clf-c02-tech-v2-041', 'aws-clf', 'Uma startup precisa de banco relacional gerenciado para uma API com tráfego imprevisível (de 5 conexões/min de noite a 500 conexões/seg em picos diários). Quer pagar proporcional ao uso e ter Postgres-compatible. Qual escolha minimiza custo e ops?', '[{"id":"A","text":"Aurora PostgreSQL Serverless v2"},{"id":"B","text":"RDS PostgreSQL Single-AZ db.t3.micro"},{"id":"C","text":"RDS PostgreSQL Multi-AZ db.r6g.xlarge fixo"},{"id":"D","text":"EC2 com PostgreSQL self-managed"}]'::jsonb, 'A', '{"summary":"Tráfego imprevisível + Postgres + escala automática = Aurora Serverless v2.","whyCorrect":"Aurora Serverless v2 escala granularmente em incrementos de 0.5 ACU (Aurora Capacity Units), respondendo a carga em segundos. Para padrões de 5 conn/min a 500/s, ajusta capacidade dinamicamente. Suporta Postgres-compatible. Você paga por ACU-hora consumida.","whyWrong":{"B":"RDS t3.micro tem capacidade fixa e baixa — vai falhar nos picos. Sem escala automática.","C":"RDS Multi-AZ r6g.xlarge custa fixo (~$400+/mês) mesmo no vale noturno — desperdício.","D":"Self-managed exige ops 24/7, patching, backup, failover manual."},"keyConcept":"Aurora Serverless v2 — auto-scaling fino em ACUs","compareWith":["Aurora Serverless v1 vs v2","Aurora Serverless v2 vs RDS provisionado"],"realWorldContext":"SaaS multitenant com workload variável, ambientes dev/test que escalam para zero.","commonMistakes":"Confundir v1 (pausável, scale lento) com v2 (sub-segundo scale, sem pause completo).","tutorSeeds":["Como ACU mapeia para CPU/RAM?","Aurora Serverless v2 scale-to-zero existe?"]}'::jsonb, 'Cloud Technology & Services', 'Cloud Technology & Services', 'medium', 'scenario', '["aurora","serverless-v2","postgres","rds"]'::jsonb, 'ai-draft', 'active', now(), now()),
    ('clf-c02-tech-v2-042', 'aws-clf', 'Uma equipe migra um sistema com 80% de leituras e 20% de escritas, baseado em PostgreSQL. Quer escalar leituras horizontalmente sem mudar a aplicação. Qual recurso é o canônico?', '[{"id":"A","text":"RDS Read Replicas (até 15 em RDS Postgres, até 15 em Aurora) com endpoint de leitura"},{"id":"B","text":"Multi-AZ deployment com failover automático"},{"id":"C","text":"Sharding manual via app"},{"id":"D","text":"DynamoDB Global Tables"}]'::jsonb, 'A', '{"summary":"Escala horizontal de leituras = Read Replicas com reader endpoint.","whyCorrect":"Read Replicas replicam assincronamente do primary e servem queries de leitura. Aurora oferece reader endpoint que load-balanceia entre réplicas automaticamente. App usa endpoints separados (writer vs reader) — não precisa lógica de sharding.","whyWrong":{"B":"Multi-AZ standby NÃO atende leituras — é apenas para failover. O standby é passivo.","C":"Sharding é complexo e demanda mudança grande de código.","D":"DynamoDB é NoSQL — mudaria o modelo da aplicação Postgres."},"keyConcept":"Read Replicas vs Multi-AZ — leitura vs HA","compareWith":["Read Replica vs Multi-AZ","Aurora reader endpoint vs RDS read replica endpoints"],"realWorldContext":"Apps com painel de relatórios pesados, BI queries que não devem competir com OLTP.","commonMistakes":"Achar que Multi-AZ standby aceita queries de leitura — RDS Multi-AZ tradicional não; Multi-AZ Cluster Deployment (3 instâncias) sim.","tutorSeeds":["RDS Multi-AZ Cluster Deployment — diferenças?","Lag de replicação — como monitorar?"]}'::jsonb, 'Cloud Technology & Services', 'Cloud Technology & Services', 'easy', 'best-practice', '["rds","read-replica","scaling"]'::jsonb, 'ai-draft', 'active', now(), now()),
    ('clf-c02-tech-v2-043', 'aws-clf', 'Sobre Aurora vs RDS (MySQL/PostgreSQL), qual afirmação é VERDADEIRA?', '[{"id":"A","text":"Aurora desacopla compute de storage; storage é shared (cluster volume) de 6 cópias em 3 AZs, com auto-grow até 128 TB"},{"id":"B","text":"Aurora e RDS são tecnologicamente idênticos; só nome diferente"},{"id":"C","text":"Aurora NÃO suporta read replicas"},{"id":"D","text":"Aurora roda em qualquer engine relacional (Oracle, SQL Server, Db2, etc.)"}]'::jsonb, 'A', '{"summary":"Aurora = storage distribuído (6 cópias / 3 AZs) compartilhado entre instâncias, auto-grow até 128 TB.","whyCorrect":"Aurora reescreveu a camada de storage do MySQL/Postgres como um cluster volume distribuído — 6 cópias em 3 AZs, write quorum 4/6, read quorum 3/6. Storage cresce automaticamente em incrementos de 10 GB até 128 TB. Replicas leem do MESMO storage (sem replicação física como no RDS), reduzindo lag para milissegundos.","whyWrong":{"B":"Aurora é arquitetura nova — não é só rebranding.","C":"Aurora SUPORTA até 15 read replicas com lag típico ~10ms.","D":"Aurora suporta apenas MySQL-compatible e PostgreSQL-compatible. Oracle/SQL Server estão em RDS."},"keyConcept":"Aurora — cluster volume distribuído + reader replicas sem replicação física","compareWith":["Aurora vs RDS MySQL/Postgres","Aurora storage vs EBS-backed RDS"],"realWorldContext":"Apps com requisitos de baixo lag entre primary e read replicas, escala storage automática.","commonMistakes":"Achar que Aurora roda Oracle — só MySQL e Postgres compatible.","tutorSeeds":["Por que Aurora tem read replica lag tão baixo?","Custo Aurora vs RDS — quando compensa?"]}'::jsonb, 'Cloud Technology & Services', 'Cloud Technology & Services', 'medium', 'recall', '["aurora","storage","architecture"]'::jsonb, 'ai-draft', 'active', now(), now()),
    ('clf-c02-tech-v2-044', 'aws-clf', 'Uma equipe DynamoDB tem padrão de carga previsível (1.000 read/s e 500 write/s constantes 24/7). Quer minimizar custo. Qual capacity mode escolher?', '[{"id":"A","text":"Provisioned Capacity (com Auto Scaling habilitado opcionalmente)"},{"id":"B","text":"On-Demand"},{"id":"C","text":"Reserved Capacity (RCU/WCU 1 ano)"},{"id":"D","text":"A + C — Provisioned com Reserved Capacity comprado"}]'::jsonb, 'D', '{"summary":"Carga previsível 24/7 = Provisioned + Reserved Capacity para máximo desconto.","whyCorrect":"Provisioned Capacity é mais barato que On-Demand para cargas previsíveis. Reserved Capacity adiciona até 76% de desconto sobre Provisioned com commit 1 ou 3 anos. Combinação dá menor TCO.","whyWrong":{"A":"Sozinho é bom, mas combinar com RC é estritamente melhor para 24/7 previsível.","B":"On-Demand é ~5-7x mais caro que Provisioned em utilização alta constante.","C":"Reserved Capacity é uma camada de desconto sobre Provisioned — não substitui."},"keyConcept":"DynamoDB capacity modes — Provisioned, On-Demand, Reserved Capacity","compareWith":["Provisioned vs On-Demand DynamoDB","Reserved Capacity ROI calc"],"realWorldContext":"Catálogos de e-commerce com tráfego estável, IoT com taxa constante de ingestão.","commonMistakes":"Usar On-Demand ''por simplicidade'' em carga estável — desperdício enorme.","tutorSeeds":["Quando On-Demand vence Provisioned + RC?","DynamoDB Auto Scaling — como funciona?"]}'::jsonb, 'Cloud Technology & Services', 'Cloud Technology & Services', 'hard', 'best-practice', '["dynamodb","capacity","reserved"]'::jsonb, 'ai-draft', 'active', now(), now()),
    ('clf-c02-tech-v2-045', 'aws-clf', 'Sobre DynamoDB Streams + Lambda triggers, qual afirmação é VERDADEIRA?', '[{"id":"A","text":"Streams capturam mudanças (INSERT/MODIFY/REMOVE) por 24h; Lambda pode consumir como event source para reagir a alterações"},{"id":"B","text":"Streams armazenam mudanças por 30 dias por padrão"},{"id":"C","text":"Lambda não pode ser invocado por DynamoDB Streams; só por Kinesis"},{"id":"D","text":"Streams capturam apenas DELETEs"}]'::jsonb, 'A', '{"summary":"DynamoDB Streams = log de mudanças (24h) consumível por Lambda.","whyCorrect":"DynamoDB Streams capturam INSERT/MODIFY/REMOVE em ordem por partition key, retidas por 24h. Lambda pode ser configurado como event source — recebe batches de records e processa (ex: replicar para Elasticsearch, invalidar cache, audit log).","whyWrong":{"B":"Retenção é 24h fixo, não 30 dias.","C":"Lambda integra nativamente com DynamoDB Streams há anos.","D":"Captura todos os tipos: INSERT, MODIFY, REMOVE."},"keyConcept":"DynamoDB Streams — CDC com retenção 24h + Lambda trigger","compareWith":["DynamoDB Streams vs Kinesis Data Streams for DynamoDB","Lambda trigger por DDB Streams vs por EventBridge Pipes"],"realWorldContext":"Replicação de dados para search engine, audit trail, cache invalidation.","commonMistakes":"Esperar retenção longa — para >24h, integre com Kinesis Data Streams for DynamoDB (365 dias).","tutorSeeds":["DynamoDB Streams vs Kinesis Data Streams for DynamoDB?","Como garantir ordem global?"]}'::jsonb, 'Cloud Technology & Services', 'Cloud Technology & Services', 'medium', 'recall', '["dynamodb","streams","lambda"]'::jsonb, 'ai-draft', 'active', now(), now()),
    ('clf-c02-tech-v2-046', 'aws-clf', 'Uma empresa precisa de data warehouse para 200 TB de dados estruturados, com queries complexas (joins, agregações) sobre SQL ANSI, e materializar dashboards de BI sub-segundo. Qual serviço é o canônico?', '[{"id":"A","text":"Amazon Redshift (com RA3 nodes ou Serverless)"},{"id":"B","text":"Amazon Athena sobre dados em Parquet em S3"},{"id":"C","text":"Amazon RDS PostgreSQL db.r6g.16xlarge"},{"id":"D","text":"Amazon DynamoDB com GSIs"}]'::jsonb, 'A', '{"summary":"DW columnar com queries complexas e dashboards sub-segundo = Redshift.","whyCorrect":"Redshift é OLAP columnar MPP otimizado para queries analíticas complexas em escala TB-PB. RA3 desacopla compute de storage; Serverless escala sob demanda. Suporta materialized views, result caching — perfeito para dashboards de BI.","whyWrong":{"B":"Athena é serverless query-on-S3, ótimo para ad-hoc, mas para dashboards repetitivos e sub-segundo, Redshift é mais rápido e previsível.","C":"RDS é OLTP transacional — sofre em queries OLAP de TB.","D":"DynamoDB é NoSQL key-value, sem joins/agregações complexas."},"keyConcept":"Redshift (DW columnar MPP) vs Athena (serverless S3 SQL) vs RDS (OLTP)","compareWith":["Redshift vs Athena","Redshift RA3 vs DC2 vs Serverless"],"realWorldContext":"BI corporativo, ETL para dashboards executivos, agregações financeiras.","commonMistakes":"Tentar usar RDS para warehouse — quebra em queries de TB.","tutorSeeds":["Quando Athena vence Redshift?","Redshift Serverless — quando vale a pena?"]}'::jsonb, 'Cloud Technology & Services', 'Cloud Technology & Services', 'medium', 'scenario', '["redshift","data-warehouse","analytics"]'::jsonb, 'ai-draft', 'active', now(), now()),
    ('clf-c02-tech-v2-047', 'aws-clf', 'Uma equipe precisa de cache in-memory com suporte a estruturas avançadas (Sets, Sorted Sets, Streams), persistência opcional e replicação multi-node com failover automático. Qual ElastiCache engine?', '[{"id":"A","text":"ElastiCache for Redis (com Multi-AZ replication group)"},{"id":"B","text":"ElastiCache for Memcached"},{"id":"C","text":"DynamoDB Accelerator (DAX)"},{"id":"D","text":"RDS com cache plugin"}]'::jsonb, 'A', '{"summary":"Estruturas ricas + persistência + failover = ElastiCache for Redis.","whyCorrect":"Redis suporta Strings, Lists, Sets, Sorted Sets, Hashes, Streams, Geospatial, HyperLogLog. Multi-AZ com replicação e failover automático. Persistência opcional (RDB/AOF) ou snapshots. Pub/Sub e Lua scripting nativos.","whyWrong":{"B":"Memcached é apenas key-value strings, sem replicação nativa, sem persistência. Mais simples e multi-thread, mas sem features avançadas.","C":"DAX é cache específico para DynamoDB (API DDB), não geral.","D":"RDS não é cache in-memory — é DB relacional."},"keyConcept":"ElastiCache Redis vs Memcached — features vs simplicidade","compareWith":["Redis (features) vs Memcached (simples, multi-thread)"],"realWorldContext":"Session store com TTL, leaderboards (Sorted Sets), rate limiting (Streams), pub/sub real-time.","commonMistakes":"Escolher Memcached por ''ser mais leve'' e depois precisar de features Redis — migrar dá dor.","tutorSeeds":["Por que Memcached é multi-thread e Redis single-thread (até v6)?","Redis cluster mode vs replication group?"]}'::jsonb, 'Cloud Technology & Services', 'Cloud Technology & Services', 'easy', 'scenario', '["elasticache","redis","memcached"]'::jsonb, 'ai-draft', 'active', now(), now()),
    ('clf-c02-tech-v2-048', 'aws-clf', 'Sobre o modelo de leitura do DynamoDB, qual afirmação é VERDADEIRA?', '[{"id":"A","text":"Reads são eventually consistent por default (1 RCU = 2 reads de até 4 KB); strongly consistent reads custam o dobro (1 RCU = 1 read de 4 KB)"},{"id":"B","text":"Reads são sempre strongly consistent"},{"id":"C","text":"Não há diferença de custo entre eventually e strongly consistent"},{"id":"D","text":"Strongly consistent reads são gratuitos"}]'::jsonb, 'A', '{"summary":"DDB: eventually 2 reads/RCU (default), strongly 1 read/RCU (2x mais caro), transactional 2x ainda.","whyCorrect":"DynamoDB default é eventually consistent: 1 RCU = 2 reads de até 4 KB. Strongly consistent: 1 RCU = 1 read de até 4 KB (2x). Transactional reads: 1 RCU = 0.5 read de até 4 KB (4x). Escolha consciente entre custo/garantia.","whyWrong":{"B":"Default é eventually; strongly é opt-in por chamada.","C":"Há diferença explícita: 2x para strongly.","D":"Não são gratuitos — custam o dobro de RCU."},"keyConcept":"DDB RCU — eventually (2/RCU) vs strongly (1/RCU) vs transactional (0.5/RCU)","compareWith":["Eventually vs Strongly consistent reads","Read vs Write capacity units"],"realWorldContext":"Apps OLTP escolhem strongly para read-after-write críticos (ex: saldo bancário) e eventually para leituras tolerantes a stale (timeline social).","commonMistakes":"Usar strongly em tudo — dobra o custo de RCU desnecessariamente.","tutorSeeds":["Quando strongly consistent é mandatório?","Como mensurar RCU consumido por API?"]}'::jsonb, 'Cloud Technology & Services', 'Cloud Technology & Services', 'hard', 'recall', '["dynamodb","consistency","rcu"]'::jsonb, 'ai-draft', 'active', now(), now()),
    ('clf-c02-tech-v2-049', 'aws-clf', 'Uma equipe quer migrar de Cassandra mantendo APIs e drivers CQL. Qual serviço AWS é compatível?', '[{"id":"A","text":"Amazon Keyspaces (for Apache Cassandra)"},{"id":"B","text":"DynamoDB"},{"id":"C","text":"Neptune"},{"id":"D","text":"DocumentDB"}]'::jsonb, 'A', '{"summary":"API Cassandra (CQL) gerenciada na AWS = Keyspaces.","whyCorrect":"Amazon Keyspaces é compatível com Apache Cassandra — aceita CQL queries e drivers Cassandra existentes. Serverless, com modos provisioned/on-demand similares a DynamoDB. Migração sem refactor da app.","whyWrong":{"B":"DynamoDB tem API/SDK próprios — não é CQL.","C":"Neptune é graph database — Gremlin/SPARQL, não CQL.","D":"DocumentDB é MongoDB-compatible — não Cassandra."},"keyConcept":"Managed databases by API compatibility — Keyspaces (Cassandra), DocumentDB (MongoDB), Neptune (Graph)","compareWith":["Keyspaces vs DynamoDB","Keyspaces vs Cassandra self-managed em EC2"],"realWorldContext":"Migração de Cassandra on-prem mantendo aplicações.","commonMistakes":"Confundir Keyspaces (Cassandra) com DocumentDB (Mongo).","tutorSeeds":["Quais features Cassandra Keyspaces NÃO suporta?","Quando preferir Keyspaces a DynamoDB?"]}'::jsonb, 'Cloud Technology & Services', 'Cloud Technology & Services', 'easy', 'scenario', '["keyspaces","cassandra","nosql"]'::jsonb, 'ai-draft', 'active', now(), now()),
    ('clf-c02-tech-v2-050', 'aws-clf', 'Uma equipe precisa de banco de séries temporais para métricas IoT (milhões de medições/seg, queries por intervalos de tempo). Qual serviço é o canônico?', '[{"id":"A","text":"Amazon Timestream"},{"id":"B","text":"DynamoDB com sort key timestamp"},{"id":"C","text":"RDS PostgreSQL com TimescaleDB extension"},{"id":"D","text":"Athena sobre Parquet"}]'::jsonb, 'A', '{"summary":"Time-series escala IoT = Amazon Timestream.","whyCorrect":"Timestream é DB serverless purpose-built para time-series — separa storage em memory tier (queries quentes) e magnetic tier (históricos). Linguagem SQL com funções time-series nativas. Escala automaticamente para trilhões de eventos.","whyWrong":{"B":"DynamoDB com sort key timestamp funciona em escala menor, mas sofre em queries de range largo e não tem funções time-series nativas.","C":"RDS+TimescaleDB é possível mas exige gerenciar instância e não escala como Timestream.","D":"Athena é batch query — não real-time ingestão de milhões/seg."},"keyConcept":"Time-series purpose-built — Timestream (vs DynamoDB workaround)","compareWith":["Timestream vs DynamoDB para séries temporais","Timestream tiers (memory vs magnetic)"],"realWorldContext":"IoT sensores industriais, métricas de aplicação, telemetria de veículos.","commonMistakes":"Forçar DDB para time-series gigante — explode em RCU e custo.","tutorSeeds":["Como Timestream cobra (writes vs queries)?","Quando InfluxDB self-managed vence Timestream?"]}'::jsonb, 'Cloud Technology & Services', 'Cloud Technology & Services', 'medium', 'scenario', '["timestream","time-series","iot"]'::jsonb, 'ai-draft', 'active', now(), now()),
    ('clf-c02-tech-v2-051', 'aws-clf', 'Uma equipe RDS faz backup automatizado diário (retention 7 dias) e ocasionalmente cria snapshots manuais. Sobre lifecycle desses recursos, qual afirmação é VERDADEIRA?', '[{"id":"A","text":"Backups automatizados são deletados se você deletar a instância RDS sem ''final snapshot''; snapshots manuais persistem até serem explicitamente deletados"},{"id":"B","text":"Ambos persistem indefinidamente após deletar a instância"},{"id":"C","text":"Ambos são deletados automaticamente quando a instância é deletada"},{"id":"D","text":"Snapshots manuais são deletados após 30 dias automaticamente"}]'::jsonb, 'A', '{"summary":"Automated backups morrem com a instância (a menos que faça final snapshot); manuais persistem.","whyCorrect":"Ao deletar uma instância RDS, automated backups são deletados (a menos que você escolha ''create final snapshot'', que converte em manual). Snapshots manuais persistem até serem explicitamente deletados — útil para arquivamento longo.","whyWrong":{"B":"Automated NÃO persistem por padrão após delete da instância.","C":"Manuais persistem.","D":"Não há expiration automática para snapshots manuais."},"keyConcept":"RDS automated backups vs manual snapshots — lifecycle","compareWith":["Automated backup vs Manual snapshot vs Final snapshot"],"realWorldContext":"Compliance que exige retenção 7 anos — deve usar manual snapshots ou export para S3.","commonMistakes":"Deletar instância sem final snapshot esperando que backups automatizados fiquem — não ficam.","tutorSeeds":["Como fazer cross-region snapshot manual?","Export RDS snapshot para S3 — quando vale?"]}'::jsonb, 'Cloud Technology & Services', 'Cloud Technology & Services', 'medium', 'best-practice', '["rds","backup","snapshot"]'::jsonb, 'ai-draft', 'active', now(), now()),
    ('clf-c02-tech-v2-052', 'aws-clf', 'Uma equipe RDS Postgres sofre lock contention em transações longas. Qual recurso AWS ajuda a IDENTIFICAR queries problemáticas com waits e top consumers?', '[{"id":"A","text":"Amazon RDS Performance Insights"},{"id":"B","text":"AWS Config rules para RDS"},{"id":"C","text":"CloudWatch Alarms padrão para CPU"},{"id":"D","text":"AWS Trusted Advisor"}]'::jsonb, 'A', '{"summary":"Performance Insights mostra DB load por wait event, top SQL, top users.","whyCorrect":"Performance Insights agrega DB load (Average Active Sessions) por dimensão (SQL, wait event, host, user). Para troubleshoot lock contention, é a ferramenta canônica — mostra exatamente quais queries esperam locks e por quanto tempo.","whyWrong":{"B":"Config audita conformidade (ex: backup habilitado?) — não diagnóstico de query.","C":"CPU alarm não revela locks em transações.","D":"Trusted Advisor dá recomendações genéricas, não diagnóstico de DB."},"keyConcept":"RDS Performance Insights — DB-level APM","compareWith":["Performance Insights vs Enhanced Monitoring","PI vs CloudWatch DB metrics"],"realWorldContext":"DBA hunting deadlocks, queries lentas, top consumers.","commonMistakes":"Confundir Enhanced Monitoring (métricas do SO da instância) com Performance Insights (DB-level waits/SQL).","tutorSeeds":["Diferença Performance Insights vs Enhanced Monitoring?","Custo de PI extended retention?"]}'::jsonb, 'Cloud Technology & Services', 'Cloud Technology & Services', 'medium', 'troubleshoot', '["rds","performance-insights","observability"]'::jsonb, 'ai-draft', 'active', now(), now()),
    ('clf-c02-tech-v2-053', 'aws-clf', 'Uma empresa quer conectar 3 VPCs (cada uma em uma Region: us-east-1, sa-east-1, eu-west-1) com roteamento any-to-any. Qual é a solução mais escalável e simples?', '[{"id":"A","text":"Transit Gateway com peering inter-Region"},{"id":"B","text":"Full mesh de VPC Peering (3 conexões)"},{"id":"C","text":"Direct Connect entre regions"},{"id":"D","text":"Site-to-Site VPN em malha"}]'::jsonb, 'A', '{"summary":"TGW + inter-Region peering = hub-and-spoke escalável para multi-Region.","whyCorrect":"Transit Gateway atua como hub regional. Para conectar VPCs em Regions distintas, usa-se TGW peering inter-Region (encryption-in-transit nativa). Escala muito além de 3 VPCs (até milhares). Gerencia rotas centralizadamente.","whyWrong":{"B":"VPC Peering full mesh para 3 funciona, mas N(N-1)/2 conexões viram inviável após ~10 VPCs. Cada peering é gerenciado individualmente.","C":"Direct Connect é para on-prem ↔ AWS, não VPC-to-VPC.","D":"VPN em malha entre VPCs AWS é over-engineering — TGW resolve internamente."},"keyConcept":"VPC Peering vs Transit Gateway — escala e gerenciamento","compareWith":["VPC Peering vs TGW","TGW inter-Region peering vs Cloud WAN"],"realWorldContext":"Empresas com presença multi-Region precisando shared services entre Regions.","commonMistakes":"Crescer em VPC Peering até a malha virar inviável — migrar tarde para TGW custa.","tutorSeeds":["Como TGW route tables funcionam?","AWS Cloud WAN vs TGW?"]}'::jsonb, 'Cloud Technology & Services', 'Cloud Technology & Services', 'medium', 'scenario', '["vpc","transit-gateway","multi-region"]'::jsonb, 'ai-draft', 'active', now(), now()),
    ('clf-c02-tech-v2-054', 'aws-clf', 'Uma equipe configura Direct Connect e precisa de virtual interface (VIF) que carregue tráfego para múltiplas VPCs via Transit Gateway. Qual tipo de VIF usar?', '[{"id":"A","text":"Transit VIF (associado ao Direct Connect Gateway, conectando ao TGW)"},{"id":"B","text":"Private VIF (ligado a um único VGW de uma VPC)"},{"id":"C","text":"Public VIF (acesso a serviços AWS públicos)"},{"id":"D","text":"Hosted VIF (sublease de outro AWS account)"}]'::jsonb, 'A', '{"summary":"DX → múltiplas VPCs via TGW = Transit VIF + Direct Connect Gateway.","whyCorrect":"Transit VIF se conecta a Direct Connect Gateway, que por sua vez se associa a Transit Gateway. Um único DX consegue alcançar múltiplas VPCs (mesma ou diferentes Regions) através do TGW. Modelo escalável para múltiplas VPCs.","whyWrong":{"B":"Private VIF se liga a um único VGW (Virtual Gateway de uma VPC) — para múltiplas VPCs via TGW não serve.","C":"Public VIF acessa serviços AWS públicos (S3, DynamoDB) sobre DX — não VPC privada.","D":"Hosted VIF é categoria de billing/ownership, não um tipo funcional."},"keyConcept":"Direct Connect VIFs — Private (1 VPC), Transit (TGW multi-VPC), Public (serviços públicos)","compareWith":["Private VIF vs Transit VIF","DX Gateway vs VGW"],"realWorldContext":"Empresa com DX 10 Gbps querendo alcançar 20 VPCs sem 20 VIFs.","commonMistakes":"Tentar conectar TGW via Private VIF — não suportado; precisa de Transit VIF.","tutorSeeds":["DX Gateway — para que serve exatamente?","MACsec em DX — quando usar?"]}'::jsonb, 'Cloud Technology & Services', 'Cloud Technology & Services', 'hard', 'scenario', '["direct-connect","transit-vif","networking"]'::jsonb, 'ai-draft', 'active', now(), now()),
    ('clf-c02-tech-v2-055', 'aws-clf', 'Uma equipe quer rotear usuários para o endpoint mais saudável e mais próximo geograficamente, com failover automático para um endpoint backup. Qual combinação Route 53 atende?', '[{"id":"A","text":"Latency-based routing primário + Failover routing secundário usando health checks"},{"id":"B","text":"Apenas Simple routing"},{"id":"C","text":"Multivalue answer routing"},{"id":"D","text":"Weighted routing 50/50"}]'::jsonb, 'A', '{"summary":"Geo-proximidade + failover = Latency-based + Failover routing com health checks.","whyCorrect":"Route 53 pode aninhar policies: registros principais com Latency-based (resolve para Region de menor RTT) e configurar Failover routing com Primary/Secondary + health checks. Quando primary fica unhealthy, Route 53 responde com secondary automaticamente.","whyWrong":{"B":"Simple routing não suporta failover nem geo-proximidade.","C":"Multivalue retorna até 8 IPs aleatórios com health check, mas sem latência geográfica nem primary/secondary.","D":"Weighted 50/50 distribui aleatoriamente — não otimiza latência."},"keyConcept":"Route 53 routing policies — Simple, Weighted, Latency, Geolocation, Geoproximity, Failover, Multivalue, IP-based","compareWith":["Latency-based vs Geolocation routing","Failover vs Multivalue"],"realWorldContext":"DR cross-Region com active-passive, sites globais com região primária.","commonMistakes":"Confundir Geolocation (por país do user) com Latency-based (por RTT real).","tutorSeeds":["Diferença Geolocation vs Geoproximity routing?","Health check tipos no Route 53?"]}'::jsonb, 'Cloud Technology & Services', 'Cloud Technology & Services', 'hard', 'scenario', '["route53","routing-policies","failover"]'::jsonb, 'ai-draft', 'active', now(), now()),
    ('clf-c02-tech-v2-056', 'aws-clf', 'Sobre Route 53 Geolocation vs Geoproximity routing, qual afirmação é VERDADEIRA?', '[{"id":"A","text":"Geolocation roteia com base na localização DO USUÁRIO (country/continent); Geoproximity roteia com base na localização DOS RECURSOS, com bias ajustável"},{"id":"B","text":"Geolocation e Geoproximity são sinônimos"},{"id":"C","text":"Geoproximity só funciona com servidores físicos on-prem"},{"id":"D","text":"Geolocation exige uso de Global Accelerator"}]'::jsonb, 'A', '{"summary":"Geolocation = onde o user está; Geoproximity = onde o recurso está (+bias).","whyCorrect":"Geolocation usa o IP do user para decidir o registro (ex: ''usuários da França → endpoint EU''). Geoproximity é diferente: você define a localização do RECURSO (Region AWS ou lat/long de DC on-prem) e o R53 roteia o user mais próximo, com bias ±99 que aumenta/reduz a ''área de influência'' de um endpoint.","whyWrong":{"B":"São distintas em parâmetro de decisão.","C":"Geoproximity funciona com Regions AWS e on-prem.","D":"Não há dependência de Global Accelerator."},"keyConcept":"Geolocation (user-side) vs Geoproximity (resource-side + bias)","compareWith":["Geolocation vs Geoproximity vs Latency-based"],"realWorldContext":"Compliance que exige rotear usuários de país X só para Region X (Geolocation); load balance entre DCs próximos com fine-tuning (Geoproximity).","commonMistakes":"Esperar Geolocation responder por proximidade geográfica — não, ela responde por país/continente configurado.","tutorSeeds":["Geoproximity exige Route 53 Traffic Flow?","Como o bias afeta o draw da região?"]}'::jsonb, 'Cloud Technology & Services', 'Cloud Technology & Services', 'hard', 'recall', '["route53","geolocation","geoproximity"]'::jsonb, 'ai-draft', 'active', now(), now()),
    ('clf-c02-tech-v2-057', 'aws-clf', 'Uma equipe quer que EC2 em subnet privada acesse APIs públicas da AWS (S3, DynamoDB) SEM NAT Gateway, mantendo tráfego dentro do backbone AWS. Qual recurso usar?', '[{"id":"A","text":"VPC Gateway Endpoint para S3 e DynamoDB"},{"id":"B","text":"VPC Interface Endpoint (PrivateLink)"},{"id":"C","text":"Internet Gateway com route table privada"},{"id":"D","text":"NAT Gateway com VPC Peering"}]'::jsonb, 'A', '{"summary":"S3 e DynamoDB têm Gateway Endpoints (gratuitos) — sem NAT, sem cobrança de saída.","whyCorrect":"VPC Gateway Endpoint funciona apenas para S3 e DynamoDB. É gratuito, evita NAT Gateway (economiza ~$33/mês + tráfego), e mantém tráfego no backbone AWS. Adiciona uma rota na route table apontando para o endpoint.","whyWrong":{"B":"Interface Endpoint (PrivateLink) funciona para muitos serviços, mas para S3 e DDB o Gateway Endpoint é mais simples e gratuito. Interface Endpoint pra S3 existe mas tem custo.","C":"IGW em route table privada não faz sentido — subnet privada é privada por definição.","D":"NAT é exatamente o que queremos evitar. Peering não tem relação."},"keyConcept":"VPC endpoints — Gateway (S3, DDB grátis) vs Interface (PrivateLink, $$)","compareWith":["Gateway Endpoint vs Interface Endpoint","VPC Endpoint vs NAT Gateway custo"],"realWorldContext":"Workloads ETL em EC2 privadas lendo PB de S3 sem pagar NAT egress.","commonMistakes":"Pagar NAT por tráfego S3 desnecessariamente — Gateway Endpoint é grátis.","tutorSeeds":["Quando S3 Interface Endpoint vence Gateway Endpoint?","Como configurar endpoint policy?"]}'::jsonb, 'Cloud Technology & Services', 'Cloud Technology & Services', 'easy', 'best-practice', '["vpc","gateway-endpoint","s3"]'::jsonb, 'ai-draft', 'active', now(), now()),
    ('clf-c02-tech-v2-058', 'aws-clf', 'Uma empresa quer expor um serviço interno (rodando atrás de NLB) para CONSUMIDORES em OUTRA conta AWS, sem peering nem expor à internet. Qual recurso é o canônico?', '[{"id":"A","text":"AWS PrivateLink — criar VPC Endpoint Service no provider, Interface Endpoint no consumer"},{"id":"B","text":"VPC Peering entre as contas"},{"id":"C","text":"Direct Connect Gateway"},{"id":"D","text":"Internet Gateway com IP allowlist"}]'::jsonb, 'A', '{"summary":"Service-to-service cross-account sem peering = PrivateLink (Endpoint Service + Interface Endpoint).","whyCorrect":"PrivateLink permite ao provider criar um VPC Endpoint Service em frente a um NLB, e consumers criam Interface Endpoints na própria VPC que tunelam para o serviço. Sem peering (escalável para milhares de consumers), sem internet, sem overlap de CIDR. Modelo SaaS dentro da AWS.","whyWrong":{"B":"VPC Peering exige sem overlap de CIDR e cresce N×M para múltiplos consumers.","C":"Direct Connect Gateway é para on-prem ↔ AWS, não AWS-to-AWS.","D":"Expor à internet com IP allowlist é o oposto do desejado."},"keyConcept":"AWS PrivateLink — SaaS-style service sharing sem peering","compareWith":["PrivateLink vs VPC Peering","Endpoint Service (provider) vs Interface Endpoint (consumer)"],"realWorldContext":"Empresas SaaS oferecendo serviços a clientes na AWS sem expor à internet (Datadog, Snowflake, etc.).","commonMistakes":"Usar VPC Peering quando há muitos consumers — vira inviável; PrivateLink escala melhor.","tutorSeeds":["PrivateLink vs Resource Access Manager?","Custos de Interface Endpoint?"]}'::jsonb, 'Cloud Technology & Services', 'Cloud Technology & Services', 'medium', 'scenario', '["privatelink","vpc","cross-account"]'::jsonb, 'ai-draft', 'active', now(), now()),
    ('clf-c02-tech-v2-059', 'aws-clf', 'Sobre VPC Flow Logs, qual afirmação é VERDADEIRA?', '[{"id":"A","text":"Flow Logs capturam metadados de tráfego IP (não payload) e podem ser entregues a CloudWatch Logs, S3 ou Kinesis Data Firehose"},{"id":"B","text":"Flow Logs capturam o conteúdo completo (payload) dos pacotes"},{"id":"C","text":"Flow Logs só funcionam em subnet pública"},{"id":"D","text":"Flow Logs só capturam tráfego de saída (egress)"}]'::jsonb, 'A', '{"summary":"Flow Logs = metadata IP (não payload); destinos CWL/S3/KDF.","whyCorrect":"VPC Flow Logs capturam metadados de fluxos IP: source/dest IP, ports, protocolo, bytes, packets, action (ACCEPT/REJECT), timestamp. NÃO capturam payload. Destinos: CloudWatch Logs, S3 (mais barato para grandes volumes) ou Kinesis Data Firehose. Granularidade: VPC, subnet ou ENI.","whyWrong":{"B":"Payload completo exige Traffic Mirroring, não Flow Logs.","C":"Funcionam em qualquer subnet (pública ou privada).","D":"Capturam ingress, egress ou ambos (configurável)."},"keyConcept":"VPC Flow Logs vs Traffic Mirroring — metadata vs payload","compareWith":["Flow Logs vs Traffic Mirroring","Destinos CWL vs S3 vs KDF"],"realWorldContext":"Forensics de incidentes, troubleshooting de conectividade, baseline de tráfego para detecção de anomalias.","commonMistakes":"Esperar inspeção de payload em Flow Logs — limitado a metadata; use Traffic Mirroring + Wireshark/Suricata.","tutorSeeds":["Custo CWL vs S3 para Flow Logs em produção?","Custom format para Flow Logs?"]}'::jsonb, 'Cloud Technology & Services', 'Cloud Technology & Services', 'easy', 'recall', '["vpc","flow-logs","observability"]'::jsonb, 'ai-draft', 'active', now(), now()),
    ('clf-c02-tech-v2-060', 'aws-clf', 'Uma equipe precisa de IPs estáticos globais que façam health-check e anycast para frontends regionais (ALBs/NLBs em 3 Regions). Qual serviço atende?', '[{"id":"A","text":"AWS Global Accelerator"},{"id":"B","text":"Amazon CloudFront"},{"id":"C","text":"Route 53 com Failover policy"},{"id":"D","text":"NLB com Elastic IP"}]'::jsonb, 'A', '{"summary":"IP estático global + anycast + multi-Region failover = Global Accelerator.","whyCorrect":"Global Accelerator provê 2 IPs anycast estáticos roteados ao endpoint regional mais próximo via backbone AWS. Health checks contínuos failover automático entre Regions. Útil para protocolos não-HTTP (gaming, IoT) ou quando precisa IP estático global.","whyWrong":{"B":"CloudFront é CDN para HTTP/HTTPS — não dá IP estático nem suporta UDP.","C":"Route 53 Failover usa DNS — clients podem cachear DNS e demorar a perceber failover; sem IP estático.","D":"NLB+EIP é regional, não global; um IP por AZ na Region."},"keyConcept":"Global Accelerator — IP estático global + anycast routing AWS backbone","compareWith":["Global Accelerator vs CloudFront","GA vs Route 53 latency routing"],"realWorldContext":"Apps gaming UDP globais, IoT MQTT, sistemas legacy que exigem IP allowlist.","commonMistakes":"Confundir GA (L4 + IPs estáticos) com CloudFront (L7 HTTP cache).","tutorSeeds":["Quando GA acelera HTTP além do CloudFront?","GA custos vs benefícios?"]}'::jsonb, 'Cloud Technology & Services', 'Cloud Technology & Services', 'medium', 'scenario', '["global-accelerator","anycast","multi-region"]'::jsonb, 'ai-draft', 'active', now(), now()),
    ('clf-c02-tech-v2-061', 'aws-clf', 'Sobre Security Groups (SG) em VPC, qual afirmação está CORRETA?', '[{"id":"A","text":"SGs são stateful — resposta de uma conexão permitida pelo inbound é automaticamente permitida no outbound (e vice-versa)"},{"id":"B","text":"SGs são stateless — você precisa permitir explicitamente inbound e outbound separadamente"},{"id":"C","text":"SGs suportam regras de DENY explícito"},{"id":"D","text":"SGs operam na borda da VPC, não em cada ENI"}]'::jsonb, 'A', '{"summary":"SG stateful: tracking de conexões automático; NACL stateless.","whyCorrect":"Security Groups são stateful — se você permite inbound TCP 443, a resposta saindo é automaticamente permitida sem regra de outbound correspondente. NACLs (Network ACLs) são o oposto: stateless, exigem regras inbound e outbound separadas.","whyWrong":{"B":"Stateless é NACL, não SG.","C":"SG só suporta ALLOW (implicit deny); DENY explícito é NACL.","D":"SGs operam em cada ENI (network interface) — granularidade fina."},"keyConcept":"Security Group (stateful, ALLOW only, per-ENI) vs NACL (stateless, ALLOW+DENY, per-subnet)","compareWith":["SG vs NACL"],"realWorldContext":"Microsegmentação dentro da VPC, controlar tráfego entre tiers (web, app, db).","commonMistakes":"Tentar criar ''regra DENY'' em SG — não existe; use NACL ou estruture SGs com referências.","tutorSeeds":["Quando NACL é necessário?","Limite de regras por SG?"]}'::jsonb, 'Cloud Technology & Services', 'Cloud Technology & Services', 'easy', 'recall', '["vpc","security-group","stateful"]'::jsonb, 'ai-draft', 'active', now(), now()),
    ('clf-c02-tech-v2-062', 'aws-clf', 'Uma equipe usa NAT Gateway e o custo está explodindo. Investigação mostra que 80% do tráfego de saída é para S3. Qual ação reduz custo SEM perder funcionalidade?', '[{"id":"A","text":"Criar VPC Gateway Endpoint para S3 e ajustar route tables"},{"id":"B","text":"Aumentar tamanho do NAT Gateway"},{"id":"C","text":"Trocar NAT Gateway por NAT Instance EC2"},{"id":"D","text":"Mover EC2 para subnet pública"}]'::jsonb, 'A', '{"summary":"Gateway Endpoint para S3 é grátis e remove tráfego do NAT.","whyCorrect":"VPC Gateway Endpoint para S3 não cobra por hora nem por dados processados. Adicionar à route table direciona tráfego S3 direto via backbone, eliminando o data processing fee do NAT Gateway (~$0.045/GB) — economia massiva quando há TB/mês de tráfego S3.","whyWrong":{"B":"NAT GW não tem ''tamanho'' configurável (escala automática); aumentar não muda custo de data.","C":"NAT Instance é gerenciado por você (overhead operacional) e não escala como NAT GW; potencialmente mais caro em escala.","D":"Mover EC2 para subnet pública compromete segurança."},"keyConcept":"NAT Gateway data processing fee vs VPC Gateway Endpoint (grátis para S3/DDB)","compareWith":["NAT Gateway vs Gateway Endpoint vs Interface Endpoint custo"],"realWorldContext":"Datalakes lendo PB/mês de S3 — economias de milhares de dólares com endpoints.","commonMistakes":"Não auditar tráfego NAT periodicamente — alvos óbvios (S3, DDB, ECR, CloudWatch) economizam muito.","tutorSeeds":["Como auditar tráfego NAT por destino via Flow Logs?","ECR pull via Interface Endpoint — vale?"]}'::jsonb, 'Cloud Technology & Services', 'Cloud Technology & Services', 'medium', 'troubleshoot', '["vpc","nat-gateway","cost-optimization","endpoint"]'::jsonb, 'ai-draft', 'active', now(), now()),
    ('clf-c02-tech-v2-063', 'aws-clf', 'Uma equipe usa CloudFront na frente de um bucket S3 estático. Quer impedir que usuários acessem o S3 diretamente (bypass do CDN). Qual é o método RECOMENDADO atualmente?', '[{"id":"A","text":"Origin Access Control (OAC) com bucket policy restringindo a CloudFront distribution"},{"id":"B","text":"Origin Access Identity (OAI) — método mais antigo e recomendado"},{"id":"C","text":"Bucket público com CloudFront em modo passthrough"},{"id":"D","text":"IAM Role anexada à distribution"}]'::jsonb, 'A', '{"summary":"OAC é a versão moderna do OAI — suporta SSE-KMS e mais features.","whyCorrect":"Origin Access Control (OAC) é a forma recomendada desde 2022. Suporta todos os Regions, SSE-KMS, dynamic requests e SigV4. Configura-se com bucket policy condicionando acesso a aws:SourceArn da distribution.","whyWrong":{"B":"OAI é legado e ainda funciona, mas a AWS recomenda migrar para OAC. OAI não suporta SSE-KMS e algumas features novas.","C":"Bucket público derrota o propósito de impedir bypass.","D":"IAM Roles não se anexam a CloudFront distributions; o controle é via bucket policy."},"keyConcept":"CloudFront origin protection — OAC (atual) vs OAI (legado)","compareWith":["OAC vs OAI"],"realWorldContext":"Sites estáticos protegidos, distribuição de assets pagos via signed URLs.","commonMistakes":"Continuar criando novos setups com OAI por costume — use OAC para novos projetos.","tutorSeeds":["Como migrar OAI para OAC?","OAC + SSE-KMS — quais permissões na key?"]}'::jsonb, 'Cloud Technology & Services', 'Cloud Technology & Services', 'medium', 'best-practice', '["cloudfront","oac","s3"]'::jsonb, 'ai-draft', 'active', now(), now()),
    ('clf-c02-tech-v2-064', 'aws-clf', 'Uma empresa precisa distribuir vídeos pagos via CloudFront, com URLs válidas apenas por 1 hora e somente para usuários autenticados. Qual recurso é o canônico?', '[{"id":"A","text":"Signed URLs ou Signed Cookies do CloudFront"},{"id":"B","text":"Bucket S3 público com lifecycle de 1h"},{"id":"C","text":"API Gateway com Lambda authorizer"},{"id":"D","text":"CORS configurado para bloquear acesso direto"}]'::jsonb, 'A', '{"summary":"URLs/cookies temporários autenticados no CDN = CloudFront Signed URLs/Cookies.","whyCorrect":"CloudFront Signed URLs (1 arquivo) e Signed Cookies (múltiplos arquivos) permitem assinar requisições com chave privada da conta. O CDN verifica assinatura + policy (expiração, IP allowlist) e nega se inválida. Ideal para vídeo on-demand pago.","whyWrong":{"B":"Bucket público + lifecycle não dá controle por usuário nem expiração por URL — só por arquivo.","C":"API Gateway + Lambda authorizer não é o caminho para servir vídeo via CDN — adiciona latência e quebra o cache.","D":"CORS é controle de origin no browser, não autenticação."},"keyConcept":"CloudFront Signed URLs/Cookies — distribuição privada via CDN","compareWith":["Signed URL vs Signed Cookie","CloudFront SU vs S3 Presigned URL"],"realWorldContext":"Netflix-like streaming, conteúdo educacional pago, downloads de software licenciado.","commonMistakes":"Usar S3 presigned URL direto sem CDN — perde benefícios de cache e edge.","tutorSeeds":["Signed URL vs Signed Cookie — quando cada um?","Como rotacionar key pair?"]}'::jsonb, 'Cloud Technology & Services', 'Cloud Technology & Services', 'medium', 'scenario', '["cloudfront","signed-urls","drm"]'::jsonb, 'ai-draft', 'active', now(), now()),
    ('clf-c02-tech-v2-065', 'aws-clf', 'Uma equipe quer rodar lógica customizada no edge do CloudFront — modificar headers de request, fazer rewrite de URL — com latência mínima e sem invocar Lambda. Qual recurso?', '[{"id":"A","text":"CloudFront Functions"},{"id":"B","text":"Lambda@Edge"},{"id":"C","text":"AWS WAF managed rules"},{"id":"D","text":"CloudFront Field-Level Encryption"}]'::jsonb, 'A', '{"summary":"Edge logic leve (header rewrite, URL rewrite) com sub-ms = CloudFront Functions.","whyCorrect":"CloudFront Functions executa JavaScript no edge (não em Region), latência sub-ms, limite de 1ms CPU + 2MB memória. Ideal para header manipulation, URL rewrites, A/B testing, redirects. Cobra ~$0.10/M invocações (10x mais barato que Lambda@Edge).","whyWrong":{"B":"Lambda@Edge é mais poderoso (Node/Python, network calls, longer runtime) mas latência maior (dezenas de ms) e mais caro. Use quando precisar de mais que header manipulation.","C":"WAF é firewall — não rewrite de URLs/headers.","D":"Field-Level Encryption protege campos específicos POST — não rewrite."},"keyConcept":"Edge compute — CloudFront Functions (leve, sub-ms) vs Lambda@Edge (poderoso, ms)","compareWith":["CloudFront Functions vs Lambda@Edge"],"realWorldContext":"Normalização de URL para cache hit ratio, geolocation redirects, A/B test seeding.","commonMistakes":"Usar Lambda@Edge para header simples — overkill caro.","tutorSeeds":["Quais limitações de CloudFront Functions?","Lambda@Edge — origin-request vs viewer-request?"]}'::jsonb, 'Cloud Technology & Services', 'Cloud Technology & Services', 'medium', 'scenario', '["cloudfront","edge-compute","cloudfront-functions"]'::jsonb, 'ai-draft', 'active', now(), now()),
    ('clf-c02-tech-v2-066', 'aws-clf', 'Sobre Cache Policies e Origin Request Policies do CloudFront, qual afirmação é VERDADEIRA?', '[{"id":"A","text":"Cache Policy define o que entra na chave de cache (headers, query strings, cookies considerados); Origin Request Policy define o que é encaminhado à origem (sem afetar cache key)"},{"id":"B","text":"São o mesmo recurso com nomes diferentes"},{"id":"C","text":"Cache Policy define ACLs de IP permitidos"},{"id":"D","text":"Origin Request Policy só funciona com Lambda@Edge"}]'::jsonb, 'A', '{"summary":"Cache Policy = chave de cache; Origin Request Policy = o que vai pro backend.","whyCorrect":"Cache Policy determina cache key (TTLs, headers/query/cookies que compõem a chave) — afeta hit ratio. Origin Request Policy determina quais headers/query/cookies são repassados à origem mas SEM entrar na chave de cache. Útil para enviar info ao backend sem fragmentar cache.","whyWrong":{"B":"São distintos com propósitos complementares.","C":"ACL de IP é função do WAF/Geo Restrictions, não dessas policies.","D":"Origin Request Policy funciona com qualquer origem, sem Lambda."},"keyConcept":"CloudFront — Cache Policy (cache key) vs Origin Request Policy (forwarding sem afetar key)","compareWith":["Cache Policy vs Origin Request Policy vs Response Headers Policy"],"realWorldContext":"Enviar Authorization header ao backend sem fragmentar cache; cache compartilhado entre users autenticados.","commonMistakes":"Incluir Authorization no Cache Policy — destrói cache (1 cache por user).","tutorSeeds":["Como debugar cache miss inesperado?","Managed cache policies — quais existem?"]}'::jsonb, 'Cloud Technology & Services', 'Cloud Technology & Services', 'hard', 'recall', '["cloudfront","cache-policy","origin-request-policy"]'::jsonb, 'ai-draft', 'active', now(), now()),
    ('clf-c02-tech-v2-067', 'aws-clf', 'Uma equipe usa CloudFront e nota que TTL configurado no Cache Policy é 24h, mas objetos no S3 mudam diariamente — usuários veem versão antiga por horas. Qual estratégia é o BEST PRACTICE para forçar atualização?', '[{"id":"A","text":"Versionar objetos no nome/path (ex: /v123/app.js) e referenciar no HTML; build novo gera novo path automaticamente"},{"id":"B","text":"Setar TTL para 0 (sem cache)"},{"id":"C","text":"Fazer invalidations em massa todo dia"},{"id":"D","text":"Desabilitar CloudFront e servir direto do S3"}]'::jsonb, 'A', '{"summary":"Cache busting via versionamento de URL é o padrão da indústria — invalidations são fallback.","whyCorrect":"Versionar paths (app.v123.js, /static/abc123/main.css) garante que cada deploy gera URLs novas — clients buscam, cache popula sem conflito, version antiga continua válida até TTL natural. Permite rollback instantâneo (mudar HTML para versão anterior). É o padrão de webpack/Vite/Next.js.","whyWrong":{"B":"TTL=0 elimina valor do CDN — paga origem em todo request.","C":"Invalidations custam ($0.005 por path após primeiros 1000/mês) e demoram minutos a propagar — não escalam para deploys frequentes.","D":"Desabilitar CDN aumenta latência e custo de S3 GET."},"keyConcept":"Cache busting via URL versioning vs invalidations","compareWith":["URL versioning vs Invalidations","TTL longo vs TTL curto"],"realWorldContext":"Webpack hashes em filenames, Next.js _next/static/[hash], assets fingerprinting.","commonMistakes":"Confiar em invalidations para deploy frequente — caro e lento.","tutorSeeds":["Como configurar TTL longo + URL versioning corretamente?","Quando invalidation é apropriada?"]}'::jsonb, 'Cloud Technology & Services', 'Cloud Technology & Services', 'easy', 'best-practice', '["cloudfront","cache-busting","deployment"]'::jsonb, 'ai-draft', 'active', now(), now()),
    ('clf-c02-tech-v2-068', 'aws-clf', 'Uma empresa quer multi-CDN para failover e quer servir conteúdo de POPs em todas as regiões geográficas, incluindo Brasil e África. Sobre a rede edge do CloudFront, qual afirmação é VERDADEIRA?', '[{"id":"A","text":"CloudFront opera 600+ edge locations e Regional Edge Caches em ~13 cidades; é por padrão global, sem opt-in"},{"id":"B","text":"CloudFront só atende América do Norte e Europa"},{"id":"C","text":"Para usar PoP no Brasil é preciso ativar feature paga ''Brazil Edge''"},{"id":"D","text":"CloudFront não tem cache regional — todos os requests vão à origem"}]'::jsonb, 'A', '{"summary":"CloudFront tem 600+ edges + Regional Edge Caches; global por default.","whyCorrect":"CloudFront possui 600+ edge locations globais e ~13 Regional Edge Caches que ficam entre edges e origem (reduzem carga na origem e melhoram hit ratio). É global por default — Brasil, África, Oriente Médio, todas regiões.","whyWrong":{"B":"Cobertura é global.","C":"Não há feature ''Brazil Edge'' paga.","D":"Há Regional Edge Caches por design."},"keyConcept":"CloudFront topology — Edge Locations + Regional Edge Caches + Origin","compareWith":["Edge cache vs Regional edge cache","CloudFront vs outros CDNs cobertura"],"realWorldContext":"Sites com audiência global, downloads de software, vídeo streaming.","commonMistakes":"Configurar Geo Restrictions errado e cortar países sem querer.","tutorSeeds":["Como Regional Edge Cache reduz carga na origem?","Price classes do CloudFront?"]}'::jsonb, 'Cloud Technology & Services', 'Cloud Technology & Services', 'easy', 'recall', '["cloudfront","edge-locations","global"]'::jsonb, 'ai-draft', 'active', now(), now()),
    ('clf-c02-tech-v2-069', 'aws-clf', 'Uma equipe quer arquitetura pub/sub onde 1 mensagem dispara N processadores diferentes em paralelo: 1 grava em S3, outro envia email, outro insere no DynamoDB. Cada processador deve ter sua própria fila de retry/DLQ. Qual padrão é o canônico?', '[{"id":"A","text":"SNS topic com múltiplas SQS subscriptions (fanout) + Lambda por fila"},{"id":"B","text":"SQS direto chamando os 3 processadores em sequência"},{"id":"C","text":"Lambda chamando outras Lambdas via SDK"},{"id":"D","text":"Kinesis Data Streams com 1 consumer iterando"}]'::jsonb, 'A', '{"summary":"Padrão SNS→SQS fanout: 1 publish, N consumers desacoplados com suas próprias DLQs.","whyCorrect":"SNS publica em N SQS subscriptions. Cada consumer (Lambda/ECS) lê de SUA fila com retry/DLQ independentes. Falha em um não afeta os outros. Desacoplamento total: adicionar/remover consumer = adicionar/remover subscription.","whyWrong":{"B":"SQS direto não faz fanout 1-para-N nativamente.","C":"Lambda chamando Lambda acopla, sem retry/DLQ por destino e sem isolamento de falha.","D":"Kinesis com 1 consumer não dá retry isolado por tipo de processamento."},"keyConcept":"SNS-SQS fanout pattern — broadcast com desacoplamento e DLQ per consumer","compareWith":["SNS-SQS fanout vs EventBridge","SNS direct to Lambda vs SNS-SQS-Lambda"],"realWorldContext":"E-commerce: order placed → email + warehouse + analytics + inventory update.","commonMistakes":"SNS direto para Lambda sem SQS — sem buffer, picos derrubam Lambda; sem DLQ por consumer.","tutorSeeds":["EventBridge fanout — quando supera SNS-SQS?","FIFO fanout — limitações?"]}'::jsonb, 'Cloud Technology & Services', 'Cloud Technology & Services', 'medium', 'best-practice', '["sns","sqs","fanout","pub-sub"]'::jsonb, 'ai-draft', 'active', now(), now()),
    ('clf-c02-tech-v2-070', 'aws-clf', 'Uma equipe precisa rotear eventos baseando em CONTEÚDO (ex: ''só processar quando event.source = stripe E event.type = invoice.paid''), com mapping de schemas e archive opcional. Qual serviço é o adequado?', '[{"id":"A","text":"Amazon EventBridge (com event bus, rules baseadas em JSON pattern, schema registry)"},{"id":"B","text":"SNS topic com filter policies"},{"id":"C","text":"SQS com SQS-as-Filter"},{"id":"D","text":"AWS Glue Workflows"}]'::jsonb, 'A', '{"summary":"Content-based routing + schema registry + archive = EventBridge.","whyCorrect":"EventBridge oferece rules com JSON pattern matching sofisticado (igualdade, prefix, anything-but, numeric ranges), schema registry com discovery e archives para replay. Suporta integração nativa com 100+ SaaS partners (Stripe, Datadog, etc.) e eventos AWS.","whyWrong":{"B":"SNS filter policies são mais limitadas (apenas message attributes, sem deep JSON matching) e sem schema registry/archive.","C":"SQS não tem feature de filtering por conteúdo na ingestão.","D":"Glue Workflows é para ETL pipelines, não event routing."},"keyConcept":"EventBridge — event router com pattern matching, schemas e archive","compareWith":["EventBridge vs SNS — quando cada um","EventBridge Pipes vs Rules"],"realWorldContext":"Integração com SaaS partners (Stripe webhooks), arquitetura event-driven multi-conta.","commonMistakes":"Confundir SNS (broadcast simples) com EventBridge (routing inteligente).","tutorSeeds":["EventBridge Pipes — para que serve?","Schema discovery — como ativar?"]}'::jsonb, 'Cloud Technology & Services', 'Cloud Technology & Services', 'medium', 'scenario', '["eventbridge","event-routing","integration"]'::jsonb, 'ai-draft', 'active', now(), now()),
    ('clf-c02-tech-v2-071', 'aws-clf', 'Uma equipe escolhe entre AWS Step Functions Standard e Express workflows. Têm um workflow de 8 horas com human approval no meio e outro de 30 segundos invocado 50k vezes/min para validação rápida. Qual escolha é a correta?', '[{"id":"A","text":"Standard para o workflow de 8h (até 1 ano, exactly-once, com human task); Express para o workflow rápido (alta vazão, at-least-once)"},{"id":"B","text":"Express para ambos — sempre é mais barato"},{"id":"C","text":"Standard para ambos — Express não suporta Lambda"},{"id":"D","text":"Step Functions não suporta workflows de horas"}]'::jsonb, 'A', '{"summary":"Standard = longo, exactly-once, human tasks. Express = curto, alta vazão, at-least-once.","whyCorrect":"Standard suporta até 1 ano de duração, exactly-once execution, history visível, integração com human approval (callback pattern). Express dura até 5 min, sync ou async, otimizado para alta vazão e baixo custo per-execution, at-least-once. Match perfeito para os dois casos.","whyWrong":{"B":"Express é mais barato POR EXECUTION mas tem limite de 5 min e não tem exactly-once — não serve para 8h com approval.","C":"Express suporta Lambda perfeitamente.","D":"Standard suporta até 1 ano."},"keyConcept":"Step Functions — Standard (durabilidade, exactly-once) vs Express (vazão, at-least-once)","compareWith":["Standard vs Express workflow types"],"realWorldContext":"Order fulfillment com human approval (Standard); IoT event processing (Express).","commonMistakes":"Usar Standard para tudo — custo explode em workflows curtos de alto volume.","tutorSeeds":["Como combinar Standard chamando nested Express?","Custos comparados em escala?"]}'::jsonb, 'Cloud Technology & Services', 'Cloud Technology & Services', 'hard', 'scenario', '["step-functions","standard","express"]'::jsonb, 'ai-draft', 'active', now(), now()),
    ('clf-c02-tech-v2-072', 'aws-clf', 'Uma equipe quer mensagens com ORDEM garantida por chave de grupo, sem duplicação dentro de 5 minutos, e ainda assim alto throughput. Qual SQS é adequado?', '[{"id":"A","text":"SQS FIFO com high throughput mode habilitado e MessageGroupId"},{"id":"B","text":"SQS Standard com FIFO emulado em código"},{"id":"C","text":"Kinesis Data Streams sempre"},{"id":"D","text":"SNS FIFO sem SQS"}]'::jsonb, 'A', '{"summary":"Ordem por chave + dedupe + alto throughput = SQS FIFO + high throughput mode + MessageGroupId.","whyCorrect":"SQS FIFO garante ordem dentro de um MessageGroupId e dedupe via MessageDeduplicationId (janela 5 min). High Throughput Mode (per-message-group-id ou per-queue) eleva limite de 300 msg/s para até 70.000 msg/s.","whyWrong":{"B":"Emular FIFO em Standard é complexo, propenso a erros e não escala bem.","C":"Kinesis é alternativa mas com modelo diferente (streams, partitions, shards) — não é resposta direta à pergunta SQS.","D":"SNS FIFO sem SQS não suporta fanout pesado nem é um destino persistente para processamento."},"keyConcept":"SQS FIFO — ordem por MessageGroupId, dedupe por MessageDeduplicationId, high throughput mode","compareWith":["SQS Standard vs FIFO","FIFO regular vs High Throughput mode"],"realWorldContext":"Processamento de pedidos por cliente em ordem, eventos de account em sequência.","commonMistakes":"Não habilitar high throughput mode e bater no limite de 300 msg/s.","tutorSeeds":["MessageGroupId estratégias?","FIFO dedupe vs idempotência da aplicação?"]}'::jsonb, 'Cloud Technology & Services', 'Cloud Technology & Services', 'hard', 'scenario', '["sqs","fifo","high-throughput"]'::jsonb, 'ai-draft', 'active', now(), now()),
    ('clf-c02-tech-v2-073', 'aws-clf', 'Uma equipe escolhe entre API Gateway REST API e HTTP API. O critério é: rotas REST simples com Lambda, baixa latência e custo mínimo. Qual é a escolha correta e por quê?', '[{"id":"A","text":"HTTP API — até 70% mais barato, latência menor, suporta JWT authorizer nativo, sem features avançadas do REST (request validation, SDK generation, API keys)"},{"id":"B","text":"REST API — sempre mais barato e simples"},{"id":"C","text":"HTTP API não suporta Lambda"},{"id":"D","text":"REST API e HTTP API são iguais em custo e features"}]'::jsonb, 'A', '{"summary":"HTTP API: mais barato, mais rápido, sem features avançadas (request validation, API keys, WAF nativo, etc.).","whyCorrect":"HTTP API é ~70% mais barato que REST API, latência menor, JWT/Cognito authorizer nativo. Falta-lhe: request validation, transformations, SDK generation, API keys/usage plans, private endpoints via VPC link sem NLB, WAF integration direta (precisa CloudFront).","whyWrong":{"B":"REST API é mais caro, embora mais completo em features.","C":"HTTP API integra com Lambda perfeitamente — é caso de uso principal.","D":"Diferem em custo, latência e features."},"keyConcept":"API Gateway — REST API (full features, $) vs HTTP API (lean, $)","compareWith":["REST API vs HTTP API feature parity","WebSocket API"],"realWorldContext":"Backends Lambda simples = HTTP API. Públicas externas com need API keys/throttling avançado = REST API.","commonMistakes":"Migrar REST→HTTP sem revisar features perdidas (API keys, request validation).","tutorSeeds":["JWT authorizer no HTTP API — como funciona?","Como expor HTTP API com WAF?"]}'::jsonb, 'Cloud Technology & Services', 'Cloud Technology & Services', 'medium', 'scenario', '["api-gateway","rest","http-api"]'::jsonb, 'ai-draft', 'active', now(), now()),
    ('clf-c02-tech-v2-074', 'aws-clf', 'Sobre AppSync (GraphQL gerenciado), qual afirmação é VERDADEIRA?', '[{"id":"A","text":"AppSync suporta queries, mutations e subscriptions (real-time via WebSocket); resolvers podem ir a DynamoDB, Lambda, RDS, HTTP, OpenSearch — usando VTL ou JavaScript"},{"id":"B","text":"AppSync só suporta REST, não GraphQL"},{"id":"C","text":"AppSync exige rodar servidor GraphQL em EC2"},{"id":"D","text":"AppSync subscriptions são via polling HTTP"}]'::jsonb, 'A', '{"summary":"AppSync = GraphQL gerenciado com subscriptions real-time e resolvers para múltiplos data sources.","whyCorrect":"AppSync expõe schema GraphQL gerenciado. Resolvers (em VTL ou JavaScript) mapeiam fields a DynamoDB, Lambda, RDS via RDS Data API, HTTP, OpenSearch. Subscriptions usam WebSocket gerenciado para push real-time. Authorization múltipla: IAM, Cognito User Pools, OIDC, API key, Lambda.","whyWrong":{"B":"AppSync é GraphQL, não REST.","C":"É serverless — sem EC2.","D":"Subscriptions são WebSocket nativo, não polling."},"keyConcept":"AppSync — GraphQL managed com real-time subscriptions","compareWith":["AppSync vs API Gateway REST","AppSync vs ECS hosting GraphQL server"],"realWorldContext":"Apps mobile com sync offline (DataStore), dashboards real-time, e-commerce com live inventory.","commonMistakes":"Tentar replicar GraphQL em REST API quando AppSync já oferece nativo.","tutorSeeds":["AppSync caching — como funciona?","Pipeline resolvers — para que servem?"]}'::jsonb, 'Cloud Technology & Services', 'Cloud Technology & Services', 'easy', 'recall', '["appsync","graphql","real-time"]'::jsonb, 'ai-draft', 'active', now(), now()),
    ('clf-c02-tech-v2-075', 'aws-clf', 'Uma equipe API Gateway REST quer expor o mesmo backend Lambda em /v1 e /v2 com responses ligeiramente diferentes. Qual feature do API Gateway REST API permite essa transformação sem mudar a Lambda?', '[{"id":"A","text":"Mapping Templates (VTL) em integration request/response"},{"id":"B","text":"CORS configuration"},{"id":"C","text":"Stage variables apenas"},{"id":"D","text":"WAF rules"}]'::jsonb, 'A', '{"summary":"Transformação request/response no API Gateway REST = Mapping Templates VTL.","whyCorrect":"Mapping Templates usam Velocity Template Language (VTL) para reescrever request body antes de ir à integração e response body antes de voltar ao client. Permite versionar API sem tocar backend.","whyWrong":{"B":"CORS controla cross-origin headers, não transformações de payload.","C":"Stage variables passam config por stage mas não transformam payload.","D":"WAF é segurança L7, não transformação."},"keyConcept":"API Gateway REST — Mapping Templates VTL para transformações","compareWith":["REST API mapping templates vs HTTP API (não tem)"],"realWorldContext":"Versionamento gradual de API sem reescrever backend.","commonMistakes":"Acoplar lógica de transformação na Lambda — torna versionamento mais difícil.","tutorSeeds":["VTL — quais funções estão disponíveis?","HTTP API tem alternativa a mapping templates?"]}'::jsonb, 'Cloud Technology & Services', 'Cloud Technology & Services', 'hard', 'scenario', '["api-gateway","rest","mapping-templates"]'::jsonb, 'ai-draft', 'active', now(), now()),
    ('clf-c02-tech-v2-076', 'aws-clf', 'Uma empresa analytics precisa decidir entre Athena, Redshift e EMR para um data lake S3 de 50 TB. Querem queries SQL ad-hoc esporádicas, sem dashboards constantes nem ETL pesado contínuo. Qual escolha minimiza ops e custo?', '[{"id":"A","text":"Athena — serverless, paga por query (TB scaneado), sem cluster para gerenciar"},{"id":"B","text":"Redshift Provisioned cluster ra3.xlplus 24/7"},{"id":"C","text":"EMR cluster Spark sempre rodando"},{"id":"D","text":"RDS PostgreSQL com import S3"}]'::jsonb, 'A', '{"summary":"Queries ad-hoc esporádicas em S3 = Athena (serverless, pay-per-scan).","whyCorrect":"Athena é serverless query engine (Presto/Trino) sobre S3. Cobra $5 por TB escaneado. Para uso esporádico, custo é mínimo (sem cluster idle). Com Parquet + particionamento, scans podem cair 90%+. Zero ops.","whyWrong":{"B":"Redshift 24/7 paga cluster mesmo idle — mais caro para uso esporádico.","C":"EMR cluster idle é desperdício; ferramentas Spark/Hadoop são overkill para SQL ad-hoc.","D":"RDS não é OLAP — não escala para 50 TB de queries analíticas."},"keyConcept":"Athena vs Redshift vs EMR — pay-per-query vs cluster contínuo","compareWith":["Athena vs Redshift Serverless","Athena vs EMR (Spark/Presto)"],"realWorldContext":"Data exploratory analysis, BI queries esporádicas, troubleshooting de logs.","commonMistakes":"Não usar particionamento + colunar (Parquet) — query scaneia tudo e custo explode.","tutorSeeds":["Athena workgroups e cost controls?","Quando Redshift Serverless vence Athena?"]}'::jsonb, 'Cloud Technology & Services', 'Cloud Technology & Services', 'easy', 'best-practice', '["athena","analytics","data-lake"]'::jsonb, 'ai-draft', 'active', now(), now()),
    ('clf-c02-tech-v2-077', 'aws-clf', 'Sobre Amazon SageMaker (plataforma ML completa), qual afirmação é VERDADEIRA no nível CLF?', '[{"id":"A","text":"SageMaker oferece um ecossistema completo: notebooks (Studio), training jobs, hyperparameter tuning, model registry, real-time/batch inference endpoints, ground truth labeling — gerenciados sem provisionar EC2 manualmente"},{"id":"B","text":"SageMaker apenas hospeda modelos pré-treinados de fornecedores terceiros"},{"id":"C","text":"SageMaker é exclusivamente para inferência, não treinamento"},{"id":"D","text":"SageMaker não suporta GPUs"}]'::jsonb, 'A', '{"summary":"SageMaker é plataforma ML end-to-end gerenciada — notebooks, training, tuning, deployment, registry.","whyCorrect":"SageMaker cobre todo o ciclo ML: Studio (notebooks), Training Jobs (spot, distribuído), HPO, Model Registry, Endpoints (real-time multi-model, async, serverless, batch transform), Ground Truth (labeling), Pipelines (MLOps), Feature Store, Clarify, Model Monitor.","whyWrong":{"B":"Faz muito além de hostar — treina, tuna, monitora.","C":"Cobre treinamento E inferência.","D":"Suporta CPUs e várias GPUs (incluindo NVIDIA P/G/H series e Trainium/Inferentia)."},"keyConcept":"SageMaker — plataforma ML end-to-end gerenciada","compareWith":["SageMaker vs EC2 self-managed ML","SageMaker JumpStart vs Bedrock"],"realWorldContext":"Times de ML que querem foco no modelo e não na infra; MLOps em scale.","commonMistakes":"Confundir SageMaker (ML platform) com Bedrock (foundation models gerenciados).","tutorSeeds":["SageMaker vs Bedrock — quando cada um?","Inference variants — real-time vs async vs serverless?"]}'::jsonb, 'Cloud Technology & Services', 'Cloud Technology & Services', 'easy', 'recall', '["sagemaker","ml","ai"]'::jsonb, 'ai-draft', 'active', now(), now()),
    ('clf-c02-tech-v2-078', 'aws-clf', 'Uma equipe usa EventBridge para integrar eventos de Stripe (webhooks) com workflows internos. Quer reprocessar eventos de 1 mês atrás após bug fix. Qual feature do EventBridge permite isso?', '[{"id":"A","text":"EventBridge Archives + Replays"},{"id":"B","text":"EventBridge não suporta replay — é necessário rebuildar manualmente"},{"id":"C","text":"DynamoDB Streams na destination"},{"id":"D","text":"CloudTrail event lookup"}]'::jsonb, 'A', '{"summary":"EventBridge Archive grava eventos e Replay reprocessa do archive.","whyCorrect":"EventBridge Archives armazenam eventos do bus (retenção configurável). Replays selecionam um intervalo de tempo + filtro e reentregam eventos às rules como se fossem novos. Perfeito para corrigir bugs em consumers retroativamente.","whyWrong":{"B":"Suporta replay nativamente desde 2020.","C":"DDB Streams não tem relação direta com EventBridge replay.","D":"CloudTrail é audit de API calls AWS, não dos eventos de domínio."},"keyConcept":"EventBridge Archive + Replay — DR e bug recovery","compareWith":["EB Archives vs S3 dump manual"],"realWorldContext":"Bug em consumer downstream — replay últimas N horas após fix.","commonMistakes":"Não ativar archive ''pra economizar'' e perder capacidade de replay quando precisar.","tutorSeeds":["Custo do archive — vale sempre ligar?","Replay impacta rate limits?"]}'::jsonb, 'Cloud Technology & Services', 'Cloud Technology & Services', 'medium', 'scenario', '["eventbridge","archive","replay"]'::jsonb, 'ai-draft', 'active', now(), now()),
    ('clf-c02-tech-v2-079', 'aws-clf', 'Uma equipe consome eventos com Kinesis Data Streams e precisa garantir ordem por chave + retenção de 7 dias + múltiplos consumers independentes. Sobre KDS, qual afirmação é VERDADEIRA?', '[{"id":"A","text":"KDS preserva ordem por shard (partition key); retém até 365 dias (configurável); suporta múltiplos consumers via Enhanced Fan-Out (cada consumer 2 MB/s dedicado)"},{"id":"B","text":"KDS é FIFO global, sem partições"},{"id":"C","text":"Retenção máxima do KDS é 24 horas"},{"id":"D","text":"KDS suporta apenas 1 consumer por stream"}]'::jsonb, 'A', '{"summary":"KDS — ordem por shard, retenção até 365d, Enhanced Fan-Out para N consumers paralelos.","whyCorrect":"KDS divide em shards; ordem garantida apenas dentro de um shard (chave de partição). Retenção default 24h, configurável até 365 dias. Enhanced Fan-Out (EFO) dá a cada consumer 2 MB/s dedicado e push via HTTP/2 — superando o limite clássico de 2 MB/s compartilhado.","whyWrong":{"B":"Não é FIFO global — ordem por shard.","C":"Até 365 dias com tier extended.","D":"Suporta múltiplos consumers; EFO é o caminho idiomático moderno."},"keyConcept":"Kinesis Data Streams — shards, partition key, retention, Enhanced Fan-Out","compareWith":["KDS vs Kinesis Firehose vs MSK","Classic shared throughput vs Enhanced Fan-Out"],"realWorldContext":"Ingestão de clickstreams, IoT telemetria, real-time analytics.","commonMistakes":"Usar partition key uniforme → hot shard → throttling.","tutorSeeds":["Como dimensionar número de shards?","On-demand mode do KDS — quando vale?"]}'::jsonb, 'Cloud Technology & Services', 'Cloud Technology & Services', 'hard', 'recall', '["kinesis","kds","enhanced-fan-out"]'::jsonb, 'ai-draft', 'active', now(), now()),
    ('clf-c02-tech-v2-080', 'aws-clf', 'Uma equipe precisa entregar streaming de dados a S3, Redshift e OpenSearch com transformação opcional e zero ops de cluster. Qual serviço?', '[{"id":"A","text":"Amazon Data Firehose (anteriormente Kinesis Data Firehose)"},{"id":"B","text":"Kinesis Data Streams com Lambda customizada"},{"id":"C","text":"Amazon MSK"},{"id":"D","text":"AWS Glue Streaming ETL"}]'::jsonb, 'A', '{"summary":"Streaming ETL para S3/Redshift/OpenSearch zero-ops = Data Firehose.","whyCorrect":"Amazon Data Firehose (ex-Kinesis Data Firehose) é serverless: ingere streams, faz batching/compression/transformação opcional (via Lambda) e entrega a S3, Redshift, OpenSearch, Splunk, HTTP endpoints, partners. Zero gerenciamento de cluster ou shards.","whyWrong":{"B":"KDS + Lambda exige você gerenciar shards e código de entrega.","C":"MSK é Kafka managed — exige mais ops e configuração de connectors.","D":"Glue Streaming ETL é para ETL Spark — mais pesado e caro para entrega simples."},"keyConcept":"Data Firehose — delivery stream serverless com transformações","compareWith":["Data Firehose vs KDS vs MSK"],"realWorldContext":"Logs de aplicações → S3/OpenSearch, métricas → Splunk, eventos → Snowflake.","commonMistakes":"Usar KDS quando o caso é entrega simples a S3 — Firehose é mais barato e simples.","tutorSeeds":["Buffering size/interval — como dimensionar?","Quando Firehose é caro vs KDS?"]}'::jsonb, 'Cloud Technology & Services', 'Cloud Technology & Services', 'medium', 'scenario', '["firehose","streaming","delivery"]'::jsonb, 'ai-draft', 'active', now(), now())
